local P = LoreForeverPacks.Begin("LoreForever_Lang_zhCN")
P.entries["quest:786"] = {n="科卡尔半人马的进攻",s="“挫败科卡尔的侵略”是一项由侦察兵拉尔·猎齿在森金村附近发布的至关重要的部落防御任务。玩家的任务是潜入科卡尔峭壁，在半人马部族袭击杜隆塔尔初建的定居点之前，摧毁三份协调一致的入侵计划。",h="“挫败科卡尔的侵略”是一项由侦察兵拉尔·猎齿在森金村附近发布的至关重要的部落防御任务。玩家的任务是潜入科卡尔峭壁，在半人马部族袭击杜隆塔尔初建的定居点之前，摧毁三份协调一致的入侵计划。",kw={"杜隆塔尔","科卡尔","科卡尔峭壁","拉尔·猎齿","奥格瑞玛","森金村","挫败科卡尔的侵略","试炼谷"},ang={["faction:Horde"]="阻止科卡尔的进攻使新生的部落免于在其新家园的门口被迫进行一场艰苦的多线领土战争。",["race:Orc"]="试炼谷是年轻兽人举行成年仪式的地方，因此在那里发生的半人马侵略是对兽人战士文化的极大侮辱。",["race:Troll"]="暗矛巨魔本已失去了古老的岛屿家园，他们无法承担让森金村被劫掠的半人马淹没的代价。"},sec={{t="迫在眉睫的入侵",b="当拉尔·猎齿在杜隆塔尔西部进行侦察时，这名巨魔追踪者潜入了科卡尔峭壁。他所发现的情况令人震惊：科卡尔半人马不仅在进行无组织的沿海突袭，还在策划一场雄心勃勃的三路入侵，目标直指兽人和暗矛巨魔的家园。半人马军阀将他们的战斗策略分派给三位不同的首领，意图袭击试炼谷、森金村以及奥格瑞玛的大门本身。"},{t="突袭峡谷",b="为了避免在杜隆塔尔干燥的红色峡谷中爆发灾难性的战斗，新兵被派往科卡尔峭壁深处，擒贼先擒王。潜入尘土飞扬的营地并烧毁三份进攻卷轴，可以破坏半人马的指挥链。尽管拉尔·猎齿坚信部落必然能击溃任何全面入侵，但摧毁这些文件能让杜隆塔尔的守军免受代价高昂的流血牺牲，毕竟这个年轻的国度才刚刚站稳脚跟。"}},faq={{q="谁提供了“挫败科卡尔的侵略”这个任务？",a="该任务由拉尔·猎齿提供，他是一位驻扎在杜隆塔尔南部悬崖边、森金村外不远处的暗矛巨魔侦察兵。",al={"任务发布者","谁给任务","拉尔·猎齿位置"}},{q="科卡尔半人马计划袭击哪些目标？",a="科卡尔的作战计划概述了一场协调一致的三层进攻，目标分别为试炼谷、森金村和部落首都奥格瑞玛。",al={"半人马攻击目标","什么是进攻计划","三个目标"}},{q="科卡尔峭壁位于哪里？",a="科卡尔峭壁是一片被太阳炙烤的峡谷群，坐落在杜隆塔尔南部，从森金村翻过岩石山脊向西即可到达。",al={"科卡尔峭壁位置","峭壁在哪里","杜隆塔尔半人马村庄"}},{q="在峭壁内哪里可以找到进攻计划？",a="载有入侵蓝图的三份卷轴分别由驻守在峭壁各处不同营地的三位科卡尔首领保管。",al={"进攻计划地点","卷轴在哪里","半人马首领"}},{q="为什么科卡尔人想要入侵杜隆塔尔？",a="科卡尔是一个极具侵略性的扩张主义半人马部族，土生土长于卡利姆多的干燥土地上。他们视新来的兽人和暗矛巨魔为入侵者，认为他们侵犯了自己的领地和狩猎场。",al={"为什么半人马要攻击","半人马动机","科卡尔背景传说"}},{q="销毁计划后会发生什么？",a="摧毁这些文件可以阻止一场协调一致的围攻，使科卡尔的战术进攻陷入混乱，保护杜隆塔尔脆弱的定居点免受突如其来的毁灭。",al={"任务后续影响","半人马进攻是否停止"}}},fp="27,194,18.307.0,20.334.0,49.118.0,55.86.0,29.86.0,49.80.0,41.174.0,43.117.0"}
P.entries["quest:7861"] = {n="通缉：邪恶祭司海克斯和她的爪牙",s="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法，任何击杀这位女祭司及其精英阿曼扎希卫兵的人都将获得丰厚的奖赏。你可以在辛特兰的辛萨罗之巅找到他们。",h="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法，任何击杀这位女祭司及其精英阿曼扎希卫兵的人都将获得丰厚的奖赏。你可以在辛特兰的辛萨罗之巅找到他们。",kw={"阿曼扎希","海克斯","辛特兰","辛萨罗","断齿族长","恶齿村","邪恶的女祭司海克斯","邪恶枝族"},sec={{t="突袭辛萨罗",b="断齿族长下令必须将邪恶的女祭司海克斯和她的爪牙绳之以法。目标是女祭司本人以及她的精英阿曼扎希卫兵。他们就在辛特兰的辛萨罗之巅。一旦将其击杀，就回到恶齿村向断齿族长报告。"}},faq={{q="是谁发布了针对邪恶的女祭司海克斯的悬赏？",a="这份号召令由断齿族长下达，任何击杀女祭司及其卫兵的人都将获得丰厚的奖励。",al={"谁想要海克斯死","谁发布了这个悬赏","女祭司海克斯任务发布者"}},{q="在哪里可以找到邪恶的女祭司海克斯和她的卫兵？",a="他们在辛特兰的辛萨罗之巅。",al={"海克斯在哪里","邪恶的女祭司海克斯位置","阿曼扎希卫兵位置"}},{q="必须击杀谁才能完成悬赏？",a="邪恶枝族的女祭司海克斯本人，以及她的阿曼扎希精英卫兵。",al={"海克斯悬赏目标","杀谁来完成海克斯的任务"}},{q="在哪里交付悬赏？",a="在击杀女祭司和她的卫兵后，向恶齿村的断齿族长报告。",al={"海克斯悬赏在哪里交付","断齿族长位置"}}},fp="43,172,23.223.0,46.100.0,54.75.0,40.68.0,30.90.0"}
P.entries["quest:7862"] = {n="职位空缺：恶齿村卫兵队长",s="卫兵队长马尔科尔下落不明，恶齿村的卫兵部队需要一位新队长。任何有意担任此职的人都必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者，然后将申请书提交给位于辛特兰的断齿族长。",h="卫兵队长马尔科尔下落不明，恶齿村的卫兵部队需要一位新队长。任何有意担任此职的人都必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者，然后将申请书提交给位于辛特兰的断齿族长。",kw={"狂战士","饮血者","卫兵队长","马尔科尔","恶齿","暗影猎手","噬魂者","断齿","邪枝"},sec={{t="空缺的职位",b="一份征兵公告显示，卫兵队长马尔科尔下落不明，因此恶齿村的卫兵部队再次失去了队长。任何想要领导卫兵部队的人，都需要完成公告中列出的任务，并将申请书递交给断齿族长。"},{t="证明价值",b="申请人需要消灭四种邪枝巨魔：狂战士、暗影猎手、饮血者和噬魂者。完成后，回到恶齿村找断齿族长复命。"}},faq={{q="为什么卫兵队长的职位空缺？",a="卫兵队长马尔科尔下落不明，公告称恶齿村的队长职位再次空缺。",al={"为什么卫兵队长职位空缺","马尔科尔发生了什么事","谁是上一任队长"}},{q="在消灭敌人后，应该向谁提交申请？",a="申请应提交给恶齿村的断齿族长。",al={"我应该向谁交任务","在哪里提交申请","谁来评估申请人"}},{q="为了获得资格，必须击败哪些敌人？",a="申请人必须消灭邪枝狂战士、暗影猎手、饮血者和噬魂者。",al={"要杀死哪些邪枝巨魔","职位空缺目标","为了担任卫兵队长我该杀谁"}}},fp="47,162,13.211.0,13.153.0,42.67.0,56.62.0,42.93.0"}
P.entries["quest:78676"] = {n="The Eye of Bhossca",s="C让你去寻找据说位于血色修道院内的Bhossca之眼。有人想要这件神器，并要求将它送回焚木村附近的一个秘密接头点。",h="C让你去寻找据说位于血色修道院内的Bhossca之眼。有人想要这件神器，并要求将它送回焚木村附近的一个秘密接头点。",kw={"神器","bhossca","c","秘密接头点","伪装","bhossca之眼","焚木村","血色修道院"},sec={{t="C的委托",b="焚木村附近的箱子里有一张字条，上面是C的新委托。据说Bhossca之眼就在血色修道院某处，C想让你把它带回来。和影牙城堡那次一样，你必须独自潜入。修道院内或许能找到伪装，方便你行动。"}},faq={{q="谁想要这只眼睛？",a="C让你取回Bhossca之眼，并将它带到焚木村附近的秘密接头点。",al={"谁想要它","c是谁","c索要眼睛"}},{q="Bhossca之眼在哪里？",a="C的线人称，Bhossca之眼在血色修道院内的某处。",al={"眼睛在哪","眼睛的位置","寻找bhossca"}},{q="C为什么想要这只眼睛？",a="C称Bhossca之眼是一件神器，并说它是最近令人觊觎的物品。",al={"为什么要眼睛","c想拿它做什么","为什么要取回它"}},{q="我该把眼睛带到哪里？",a="你要把Bhossca之眼送回C在焚木村附近的秘密接头点。",al={"送回哪里","秘密接头点位置","箱子在哪里"}},{q="我必须独自前往吗？",a="C要求你独自进入血色修道院，并独自完成任务。",al={"要独自行动吗","能带帮手吗","独自取眼睛"}},{q="伪装会有帮助吗？",a="C说，伪装或许能让你更方便地行动，并建议你在修道院内找找看。",al={"眼睛与伪装","需要伪装吗","伪装在哪里"}}},fp="18,145,11.282.0,26.92.0,28.76.0,24.82.0,24.65.0,22.79.0,22.105.0"}
P.entries["quest:78699"] = {n="The Eye of Bhossca",s="箱子里有一张留给你的便笺。写信人只署了首字母 C。",h="箱子里有一张留给你的便笺。写信人只署了首字母 C。",kw={"bhossca","c","箱子","eye of bhossca","留意消息","便笺"},sec={{t="便笺",b="箱子里有一张写给你的便笺。写信人说会留意你的消息，随后署上字母 C。"}},faq={{q="是谁留下了便笺？",a="便笺署名只有首字母 C，没有写出全名。",al={"c 是谁","是谁写的","c 写的便笺"}},{q="便笺上写了什么？",a="写信人告诉你会留意你的消息，并署上首字母 C。",al={"箱子里有什么","eye of bhossca 便笺","c 写了什么"}},{q="便笺在哪里？",a="便笺放在一个箱子里。",al={"便笺在哪里","箱子里的便笺"}}},fp="18,74,8.119.0,18.61.0,23.84.0,18.25.0"}
P.entries["quest:787"] = {n="新的部落",s="“新部落”是试炼谷的一项入门任务，由老兵伊崔格指派。任务引导新兵向大兽穴内的高内克报到，以开始他们的训练。通过这次简短的召集，伊崔格分享了他个人的经历，以及萨尔对于救赎后的部落所构想的愿景。",h="“新部落”是试炼谷的一项入门任务，由老兵伊崔格指派。任务引导新兵向大兽穴内的高内克报到，以开始他们的训练。通过这次简短的召集，伊崔格分享了他个人的经历，以及萨尔对于救赎后的部落所构想的愿景。",kw={"燃烧军团","杜隆塔尔","伊崔格","高内克","新部落","大兽穴","萨尔","试炼谷"},ang={["faction:Horde"]="这项任务概括了萨尔政权建立的基本精神：彻底断绝恶魔的奴役，转而追求荣誉、生存和祖先的身份认同。",["race:Orc"]="对于走进试炼谷的年轻兽人来说，伊崔格代表了他们种族悲惨过去的鲜活记忆，以及他们在萨尔领导下的救赎。",["race:Troll"]="暗矛巨魔在试炼谷与兽人并肩训练，他们已经拥抱了萨尔关于相互生存和荣誉的愿景。"},sec={{t="老兵的回归",b="伊崔格站在试炼谷，受大酋长萨尔之命负责评估和指导部落最新的希望之星。他在第二次战争后因对旧部落被燃烧军团腐蚀感到幻灭而离开，并在流亡中隐居，直到被人类俘虏。在被萨尔救出后，得知这位年轻大酋长的梦想——一个植根于萨满教义、彻底切断与恶魔主子联系的荣誉部落——他选择了回归。"},{t="向大兽穴报到",b="任何新兵在冒险走出试炼谷那崎岖的峡谷之前，都必须证明自己的实力。伊崔格会派遣新人进入被称为“大兽穴”的阴凉洞穴去见高内克。虽然高内克对新加入的应募者那粗糙的状态几乎从不委婉评价，但他的监督确保了只有那些掌握了纪律与生存之道的人，才被允许进入杜隆塔尔的更广阔天地。"}},faq={{q="谁是伊崔格？",a="伊崔格是一位年迈的兽人老兵，曾亲眼目睹了旧部落在燃烧军团影响下的堕落。心灰意冷之下，他在洛丹伦选择了自我流放。在被人类俘虏并随后被萨尔解放后，他向萨尔新改组的部落宣誓效忠，现在协助监督在试炼谷的新兵训练。",al={"谁是伊崔格","伊崔格背景故事","伊崔格背景知识"}},{q="为什么伊崔格会谈论“新部落”？",a="最初的部落曾在燃烧军团的摆布下被恶魔的嗜血冲动所操纵和奴役。萨尔建立的新部落旨在抛弃恶魔的控制，复兴传统的萨满之道，并为卡利姆多的兽人及其盟友建立一个荣耀、自主的未来。",al={"什么是新部落","新旧部落的区别","新部落的含义"}},{q="高内克在哪里？",a="高内克驻扎在大兽穴的入口处，那是试炼谷北侧岩壁上开凿出的一处显眼的洞穴。",al={"高内克在哪里","找到高内克","高内克位置"}},{q="向高内克报到后会发生什么？",a="高内克会接纳你成为伊崔格的学员之一，并交给你最初的实地任务，让你通过保卫山谷来投入工作，并测试你为部落效力的准备情况。",al={"新部落任务后的下一个任务","高内克做什么","高内克任务"}},{q="伊崔格为何被流放？",a="伊崔格离开部落是因为他对早期战争中术士侍奉燃烧军团所造成的恶魔腐蚀和毫无意义的屠杀感到厌恶。",al={"伊崔格为什么离开","伊崔格流放原因","伊崔格恶魔腐蚀"}},{q="为什么新兵要在试炼谷受训？",a="试炼谷为杜隆塔尔的年轻兽人和盟友新人提供了一个隐蔽、崎岖的环境，让他们在踏入更广阔的世界之前，能在老兵教官的注视下应对凶猛的野兽和蝎虫。",al={"为什么要试炼谷","试炼谷的目的","试炼谷训练"}}},fp="13,193,18.420.0,20.300.0,15.309.0,44.243.0,24.115.0,39.181.0,23.158.0,49.204.0"}
P.entries["quest:789"] = {n="工蝎的尾巴",s="“蝎尾之毒”是高内克交给试炼谷大兽穴中部落新兵的一项早期试炼。新手们需要前往营地西北方猎杀毒蝎工蜂，并带回十根尾巴，以证明他们的战斗准备已经就绪。这项任务旨在通过实战来教会新兵如何在战场险境中生存，以及无论对手多么弱小都不能轻视。",h="“蝎尾之毒”是高内克交给试炼谷大兽穴中部落新兵的一项早期试炼。新手们需要前往营地西北方猎杀毒蝎工蜂，并带回十根尾巴，以证明他们的战斗准备已经就绪。这项任务旨在通过实战来教会新兵如何在战场险境中生存，以及无论对手多么弱小都...",kw={"解药","杜隆塔尔","高内克","蝎子","蝎子工蜂","蝎尾之毒","大兽穴","试炼谷","剧毒"},ang={["class:Warrior"]="高内克将蝎子狩猎视为磨练战斗意志的基础课程，提醒战士们决断的打击可以克服坚硬的甲壳，而对弱小敌人的傲慢则会引致失败。",["race:Orc"]="对于在试炼谷成年的年轻兽人来说，猎杀剧毒蝎子是一项由高内克监督的必要试炼，旨在考验他们的耐力和战场意识。",["race:Troll"]="与部落一同在试炼谷进行训练的暗矛巨魔，也必须在深入杜隆塔尔之前证明他们对抗当地蝎子的勇武。"},sec={{t="毒刺的试炼",b="在烈日炙烤的试炼谷峡谷中，高内克通过让他们对抗当地野生生物来考验部落新兵。大兽穴西北方干旱土地上游荡的剧毒蝎子，曾让经验丰富的战士和笨拙的初学者同样吃过苦头。为了证明他们的战场能力，年轻的勇士必须深入岩石地带，击杀蝎子工蜂，并带回十根被切下的尾巴作为武艺的证明。"},{t="剧毒与警惕",b="虽然这些剧毒捕食者十分致命，但它们也为受伤的新手提供了救命良药。大兽穴储备有直接从蝎毒中提取并酿制而成的抗毒剂，专门用于救治受伤的新手。除了如何规避毒素之外，高内克还强调了一个核心的战术道理：在激烈的战场上，傲慢是致命的，即使是最小的敌人也足以用其致命的毒素放倒强大的战士。"}},faq={{q="谁发布了“蝎尾之毒”任务？",a="高内克，负责监督试炼谷大兽穴新兵训练的战歌军官，会向年轻的战士和冒险者发布此项试炼。",al={"谁发布蝎尾之毒","蝎子任务发布者","高内克任务"}},{q="蝎子在哪里？",a="蝎子工蜂大量栖息在试炼谷大兽穴的正西北方，在干旱的红色峡谷地形中游荡。",al={"哪里寻找蝎子","蝎子位置","试炼谷蝎子"}},{q="高内克要求从狩猎中带回什么？",a="高内克要求带回十根蝎子工蜂的尾巴，作为新兵已经面对过这些剧毒野兽并取得战斗胜利的确凿证据。",al={"蝎子掉落什么","蝎子任务物品","蝎子尾巴"}},{q="如何制造蝎毒解药？",a="蝎毒解药是直接从这些生物的毒刺中提取毒液酿制而成的。大兽穴储备有充足的解药，用于治疗那些低估了猎物的小看者。",al={"蝎毒治疗","解药设定","蝎毒解药如何制作"}},{q="高内克希望新兵学到什么教训？",a="高内克利用这次狩猎来教导新手战士，任何对手，无论大小，都具备致命的潜力。在面对看似弱小的生物时，战场上的过度自信很快就会导致死亡。",al={"高内克的教诲","为什么要猎杀蝎子","蝎子试炼目的"}},{q="在这场狩猎之后，高内克是否提供进一步的训练？",a="在交回尾巴后，高内克会表示他在大兽穴没什么可以再教你的了，并让你前往杜隆塔尔继续为部落效力。",al={"蝎尾之毒后要做什么","高内克的下一个任务","高内克是否教导更多内容"}}},fp="20,154,20.271.0,19.277.0,33.122.0,31.66.0,39.103.0,46.138.0,47.135.0,51.138.0"}
P.entries["quest:79"] = {n="斯塔文的传说",s="这个任务标志着关于斯塔文·密斯特曼托的零散传言汇聚成了无可辩驳的残酷罪证。旅店老板斯密茨交出了长期隐藏的沾满泥污的日记书页，并指引调查者直接去找夜色镇的指挥官阿尔泰娅·埃伯洛克。",h="这个任务标志着关于斯塔文·密斯特曼托的零散传言汇聚成了无可辩驳的残酷罪证。旅店老板斯密茨交出了长期隐藏的沾满泥污的日记书页，并指引调查者直接去找夜色镇的指挥官阿尔泰娅·埃伯洛克。",kw={"夜色镇","暮色森林","埃伯洛克","调查","密斯特曼托","沾满泥污的日记","夜色守夜人","斯密茨","斯塔文"},ang={["class:Paladin"]="将尘封已久的谋杀案公之于众，履行了圣骑士的使命，要求为在暮色森林阴影中惨遭杀害的无辜生命伸张正义。",["class:Rogue"]="在酒馆和布满灰尘的箱子之间拼凑笔迹样本，体现了追踪难以捉摸的猎物时通常所需的耐心侦探工作。",["faction:Alliance"]="这项调查展示了在暴风城的官方支持完全缺席时，南部地区必须依靠游荡的联盟英雄来执行正义。"},sec={{t="夜色镇的突破",b="多年来，一个来访贵族家庭的凄惨命运一直是暮色森林中一桩未解的悲剧。旅店老板斯密茨和当时担任暴风城卫队队长的哈格德警官最初调查了屠杀现场，并发现了几页撕裂且沾满泥污的日记。由于缺乏笔迹样本或佐证文件，这些记录一直未能取得进展，无法正式指控传闻中隐居在荒野里的那个人。在艾尔文森林、西部荒野和暮色森林收集到的证据最终将笔迹与斯塔文·密斯特曼托联系了起来，将镇上的流言转变成了一起证据确凿的谋杀案。"},{t="诉诸卫兵",b="夜色镇一直生活在亡灵、野兽以及潜伏在森林阴影中更可怕的威胁的持续围困之下。当城镇的生存都岌岌可危时，指挥官阿尔泰娅·埃伯洛克对于无稽之谈或毫无根据的怀疑几乎没有耐心。交出这些沾满泥污的书页，架起了冰冷的历史与即时军事正义之间的桥梁。在暮色森林的土地上看到屠杀的确凿证据后，夜色守夜人终于被迫承认斯塔文·密斯特曼托不仅仅是一个古怪的隐士或鬼故事的主角，而是一个必须绳之以法的危险逃犯。"}},faq={{q="旅店老板斯密茨一直掌握着什么证据？",a="几年前，斯密茨曾与哈格德一起调查那场来访贵族的屠杀事件。他们在现场找回了撕裂且沾满泥污的日记书页，但直到现在才缺乏匹配的笔迹样本来证明斯塔文·密斯特曼托就是作者。",al={"斯密茨 日记书页","沾满泥污的日记书页","斯密茨发现了什么"}},{q="为什么斯密茨没有早点向埃伯洛克指挥官报告这件事？",a="由于缺乏将沾满泥污的书页上的笔迹与那位隐居的家庭教师联系起来的证据，斯密茨和哈格德当时只有一些推测性的碎片。向埃伯洛克指挥官呈报未经证实的谣言，会被视为对夜色守夜人紧缺人力的无用浪费，从而被驳回。",al={"为什么等这么久","为什么要隐瞒这些书页","为什么斯密茨不告诉卫兵"}},{q="指挥官阿尔泰娅·埃伯洛克是谁？",a="指挥官阿尔泰娅·埃伯洛克是夜色守夜人的首领，这是一支负责守卫夜色镇并在暮色森林的道路上巡逻，以抵御亡灵和森林掠食者的城镇民兵组织。",al={"埃伯洛克是谁","阿尔泰娅·埃伯洛克的职责","夜色镇指挥官"}},{q="暮色森林发生了什么大屠杀？",a="几年前，一个来访的贵族家庭在暮色森林中遭到屠杀。虽然传言指向他们以前的家庭教师斯塔文·密斯特曼托，但当地调查人员最初缺乏指控他所需的决定性证据。",al={"什么屠杀","贵族被屠杀","谁被谋杀了"}},{q="这一步骤在整体调查中处于什么位置？",a="这一步代表了从私人调查向正式司法的过渡。在查阅了三个地区的登记册、学校记录和家庭箱子后，你将收集到的证据交给地方当局，以批准对斯塔文采取行动。",al={"斯塔文任务线进度","进行到哪一步了","这是任务的终点吗"}},{q="为什么夜色守夜人如此不情愿调查旧案？",a="夜色镇每天都面临着被游荡的憎恶、狼人族群和蜘蛛毁灭的直接威胁。埃伯洛克指挥官必须将所有可用的守夜人集中在生存问题上，这意味着冷案在得到无可辩驳的证据之前，她不会分出人力去调查。",al={"为什么埃伯洛克很忙","夜色镇防御优先级","夜色守夜人的优先事项"}}},fp="21,154,27.512.0,22.452.1,51.215.0,61.186.0,34.169.0,37.179.0,56.226.0,62.210.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="“……以及你找到的那张便条”始于一个不久前废弃的营地，营火余烬尚存，补给散落一地。余烬之中躺着一张被烧焦起泡的羊皮纸，上面写着一条关于寻找“双生之地”的谜语。由于没有其他向导，这张烧焦的残片成为了追寻遗留之物的唯一线索。",h="“……以及你找到的那张便条”始于一个不久前废弃的营地，营火余烬尚存，补给散落一地。余烬之中躺着一张被烧焦起泡的羊皮纸，上面写着一条关于寻找“双生之地”的谜语。由于没有其他向导，这张烧焦的残片成为了追寻遗留之物的唯一线索。",kw={"以及你找到的那张便条","起泡的便条","烧焦的便条","余烬","最近的营火","散落的物资","双生之地"},sec={{t="荒野余烬",b="在最近的一次营火的余温和散落的物资旁，躺着一张受损且起泡的纸。曾在此处停留的人不久前刚刚离开，只留下了正在冷却的余烬和一张险些被火焰吞噬的羊皮纸残片。现场迹象显示离开时非常匆忙或突发状况导致，物资甚至未加遮蔽地暴露在外。"},{t="晦涩的谜语",b="这张幸存的羊皮纸残片上写着一条神秘的指令：“并非所有燃烧之物皆已散失。寻觅双生之地，寻觅此处。”由于在火灾中没有留下签名、坐标或更多背景信息，这张烧焦的残片成了偶然发现它的人唯一的踪迹线索。"}},faq={{q="营地里找到的便条上写着什么？",a="这张烧焦、起泡的便条上写着一条神秘的信息：“并非所有燃烧之物皆已散失。寻觅双生之地，寻觅此处。”这是废弃营地里留下的唯一线索。",al={"便条上写了什么","便条正文","起泡的便条"}},{q="是谁留下了这张便条？",a="作者尚不得而知。它是在最近一次营火的余烬旁，在散落的物资中被发现的。这表明撰写或持有此便条的人不久前刚刚离开，或是被迫匆忙离去。",al={"便条来自何处","谁写了便条","谁生起的营火"}},{q="“双生之地”指的是什么？",a="便条中神秘地提到了“双生之地”，指引读者去寻找一个匹配或镜像的地点。这张烧焦的残片没有提供进一步的解释，将其实际含义留给旅行者自行解开谜题。",al={"什么是双生之地","双生之地线索"}},{q="该如何根据便条上的线索行动？",a="由于地图上没有标记明确的目的地，便条上烧焦的残余是你的唯一向导。要解开其中的谜语，必须寻找一个与便条中神秘描述相呼应的土地或地点。",al={"如何处理便条","任务导向何处"}},{q="为什么营地会被废弃？",a="现场显示出匆忙离开或遭遇突发状况的迹象，物资被留在了正在熄灭的余烬旁。除了幸存的那张起泡的纸片外，没有留下任何可以辨识身份的装备或标记。",al={"谁废弃了物资","散落物资的营地"}},{q="营火处还有其他线索吗？",a="营火处没有留下任何完好的文字或标记。火焰摧毁了几乎所有东西，只留下了那张起泡的纸片作为曾有人在此休息的幸存证据。",al={"营火还揭示了什么","营地线索"}}},fp="27,170,18.258.0,16.233.0,45.156.0,25.202.0,35.159.0,40.148.0,31.183.0,38.169.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="这张烧焦的字条在西部荒野一处即将熄灭的营火灰烬中被发现，留下了一条晦涩而孤独的线索。其灼烧的讯息暗示了世上某处等待着的目的地，敦促发现者去寻找一片“孪生之地”。",h="这张烧焦的字条在西部荒野一处即将熄灭的营火灰烬中被发现，留下了一条晦涩而孤独的线索。其灼烧的讯息暗示了世上某处等待着的目的地，敦促发现者去寻找一片“孪生之地”。",kw={"烧焦的字条","营火","灰烬","字条","孪生之地","西部荒野"},ang={["class:Rogue"]="对那些依靠低语、秘密和隐秘信件生活的人来说，解读留在隐蔽营地中的晦涩线索是他们的第二天性。",["faction:Alliance"]="对于试图恢复西部荒野秩序的冒险者来说，一个身份不明的营地和一道神秘的暗语，代表着王国边境上又一个正在展开的谜团。"},sec={{t="熄灭的营火",b="在西部荒野那荒废的田野、搜刮一空的农庄和饱经风霜的平原之间，旅行者经常会遇到流浪汉、不法之徒或绝望的流民营地。然而，这座小营地却是在匆忙或秘密中被遗弃的，补给品被弃之不顾，灰烬中仍有微光闪烁。在散乱的残骸中，留着一张在火灾中幸存下来的烧焦羊皮纸。"},{t="晦涩的讯息",b="这张烧焦的字条上只写着两句简短的话：“并非所有燃烧之物皆已遗失。寻找孪生之地，寻找那个地方。”这些话语笼罩在谜团之中，既像是一道神秘的谜题，又像是一份邀请，指引人们离开西部荒野那凄凉的田野，前往另一个在名称、地理或命运上与之相连的领域。"}},faq={{q="字条上写了什么？",a="这张烧焦的字条上写着：“并非所有燃烧之物皆已遗失。寻找孪生之地，寻找那个地方。”这是被遗弃的营地中留下的唯一线索。",al={"字条内容","字条上写了什么","烧焦字条上的话"}},{q="这张字条在哪里被发现？",a="这张字条是在西部荒野野外的一处近期营火残骸和散落的补给品中被发现的。",al={"字条位置","字条在哪里","营火位置"}},{q="是谁留下了这个营火？",a="作者身份不明。无论谁生起了这堆火，都已经离开不久，留下了散乱的补给品和灰烬中烧焦的讯息。",al={"谁留下了字条","营火主人","字条作者"}},{q="“孪生之地”指的是什么？",a="这个短语是一个谜题，指向世上另一个与发现地相互映照或有着某种联系的地区，尽管这张烧焦的字条没有提供进一步的解释。",al={"孪生之地的含义","什么是孪生之地","孪生之地在哪里"}},{q="为什么字条会被烧焦？",a="这张字条是在营火的灰烬中被烫伤和烧焦的，这表明有人要么是匆忙中试图将其销毁，要么是在火焰熄灭时漫不经心地将其丢弃。",al={"为什么它会被烧毁","有人试图烧毁字条吗","烧焦的字条"}},{q="这与迪菲亚潜行者有关吗？",a="虽然西部荒野到处都是迪菲亚潜行者和赤贫的非法定居者，但这条讯息的晦涩本质表明其含义比普通的强盗通讯更为隐晦。",al={"迪菲亚字条","是迪菲亚吗","兄弟会营火"}}},fp="27,115,12.296.0,19.240.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:7901"] = {n="Soft Bushy Tails",s="在暗月马戏团，收集蓬松的尾巴可以为游客准备奖品。马戏团希望开心的游客能带其他人一起来。",h="在暗月马戏团，收集蓬松的尾巴可以为游客准备奖品。马戏团希望开心的游客能带其他人一起来。",kw={"暗月马戏团","奖品","柔软蓬松的尾巴","尾巴","奖券","游客"},sec={{t="马戏团奖品",b="游客开心，暗月马戏团就能吸引更多人。你带来的尾巴会成为送给游客的奖品，满意的游客也许还会告诉朋友来这里游玩。马戏团会给你奖券，欢迎你在这里尽情游玩。"}},faq={{q="蓬松的尾巴有什么用？",a="暗月马戏团会把它们用作送给游客的奖品。",al={"尾巴的用途","蓬松尾巴的用途","马戏团用的尾巴"}},{q="马戏团为什么希望游客开心？",a="开心的游客也许会把马戏团介绍给朋友，带来更多游客。",al={"游客开心的原因","马戏团游客","更多马戏团游客"}},{q="马戏团会给你什么？",a="马戏团会给你奖券。",al={"马戏团奖券","我能得到什么","尾巴换奖券"}}},fp="16,143,12.228.0,29.60.0,39.78.0,29.28.0"}
P.entries["quest:7905"] = {n="The Darkmoon Faire",s="你带着一张Free Ticket Voucher，要交给Darkmoon Faire游乐场内的Gelvas Grimgate。这张兑换券是给他的。",h="你带着一张Free Ticket Voucher，要交给Darkmoon Faire游乐场内的Gelvas Grimgate。这张兑换券是给他的。",kw={"游乐场","darkmoon faire","free ticket voucher","gelvas grimgate","兑换券"},sec={{t="给Gelvas的兑换券",b="Gelvas Grimgate在Darkmoon Faire游乐场内，你带着一张要交给他的Free Ticket Voucher。这张兑换券尚待送达。"}},faq={{q="兑换券是给谁的？",a="Free Ticket Voucher是给Gelvas Grimgate的，他在Darkmoon Faire游乐场内。",al={"兑换券给谁","gelvas兑换券"}},{q="Gelvas Grimgate在哪里？",a="Gelvas Grimgate在Darkmoon Faire游乐场内。",al={"gelvas在哪里","gelvas位置"}},{q="我要带什么给Gelvas？",a="把Free Ticket Voucher交给Gelvas Grimgate。",al={"什么兑换券","门票兑换券"}}},fp="18,116,20.128.0,23.90.0,25.54.0,26.49.0"}
P.entries["quest:79091"] = {n="Archmage Antonidas: The Unabridged Autobiography",s="这个任务需要找回大法师安东尼达斯详尽的个人回忆录，他曾是备受尊崇的肯瑞托领袖。这本珍贵的书卷原藏于铁炉堡的宏伟档案馆中，为研究达拉然的历史和高等奥术学识提供了不可替代的洞见。",h="这个任务需要找回大法师安东尼达斯详尽的个人回忆录，他曾是备受尊崇的肯瑞托领袖。这本珍贵的书卷原藏于铁炉堡的宏伟档案馆中，为研究达拉然的历史和高等奥术学识提供了不可替代的洞见。",kw={"安东尼达斯","奥术","大法师安东尼达斯","自传","达拉然","探险者大厅","铁炉堡","肯瑞托","图书馆","法师"},ang={["class:Mage"]="大法师安东尼达斯是肯瑞托最伟大的领袖之一，也是奥术学术的典范。研究他的生平和个人著作对任何奥术练习者来说都能提供至关重要的见解。",["faction:Alliance"]="安东尼达斯曾是洛丹伦联盟对抗兽人部落和天灾军团的中流砥柱，这使得他的个人回忆录成为整个联盟领地内珍贵的历史记录。",["race:Dwarf"]="这卷书源自铁炉堡探险者大厅里的大图书馆，不过接收它的学者似乎并不在意夺走了矮人档案管理员的一本珍稀书籍。",["race:Human"]="安东尼达斯是一位受人尊敬的人类大法师，他带领肯瑞托和达拉然度过了第二次和第三次战争，这使得他的全本自传成为了一段珍贵的人类历史。"},sec={{t="大法师的箴言",b="大法师安东尼达斯是艾泽拉斯最聪慧的头脑之一，他曾担任肯瑞托的尊崇领袖及达拉然的统治者长达数十年。他的全本自传记载了他从紫罗兰城堡中不断晋升的过程、他对奥术的精通，以及在第二次和第三次战争那动荡时期中的领导经历。对于魔法学者和施法者来说，安东尼达斯的第一手回忆为深入了解达拉然的内幕和奥术艺术提供了一个绝佳窗口。"},{t="来自铁炉堡大图书馆",b="在被送往新家之前，这份珍稀的手稿一直存放于铁炉堡的大图书馆内，与探险者大厅里的古代泰坦遗物和矮人史料一同保管。矮人们拥有从艾泽拉斯各处的废墟和外邦王国中收集来的庞大藏书，这使得他们的档案馆成为了珍稀文献的宝库。然而，其他地方的奥术学者们却渴望将这些作品据为己有，他们确信忙碌的矮人档案管理员绝不会注意到少了一本书。"}},faq={{q="大法师安东尼达斯是谁？",a="大法师安东尼达斯曾是肯瑞托的长期领袖，也是魔法城市达拉然的统治者。作为一位传奇的奥术大师，他在第二次战争期间担任洛丹伦联盟的关键顾问，并在第三次战争中为了保卫达拉然而牺牲前，曾向泰瑞纳斯国王警告过瘟疫的到来。",al={"安东尼达斯是谁","大法师安东尼达斯背景故事","安东尼达斯身世"}},{q="什么是全本自传？",a="这是由大法师安东尼达斯本人撰写的详尽全本自传，详细记述了他的生平、学术研究以及在达拉然的领导生涯。鉴于他作为肯瑞托首领的地位，他的个人著作是一份极具价值的历史和魔法记录。",al={"这本书是什么","全本自传","安东尼达斯书卷"}},{q="这本书是从哪里来的？",a="这卷书是从铁炉堡的图书馆中获取的，原本存放于这座矮人要塞的探险者大厅里。矮人的探险家和档案管理员经常从东部大陆各地收集历史和魔法文献。",al={"书的来源","这书来自铁炉堡吗","铁炉堡图书馆书籍"}},{q="为什么要搜寻这本书？",a="学者和图书管理员们不断地搜寻强大或具有历史意义的魔法文献，以扩充他们的馆藏并保存奥术知识，尤其是那些由传奇法师所著、否则可能会失传或埋没在异国馆藏中的作品。",al={"为什么要收集魔法书","谁想要安东尼达斯的书","图书馆为何需要这本书"}},{q="大法师安东尼达斯遭遇了什么？",a="大法师安东尼达斯在第三次战争中，当堕落的阿尔萨斯·米奈希尔王子率领天灾军团入侵达拉然时不幸牺牲。安东尼达斯升起了一道强大的魔法结界来保卫城市及其秘密，但阿尔萨斯突破了防御，并击杀了他以夺取麦迪文之书。",al={"安东尼达斯死了吗","安东尼达斯是怎么死的","安东尼达斯发生了什么"}},{q="铁炉堡图书馆会发现书丢了吗？",a="收件人随口打消了关于矮人会察觉书本丢失的顾虑，认为铁炉堡的档案库规模宏大，少了一本书很可能根本不会被发现。",al={"铁炉堡会发现书丢了吗","从铁炉堡图书馆窃取"}}},fp="48,205,28.382.0,35.417.0,27.304.0,37.216.0,30.178.0,36.224.0,36.278.0,51.163.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="《塞欧克瑞图斯大法师的研究日志》是一卷记载了阿祖拉之塔的大法师所进行研究的奥术文献。这本日志被送往铁炉堡图书馆的学者手中，为这座伟大的矮人档案馆增添了宝贵的魔法见解。",h="《塞欧克瑞图斯大法师的研究日志》是一卷记载了阿祖拉之塔的大法师所进行研究的奥术文献。这本日志被送往铁炉堡图书馆的学者手中，为这座伟大的矮人档案馆增添了宝贵的魔法见解。",kw={"奥术知识","塞欧克瑞图斯大法师","铁炉堡","铁炉堡图书馆","研究日志","塞欧克瑞图斯","阿祖拉之塔"},ang={["class:Mage"]="奥术学者们珍视来自塞欧克瑞图斯大法师等杰出人物的笔记，他的研究有助于保护铁炉堡档案馆中的历史魔法论著。",["faction:Alliance"]="搜集稀有文本和日志丰富了铁炉堡核心地带为所有联盟学者所建立的庞大知识库。"},sec={{t="大师的实地笔记",b="塞欧克瑞图斯大法师在整个联盟中以一位受人尊敬的施法者而闻名，他驻扎在艾尔文森林东部边缘的阿祖拉之塔。经过多年的潜心研究，塞欧克瑞图斯调查了许多奇特的文物、能量线异常以及附近的魔法威胁，并将他的发现记录在详细的日志中。找回这样一卷日志，是研究一位肯瑞托资深大法师个人观察记录的难得机会。"},{t="扩充铁炉堡档案馆",b="探险者协会和铁炉堡图书馆的管理员们维护着大陆上最伟大的档案库之一。通过将《塞欧克瑞图斯大法师的研究日志》交付给他们，冒险者确保了其中的奥术见解能够被安全地保存，并与卡兹莫丹的历史卷宗一起编目收藏。图书管理员们热烈欢迎任何能进一步拓宽他们集体智慧的魔法发现。"}},faq={{q="什么是《塞欧克瑞图斯大法师的研究日志》？",a="这是一本属于塞欧克瑞图斯大法师的学术研究日志，上交至铁炉堡图书馆以保存奥术知识并扩充档案。",al={"塞欧克瑞图斯日志上交","什么是塞欧克瑞图斯日志"}},{q="塞欧克瑞图斯大法师是谁？",a="塞欧克瑞图斯大法师是一位著名的人类法师，他居住在艾尔文森林的阿祖拉之塔，研究古代魔法干扰和文物。",al={"谁是塞欧克瑞图斯","塞欧克瑞图斯大法师背景"}},{q="这本日志会被带到哪里？",a="这本日志会被带给铁炉堡图书馆的档案管理员，他们负责为馆藏收集稀有文献和魔法手稿。",al={"我在哪里上交塞欧克瑞图斯日志","谁想要塞欧克瑞图斯日志"}},{q="为什么图书馆想要这本日志？",a="铁炉堡图书馆的学者们致力于保存奥术知识，并研究来自施法大师的稀有论著，以扩充他们的历史记录。",al={"为什么收集魔法日志","塞欧克瑞图斯日志的用途"}},{q="还有更多的魔法作品可以送到图书馆吗？",a="是的，馆长们鼓励冒险者继续在世界各地寻找失落的魔法作品和历史文献，以帮助他们的档案收集工作。",al={"还有更多日志可以上交吗","还有其他书籍给图书馆吗"}},{q="日志中包含了什么样的研究？",a="这本日志包含了塞欧克瑞图斯大法师在对魔法现象和奥术知识进行广泛调查期间所编写的笔记和观察记录。",al={"塞欧克瑞图斯日志里有什么","塞欧克瑞图斯日志的内容"}}},fp="37,199,22.424.0,32.354.0,46.168.0,27.150.0,30.121.0,39.156.0,51.99.0,50.131.0"}
P.entries["quest:79093"] = {n="Rumi of Gnomeregan: The Collected Works",s="“Rumi of Gnomeregan: The Collected Works”涉及寻回并上交一卷侏儒著作汇编，以扩充图书馆的藏书。通过递交这些珍贵的文献，冒险者可以帮助学者们保护宝贵的历史和魔法知识，使其免于失传。",h="“Rumi of Gnomeregan: The Collected Works”涉及寻回并上交一卷侏儒著作汇编，以扩充图书馆的藏书。通过递交这些珍贵的文献，冒险者可以帮助学者们保护宝贵的历史和魔法知识，使其免于失传。",kw={"合集著作","诺莫瑞根背景知识","侏儒著作","图书馆","魔法著作","诺莫瑞根的卢米"},ang={["class:Mage"]="奥术学者非常重视从艾泽拉斯各地寻回的珍稀和奇特的著作，尤其是那些能扩展人们对魔法理论和历史的集体理解的作品。",["faction:Alliance"]="联盟的学者和馆长不断寻求寻回并保护珍贵的文学和魔法文献，以造福联盟的共同知识。",["race:Gnome"]="对于那些在诺莫瑞根陷落后试图保护本族文化和智力贡献的侏儒来说，确保像卢米这样思想家的著作合集被安全地归档，是关乎遗产传承的大事。"},sec={{t="保护侏儒智慧",b="“Rumi of Gnomeregan: The Collected Works”代表了保护著名的侏儒文学作品和智力成就的努力。在诺莫瑞根被穴居人侵占而惨遭沦陷后，许多侏儒的文字遗产流散、掩埋或面临毁灭的威胁。在图书馆和学术中心工作的学者与档案管理员们正积极搜寻幸存的手稿、专著和汇编，以确保侏儒思想家的智慧和创造力不会随着时间流逝而湮灭。"},{t="档案回收",b="当冒险者在野外发现这些合集卷册并将其送交档案馆时，馆长会急切地将其纳入不断增长的藏品库中。档案管理员将每一份寻回的手稿都视为对集体认知的一次扩展，并鼓励旅行者带回他们发现的任何进一步的魔法或历史文献。通过这些贡献，知识得以让那些致力于保护艾泽拉斯学术遗产的学者、法师和历史学家们查阅。"}},faq={{q="什么是“诺莫瑞根的卢米：全集”？",a="“诺莫瑞根的卢米：全集”是一项涉及寻回并贡献一份著名的侏儒著作汇编的任务。冒险者将这些文学资料交给一位正在构建图书馆藏书的学者，以确保宝贵的知识得以保存和研究。",al={"诺莫瑞根的卢米任务","什么是诺莫瑞根的卢米","谁是卢米"}},{q="这些合集应该交给谁？",a="这些合集被上交给维护图书馆藏书的馆长或学者。接收者会搜寻重要的著作和魔法专著，以扩充他们的档案馆藏。",al={"在哪里上交卢米的作品","谁接收卢米的著作","卢米合集上交"}},{q="图书馆为什么要这些合集？",a="学者和档案管理员积极从世界各地搜集珍稀文献、历史专著和魔法手稿，以确保重要的学术成果得以保存，特别是那些源自诺莫瑞根的著作。",al={"为什么要收集卢米的著作","诺莫瑞根的卢米的目的","为什么图书馆需要卢米的著作"}},{q="谁是诺莫瑞根的卢米？",a="诺莫瑞根的卢米是一位知识分子或魔法作家，其汇编的著作备受档案管理员追捧。由于诺莫瑞根大部分地区已被占领，幸存的侏儒思想和学识合集便成为了他们学术传统的珍贵记录。",al={"诺莫瑞根的卢米是谁","卢米背景知识","卢米作者"}},{q="之后还可以带更多的书去图书馆吗？",a="可以，档案管理员欢迎更多的发现。馆长鼓励冒险者继续搜寻珍稀或重要的魔法专著和历史著作，将其添加到馆藏中。",al={"还有更多的书可以找吗","我可以带更多的文献吗","更多的魔法著作图书馆"}},{q="谁能完成这项任务？",a="该任务由协助学者保护历史和奥术文献的联盟冒险者承担。任何寻回这些珍贵文献的人都可以将其呈交给档案馆，以助力学术研究。",al={"卢米任务要求","谁可以上交卢米的作品","仅限联盟卢米"}}},fp="39,157,26.247.0,17.333.0,48.182.0,42.153.0,48.189.0,26.191.0,52.147.0,27.160.0"}
P.entries["quest:79094"] = {n="The Lessons of Ta'zo",s="图书管理员请你将《Ta'zo的教诲》等魔法著作带到图书馆。每新增一部著作，都能丰富馆藏并拓展知识。",h="图书管理员请你将《Ta'zo的教诲》等魔法著作带到图书馆。每新增一部著作，都能丰富馆藏并拓展知识。",kw={"馆藏","铁炉堡","知识","教诲","图书馆","魔法著作","ta'zo"},sec={{t="图书馆的馆藏",b="图书管理员问你是否带来了可供图书馆收藏的东西。欢迎捐赠可能对图书馆有益的魔法著作，你的努力也能拓展馆藏知识。"}},faq={{q="谁在征集魔法著作？",a="图书管理员请你带来可能对图书馆有益的魔法著作。《The Lessons of Ta'zo》就是其中之一。",al={"ta'zo是谁","ta'zo图书馆","ta'zo"}},{q="图书管理员想让你带什么到图书馆？",a="图书管理员征集可能丰富图书馆馆藏的魔法著作。",al={"给ta'zo带什么","魔法书籍","图书馆馆藏"}},{q="馆藏存放在哪里？",a="图书管理员在暴风城和幽暗城收集这类著作。",al={"ta'zo在哪里","ironforge图书馆","图书馆位置"}},{q="图书管理员为什么征集魔法著作？",a="图书管理员说，你的努力能拓展图书馆的知识。",al={"为何征集魔法著作","拓展知识","帮助图书馆"}}},fp="20,145,22.183.0,32.114.0,52.81.0,29.63.0,45.72.0"}
P.entries["quest:79095"] = {n="The Apothecary's Metaphysical Primer",s="\"The Apothecary's Metaphysical Primer\" 是一本专门的魔法文献，馆长们希望能借此丰富学术档案。上交此书有助于为研究者和施法者保存珍贵的炼金术与奥术理论。",h="\"The Apothecary's Metaphysical Primer\" 是一本专门的魔法文献，馆长们希望能借此丰富学术档案。上交此书有助于为研究者和施法者保存珍贵的炼金术与奥术理论。",kw={"炼金术","药剂师","幽暗城","图书馆","魔法著作","形而上学入门书","典籍"},ang={["class:Mage"]="奥术修行者们非常看重形而上学入门书，因为它们对魔法理论、炼金相互作用以及施法基础定律有着深刻的见解。",["faction:Horde"]="部落的学者和冒险者们通过回收珍稀论著来协助幽暗城的Owen Thadd，以此充实图书馆的奥术知识储备。"},sec={{t="学者的收藏",b="\"The Apothecary's Metaphysical Primer\" 是一本涵盖深奥魔法原理的学术文献。馆长们致力于扩充档案，非常欢迎上交此类论著，并将这本入门书直接加入到他们的魔法参考资料收藏中。"},{t="扩充档案",b="对于幽暗城的Owen Thadd收藏馆等图书馆来说，保存这些专业论著至关重要。通过上交有关奥术和炼金理论的珍稀入门书，探险者们能够确保这些罕见的形而上学见解被妥善存档，供研究人员查阅，而不是遗失在荒野之中。"}},faq={{q="什么是 \"药剂师的形而上学入门\"？",a="\"药剂师的形而上学入门\" 是一本罕见的学术文献，馆长们希望借此丰富他们的魔法书库，并扩展对形而上学科学的理解。",al={"什么是 \"药剂师的形而上学入门\"","形而上学入门书任务","这是什么书"}},{q="谁需要这份入门书？",a="这本书要交给幽暗城的欧文·萨德，他正在搜寻魔法著作和奥术论著，以便为研究者和施法者保存知识。",al={"谁需要这本书","我应该在哪里上交入门书","谁会接收这本入门书"}},{q="图书馆为什么要收集这类著作？",a="图书馆和档案库收集形而上学和魔法著作，旨在系统地扩充其知识储备，帮助学者、炼金术师和奥术师研究奥术原理。",al={"图书馆为什么需要入门书","收集入门书的目的","为什么要收集魔法书"}},{q="你能给图书馆带来更多魔法著作吗？",a="负责整理魔法文献的学者们欢迎你发现并带来的任何奥术与学术研究成果，这些成果将丰富他们的档案。",al={"还有更多的书可以上交吗","我可以带来其他的书吗","更多的图书馆藏书"}},{q="形而上学入门书里包含了什么样的知识？",a="在魔法学术界，形而上学涉及魔法能量的基本本质、支配现实的无形力量，以及物理试剂如何与奥术力量相互作用。",al={"什么是形而上学","魔兽世界中的形而上学知识","什么是药剂师形而上学"}},{q="谁撰写了 \"药剂师的形而上学入门\"？",a="记录中并未提及撰写此书的具体药剂师，但药剂师和学者们经常编写入门书，总结实用的炼金术、草药混合配方和神秘公式。",al={"谁写了药剂师入门书","药剂师入门书作者","谁是那位药剂师"}}},fp="36,172,23.186.0,22.266.0,45.154.0,40.158.0,45.160.0,48.117.0,56.168.0,47.170.0"}
P.entries["quest:79096"] = {n="Ataeric: On Arcane Curiosities",s="“Ataeric: On Arcane Curiosities”涉及交付寻获的魔法文献，以扩充学术档案馆的馆藏。通过从野外收集晦涩的文本和论着，研究人员力求加深对奥术研究的理解并保存神秘学知识。",h="“Ataeric: On Arcane Curiosities”涉及交付寻获的魔法文献，以扩充学术档案馆的馆藏。通过从野外收集晦涩的文本和论着，研究人员力求加深对奥术研究的理解并保存神秘学知识。",kw={"奥术","奥术珍品","阿塔瑞克","图书馆","魔法作品","学者"},ang={["class:Mage"]="法师对奥术研究有着天生的兴趣，因此向学术图书馆捐赠和寻回魔法论着与他们的技艺直接相关。",["race:Dwarf"]="矮人学者和探险者协会非常重视积累书面记录、文物和深奥的学识。"},sec={{t="保存奥术知识",b="艾泽拉斯各地的学者和档案管理员都依赖四处游历的冒险者，从危险之地寻回稀有书籍和被遗忘的论着。在这个任务中，寻求者专门寻找魔法文献，以拓宽机构对奥术艺术的理解。每一本被寻回的卷册都有助于拼凑出那些本可能散佚或失传的神秘学实践。"},{t="不断扩充的档案馆",b="在收到这些珍品后，馆长会将其直接纳入档案馆的藏品库。图书馆并不认为收购任务已经完成，而是保持着对世界各地发现的任何进一步魔法文献的公开征集，确保其藏品随着持续的学术研究而不断增长。"}},faq={{q="这个任务的目的是什么？",a="“阿塔瑞克：论奥术奇观”代表着向寻求扩充图书馆深奥知识储备的收藏家交付学术或魔法文本。",al={"这是什么任务","阿塔瑞克任务","奥术珍品上交"}},{q="谁在收集这些奥术文献？",a="阿塔瑞克是该论着的作者。它会被交给正在收集魔法着作和稀有卷册以充实图书馆档案馆的研究员或馆长。",al={"谁想要这个","谁获得了这本书","谁是阿塔瑞克"}},{q="哪座图书馆受益于这些珍品？",a="寻求这些文本是为了增强学术收藏，并使接收该作品的学术图书馆受益。",al={"这是什么图书馆","这些书去了哪里"}},{q="还有更多的魔法作品可以收集吗？",a="学者特别鼓励冒险者在旅途中带回任何额外发现的魔法作品，以持续拓宽他们的知识储备。",al={"可以上交更多吗","可重复收集的魔法作品","图书馆需要的更多书籍"}},{q="为什么图书馆要寻求奥术珍品？",a="学者们不断寻找稀有的论着，以更好地理解奥术的细微差别，并保存历史性的神秘学知识。",al={"图书馆研究什么","为什么要收集奥术书籍"}},{q="为什么寻回奥术作品很重要？",a="奥术文本通常包含不稳定或晦涩的知识，因此在专门的图书馆内妥善保存和研究它们，远比让它们遗落在野外要好。",al={"这有危险吗","奥术魔法的风险"}}},fp="30,158,27.279.0,20.179.0,34.79.0,35.116.0,46.77.0,40.108.0,45.99.0,41.136.0"}
P.entries["quest:79097"] = {n="Baxtan: On Destructive Magics",s="《Baxtan: On Destructive Magics》是一个学术性的上交任务，冒险者需要将Baxtan关于破坏性法术的论著交给图书馆学者。寻回这些著作有助于图书馆的档案管理员加深对不稳定的奥术能量的理解。",h="《Baxtan: On Destructive Magics》是一个学术性的上交任务，冒险者需要将Baxtan关于破坏性法术的论著交给图书馆学者。寻回这些著作有助于图书馆的档案管理员加深对不稳定的奥术能量的理解。",kw={"奥术","巴克斯坦","书籍","破坏性魔法","图书馆","魔法","典籍"},ang={["class:Mage"]="关于破坏性魔法的学术论著自然会引起法师们的兴趣，他们致力于研究奥术力量与破坏性力量之间的平衡。",["class:Warlock"]="那些钻研不稳定或禁忌力量的施法者能够理解学者们在探究破坏性奥术时所展现出的学术兴趣。",["faction:Alliance"]="扩充联盟图书馆内收藏的知识，能够巩固整个联盟的学术基础。"},sec={{t="一本毁灭艺术典籍",b="这个任务代表了学者们在编纂和保存奥术知识方面所做的持续努力。当冒险者发现探讨破坏性魔法不稳定性本质的文本时，将其交由严谨的学术机构保管，可以确保这些艺术的力量与危险被理解，而不是失传。"},{t="整理图书馆的知识",b="图书馆是历史、科学和奥术的宝库。其学者负责获取稀有卷宗，并欢迎那些从世界各地危险角落寻回遗忘论著的旅者，以扩充图书馆的馆藏知识。"}},faq={{q="任务“巴克斯坦：论毁灭魔法”是什么？",a="这个任务的内容是将巴克斯坦的破坏性魔法论著交给图书馆学者，从而充实魔法著作的收藏。",al={"什么是巴克斯坦: 论毁灭魔法","这是一个什么任务","巴克斯坦任务"}},{q="巴克斯坦是谁？",a="巴克斯坦是《论毁灭魔法》的作者。接收这本著作的学者正负责为图书馆收集重要的书籍和魔法论著。",al={"巴克斯坦是谁","巴克斯坦 非玩家角色","巴克斯坦在哪里"}},{q="巴克斯坦在寻找什么样的书籍？",a="图书馆的学者寻求对馆藏有益的学术和魔法著作，并欢迎在世界各地发现的任何进一步的魔法论著。",al={"巴克斯坦想要什么样的书","巴克斯坦书籍收藏","给巴克斯坦的更多书籍"}},{q="这些魔法知识最终会被送到哪里？",a="收集到的文本会被纳入接收它们的图书馆的馆藏中，从而将奥术和危险艺术的知识保存下来以供研究。",al={"书会被送到哪里","哪个图书馆","铁炉堡图书馆藏书"}},{q="图书馆为什么要收集关于破坏性魔法的著作？",a="学者们编纂破坏性魔法，是为了更好地理解强大奥术能量所带来的危害、理论机制以及表现形式。",al={"为什么要研究破坏性魔法","破坏性魔法知识"}},{q="你还能给巴克斯坦带来更多的魔法著作吗？",a="可以。学者鼓励冒险者继续带来他们发现的任何额外魔法著作，这表明收集知识的工作仍在持续进行。",al={"巴克斯坦还有更多任务吗","我可以上交更多书吗"}}},fp="29,115,22.202.0,27.205.0,50.113.0,14.126.0,42.122.0,41.120.0,56.108.0,43.101.0"}
P.entries["quest:791"] = {n="新的背包",s="“各尽其责”是由弗恩·凝眉在俯瞰剃刀岭的瞭望塔顶端提供的一项入门任务。这位伤痕累累的老兵已无法再上前线作战，他请求年轻的部落冒险者从当地的敌对人类和半人马身上搜集帆布，好让他制作出能助力他们旅途的补给品。",h="“各尽其责”是由弗恩·凝眉在俯瞰剃刀岭的瞭望塔顶端提供的一项入门任务。这位伤痕累累的老兵已无法再上前线作战，他请求年轻的部落冒险者从当地的敌对人类和半人马身上搜集帆布，好让他制作出能助力他们旅途的补给品。",kw={"帆布脚料","各尽其责","杜隆塔尔","弗恩·凝眉","诺克-卡隆","剃刀岭","剃刀岭哨塔","提拉加德"},ang={["faction:Horde"]="杜隆塔尔的每一位年轻士兵都依赖像弗恩·凝眉这样经验丰富的老兵，他们时刻提醒新兵：荣耀部落意味着履行家园要求的任何职责，无论是守卫前哨站还是缝制帆布。",["profession:Tailoring"]="弗恩展示了实用且硬朗的边境裁缝手艺，将从人类入侵者和半人马掠夺者那里剥下的废弃厚帆布变成了耐用的荒野生存装备。",["race:Orc"]="弗恩代表了那一代兽人：他们摆脱了恶魔的腐化，随萨尔跨越海洋，现在正将他们的余生奉献给培育他们初建国家的未来。"},sec={{t="老兵的召唤",b="弗恩·凝眉是第三次战争的老兵，他曾追随萨尔大酋长在杜隆塔尔的拓荒时期并肩作战，也参与了海加尔山的生死保卫战。如今，因年事已高且旧伤缠身，他已无法再挥舞战斧上阵。相反，他时刻在剃刀岭的瞭望塔上保持警惕，在防范外敌入侵的同时，也尽力为下一代守卫者提供支持。"},{t="搜集的帆布",b="随着部落对该地区的掌控日益稳固，警戒号角的鸣响声也随之减少，弗恩便将空闲时间用于制作实用的装备。在杜隆塔尔干旱的峡谷中，坚韧的帆布很难获得，但东岸的库尔提拉斯入侵者以及游荡在平原上的诺克-卡隆半人马身上却携带着大量这种材料。从这些敌对势力手中搜集脚料，让弗恩有了足够的布料，可以为活跃的侦察兵缝制多功能背包。"}},faq={{q="弗恩·凝眉是谁？",a="弗恩·凝眉是一位年迈的兽人老兵，驻守在剃刀岭上方的瞭望塔中。他曾在杜隆塔尔的奠基时期与萨尔并肩作战，也曾站在击败阿克蒙德的海加尔山联军阵列中。他已无法再上前线作战，现在担任瞭望员，并利用空闲时间为年轻的部落战士制作战地装备。",al={"弗恩是谁","弗恩·凝眉背景故事","谁发布各尽其责任务"}},{q="在杜隆塔尔哪里可以找到帆布脚料？",a="帆布脚料可以从杜隆塔尔沿岸占据提拉加德城堡的库尔提拉斯人身上，以及在平原上扎营的诺克-卡隆半人马身上获得。这两个势力都携带着大量结实的编织材料，可以从他们的营地和随身物品中搜集到。",al={"哪里获得帆布脚料","谁掉落帆布脚料","帆布脚料位置"}},{q="弗恩所在的瞭望塔在哪里？",a="弗恩的瞭望塔坐落在剃刀岭正西北方的高耸岩崖上。定居点后方的一条蜿蜒小路直通山顶，那座木制瞭望建筑就立在那里。",al={"弗恩·凝眉在哪里","剃刀岭瞭望塔位置","找到剃刀岭瞭望塔"}},{q="弗恩用帆布脚料制作什么？",a="弗恩将搜集到的帆布脚料缝制成结实的多功能背包。对于在杜隆塔尔各地旅行的年轻冒险者来说，增加携带补给品、口粮和缴获武器的容量，对于在残酷的荒野中生存至关重要。",al={"弗恩制作什么","帆布有什么用","帆布脚料奖励"}},{q="为什么一位老战士要在制作背包而不是去战斗？",a="几十年的残酷战斗让弗恩的身体不堪重负，他已无法再满足战场对速度和力量的要求。他并没有哀叹自己的退役，而是以守望剃刀岭并制造能直接增强年轻战士防卫能力的装备为荣。",al={"为什么弗恩在制作物品","为什么弗恩待在塔里","为什么弗恩不战斗"}},{q="弗恩参加过哪场战争？",a="弗恩在萨尔大酋长麾下参加了第三次战争，参与了杜隆塔尔的定居过程，以及对抗燃烧军团的海加尔山决战。他自豪地回忆起在部落、暗夜精灵和联盟为了击败阿克蒙德而达成临时且必要的停战协议时，他所响应的战吼。",al={"弗恩战斗历史","弗恩以前做过什么","阿克蒙德与弗恩"}}},fp="17,233,19.360.0,16.407.0,22.324.0,44.217.0,46.165.0,44.199.0,56.218.0,27.241.0"}
P.entries["quest:79192"] = {n="Stepping Stones",s="Stepping Stones 是一项调查任务，源于在贫瘠之地崎岖荒野中贴着的一张饱经风霜的便条。潦草的字迹写着有两名信使一直在为新的瘟疫运送货物，并将发生在他们身上的事称为简单的药剂师事故。神秘的作者敦促任何找到它的人前往凄凉之地边界的一处隐秘山间避难所。",h="Stepping Stones...",kw={"凄凉之地","雇佣兵","山脉","新的瘟疫","便条","皇家药剂师协会","垫脚石","贫瘠之地"},ang={["class:Rogue"]="追踪匿名线人并审查凄凉之地和贫瘠之地之间隐秘的偏远地区补给点，对于那些从事匕首与情报交易的人来说是第二天性。",["faction:Horde"]="在贫瘠之地游荡的部落成员必须决定，关于卡利姆多土地上致命瘟疫运输的传闻是否对他们的领土和联盟构成了威胁。",["race:Undead"]="对于被遗忘者的旅行者来说，任何关于皇家药剂师协会及其枯萎病研究的零星提及都是紧迫的安全问题，或者说是来自内部的危险阴谋。"},sec={{t="荒野中的便条",b="这张信息随意地钉在偏远营地的一块木板上，在贫瘠之地严酷的环境中格外显眼。这里的营地常有雇佣兵、亡命之徒和流浪者出没，他们寻求远离十字路口或棘齿城窥探目光的临时住所。这张撕碎的便条立刻打破了荒野中平淡的闲谈，发出了一个充满阴谋和黑暗基调的邀请。"},{t="关于新的瘟疫的私语",b="便条作者报告说，两名特工一直在为新的瘟疫运送货物，并将发生在他们身上的事称为简单的药剂师事故。在卡利姆多各地运送挥发性瘟疫药剂的信使承担着巨大的风险，作者提供了一个位于贫瘠之地和凄凉之地之间的山中舒适地点，作为一个安全的谈话场所。"}},faq={{q="在 垫脚石 中找到的便条说了些什么？",a="该便条透露，运送与被遗忘者的新的瘟疫有关材料的信使遭遇了突然死亡。作者称这些为简单的药剂师事故，但提供了一个山中的会面点来安全地讨论此事。",al={"踏脚石 便条","便条的内容","踏脚石 任务文本"}},{q="便条告诉你去哪里？",a="作者邀请读者前往一个隐藏在贫瘠之地和凄凉之地之间的高山上的营地，这里远离常规巡逻路线和贸易通道。",al={"踏脚石 前往何处","山间舒适地点","踏脚石 地点"}},{q="信中提到的新的瘟疫是什么？",a="新的瘟疫是被遗忘者的皇家药剂师协会在幽暗城研发的致命混合药剂。它旨在根除天灾军团和活着的敌人，其在各大陆的测试和信使任务都充满了秘密和致命的危险。",al={"什么是 新的瘟疫","皇家药剂师瘟疫","药剂师运送"}},{q="是谁写了钉在木板上的便条？",a="该信息是匿名留在偏远营地的一块粗糙木板上的。作者没有署名，只提供了一个位于贫瘠之地和凄凉之地之间的山中舒适地点作为安全的谈话场所。",al={"谁写了便条","踏脚石 作者","谁在山中等待"}},{q="被遗忘者的信使为什么会出现在卡利姆多？",a="被遗忘者的药剂师经常从卡利姆多各地的严酷动植物身上采集奇异的毒液、孢子和试剂，并通过部落哨所和荒野路线协调运输。",al={"贫瘠之地的被遗忘者","为什么 新的瘟疫 出现在卡利姆多","贫瘠之地的药剂师"}},{q="为什么偏远营地会被用于此类便条？",a="贫瘠之地地域辽阔，在主要定居点之外的管理较为松散。中立的中转站、雇佣兵休息点和流浪者营地让旅行者、走私者和线人能够留下隐秘的消息，而不会引起部落或地区岗哨的注意。",al={"偏远营地背景知识","贫瘠之地的雇佣兵营地"}}},fp="15,232,19.313.0,26.258.1,56.201.0,35.94.0,47.247.0,39.156.0,51.169.0,51.247.0"}
P.entries["quest:792"] = {n="邪灵劣魔",s="“邪恶的魔仆”是祖雷萨在试炼谷向刚抵达的勇士下达的早期任务之一。在监视山谷内的试炼时，祖雷萨发现附近的一处洞穴中隐藏着一个阴险的火刃集会所。为了遏制他们突如其来的扩张，新兵们被派遣去猎杀那些潜入杜隆塔尔红土地上的恶魔仆从。",h="“邪恶的魔仆”是祖雷萨在试炼谷向刚抵达的勇士下达的早期任务之一。在监视山谷内的试炼时，祖雷萨发现附近的一处洞穴中隐藏着一个阴险的火刃集会所。为了遏制他们突如其来的扩张，新兵们被派遣去猎杀那些潜入杜隆塔尔红土地上的恶魔仆从...",kw={"火刃氏族","火刃集会所","杜隆塔尔","小鬼","大兽穴","试炼谷","邪恶的魔仆","祖雷萨"},ang={["class:Warlock"]="兽人和巨魔术士必须正视那些滥用恶魔契约进行破坏，而非将邪能用于部落生存的堕落施法者所带来的现实。",["faction:Horde"]="火刃氏族是杜隆塔尔目前面临的最迫切的内部威胁之一，他们试图在年轻的部落巩固主权之前从内部将其腐蚀。",["race:Orc"]="对于那些努力践行萨尔关于拒绝恶魔奴役理念的兽人来说，在他们神圣的训练场中遇到邪能污染，这是一个苦涩的提醒，表明暗影议会的遗产依然在发酵。"},sec={{t="山谷中的阴影",b="试炼谷旨在成为年轻的兽人和暗矛巨魔展示他们对萨尔领导的部落的忠诚、纪律和力量的试炼场。它原本是用来测试新兵对抗蝎虫和野猪这类本土掠食者的能力，而非对抗恶魔腐蚀。然而，在东北方的一处洞穴中，自称为火刃氏族的特工们在山谷监工的眼皮底下建立了一个秘密集会所。"},{t="扑杀小鬼",b="祖雷萨在指引大兽穴附近的新手时，在这些恶魔污染蔓延至整个峡谷之前就察觉到了异常。被称为“邪恶的魔仆”的次级恶魔生物开始从洞口蜂拥而出，向任何靠近的冒险者投掷火焰并进行威胁。在部落能够铲除隐藏在阴影中的幕后主使之前，年轻的新兵们肩负着斩杀这些低级仆从以保卫山谷的任务。"}},faq={{q="谁发布了“邪恶的魔仆”这个任务？",a="该任务由祖雷萨发布。她驻扎在试炼谷中心的大兽穴入口外。",al={"邪恶的魔仆任务发布者","谁发布邪恶的魔仆","在哪里接取邪恶的魔仆"}},{q="什么是邪恶的魔仆？",a="邪恶的魔仆是由火刃氏族术士召唤并束缚的小鬼状恶魔生物。它们作为次级爪牙和宠物，使用火焰骚扰闯入者。",al={"什么是邪恶的魔仆","邪恶的魔仆背景故事","邪恶的魔仆怪物类型"}},{q="火刃集会所位于何处？",a="该集会所坐落在试炼谷东北部尽头的一处洞穴内，穿过四处游荡的杂斑野猪和蝎虫工兵即可到达。",al={"火刃集会所位置","火刃集会所在哪","试炼谷洞穴"}},{q="为什么火刃氏族会在试炼谷中？",a="火刃氏族是一个致力于破坏萨尔新部落并传播恶魔腐蚀的秘密邪教。渗透进试炼谷让他们能够潜伏在暗处，并威胁到部落最新一代的战士。",al={"为什么火刃氏族在这里","火刃氏族动机","火刃氏族想要什么"}},{q="完成“邪恶的魔仆”之后会发生什么？",a="当洞穴外的魔仆被清除后，祖雷萨会指引你深入洞穴去面对邪教头目，并取回一枚火刃奖章。",al={"邪恶的魔仆后续任务","邪恶的魔仆之后是什么","火刃奖章任务"}},{q="我必须进入洞穴深处才能找到这些魔仆吗？",a="不需要。虽然它们栖息在洞穴内，但大量的邪恶的魔仆也在洞穴入口周围和洞口外的峡谷地面上游荡。",al={"邪恶的魔仆在洞穴里吗","在哪里击杀邪恶的魔仆","刷邪恶的魔仆"}}},fp="14,220,22.318.0,16.332.0,35.113.0,24.147.0,41.137.0,49.243.0,45.170.1,57.130.0"}
P.entries["quest:79229"] = {n="Highway Robbery",s="在凄凉之地，一处遭劫的营地留下了暴力袭击的线索。你要寻找能解释事发经过的人。",h="在凄凉之地，一处遭劫的营地留下了暴力袭击的线索。你要寻找能解释事发经过的人。",kw={"袭击","营地","半人马","凄凉之地","矮人","劫掠","人类","遭劫的营地","拾荒者"},sec={{t="遭劫的营地",b="凄凉之地的一处营地里，两名人类和一名矮人的遗骸散落在营地废墟间。他们骨骼上的痕迹表明，他们遭到了残暴袭击；被盗的物资则说明，袭击者不是野兽。他们身上的伤口也不像半人马武器造成的。有人请你在凄凉之地寻找熟悉这片土地、能够解释这些迹象的人。"}},faq={{q="营地里遇害的是谁？",a="遗骸表明，两名人类和一名矮人遭到了袭击。",al={"营地遇害者","营地受害者","人类和矮人"}},{q="营地里发生了什么？",a="营地遭到劫掠，遗骸上也有残暴袭击的迹象。",al={"这里发生了什么","遭劫的营地","营地袭击"}},{q="袭击是野兽所为吗？",a="被劫走的物资表明，袭击并非野兽所为。",al={"野兽袭击","是野兽干的吗","谁袭击了他们"}},{q="伤口是半人马造成的吗？",a="这些伤口不像是半人马武器造成的。",al={"半人马袭击","半人马武器","是半人马干的吗"}},{q="谁能解释这场袭击？",a="有人请你在凄凉之地寻找熟悉在这片土地上搜寻残骸的人。",al={"谁了解营地情况","询问拾荒者","该找谁"}}},fp="15,119,16.330.0,33.63.0,30.73.0,26.65.0,33.41.0,27.80.0"}
P.entries["quest:79235"] = {n="On the Lam",s="一则商队传闻指向了袭击凄凉之地人类与矮人营地后逃离的部落劫掠者。你将前往藏宝海湾寻找其中一人。",h="一则商队传闻指向了袭击凄凉之地人类与矮人营地后逃离的部落劫掠者。你将前往藏宝海湾寻找其中一人。",kw={"联盟元帅","藏宝海湾","商队","凄凉之地","部落","劫掠者","逃亡"},sec={{t="通往藏宝海湾的线索",b="一名商队联系人提到凄凉之地的人类与矮人营地遭到袭击，随后指引你前往藏宝海湾。受害者和这场暴行让商队怀疑是部落劫掠者所为。一名联盟元帅追捕过这伙匪徒，他们已离开凄凉之地。现在，你受命寻找其中一人。"}},faq={{q="是谁袭击了营地？",a="商队传闻将凄凉之地人类与矮人营地遭袭归咎于一伙部落劫掠者。",al={"是谁干的","袭击营地的人"}},{q="劫掠者去了哪里？",a="联盟元帅追捕后，这伙匪徒逃离了凄凉之地。据说可以去藏宝海湾寻找其中一人。",al={"他们逃往何处","劫掠者的位置"}},{q="为什么要去藏宝海湾寻找？",a="联系人建议前往藏宝海湾，因为品行可疑之人常常经过那里的港口，而劫掠者或许正在寻找船只。",al={"为何去藏宝海湾","去哪里找劫掠者"}},{q="我要找什么？",a="你要寻找一名来自凄凉之地的劫掠者。",al={"逃亡目标","寻找其中一人"}}},fp="10,150,20.286.0,23.97.0,27.116.0,22.130.0,22.55.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="在藏宝海湾，一名叫托卡尔的雇佣兵想要一杯酒，作为交换，她愿意透露近期人类和矮人哨所遇袭背后的真相。虽然有流言指责部落是幕后黑手，但托卡尔坚称她的团队是在受私人雇佣合约的约束下行事。",h="在藏宝海湾，一名叫托卡尔的雇佣兵想要一杯酒，作为交换，她愿意透露近期人类和矮人哨所遇袭背后的真相。虽然有流言指责部落是幕后黑手，但托卡尔坚称她的团队是在受私人雇佣合约的约束下行事。",kw={"藏宝海湾","樱桃酒的代价","樱桃酒","治安官","雇佣兵","劫掠","私人合同","托卡尔"},ang={["faction:Alliance"]="联盟成员会很有兴趣了解，袭击人类和矮人定居点的劫掠者并非受部落指使，而是受雇于一位私人资助者。",["faction:Horde"]="部落冒险者可以在托卡尔的供述中找到辩护的理由，这澄清了针对联盟营地的袭击是私人雇佣合约，而非部落的官方侵略行为。"},sec={{t="藏宝海湾的低语",b="在热闹的藏宝海湾港口，一个叫托卡尔的人正保持着低调，同时警惕着执法者的动向。近期发生的一系列激进劫掠事件重创了人类和矮人营地，助长了部落策划了这些袭击的传言。当那些显然不为调查此事的治安官工作的旅者接近她时，托卡尔立刻反驳了这些广为流传的说法，并提出只要请她喝杯酒，就愿意讲述另一版本的真相。"},{t="私人雇佣兵",b="托卡尔坦承参与了对人类和矮人哨所的劫掠，但坚决否认这些袭击是受部落指使的。相反，她声称她的团伙是受某个未透露身份的第三方私下雇佣。在披露究竟是谁资助了这次行动以及动机之前，她坚持要求对方先请她喝杯清爽的樱桃酒。"}},faq={{q="托卡尔是谁？",a="托卡尔是一名藏身于海盗避风港藏宝海湾的特工或雇佣兵。由于近期对人类和矮人定居点的劫掠受到审查，她向任何愿意为她买一杯樱桃酒的人提出，会讲述她为谁工作的完整故事。",al={"托卡尔是谁","托卡尔 藏宝海湾","樱桃酒任务提供者"}},{q="为什么托卡尔想要樱桃酒？",a="托卡尔在清醒时不愿意分享她过往合同的敏感细节。给她买一杯樱桃酒能让她卸下心防，从而说明是谁私下资助了针对联盟营地的劫掠。",al={"为什么要买樱桃酒","樱桃酒 托卡尔","托卡尔想要什么"}},{q="是部落负责劫掠人类和矮人营地的吗？",a="根据托卡尔的说法，针对人类和矮人营地的袭击并非部落下令。虽然传言称部落是始作俑者，但她坚称她的团队是在私人雇佣合约下工作的。",al={"谁雇佣了托卡尔","部落攻击了联盟营地吗","部落是幕后黑手吗"}},{q="为什么托卡尔担心治安官？",a="托卡尔害怕遭到正在调查劫掠人类和矮人定居点事件的治安官的追捕。她非常小心，确保在藏宝海湾接近她的人不是被派来将她绳之以法的代理人。",al={"治安官是谁","托卡尔在躲避治安官吗","治安官寻找托卡尔"}},{q="在哪里可以为托卡尔弄到樱桃酒？",a="樱桃酒是一种可以从藏宝海湾的旅店老板和酒保处买到的饮料。给托卡尔送上一杯这种酒，就能满足她的要求，并促使她说出她的故事。",al={"哪里可以得到樱桃酒","樱桃酒位置","藏宝海湾的酒"}},{q="为什么托卡尔待在藏宝海湾？",a="藏宝海湾是一个中立的自由港，不受联盟和部落的严格管辖。对于一名在劫掠了人类和矮人定居点后想要避风头的雇佣兵来说，这里是一个理想的藏身处。",al={"为什么托卡尔在藏宝海湾","托卡尔的藏身处"}}},fp="25,167,25.301.0,19.269.1,13.166.0,34.135.0,68.153.0,37.173.0,39.133.0,34.175.0"}
P.entries["quest:793"] = {n="破碎的联盟",s="高恩派遣你去荒芜之地最东端的莱瑟罗峡谷，黑龙BossBlacklash和赫玛图斯正被大地印章束缚在那里。这是“破碎的联盟”任务之后的后续。",h="高恩派遣你去荒芜之地最东端的莱瑟罗峡谷，黑龙BossBlacklash和赫玛图斯正被大地印章束缚在那里。这是“破碎的联盟”任务之后的后续。",kw={"黑龙军团","布莱克拉什","黑石兽人","高恩","赫玛图斯","莱瑟罗峡谷","大地印章"},sec={{t="三块符文石",b="三块符文石封印着大地印章。它们分别位于莱瑟罗峡谷的几根石柱中：钻石、猫眼石和紫水晶。高恩交给你的大地印章可以抽出这些石头并解开封印。峡谷里栖息着无数龙类，布莱克拉什和赫玛图斯非常强大。高恩希望杀掉它们，并带回它们的束缚物。"},{t="高恩的意图",b="高恩称黑龙军团依然与黑石氏族的叛徒兽人结盟，无论龙类还是兽人都必须受到约束或被铲除。一旦布莱克拉什和赫玛图斯伏诛，部落就可以将目光投向西边的黑石塔了。"}},faq={{q="谁发布了这个任务？",a="由高恩发布，作为“破碎的联盟”之后的下一步。",al={"破碎的联盟任务发布者","高恩位置","谁发布破碎的联盟"}},{q="莱瑟罗峡谷在哪里？",a="前往荒芜之地的最东端。峡谷中栖息着无数龙类。",al={"莱瑟罗峡谷位置","如何前往莱瑟罗峡谷","莱瑟罗峡谷在哪里"}},{q="如何释放布莱克拉什和赫玛图斯？",a="大地印章可以从三根石柱中分别抽出一块符文石。将这些石头嵌入大地印章中，就能解开两头龙的束缚。",al={"如何召唤布莱克拉什","大地印章","钻石猫眼石紫水晶石柱"}},{q="必须带回给高恩什么东西？",a="在两头龙死亡后，带回布莱克拉什的束缚物、赫玛图斯的锁链以及大地印章。",al={"破碎的联盟任务交付物品","高恩想要回什么","布莱克拉什的束缚物"}}},fp="16,137,16.354.0,21.228.1,21.86.0,32.99.0,38.140.0,34.113.0"}
P.entries["quest:79360"] = {n="Elemental Aid",s="为了报答元素的援助，你受命前往剃刀沼泽。野猪人正在扭曲元素之力，他们的图谋威胁着这片土地。",h="为了报答元素的援助，你受命前往剃刀沼泽。野猪人正在扭曲元素之力，他们的图谋威胁着这片土地。",kw={"卡尔加·刺肋","elemental aid","元素","野猪人","野猪人计划","剃刀沼泽"},ang={["class:Shaman"]="作为一名萨满祭司，你已掌握元素之力。如今有人请你报答元素的援助，保护它们免受野猪人阴谋的侵害。"},sec={{t="向元素发出的召唤",b="元素曾助你一臂之力，如今有人请你回报这份恩情。野猪人正将元素之力据为己用，似乎还在不断扩大势力范围。你受命前往剃刀沼泽，阻止他们的阴谋，守护这片土地。"}},faq={{q="我为什么要去剃刀沼泽？",a="野猪人正将元素之力据为己用，似乎还在扩大势力范围。有人请你阻止他们的阴谋，守护这片土地。",al={"剃刀沼泽原因","为什么去剃刀沼泽","元素援助原因"}},{q="卡尔加·刺肋是谁？",a="卡尔加·刺肋是你受命前往剃刀沼泽击败的野猪人。",al={"卡尔加是谁","卡尔加·刺肋","刺肋"}},{q="我要收集什么情报？",a="有人请你收集野猪人的计划情报。",al={"野猪人计划","什么情报","计划情报"}},{q="我为什么要帮助元素？",a="你曾得到元素的援助，如今有人请你回报这份恩情，保护这片土地免受野猪人阴谋的侵害。",al={"元素援助为何","帮助元素","报答元素"}}},fp="13,154,22.256.0,35.154.0,26.76.0,39.61.0,31.128.0"}
P.entries["quest:79361"] = {n="Storm, Earth, and Fire",s="普拉特·白云请你阻止 Quilboar 施展邪恶萨满法术，淹没千针石林。一本供你修习的典籍或许能驱散即将到来的风暴。",h="普拉特·白云请你阻止 Quilboar 施展邪恶萨满法术，淹没千针石林。一本供你修习的典籍或许能驱散即将到来的风暴。",kw={"普拉特·白云","quilboar","storm, earth, and fire","千针石林","典籍","邪恶的萨满法术","被扭曲的图腾"},sec={{t="风暴将至",b="普拉特·白云原本打算继续指导你修行，但千针石林的威胁刻不容缓。你已经见识过 Quilboar 不容小觑。普拉特交给你一本供研习的典籍，并请你收集被扭曲的火焰、大地、空气和水之图腾。这本典籍或许藏有驱散他们即将引发的风暴之法。"}},faq={{q="谁在寻求帮助？",a="普拉特·白云请你在千针石林收集被扭曲的图腾。",al={"普拉特·白云是谁","普拉特·白云"}},{q="Quilboar 想做什么？",a="普拉特说，Quilboar 想通过邪恶的萨满法术淹没千针石林。",al={"quilboar 的计划","图腾的用途","quilboar 引发的风暴"}},{q="普拉特给了我什么？",a="普拉特给了你一本原本供研习的典籍，或许能驱散即将到来的风暴。",al={"典籍","这本书是什么","研习典籍"}},{q="普拉特需要哪些图腾？",a="普拉特请你收集被扭曲的火焰、大地、空气和水之图腾。",al={"图腾种类","火焰、大地、空气、水","需要哪些图腾"}}},fp="22,175,18.334.0,23.70.0,35.81.0,24.87.0,29.68.0"}
P.entries["quest:79362"] = {n="Grant's Shield",s="Sirra Von’Indie正在寻找Grant Valor留在乌鸦岭墓地的钉锤，他的灵魂仍在那里与亡灵战斗。这些武器或许能帮助她进一步了解这位骄傲的英雄。",h="Sirra Von’Indie正在寻找Grant Valor留在乌鸦岭墓地的钉锤，他的灵魂仍在那里与亡灵战斗。这些武器或许能帮助她进一步了解这位骄傲的英雄。",kw={"夜色镇","grant valor","grant的钉锤","grant的盾牌","乌鸦岭墓地","sirra von'indie","亡灵","the valor family"},sec={{t="部落英雄的灵魂",b="夜色镇的Sirra Von’Indie请你在乌鸦岭墓地的骷髅中寻找Grant Valor的钉锤。Grant的幽灵留下了他的盾牌，而他的灵魂仍在那里与亡灵战斗。这把钉锤或许能提供线索，找出打伤他的生物，Sirra想研究这些武器。"},{t="武器",b="在夜色镇，Sirra Von’Indie感叹，一个普通的生物竟然让Grant Valor落得如此下场。她说，一次失足就可能让人终身残疾。她相信，武器能透露许多主人的往事，因此花时间仔细研究它们。"}},faq={{q="Grant Valor是谁？",a="Grant Valor是The Valor Family的父亲，也是乌鸦岭的英雄。他的幽灵仍在与亡灵战斗。",al={"grant valor","grant是谁","grant的往事"}},{q="Grant的钉锤在哪里？",a="Grant的钉锤在乌鸦岭墓地的一具骷髅身上。",al={"grant的钉锤","寻找grant的钉锤","钉锤位置"}},{q="我为什么要寻找Grant的钉锤？",a="Sirra Von’Indie请你找到钉锤，以便从Grant的武器中了解更多。",al={"为什么寻找钉锤","grant的盾牌任务","sirra想要什么"}},{q="我该把钉锤带到哪里？",a="把Grant的钉锤交还给夜色镇的Sirra Von’Indie。",al={"归还钉锤","sirra的位置","von'indie在哪里"}},{q="Grant遭遇了什么？",a="Grant在乌鸦岭墓地被一个生物打伤。他的灵魂仍在那里与亡灵战斗。",al={"grant受伤","grant是怎么受伤的","grant valor的盾牌"}}},fp="14,169,13.298.0,11.234.1,20.110.0,22.65.0,34.89.0,25.56.0,23.98.0"}
P.entries["quest:79363"] = {n="西尔维娅的剑",s="Silvia Valor的灵魂留下的剑，指引你前去寻找乌鸦岭附近的迪菲亚。这把剑的主人曾是一名守卫，保护着平民和他们的家园。",h="Silvia Valor的灵魂留下的剑，指引你前去寻找乌鸦岭附近的迪菲亚。这把剑的主人曾是一名守卫，保护着平民和他们的家园。",kw={"腐草农场","夜色镇","迪菲亚","守卫","乌鸦岭","silvia valor","silvia的剑","希拉·沃宁迪","未了的心愿"},sec={{t="守卫之剑",b="乌鸦岭的守卫Silvia Valor的灵魂留下了她的剑。Silvia一生都在保护平民和他们的家园。她的灵魂仍会造访各处农庄，而迪菲亚已在乌鸦岭以南的腐草农场盘踞下来。赶走他们或许就是她未了的心愿，夜色镇的希拉·沃宁迪正等着听取此事的结果。"},{t="研究佩剑",b="在腐草农场，迪菲亚是查明Silvia Valor未了心愿的第一条线索。当你回到夜色镇的希拉·沃宁迪身边时，她承认Silvia是一名出色的战士和守护者，只是对于谁值得保护，她的看法颇为狭隘。Sirra无法判断Silvia想借这把剑达成什么心愿，于是继续研究这把剑。"}},faq={{q="Silvia Valor是谁？",a="Silvia Valor曾是乌鸦岭的一名守卫，一生都在保护平民和他们的家园。",al={"silvia valor的身世","silvia是谁","乌鸦岭守卫silvia"}},{q="Silvia的灵魂为什么在各处农庄徘徊？",a="Silvia的灵魂仍会造访各处农庄，她未了的心愿或许与腐草农场的迪菲亚有关。",al={"silvia的幽灵为何徘徊","她为何在农场徘徊","silvia未了的心愿"}},{q="谁在询问Silvia的剑？",a="夜色镇的希拉·沃宁迪接着讲述这把剑的故事。解决腐草农场的迪菲亚之后，你回到她那里，进一步了解Silvia Valor的往事。",al={"谁给了silvia的剑","希拉·沃宁迪的剑","夜色镇给剑的人"}},{q="迪菲亚盘踞在哪里？",a="迪菲亚已经盘踞在乌鸦岭以南的腐草农场。",al={"迪菲亚腐草农场","迪菲亚在哪里","乌鸦岭迪菲亚"}},{q="Sirra如何评价Silvia？",a="Sirra称Silvia是一名出色的战士和守护者，但也说她对于谁值得保护的看法颇为狭隘。",al={"sirra对silvia的评价","战士silvia","silvia是怎样的守卫"}},{q="Sirra如何处理这把剑？",a="Sirra继续研究Silvia Valor的剑。",al={"这把剑的后续","sirra研究佩剑","silvia的剑后续"}}},fp="14,154,15.360.0,17.332.1,21.95.0,43.109.0,30.150.0,41.73.0,32.116.0,34.43.0"}
P.entries["quest:79364"] = {n="Eyes on the Sky",s="一张纸条警告，钢鬃正在千针石林举行一场隐秘仪式。你受托查明风暴与潮水上涨带来的威胁。",h="一张纸条警告，钢鬃正在千针石林举行一场隐秘仪式。你受托查明风暴与潮水上涨带来的威胁。",kw={"元素巫术","仰望天空","hirzek","普拉特·白云","quilboar","钢鬃","上涨的潮水","仪式","风暴","千针石林"},sec={{t="迫近的威胁",b="你找到的纸条指向千针石林的钢鬃，那里正在举行一场隐秘仪式。狂暴的风暴和不断上涨的潮水令人担心峡谷可能被淹没。Quilboar或许正运用从萨满Hirzek那里学来的元素之力。回到盟友身边，与普拉特·白云交谈。"}},faq={{q="纸条上写了什么？",a="纸条上说，钢鬃已钻入千针石林举行一场隐秘仪式，那里风暴狂暴，潮水不断上涨。",al={"千针石林的纸条","纸条内容","钢鬃纸条"}},{q="Hirzek是谁？",a="Hirzek是一名萨满，他教会Quilboar扭曲元素的巫术。",al={"hirzek","hirzek萨满","hirzek是谁"}},{q="Quilboar构成什么威胁？",a="令人担忧的是，Quilboar可能会运用元素之力淹没峡谷。",al={"quilboar的威胁","钢鬃仪式","quilboar在做什么"}},{q="我应该和谁交谈？",a="你受托前往千针石林，与普拉特·白云交谈。",al={"前往何处","寻找谁","普拉特·白云"}}},fp="15,160,18.309.0,23.116.0,14.76.0,33.85.0,24.64.0"}
P.entries["quest:79366"] = {n="Heed My Call",s="你用 Twisted Totems 对付钢鬃的仪式，随后向劳恩·峭壁行者报告。受腐化的元素生物可能会让这片土地无法恢复洁净。",h="你用 Twisted Totems 对付钢鬃的仪式，随后向劳恩·峭壁行者报告。受腐化的元素生物可能会让这片土地无法恢复洁净。",kw={"受腐化的元素生物","大地之环","听从我的召唤","quilboar","劳恩·峭壁行者","钢鬃","仪式","steam pools","twisted totems"},sec={{t="在 Steam Pools",b="手持 Twisted Totems，你已准备好打断钢鬃的仪式。有人告诉你，先去西边的 Steam Pools，那里各种元素都很充沛。quilboar 会抵抗你的行动。用图腾对付仪式及其受腐化的元素生物。"},{t="劳恩的感谢",b="劳恩·峭壁行者问你是否带来了风暴的消息。你回来时，他得知隆隆作响的大地已经归于沉寂，并感谢你为大地之环争得了荣誉。"}},faq={{q="劳恩·峭壁行者要我做什么？",a="劳恩·峭壁行者要你用 Twisted Totems 终结 quilboar 的仪式，然后回来向他报告成功的消息。",al={"劳恩·峭壁行者的任务","劳恩要什么"}},{q="我该从哪里开始？",a="从西边的 Steam Pools 开始，那里各种元素都很充沛。",al={"从哪里开始","steam pools"}},{q="Twisted Totems 有什么用？",a="Twisted Totems 用来召唤 quilboar 所依仗的受腐化元素生物。",al={"twisted totems","图腾的用途"}},{q="谁在举行仪式？",a="钢鬃 quilboar 正在举行仪式，召唤受腐化的元素生物。",al={"谁在举行仪式","钢鬃仪式"}},{q="quilboar 为什么会抵抗？",a="有人警告你，quilboar 不会坐视你打断他们的计划。",al={"quilboar 抵抗","为什么攻击我"}}},fp="12,155,18.271.0,12.170.1,40.122.0,21.70.0,32.87.0,29.84.0,30.83.0"}
P.entries["quest:794"] = {n="火刃奖章",s="这项任务由术士祖雷萨指派，要求年轻的部落新兵深入试炼谷的火刃集会所洞穴。在那里，玩家必须直面一名潜藏的邪教徒，并找回一件名为火刃奖章的黑暗魔法神器。这项任务揭示了恶魔的腐化正在部落的眼皮底下生根发芽。",h="这项任务由术士祖雷萨指派，要求年轻的部落新兵深入试炼谷的火刃集会所洞穴。在那里，玩家必须直面一名潜藏的邪教徒，并找回一件名为火刃奖章的黑暗魔法神器。这项任务揭示了恶魔的腐化正在部落的眼皮底下生根发芽。",kw={"火刃氏族","集会所","杜隆塔尔","奖章","大兽穴","试炼谷","术士","亚罗格·刺影","祖雷萨"},ang={["class:Shaman"]="找回受污染的圣物有助于祖雷萨揭露那些玷污杜隆塔尔大地的恶魔腐化。",["class:Warlock"]="直面亚罗格是一个严酷的提醒，警示着在萨尔统治下所制定的受认可、经过仔细隐藏的契约之外，进行堕落的恶魔崇拜所带来的危险。",["faction:Horde"]="这项任务代表了年轻新兵的最终试炼，标志着他们已准备好前往杜隆塔尔更广阔的荒野，以保卫这个年轻的国家。",["race:Orc"]="追捕亚罗格·刺影凸显了新部落在训练场内清除旧时代残留恶魔污秽的内部斗争。"},sec={{t="谷中的隐藏威胁",b="当年轻的兽人和巨魔在试炼谷进行基础的战斗与生存试炼时，一股阴险的威胁正潜伏在阴影中。通过占卜，术士祖雷萨感觉到那些盘踞在北部峭壁上的邪恶魔仆只不过是更黑暗势力的先遣队。在附近的一个洞穴深处，火刃氏族建立了一个隐秘的集会所，他们在那练习黑暗魔法，并窝藏着危险的恶魔力量圣物。"},{t="直面亚罗格·刺影",b="这枚奖章正掌握在亚罗格·刺影手中，这是一名充当火刃氏族代理人的兽人术士。亚罗格躲藏在地下大兽穴深处的一处高台上，指挥着邪能野兽并施展黑暗魔法，避开了谷中监视者的目光。击败他并夺取奖章，可以在该邪教的仪式进一步蔓延到杜隆塔尔腹地之前，扰乱其当地的领导层。"},{t="挥之不去的阴影",b="获得这枚护身符证实了祖雷萨最担心的事。虽然试炼谷中的集会所已被拆除，但奖章证明了火刃氏族是有组织、有目的地在行动。该邪教的触角已远超试炼场，预示着羽翼未丰的部落将在整个杜隆塔尔面临更广泛的恶魔阴谋。"}},faq={{q="我在哪里可以找到火刃集会所？",a="火刃集会所位于试炼谷大兽穴西北方峭壁内的一个洞穴中，周围环绕着类似小鬼的邪恶魔仆。",al={"集会所洞穴位置","洞穴在哪里","试炼谷火刃氏族洞穴"}},{q="谁持有火刃奖章？",a="奖章由亚罗格·刺影持有，这名堕落的兽人邪教徒位于洞穴深处，处于浅水池后方的一处凸起的岩石平台上。",al={"谁掉落奖章","亚罗格·刺影","奖章持有者"}},{q="火刃氏族是什么？",a="火刃氏族是一个背叛的邪教组织，由受到邪能腐蚀的兽人和术士组成，他们沉迷于恶魔力量，并从隐藏的巢穴和营地中积极策划对抗萨尔的新部落。",al={"火刃氏族是什么","火刃邪教"}},{q="为什么这枚奖章对祖雷萨如此重要？",a="祖雷萨通过她的占卜发现了这枚奖章。它是一件能够助长邪教黑暗仪式的力量物品，并提供了无可辩驳的证据，证明恶魔特工正在渗透试炼谷。",al={"为什么祖雷萨想要它","什么是奖章","祖雷萨奖章"}},{q="击败 亚罗格 能彻底铲除杜隆塔尔的邪教吗？",a="不能。虽然 亚罗格 的死亡净化了试炼谷的洞穴，但祖雷萨警告说，这个集会所只是一个小组织，火刃氏族在整个杜隆塔尔还有更大的野心。",al={"火刃氏族被消灭了吗","他们消失了吗","火刃奖章之后"}},{q="上交奖章后会发生什么？",a="在击杀 亚罗格 并找回圣物证明了你的价值后，你被认为已经准备好离开试炼谷，并被指引前往杜隆塔尔南海岸的森金村报到。",al={"下一个任务","接下来是什么","完成此任务后"}}},fp="23,237,29.405.0,29.348.1,20.290.1,40.143.0,44.124.0,26.183.0,54.170.0,53.177.0,44.191.0"}
P.entries["quest:79442"] = {n="The Tempest's Weapons",s="奥特兰克山脉的一位老萨满或许知道如何使用 Eye of the Tempest。你把这件神器带给他，好让他借助其中的风暴魔法进行打造。",h="奥特兰克山脉的一位老萨满或许知道如何使用 Eye of the Tempest。你把这件神器带给他，好让他借助其中的风暴魔法进行打造。",kw={"奥特兰克山脉","巴斯拉","捕风者巴斯拉","eye of the tempest","萨满","风暴元素魔法","the tempest's weapons"},ang={["class:Shaman"]="身为萨满，你把一件蕴含强大风暴元素魔法的神器带给巴斯拉。他是一位精通这种魔法的老萨满。"},sec={{t="一位老萨满",b="与元素生物交战后，你把 Eye of the Tempest 带给奥特兰克山脉的捕风者巴斯拉。他对风暴元素魔法颇有见识，也看出了这件神器蕴藏的力量。巴斯拉说，他已经很久没接触过类似的东西了，并叮嘱你要好好保管。"}},faq={{q="巴斯拉是谁？",a="捕风者巴斯拉是奥特兰克山脉的一位老萨满，对风暴元素魔法颇有见识。",al={"捕风者巴斯拉","老萨满","巴斯拉是谁"}},{q="Eye of the Tempest 是什么？",a="Eye of the Tempest 是一件与风暴元素魔法有关的强大神器。",al={"tempest之眼","之眼神器","这只眼睛是什么"}},{q="为什么要把 Eye of the Tempest 带给巴斯拉？",a="巴斯拉了解风暴元素魔法，或许能用 Eye of the Tempest 打造出某种物品。",al={"为何找巴斯拉","tempest之眼武器任务","该把 eye of the tempest 带到哪里"}},{q="巴斯拉对这件神器怎么说？",a="巴斯拉称 Eye of the Tempest 威力强大，还说自己已经很久没用类似的东西打造物品了。",al={"巴斯拉的反应","他说了什么","eye of the tempest 完成情况"}}},fp="21,147,13.305.0,16.105.0,31.84.0,30.113.0,42.112.0"}
P.entries["quest:79624"] = {n="Anyone Can Cook",s="一份难以辨认的食谱似乎描述了一道肉菜，你猜那是食人魔文字。找一位能读懂它的食人魔。",h="一份难以辨认的食谱似乎描述了一道肉菜，你猜那是食人魔文字。找一位能读懂它的食人魔。",kw={"人人都能做菜","难以辨认的食谱","肉菜","食人魔","食谱","skonk","翻译"},ang={["profession:Cooking"]="作为一名厨师，你自然会好奇这份难以辨认的食谱描述了什么肉菜。"},sec={{t="奇怪的食谱",b="这份食谱写在一种你看不懂的语言里，内容似乎是一道肉菜。考虑到它的来历和描述的内容，你猜最有可能是食人魔语。你希望能找到一位食人魔帮忙翻译。"}},faq={{q="这份食谱写的是什么？",a="看起来像是某种肉菜的做法。",al={"食谱用途","什么菜","肉菜食谱"}},{q="这份食谱是用什么语言写的？",a="你看不懂这种语言。你猜最有可能是食人魔语。",al={"食谱语言","什么文字","看不懂食谱"}},{q="谁能读懂这份食谱？",a="你正在寻找一位能读懂它的食人魔。",al={"翻译食谱","谁能读懂","食人魔读者"}},{q="Skonk是谁？",a="Skonk是一名食人魔，正在打听这份食谱。",al={"skonk","skonk是谁","食人魔skonk"}}},fp="15,112,16.213.0,23.44.0,39.60.0,24.44.0,13.49.0"}
P.entries["quest:79677"] = {n="A Quick Grocery Run",s="Skonk请你在阿拉希高地收集烹制一道菜所需的食材。其他食人魔嘲笑他的体型和战斗能力后，他学会了烹饪。",h="Skonk请你在阿拉希高地收集烹制一道菜所需的食材。其他食人魔嘲笑他的体型和战斗能力后，他学会了烹饪。",kw={"阿拉希高地","烹饪","菜肴","食材","食人魔","skonk","嘲笑"},ang={["profession:Cooking"]="作为一名厨师，你可以帮Skonk收集烹制一道他会做的菜所需的食材。"},sec={{t="Skonk的食材",b="Skonk是阿拉希高地的一名食人魔，需要烹制一道他会做的菜所需的食材。其他食人魔嘲笑他个头小，还说他软弱，于是他转而学习烹饪。你收集食材后把它们交给他。"}},faq={{q="Skonk是谁？",a="Skonk是一名食人魔，其他食人魔嘲笑他的体型和战斗能力后，他学会了烹饪。",al={"skonk","谁是skonk"}},{q="Skonk为什么烹饪？",a="其他食人魔嘲笑Skonk个头小，还说他软弱，于是他学会了烹饪，而不是战斗。",al={"为何烹饪","skonk烹饪"}},{q="Skonk需要什么？",a="Skonk需要烹制一道他会做的菜所需的食材。",al={"食材","需要什么食材"}},{q="我该把食材交给谁？",a="把食材交给阿拉希高地的Skonk。",al={"skonk在哪","交付食材"}}},fp="19,143,19.214.0,13.92.0,20.107.0,21.47.0,33.51.0"}
P.entries["quest:79948"] = {n="Defensive Magics 101",s="图书馆正在为馆藏搜寻魔法典籍。你可以带来可能有益于馆藏的著作，帮助拓展图书馆的知识。",h="图书馆正在为馆藏搜寻魔法典籍。你可以带来可能有益于馆藏的著作，帮助拓展图书馆的知识。",kw={"馆藏","防护魔法","知识","图书馆","魔法典籍"},sec={{t="不断丰富的馆藏",b="图书馆的馆藏可以在你的帮助下不断丰富。把可能适合入藏的魔法典籍交给馆员，图书馆的知识便会随之扩展。"}},faq={{q="图书馆需要什么？",a="图书馆正在征集可能适合入藏的魔法典籍。",al={"图书馆需要什么","带什么来","魔法书籍"}},{q="这项请求来自哪里？",a="这项请求来自一位图书管理员。联盟方面是暴风城的 Garion Wendell，部落方面则是幽暗城的 Owen Thadd。",al={"是谁提出的","图书馆的请求","哪座图书馆"}},{q="为什么要带来魔法典籍？",a="带到图书馆的魔法典籍能拓展图书馆的知识。",al={"为何收集魔法典籍","有什么帮助","图书馆馆藏"}}},fp="20,137,20.153.0,27.66.0,27.135.0,24.58.0"}
P.entries["quest:79950"] = {n="Demons and You",s="图书管理员请你为馆藏增添一部魔法典籍。你的努力让图书馆的知识更加丰富。",h="图书管理员请你为馆藏增添一部魔法典籍。你的努力让图书馆的知识更加丰富。",kw={"馆藏","恶魔与你","知识","图书馆","魔法典籍"},sec={{t="图书馆藏书",b="你带来的任何魔法著作都可上架收藏。藏书因你的努力而日渐丰富，管理员也欢迎你继续带来有益于图书馆的著作。"}},faq={{q="图书管理员想要什么？",a="管理员请你带来一部魔法典籍，加入图书馆的馆藏。",al={"该带什么","图书馆的请求","恶魔与你任务"}},{q="馆藏在哪里？",a="管理员是一位图书管理员。联盟方面是暴风城的 Garion Wendell，部落方面则是幽暗城的 Owen Thadd。",al={"这里在哪里","图书馆位置","哪座图书馆"}},{q="为什么要把魔法典籍带到图书馆？",a="管理员说，你的努力能丰富图书馆的知识。",al={"为什么捐赠书籍","这是做什么用的","图书馆的用途"}}},fp="14,118,20.166.0,34.81.0,24.126.0,39.62.0"}
P.entries["quest:79952"] = {n="RwlRwlRwlRwl!",s="图书管理员欢迎您将魔法著作捐赠给图书馆馆藏。您的捐赠有助于增长馆藏知识。",h="图书管理员欢迎您将魔法著作捐赠给图书馆馆藏。您的捐赠有助于增长馆藏知识。",kw={"馆藏","知识","图书馆","魔法典籍","rwl"},sec={{t="日渐丰富的馆藏",b="每一份新增藏书都能拓展馆藏知识，管理员也为此向您致谢。欢迎继续捐赠可能对馆藏有益的著作。"}},faq={{q="图书馆管理员想要什么？",a="管理员欢迎捐献有益于图书馆馆藏的魔法典籍。",al={"图书馆书籍","魔法典籍","需要带什么"}},{q="这批馆藏在哪里？",a="此处未提及城市。像这样的书可以交给暴风城的 Garion Wendell，或幽暗城的 Owen Thadd。",al={"图书馆位置","铁炉堡图书馆","图书馆在哪里"}},{q="为什么要带来魔法典籍？",a="你的捐献能让图书馆的知识更加丰富。",al={"为什么要捐书","帮助图书馆","有何意义"}}},fp="13,113,20.138.0,34.76.0,25.99.0,24.53.0"}
P.entries["quest:79974"] = {n="Wet Job",s="Wet Job是一个任务，其核心在于寻找一个遗留在高耸山腰上的应急补给箱。为了应对突发撤离的情况，这个补给箱被隐藏在风景秀丽的悬崖边，其中存放的物资通过精巧的矮人工艺得到了妥善保护。",h="Wet Job是一个任务，其核心在于寻找一个遗留在高耸山腰上的应急补给箱。为了应对突发撤离的情况，这个补给箱被隐藏在风景秀丽的悬崖边，其中存放的物资通过精巧的矮人工艺得到了妥善保护。",kw={"矮人工程","鹰巢","邮差包","山腰","羊皮纸","储备物资","补给品","脏活"},ang={["class:Rogue"]="对于生活在阴影中的人来说，将隐藏的应急补给箱藏好以备匆忙撤离，是他们的第二天性。",["profession:Engineering"]="该补给箱展示了矮人工程的独创性，作为隐藏在崎岖地形中的可靠应急库存。",["race:Dwarf"]="在找回补给箱的过程中，矮人工艺受到了赞誉，突显了他们山地手工制品持久的品质。"},sec={{t="应急补给箱",b="那些在危险条件下行动的人深知，不准备备用计划绝不能贸然行动。Wet Job要求定位一个隐藏在崎岖高地上的储备物资。作为紧急情况下的备用措施，万一需要快速撤离，这个补给箱便可以在计划出错时随时取用。"},{t="鹰巢",b="线索直接指向一处风景优美的山地制高点，诗意地描述为从时间的瀑布中雕刻而成。在这面岩壁的高处坐落着所谓的“鹰巢”。在那里，半埋在地下的一个风化邮差包，利用可靠的矮人工艺保护着里面的物资和羊皮纸，使其免受自然环境的侵蚀。"}},faq={{q="湿活是什么任务？",a="湿活是一个涉及找回隐藏在地貌中的应急储备物资的任务。准备这个补给箱的人确保了在需要紧急撤离时，物资能够得到保障。",al={"什么是水下工作","水下工作任务","水下工作是什么类型的任务"}},{q="是谁留下了这个储备物资？",a="这个物资是由一个为防万一需要匆忙撤离而准备应急储备的人所留下的。找回的邮差包中藏有羊皮纸和通过卓越矮人工程制造的物资。",al={"是谁留下了储备物资","这些物资是谁的","谁隐藏了应急补给"}},{q="补给箱藏在哪里？",a="线索指向一处风景如画的山腰，那里被描述为从时间的瀑布中雕刻而成，具体指引寻找者前往岩壁高处的一处鹰巢，在那里邮差包从泥土中显露出来。",al={"补给箱在哪里","水下工作位置","鹰巢位置"}},{q="邮差包里有什么？",a="打开埋藏的邮差包，会发现里面有必需的补给品和一张隐藏的羊皮纸，它们受到坚固耐用的矮人工艺的保护。",al={"补给箱里有什么","水下工作物品","你会发现什么"}},{q="为什么这个任务被称为湿活？",a="虽然这个标题通常暗示隐秘或混乱的现场行动，但在这里它直接联系到山地的地标，周围是迷雾、时间的瀑布以及隐藏包裹的潮湿泥土。",al={"为什么叫水下工作","水下工作名字含义"}},{q="矮人工程是如何参与的？",a="在发现并打开补给箱后，该补给箱的结构和可靠性被赞誉为矮人工程的奇迹，足以承受户外埋藏环境。",al={"与矮人工程的联系","这是矮人制造的吗"}}},fp="7,154,18.194.0,16.273.0,32.80.0,27.162.0,26.163.0,35.84.0,31.103.0,36.101.0"}
P.entries["quest:79975"] = {n="Eagle's Fist",s="Eagle's Fist围绕着一封在迷雾缭绕的高海拔制高点工具箱中发现的神秘信件展开。信中揭示了一名孤独的哨兵，出于对旧王国以及“鹰与拳”的忠诚，守护着一座风化的路障。尽管篝火刚添过柴，但守望者已匆忙离开。",h="Eagle's Fist围绕着一封在迷雾缭绕的高海拔制高点工具箱中发现的神秘信件展开。信中揭示了一名孤独的哨兵，出于对旧王国以及“鹰与拳”的忠诚，守护着一座风化的路障。尽管篝火刚添过柴，但守望者已匆忙离开。",kw={"路障","篝火","鹰之拳","折叠的信","瞭望点","旧王国","降落伞滑翔机","工具箱"},ang={["profession:Engineering"]="这名瞭望者的笔记强调了此地是部署降落伞滑翔机的理想出发点，吸引了那些青睐空中侦察和机械飞行的工程学爱好者的注意。"},sec={{t="一处隐蔽的栖身之所",b="在一处风景优美的制高点，一个不起眼的工具箱里藏着一封折叠整齐的信。作者反思了这个高处瞭望台居高临下的位置，感叹这里既可以掌控全局，也能发射降落伞滑翔机飞越地貌。在这片被水雾浸湿的孤独哨位上，可以将历史悠久的土地尽收眼底。"},{t="对旧王国的忠诚",b="写信人声称对“鹰与拳”怀有深厚而持久的忠诚，并指出要妥善效忠于这一事业，需要保持适当的距离。虽然承认当地的路障已经年久失修——正如它曾经抵御危险的旧王国一样——但这位坚定的守望者发誓绝不会真正放弃这个岗位。"},{t="匆忙离去",b="不论是谁负责这个瞭望点，他们离开时都十分匆忙。发现该岗位的游客会看到一堆刚添过新柴的篝火，但哨兵却消失得无影无踪，只留下了工具、燃烧的余烬和那封神秘的信。"}},faq={{q="什么是鹰拳？",a="鹰拳是一次围绕着一个隐藏工具箱的遭遇，箱内装有一封折叠整齐的信，位于俯瞰一座旧路障、风景优美且雾气缭绕的制高点。它标志着一位最近逃离的神秘斥候的营地。",al={"什么是鹰之拳","鹰之拳任务","这是什么任务"}},{q="工具箱里的信是谁写的？",a="作者是一位身份不明的斥候或哨兵，忠于旧王国以及一个被称为“鹰与拳”的实体或联盟。他们在这座破败的路障处进行着孤独的守望。",al={"谁写的便条","谁留下的信","工具箱信件作者"}},{q="“鹰与拳”指的是什么？",a="信中提到了对“鹰与拳”的忠诚，并指出只有保持距离才能更好地效忠。虽然确切的组织情况仍是个谜，但它与保卫旧王国的残余势力有关。",al={"什么是鹰与拳","鹰与拳的含义","鹰与拳是谁"}},{q="营地为何被废弃了？",a="这名斥候匆匆离开，留下了一堆刚添过新柴的篝火。他们的去向仍然未知，不过这个地点被赞誉为部署降落伞滑翔机的绝佳场所。",al={"斥候去哪了","他们为何离开","谁添加的篝火燃料"}},{q="正在防守的是什么路障？",a="作者感叹该路障已不复往昔，将其破损的状态比作它曾经守护的、已陨落的人类旧王国，但却誓言绝不放弃对它的守卫。",al={"什么路障","哪些旧王国","路障背景故事"}},{q="这是一个什么样的瞭望点？",a="这个岗哨拥有绝佳的全景视野，空气中弥漫着水雾，表明它位于大型瀑布或湍流河道附近的高耸悬崖或制高点上。",al={"地点位置","为什么有水雾","鹰之拳位置"}}},fp="12,190,14.236.0,27.295.0,17.175.1,21.129.0,42.145.0,40.167.0,30.161.0,33.151.0,34.147.0"}
P.entries["quest:79976"] = {n="This Must Be The Place",s="This Must Be The Place标记了一个刚刚废弃的营地，其主人就在不久前刚刚消失。留下来的一张字条碎片揭示了这位神秘的作者为了防止研究成果落入不轨之徒手中，已转入地下继续工作。",h="This Must Be The Place标记了一个刚刚废弃的营地，其主人就在不久前刚刚消失。留下来的一张字条碎片揭示了这位神秘的作者为了防止研究成果落入不轨之徒手中，已转入地下继续工作。",kw={"废弃营地","装备包","藏身处","睡袋","一定就是这里","字条碎片","地下"},sec={{t="匆忙离开",b="在这个偏僻的地方，一位身份不明的旅者刚刚匆忙撤离营地。现场只留下一只摊开在脚下的睡袋、捆扎着各类装备的沉重帆布，以及一张撕得刚好写下一句匆忙告别的字条。无论谁曾在这里露营，都在别人赶到之前就已不见踪影。"},{t="转入地下",b="留下的字条揭示了作者决定将他们的工作带回地下，以确保其不会落入不轨之徒的手中。这张字条究竟是最后的告别，还是暗示研究者下一个隐秘据点的线索，目前还不得而知，只留下一堆废弃的设备给偶然发现此地的人。"}},faq={{q="那张字条是谁写的？",a="字条中并未提及作者的身份。作者只是解释说，为了防止研究成果落入不轨之徒手中，他们决定转入地下，留下了废弃的营地和装备。",al={"谁写的字条","字条作者","谁留下了信息"}},{q="什么样的工作被带到了地下？",a="作者工作的具体性质尚未揭晓。他们提到转入地下仅仅是为了保护他们的研究或成果，使其免受可能滥用这些成果的不明敌人的侵害。",al={"什么地下工作","为什么要带入地下","什么工作"}},{q="营地的主人去了哪里？",a="无论占据此地的人是谁，他们都匆忙打包并在有人抵达前不久溜走了。他们的去向不明，尽管字条暗示他们可能转移到了另一个隐蔽的藏身处。",al={"我是不是错过了他们","他们去了哪里","作者在哪里"}},{q="营地里留下了什么？",a="这位旅者留下了一只未能收好、散落在地上的睡袋、包着各种装备的沉重帆布，以及一个装有杂物的背包。",al={"留下了什么","营地的补给品","背包里有什么"}},{q="这是否通往另一个藏身处的线索？",a="这张字条碎片含义模糊，无法确定这究竟是道别的话语，还是指引作者下一个地下避难所的有意留下的线索。",al={"还有其他的藏身处吗","下一个营地","更多线索"}},{q="字条中提到的“不轨之徒”是谁？",a="字条中并未具体说明谁是“不轨之徒”。作者显然担心被追捕或失窃，因此在成果可能泄露前匆忙撤离。",al={"谁是不轨之徒","不轨之徒的含义","谁在追赶作者"}}},fp="22,180,17.289.0,20.253.1,24.175.0,37.140.0,37.143.0,37.175.0,42.106.0,48.127.0"}
P.entries["quest:79980"] = {n="Scramble",s="“攀爬”是一场隐藏的寻宝游戏，指引冒险者沿着陡峭的悬崖向下寻找坐标。在寻宝者便条的引导下，旅行者们挖掘出了一个埋藏的信使袋，里面装有生存物资和一张肮脏的羊皮纸。",h="“攀爬”是一场隐藏的寻宝游戏，指引冒险者沿着陡峭的悬崖向下寻找坐标。在寻宝者便条的引导下，旅行者们挖掘出了一个埋藏的信使袋，里面装有生存物资和一张肮脏的羊皮纸。",kw={"藏匿点","悬崖边","信使袋","羊皮纸","攀爬","补给品"},sec={{t="向北的小径",b="一则神秘的信息指引着任何足够聪明的旅行者找到一个隐藏的补给藏匿点。作者在留下精确方向的同时，还留下了非正式的鼓励：向正北方向沿着险峻的悬崖行进一百步，就能找到为了让旅行者继续前行而留下的物资。"},{t="挖掘信使袋",b="沿着指示走下陡峭的悬崖面，可以发现一个埋藏的信使袋。从泥土中挖出袋子后，里面装着实用的生存物资，还有一张塞在里面的肮脏羊皮纸，暗示这次简短的“攀爬”只是更大路径的一部分。"}},faq={{q="“攀爬”任务是什么？",a="“攀爬”是一个寻宝路径任务，引导冒险者前往一个隐藏的生存物资藏匿点。一张写好的便条指引找到它的人向北沿着险峻的悬崖行进，去回收埋藏的补给。",al={"攀爬任务","什么是攀爬","攀爬藏匿点"}},{q="隐藏的藏匿点在哪里？",a="根据说明，藏匿点埋在正北方向大约一百步处，位于陡峭的悬崖下方。需要小心落脚，以免从岩壁上跌落。",al={"藏匿点在哪里","如何找到藏匿点","藏匿点位置"}},{q="是谁留下了便条和藏匿点？",a="作者的确切身份不明。写信人留下了一些非正式的实用笔记，意在让探险者定位他们的应急物资，并确认藏匿点保持完好。",al={"谁写了攀爬便条","谁留下了藏匿点","攀爬任务作者"}},{q="埋藏的藏匿点里有什么？",a="挖出藏匿点后，会发现一个埋藏的信使袋，里面装有生存物资和一张夹在装备中的肮脏羊皮纸。",al={"攀爬任务奖励","攀爬藏匿点里有什么","袋中物品"}},{q="与物资一起发现的肮脏羊皮纸是什么？",a="肮脏的羊皮纸与补给品一起塞在埋藏的信使袋里，是在将袋子从地下拉出来时被发现的。",al={"攀爬肮脏羊皮纸","羊皮纸上写了什么","攀爬便条"}},{q="到达藏匿点有什么危险？",a="主要的危险在于从北面的悬崖向下进行陡峭的下降，任何失足都可能导致脚踝骨折或严重的坠落。",al={"攀爬危险","悬崖攀爬","攀爬悬崖边"}}},fp="8,163,19.246.0,28.196.1,27.156.0,34.127.0,32.143.0,32.89.0,52.133.0,48.99.0"}
P.entries["quest:8"] = {n="潜行者的交易",s="卡尔文·蒙泰古在丧钟镇请求的一件看似随意的差事，将一名旅行者送上了前往布瑞尔恐惧之末旅店的道路。这项差事涉及以普通信使的名义，向旅店老板瑞尼递送一封神秘且没有收件人地址的信件。",h="卡尔文·蒙泰古在丧钟镇请求的一件看似随意的差事，将一名旅行者送上了前往布瑞尔恐惧之末旅店的道路。这项差事涉及以普通信使的名义，向旅店老板瑞尼递送一封神秘且没有收件人地址的信件。",kw={"布瑞尔","卡尔文·蒙泰古","丧钟镇","恐惧之末","旅店老板瑞尼","笔迹潦草的信件","潜行者","提瑞斯法林地"},ang={["class:Rogue"]="卡尔文·蒙泰古的私人信使差事让人们得以一窥丧钟镇和布瑞尔周围进行的非正式交易。",["faction:Horde"]="这次投递直接通向布瑞尔，将刚到达的盟友引向提瑞斯法林地被遗忘者行政和休整的区域中心。",["race:Undead"]="对于刚复活的被遗忘者来说，这项差事标志着他们第一次离开丧钟镇墓地的安全范围，前往熙熙攘攘的布瑞尔中心。"},sec={{t="友好的信使",b="卡尔文·蒙泰古在丧钟镇那庄严肃穆的墓地和破败的礼拜堂间徘徊，表现得像个被天灾僵尸和爬行的蜘蛛折磨得精疲力竭的战士。他声称自己只是需要人手帮忙把一封信送到布瑞尔，并将一封未标记的信件托付给路过的冒险者。他轻松的态度和丰厚报酬的承诺，让这项任务看起来不过是件为了引导刚觉醒的被遗忘者前往该地区主要城镇而进行的无害之举。"},{t="恐惧之末旅店",b="道路向东延伸，穿过提瑞斯法林地那枯萎的树木，经过炉灰庄园，最终到达布瑞尔定居点。在当地旅店的柜台后，旅店老板瑞尼最初以一种令人不安的阳光态度迎接新人，对客人的舒适度关怀备至。然而，在收到蒙泰古的信件后，她的热情立刻土崩瓦解。她抛弃了伪装出来的亲切，佯称自己收到了来自慈母的消息，随后责骂信使多管闲事，并要求他们买点东西或者立刻离开。事后回到卡尔文那里又会出现另一个惊喜：他并没有和平地支付承诺的报酬，而是向信使发起了决斗。"}},faq={{q="卡尔文·蒙泰古是谁？",a="卡尔文·蒙泰古是丧钟镇的一名潜行者，他请求刚觉醒的旅行者帮他把一封信送到布瑞尔的旅店老板瑞尼手中。他将此描述为一个简单的恩惠，并承诺给予丰厚的回报。",al={"卡尔文·蒙泰古","谁发布潜行者的交易","任务发布者"}},{q="笔迹潦草的信件里写了什么？",a="这封信的具体内容并未被记录。卡尔文交给信使一封未标记的信件，要求送给布瑞尔的旅店老板瑞尼。",al={"笔迹潦草的信件内容","信里有什么","卡尔文的信"}},{q="为什么旅店老板瑞尼表现得如此奇怪？",a="瑞尼经营着布瑞尔的旅店，并坚称她的信件是私人的。将蒙泰古的信件带给她，就能揭晓她对这次投递的反应。",al={"旅店老板瑞尼的态度","为什么瑞尼在演戏","瑞尼母亲的借口"}},{q="卡尔文·蒙泰古真的会为这次投递支付报酬吗？",a="蒙泰古承诺会为投递支付高额报酬。当信件送达时，瑞尼会提供食物或水；事后请回到卡尔文那里，继续就他承诺的报酬进行交涉。",al={"卡尔文是不是骗我","我的钱在哪里","蒙泰古的奖励"}},{q="布瑞尔在哪里？",a="布瑞尔位于丧钟镇的东北方。旅行者沿着起始山谷的主要道路向东走，向右拐过炉灰庄园，穿过一座廊桥即可到达该定居点。",al={"如何前往布瑞尔","去布瑞尔的路","布瑞尔路线指引"}},{q="把信交给瑞尼之后会发生什么？",a="后续任务名为“潜行者的交易”。回到丧钟镇的卡尔文·蒙泰古那里，继续与他进行交易。",al={"下一个任务","潜行者的交易后续","交给瑞尼后做什么"}}},fx={df83fdd9={q="卡尔文·蒙泰古为什么要送出这封信？",a="卡尔文·蒙泰古声称，自己在丧钟镇附近对付过不少毫无理智的僵尸和蜘蛛，现在只需要有人替他跑一趟腿。他不愿亲自沿路走到布瑞尔，便提出付给你一大笔钱，让你把他封好的、笔迹潦草的信件直接送给旅店老板瑞尼。",al={"卡尔文·蒙泰古的动机","为什么要把信送给瑞尼","卡尔文为什么要我做这件事"}}},fp="14,136,18.299.0,23.469.1,23.175.0,38.112.0,40.147.0,51.194.0,23.161.0,46.100.1"}
P.entries["quest:80"] = {n="斯塔文的传说",s="调查斯塔文·密斯曼托的关键一步是将收集到的证据提交给夜色镇的当局。指挥官阿尔泰娅·埃伯洛克手中拿着一张染血的日记书页，指示调查员去找书记员达尔塔，以便彻底鉴定笔迹的真伪。",h="调查斯塔文·密斯曼托的关键一步是将收集到的证据提交给夜色镇的当局。指挥官阿尔泰娅·埃伯洛克手中拿着一张染血的日记书页，指示调查员去找书记员达尔塔，以便彻底鉴定笔迹的真伪。",kw={"阿尔泰娅·埃伯洛克","染血的日记书页","书记员达尔塔","夜色镇","暮色森林","斯塔文的传说","夜色守夜人","斯塔文·密斯曼托"},ang={["faction:Alliance"]="这次调查突显了像夜色镇这样的边境城镇尽管受到亡灵和暗影野兽的围困，却依然努力维持法律、秩序和民事记录。",["race:Human"]="对于南方王国的人类来说，这个任务触及了将暴风城贵族、暮色森林定居者和艾尔文森林散落的庄园联系在一起的各种悲剧。"},sec={{t="收网",b="随着在暮色森林及周边人类领地搜寻到的日记书页留下的线索，夜色守夜人终于掌握了似乎能证实那个难以捉摸的导师——斯塔文·密斯曼托罪行的确凿证据。指挥官阿尔泰娅·埃伯洛克对这个人抱有怀疑已经有一段时间了，但要进行正式宣判，就需要绝对的确定性。在能够毫无疑问地证明这些恐怖的文字确实出自斯塔文之手前，单单一页染血的日记还不足以定罪。"},{t="书记员的慧眼",b="为了弥合怀疑与确定性之间的差距，夜色守夜人求助于夜色镇的镇档案管理员，书记员达尔塔。由于多年来一直负责镇上的登记工作，达尔塔检查过无数的账簿和签名，这使他成为了笔迹鉴定方面的权威。将新发现的日记书页与镇档案中斯塔文过去的签名直接进行对比，提供了确认其堕落和罪行所需的最后且无可辩驳的证据。"}},faq={{q="为什么埃伯洛克指挥官需要达尔塔书记员的确认？",a="指挥官阿尔泰娅·埃伯洛克希望在采取最终行动之前，确保斯塔文的罪行得到毫无疑问的证实。书记员达尔塔负责管理夜色镇的镇登记册，并且在检查签名方面经验丰富，这使他有独特的资格来验证那页染血的日记是否与镇档案中斯塔文的笔迹相符。",al={"为什么要找达尔塔","为什么要核对笔迹","书记员达尔塔的作用"}},{q="这一步在“斯塔文的传说”故事线中处于什么位置？",a="这是这项漫长调查的第十一章。它发生在找回染血的日记书页之后，是夜色守夜人对斯塔文采取果断行动之前进行的最后证据核实。",al={"这是任务的哪一部分","任务链进度","斯塔文任务链顺序"}},{q="书记员达尔塔在夜色镇的什么位置？",a="书记员达尔塔可以在夜色镇的市政厅内找到，他负责为社区管理当地的记录和财产登记册。",al={"达尔塔的位置","书记员达尔塔在哪里","寻找达尔塔"}},{q="调查员带给夜色镇什么证据？",a="调查员携带了一页在持续搜寻斯塔文下落的过程中找回的染血的日记书页。书页上的文字描述了他阴暗的思想和经历，但需要与官方记录进行笔迹比对。",al={"证据是什么","这是哪一页","染血的日记书页背景"}},{q="书记员达尔塔确认那是斯塔文的笔迹吗？",a="是的。通过将染血的书页与镇登记册中的签名进行比对，达尔塔确认笔迹相符，这让埃伯洛克在采取最终行动前获得了她所需要的确定性。",al={"笔迹匹配吗","是斯塔文吗","是斯塔文写的吗"}},{q="为什么夜色守夜人对指控斯塔文如此谨慎？",a="即使在暮色森林这片饱受困扰、与世隔绝的土地上，夜色守夜人也在努力维持合法的秩序。指控一位前学者犯下骇人听闻的罪行需要具体的、可验证的证据，而不是仅仅依靠传闻或推测。",al={"为什么要证据","为什么不直接杀了斯塔文","埃伯洛克的怀疑"}}},fp="21,201,15.372.0,15.329.1,62.286.0,62.202.0,43.119.0,54.194.0,55.183.1,58.219.0"}
P.entries["quest:80001"] = {n="Rekindle",s="熄灭的火坑里备有干柴，随时可以点燃。你将侦察技能派上用场。",h="熄灭的火坑里备有干柴，随时可以点燃。你将侦察技能派上用场。",kw={"干柴","熄灭的火","火坑","rekindle","侦察技能"},sec={{t="火坑旁",b="木柴干燥，足以点燃。你在熄灭的火坑旁将侦察技能派上用场。"}},faq={{q="Rekindle 讲的是什么？",a="熄灭的火坑里备有干柴，随时可以点燃，而你将侦察技能派上用场。",al={"rekindle 任务","rekindle 火焰","火坑"}},{q="火坑出了什么问题？",a="火坑已经熄灭，不过木柴干燥，足以点燃。",al={"火坑问题","为何没有火","熄灭的火"}},{q="完成时的描述说了什么？",a="完成时的描述说，你将侦察技能派上用场。",al={"rekindle 结局","完成时会发生什么","侦察技能"}}},fp="8,96,15.107.0,23.98.0,32.75.0,29.54.0"}
P.entries["quest:804"] = {n="萨科斯",s="在为受伤的暗矛巨魔哈纳祖报仇，击杀了恐怖的蝎虫萨科斯之后，冒险者必须将他的困境传达回大兽穴。必须立刻通知高内克，这样救援才能及时抵达，在剧毒夺去这位侦察兵的性命之前将他救回。",h="在为受伤的暗矛巨魔哈纳祖报仇，击杀了恐怖的蝎虫萨科斯之后，冒险者必须将他的困境传达回大兽穴。必须立刻通知高内克，这样救援才能及时抵达，在剧毒夺去这位侦察兵的性命之前将他救回。",kw={"暗矛","杜隆塔尔","高内克","哈纳祖","萨科斯","蝎虫","大兽穴","试炼谷"},ang={["faction:Horde"]="新部落建立在严酷无情的土地上，强调共同生存；不抛弃任何一名同伴是学徒从迈出第一步起就被教导的基本原则。",["race:Orc"]="兽人文化重视个人的力量，但挺身而出捍卫一名失去行动能力的盟友的荣誉，这证明了一个真正战士的内心。",["race:Troll"]="暗矛部族与萨尔的兽人之间萌芽的联盟，正是通过诸如从缓慢的剧毒死亡中拯救哈纳祖这类兄弟情谊的行为而得以加强。"},sec={{t="侦察兵的困境",b="暗矛侦察兵哈纳祖被困在试炼谷的高耸峭壁上，他身中剧毒，无法独自走下险峻的山路。虽然他击败了将他打倒的恐怖蝎虫萨科斯并完成了复仇，但仅凭骄傲无法支撑一位中毒的战士穿越这片贫瘠的乱石之地。他被困在岩石上，只能寄希望于路过的学徒将消息带回训练营地。"},{t="大兽穴的荣誉",b="回到大兽穴向高内克复命即可完成试炼。高内克立刻意识到了萨科斯的威胁，并迅速组织人手营救哈纳祖。在部落指挥官眼中，暂时放下个人的训练去伸张正义并营救一名落难的陌生人，体现了真正的荣誉。这证明了学徒在真正踏入杜隆塔尔之前就已经具备了应有的价值。"}},faq={{q="哈纳祖是谁，他为什么会被困住？",a="哈纳祖是一位年轻的暗矛巨魔侦察兵，他在前往试炼谷高处时遭到恐怖蝎虫萨科斯的伏击并中毒。由于虚弱无法独自爬下山崖，他需要救援。",al={"哈纳祖","哈纳祖是谁","为什么巨魔受伤了"}},{q="高内克是谁？",a="高内克是一位驻扎在试炼谷大兽穴的兽人监工。他负责评估新兵、分配生存任务，并在学徒在峡谷中遭遇致命威胁时协调救援。",al={"高内克","高内克在哪里","大兽穴领导者"}},{q="萨科斯是什么？",a="萨科斯是一只臭名昭著的巨型蝎虫，栖息在试炼谷上方的岩石峭壁中。它的剧毒和凶猛使它成为年轻兽人和巨魔试炼中的一个传说级威胁。",al={"野兽萨科斯","萨科斯是什么样的怪物"}},{q="哈纳祖的伤势能痊愈吗？",a="高内克承诺在收到你的报告后会立即派遣救援前往哈纳祖所在的地方。至于这位侦察兵后来如何，文中并未提及。",al={"巨魔活下来了吗","哈纳祖还好吗","哈纳祖获救"}},{q="为什么高内克如此高度赞扬这一行为？",a="人们期望你能从试炼中存活下来，但将你自己的任务搁置一旁，为了一个陌生人的荣誉而战并确保他们能活下去，这才是新部落试图在战士身上培养的核心价值观。",al={"为什么高内克在意","高内克的荣誉演讲"}},{q="大兽穴在哪里？",a="大兽穴是位于杜隆塔尔西南部试炼谷中心地带的中央训练洞穴和集结地。",al={"大兽穴在哪里","杜隆塔尔大兽穴位置"}}},fp="7,210,16.336.0,16.328.0,39.166.0,14.182.0,16.184.0,33.121.1,43.179.0,25.117.0"}
P.entries["quest:805"] = {n="去森金村报到",s="“向森金村报告”标志着年轻的部落新兵离开了与世隔绝的试炼谷，去警告暗矛巨魔有关恶魔邪教活动的时刻。在祖雷萨的委托下，信使将火刃氏族的消息带给了加德林大师，并发现暗影魔法已经威胁到了附近的海岸。",h="“向森金村报告”标志着年轻的部落新兵离开了与世隔绝的试炼谷，去警告暗矛巨魔有关恶魔邪教活动的时刻。在祖雷萨的委托下，信使将火刃氏族的消息带给了加德林大师，并发现暗影魔法已经威胁到了附近的海岸。",kw={"火刃氏族","暗矛","杜隆塔尔","回音群岛","加德林大师","森金村","试炼谷","祖雷萨"},ang={["faction:Horde"]="这项任务展示了萨尔领导的部落各大创始种族之间至关重要的合作，他们通过交换情报来保护彼此年轻的定居点。",["race:Orc"]="对于年轻的兽人来说，离开试炼谷去帮助暗矛部族是考验荣誉和团结的一项早期试炼，也是对那些在无尽之海彼岸与萨尔并肩作战的盟友展现支持的契机。",["race:Troll"]="回到森金村，暗矛冒险者们将直面族人流离失所的现状，以及收复回音群岛的持续斗争。"},sec={{t="离开大兽穴",b="在证明了自己的战斗实力并从试炼谷内的火刃集会所夺回黑暗勋章后，新手们被认为已做好准备迎接更广阔的世界。祖雷萨意识到，这些神圣试炼场中的恶魔存在并非孤立的骚乱，而是杜隆塔尔蔓延开来的枯萎症的征兆。她引导年轻的冒险者们向东穿过峡谷出口，并向南前往海岸，以警告暗矛部族。"},{t="海岸之上的阴影",b="当旅行者抵达沿海定居点森金村时，他们将警告传达给了流亡中的暗矛部族领袖、年长的巫医加德林大师。虽然加德林证实火刃氏族本身并未袭击村庄的沙滩，但他透露黑暗魔法已在附近的回音群岛生根。这份报告揭示了年轻部落的立足点依然是多么脆弱：即使盟友们竞相保卫彼此，古老的部落背叛和邪能腐蚀也在同时打击着他们的侧翼。"}},faq={{q="祖雷萨为什么派人离开试炼谷？",a="在揭露了试炼谷内的恶魔活动后，祖雷萨担心火刃集会所对整个杜隆塔尔构成了有组织的威胁。她派遣久经考验的新兵走出山谷，去警告盟友的定居点，并查明邪教的影响范围有多广。",al={"为什么要离开山谷","为什么要前往森金","祖雷萨的任务"}},{q="加德林大师是谁？",a="加德林大师是一位年长的巫医，也是居住在森金村的暗矛巨魔的精神领袖。他担任沃金酋长的顾问，在处理笼罩着他们临时沿海避难所的威胁的同时，监督部落事务。",al={"加德林大师的背景","谁是加德林"}},{q="火刃氏族袭击过森金村吗？",a="没有，火刃氏族并未直接袭击过森金村。然而，加德林大师指出，类似的黑暗魔法和背叛已经在附近的回音群岛生根，这意味着巨魔们正面临着属于他们自己的迫在眉睫的危险。",al={"火刃氏族在森金村吗","森金村的邪教"}},{q="森金村在哪里？",a="森金村位于试炼谷主峡谷出口向东的方向，在路口处向南转，沿着杜隆塔尔的东南海岸即可到达。",al={"如何前往森金村","森金村的方向"}},{q="加德林大师提到了回音群岛的什么威胁？",a="加德林大师担心扎拉赞的黑暗背叛，这名巨魔巫医同僚利用阴险的妖术奴役了他的族人并夺取了回音群岛的控制权，迫使幸存的暗矛部族逃往大陆海岸。",al={"回音群岛的麻烦","回音群岛发生了什么"}},{q="向加德林大师报告后会发生什么？",a="在听取了你的报告并详细说明了巨魔们自己的困境后，加德林请求你协助应对威胁海岸线的危险，随后的命令会将你派往西北方向，去寻找剃刀岭的奥戈尼尔·魂痕。",al={"向森金报告后的下一个任务","加德林之后做什么"}}},fp="25,237,15.395.0,22.434.1,70.235.0,21.202.0,47.176.0,33.144.0,57.235.0,46.204.0"}
P.entries["quest:806"] = {n="黑暗风暴",s="“黑暗风暴”是剃刀岭的奥戈尼尔·魂痕委派的一项重要任务，旨在铲除一名正在腐化这片土地的邪恶术士。一个名叫费索·暗风的哥布林代表阴险的火刃氏族在雷霆山扎下了根。在他进一步扩散其邪教势力之前消灭他，对于保护杜隆塔尔免受恶魔复苏的威胁至关重要。",h="“黑暗风暴”是剃刀岭的奥戈尼尔·魂痕委派的一项重要任务，旨在铲除一名正在腐化这片土地的邪恶术士。一个名叫费索·暗风的哥布林代表阴险的火刃氏族在雷霆山扎下了根。在他进一步扩散其邪教势力之前消灭他，对于保护杜隆塔尔免受恶魔复...",kw={"火刃氏族","黑暗风暴","杜隆塔尔","费索·暗风","费索的爪子","奥戈尼尔·魂痕","剃刀岭","雷霆山"},ang={["class:Shaman"]="费索及其爪牙所施行的黑暗仪式扰乱了雷霆山的自然之灵，激怒了这里的野兽，迫切需要恢复元素平衡。",["class:Warlock"]="费索·暗风展示了对邪能盲目崇拜所带来的鲁莽危险，这使他成为了一个令部落严守纪律的施法者们无法容忍的污点和隐患。",["faction:Horde"]="确保杜隆塔尔的核心区域免受恶魔的颠覆，这能让初生的部落将防御力量集中于对外，而不是从内部瓦解。",["race:Orc"]="火刃氏族代表着兽人们每天都在努力克服的黑暗过去。消灭像费索这样的邪教潜入者，对于维护萨尔建立的自由国度至关重要。"},sec={{t="岭中的威胁",b="正当年轻的部落保卫者巡视杜隆塔尔边境时，内部的腐化正在他们的眼皮底下滋生。奥戈尼尔·魂痕在剃刀岭进行调查时发现，西北方的雷霆山已陷入黑暗魔法的掌控。那片峡谷里爬满了火刃氏族的邪教徒，他们给当地的野生生物和土地带来了毁灭与混乱。"},{t="费索·暗风",b="统领峡谷内邪教活动的正是费索·暗风，一个与火刃氏族结盟的投机主义哥布林术士。费索并非为了商业或财阀利益服务，而是直接运用邪能来推动该邪教的颠覆性议程。杀掉他并取回他的扭曲爪子，向奥戈尼尔证明该峡谷内邪教的直接领导层已被瓦解。"},{t="铲除邪教",b="火刃氏族代表着萨尔的新部落竭力摒弃的一切：恶魔奴役、鲁莽的腐化以及嗜血的疯狂。铲除费索不仅从杜隆塔尔的腹地清除了一名活跃的阴谋家，也预示着笼罩在兽人故乡上的阴影远比一些孤立的营地要深远得多。"}},faq={{q="谁是费索·暗风？",a="费索·暗风是一名代表火刃氏族行事的哥布林术士。他和他的邪教追随者躲藏在雷霆山，在峡谷中散布恶魔带来的混乱，直到奥戈尼尔·魂痕下令将他处决。",al={"谁是费索","费索·暗风背景故事","费索哥布林"}},{q="雷霆山位于何处？",a="雷霆山是一条崎岖的峡谷，位于杜隆塔尔西北部，剃刀岭以北，奥格瑞玛西南方。这里以充斥着带有闪电能量的野兽和火刃氏族邪教营地而闻名。",al={"雷霆山在哪里","雷霆山位置","如何找到雷霆山"}},{q="为什么火刃氏族会出现在杜隆塔尔？",a="火刃氏族试图破坏萨尔的部落，并重建恶魔对兽人的统治。他们在杜隆塔尔各处的隐秘峡谷、洞穴和山涧中秘密活动，试图从内部散布腐化。",al={"杜隆塔尔的火刃氏族","为什么邪教徒在杜隆塔尔","火刃氏族的目的"}},{q="为什么奥戈尼尔·魂痕特别需要费索的爪子？",a="奥戈尼尔需要确凿的证据来证明该术士已被终结。带回费索的爪子可以确认，雷霆山邪教团伙的首领已无法继续指挥行动。",al={"为什么需要费索的爪子","费索的爪子的含义","费索死亡证明"}},{q="击杀费索后会发生什么？",a="击败费索扫清了雷霆山的直接威胁，奥戈尼尔·魂痕会指引你去找萨满祭司玛戈兹，他了解更多关于火刃氏族腐化的信息，以铲除更多火刃氏族的阴谋。",al={"黑暗风暴之后的任务","黑暗风暴后续","黑暗风暴的下一个任务"}},{q="为什么哥布林会为火刃氏族效力？",a="虽然许多哥布林通过贸易财阀追求黄金，但也有一些哥布林被暗影魔法所带来的原始力量、影响力和黑暗技艺所诱惑。费索拥抱了邪能巫术，并将他那冷酷的狡诈直接贡献给了邪教徒。",al={"哥布林与火刃氏族","费索为何加入邪教","术士费索"}}},fp="11,179,21.246.0,16.291.0,20.284.1,24.204.0,31.169.0,36.193.0,57.166.0,35.182.1,46.167.0"}
P.entries["quest:808"] = {n="明希纳的颅骨",s="森金村的加德林大师一直被他已故兄弟明希纳绝望的哭喊声所困扰。明希纳在回音群岛被邪恶的巫医扎拉赞杀害并施以黑暗魔法，他的灵魂被禁锢在自己破碎的颅骨之中。想要解救这位倒下的巨魔，必须潜入扎拉赞的仪式场地，夺回这件圣物，并使他的灵魂从永恒的折磨中解脱出来。",h="森金村的加德林大师一直被他已故兄弟明希纳绝望的哭喊声所困扰。明希纳在回音群岛被邪恶的巫医扎拉赞杀害并施以黑暗魔法，他的灵魂被禁锢在自己破碎的颅骨之中。想要解救这位倒下的巨魔，必须潜入扎拉赞的仪式场地，夺回这件圣物，并使他...",kw={"能量之环","暗矛","回音群岛","加德林","明希纳","森金村","颅骨","巫毒","扎拉赞"},ang={["class:Priest"]="牧师理解已故灵魂的神圣性，也明白那种将倒下的兄弟禁锢在永恒安宁之外的死灵仪式的恐怖。",["class:Shaman"]="萨满崇敬祖先的灵魂；打破扎拉赞的圆环来释放一个被折磨的灵魂，能够恢复精神世界与现实世界之间的平衡。",["faction:Horde"]="协助加德林大师是对新部落与暗矛巨魔之间纽带的尊重，证明了盟友的悲痛是大家共同承担的。",["race:Troll"]="对于一名暗矛巨魔来说，取回明希纳的颅骨是对家庭和部落的神圣职责，这沉重打击了扎拉赞对祖先巫毒传统的扭曲。"},sec={{t="来自阴影的恳求",b="加德林大师是森金村暗矛巨魔部落的精神支柱之一，但他此刻正深受黑暗幻象的折磨。他的兄弟明希纳在疯狂的术士扎拉赞夺取回音群岛控制权时，成为了这场背叛的受害者。明希纳在那场冲突中丧生，但在巨魔的传统和巫毒秘术中，肉体的死亡并不意味着真正的安宁。明希纳受尽折磨的声音不断在加德林的梦境中响起，恳求着从这比死亡更糟糕的命运中获得救赎。"},{t="扎拉赞的能量之环",b="扎拉赞不仅仅是杀害了他的同胞，他还捕获了他们的灵魂，以此为自己的黑暗巫术提供力量。明希纳的灵魂被仪式性地禁锢在他自己的颅骨上，现在这颗颅骨正安放在回音群岛中最大的一座岛屿上的邪恶能量之环中。在被施了妖术的巨魔守卫下，浸泡在烛光仪式之中，这颗颅骨成为了那个叛徒扭曲巫术的焦点。只要它还留在那个圆环中，明希纳就将永远受制于扎拉赞的意志。"},{t="死亡中的自由",b="为了拯救明希纳，一位勇敢的勇士必须横渡森金村东侧的水域，抵达回音群岛的南端，闯入仪式圆环，并将颅骨从那位巫医的控制中解救出来。将遗骸带回给加德林大师可以切断黑暗的束缚，让明希纳感恩的灵魂短暂现身，鞠躬致敬，最终前往祖先的国度。"}},faq={{q="明希纳是谁？",a="明希纳是加德林大师的兄弟，加德林是居住在森金村的一位杰出的巫医兼长者。他在回音群岛的叛乱中被扎拉赞杀害，扎拉赞随后利用黑暗巫术亵渎了他的遗骸。",al={"明希纳身份","明希纳是谁","加德林的兄弟"}},{q="为什么明希纳的灵魂会被困在他的颅骨里？",a="扎拉赞利用黑暗巫毒和术士魔法来奴役被杀害的暗矛巨魔的灵魂。通过将明希纳的灵魂直接禁锢在他的颅骨上，并将其放置在一个仪式的能量之环中，扎拉赞剥夺了他前往来世的通道，并奴役了他的灵魂。",al={"为何禁锢颅骨","扎拉赞灵魂陷阱","明希纳灵魂"}},{q="能量之环在哪里？",a="这个仪式地点位于杜隆塔尔东南海岸外，回音群岛中最靠南、也是最大的一座岛屿山顶之上。那里有仪式蜡烛、跳舞的受控巨魔和展示的颅骨，非常容易辨认。",al={"颅骨在哪里","能量之环位置","明希纳颅骨位置"}},{q="当颅骨被带回森金村时会发生什么？",a="加德林大师收到颅骨后，死灵束缚将会破碎。明希纳的鬼魂将出现在他的兄弟和探险者面前，感激地鞠躬，然后消失，去与祖先们安息在一起。",al={"任务交还","明希纳发生了什么","明希纳会出现吗"}},{q="扎拉赞是谁？他为什么要这么做？",a="扎拉赞曾是暗矛巨魔部落里备受尊敬的巫医。由于对力量的渴望而陷入疯狂，他背叛了部落，使用妖术控制了族人的心智，并将剩余的暗矛难民驱赶到了杜隆塔尔的大陆上。",al={"谁是扎拉赞","为什么扎拉赞是邪恶的","扎拉赞背景故事"}},{q="为什么加德林自己不去取回颅骨？",a="加德林大师对于维持森金村的稳定至关重要。他既要指导年轻的暗矛领导层，又要为酋长沃金提供建议，还要积极应对扎拉赞在海岸沿线不断蔓延的妖术，因此他无法离开村庄，使其陷入无人保护的境地。",al={"为什么加德林不亲自去","加德林的职责"}}},fp="16,254,23.468.0,26.384.0,16.345.1,17.142.0,46.259.0,37.197.0,63.199.1,39.230.0,44.220.0"}
P.entries["quest:809"] = {n="雅克塞罗斯",s="雅克塞罗斯是一个早期部落任务，由术士尼尔鲁·火刃在奥格瑞玛深处的暗影裂口中发布。由于发现了残留的恶魔腐蚀证据，尼尔鲁派遣冒险者前往贫瘠之地，与他驻扎在边界附近的现场联络人会合。",h="雅克塞罗斯是一个早期部落任务，由术士尼尔鲁·火刃在奥格瑞玛深处的暗影裂口中发布。由于发现了残留的恶魔腐蚀证据，尼尔鲁派遣冒险者前往贫瘠之地，与他驻扎在边界附近的现场联络人会合。",kw={"雅克塞罗斯","贫瘠之地","火刃氏族","暗影裂口","恶魔之种","鬼雾峰","前沿哨所","尼尔鲁·火刃"},ang={["class:Warlock"]="熟悉尼尔鲁·火刃教导的术士可能会注意到，当他自己的助手质疑摧毁恶魔圣物的命令时，其中必有蹊跷。",["faction:Horde"]="确保前沿哨所的安全并清除鬼雾峰对于保护连接杜隆塔尔与贫瘠之地的早期贸易和交通路线至关重要。",["race:Orc"]="兽人们曾为摆脱燃烧军团的掌控而进行过艰苦的战斗，因此在他们的家门口出现火刃氏族和恶魔圣物的任何迹象都是一种迫在眉睫的威胁。"},sec={{t="暗影的踪迹",b="在杜隆塔尔发现一条火刃氏族的徽记项圈后，尼尔鲁·火刃声称要追捕威胁这个新定居部落的恶魔残党。尼尔鲁自诩为对抗邪能腐蚀的守门人，他将冒险者指引向贫瘠之地的干旱平原，并警告说一个邪恶的教派正在围绕一件名为恶魔之种的邪恶神器集结。"},{t="前沿哨所的联络人",b="为了协调针对该教派的打击行动，冒险者必须寻找雅克塞罗斯，他是尼尔鲁的助手，驻扎在杜隆塔尔与贫瘠之地交界处的前沿哨所附近。然而在抵达时，雅克塞罗斯对这项任务表现出了一种沉默的怀疑，他公开揣测他的主人为何会真心想要销毁这件神器，随后才提供了关于如何处理鬼雾峰上恶魔之种的指示。"}},faq={{q="谁发布了这个任务？",a="该任务由尼尔鲁·火刃发布，他是一名居住在奥格瑞玛下方暗影裂口阴暗洞穴中的术士。在你向他出示火刃氏族项圈后，他便会发布此任务。",al={"任务发布者","如何找到雅克塞罗斯","尼尔鲁·火刃任务"}},{q="雅克塞罗斯在哪里？",a="雅克塞罗斯位于前沿哨所外，就在贫瘠之地东部边界、杜隆塔尔桥梁过处的地方。",al={"雅克塞罗斯位置","雅克塞罗斯在哪里","寻找雅克塞罗斯"}},{q="什么是恶魔之种？",a="恶魔之种是一件拥有恶魔之力的污秽神器，被火刃氏族教派保存在贫瘠之地北部的险峻山峰鬼雾峰之上。",al={"恶魔之种背景","什么是恶魔之种"}},{q="为什么雅克塞罗斯觉得尼尔鲁的命令很奇怪？",a="雅克塞罗斯没有解释原因。他只是评论说尼尔鲁想要销毁恶魔之种令人感到奇怪，然后才同意告诉你如何移除它。",al={"为什么雅克塞罗斯感到惊讶","雅克塞罗斯的奇怪反应"}},{q="这个任务之后是什么任务？",a="与雅克塞罗斯交谈会直接引导至任务“恶魔之种”，该任务要求你登上鬼雾峰来清除这件具有腐蚀性的圣物。",al={"雅克塞罗斯后的下一个任务","雅克塞罗斯后续"}},{q="这个任务是火刃氏族剧情线的一部分吗？",a="是的。它起到了关键的连接作用，将杜隆塔尔发现的当地教派阴谋与贫瘠之地中更广泛、更有组织的教派活动联系了起来。",al={"火刃氏族任务线","奥格瑞玛教派任务"}}},fp="9,122,17.313.0,19.224.1,21.126.0,27.120.0,23.122.0,47.116.1,28.105.0,50.111.0"}
P.entries["quest:812"] = {n="救命如救火",s="暗矛巨魔林纳格被困在杜隆塔尔西北部崎岖的峭壁上，身中尾蝎毒素，生命垂危。在毒素发作之前的时间所剩无几，他只能寄希望于一名信使，请求其飞奔前往奥格瑞玛，从考格汉那里取回解药。",h="暗矛巨魔林纳格被困在杜隆塔尔西北部崎岖的峭壁上，身中尾蝎毒素，生命垂危。在毒素发作之前的时间所剩无几，他只能寄希望于一名信使，请求其飞奔前往奥格瑞玛，从考格汉那里取回解药。",kw={"解毒剂","暗影裂口","杜隆塔尔","考格汉","寻求治疗","奥格瑞玛","林纳格","蝎子","尾蝎"},ang={["faction:Horde"]="杜隆塔尔的岩石地形严酷无情，对于新抵达萨尔年轻王国的保卫者而言，这是一场永无止境的烈火试炼。",["race:Troll"]="林纳格对返回森金村的恐惧，凸显了暗矛部族那严苛的自尊心，在荒野生存中表现出的粗心大意会招致同族的严厉嘲讽。"},sec={{t="蝎子的毒刺",b="杜隆塔尔干旱的峡谷中到处都是尾蝎，这些侵略性极强的掠食者尾刺中带有迅速且令人虚弱的神经毒素。林纳格在边境附近与这些野兽战斗时一时大意，不幸中毒。深知毒素蔓延下他活不过一小时，身体也无法支撑他自己走到城门，他只能将生存的希望托付给每一个经过他营地的人。"},{t="阴影中的秘密",b="林纳格没有去寻找普通的药剂师或萨满，而是指引旅人深入奥格瑞玛地底的暗影裂口——大断崖。那里住着考格汉，一位对杜隆塔尔荒野剧毒了如指掌的神秘修行者。考格汉拥有配制强效解毒剂的知识，但他很少轻易向那些尚未证明自己实力的人提供帮助。"}},faq={{q="林纳格是谁？",a="林纳格是一名暗矛巨魔冒险者，在杜隆塔尔西北部的峭壁上奄奄一息。他被尾蝎刺伤，不仅担心即将到来的死亡，更害怕如果以如此狼狈的状态回到森金村，会招致族人的嘲笑。",al={"林纳格背景故事","林纳格是谁","巨魔林纳格"}},{q="为什么考格汉在大断崖？",a="考格汉住在大断崖，这是奥格瑞玛地下的阴暗洞穴，术士、潜行者和其他黑魔法修行者都在这里避开萨尔荣誉卫士的目光进行活动。他对毒药配方和残酷试炼的理解与大断崖的地下环境非常契合。",al={"考格汉在哪里","谁是考格汉","考格汉位置"}},{q="为什么林纳格不直接去森金村找萨满或治疗者？",a="林纳格承认是自己的自尊心在作祟。他担心以如此大意且身中剧毒的状态回到森金村只会遭到同族巨魔的嘲笑，因此更愿意从考格汉那里寻求隐秘的治疗。",al={"为什么不去森金村","林纳格为何避开森金村"}},{q="林纳格服下解药后会发生什么？",a="林纳格喝下解药后恢复了健康，但他的麻烦并未就此结束。以他对考格汉的了解，这位施药者会要求林纳格通过更艰苦的试炼——猎杀野猪并收集蝎尾——以此来证明自己，直到他完全获得这位修行者的认可。",al={"林纳格活下来了吗","林纳格的后续"}},{q="林纳格在哪里？",a="他位于杜隆塔尔西北部崎岖的峭壁上，靠近通往西方贫瘠之地的边境关口附近。",al={"林纳格位置","林纳格在哪里"}},{q="为什么这剂解药这么紧急？",a="尾蝎的毒素极其猛烈，受害者若不及时治疗，不到一小时内毒素就会蔓延至重要器官，导致死亡。",al={"为什么会有时间限制","林纳格中毒倒计时"}}},fp="15,218,17.239.0,22.216.0,14.215.0,39.260.0,67.197.0,48.222.1,26.121.0,47.113.0"}
P.entries["quest:813"] = {n="寻找解毒剂",s="“寻找解药”是一项为了在奥格瑞玛的考格汉而进行的紧急任务，目的是为中毒的猎人林纳格酿制解药。由于必须在毒液致命前完成，冒险者必须在城墙外从蝎尾毒虫身上收集蝎尾毒囊。这突显了杜隆塔尔野生动物的残酷本性以及野外生存准备的必要性。",h="“寻找解药”是一项为了在奥格瑞玛的考格汉而进行的紧急任务，目的是为中毒的猎人林纳格酿制解药。由于必须在毒液致命前完成，冒险者必须在城墙外从蝎尾毒虫身上收集蝎尾毒囊。这突显了杜隆塔尔野生动物的残酷本性以及野外生存准备的必要...",kw={"解药","杜隆塔尔","考格汉","奥格瑞玛","毒液","林纳格","蝎尾毒虫"},ang={["class:Hunter"]="考格汉对所有猎人提出了严厉的提醒：了解野兽的毒液并携带适当的药物与你的弓箭和追踪技能一样至关重要。",["faction:Horde"]="杜隆塔尔的部落照顾着自己的人民，确保边境上孤立的游侠和侦察兵可以依靠奥格瑞玛的堡垒获得援助。",["race:Orc"]="在杜隆塔尔的生存考验着新定居的兽人的耐力，这表明即使是经验丰富的侦察兵，如果粗心大意，也可能倒在当地的危险之下。"},sec={{t="与毒液赛跑",b="在杜隆塔尔各地狩猎时，一名名叫林纳格的暗矛巨魔犯了一个危险的错误：在没有携带解药的情况下与当地的蝎尾毒虫交战。他被蜇伤并迅速屈服于它们强效的毒素之下，被迫求援。这项任务落在了居住在奥格瑞玛的经验丰富的猎人考格汉身上，他必须在毒素发作前调配出修复药剂。"},{t="制作解药",b="制作解药需要采集痛苦的源头：潜伏在奥格瑞玛大门外的成熟蝎尾毒虫的毒囊。考格汉指出，现在不是责备林纳格缺乏准备的时候，因为每一刻都至关重要。一旦迅速取回毒囊并带回城里，考格汉就会合成药剂，以便能立刻送往垂死的猎人手中。"}},faq={{q="林纳格是谁？",a="林纳格是杜隆塔尔的一名暗矛巨魔猎人，他在追踪野兽时被当地的蝎尾毒虫严重蜇伤。由于在野外缺乏解药，他丧失了行动能力，只能依靠信使从奥格瑞玛取回药物，以免死于中毒。",al={"林纳格背景故事","谁中毒了","谁需要解药"}},{q="考格汉是谁？",a="考格汉是一位经验丰富的暗矛巨魔猎人，常驻于奥格瑞玛的暗影裂口。他深谙杜隆塔尔的野生动物，并拥有使用原始蝎尾毒虫毒囊酿制有效解毒剂所需的炼金知识。",al={"考格汉","考格汉是谁","考格汉 奥格瑞玛"}},{q="所需的毒囊来自哪里？",a="毒囊直接从在奥格瑞玛入口附近多岩石的干旱地面上游荡的蝎尾毒虫身上采集。",al={"蝎尾毒虫在哪里","毒囊位置","蝎尾毒虫毒囊"}},{q="为什么这个任务有时间限制？",a="紧迫性源于林纳格在野外恶化的健康状况。由于蝎尾毒虫的毒素极其猛烈且作用迅速，考格汉必须在猎人因全身中毒而死亡前收到原料并蒸馏出解药。",al={"为什么有计时","治愈的需求计时","限时任务"}},{q="考格汉在这次狩猎中强调了什么教训？",a="考格汉警告说，每一位猎人在与猎物交战前，都必须仔细研究它们的习性和致命危险。在没有做好充分准备或没有应对措施的情况下进入荒野，是一个很容易让战士付出生命代价的疏忽。",al={"考格汉的教训","狩猎教训","考格汉的建议"}},{q="这个任务如何与“治愈的需求”相衔接？",a="“治愈的需求”是引发紧急情况并启动计时的基础差事。“寻找解药”是中间步骤，玩家在此收集原始成分，供考格汉酿制成品药剂。",al={"治愈的需求关联","前置任务","它如何衔接"}}},fp="20,262,24.232.0,17.282.0,14.180.0,16.164.0,43.114.0,47.160.0,53.181.0,46.202.0"}
P.entries["quest:815"] = {n="恐龙蛋大餐",s="“打碎几个蛋”是一项跑腿任务，旨在协助一位忙得不可开交的厨师，他必须跟上无休止的餐点准备工作。搜集新鲜且易碎的食材而不将其弄碎，是维持厨房正常运转和烹饪进度按时进行的关键。",h="“打碎几个蛋”是一项跑腿任务，旨在协助一位忙得不可开交的厨师，他必须跟上无休止的餐点准备工作。搜集新鲜且易碎的食材而不将其弄碎，是维持厨房正常运转和烹饪进度按时进行的关键。",kw={"打碎几个蛋","早餐","厨师","烹饪","蛋","厨房","餐点"},ang={["profession:Cooking"]="每一位在职的厨师都知道让人们吃饱饭所带来的巨大压力。在任何厨房里，搜集易碎食材而不把它们打碎，这本身就是挑战的一半。"},sec={{t="无休止的餐点",b="供养一群人是一项精疲力竭、永无止境的工作。在早餐、午餐和晚餐之间，几乎没有时间离开炉灶，更不用说离开厨房去寻找原材料了。在“打碎几个蛋”中，一位焦头烂额的厨师求助于路过的冒险者，请他们赶在下一顿餐点服务延误之前找来新鲜的蛋。"},{t="厨师的感激",b="运输蛋需要一种蛮力无法替代的轻柔触碰。厨师可能会出言不逊，很少给予夸奖，但完好无损的食材本身就是最好的证明。一旦蛋被安全地送达且没有碎裂，厨师就会立刻打发采集者离开，直接回到火炉前继续工作。"}},faq={{q="“打碎几个蛋”是什么任务？",a="“打碎几个蛋”是一项烹饪任务，冒险者在此协助一位忙碌的厨师，他被准备餐点的持续需求压得喘不过气来。这项任务包括将蛋完好无损地送到，以确保烹饪进度不会滞后。",al={"打碎几个蛋任务","什么是打碎几个蛋","蛋任务"}},{q="“打碎几个蛋”里的厨师是谁？",a="这位厨师是杜隆塔尔剃刀岭的厨师托尔卡，他全天候都在准备餐点。虽然态度生硬且匆忙，但托尔卡依靠能干的帮手从回音群岛取回断尾龙虾的蛋，并确保在开饭前不把它们弄碎。",al={"谁发布打碎几个蛋","蛋任务厨师","谁在做饭"}},{q="厨师为什么需要蛋？",a="厨师需要它们进行持续的餐点准备，无论是早餐、午餐还是晚餐。供养人们是一项无休止的琐事，而新鲜的蛋是炉灶上迫切需要的厨房必需品。",al={"为什么需要蛋","蛋有什么用"}},{q="为什么厨师会评论说不要笨手笨脚？",a="蛋很脆弱，在运输过程中很容易损坏。厨师明确表示看重那些不笨手笨脚的人，因为蛋壳碎裂和蛋黄流失会毁掉餐点服务所需的食材。",al={"为什么拿蛋要小心","不要打破蛋","为什么不要笨手笨脚"}},{q="任务标题“打碎几个蛋”是指什么？",a="这个名字引用了一句常见的谚语：不打碎几个蛋就做不成煎蛋卷。这非常符合这项为繁忙的餐点服务收集易碎厨房食材的任务。",al={"打碎几个蛋含义","短语含义","为什么叫打碎几个蛋"}},{q="为什么厨师这么不耐烦？",a="厨师忙于应付早餐、午餐和晚餐的连轴转，根本没有时间停歇。还有这么多烹饪工作要做，厨师对闲聊毫无耐心，只想赶快回到炉灶前。",al={"厨师态度","为什么厨师很粗鲁","脾气暴躁的厨师"}}},fp="16,147,13.350.0,18.256.0,35.121.0,36.209.0,28.139.0,46.105.0,46.139.0,29.163.0"}
P.entries["quest:816"] = {n="丢失的孩子",s="“失踪但未被遗忘”是一个由米莎·托克伦发布的忧伤任务，她的家园位于剃刀岭西北方。为了寻求一个了结，她恳求旅者在危机四伏的怒水河岸搜寻她那倔强的儿子克鲁恩的下落。",h="“失踪但未被遗忘”是一个由米莎·托克伦发布的忧伤任务，她的家园位于剃刀岭西北方。为了寻求一个了结，她恳求旅者在危机四伏的怒水河岸搜寻她那倔强的儿子克鲁恩的下落。",kw={"护身符","鳄鱼","恐鳄","克鲁恩","米沙","剃刀岭","怒水河","托克伦"},ang={["class:Hunter"]="对于猎人来说，克鲁恩是一个警示故事，讲述了一名未能评估猎物凶猛程度的追踪者最终成为了它们的盘中餐。",["faction:Horde"]="杜隆塔尔早期的生活艰苦而严酷，平凡的家庭必须在无情的荒野和在其边界徘徊的致命掠食者之间挣扎求生。",["race:Orc"]="克鲁恩的命运是一个悲剧性的提醒：虽然自尊和尚武荣耀是兽人文化的核心，但缺乏对危险野兽的敬畏的鲁莽傲慢只会导致毫无英雄气概的死亡。"},sec={{t="母亲的恐惧",b="在剃刀岭西北方，隐匿于杜隆塔尔干旱的红色荒原之中，坐落着简朴的托克伦农场。米莎·托克伦住在这里，这是一位被悲伤和焦虑所麻痹的兽人母亲。几天前，她的儿子克鲁恩声称他要前往西边靠近贫瘠之地边界的怒水河，去猎杀河中凶猛的鳄鱼。尽管她警告过那些致命的野兽，但克鲁恩倔强的自尊心驱使他冲了出去，想要证明自己的勇气。从那以后，他就再也没有出现过。"},{t="残酷的确认",b="米莎请求路过的探险者仔细搜寻怒水河岸，寻找任何关于克鲁恩命运的线索，甚至建议他们去搜查那些鳄鱼的肚子。悲剧的是，她最坏的预感成真了。在水边屠宰凶恶的巨齿鳄鱼时，可以发现克鲁恩被吞下的护身符。将这件遗物带回给米莎虽然熄灭了她儿子幸存的最后希望，但终于让这位悲痛的母亲得到了她开始哀悼所需的结果。"}},faq={{q="谁是米莎·托克伦？",a="米莎·托克伦是一位兽人农场母亲，居住在杜隆塔尔剃刀岭西北方的一处偏僻家园。她饱受悲伤和忧虑的折磨，请求流浪者们搜寻她失踪的儿子克鲁恩的下落。",al={"米莎·托克伦","谁发布失踪但未被遗忘任务","克鲁恩的母亲"}},{q="克鲁恩是谁？",a="克鲁恩是米莎·托克伦那倔强的儿子。为了证明自己的力量，他无视了母亲的警告，离开家去怒水河附近猎杀危险的鳄鱼，并在那里遭遇了不测。",al={"谁是克鲁恩","克鲁恩发生了什么","米莎的儿子"}},{q="克鲁恩是在哪里失踪的？",a="克鲁恩向西穿过杜隆塔尔，前往贫瘠之地的边界，在怒水河岸进行狩猎时失踪的。",al={"克鲁恩在哪里","去哪里寻找克鲁恩","克鲁恩的位置"}},{q="你如何向米莎证明克鲁恩的命运？",a="你在徘徊于怒水河水域的恐齿鳄鱼遗骸中找到了克鲁恩被吞下的护身符。将这件找回的传家宝带回给米莎就确认了他的死亡。",al={"克鲁恩的护身符","克鲁恩命运的线索","鳄鱼的肚子"}},{q="米莎会给予什么奖励？",a="米莎把她原本准备给克鲁恩庆祝狩猎凯旋的礼物送给了你。在得知他的死讯后，她无法忍受再看这件东西，于是把它转交给了带给她结果的探险者。",al={"失踪但未被遗忘奖励","米莎的礼物"}},{q="克鲁恩当初为什么要离开？",a="克鲁恩的离去源于他倔强的自尊心和想要证明自己狩猎本领的渴望。当他的母亲警告他这些鳄鱼太过凶恶危险时，他大发雷霆，执意冲出去进行狩猎。",al={"克鲁恩为什么要打猎","克鲁恩的自尊"}}},fp="22,156,16.286.0,19.323.1,22.177.0,13.150.1,26.104.0,38.141.1,28.201.1,38.172.0"}
P.entries["quest:817"] = {n="生活所需的虎皮",s="“实用的猎物”是由森金村的制皮师维尔林·长牙发布的一项狩猎任务。面对不断增长的人口和日渐枯竭的库存，暗矛巨魔必须从邻近的回音群岛采集耐用的虎皮，以制作必要的住所、衣物和装备。",h="“实用的猎物”是由森金村的制皮师维尔林·长牙发布的一项狩猎任务。面对不断增长的人口和日渐枯竭的库存，暗矛巨魔必须从邻近的回音群岛采集耐用的虎皮，以制作必要的住所、衣物和装备。",kw={"暗矛","杜隆塔尔猛虎","回音群岛","狩猎","制皮","实用的猎物","森金村","虎皮","维尔林·长牙"},ang={["class:Hunter"]="维尔林讲述的关于在出击前坚持静默追踪一整天的故事，正是暗矛巨魔教导所有年轻猎手耐心与精准这些核心美德的直接体现。",["faction:Horde"]="支持这处暗矛巨魔的新生飞地，并提供必要的贸易物资，有助于稳固部落在无尽之海沿岸的南方侧翼。",["race:Troll"]="对于流亡的暗矛巨魔来说，前往回音群岛狩猎是一种苦涩的提醒，让他们想起失去的家园，在那里，为了供养族人，他们必须踏上被扎拉赞窃取的土地。"},sec={{t="生存之道",b="杜隆塔尔干旱海岸上的生活十分艰苦，流亡到森金村的暗矛巨魔必须充分利用每一份资源。虎皮是现有的用途最广泛的材料之一，是缝制帐篷、厚毯子和加固护甲的必需品。随着定居点里难民和归来斥候人数的增加，储备物资已经捉襟见肘，迫使像维尔林·长牙这样的工匠不得不委托进行新的狩猎。"},{t="平衡与狩猎",b="暗矛巨魔与他们领地内的掠食者保持着一种审慎的关系。巨魔通常不会过度狩猎杜隆塔尔本土的猛虎，而是任由这些徘徊者自由繁衍，只在部落物资需要补充时才会进行捕杀。冒险渡水前往回音群岛去跟踪这些掠食者，既是出于实际需要，也是对耐心、纪律和野外生存技巧的一种传统考验。"}},faq={{q="谁是维尔林·长牙？",a="维尔林·长牙是一位在森金村工作的暗矛巨魔工匠，专门处理兽皮和皮革。他负责引导猎手采集必要的毛皮，以保障部落的衣物、住所和装备供应。",al={"维尔林·长牙","谁发布了实用的猎物"}},{q="为什么森金村需要虎皮？",a="森金村不断增长的人口已经让现有的储备不堪重负。虎皮可以提供耐用的材料，制作保暖的毯子、结实的帐篷以及皮革护甲，以保护村民免受恶劣环境的侵袭。",al={"为什么需要虎皮","实用的猎物目标","毛皮的用途"}},{q="杜隆塔尔的猛虎在哪里可以找到？",a="这些猛虎在回音群岛的荒野中徘徊，该群岛位于杜隆塔尔东南部海岸外。",al={"老虎在哪里","老虎位置","回音群岛的老虎"}},{q="为什么巨魔不捕杀附近所有的老虎？",a="维尔林解释说，暗矛巨魔特意在自身需求与当地生态之间保持平衡。他们让掠食者繁衍壮大以保持种群的可持续性，只在村庄的物资需求超过储备时才会介入进行捕杀。",al={"为什么要让老虎繁衍","捕杀"}},{q="狩猎老虎对暗矛巨魔的文化重要吗？",a="是的。跟踪老虎被视为一种考验耐心和狡黠的仪式。维尔林曾深情地讲述过他在回音群岛的枝叶间一动不动地等待了近一天时间，才最终完成了他第一次重大狩猎胜利的故事。",al={"狩虎传统","第一次狩虎"}},{q="如果回音群岛被扎拉赞控制，为什么猎手们必须前往那里？",a="虽然叛变的巫医扎拉赞和他被施了巫术的爪牙占据了群岛的大部分地区，但岛上的野生猛兽依然繁多。在群岛外围海岸进行搜寻和狩猎，对暗矛巨魔来说依然是一项必要的冒险。",al={"回音群岛的老虎","为什么去回音群岛"}}},fp="14,137,20.267.0,20.236.0,20.144.0,41.131.0,35.79.0,48.138.0,51.171.0,65.182.0"}
P.entries["quest:818"] = {n="沃纳尔大师",s="森金村的沃纳尔大师通过索要试剂来测试初出茅庐的冒险者，以弥补他日益衰退的视力。他会派遣未来的学生前往杜隆塔尔沿岸收集龙虾人的眼睛和甲壳虫的粘液。虽然他对收徒弟的想法嗤之以鼻，但这项任务实际上是对耐心和决心的刻意考验。",h="森金村的沃纳尔大师通过索要试剂来测试初出茅庐的冒险者，以弥补他日益衰退的视力。他会派遣未来的学生前往杜隆塔尔沿岸收集龙虾人的眼睛和甲壳虫的粘液。虽然他对收徒弟的想法嗤之以鼻，但这项任务实际上是对耐心和决心的刻意考验。",kw={"炼金术","甲壳虫粘液","暗矛海滩","杜隆塔尔","完好的龙虾人眼睛","龙虾人","沃纳尔大师","森金村"},ang={["faction:Horde"]="杜隆塔尔海岸对初出茅庐的部落来说依然危机四伏；清理具有攻击性的龙虾人和冲浪甲壳虫可以保障森金村周围渔场的安全。",["race:Orc"]="沃纳尔公开怀疑兽人是否具备炼金术所需的安静纪律，这使得这项任务成为了证明部落团结可以延伸至学术耐心的机会。",["race:Troll"]="对于在森金村重建的暗矛部族来说，向沃纳尔大师这样的长者证明自己，对于传承部落的神秘和炼金传统至关重要。"},sec={{t="大师衰退的视力",b="沃纳尔大师坐在森金村里，背负着岁月的沉重和日益模糊的视力。曾经信手拈来的原始魔法，如今他不得不更多地依赖炼金术来强化感知并编织法术。尽管身体状况每况愈下，这位固执的巨魔却拒绝收徒，声称暗矛部族和杜隆塔尔的兽人中还没出现过有资格接受他教导的人。"},{t="考验未受证明者",b="沃纳尔并不进行直接的教导，而是要求从严酷的海岸线获取原材料：完好的龙虾人眼睛和甲壳虫粘液瓶。从披甲且善于夹击的龙虾人身上获取未受损的眼睛需要精准的打击，而收集足够的粘液则是对冒险者是否愿意忍受枯燥杂务的考验。在沃纳尔看来，狩猎这些沿海野兽与其说是为了试剂，不如说是为了剔除那些缺乏专注力的人。"},{t="意志的衡量",b="对于沃纳尔大师来说，时间和耐心是衡量强度的终极标准。他预料鲁莽的年轻人会因挫折而放弃，或者彻底抛弃这项苦差事。带着纯净的原料回到森金村，不仅证明了在回音群岛海峡危险礁石区的生存技能，也证明了掌握炼金术微妙艺术所必需的纪律。"}},faq={{q="沃纳尔大师是谁？",a="沃纳尔大师是一位居住在森金村的老年巨魔炼金术士和施法者。随着年龄的增长，他的视力正在衰退，这迫使他不得不转而依靠炼金溶剂和药剂来施展曾经轻而易举的魔法。",al={"沃纳尔大师","沃纳尔是谁","沃纳尔背景故事"}},{q="为什么沃纳尔需要龙虾人的眼睛和甲壳虫粘液？",a="沃纳尔依靠炼金合剂来辅助他的魔法，并弥补他衰退的视力。粘液和完好的龙虾人眼睛既是他的药剂试剂，也充当了对他未来学徒的入门测试。",al={"为什么需要甲壳虫粘液","为什么需要龙虾人眼睛","沃纳尔制造什么"}},{q="为什么沃纳尔如此不愿收徒？",a="沃纳尔有着极高的标准，对傲慢毫无容忍度。他认为没有哪个巨魔或兽人展现出了向他学习所需的真正奉献精神和耐心，他眼中的大多数求学者都过于自负且容易气馁。",al={"沃纳尔学徒","为什么不收学徒","沃纳尔在找学生吗"}},{q="这些生物在森金村附近哪里可以找到？",a="甲壳虫和龙虾人在暗矛海滩沿岸的浅滩游荡，并栖息在离岸将大陆与回音群岛隔开的水道中。",al={"龙虾人在哪里","甲壳虫在哪里","暗矛海滩野兽"}},{q="为什么龙虾人的眼睛需要完好无损？",a="用于强化感知的炼金药剂需要未受损的感觉器官。战斗中的蛮力打击有压碎龙虾人脆弱眼睛的风险，因此需要狩猎者具备精准度和克制力。",al={"完好的眼睛","完好的龙虾人眼睛","为什么需要完好的眼睛"}},{q="沃纳尔试图传授什么课程？",a="沃纳尔认为耐心是品格的真正试金石。通过布置在岸边重复且肮脏的采集任务，他旨在观察新手是会屈服于软弱和急躁，还是能保持炼金术士那种冷静的专注。",al={"沃纳尔的教导","任务的意义","耐心测试"}}},fp="16,194,23.343.0,20.348.0,17.315.0,21.196.0,52.200.0,50.212.0,55.127.0,42.180.0,38.161.0"}
P.entries["quest:819"] = {n="老陈的空酒桶",s="在贫瘠之地的荒野中，遗落着一只刻有陈·风暴烈酒名字的空酒桶。找到它将开启一段旅程，追溯这位著名的游历酿酒师往日的功绩，他曾为杜隆塔尔的建立贡献了自己的战斗技艺。",h="在贫瘠之地的荒野中，遗落着一只刻有陈·风暴烈酒名字的空酒桶。找到它将开启一段旅程，追溯这位著名的游历酿酒师往日的功绩，他曾为杜隆塔尔的建立贡献了自己的战斗技艺。",kw={"贫瘠之地","酿酒","酿酒师德罗恩","陈·风暴烈酒","空酒桶","熊猫人","棘齿城","雷克萨"},ang={["faction:Horde"]="陈·风暴烈酒被铭记为一位受人尊敬的盟友，他曾与雷克萨和洛克汗并肩作战，建立杜隆塔尔，并在部落最初的日子里保卫了它。",["profession:Cooking"]="这只酒桶代表了一位技艺精湛的酿酒师的传承，他那传奇般的品味和对稀有原料的追求激励了整个卡利姆多的工匠。"},sec={{t="一件游历者的遗物",b="在贫瘠之地那片干旱广袤的土地上，旅人们偶尔会发现一只被遗弃的木桶。不同于剃刀鬃毛野猪人或科卡尔半人马留下的常见货色，这只木桶制作精良，上面还刻有一块独特的铭牌：“陈·风暴烈酒——愿你的灵魂得到升华，也愿你永远兴致高昂。”在卡利姆多的烈日炙烤下，这真是一件不同寻常的遗物，促使任何好奇心旺盛的人去寻找一位精通酿酒之道的人，以了解它为何会出现在这里。"},{t="杜隆塔尔奠基的回响",b="将这只木桶带给棘齿城的酿酒师德罗恩，就能揭开它的起源。德罗恩一眼就认出了这精湛的工艺：它属于陈·风暴烈酒，那位在萨尔的部落确保杜隆塔尔安全的关键战役中与雷克萨并肩作战的传奇熊猫人游历者。尽管陈行走在卡利姆多红土地上的日子已过去多年，但他那传奇的酿酒配方和游历精神在艾泽拉斯的资深酿酒师心中依然记忆犹新。"}},faq={{q="什么是陈的空酒桶？",a="它是在贫瘠之地发现的一只废弃酿酒桶。上面刻有题词，将其献给游历的熊猫人酿酒师，陈·风暴烈酒。",al={"空酒桶","陈的酒桶","这个木桶是什么"}},{q="陈·风暴烈酒是谁？",a="陈·风暴烈酒是一位行踪不定的熊猫人酿酒师，他曾广泛游历卡利姆多。他最出名的事迹是在杜隆塔尔的防御和早期建设过程中协助半食人魔兽王雷克萨。",al={"谁是陈","陈的背景故事","熊猫人酿酒师"}},{q="我应该把这只酒桶交给谁？",a="这只酒桶可以交给酿酒师德罗恩，他是一位驻扎在棘齿城附近路边的兽人酿酒师，认得陈的标记，也知道如何重现他的配方。",al={"酒桶交给谁","谁想要陈的酒桶","酒桶交付"}},{q="为什么陈的酒桶会丢在贫瘠之地？",a="多年前，陈曾游历卡利姆多，为他的佳酿寻找奇异的原料，特别是在他帮助新兴的部落保卫新家园、抵御普罗德摩尔上将的军队时。",al={"为什么酒桶在贫瘠之地","酒桶是怎么到这里的"}},{q="陈·风暴烈酒会亲自出现吗？",a="不。陈已经离开了该地区，很久没有在卡利姆多露面了。留下的只有他旧时的木桶、配方，以及像德罗恩和雷克萨这样的盟友对他的美好回忆。",al={"我能找到陈吗","陈·风暴烈酒在哪里","陈在经典旧世里吗"}},{q="酿酒师德罗恩会用这只酒桶做什么？",a="德罗恩看到这件遗物非常兴奋，并借此机会向冒险的游历者发起挑战，收集当地野兽的原料，以便他能重现陈那烈性十足的传奇佳酿。",al={"德罗恩任务线","酒桶后续"}}},fp="16,124,17.383.0,28.343.0,25.129.0,23.172.0,29.153.0,43.172.0,38.167.0,43.163.0"}
P.entries["quest:8193"] = {n="Master Angler",s="每逢星期日，都会举行钓鱼大赛，选出最出色的钓手。率先带来荆棘谷海岸鱼群中的Tastyfish，前五十名可获Master Angler称号。",h="每逢星期日，都会举行钓鱼大赛，选出最出色的钓手。率先带来荆棘谷海岸鱼群中的Tastyfish，前五十名可获Master Angler称号。",kw={"钓鱼大赛","钓鱼","鱼群","master angler","荆棘谷","星期日","tastyfish"},sec={{t="周日大赛",b="大赛每逢星期日举行。率先将Tastyfish交给组织者的前五十名钓手，可获得Master Angler称号。Tastyfish来自荆棘谷沿岸的鱼群，而且很快就会变质。"},{t="另一种报酬",b="如果你来晚了，没能排进前五十名，组织者的学徒仍会收购你的Tastyfish。这些鱼无法保存到下个星期日。"}},faq={{q="钓鱼大赛什么时候举行？",a="大赛每逢星期日举行。",al={"master angler 日期","钓鱼大赛是哪天"}},{q="在哪里能找到Tastyfish？",a="荆棘谷沿岸的鱼群中可以钓到Tastyfish。",al={"tastyfish 位置","哪里有tastyfish"}},{q="怎样才能成为Master Angler？",a="在前五十名之内，将Tastyfish交给大赛组织者。",al={"master angler 条件","赢得钓鱼大赛"}},{q="如果我来晚了怎么办？",a="如果你来晚了，没能排进前五十名，组织者的学徒会收购你的Tastyfish。",al={"错过大赛","钓鱼太慢"}},{q="我能把Tastyfish留到下周吗？",a="不能。Tastyfish很快就会变质，无法保存到下个星期日。",al={"tastyfish 会变质吗","鱼能留到星期日吗"}}},fp="13,169,18.231.0,14.157.0,28.37.0,26.62.0,32.70.0,26.104.0,35.73.0"}
P.entries["quest:82"] = {n="腐化之巢",s="高级勘探员菲兹杜瑟想要弄清楚敌人到底是什么。虫子们一直在抽干腐化之巢所在的水池，关于它们的资料少之又少。你被要求从腐化之巢的蜈蚣身上收集五份虫壳，并将它们交给加基森的炼金师匹斯特苏格。",h="高级勘探员菲兹杜瑟想要弄清楚敌人到底是什么。虫子们一直在抽干腐化之巢所在的水池，关于它们的资料少之又少。你被要求从腐化之巢的蜈蚣身上收集五份虫壳，并将它们交给加基森的炼金师匹斯特苏格。",kw={"蜈蚣","菲兹杜瑟","加基森","昆虫","腐化之巢","匹斯特苏格","塔纳利斯"},sec={{t="来自巢穴的碎片",b="在完成加基森水质调查之后，高级勘探员菲兹杜瑟开始关注关于那些虫子的报告。目前已知的信息很少，只知道它们正在抽干曾经位于腐化之巢所在地的水池。菲兹杜瑟想先搞清楚敌人是谁，所以他请求你进入巢穴，从那里的蜈蚣身上收集五份样本，并将它们带回加基森交给炼金师匹斯特苏格进行检验。"},{t="匹斯特苏格的发现",b="匹斯特苏格立刻开始研究这些样本，并断言它们与之前见过的任何昆虫形态都不匹配，看起来就像是有某种外部力量在控制着这些虫子。随后，匹斯特苏格让你回去找菲兹杜瑟，因为有一个紧急情况需要你的帮助，这可能涉及塔纳利斯更多的虫子。"}},faq={{q="为什么高级勘探员菲兹杜瑟需要虫子样本？",a="虫子们正在抽干腐化之巢曾经所在的水池，人们对它们知之甚少。收集蜈蚣的碎片是为了帮助匹斯特苏格研究它们到底是什么。",al={"为什么收集虫子碎片","菲兹杜瑟 昆虫样本","腐化之巢的目的"}},{q="蜈蚣在哪里可以找到？",a="蜈蚣位于腐化之巢，也就是曾经的水池所在地。",al={"腐化之巢在哪里","蜈蚣位置","哪里能找到蜈蚣"}},{q="在加基森是谁负责接收这些虫子样本？",a="加基森的炼金师匹斯特苏格，他将对样本进行检验。",al={"向谁交付任务","匹斯特苏格位置","谁需要虫子样本"}},{q="这一步之前是什么？",a="它是加基森水质调查的后续任务。",al={"前置任务","任务前提","引导任务"}}},fp="26,219,19.364.0,21.280.1,56.176.0,30.72.0,43.76.0,28.38.0"}
P.entries["quest:821"] = {n="老陈的空酒桶",s="这个任务延续了贫瘠之地中熊猫人酿酒的传奇血统。棘齿城的酿酒师德罗恩提出，只要你从游荡在草原上的野生野兽身上收集野外原料，他就愿意为你重现老陈那久负盛名的烈性佳酿。",h="这个任务延续了贫瘠之地中熊猫人酿酒的传奇血统。棘齿城的酿酒师德罗恩提出，只要你从游荡在草原上的野生野兽身上收集野外原料，他就愿意为你重现老陈那久负盛名的烈性佳酿。",kw={"酿酒师德罗恩","老陈","酒桶","平原陆行鸟的肾脏","棘齿城","草原狮的獠牙","贫瘠之地","雷霆蜥蜴的角","穴居人啤酒"},ang={["faction:Horde"]="老陈曾与雷克萨并肩作战，帮助建立了杜隆塔尔，这使得他旅途中的任何遗留物都对部落有着特殊的文化共鸣。",["profession:Cooking"]="烹饪冒险家们会欣赏边境屠宰与精湛酿造之间那种大胆——尽管有些令人不安——的结合，正是这种结合打造出了传奇的卡利姆多烈酒。",["race:Orc"]="德罗恩体现了兽人是如何拥抱那些直接从曾与早期部落一同在这片土地上行走的旅行者那里传下来的古老酿酒师传统的。"},sec={{t="桶中的传奇",b="当一个刻有熊猫人文字的废弃酒桶最终落入棘齿城的酿酒师德罗恩手中时，这唤起了他对那位传奇流浪者老陈的美好回忆。老陈将他同名佳酿的秘诀传授给了德罗恩的导师，而导师又将其托付给了德罗恩。虽然对非酿酒师来说这很罕见，但这份配方需要直接取自贫瘠之地凶猛野生动物身上的原始且强劲的材料。"},{t="收获草原",b="酿造老陈的烈性酒需要一系列不同寻常的成分：平原陆行鸟的肾脏、草原狮的獠牙，以及雷霆蜥蜴的角。寻找这些物品需要在尘土飞扬的平原上狩猎，这证明了只有最强韧的野兽才能提供真正熊猫人风格酿造所需的劲道。一旦收集齐，德罗恩便会充满怀旧之情，感叹重现这个古老的配方让他胃里感到的温暖，几乎不亚于他过去酿造的穴居人啤酒。"}},faq={{q="酿酒师德罗恩是谁？",a="酿酒师德罗恩是驻扎在棘齿城港口的一名兽人酿酒师。他从一位曾亲自从传奇流浪者老陈那里获得配方的导师身上学到了酿酒艺术。",al={"酿酒师德罗恩","谁是德罗恩","棘齿城的德罗恩"}},{q="为什么啤酒配方需要动物肾脏和角？",a="熊猫人的酿酒传统——以及粗犷的边境酿酒师所做的调整——往往依赖于当地野生动物身上强大而神秘的成分，以便为他们的烈酒注入活力、劲道和独特的自然精华。",al={"为什么需要动物部位","平原陆行鸟肾脏啤酒","狮牙啤酒"}},{q="可以在哪里找到所需的原料？",a="这三种成分都采自贫瘠之地的本土动物。平原陆行鸟和草原狮在开阔的草原上游荡，而雷霆蜥蜴通常可以在平原上更干旱或多岩石的区域找到。",al={"在哪里可以找到獠牙","雷霆蜥蜴在哪里","寻找酿酒原料"}},{q="老陈是谁？",a="老陈是一位流浪的熊猫人酿酒师，他在杜隆塔尔建国期间游历了卡利姆多，在寻找珍稀原料来完善他那烈性啤酒的同时，也为部落提供了帮助。",al={"谁是老陈","老陈的背景故事","老陈"}},{q="把原料带给德罗恩后会发生什么？",a="交出狮牙、平原陆行鸟肾脏和雷霆蜥蜴的角会让德罗恩感到高兴，这提醒了他早期的酿酒岁月，并直接进入了重现那传奇烈酒的最后阶段。",al={"陈的空酒桶之后的下一个任务","德罗恩的奖励","接下来是什么"}},{q="德罗恩提到的穴居人啤酒是什么？",a="看到这些野生原料，德罗恩深情地回忆起了一种早期的混合酒，即穴居人啤酒，这证明了他过去在边境发酵那些口感浓烈、不同寻常的混合酒的古怪历史。",al={"穴居人啤酒","德罗恩的穴居人啤酒"}}},fp="16,109,17.301.0,23.360.1,24.167.0,56.181.0,44.124.0,24.198.0,53.205.0,38.169.0"}
P.entries["quest:822"] = {n="老陈的空酒桶",s="在成功酿造出强力的风暴烈酒之后，位于棘齿城的酿酒师德罗恩提出可以制作另一种从神秘的熊猫人流浪者陈·风暴烈酒那里学到的秘方。这种名为“穴居人麦酒”的烈性混合饮料，需要从贫瘠之地的本土野兽身上获取稀有的器官和腺体。",h="在成功酿造出强力的风暴烈酒之后，位于棘齿城的酿酒师德罗恩提出可以制作另一种从神秘的熊猫人流浪者陈·风暴烈酒那里学到的秘方。这种名为“穴居人麦酒”的烈性混合饮料，需要从贫瘠之地的本土野兽身上获取稀有的器官和腺体。",kw={"贫瘠之地","酿酒师德罗恩","陈·风暴烈酒","陈的空酒桶","科多兽的肝脏","棘齿城","风暴兽","雷鹰","穴居人麦酒"},ang={["faction:Horde"]="陈·风暴烈酒曾在杜隆塔尔保卫战期间与部落并肩作战，给德罗恩等在早期遇到他的兽人们留下了深刻的印象。",["profession:Cooking"]="烹饪纯粹主义者或许会排斥穴居人麦酒，但提取丰富的脏器肉和强力腺体，体现了边境烹饪传统中“猎物绝不浪费”的精髓。",["race:Orc"]="酿酒师德罗恩代表了兽人中少见的职业，他摒弃了传统的战士之路，拥抱了陈的异域酿酒法，并在棘齿城经营着自己的生意。"},sec={{t="第二个熊猫人配方",b="在帮助酿酒师德罗恩复刻了传奇人物陈·风暴烈酒的最初配方后，这位兽人酿酒师透露，那位流浪的熊猫人分享的秘密远不止一个。德罗恩掌握着一种名为“穴居人麦酒”的奇特饮料的配方。与用谷物蒸馏而成的普通烈酒不同，这种奇怪的麦酒完全依赖于从卡利姆多中部最凶猛的野生动物身上搜集而来的强力有机试剂。"},{t="穴居人麦酒的配料",b="为了酿造这种味道浓烈、令人振奋的饮料，德罗恩需要一些雷霆般的成分：风暴兽的闪电腺、巨型雷鹰的雷鹰的唾液腺，以及平原上游荡的科多兽的肝脏。蒸馏后，这种混合物便成为了一种专为在荒野生存而设计的强力刺激饮品。"},{t="持久的合作",b="德罗恩的技艺并不仅限于酿造一批。他意识到穿梭于棘齿城这一中立港口的旅行冒险者和雇佣兵对此有需求，因此他愿意保持长期合作，只要有探险者带来新鲜的兽类器官，他就愿意酿造新的穴居人麦酒。"}},faq={{q="陈·风暴烈酒是谁？",a="陈·风暴烈酒是一位神秘的流浪熊猫人酿酒师，他在杜隆塔尔建立期间游历了卡利姆多。在旅途中，他在棘齿城向德罗恩分享了一些强力的酿酒技术，随后继续了他的流浪之旅。",al={"陈是谁","陈的背景故事","熊猫人陈"}},{q="酿酒师德罗恩在哪里？",a="酿酒师德罗恩居住在棘齿城的中立港口城镇，该城镇位于贫瘠之地的东海岸。他终日沉浸在钻研与陈相遇时学到的奇特酿酒技艺中。",al={"德罗恩位置","酿酒师德罗恩在哪里","德罗恩非玩家角色"}},{q="什么是穴居人麦酒？",a="穴居人麦酒是陈教给德罗恩的一种非传统且强力的混合饮料。它不使用标准的酿酒啤酒花，而是加入了兽类腺体和内脏，这使其具有一种备受硬派冒险者青睐的劲头。",al={"穴居人麦酒","这是什么饮料","德罗恩酿什么"}},{q="去哪里收集闪电腺？",a="闪电腺可以从潜伏在贫瘠之地干旱荒原上的风暴兽身上获取，它们的体内蕴含着天然的电荷。",al={"闪电腺来源","风暴兽位置","去哪里获得闪电腺"}},{q="哪些野兽会掉落雷鹰的唾液腺？",a="这些腺体专门从巨型雷鹰身上采集。巨型雷鹰是掠食性鸟类，体型雄伟，能够施放电击，狩猎于贫瘠之地广阔的天空之上。",al={"雷鹰的唾液腺","巨型雷鹰在哪里","雷鹰位置"}},{q="我可以多次酿造穴居人麦酒吗？",a="可以。只要冒险者为他提供新鲜的腺体和科多兽的肝脏，酿酒师德罗恩就愿意随时调制更多的麦酒。",al={"可以重复吗","我可以再做一次吗","重复穴居人麦酒"}}},fp="16,154,25.261.0,28.252.0,23.181.1,23.209.0,34.145.0,18.176.0,37.133.0,43.124.0,36.104.0"}
P.entries["quest:823"] = {n="向奥戈尼尔报告",s="“向奥戈尼尔报告”是部落早期的一项任务，由森金村的加德林大师派遣。它指引初出茅庐的冒险者向北前往剃刀岭，向奥戈尼尔·魂痕发出警告，告知其火刃氏族邪教那阴险的触角。这次派遣有助于协调杜隆塔尔各地分散的防御力量，对抗在兽人故乡酝酿的恶魔腐蚀。",h="“向奥戈尼尔报告”是部落早期的一项任务，由森金村的加德林大师派遣。它指引初出茅庐的冒险者向北前往剃刀岭，向奥戈尼尔·魂痕发出警告，告知其火刃氏族邪教那阴险的触角。这次派遣有助于协调杜隆塔尔各地分散的防御力量，对抗在兽人故...",kw={"火刃氏族","杜隆塔尔","加德林大师","奥戈尼尔·魂痕","剃刀岭","向奥戈尼尔报告","森金村"},ang={["faction:Horde"]="这项任务标志着新结盟的暗矛巨魔与杜隆塔尔的兽人在面对共同威胁时，进行了至关重要的沟通与合作。",["race:Orc"]="奥戈尼尔·魂痕代表了你新家园的前线防御，确保恶魔的污染不会在杜隆塔尔境内扎根。",["race:Troll"]="尽管暗矛部族正忙于与扎拉赞的战斗，加德林大师仍通过向兽人领导人通报区域性危险，展现了巨魔对部落的忠诚。"},sec={{t="协调防御",b="当森金村正忙于应对自身的当地困境——尤其是回音群岛上扎拉赞的背叛——时，加德林大师意识到有关火刃氏族邪教的报告代表着一种更为广泛的危险。在试炼谷发现了恶魔腐蚀的流言，这位暗矛巫医深知这些威胁不能孤立处理。他派遣远道而来的英雄沿着尘土飞扬的道路向北前往剃刀岭，那里的当地兽人官员负责对杜隆塔尔进行更广泛的监视。"},{t="奥戈尼尔·魂痕",b="奥戈尼尔·魂痕驻扎在剃刀岭的军事营地中，他是一位负责铲除内部邪恶并保卫中部腹地的兽人。当冒险者传达加德林大师的警告时，奥戈尼尔毫不迟疑地整合了来自试炼谷和森金村的报告。他意识到火刃氏族的阴影正危险地逼近，随即迅速动员部队，试图在邪教徒的黑暗仪式动摇这个年轻国家之前将他们瓦解。"}},faq={{q="谁发布了“向奥戈尼尔报告”这个任务？",a="加德林大师，即居住在森金村的暗矛巫医兼精神领袖，会在你协助巨魔解决了当地的初步困难后将此任务交给你。",al={"谁发布向奥戈尼尔报告","在哪里接向奥戈尼尔报告","向奥戈尼尔报告任务发布者"}},{q="奥戈尼尔·魂痕在哪里？",a="奥戈尼尔·魂痕位于剃刀岭，那是位于森金村以北、杜隆塔尔中部的一个防御定居点。",al={"奥戈尼尔·魂痕在哪里","奥戈尼尔·魂痕位置","寻找奥戈尼尔·魂痕"}},{q="为什么加德林大师要派你去剃刀岭？",a="加德林大师意识到在试炼谷及杜隆塔尔周边发现的恶魔邪教活动对所有人构成威胁，而不仅仅是针对巨魔。他指引你去找奥戈尼尔·魂痕，这位兽人负责在该地区执行针对火刃氏族的治安任务。",al={"为什么要向奥戈尼尔报告","为什么要前往剃刀岭","向奥戈尼尔报告的目的"}},{q="任务中提到的火刃氏族是什么？",a="火刃氏族是一个在杜隆塔尔及更广阔区域的阴影中活动的背叛性恶魔崇拜邪教。他们在附近峡谷和洞穴中的秘密存在威胁着新部落的安全与稳定。",al={"谁是火刃氏族","火刃氏族邪教","什么是火刃氏族"}},{q="“向奥戈尼尔报告”之后是什么任务？",a="当你向剃刀岭的奥戈尼尔·魂痕提交报告后，他会立即指派你执行“黑暗风暴”任务，以调查并对抗正在集结的邪教徒威胁。",al={"向奥戈尼尔报告后的下一个任务","向奥戈尼尔报告后续","向奥戈尼尔报告之后是什么"}},{q="在接受此任务之前必须完成什么前置条件？",a="它自然而然地衔接在你通过“向森金村报告”任务抵达森金村之后，将试炼谷早期的发现与更广泛的杜隆塔尔战役联系起来。",al={"向奥戈尼尔报告前置任务","如何解锁向奥戈尼尔报告","向奥戈尼尔报告的前置任务"}}},fp="16,138,21.361.0,15.375.0,37.151.0,33.103.0,46.230.0,49.194.0,36.156.0,64.158.0"}
P.entries["quest:824"] = {n="大地之环的耶努萨克雷",s="这个任务指引部落冒险者将从灰谷的元素生物身上找到的被污染的水球交给大地之环的耶努萨克雷。作为一名致力于元素和谐的萨满祭司，耶努萨克雷试图了解佐拉姆海岸和黑暗深渊内蔓延的腐蚀。研究这个圣物有望制止这种正在毒害该地区水域的非自然枯萎。",h="这个任务指引部落冒险者将从灰谷的元素生物身上找到的被污染的水球交给大地之环的耶努萨克雷。作为一名致力于元素和谐的萨满祭司，耶努萨克雷试图了解佐拉姆海岸和黑暗深渊内蔓延的腐蚀。研究这个圣物有望制止这种正在毒害该地区水域的非...",kw={"被污染的水球","黑暗深渊","大地之环","元素生物","耶努萨克雷","马斯托克·维尔西斯","佐拉姆海岸","佐拉姆加前哨站"},ang={["class:Shaman"]="这项任务直接涉及维护元素平衡的萨满职责。运送被污染的球体有助于大地之环的成员诊断一种危险的精神疾病。",["faction:Horde"]="随着部落在灰谷建立像佐拉姆加前哨站这样的防御营地，挖掘当地元素敌意背后的黑暗起源对于确保海岸线的安全至关重要。",["race:Troll"]="耶努萨克雷展现了暗矛部族深厚的精神智慧，代表大地之环运用他与灵魂的祖传羁绊。"},sec={{t="元素的信使",b="当奇怪且受到污染的元素生物开始在灰谷各处出现时，斥候们注意到了驱动它们的那股非自然力量。在残留物中躺着一颗被污染的水球，这是一个跳动着腐蚀魔法的完整容器。由于知道普通士兵和斥候缺乏诊断这种异常现象所需的精神洞察力，马斯托克·维尔西斯指引部落旅行者去寻找一位拥有深厚古代传说和元素知识的人：耶努萨克雷。"},{t="大地之环的注视",b="耶努萨克雷隶属于大地之环，这是一个致力于维护艾泽拉斯原始力量平衡的萨满教团。当部落军队在佐拉姆海岸沿线守卫边疆时，耶努萨克雷则专注于在附近的黑暗深渊神庙遗迹中溃烂的精神创伤。对他而言，一个从受污染的容器中汲取力量的元素生物不仅仅是一个孤立的威胁，更是一个令人警觉的预兆，表明未知的古老力量正在扭曲自然秩序。"}},faq={{q="耶努萨克雷是谁？",a="耶努萨克雷是一位代表卡利姆多北部大地之环的巨魔萨满祭司。他毕生致力于与元素沟通并进行研究，他驻扎在佐拉姆海岸附近，调查从黑暗深渊升起的黑暗骚乱。",al={"耶努萨克雷是谁","耶努萨克雷背景故事","耶努萨克雷在这里做什么"}},{q="什么是大地之环？",a="大地之环是一个致力于保持艾泽拉斯原始元素和谐的萨满组织。他们钻研古代传说、被遗忘的灵魂和旧日轶事，以修复元素混乱并治愈世界各地的精神腐蚀。",al={"什么是大地之环","大地之环是什么组织","大地之环背景故事"}},{q="在哪里可以找到耶努萨克雷？",a="耶努萨克雷位于灰谷佐拉姆海岸的佐拉姆加前哨站，他在那里研究从附近黑暗深渊升起的元素骚乱。",al={"耶努萨克雷在哪里","耶努萨克雷位置","寻找耶努萨克雷"}},{q="什么是被污染的水球？",a="这个球体是一个魔法导管，强大的水元素通过它引导自己的力量。发现一个被污染且完整的球体表明该地区的黑暗力量正在蓄意扭曲并奴役当地的灵魂。",al={"什么是被污染的水球","被污染的水球背景故事","水球"}},{q="是谁派你去和耶努萨克雷交谈的？",a="马斯托克·维尔西斯，一位驻扎在灰谷的部落军官，在意识到军队无法解读这种奇怪的魔法本质后，指引冒险者将这个被污染的圣物交给耶努萨克雷。",al={"谁开启了这个任务","马斯托克任务"}},{q="耶努萨克雷会怎么处理这个球体？",a="耶努萨克雷会保管这个容器，以便大地之环能够检查其枯萎的本质，希望研究结果能揭示一种净化水域并恢复该地区受困元素平静的方法。",al={"这个球体会怎么样","治愈腐蚀"}}},fp="26,308,28.440.0,28.407.0,22.235.0,25.234.0,34.173.0,33.220.0,35.168.0,35.188.0"}
P.entries["quest:8241"] = {n="炽热助熔剂的补给：铁锭",s="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而开始补充灼热峡谷中日益减少的炽热助熔剂供应。博恩奈特需要炽火龙鳞、铁锭和煤块，而且他有多少要多少。",h="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而开始补充灼热峡谷中日益减少的炽热助熔剂供应。博恩奈特需要炽火龙鳞、铁锭和煤块，而且他有多少要多少。",kw={"煤块","炽热助熔剂","炽火龙鳞","铁锭","大铁匠博恩奈特","通过铁补给恢复炽热助熔剂","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂快用完了，博恩奈特需要炽火龙鳞、铁锭和煤块：两块龙鳞、四块铁锭以及煤块。他有多少要多少。"}},faq={{q="谁需要这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布此任务","博恩奈特 炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两块炽火龙鳞、四块铁锭和一些煤块。",al={"我需要什么物品","炽热助熔剂的材料","博恩奈特上交物品"}},{q="这个任务的前置任务是什么？",a="名为“助熔剂怎么了？”的任务步骤，博恩奈特在这之前给你的任务。",al={"此任务的前置任务","炽热助熔剂的上一个任务","助熔剂怎么了的前置条件"}},{q="博恩奈特为什么需要这些物资？",a="博恩奈特说炽热助熔剂的供应正在减少，他想要补充库存。",al={"为什么要炽热助熔剂","博恩奈特的动机"}}},fp="38,190,17.196.0,25.91.0,35.65.0,30.70.0,36.88.0"}
P.entries["quest:8242"] = {n="炽热助熔剂的补给：重皮",s="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而致力于补充灼热峡谷内日渐减少的炽热助熔剂储备。博恩奈特需要焚火龙鳞、重皮和煤块，并且有多少收多少。",h="在完成“助熔剂怎么了？”之后，大铁匠博恩奈特转而致力于补充灼热峡谷内日渐减少的炽热助熔剂储备。博恩奈特需要焚火龙鳞、重皮和煤块，并且有多少收多少。",kw={"大铁匠博恩奈特","煤块","炽热助熔剂","重皮","焚火龙鳞","灼热峡谷","瑟银兄弟会"},sec={{t="急需炽热助熔剂",b="大铁匠博恩奈特没时间闲聊。炽热助熔剂快用完了，博恩奈特需要焚火龙鳞、重皮和煤块：两片鳞片、十张重皮和一些煤块。博恩奈特有多少就会收多少。"}},faq={{q="谁需要这些物资？",a="位于灼热峡谷的大铁匠博恩奈特，他会亲自接收这些物资。",al={"谁发布此任务","博恩奈特炽热助熔剂","在哪里交任务"}},{q="博恩奈特需要什么材料？",a="两片焚火龙鳞、十张重皮和一些煤块。",al={"我需要什么物品","炽热助熔剂材料","博恩奈特上交物品"}},{q="在这个任务之前有什么前置任务？",a="名为“助熔剂怎么了？”的任务步骤，这是博恩奈特在此之前交给你的任务。",al={"此任务的前置要求","炽热助熔剂的前置任务","助熔剂怎么了的前置条件"}},{q="博恩奈特为什么要这些物资？",a="博恩奈特说炽热助熔剂的储备正在减少，因此需要进行补充。",al={"为什么需要炽热助熔剂","博恩奈特的动机"}}},fp="47,202,17.200.0,25.91.0,35.78.0,30.55.0,36.75.0"}
P.entries["quest:8249"] = {n="垃圾箱",s="在拉文霍德庄园，法拉德对坚固的锁闭容器有着源源不断的需求，以训练公会中冉冉升起的潜行者。由于庄园内部工匠提供的练习锁对于高阶学员来说太过简单，法拉德愿意用特制的飞刀与任何愿意提供真正重垃圾箱的人进行交易。",h="在拉文霍德庄园，法拉德对坚固的锁闭容器有着源源不断的需求，以训练公会中冉冉升起的潜行者。由于庄园内部工匠提供的练习锁对于高阶学员来说太过简单，法拉德愿意用特制的飞刀与任何愿意提供真正重垃圾箱的人进行交易。",kw={"重垃圾箱","希尔斯布莱德","垃圾箱","开锁","偷窃","拉文霍德","法拉德","赞"},ang={["class:Rogue"]="搜集这些重箱子完全依赖于偷窃老练对手的技艺，这使得拉文霍德成为潜行者非法技能的终极集散地。",["faction:Alliance"]="虽然隐藏在洛丹伦的争议领土中，但拉文霍德独立运作，接受来自联盟流浪者的契约，不考虑阵营界限。",["faction:Horde"]="勇敢踏入希尔斯布莱德山脉的部落特工会发现，拉文霍德对阵营忠诚度漠不关心，他们视有用的非法货物高于一切。"},sec={{t="磨砺拉文霍德之爪",b="在希尔斯布莱德丘陵上方群山中隐藏的拉文霍德庄园内，训练从未停止。盗贼大师法拉德负责指导公会特工的训练，非常看重实战开锁的精通程度。虽然赞为新兵提供练习装置，但法拉德认为那种粗糙的工艺完全不适合需要应付野外真实、顽固锁具的资深特工。"},{t="奇怪的开放式安排",b="为了让庄园获得真正的实战开锁装置，法拉德外包了从艾泽拉斯各处危险目标身上偷来的重垃圾箱。虽然只有熟练的盗贼才能从野外的目标身上偷窃这些箱子，但法拉德并不将业务仅限于潜行者。任何人只要送来一批这些锁闭的箱子——即使已经清空了里面的主要贵重物品——都能赢得法拉德的好感，并获得庄园精心制造的致命飞刀，前提是箱子里还要留有一枚代币，以激励学员。"}},faq={{q="为什么法拉德需要这些垃圾箱？",a="拉文霍德的潜行者学徒需要真实的装置来练习开锁。法拉德认为庄园驻地工匠赞制作的练习箱对于初学者以外的任何人来说都太基础了，他们需要从危险的目标身上收集真正的锁箱。",al={"为什么需要垃圾箱","垃圾箱的用途","为什么法拉德想要箱子"}},{q="这个任务在哪里进行？",a="交换地点位于拉文霍德庄园，这是隐藏在希尔斯布莱德丘陵以北山脉中的盗贼公会秘密避难所。",al={"垃圾箱任务地点","法拉德在哪里","拉文霍德位置"}},{q="只有潜行者才能交付这个任务吗？",a="虽然重垃圾箱最初是通过潜行者的偷窃艺术获得的，但法拉德接受任何有能力将其带到庄园的人的交付。",al={"这是潜行者专属任务吗","任何人都可以做垃圾箱任务吗","其他职业垃圾箱任务"}},{q="为什么箱子里必须保留硬币？",a="法拉德坚持每个箱子里都要留几枚硬币，因为即使是训练中的潜行者也需要实实在在的激励和奖励来鞭策他们的开锁训练。",al={"为什么要在箱子里留硬币","箱子里需要有战利品吗","空的垃圾箱"}},{q="拉文霍德提供什么作为交换？",a="法拉德会用公会声望和精心制作的飞刀奖励贡献者，他讽刺地希望这些飞刀能直接扎进某人的心脏。",al={"垃圾箱任务奖励","法拉德给什么","拉文霍德飞刀"}},{q="法拉德抱怨的赞是谁？",a="赞是拉文霍德内部的锁具供应商。法拉德认为赞制作的练习装置太粗糙，只适合最原始的新手，而不是严肃的特工。",al={"赞是谁","赞和拉文霍德","赞的锁具"}}},fp="16,166,30.335.0,28.382.0,37.257.0,32.131.0,35.136.0,52.128.0,39.138.0,39.148.0"}
P.entries["quest:825"] = {n="海底沉船",s="剃刀岭的加索克指挥部落侦察兵去流亡海岸搜寻戴林·普罗德摩尔海军上将舰队的沉船残骸。通过从水下的残骸中回收先进的侏儒的工具，部落希望能够拆解联盟的工程学技术，并将这种技术优势转化为自己的利益。",h="剃刀岭的加索克指挥部落侦察兵去流亡海岸搜寻戴林·普罗德摩尔海军上将舰队的沉船残骸。通过从水下的残骸中回收先进的侏儒的工具，部落希望能够拆解联盟的工程学技术，并将这种技术优势转化为自己的利益。",kw={"杜隆塔尔","加索克","侏儒的工具","普罗德摩尔","剃刀岭","打捞","流亡海岸","提拉加德城堡","残骸"},ang={["faction:Horde"]="加索克将每一片联盟的金属残片视为双重奖赏：既是击败未来入侵的知识，又是帮助建设杜隆塔尔这个新生国家的材料。",["profession:Engineering"]="对于工匠来说，侏儒的工具的回收凸显了联盟机械精度与部落蓬勃发展的工艺产业之间早期的技术摩擦。",["race:Gnome"]="虽然身材矮小，但侏儒在联盟航行的每一个地方都留下了他们的印记；他们精密的装备受到了部落足够的尊重，值得专门进行回收任务。"},sec={{t="舰队的回响",b="当戴林·普罗德摩尔海军上将将库尔提拉斯的海军力量带到卡利姆多时，他的船只挤满了提拉加德城堡附近的海岸线。在他战败后，破碎的船体散落在流亡海岸。虽然幸存的库尔提拉斯人士兵加固了城堡本身，但他们舰队的残骸却破碎地躺在浅滩上，在潮汐下慢慢腐烂。"},{t="侏儒的装置",b="兽人的战争传统上依靠蛮力、钢铁和鲜血，但部落也意识到了联盟的独创性所带来的危险优势。侏儒技术人员曾随远征舰队同行，为联盟的船只配备了复杂的机械和精密齿轮。加索克试图回收这些沉没的工具，以便部落能够解开它们背后的机械原理。"},{t="运往奥格瑞玛",b="这些回收的工具并非要在剃刀岭落满灰尘。加索克安排将它们通过大篷车直接运往奥格瑞玛。通过对侏儒仪器进行逆向工程，部落的工匠和战术家旨在在未来的冲突中更好地应对联盟的装置，同时增强自己新兴的工业。"}},faq={{q="为什么部落要从这些沉船中回收工具？",a="部落想要了解联盟所使用的先进技术。侏儒为人类军队制造精密的机械，通过研究这些工具，部落的战术家可以找到对抗联盟装置的方法，同时为自己的工匠采用有用的机械原理。",al={"为什么要获取侏儒的工具","为什么要打捞沉船","加索克对工具的意图"}},{q="流亡海岸外沉没的是谁的船？",a="这些沉没的船只属于戴林·普罗德摩尔海军上将的库尔提拉斯舰队。在登陆杜隆塔尔的海岸并向萨尔新建立的国家发动战争后，几艘船只在提拉加德城堡以东的海岸线沿线被摧毁。",al={"这些是谁的船","谁在杜隆塔尔摧毁了船只","普罗德摩尔舰队残骸"}},{q="回收的工具在离开剃刀岭后会被运往哪里？",a="加索克会将回收的侏儒的工具通过下一支前往奥格瑞玛的大篷车运走。在那里，工程师和工匠可以彻底研究这些装置，以帮助加强首都的防御和工业。",al={"工具会怎么样","侏儒的工具去哪里","谁获得了打捞物"}},{q="为什么人类的战舰上会有侏儒工具？",a="侏儒是联盟中人类的亲密盟友，经常为海军远征队提供机械专业知识、攻城装备和精密维护工具，以保持作战舰队的正常运转。",al={"为什么侏儒与人类在一起","普罗德摩尔船上的侏儒","联盟的侏儒科技"}},{q="什么是流亡海岸？",a="流亡海岸是杜隆塔尔东部的海岸线，经过提拉加德城堡。它的得名是因为在与普罗德摩尔的远征军战斗后，这里浅水区遍布半沉和沉没的船只。",al={"流亡海岸在哪里","流亡海岸的位置","杜隆塔尔沉船区域"}},{q="这项任务与提拉加德城堡的威胁有什么联系？",a="在对提拉加德城堡的突袭中扫清了库尔提拉斯海军陆战队之后，加索克利用这个机会搜刮了剩余的联盟资源。剥离附近的沉船残骸可以确保在拾荒者或潮汐带走一切之前，部落能从敌人的失败中获利。",al={"提拉加德城堡的联系","战胜背叛者任务链接","为什么在提拉加德之后做这个"}}},fp="21,158,19.294.0,20.317.0,22.254.0,51.247.0,46.219.0,49.182.0,46.159.0,26.186.0,58.246.0"}
P.entries["quest:826"] = {n="扎拉赞恩",s="森金村的加德林大师派遣部落的勇士前往回音群岛，终结巫医扎拉赞恩的背叛。受黑魔法蛊惑而疯狂的扎拉赞恩奴役了自己的族人，并占领了暗矛巨魔原本的家园，迫使他们流亡至杜隆塔尔的海岸。",h="森金村的加德林大师派遣部落的勇士前往回音群岛，终结巫医扎拉赞恩的背叛。受黑魔法蛊惑而疯狂的扎拉赞恩奴役了自己的族人，并占领了暗矛巨魔原本的家园，迫使他们流亡至杜隆塔尔的海岸。",kw={"暗矛","杜隆塔尔","回音群岛","被施法的巨魔","加德林大师","森金村","沃金","巫毒巨魔","扎拉赞恩"},ang={["class:Shaman"]="扎拉赞恩扭曲了巨魔萨满和巫医所修习的灵性技艺与原始力量，将禁锢魔法用于攻击自己的同胞。",["faction:Horde"]="这场冲突代表了年轻部落面临的第一次重大团结考验，证明了来自杜隆塔尔各地的盟友会团结起来，保卫流离失所的暗矛巨魔部落。",["race:Troll"]="对于暗矛巨魔来说，击杀扎拉赞恩是一场极其私人的复仇与职责履行，是对那个窃取了你们民族的真正家园并奴役你们兄弟的叛徒的惩罚。"},sec={{t="群岛上的背叛",b="当暗矛巨魔逃离他们沉没的岛屿家园，跟随萨尔跨越无尽之海后，他们在杜隆塔尔东南海岸外的回音群岛建立了一个定居点。扎拉赞恩，这位部落中受人尊敬且力量强大的巫医，屈服于权力欲望。他利用奴役心智的妖术，控制了许多族人并掀起了一场暴乱。幸存的自由暗矛巨魔在沃金的带领下被驱逐出祖传的营地，被迫在森金村建立了一个临时避难所。"},{t="部落的磨难",b="扎拉赞恩并不满足于仅仅将族人赶走。他在回音群岛最大的岛屿上的山顶堡垒中，不断派突袭队穿过海峡，抓捕更多的暗矛巨魔并将其变成奴隶。那些受害者变成了毫无思想的巫毒奴隶，对部落而言已彻底失去。加德林大师认为这不仅仅是领土的占领，更是一种生存威胁：除非将扎拉赞恩的首级带到长老面前，否则没有任何暗矛巨魔能真正安全。"}},faq={{q="扎拉赞恩是谁？",a="扎拉赞恩曾是暗矛巨魔中一位杰出的巫医。他因对黑暗力量的渴望而堕落，转而攻击同胞，利用控制心智的巫毒术奴役族人，并为自己占领了回音群岛。",al={"扎拉赞恩传说","回音群岛的首领是谁","巫医扎拉赞恩"}},{q="为什么暗矛巨魔会逃离回音群岛？",a="扎拉赞恩在岛上发动了突袭政变，通过邪恶的巫术将兄弟姐妹变成了毫无思想的奴隶。沃金和幸存的自由暗矛巨魔因人数不足无法对抗被施了法的同胞，于是撤退到杜隆塔尔大陆，建立了森金村作为临时避难所。",al={"为什么巨魔在森金村","回音群岛背景故事","巨魔是如何失去回音群岛的"}},{q="在扎拉赞恩控制下的巨魔会怎样？",a="在扎拉赞恩控制下的巨魔，其心智已被强大的妖术完全摧毁。他们完全沦为扎拉赞恩毫无思想的仆从，在岛上巡逻并对大陆发起突袭以捕获更多受害者。加德林大师认为他们对部落而言已彻底沦丧，执行处决是唯一的仁慈。",al={"被施法的巨魔","巫毒巨魔","扎拉赞恩的奴隶能治愈吗"}},{q="扎拉赞恩在哪里？",a="扎拉赞恩将巢穴设在回音群岛链中最大的岛屿上，位于杜隆塔尔南海岸的正东方。他在中央山丘的高峰和下方那一群巨魔小屋之间巡逻。",al={"扎拉赞恩位置","寻找扎拉赞恩","扎拉赞恩在哪里"}},{q="是谁发布了杀死扎拉赞恩的任务？",a="加德林大师，即位于杜隆塔尔南岸森金村的部落长老，会在你完成处理当地威胁的入门任务并从试炼谷来到这里后提供该任务。",al={"谁发布扎拉赞恩的任务","在哪里接扎拉赞恩任务"}},{q="为什么沃金不亲自领导进攻？",a="虽然沃金统领着部落，并在奥格瑞玛与萨尔大酋长一同协调暗矛巨魔的防御工作，但森金村仍由像加德林大师这样的当地长老负责引导。加德林负责协调日常生存，并招募有能力的冒险者反击这位背叛的巫医。",al={"沃金在哪里","为什么沃金不打扎拉赞恩"}}},fp="8,304,21.444.0,17.430.0,16.205.0,42.291.0,52.233.0,26.186.0,37.186.0,46.241.0"}
P.entries["quest:827"] = {n="骷髅石",s="此项任务由隐士玛高兹委派，指引部落冒险者前往位于奥格瑞玛正东方的骷髅石洞穴。该洞穴已被火刃氏族邪教所占据，他们使用痛苦的恶魔装置将自己与黑暗魔法绑定。收缴这些被诅咒的神器可以让玛高兹研究在这个首都家门口出现的邪教动向。",h="此项任务由隐士玛高兹委派，指引部落冒险者前往位于奥格瑞玛正东方的骷髅石洞穴。该洞穴已被火刃氏族邪教所占据，他们使用痛苦的恶魔装置将自己与黑暗魔法绑定。收缴这些被诅咒的神器可以让玛高兹研究在这个首都家门口出现的邪教动向。",kw={"火刃氏族","邪教徒","恶魔","杜隆塔尔","邪能","玛高兹","奥格瑞玛","灼热项圈","骷髅石"},ang={["class:Warlock"]="灼热项圈展示了粗糙但强大的邪能绑定，让黑暗践行者得以一窥该邪教如何将恶魔祭品转化为原始力量。",["faction:Horde"]="一个在奥格瑞玛城墙外滋生的恶魔邪教威胁着年轻部落的核心与安全。",["race:Orc"]="火刃氏族代表了兽人们每天都在努力摆脱的黑暗过去；将他们从杜隆塔尔的岩石中清除出去，不仅关乎生存，也关乎荣誉。"},sec={{t="阴影巢穴",b="骷髅石是位于杜隆塔尔东北部崎岖山丘中的一座险恶洞穴。虽然看似偏僻，但它距离奥格瑞玛大门却近得令人不安。这些洞穴里没有野兽或普通的亡命之徒，而是盘踞着火刃氏族的一个分支——长期以来一直困扰着兽人社会的阴暗恶魔邪教。在这些昏暗的隧道中，邪教徒在大酋长的斥候眼皮底下进行着邪恶的仪式。"},{t="恶魔协调",b="在骷髅石内活动的邪教徒佩戴着灼热项圈，这是一种旨在灼烧和烙印他们自身血肉的颈圈。据玛高兹说，这种自残行为远非单纯的残忍；金属中嵌入的灼热痛苦和邪能魔法有助于使佩戴者与恶魔力量达成协调。通过回收这些神器，玛高兹打算解开赋予火刃氏族力量的具体咒语和绑定。"},{t="迫在眉睫的威胁",b="揭开项圈背后的秘密证实了该邪教在杜隆塔尔的活动是蓄意且有组织的。火刃氏族并非仅仅以分散的强盗形式活动；他们的魔法根深蒂固，对新建立的部落领地构成了直接而阴险的威胁。分析这些项圈引发了一连串的调查，并将线索直接指向了奥格瑞玛阴影中的圈子。"}},faq={{q="骷髅石位于何处？",a="骷髅石是一座位于杜隆塔尔东北部的海岸洞穴，坐落在奥格瑞玛以东、森金村以北的海岸线上。其入口处有险峻的悬崖作为标记。",al={"骷髅石位置","骷髅石在哪里","杜隆塔尔骷髅石洞穴"}},{q="火刃氏族是什么？",a="火刃氏族是一个危险的兽人与邪能崇拜者邪教，致力于崇拜恶魔实体和黑暗魔法。虽然现代部落已经脱离了恶魔的奴役，但像火刃氏族这样的分裂团体仍在继续进行禁忌仪式，试图从阴影中腐化部落。",al={"火刃氏族是什么","火刃氏族邪教徒是谁","火刃氏族背景"}},{q="邪教徒使用灼热项圈做什么？",a="邪教徒将灼热的金属带戴在脖子上以灼烧自己的血肉。玛高兹怀疑这种仪式性的痛苦和恶魔附魔使他们能够引导并协调自己以获取黑暗的邪能。",al={"灼热项圈用途","为什么要佩戴灼热项圈","什么是灼热项圈"}},{q="玛高兹是谁？",a="玛高兹是一位兽人隐士，居住在杜隆塔尔悬崖顶上的一个小营地里，靠近骷髅石。他密切关注着沿海地区的邪教活动，并致力于瓦解火刃氏族的黑暗行动。",al={"玛高兹是谁","杜隆塔尔玛高兹","玛高兹任务给予者"}},{q="为什么部落允许邪教在奥格瑞玛附近存在？",a="他们并非知情并容忍。该邪教在极度保密的情况下运作，隐藏在常规巡逻队很少到达的洞穴和荒凉的峡谷中。冒险者之所以被派去调查，正是因为这些邪教徒在黑暗仪式开始前，成功地掩盖了他们的立足点。",al={"为什么骷髅石在奥格瑞玛附近","奥格瑞玛火刃氏族"}},{q="玛高兹检查项圈后会发生什么？",a="玛高兹打算检查灼热项圈。调查将随着奥格瑞玛的尼尔鲁·火刃任务继续进行。",al={"骷髅石之后的任务","项圈线索","玛高兹法术"}}},fp="10,216,16.308.0,18.283.0,18.239.1,28.145.0,25.257.0,49.201.0,14.192.0,56.219.0,47.107.1"}
P.entries["quest:8273"] = {n="奥兰的感谢",s="在“林吉的秘密”任务之后，始于“林吉被困！”的任务线，随着你将一块石板带给奥兰·斯内克威瑟而宣告终结。",h="在“林吉的秘密”任务之后，始于“林吉被困！”的任务线，随着你将一块石板带给奥兰·斯内克威瑟而宣告终结。",kw={"黑暗女王","辛特兰","奥兰·斯内克威瑟","眺望台悬崖","林吉","石板"},sec={{t="给奥兰的石板",b="“林吉被困！”开启了这条任务线，而“林吉的秘密”是紧接在这一步之前的任务。奥兰·斯内克威瑟是你所携带石板的交付对象。"},{t="奥兰的回答",b="奥兰询问石板是在哪里发现的，你告诉他是在眺望台悬崖边的一座荒废小岛上。奥兰觉得这非常有趣，小心地收好了石板，并说黑暗女王会对这个发现感到非常高兴。"}},faq={{q="奥兰·斯内克威瑟是谁？",a="奥兰·斯内克威瑟是结束了那条始于“林吉被困！”并贯穿了“林吉的秘密”的任务线的人。",al={"奥兰","奥兰是谁","奥兰·斯内克威瑟背景故事"}},{q="任务线中这一步之前是什么？",a="在这之前是“林吉的秘密”，而在那之前是“林吉被困！”。",al={"前序任务","奥兰的感激的前置任务","如何开始奥兰的感激"}}},fp="16,72,17.91.0,13.220.1,24.134.0,36.66.0"}
P.entries["quest:828"] = {n="玛高兹",s="玛高兹是一个部落任务，要求冒险者寻找一位守望在杜隆塔尔北部的隐居兽人萨满。在枯水谷遭遇邪能腐蚀后，奥戈尼尔·魂痕会指引勇士们在袭击附近的邪教据点前先去咨询玛高兹。这位睿智的隐士对火刃氏族投下的日益增长的阴影提供了关键建议。",h="玛高兹是一个部落任务，要求冒险者寻找一位守望在杜隆塔尔北部的隐居兽人萨满。在枯水谷遭遇邪能腐蚀后，奥戈尼尔·魂痕会指引勇士们在袭击附近的邪教据点前先去咨询玛高兹。这位睿智的隐士对火刃氏族投下的日益增长的阴影提供了关键建议...",kw={"火刃氏族","枯水谷","杜隆塔尔","玛高兹","奥戈尼尔·魂痕","奥格瑞玛","萨满","骷髅石"},ang={["class:Shaman"]="玛高兹代表了萨满教古老而耐心的智慧，他在荒野边缘守望，以便在精神腐蚀演变成战争之前就察觉到它。",["faction:Horde"]="玛高兹的警告突显了奥格瑞玛的脆弱性，证明了恶魔邪教潜伏在部落心脏的打击距离之内。",["race:Orc"]="拜访玛高兹提醒了兽人战士们邪能力量挥之不去的诱惑，敦促新一代人走上一条纯洁而光荣的道路。"},sec={{t="隐士的守望",b="在发现雷霆山的邪能腐蚀深度后，奥戈尼尔·魂痕认识到仅靠蛮力不足以净化杜隆塔尔。他指引他的勇士们去找玛高兹，一位经验丰富的兽人萨满，在剃刀岭东北部的岩石地带独自扎营。玛高兹位于枯水谷的崎岖高地与东海之间，时刻监视着奥格瑞玛那些忙碌的战士们往往会忽略的黑暗预兆。"},{t="骷髅石的威胁",b="玛高兹掌握着有关火刃氏族在杜隆塔尔北部真正权力基地的关键情报：一个被称为骷髅石的隐藏洞穴系统，就开凿在奥格瑞玛南门外的山崖上。通过与玛高兹商议，旅行者们了解到这些邪教徒在萨尔的首都附近的活动，远比酋长的卫兵们所意识到的要近得多。这位萨满确保任何被派去清除该集会所的人都不会盲目地陷入恶魔的伏击。"}},faq={{q="玛高兹是谁？",a="玛高兹是一位效忠于部落的睿智兽人萨满，住在杜隆塔尔东北部的一个隐蔽营地里。他研究黑暗魔法的动向，并监视着在该地区蔓延的恶魔腐蚀。",al={"玛高兹背景故事","玛高兹是谁","玛高兹 非玩家角色"}},{q="我在哪里可以找到玛高兹？",a="玛高兹在杜隆塔尔东北部的崎岖山丘中扎营，位于枯水谷和东海岸线之间，就在奥格瑞玛的东南部。",al={"玛高兹位置","寻找玛高兹","玛高兹在哪里"}},{q="为什么奥戈尼尔·魂痕要派我去找玛高兹？",a="奥戈尼尔认识到玛高兹花了大量时间研究当地的火刃氏族邪教徒。在派你去袭击他们的据点之前，奥戈尼尔希望你能得到玛高兹的精神智慧和实践建议。",al={"为什么要与玛高兹交谈","奥戈尼尔·魂痕 玛高兹"}},{q="什么是骷髅石？",a="骷髅石是一个位于奥格瑞玛东墙南侧的隐藏山洞。它作为火刃氏族的一个防御森严的集会所，崇拜恶魔的邪教徒们就在部落的眼皮底下进行仪式。",al={"骷髅石背景故事","什么是骷髅石"}},{q="找到玛高兹之后会发生什么？",a="一旦你向玛高兹报告，他会认可你不断增长的实力，并立即指派你进入骷髅石，杀死邪教徒并取回他们受腐蚀的徽记。",al={"玛高兹之后的后续任务","玛高兹后续"}},{q="玛高兹是火刃氏族的一员吗？",a="不。玛高兹是一位忠诚的部落萨满，致力于清除恶魔的影响，并让年轻的勇士们保持在一条光荣且未受腐蚀的道路上。",al={"玛高兹是邪恶的吗","玛高兹是邪教徒吗"}}},fp="6,333,16.370.0,24.392.0,14.189.0,23.151.0,43.211.0,19.186.0,34.153.1,36.137.0"}
P.entries["quest:829"] = {n="尼尔鲁·火刃",s="这个任务将杜隆塔尔的玛高兹指引部落冒险者前往奥格瑞玛那阴影笼罩的腹地。你带着从火刃氏族邪教徒手中缴获的恶魔灼热项圈，被指引去寻找尼尔鲁·火刃。他是一位居住在暗影裂口的著名术士，声称自己研究黑暗魔法仅仅是为了保护部落。",h="这个任务将杜隆塔尔的玛高兹指引部落冒险者前往奥格瑞玛那阴影笼罩的腹地。你带着从火刃氏族邪教徒手中缴获的恶魔灼热项圈，被指引去寻找尼尔鲁·火刃。他是一位居住在暗影裂口的著名术士，声称自己研究黑暗魔法仅仅是为了保护部落。",kw={"火刃氏族","暗影裂口","杜隆塔尔","玛高兹","尼尔鲁·火刃","奥格瑞玛","灼热项圈","骷髅石","术士"},ang={["class:Shaman"]="玛高兹的坦白标志着萨满教义与恶魔魔法之间有着清晰的界限：元素不会与邪能神器沟通，因此需要术士的协助。",["class:Warlock"]="进入暗影裂口咨询尼尔鲁·火刃，让你直接接触到了奥格瑞玛最著名的术士，验证了你的禁忌技艺对部落的现实价值。",["faction:Horde"]="这项任务展示了奥格瑞玛内部脆弱的休战状态，大酋长的萨满们有时必须求助于暗影裂口中的阴影流放者，以保护杜隆塔尔免于灭亡。"},sec={{t="萨满的极限",b="在从潜伏于骷髅石的邪教徒手中回收了灼热项圈后，萨满玛高兹发现，解开这些邪恶魔法的奥秘已超出了他先祖技艺的能力范围。萨满与元素之灵和大地沟通，而这些神器却散发着原始的恶魔腐蚀气息。玛高兹意识到，若要了解火刃氏族的装置，就需要找一位精通神秘学的人，因此他派你去寻找居住在首都的一位术士。"},{t="进入暗影裂口",b="在奥格瑞玛的红色峭壁之下，坐落着暗影裂口，这是一个光线昏暗的洞穴，禁忌魔法的修行者们在萨尔警惕的注视下在此施展技艺。兽人术士尼尔鲁·火刃居住于此，他是一位极具影响力的人物，坚称自己对邪能的掌握完全是为了挫败恶魔的威胁。将项圈样本交给他引起了他极大的好奇心，将杜隆塔尔对邪教的调查直接带入了术士聚集地的核心。"}},faq={{q="为什么玛高兹要我去找术士？",a="玛高兹是一位萨满，他的力量源自元素和先祖之灵。从骷髅石回收的灼热项圈本质上纯粹是恶魔之物，而要探明其附魔和起源，需要精通邪能魔法和黑暗艺术的人。",al={"为什么需要术士","为什么是尼尔鲁","玛高兹 术士"}},{q="我在哪里可以找到尼尔鲁·火刃？",a="尼尔鲁·火刃位于暗影裂口，这是奥格瑞玛下方的一个地下洞穴群，术士、潜行者和暗影施法者们聚集于此。",al={"尼尔鲁位置","尼尔鲁·火刃在哪","暗影裂口 尼尔鲁"}},{q="尼尔鲁·火刃值得信任吗？",a="玛高兹本人也抱有怀疑。他指出，虽然尼尔鲁声称他的神秘学研究是无害的，仅用于对抗恶魔，但这究竟是真是假还有待观察。萨尔允许术士在奥格瑞玛活动，但会对他们进行严格的监督，建议保持警惕。",al={"尼尔鲁是邪恶的吗","尼尔鲁值得信任吗","我可以信任火刃吗"}},{q="什么是项圈样本？",a="项圈样本是从骷髅石的火刃氏族邪教徒身上缴获的灼热项圈之一。玛高兹把它交给你，让你直接送交给尼尔鲁·火刃进行魔法分析。",al={"项圈样本","什么是项圈","灼热项圈任务物品"}},{q="把项圈交给尼尔鲁之后会发生什么？",a="尼尔鲁会仔细检查这个项圈，随后引出任务“雅克塞罗斯”，他会派你深入调查该邪教在杜隆塔尔的阴影存在。",al={"尼尔鲁之后的后续任务","尼尔鲁做什么","尼尔鲁的任务线"}},{q="为什么部落允许术士留在奥格瑞玛？",a="大酋长萨尔出于现实的需要容忍了术士的存在，将他们限制在暗影裂口的地下，以便对其危险的研究进行监视和控制，并偶尔利用他们的知识来了解恶魔敌人。",al={"为什么允许术士存在","暗影裂口里的术士","萨尔 术士"}}},fp="15,210,17.276.0,24.342.0,37.237.0,33.121.0,31.198.0,27.167.0,46.147.0,47.205.0"}
P.entries["quest:83"] = {n="红色亚麻布",s="“红色亚麻面罩”是东谷伐木场的一位裁缝萨拉·迪博雷恩提供的一项艾尔文森林任务。由于布料短缺，她请求过往的冒险者去猎杀当地的迪菲亚强盗，并夺取他们身上的亚麻面罩。作为交换，她会利用回收来的布料为旅行者制作有用的商品。",h="“红色亚麻面罩”是东谷伐木场的一位裁缝萨拉·迪博雷恩提供的一项艾尔文森林任务。由于布料短缺，她请求过往的冒险者去猎杀当地的迪菲亚强盗，并夺取他们身上的亚麻面罩。作为交换，她会利用回收来的布料为旅行者制作有用的商品。",kw={"粗麻布","迪菲亚潜行者","东谷伐木场","艾尔文森林","红色亚麻面罩","萨拉·迪博雷恩","裁缝"},ang={["faction:Alliance"]="清理侵扰艾尔文森林树林的迪菲亚强盗不仅能为东谷带来有用的回收品，还能积极削弱兄弟会对王国腹地的控制。",["profession:Tailoring"]="萨拉·迪博雷恩的生意展示了乡村裁缝业的严酷现实，由于布料极其匮乏，当地裁缝不得不直接从地区强盗的背上收割布料。"},sec={{t="强盗与粗麻布",b="虽然在北郡山谷游荡的低等级迪菲亚强盗们只会用廉价的粗麻布面罩凑合，但在广阔的艾尔文森林出没的有组织的不法之徒们佩戴的却是更精细的绯红色亚麻面罩。对于缺乏原材料的当地工匠来说，这些帮派标识代表着一种极其务实且可用的布料来源。"},{t="营地回收",b="萨拉·迪博雷恩在艾尔文森林东部边缘繁忙的东谷伐木场工作，她总是在寻找可用的纺织品。通过鼓励冒险者清理隐藏在森林各处的迪菲亚营地，她既能维持自己的裁缝生意，又能帮助遏制兄弟会日益猖獗的侵扰。"}},faq={{q="是谁提供了“红色亚麻面罩”任务？",a="这项任务是由位于艾尔文森林东部东谷伐木场的裁缝萨拉·迪博雷恩提供的。",al={"谁提供红色亚麻面罩任务","红色亚麻面罩任务发布者","萨拉·迪博雷恩任务"}},{q="完成“红色亚麻面罩”任务需要哪些物品？",a="你需要收集6个红色亚麻面罩，它们可以从散布在艾尔文森林各处的迪菲亚帮派成员身上拾取。",al={"红色亚麻面罩需要收集什么","红色亚麻面罩所需物品","需要的面罩"}},{q="我在哪里可以在艾尔文森林找到迪菲亚强盗？",a="迪菲亚不法之徒栖息在艾尔文森林各处的小型营地中，包括布莱克威尔南瓜田、斯通菲尔德农场以及杰罗德码头周围的森林区域。",al={"艾尔文森林迪菲亚位置","迪菲亚营地在哪里","去哪里获取红色面罩"}},{q="为什么艾尔文森林的迪菲亚成员戴的是亚麻布而不是粗麻布？",a="根据萨拉·迪博雷恩的说法，北郡的低阶迪菲亚成员佩戴的是简陋的粗麻布面罩，而活跃在更广阔的艾尔文森林区域的成员装备更好，佩戴的是红色亚麻布，这标志着他们在兄弟会内部拥有更高的组织和补给层级。",al={"为什么要红色亚麻布","迪菲亚粗麻布对比亚麻布","迪菲亚面罩材质"}},{q="为什么萨拉·迪博雷恩想要强盗的面罩？",a="萨拉的裁缝生意正面临布料短缺。她会对从迪菲亚面罩上回收的干净亚麻布进行再利用，为伐木工和旅行者缝制实用的物品。",al={"为什么要收集面罩","萨拉如何处理面罩"}},{q="东谷伐木场位于哪里？",a="东谷伐木场位于艾尔文森林的最东端，就在通往赤脊山桥梁的主路北侧。",al={"东谷位置","东谷在哪里","如何找到萨拉·迪博雷恩"}}},fx={["18a4a024"]={q="红色亚麻面罩有什么用？",a="在艾尔文森林各处游荡的迪菲亚潜行者匪徒用这些红色亚麻面罩遮面。北郡的恶徒只能将就着使用粗麻布，而森林其他地方的盗贼用的布料更好。萨拉·迪博雷恩会将缴获的面罩拆开，重新织成实用的亚麻衣物。",al={"红色亚麻面罩有什么用","红色亚麻面罩用途","为什么要红色亚麻面罩"}},["8ac6c8ef"]={q="为什么艾尔文森林里会有迪菲亚匪徒？",a="迪菲亚潜行者在艾尔文森林各处设立营地，骚扰旅人，劫掠补给线，削弱暴风城的统治。他们的势力日益壮大，威胁着东谷伐木场等当地聚居地，趁着王国卫兵人手不足，在都城近旁扩大不法活动。",al={"艾尔文的迪菲亚","迪菲亚为什么在这里","迪菲亚潜行者 艾尔文森林"}},fea06053={q="萨拉·迪博雷恩为什么需要你帮忙，而不找卫兵？",a="萨拉·迪博雷恩是东谷伐木场的一名裁缝，并非士兵，也没有能力亲自对抗匪徒。暴风城的卫兵和当地驻军为了遏制四处发生的迪菲亚侵袭和豺狼人劫掠，早已不堪重负，普通工匠只能依靠路过的冒险者获取材料和保护。",al={"萨拉为什么找我","为什么不找艾尔文卫兵","迪博雷恩为什么需要帮助"}}},fp="15,169,18.181.0,19.200.0,37.109.0,42.92.0,49.138.0,54.180.0,46.153.0,43.127.0"}
P.entries["quest:830"] = {n="将军的命令",s="这些饱经风霜的文件是从提拉加德城堡顶层的一个锁着的保险箱里回收的，上面印有已故海军上将戴林·普罗德摩尔的个人印章。这些回收的命令揭示出，杜隆塔尔海岸沿线的库尔提拉斯人驻军绝非简单的海难幸存者，而是更加根深蒂固、组织严密的军队。将这些文件交给剃刀岭的加索克，便暴露了威胁着这个新生兽人国度的残余军事计划。",h="这些饱经风霜的文件是从提拉加德城堡顶层的一个锁着的保险箱里回收的，上面印有已故海军上将戴林·普罗德摩尔的个人印章。这些回收的命令揭示出，杜隆塔尔海岸沿线的库尔提拉斯人驻军绝非简单的海难幸存者，而是更加根深蒂固、组织严密的...",kw={"海军上将的命令","旧信封","戴林·普罗德摩尔","加索克","库尔提拉斯","本尼迪克特中尉","剃刀岭","提拉加德城堡"},ang={["faction:Horde"]="发掘普罗德摩尔的命令证明，联盟在杜隆塔尔海岸的存在是一场蓄谋已久的灭绝行动，这更加强调了部落为何必须时刻警惕地保卫其新家园。",["race:Orc"]="对于在杜隆塔尔为建立未来而奋斗的兽人来说，这些文件无情地提醒着他们戴林·普罗德摩尔那不懈的仇恨，以及那些仍试图毁灭他们的残余势力。"},sec={{t="一份尘封的遗赠",b="在提拉加德城堡上层的一个沉重箱子里，藏着一个旧信封，由本尼迪克特中尉看守。这份羊皮纸上盖着海军上将戴林·普罗德摩尔的徽章，概述了库尔提拉斯在血腥入侵杜隆塔尔期间发布的直接海军命令。即使在海军上将倒在塞拉摩之后，他的军官们仍坚守着防御工事，紧紧地执行着消灭部落定居点的任务。"},{t="剃刀岭的警报",b="将回收的文件交给剃刀岭的指挥官加索克，证实了当地防御部队最担心的事。沿东海岸扎根的人类部队并非漫无目的的落难者，而是一处等待增援的稳固滩头阵地。加索克立刻意识到，瓦解提拉加德的指挥体系对于杜隆塔尔的生存来说是当务之急。"}},faq={{q="在哪里可以找到海军上将的命令？",a="这些命令位于杜隆塔尔提拉加德城堡三楼一个锁着的箱子里，装在一个旧信封中。要打开这个箱子，你必须先击败二楼的本尼迪克特中尉，夺取他的钥匙。",al={"命令位置","旧信封在哪里","寻找海军上将的命令"}},{q="普罗德摩尔上将是谁？",a="海军上将戴林·普罗德摩尔是库尔提拉斯的统治者，也是第二次战争期间联盟海军舰队的最高指挥官。他拒绝相信兽人可以和平生活，于是航行至卡利姆多，对杜隆塔尔发动了一场灭绝战争，最终在塞拉摩陨落。",al={"海军上将是谁","戴林·普罗德摩尔的背景故事","谁发布了这些命令"}},{q="为什么库尔提拉斯的士兵仍留在提拉加德城堡？",a="当戴林·普罗德摩尔入侵杜隆塔尔时，他建立了像提拉加德城堡这样加固的沿海立足点。在他战败后，本尼迪克特中尉领导的残存军官和海军陆战队依然坚守岗位，决心继续他针对部落的战役。",al={"人类为什么在杜隆塔尔","提拉加德城堡的士兵","杜隆塔尔的库尔提拉斯人"}},{q="为什么加索克对这些命令如此担忧？",a="作为剃刀岭的军事指挥官，加索克的职责是保卫杜隆塔尔中部。发现组织严密的海军命令证明了提拉加德城堡对兽人家园构成了主动且经过计算的军事威胁，而非仅仅是无组织的落难幸存者。",al={"加索克的反应","为什么加索克关心这件事"}},{q="谁持有海军上将箱子的钥匙？",a="本尼迪克特中尉是位于提拉加德城堡二层的库尔提拉斯指挥官，他携带着打开装有旧信封的保险箱所需的钥匙。",al={"本尼迪克特之钥","谁掉落钥匙"}},{q="把命令交给加索克后会发生什么？",a="在检查了这些命令后，加索克认识到了危险：普罗德摩尔的计划在他死前就已经制定好了，而且可能会有更多波次的军队登陆杜隆塔尔海岸。他立即将命令送往奥格瑞玛，以便让大酋长的议会发出警报。",al={"海军上将的命令后续","下一个任务"}}},fp="20,262,15.398.0,19.327.1,37.156.0,27.252.0,51.244.0,48.191.0,41.146.0,49.204.0"}
P.entries["quest:8311"] = {n="耶斯帕尔的万圣节糖果！",s="在万圣节期间，一个名叫耶斯帕尔的孤儿因病躺在暴风城的孤儿院里，他渴望能参加节日庆典。由于病重无法外出，他请求联盟的冒险者代他去世界各地进行不给糖就捣蛋的活动。",h="在万圣节期间，一个名叫耶斯帕尔的孤儿因病躺在暴风城的孤儿院里，他渴望能参加节日庆典。由于病重无法外出，他请求联盟的冒险者代他去世界各地进行不给糖就捣蛋的活动。",kw={"达纳苏斯","橡皮糖","万圣节","铁炉堡","耶斯帕尔","水果糖","夜莺","杏仁糖","暴风城","塔瓦斯德","不给糖就捣蛋"},ang={["faction:Alliance"]="这项节日任务将遥远的首都联系在一起，要求英雄们从暴风城的大街，前往铁炉堡的山中大厅和达纳苏斯的树枝上，为一名孤儿带来欢乐。",["race:Gnome"]="由于他们的家园被穴居人和辐射摧毁，侏儒对节日的参与落到了铁炉堡的塔瓦斯德·基瑟尔身上，他确保了诺莫瑞根橡皮糖仍然可以被分享。"},sec={{t="一个受庇护的孩子",b="耶斯帕尔住在暴风城教堂广场的孤儿院里，这个万圣节他生病了。无法享受从艾泽拉斯各地收集糖果这种简单的童年乐趣，耶斯帕尔只能待在室内，希望路过的冒险者能分享节日精神，代他收集这些糖果。"},{t="联盟各地的糖果戏法",b="为了收集耶斯帕尔梦寐以求的节日糖果，冒险者必须前往艾尔文森林之外的远方。任务要求拜访暴风城、铁炉堡和达纳苏斯的旅店老板，以及流亡的侏儒塔瓦斯德·基瑟尔。每个成年人都要求你在交出奖品前进行表演——迫使旅行者模仿小鸡打鸣、跳舞、展示肌肉或像火车一样鸣笛，以换取暴风城杏仁糖和诺莫瑞根橡皮糖等地区特产。"}},faq={{q="耶斯帕尔是谁？",a="耶斯帕尔是住在暴风城孤儿院的一名年轻孤儿。在万圣节期间，他渴望得到节日糖果，但因病无法外出亲自收集。",al={"耶斯帕尔 暴风城","孤儿 耶斯帕尔","谁是耶斯帕尔"}},{q="为什么耶斯帕尔不能亲自去进行不给糖就捣蛋？",a="耶斯帕尔生病了，当城市其他地方都在庆祝万圣节时，他的病情使他不得不留在孤儿院里。",al={"为什么耶斯帕尔不能离开","耶斯帕尔生病了吗","耶斯帕尔 不给糖就捣蛋"}},{q="耶斯帕尔想要哪些糖果？",a="他请求四种不同的地区特产糖果：暴风城杏仁糖、铁炉堡薄荷糖、达纳苏斯水果糖和诺莫瑞根橡皮糖。",al={"耶斯帕尔 糖果","万圣节 糖果列表","耶斯帕尔 需要的糖果"}},{q="你在哪里可以获得诺莫瑞根橡皮糖？",a="由于诺莫瑞根仍然受到辐射且被占领，这种橡皮糖由目前待在铁炉堡秘法区的侏儒难民塔瓦斯德·基瑟尔分发。",al={"诺莫瑞根橡皮糖 位置","谁提供橡皮糖","塔瓦斯德 糖果"}},{q="旅店老板让你表演什么戏法？",a="旅店老板要求你表演滑稽的动作来换取糖果：在暴风城展示肌肉，在达纳苏斯跳舞，在铁炉堡模仿小鸡打鸣，并为塔瓦斯德发出火车鸣笛声。",al={"万圣节 戏法","旅店老板 戏法","糖果戏法 联盟"}},{q="耶斯帕尔会给你什么作为糖果的回报？",a="在收到四种节日糖果后，耶斯帕尔会很高兴地用他积攒的一些南瓜糖果与旅行者交换。",al={"耶斯帕尔 奖励","给耶斯帕尔的糖果 完成"}}},fx={["103fae29"]={q="耶斯帕尔为什么想要收集万圣节糖果？",a="耶斯帕尔是个患病的孤儿，只能待在暴风城孤儿院里，由护士长南丁格尔悉心照料，无法参加联盟各主城的万圣节庆典。为了像其他孩子一样感受节日，他希望尝尝各个盟友主城特有的节庆糖果，并愿意拿自己的南瓜糖果交换，好让自己不至于完全错过节日。",al={"耶斯帕尔为什么想要糖果","耶斯帕尔要糖果的动机","耶斯帕尔为什么要万圣节糖果"}},["423b280b"]={q="暴风城杏仁糖有什么用？",a="暴风城杏仁糖是当地的传统糖果，由贸易区的旅店老板在万圣节期间分发。它是耶斯帕尔托你收集的节庆糖果中代表人类王国的一种，向旅店老板展示你的力量就能得到。",al={"暴风城杏仁糖用途","暴风城杏仁糖是什么","谁想要暴风城杏仁糖"}},["37e1df8a"]={q="诺莫瑞根橡皮糖有什么用？",a="诺莫瑞根橡皮糖是一种特色糖果，由铁炉堡的塔瓦斯德·基瑟尔代表流亡侏儒分发。耶斯帕尔托你收集四种特色糖果，它就是其中之一，好让他尝遍联盟各族的节庆美味。",al={"诺莫瑞根橡皮糖用途","诺莫瑞根橡皮糖是什么","谁想要诺莫瑞根橡皮糖"}},e8e502ad={q="铁炉堡薄荷糖有什么用？",a="铁炉堡薄荷糖是矮人的特色糖果，由铁炉堡的旅店老板在这个秋季节日期间赠送。耶斯帕尔需要它来凑齐四座城市的万圣节糖果，只要活灵活现地模仿小鸡，逗旅店老板开心，就能得到。",al={"铁炉堡薄荷糖用途","铁炉堡薄荷糖是什么","谁想要铁炉堡薄荷糖"}},["61787ad3"]={q="达纳苏斯水果糖有什么用？",a="达纳苏斯水果糖是暗夜精灵的精致糖果，由达纳苏斯工匠区的旅店老板分发。有了它，就能凑齐各地的万圣节特色美食，让困在暴风城孤儿院里的耶斯帕尔如愿品尝。",al={"达纳苏斯水果糖用途","达纳苏斯水果糖是什么","谁想要达纳苏斯水果糖"}}},fp="31,175,17.236.0,37.367.0,14.135.0,46.101.0,30.117.0,43.90.0,47.135.0,50.92.0"}
P.entries["quest:8312"] = {n="斯波普斯的万圣节糖果！",s="“给斯普普的万圣节糖果！”是一个节日任务，冒险者需要替生病无法出门进行“不给糖就捣蛋”的斯普普收集节日糖果。作为回报，斯普普会提供一些神奇的糖果，食用后可以将你变身为各种滑稽又可怕的形态。你需要在各大主城的旅店老板和森金村的卡利·雷米克处收集这些糖果。",h="“给斯普普的万圣节糖果！”是一个节日任务，冒险者需要替生病无法出门进行“不给糖就捣蛋”的斯普普收集节日糖果。作为回报，斯普普会提供一些神奇的糖果，食用后可以将你变身为各种滑稽又可怕的形态。你需要在各大主城的旅店老板和森金...",kw={"糖果","万圣节","旅店老板","卡利·雷米克","森金村","斯普普","不给糖就捣蛋"},ang={["faction:Horde"]="这个任务让部落冒险者们为了一个生病的孩子，在各大主城以及森金村的暗矛巨魔聚落进行“不给糖就捣蛋”的活动。",["race:Troll"]="杜隆塔尔的暗矛巨魔也参与了庆祝活动，卡利·雷米克就在森金村分发节日糖果。"},sec={{t="卧床的节日",b="万圣节带来了庆祝、恶作剧和遍布各地的节日糖果，但并不是每个人都能参与户外的欢庆活动。当世界各地沉浸在节日的狂欢中时，斯普普却因病被困在室内。无法出门走动，斯普普便委托过往的旅行者代为收集糖果，并以一袋奇特的变形糖果作为回报。"},{t="遍布各地的“不给糖就捣蛋”",b="想要收集糖果，需要走遍各地的定居点。各大主城的旅店老板都存有节日糖果，但他们会要求访客在交出糖果前先展示一下节日精神，表演一些戏法。除了繁华的主城旅店，这一传统也延伸到了杜隆塔尔的海岸，那里的森金村的卡利·雷米克也会为前往那里的旅行者分发糖果。"}},faq={{q="谁是斯普普？",a="斯普普是一个生病的孩子，无法在万圣节期间出门进行“不给糖就捣蛋”。为了能参与这个节日，斯普普请求旅行者代为向世界各地的旅店老板和商贩收集节日糖果。",al={"谁是斯普普","斯普普","斯普普是什么人"}},{q="为什么斯普普不能去“不给糖就捣蛋”？",a="斯普普身体不适，病得太重，无法外出庆祝万圣节。由于疾病使他卧床不起，他只能依靠热心的冒险者去拜访各地的旅店老板，收集节日糖果。",al={"为什么斯普普不能去不给糖就捣蛋","为什么斯普普要待在家里","斯普普生病"}},{q="斯普普会交换什么糖果？",a="作为从旅店老板那里收集到的节日糖果的回报，斯普普承诺提供具有神奇变形效果的特殊糖果。食用它们可以将你变成各种既滑稽又可怕的生物和形态。",al={"斯普普给什么糖果","斯普普的糖果奖励","特殊糖果"}},{q="去哪里找给斯普普的糖果？",a="节日糖果由分布在各个主城的旅店老板发放，他们会要求旅行者表演戏法来交换糖果。除了城市旅店外，杜隆塔尔森金村的巨魔卡利·雷米克也会分发节日糖果。",al={"去哪里拿糖果","谁给糖果","糖果位置"}},{q="谁是卡利·雷米克？",a="卡利·雷米克是居住在杜隆塔尔森金村的一名巨魔，他通过向到访的欢乐旅行者发放节日糖果来参与万圣节活动。",al={"谁是卡利·雷米克","卡利·雷米克糖果","森金村糖果"}},{q="为什么旅店老板会要求表演戏法？",a="万圣节期间，主要定居点的旅店老板会要求访客通过表演各种滑稽的戏法或动作来展示他们的节日精神，然后才会分享他们的节日糖果。",al={"旅店老板想要什么","旅店老板戏法","如何获得旅店老板的糖果"}}},fp="31,209,19.201.0,34.230.0,14.198.0,38.150.0,41.130.0,40.137.0,18.128.0,33.153.0"}
P.entries["quest:832"] = {n="燃影之眼",s="这个神秘的炽光坠饰是在骷髅石深处从火刃氏族邪教徒加祖兹身上收缴的，它不断在持有者的脑海中低语着紧急警告。那个声音特别提到要让奥格瑞玛的兽人术士尼尔鲁·火刃去惩罚加祖兹。",h="这个神秘的炽光坠饰是在骷髅石深处从火刃氏族邪教徒加祖兹身上收缴的，它不断在持有者的脑海中低语着紧急警告。那个声音特别提到要让奥格瑞玛的兽人术士尼尔鲁·火刃去惩罚加祖兹。",kw={"火刃氏族","灼热之影","暗影裂口","杜隆塔尔","燃影之眼","加祖兹","尼尔鲁·火刃","奥格瑞玛","骷髅石"},ang={["class:Warlock"]="对于在暗影裂口中修行的术士来说，看到另一个修行者的名字被火刃氏族引用，这严酷地提醒着人们：国家准许的邪能研究与公开叛国之间的界限是多么薄弱。",["faction:Horde"]="在首都大门外发现邪教徒之间的低语，揭示了旧部落的恶魔腐化仍然在离杜隆塔尔中心非常近的地方令人不安地滋生着。",["race:Orc"]="与萨尔并肩作战净化燃烧军团腐化的兽人们，将火刃氏族在杜隆塔尔的存在视为对他们新家园不可容忍的亵渎。"},sec={{t="石中的声音",b="在骷髅石深处击杀加祖兹后，从他的遗骸中可以拾取到一个名为“燃影之眼”的不祥坠饰。这颗石头并非只是一个惰性的魔法饰品，它还会通过心灵感应发出震动。任何持有它的人都能直接听到一个严厉的声音在脑海中响起，向加祖兹索要报告，并警告他，他在奥格瑞玛以东的秘密行动已经暴露了。"},{t="奇怪的威胁",b="任何忠诚的部落侦察兵都会被这个声音发出的孤注一掷的最后通牒所震惊：如果不回应，尼尔鲁·火刃就会接到通知，以迅猛且残暴的手段猎杀加祖兹。尼尔鲁·火刃公开居住在奥格瑞玛的暗影裂口中，表面上是在萨尔的严格监督下研习黑暗魔法。将这个护身符交给尼尔鲁，他会表现出假装的惊讶和好奇，并对自己的名字被当作恐吓邪教徒的“鬼怪”而感到诧异。"}},faq={{q="什么是燃影之眼？",a="燃影之眼是火刃氏族首领加祖兹在骷髅石内掉落的一枚附魔坠饰。它充当了邪教特工与其幕后神秘主人之间的双向心灵感应中继器。",al={"燃影之眼","这个坠饰是什么","加祖兹之眼"}},{q="谁在通过坠饰说话？",a="暗影议会或火刃氏族内部的一位身份不明的上级正试图联系加祖兹，但他并不知道这个邪教徒已经在骷髅石被杀死了。",al={"谁在和我说话","坠饰里的声音","谁在通过眼睛说话"}},{q="为什么那个声音要用尼尔鲁·火刃来威胁加祖兹？",a="那个声音声称，如果加祖兹不提交报告，尼尔鲁·火刃就会以残酷的手段对他进行惩罚。尼尔鲁本人表示，他确实以猎杀大酋长的敌人而闻名，但他觉得因为自己的名字被单独点出来而感到奇怪。",al={"为什么要提到尼尔鲁","尼尔鲁·火刃的威胁","尼尔鲁的联系"}},{q="我应该把燃影之眼交给谁？",a="把坠饰带给尼尔鲁·火刃，他就在奥格瑞玛的暗影裂口深处，盘旋在坩埚和书籍旁边。",al={"灼热之影任务去哪里交","尼尔鲁·火刃在哪里"}},{q="尼尔鲁·火刃在收到燃影之眼时有什么反应？",a="尼尔鲁对那个声音点出他的名字感到十分好奇，更让他觉得奇怪的是，火刃氏族的邪教徒名字竟然与他如此相近。他留下了坠饰，打算对其进行研究，并思考其中传达的信息含义。",al={"尼尔鲁的反应","尼尔鲁说了什么"}},{q="加祖兹在哪里？",a="加祖兹潜伏在骷髅石的最深处，那是一个隐藏在杜隆塔尔东海岸岩壁中的洞穴，就在奥格瑞玛以东。",al={"加祖兹在哪里","加祖兹的位置","骷髅石首领"}}},fx={["286b7c01"]={q="燃影之眼中的声音为什么想要一份报告？",a="在吊坠中低语的声音正试图联系骷髅石的火刃氏族首领加兹乌兹。邪教高层已获悉他们的隐秘据点被部落发现，这位隐秘的指挥官急于召集加兹乌兹做好防御准备，以免他们的立足之地在不可避免的进攻中被摧毁。",al={"吊坠为什么会说话","燃影之眼为什么要报告","燃影之眼中的声音有何目的"}}},fp="15,139,20.260.0,16.347.1,34.212.0,36.152.0,57.213.0,42.109.0,50.205.1,25.137.0"}
P.entries["quest:833"] = {n="神圣的墓地",s="“神圣的安葬”是由博学者诺拉·暴雨图腾委托的一项任务，要求部落的冒险者们保护位于莫高雷东部的赤色石。这片神圣的先祖埋骨地正遭受刺鬃野猪人的劫掠，这些野猪人正在亵渎受人尊敬的牛头人战士的坟墓。驱逐这些闯入者，将为那些为了建立和保卫雷霆崖而献出生命的先烈恢复荣耀与安宁。",h="“神圣的安葬”是由博学者诺拉·暴雨图腾委托的一项任务，要求部落的冒险者们保护位于莫高雷东部的赤色石。这片神圣的先祖埋骨地正遭受刺鬃野猪人的劫掠，这些野猪人正在亵渎受人尊敬的牛头人战士的坟墓。驱逐这些闯入者，将为那些为了建...",kw={"神圣的安葬","先祖","刺鬃闯入者","博学者诺拉·暴雨图腾","莫高雷","野猪人","赤色石","雷霆崖"},ang={["class:Shaman"]="对圣地的亵渎惊扰了受尊崇先祖的灵魂，因此你必须介入以恢复大地的平衡。",["faction:Horde"]="协助牛头人长者守卫他们的神圣遗迹，巩固了部落与盟友共同保卫莫高雷的誓约。",["race:Tauren"]="保卫赤色石是一项深重的先祖荣耀，确保那些为你们族人的统一家园做出贡献的战士们能够不受干扰地安息。"},sec={{t="舒哈鲁的圣地",b="赤色石是整个莫高雷最受尊崇的圣地之一。它坐落在东部山脉下方的岩架中，是专门为最英勇的牛头人预留的最后安息之所。安葬在这里的英雄们都是传说中的战士，他们曾为保护族群、支持酋长以及在雷霆崖的高原上开辟永久家园而浴血奋战。对于舒哈鲁人来说，打扰他们的安息不仅是对传统的冒犯，更是对大地母亲本人的亵渎。"},{t="刺鬃氏族的亵渎",b="游牧的刺鬃氏族野猪人一直以来都在挑战牛头人对卡利姆多中部地区的控制，但他们最近向赤色石的推进标志着事态的严重升级。成群的刺鬃闯入者已经潜入了这片圣地，蹂躏大地并扰动安息之所。由于守护者博学者诺拉·暴雨图腾年事已高，无法独自一人驱逐入侵者，部落的年轻勇士们必须拿起武器，清除此地的闯入者，保卫那些受尊崇的逝者。"}},faq={{q="什么是赤色石？",a="赤色石是一处神圣的先祖墓地，位于莫高雷的东部山脉沿线。它专门为最英勇的牛头人战士预留，特别是那些为了保卫族群和建立雷霆崖而牺牲的战士。",al={"赤色石在哪里","莫高雷赤色石","牛头人墓地"}},{q="博学者诺拉·暴雨图腾是谁？",a="博学者诺拉·暴雨图腾是一位年长的牛头人，负责照料和守护神圣的赤色石。他意识到自己已过壮年，无法凭一己之力抵御入侵的刺鬃野猪人，因此他呼唤有能力的冒险者前来保卫逝者。",al={"暴雨图腾","博学者诺拉·暴雨图腾","谁发布神圣的安葬任务"}},{q="为什么刺鬃野猪人会出现在赤色石？",a="刺鬃氏族不断向莫高雷和贫瘠之地的牛头人领地施压。由于对领土和资源的渴望，成群的闯入者闯进了赤色石的岩架，在此过程中亵渎了坟墓。",al={"为什么野猪人在赤色石","刺鬃闯入者","野猪人入侵"}},{q="为什么这种亵渎行为对牛头人来说如此不可原谅？",a="牛头人文化极其推崇对先祖的敬意，并主张与逝者的灵魂和谐共存。任由野蛮的野猪人践踏大地，惊扰那些为雷霆崖献身的英雄们的骸骨，是对精神层面的极大侮辱。",al={"牛头人丧葬习俗","牛头人为何重视墓地"}},{q="这个任务接下来会导向哪里？",a="“神圣的安葬”是一项由博学者诺拉·暴雨图腾提供的独立防御任务。一旦刺鬃闯入者被解决，眼前的亵渎行为便会停止。",al={"神圣的安葬后续","神圣的安葬之后是什么"}},{q="谁被安葬在赤色石？",a="此地是为那些为了种族生存和酋长荣耀而战的牛头人勇士所预留的，尤其是那些因他们的牺牲才使得雷霆崖得以建立和保卫的英雄们。",al={"谁被埋葬在这里","赤色石坟墓"}}},fx={e11b84bd={q="博学者诺拉·暴雨图腾为什么请你帮忙，而不自己赶走他们？",a="博学者诺拉·暴雨图腾是一位长者，年事已高，早已不复当年，无法拿起武器对抗凶暴的战团。他的职责是照料并尊崇赤色石的灵魂，而非在前线作战，因此只能依靠你这样的能干旅人，去承担驱逐刺背入侵者的危险任务。",al={"诺拉·暴雨图腾为什么不能自己处理","诺拉·暴雨图腾为什么需要帮忙","诺拉·暴雨图腾为什么不战斗"}}},fp="15,241,31.385.0,27.398.0,18.206.0,28.186.0,46.201.0,51.200.0,32.154.0,27.180.0"}
P.entries["quest:834"] = {n="沙漠之风",s="雷兹拉克是加兹鲁维手下的一名承包工程师，他急需帮助来找回被杜隆塔尔的鹰身人偷走的建筑材料。一队开往奥格瑞玛的商队在烈风峡谷遭到伏击，货物被散落在悬崖各处。",h="雷兹拉克是加兹鲁维手下的一名承包工程师，他急需帮助来找回被杜隆塔尔的鹰身人偷走的建筑材料。一队开往奥格瑞玛的商队在烈风峡谷遭到伏击，货物被散落在悬崖各处。",kw={"商队","杜隆塔尔","尘风鹰身人","加兹鲁维","奥格瑞玛","棘齿城","烈风峡谷","雷兹拉克","物资"},ang={["faction:Horde"]="每一批在峡谷中损失的货物都威胁着部落在杜隆塔尔的据点的快速扩张和防御加固。",["profession:Engineering"]="雷兹拉克代表了热砂港工程师务实的精明，他们更关心的是让蓝图和交付如期进行，而不是当地的野外麻烦。",["race:Orc"]="兽人依靠地精的专业知识和外来物资，将杜隆塔尔贫瘠干燥的土地变成了防御稳固的家园。"},sec={{t="有期限的地精",b="雷兹拉克是由棘齿城的总工程师加兹鲁维直接派遣的，旨在协助部落在杜隆塔尔进行庞大的建筑工程。在贫瘠严酷的地形上修建防御工事本身就已经困难重重，如果再加上后勤灾难，情况就更糟了，但雷兹拉克的货物总是在运抵工地前就消失不见。没有了必要的货物，所有工作都陷入了停滞，这让这位脾气暴躁的地精主管陷入了无米下锅的窘境。"},{t="峡谷伏击",b="雷兹拉克原本期待的一批重要物资在烈风峡谷被尘风鹰身人拦截了。这些长着翅膀的食腐动物在剃刀岭和奥格瑞玛之间的道路两侧高耸的峡谷缝隙中筑巢，并会俯冲袭击毫无防备的货车。鹰身人们并没有吃掉或毁坏货物，而是将这些板条箱和麻袋囤积在巢穴周围，这使得任何有勇气杀入它们领地的人都可以完好地找回这些物资。"}},faq={{q="雷兹拉克是谁？",a="雷兹拉克是一名地精工人，受雇于棘齿城的头目加兹鲁维。加兹鲁维派他前往杜隆塔尔，协助兽人在奥格瑞玛大门外进行持续的建设工作。",al={"雷兹拉克","雷兹拉克是谁","谁给的任务"}},{q="为什么地精要帮助在杜隆塔尔进行建设？",a="加兹鲁维和热砂港与萨尔大酋长之间有着长期的商业和工程合作关系。地精工程师和机器帮助打下了奥格瑞玛的基石，而加兹鲁维也继续为部落提供承包劳动力和材料。",al={"为什么地精帮助兽人","加兹鲁维 杜隆塔尔","地精与部落合作"}},{q="物资从哪里来？",a="雷兹拉克并没有说明这些物资的来源。他只说是为了协助他在杜隆塔尔为兽人工作而运送的货物。",al={"物资来源","商队来源"}},{q="鹰身人在杜隆塔尔做什么？",a="尘风鹰身人是一种好斗的掠夺性食腐生物，它们盘踞在杜隆塔尔中部的悬崖和峡谷中。它们骚扰过往的旅行者，抢劫穿过烈风峡谷的贸易路线，并搜集任何发光或有用的东西来装饰巢穴。",al={"为什么杜隆塔尔有鹰身人","尘风鹰身人背景故事","烈风峡谷鹰身人"}},{q="烈风峡谷在哪里？",a="烈风峡谷直接从连接奥格瑞玛和剃刀岭的主要南部峡谷分支出来。峡谷切割了东侧和西侧的悬崖壁，形成了高耸的栖息地，尘风鹰身人就将偷来的货物藏在那里。",al={"烈风峡谷位置","在哪里寻找物资","补给袋位置"}},{q="为什么兽人守卫没有保护商队？",a="雷兹拉克说商队一直难以保持安全，并且这批货物原本承诺过会顺利送达。他没有解释随行了什么样的护卫，也没有解释为什么其防御在尘风鹰身人面前失败了。",al={"商队为什么失败","杜隆塔尔安全","兽人商队"}}},fp="19,156,22.315.0,20.349.0,14.145.0,41.237.0,33.129.0,38.220.0,34.190.0,46.182.0"}
P.entries["quest:835"] = {n="保卫商路",s="“维护补给线”是雷兹拉克在烈风峡谷附近发布的一项任务，旨在保护途经杜隆塔尔的重要地精补给路线。盘踞在枯水谷的鹰身人不断拦截并洗劫补给商队，这让这位地精感到十分恼火，于是雇佣人手来清理它们。",h="“维护补给线”是雷兹拉克在烈风峡谷附近发布的一项任务，旨在保护途经杜隆塔尔的重要地精补给路线。盘踞在枯水谷的鹰身人不断拦截并洗劫补给商队，这让这位地精感到十分恼火，于是雇佣人手来清理它们。",kw={"枯水谷","尘风野蛮人","尘风风暴女巫","加兹鲁维","棘齿城","烈风峡谷","雷兹拉克","维护补给线"},ang={["faction:Horde"]="清除烈风峡谷东部的鹰身人威胁，有助于维持杜隆塔尔前哨站与沿海贸易枢纽之间货物和增援的流动。",["profession:Engineering"]="守护雷兹拉克的货物能确保尖端地精组件从棘齿城源源不断地运送到当地工匠手中。"},sec={{t="鹰身人肆虐的路线",b="杜隆塔尔干旱的峡谷本身就已经够恶劣了，更不用说还有那些会俯冲袭击毫无防备的旅行者的凶猛鹰身人。地精雷兹拉克代表他的老板加兹鲁维负责监管区域内的补给作业。不幸的是，居住在枯水谷的尘风鹰身人将烈风峡谷变成了一处险地，它们经常袭击商队，在货物运抵目的地之前就将其掠夺一空。"},{t="生意与杀戮",b="雷兹拉克的座右铭是：只要出得起价，没有办不成的事。与其亲自进入峡谷，他更愿意雇佣冒险者来消灭尘风野蛮人和尘风风暴女巫，从而摧毁它们的巢穴。清除这些鹰身人可以保持贸易通道畅通，确保工程小玩意的补给安全，并为热心的旅行者指明前往棘齿城获取更多机遇的道路。"}},faq={{q="雷兹拉克为谁效力？",a="雷兹拉克为加兹鲁维效力，加兹鲁维是中立地精港口城镇棘齿城的首席工程师兼镇长。加兹鲁维监管着杜隆塔尔和贫瘠之地各地的大量商业与基础设施项目。",al={"雷兹拉克的上司","雷兹拉克为谁工作","雷兹拉克的雇主"}},{q="为什么鹰身人要袭击商队？",a="尘风鹰身人在枯水谷建立了庞大的巢穴，而枯水谷正好直接横跨烈风峡谷的主要交通路线。它们会疯狂攻击任何入侵者，并洗劫过往的货车和货物。",al={"鹰身人为什么袭击","尘风鹰身人的动机","为什么是枯水谷"}},{q="枯水谷位于哪里？",a="枯水谷位于杜隆塔尔北部烈风峡谷的深处，在干旱的赤色丘陵中开凿而成。",al={"枯水谷的位置","枯水谷在哪里","如何找到枯水谷"}},{q="帮助雷兹拉克之后会发生什么？",a="随着尘风鹰身人被肃清，补给路线也变得安全了。雷兹拉克会建议冒险者前往边界另一侧贫瘠之地的棘齿城，寻找加兹鲁维以获得更多有利可图的合同。",al={"维护补给线之后","雷兹拉克的后续任务","雷兹拉克任务之后做什么"}},{q="为什么是地精而不是部落来对付这些鹰身人？",a="虽然部落在杜隆塔尔设有哨所，但他们的资源很有限，还要忙于应对半人马、野猪人和定居点内部的需求。像雷兹拉克这样的地精商人通常认为，直接雇佣独立的冒险者来保护他们的私人企业既快捷又划算。",al={"为什么地精会雇人","为什么奥格瑞玛不处理此事","部落与鹰身人"}},{q="枯水谷里有哪些种类的鹰身人？",a="这里的巢穴主要由进行近战攻击的尘风野蛮人，以及能操控风暴与闪电攻击过往商队的尘风风暴女巫组成。",al={"鹰身人类型","尘风鹰身人类型","枯水谷的敌人"}}},fp="18,182,26.278.0,22.363.0,26.191.0,39.168.0,33.125.0,34.209.0,60.259.0,48.172.0"}
P.entries["quest:8353"] = {n="学小鸡，换糖果",s="“学鸡叫换薄荷糖”是万圣节期间在铁炉堡提供的一个轻松愉快的联盟节日任务。为了替年幼的孤儿耶斯帕尔换取传统的铁炉堡薄荷糖，冒险者们必须放下久经沙场的尊严，在酒馆里像小鸡一样拍打双臂并咯咯叫，以此博取大家一乐。旅店老板洛雷·火酒非常乐意奖励那些愿意放下身段，为孩子带去节日欢乐的人。",h="“学鸡叫换薄荷糖”是万圣节期间在铁炉堡提供的一个轻松愉快的联盟节日任务。为了替年幼的孤儿耶斯帕尔换取传统的铁炉堡薄荷糖，冒险者们必须放下久经沙场的尊严，在酒馆里像小鸡一样拍打双臂并咯咯叫，以此博取大家一乐。旅店老板洛雷·...",kw={"小鸡","咯咯叫","火酒","万圣节","旅店老板","铁炉堡薄荷糖","耶斯帕尔","糖果"},ang={["faction:Alliance"]="这个季节性的差事突显了联盟各主城之间的情谊，将铁炉堡的矮人好客之道与为暴风城的孤儿带去欢乐直接联系了起来。",["race:Dwarf"]="矮人们欣赏幽默、豪饮和节日传统，火酒的要求表明，没有哪个铁炉堡的顾客会把自己看得太过严肃。"},sec={{t="万圣节的传统",b="在万圣节期间，艾泽拉斯各地都沉浸在节日的喜悦中，人们通过变装狂欢和享用节日美食，庆祝丰收与冬季之间的这段时光。虽然经验丰富的英雄通常觉得自己年纪太大，不适合挨家挨户讨要糖果，但病重或孤儿的困境提供了一个体面的借口。在暴风城，年幼的耶斯帕尔渴望着节日糖果，这促使前往各地的联盟勇士们从联盟各主城的旅店老板那里收集具有代表性的地方特产。"},{t="旅店老板洛雷·火酒的条件",b="在铁炉堡热闹非凡的酒馆柜台后面，站着旅店老板洛雷·火酒，他正是著名的铁炉堡薄荷糖的守护者。火酒可不是那种轻易就会让冒险者如愿的人，他拒绝直接交出糖果。他坚持要一点“娱乐表演”，要求身经百战的战士和深沉冷静的施法者在拿到奖品前，必须像农家禽类一样拍打翅膀并咯咯叫。这一切都是为了节日欢乐，也让酒馆的客人们能以英雄的滑稽表现为乐。"}},faq={{q="为什么旅店老板洛雷·火酒要我学鸡叫？",a="旅店老板洛雷·火酒正在融入万圣节那爱玩的节日精神。由于久经沙场的冒险者们年纪太大，没法像小孩子那样去不给糖就捣蛋，他便要求用一段滑稽的“捣蛋”来换取糖果。他认为看一位强大的勇士拍打双臂并学鸡叫是一种不错的酒馆娱乐，于是便愉快地用一份铁炉堡薄荷糖来换取这小小的公众出丑。",al={"为什么要学鸡叫","火酒要我学鸡叫的原因","为什么我必须学鸡叫"}},{q="耶斯帕尔是谁，我为什么要为他弄薄荷糖？",a="耶斯帕尔是一位住在暴风城的患病孤儿，他自己无法参与城里的万圣节庆典。为了让他开心，联盟冒险者们要在世界各地奔波，从联盟的各个主要城市收集四种特殊的节日糖果，其中包括来自丹莫罗的爽脆的铁炉堡薄荷糖。",al={"耶斯帕尔是谁","为什么获取薄荷糖","耶斯帕尔 孤儿"}},{q="这个任务在万圣节假期中处于什么位置？",a="这个任务是与大型季节性任务“万圣节的礼物，给耶斯帕尔的糖果！”相关的四个地区性任务之一，除此之外还有来自暴风城和达纳苏斯的旅店老板，以及铁炉堡的塔瓦斯德·基瑟尔的任务。他们在交出各自城市的招牌糖果前，都要求冒险者进行特定的羞耻或戏剧性的表情动作。",al={"万圣节任务线","耶斯帕尔 糖果任务线","任务顺序"}},{q="我在哪里可以找到旅店老板洛雷·火酒？",a="旅店老板洛雷·火酒驻守在铁炉堡平民区石火旅店内部的吧台后面，在这个矮人主城的核心地带为游客提供饮品和住宿。",al={"火酒在哪里","火酒位置","铁炉堡旅店老板"}},{q="学鸡叫能得到什么奖励？",a="在完成学鸡叫后，旅店老板洛雷·火酒会交给你一份铁炉堡薄荷糖，这是一种活动限定的节日糖果，需要带回暴风城以凑齐耶斯帕尔的万圣节糖果礼盒。",al={"任务奖励","什么是薄荷糖","铁炉堡薄荷糖"}},{q="部落玩家可以完成这个任务吗？",a="不能，这个任务是联盟专属的。部落冒险者有他们自己的对应任务，孤儿斯波普斯会派遣勇士前往各个部落主城，从奥格瑞玛、幽暗城和雷霆崖的旅店老板那里收集糖果。",al={"这是联盟专属吗","部落的学鸡叫任务","部落可以做这个吗"}}},fp="27,193,24.246.0,26.296.0,60.230.0,49.232.0,56.254.0,36.124.0,31.127.0,37.160.0"}
P.entries["quest:8354"] = {n="学小鸡，换糖果",s="在万圣节的节日期间，幽暗城的旅店老板诺曼会向帮助生病儿童的旅行者提供糖果。为了获得幽暗城薄荷糖，冒险者们必须放下尊严，像只小鸡一样扑腾。",h="在万圣节的节日期间，幽暗城的旅店老板诺曼会向帮助生病儿童的旅行者提供糖果。为了获得幽暗城薄荷糖，冒险者们必须放下尊严，像只小鸡一样扑腾。",kw={"小鸡","咯咯叫","万圣节","旅店老板诺曼","斯波普斯","贸易区","幽暗城","幽暗城薄荷糖"},ang={["faction:Horde"]="在万圣节期间，部落的冒险者们会奔波于各个主城之间，在每一处都忍受愚蠢的屈辱，只为给一个孤儿带去快乐。",["race:Undead"]="在幽暗城腐烂的大厅里找到这种愚蠢的幽默感是很少见的，这使得诺曼的节日要求成为日常死灵实用主义中一种奇异的调剂。"},sec={{t="难得的欢乐",b="幽暗城因其是被遗忘者在洛丹伦废墟之下建立的，所以很少有人会将它与欢笑或温暖联系起来。然而，当万圣节到来时，即使是贸易区阴沉的居民们也会加入到节日的狂欢中。旅店老板诺曼手里有一批幽暗城薄荷糖，是专门留给那些为了帮助生病孤儿斯波普斯收集糖果的人准备的，那个孩子需要节日的快乐。"},{t="赢得糖果",b="诺曼并没有直接把糖果交给经验丰富的冒险者，而是要求他们进行一点令人尴尬的表演。他认为成年的战士和施法者应该靠自己的努力赢得糖果，因此，在请愿者在他的柜台前模仿农场里的鸡之前，他拒绝交出薄荷糖。"}},faq={{q="为什么旅店老板诺曼要我像小鸡一样咯咯叫？",a="旅店老板诺曼认为，成熟的勇士如果想讨糖果，就必须先表演一番。为了活跃万圣节的气氛，他要求在交出节日糖果之前，冒险者必须先进行一场滑稽的表演——像小鸡一样扑腾翅膀并咯咯叫。",al={"为什么要做小鸡表情","为什么诺曼要我咯咯叫","诺曼小鸡舞"}},{q="这份糖果是给谁的？",a="幽暗城薄荷糖是为斯波普斯收集的，他是一名在奥格瑞玛休养的生病孤儿，无法在万圣节期间亲自去讨糖果。",al={"谁会得到薄荷糖","薄荷糖是做什么用的","为什么要获取幽暗城薄荷糖"}},{q="旅店老板诺曼在哪里？",a="旅店老板诺曼经营着幽暗城贸易区内的中央旅店，为被遗忘者顾客和来访的部落旅行者提供服务。",al={"诺曼的位置","幽暗城旅店老板在哪里"}},{q="这是一个节日任务吗？",a="是的。这个任务是艾泽拉斯部落和联盟共同庆祝的年度万圣节庆典的一部分。",al={"这是万圣节吗","这个任务何时可用"}},{q="被遗忘者通常会庆祝万圣节吗？",a="被遗忘者非常热情地庆祝万圣节，他们在洛丹伦废墟外焚烧一个巨大的柳条人，以纪念他们的解放并与他们曾经的凡人生活彻底决裂。",al={"被遗忘者的万圣节","亡灵节日"}},{q="拿到幽暗城薄荷糖后会怎样？",a="薄荷糖会与从部落各个种族主城收集来的其他招牌糖果组合在一起，为年幼的斯波普斯拼凑出一份完整的节日礼物。",al={"下一个任务","我该如何处理薄荷糖"}}},fp="27,181,19.303.0,17.222.0,58.201.0,30.121.0,34.130.0,34.105.0,44.183.0,46.129.0"}
P.entries["quest:8355"] = {n="学火车，换糖果",s="“橡皮糖来了”是万圣节期间在铁炉堡接到的一项节日任务，任务发布者是侏儒工匠塔瓦斯德·基瑟尔。为了给暴风城的一名生病儿童获取节日糖果，冒险者必须先为这位乐在其中的侏儒表演一段有趣的火车模仿秀。",h="“橡皮糖来了”是万圣节期间在铁炉堡接到的一项节日任务，任务发布者是侏儒工匠塔瓦斯德·基瑟尔。为了给暴风城的一名生病儿童获取节日糖果，冒险者必须先为这位乐在其中的侏儒表演一段有趣的火车模仿秀。",kw={"诺莫瑞根橡皮糖","万圣节","橡皮糖来了","铁炉堡","耶斯帕尔","塔瓦斯德·基瑟尔","侏儒区","火车表情动作"},ang={["faction:Alliance"]="寻找节日橡皮糖的过程会促使联盟英雄们奔波于各个王国之间，以确保暴风城的一名患病儿童也能分享节日的快乐。",["race:Gnome"]="对于侏儒区的流亡侏儒来说，在万圣节期间提供诺莫瑞根橡皮糖是对家园和机械独创性的一种欢快的提醒，即便他们正流离失所。"},sec={{t="异想天开的代价",b="在万圣节的秋季庆典期间，不给糖就捣蛋的人们会搜寻联盟的各大据点，收集各具特色的地区糖果。在铁炉堡的秘法区，侏儒塔瓦斯德·基瑟尔手中就有令人垂涎的诺莫瑞根橡皮糖。虽然他也很同情那位渴望糖果的孤儿，但塔瓦斯德坚持要维护万圣节的恶作剧精神，在交出糖果前，他要求任何寻求施舍的人模仿火车的鸣笛声。"},{t="节日善举",b="该任务是一项宏大的季节性事业的一部分，旨在为暴风城的孤儿院里一位名叫耶斯帕尔的患病孤儿带来欢乐。耶斯帕尔渴望得到联盟领地各处的四种特产糖果：暴风城的牛轧糖、铁炉堡的薄荷糖、达纳苏斯的杏仁糖和诺莫瑞根的橡皮糖。通过模仿呼啸的火车头来取悦塔瓦斯德，勇士们可以获得这种侏儒糖果，以满足这位小男孩的节日愿望。"}},faq={{q="我需要做什么才能完成“橡皮糖来了”？",a="你必须选中塔瓦斯德·基瑟尔并对他使用火车表情动作，以此为他表演一段火车模仿秀。一旦他听到了火车的鸣笛声，就会乐意交出诺莫瑞根橡皮糖。",al={"如何完成橡皮糖来了","橡皮糖来了任务目标","塔瓦斯德的橡皮糖恶作剧"}},{q="塔瓦斯德·基瑟尔是谁？",a="塔瓦斯德·基瑟尔是一位来自诺莫瑞根的侏儒珠宝匠，现居于矮人山城铁炉堡的秘法区。在万圣节期间，他担任诺莫瑞根招牌橡皮糖的联盟经销商。",al={"塔瓦斯德是谁","塔瓦斯德·基瑟尔背景故事"}},{q="诺莫瑞根橡皮糖有什么用？",a="诺莫瑞根橡皮糖是为满足暴风城孤儿院里患病孤儿耶斯帕尔的万圣节请求而收集的四种节日糖果之一。",al={"诺莫瑞根橡皮糖用途","橡皮糖是干什么用的"}},{q="在哪里可以找到塔瓦斯德·基瑟尔？",a="你可以在铁炉堡的秘法区找到塔瓦斯德。",al={"塔瓦斯德在哪里","塔瓦斯德位置"}},{q="为什么塔瓦斯德要让人模仿火车？",a="万圣节植根于“不给糖就捣蛋”的传统。塔瓦斯德调皮地要求对方进行一个小小的无伤大雅的恶作剧——模仿火车头——才会愿意交出他的节日糖果。",al={"为什么是火车鸣笛","为什么要为塔瓦斯德表演火车"}},{q="这个任务全年都可以做吗？",a="不，该任务仅在每年秋季的万圣节期间开放。",al={"可以随时做橡皮糖来了吗","这是季节性任务吗"}}},fp="16,150,16.308.0,15.323.0,50.116.0,26.176.0,40.135.0,38.61.0,42.143.0,35.75.0"}
P.entries["quest:8356"] = {n="显肌肉，换糖果",s="在万圣节的秋季庆典期间，造访暴风城的冒险者们可以帮助当地的孤儿收集节日糖果。想要从闪金镇旅店的旅店老板奥里森那里获得一块暴风城杏仁糖，访客们必须配合地展示一下强健的肌肉，博得老板一笑，她才会交出糖果。",h="在万圣节的秋季庆典期间，造访暴风城的冒险者们可以帮助当地的孤儿收集节日糖果。想要从闪金镇旅店的旅店老板奥里森那里获得一块暴风城杏仁糖，访客们必须配合地展示一下强健的肌肉，博得老板一笑，她才会交出糖果。",kw={"为了杏仁糖展示肌肉","闪金镇","万圣节","旅店老板奥里森","耶斯帕尔","暴风城","暴风城杏仁糖","不给糖就捣蛋"},ang={["class:Warrior"]="对于习惯了血腥战场的强壮战士来说，在旅店老板的要求下展示手臂肌肉，虽然有些不够庄重，却是一种无伤大雅的力量展示。",["faction:Alliance"]="这种有趣的互动突显了暴风城在万圣节等节日期间蓬勃发展的轻松社区精神，让市民和四处漂泊的英雄们聚在一起开怀大笑。",["race:Human"]="对于暴风城的人类来说，宠溺孩子并用恶作剧交换糖果是一项珍贵的节日习俗，它让人们从王国面临的黑暗危机中得到片刻解脱。"},sec={{t="万圣节的传统",b="万圣节为暴风城的街道带来了一种难得的轻松氛围。虽然这个节日有着古老的渊源，象征着季节更替和驱除黑暗幽灵，但平民百姓还是通过化装、狂欢和不给糖就捣蛋来庆祝它。联盟各地的旅店老板们都会参与进来，发放传统的糖果，前提是寻求节日乐趣的人们愿意表演一个无伤大雅的恶作剧来换取糖果。"},{t="取悦旅店老板",b="在热闹的商业区的闪金镇旅店里，旅店老板奥里森坚持不让任何人免费得到节日糖果——即使他们是在为像耶斯帕尔这样的孤儿跑腿。奥里森会观察冒险者身上穿的装备或服饰，打趣地评价一番他们的身材，并坚持让他们展示肌肉以供消遣。只有当冒险者展示过力量后，她才会奖励他们一块耐嚼的暴风城杏仁糖。"}},faq={{q="为什么旅店老板奥里森要让人们展示肌肉？",a="万圣节的核心就是不给糖就捣蛋的传统。因为冒险者是代表一位寻求糖果的孤儿前来的，旅店老板奥里森坚持让他们用一个有趣的恶作剧来换取糖果——也就是展示他们的肌肉。",al={"为什么为了杏仁糖展示肌肉","奥里森想要什么","为什么要做展示肌肉的表情"}},{q="这个任务是在哪里进行的？",a="这个请求是在位于暴风城商业区中心的闪金镇旅店里提出并完成的，旅店老板奥里森就在那里照看酒馆柜台。",al={"为了杏仁糖展示肌肉在哪里","奥里森的位置","闪金镇旅店老板"}},{q="暴风城杏仁糖是给谁准备的？",a="这块杏仁糖是给耶斯帕尔准备的，他是一个住在暴风城的孤儿。他希望在万圣节期间尝遍联盟各大主城的传统节日糖果。",al={"谁得到了杏仁糖","谁想要暴风城杏仁糖","耶斯帕尔的糖果"}},{q="什么是暴风城杏仁糖？",a="暴风城杏仁糖是暴风城的旅店老板在万圣节期间发放的一种地方特产糖果，在节日参与者中被誉为人类王国的经典糖果之一。",al={"暴风城杏仁糖传说","万圣节杏仁糖","暴风城糖果"}},{q="部落玩家能从奥里森那里获得这种糖果吗？",a="不能。旅店老板奥里森身处联盟控制的暴风城深处，只接待联盟成员。部落冒险者需要在他们自己的主城里为旅店老板表演各自的节日节目。",al={"部落能为了杏仁糖展示肌肉吗","部落版的杏仁糖"}},{q="这个任务是全年都有吗？",a="不是。旅店老板奥里森只在万圣节的节日期间提供这个请求，那时不给糖就捣蛋的风俗会在各个城市流行开来。",al={"为了杏仁糖展示肌肉何时开放","这是节日任务吗","万圣节时间"}}},fp="18,176,24.276.0,26.304.0,44.116.0,33.112.0,38.158.0,25.165.0,49.179.0,34.114.0"}
P.entries["quest:8357"] = {n="跳跳舞，换糖果",s="在万圣节期间，旅行至达纳苏斯的冒险者们肩负着为暴风城的一名生病孤儿收集节日糖果的任务。旅店老板塞琳尼完全秉承了“不给糖就捣蛋”的传统，她要求冒险者在交出宝贵的达纳苏斯水果糖之前，必须即兴表演一段舞蹈。",h="在万圣节期间，旅行至达纳苏斯的冒险者们肩负着为暴风城的一名生病孤儿收集节日糖果的任务。旅店老板塞琳尼完全秉承了“不给糖就捣蛋”的传统，她要求冒险者在交出宝贵的达纳苏斯水果糖之前，必须即兴表演一段舞蹈。",kw={"跳舞","达纳苏斯","万圣节","旅店老板","耶斯帕尔","水果糖","塞琳尼","泰达希尔"},ang={["faction:Alliance"]="这项节日任务展示了联盟各主城之间共享的团结与轻松友谊，将来自遥远泰达希尔的糖果一直送到了暴风城的一名年轻孤儿手中。",["race:NightElf"]="对于暗夜精灵来说，参与万圣节是对联盟节日习俗的一种亲切采纳，将他们宁静的林地生活方式与俏皮的狂欢融合在了一起。"},sec={{t="延续的传统",b="即使在神圣的森林之城达纳苏斯，万圣节的狂欢也为长寿的暗夜精灵们带来了更为轻松的精神面貌。当旅行者们为了耶斯帕尔——一名在暴风城养病的患儿——前来收集节日糖果时，旅店老板塞琳尼坚持要遵守节日规则。无论是否出于慈善目的，想要得到糖果，必须先完成一次捣蛋。"},{t="水果糖的代价",b="为了获得精致的达纳苏斯水果糖，冒险者们必须放下尊严，在旅店地板上表演一场节目。塞琳尼只接受一段舞蹈作为交换，并乐于将这种完成跨大陆节日爱心包裹所需的糖果，奖励给那些愿意放下骄傲、拥抱节日欢乐的人。"}},faq={{q="“为水果糖而舞”的目的是什么？",a="该任务是联盟万圣节节日庆典的一部分。你需要为达纳苏斯的旅店老板塞琳尼跳一支舞，以获得达纳苏斯水果糖，这是让暴风城的患儿耶斯帕尔开心起来所需的几种节日糖果之一。",al={"为什么为了水果糖跳舞","这是什么任务","水果糖任务"}},{q="旅店老板塞琳尼是谁？",a="旅店老板塞琳尼管理着达纳苏斯内的旅店，为泰达希尔枝叶下的旅行者们提供庇护和休息。在万圣节期间，她负责向那些愿意遵循传统的旅行者分发当地的节日糖果。",al={"塞琳尼是谁","塞琳尼背景故事"}},{q="为什么塞琳尼坚持要跳舞？",a="塞琳尼严格遵守万圣节的精神。尽管这些糖果是给患儿准备的，但她依然坚守“不给糖就捣蛋”的习俗，俏皮地要求对方展示一下舞技作为“捣蛋”项目，之后才会交出糖果。",al={"为什么跳舞","为什么塞琳尼要我跳舞"}},{q="水果糖之后会去哪？",a="收到达纳苏斯水果糖后，它会被与其他从铁炉堡和暴风城的旅店以及铁炉堡的塔瓦斯德·基瑟尔处收集来的节日糖果打包在一起，以完成为暴风城的年轻孤儿耶斯帕尔带来节日欢乐的任务。",al={"谁得到了水果糖","水果糖怎么用"}},{q="什么是达纳苏斯水果糖？",a="达纳苏斯水果糖是一种在暗夜精灵主城制作的含糖甜点。它是达纳苏斯在万圣节期间为来访的“不给糖就捣蛋”者提供的标志性节日糖果。",al={"达纳苏斯水果糖背景故事","这是什么样的糖果"}},{q="部落玩家可以完成这个任务吗？",a="不可以。为水果糖而舞是联盟专属的节日任务。达纳苏斯是联盟的据点，且水果糖是专为在暴风城养病的联盟孤儿收集的。",al={"这个任务是联盟专属吗","部落水果糖任务"}}},fp="20,206,18.289.0,21.165.0,44.162.0,27.197.0,37.130.0,38.214.0,27.132.0,38.155.0"}
P.entries["quest:8359"] = {n="显肌肉，换糖果",s="在万圣节这个秋季庆典期间，奥格瑞玛的旅店老板格雷什卡会向那些乐于配合的人提供美味的节日糖果。为了给一个卧病在床的孩子弄到一块奥格瑞玛软糖，部落的勇士们必须抛下作为战士的骄傲，按要求展示他们的肌肉。",h="在万圣节这个秋季庆典期间，奥格瑞玛的旅店老板格雷什卡会向那些乐于配合的人提供美味的节日糖果。为了给一个卧病在床的孩子弄到一块奥格瑞玛软糖，部落的勇士们必须抛下作为战士的骄傲，按要求展示他们的肌肉。",kw={"糖果","展示肌肉","格雷什卡","万圣节","软糖","奥格瑞玛","斯波普斯","不给糖就捣蛋"},ang={["class:Warrior"]="那些以毁灭性的前线功绩为傲的战士们可能会发现，为了方块状的节日糖果而像舞台表演者一样摆姿势，是一件有趣——或者说略显谦卑的事情。",["faction:Horde"]="即使是面对致命军阀的资深勇士，最终也不得不为了给部落的孩子们收集节日糖果，而向旅店老板展示肱二头肌。",["race:Orc"]="奥格瑞玛的旅店老板期待着令人印象深刻的肌肉展示，这是一种典型的兽人式骄傲考验，变成了轻松愉快的节日戏码。"},sec={{t="不给糖就捣蛋",b="万圣节带来了欢快的气氛、恶作剧以及在艾泽拉斯各大主城收集糖果的活动。虽然冒险的英雄们经常要面对巨龙和黑暗魔法，但秋季节日的传统却需要轻松得多的方式。在奥格瑞玛旅店大厅主持工作的旅店老板格雷什卡很乐意分享她的节日糖果，但前提是顾客必须遵守这个节日最古老的规则：表演一个戏法，否则就空手而归。"},{t="展示肌肉",b="无论冒险者穿着什么伪装或护甲，格雷什卡都觉得很有趣，她要求展示原始的兽人力量。在交出给小斯波普斯准备的奥格瑞玛软糖之前，她坚持要看到这位强大的旅者摆出一个展示肌肉的姿势。这是一个轻松的提醒，即使是部落中最令人畏惧的战士，也可以为了糖果而娱乐大众。"}},faq={{q="是谁要求展示肌肉的？",a="旅店老板格雷什卡，奥格瑞玛力量谷内主旅店的经营者，在交出节日糖果之前要求表演戏法。",al={"谁给予任务","格雷什卡","旅店老板格雷什卡"}},{q="为什么为了糖果我需要展示肌肉？",a="万圣节习俗规定，不给糖就捣蛋的人必须表演一个小戏法来换取糖果。格雷什卡决定逗弄一下冒险者，要求在奖励他们之前展示一下纯粹的体能。",al={"为什么要展示肌肉","戏法是什么","软糖获取条件"}},{q="奥格瑞玛软糖有什么用？",a="这种软糖是在部落各大主城收集的四种特色糖果之一，用来安慰生病的孤儿斯波普斯，他自己无法去参加不给糖就捣蛋的活动。",al={"为什么需要软糖","软糖用途","斯波普斯的糖果"}},{q="旅店老板格雷什卡住在哪里？",a="你可以在奥格瑞玛力量谷的主旅店柜台后面找到她，她正在那里为疲惫的旅人和当地人服务。",al={"格雷什卡在哪里","奥格瑞玛旅店老板位置"}},{q="所有部落成员都能参与吗？",a="是的，任何部落成员都可以在万圣节期间拜访旅店老板格雷什卡，摆个姿势来领取节日糖果。",al={"谁能展示肌肉","阵营限制","仅限部落"}},{q="这是什么节日的一部分？",a="这个任务是万圣节的一部分，这是一个庆祝丰收结束，并通过服装、恶作剧和糖果来蔑视死亡的秋季节日。",al={"什么活动","什么节日","万圣节任务"}}},fp="18,148,17.282.0,17.237.0,27.143.0,32.161.0,38.159.0,36.131.0,41.122.0,31.136.0"}
P.entries["quest:836"] = {n="拯救OOX-09/HL！",s="当信号标激活了坠毁的寻路机器人后，奥格索普·奥布诺提斯的声音便从机器人身上传了出来。OOX-09/HL需要一个开阔、安全的地方来开始它的起飞程序，因此必须护送它前往眺望崖彼岸的海岸，然后奥格索普会在藏宝海湾等待。",h="当信号标激活了坠毁的寻路机器人后，奥格索普·奥布诺提斯的声音便从机器人身上传了出来。OOX-09/HL需要一个开阔、安全的地方来开始它的起飞程序，因此必须护送它前往眺望崖彼岸的海岸，然后奥格索普会在藏宝海湾等待。",kw={"藏宝海湾","隐形","寻路机器人","奥格索普·奥布诺提斯","眺望崖","机械小鸡-09/辛特兰"},sec={{t="前往海岸",b="奥格索普的声音再次从机器人身上传出，伴随着一阵杂音。这台机器需要一个开阔、安全的地方来开始漫长的起飞程序，眺望崖彼岸的海岸再合适不过了。它内置的隐形装置还无法使用，奥格索普需要时间让它恢复正常运作。"},{t="藏宝海湾的消息",b="一旦机器人被安全护送到海岸，奥格索普·奥布诺提斯会要求你去藏宝海湾找他谈话。"}},faq={{q="机器人需要被护送到哪里？",a="机械小鸡09号需要被带到眺望崖彼岸的海岸，那是一个开阔的地方，它可以在那里开始起飞。",al={"机械小鸡-09去哪里","辛特兰机械鸡护送目的地","眺望崖海岸"}},{q="是谁制造了这个寻路机器人？",a="这个机器人是侏儒奥格索普·奥布诺提斯的作品，他就在藏宝海湾。",al={"谁制造了机械小鸡-09","机械小鸡制造者","谁建造了机械鸡"}},{q="为什么机器人不能直接在被发现的地方起飞？",a="它的起飞程序非常漫长，需要一个开阔、安全的地方。与此同时，奥格索普需要时间让它的隐形装置恢复运作。",al={"为什么机械鸡要走路","为什么要护送机械小鸡-09"}},{q="护送到达海岸后你应该去哪儿？",a="一旦机器人安全抵达海岸，奥格索普·奥布诺提斯要求你去藏宝海湾见他。",al={"救援机械小鸡-09去哪交付","我向谁汇报","奥格索普位置"}},{q="在这个护送任务之前发生了什么？",a="在此之前是“寻找机械小鸡09号！”任务，你需要将求救信号标带到坠毁的机器人身边。",al={"机械小鸡-09前置任务","救援机械小鸡-09的前置条件"}}},fp="17,187,19.257.0,17.102.0,41.96.0,50.69.0,55.115.0,50.94.0,29.88.0"}
P.entries["quest:8360"] = {n="跳跳舞，换糖果",s="“为奶糖跳舞”是万圣节期间在雷霆崖由旅店老板帕拉提供的一个节日任务。为了给一名生病的孤儿收集甜点，冒险者必须放下久经沙场的尊严，为旅店老板跳一支欢快的舞蹈。即使在莫高雷那风吹的高原之上，这一任务也突显了节日中那种充满乐趣、社区至上的精神。",h="“为奶糖跳舞”是万圣节期间在雷霆崖由旅店老板帕拉提供的一个节日任务。为了给一名生病的孤儿收集甜点，冒险者必须放下久经沙场的尊严，为旅店老板跳一支欢快的舞蹈。即使在莫高雷那风吹的高原之上，这一任务也突显了节日中那种充满乐趣...",kw={"为奶糖跳舞","万圣节","旅店老板帕拉","奶糖","莫高雷","雷霆崖","不给糖就捣乱"},ang={["faction:Horde"]="这是部落艰苦日常中的轻松一刻，展现了当旅行者穿梭于各个主城为孤儿带来节日欢乐时，这个阵营所拥有的温情。",["race:Tauren"]="旅店老板帕拉将传统的节日欢愉直接带到了莫高雷，证明了即使是高大、坚毅的牛头人，也能为了一个甜蜜的事业而跳上一支欢快的舞蹈。"},sec={{t="崖上的舞蹈",b="在万圣节的秋季庆典期间，艾泽拉斯到处都洋溢着高昂的情绪，即便是雷霆崖宁静的高原上也不例外。负责照看高地旅店的旅店老板帕拉，在分发任何糖果之前，会要求对方先表演一个戏法，以此来感受节日气氛。即使冒险者是代表一名生病的孩子而来，传统依然不可动摇：帕拉坚持要看到一段节日舞蹈，才会交出她那珍贵的雷霆崖奶糖。"},{t="不给糖就捣乱",b="以娱乐换取糖果的节日习俗，展现了部落文化中罕见而轻松的一面。帕拉的要求并不复杂，只需上前一步，抖落一身的旅途疲惫，跳出你最棒的舞步即可。在被逗乐之后，这位旅店老板会很高兴地交出奶糖，并对等待这份甜点的那名生病的孩子表达她温暖的祝福。"}},faq={{q="“为奶糖跳舞”的任务目的是什么？",a="该任务要求你为雷霆崖的旅店老板帕拉表演一个跳舞表情。作为回报，她会给你一块雷霆崖奶糖，这是万圣节期间为生病孤儿收集的一系列节日糖果中的一部分。",al={"为什么要为奶糖跳舞","奶糖任务目标","为奶糖跳舞的任务目标"}},{q="是谁发布了这个任务？",a="旅店老板帕拉，这位在雷霆崖为游客和当地人提供服务的牛头人旅店老板，会在万圣节期间发布此任务。",al={"谁发布了为奶糖跳舞任务","帕拉的任务","旅店老板帕拉雷霆崖"}},{q="既然糖果是给生病的孩子吃的，为什么帕拉坚持要跳舞？",a="帕拉强调，即使是执行高尚的差事，也必须尊重节日传统。秉承着“不给糖就捣乱”的精神，必须表演一个戏法才能赢得甜蜜的奖励，以确保万圣节保持欢乐和活跃的氛围。",al={"为什么我必须跳舞","为什么帕拉想要看舞蹈"}},{q="跳舞能获得什么奖励？",a="你将获得一块雷霆崖奶糖，这是一种当地的节日甜点，是完成万圣节为生病的孩子收集糖果这一宏大任务所必需的物品。",al={"奶糖奖励","为奶糖跳舞任务物品"}},{q="联盟玩家可以完成这个任务吗？",a="不能。旅店老板帕拉是常驻雷霆崖中心的一名部落商人，这意味着节日糖果收集之旅中的这一特定环节仅限于部落成员参与。",al={"这是部落专属任务吗","联盟为奶糖跳舞"}},{q="这个任务什么时候可以完成？",a="该任务仅在每年的秋季节日“万圣节”期间开放，届时艾泽拉斯各地的旅店老板都会提供特殊的糖果和节日游戏。",al={"什么时候可以获得奶糖","万圣节奶糖任务"}}},fp="20,185,20.215.0,17.180.0,44.168.0,21.123.0,65.123.0,39.138.0,41.125.0,29.133.0"}
P.entries["quest:837"] = {n="野猪人的进犯",s="“入侵”是部落的一项任务，由位于杜隆塔尔中部的剃刀岭的加索克委派。该任务要求勇士深入西部的荆棘窝，消灭那些盘踞在此、威胁着年轻兽人国家边境的剃刀鬃毛野猪人。",h="“入侵”是部落的一项任务，由位于杜隆塔尔中部的剃刀岭的加索克委派。该任务要求勇士深入西部的荆棘窝，消灭那些盘踞在此、威胁着年轻兽人国家边境的剃刀鬃毛野猪人。",kw={"荆棘","杜隆塔尔","入侵","加索克","野猪人","剃刀岭","剃刀鬃毛"},ang={["faction:Horde"]="清除来自本地剃刀鬃毛野猪人的威胁，对为新兴部落建立一个安全、永久的家园至关重要。",["race:Orc"]="兽人已将杜隆塔尔作为他们新的主权领土，他们将残存的剃刀鬃毛荆棘窝视为对定居点不可接受的威胁。"},sec={{t="杜隆塔尔的芒刺",b="当萨尔带领兽人来到卡利姆多并建立杜隆塔尔时，他们发现这片严酷干旱的土地上早已居住着剃刀鬃毛野猪人。这些好斗的野猪状生物成了新定居点的心腹大患。通过持续的军事努力，部落击退了他们大部分的兵力，但剃刀鬃毛野猪人的顽固据点仍然死守在剃刀岭以西的荆棘堡垒中。"},{t="加索克的攻势",b="加索克，一位驻扎在剃刀岭的军官，正在监督旨在彻底清除残余的剃刀鬃毛威胁的行动。他委派经验丰富的保卫者直接深入西部的荆棘营地，去消灭他们的侦察兵、战士和尘暴奔袭者。对加索克和部落领导层来说，让野猪人在剃刀岭附近有任何立足之地都会招致灾难，在这里打击他们被视为确保卡利姆多安全的第一步。"},{t="清除荆棘",b="消灭野猪人防卫者为部落军队焚烧荆棘窝扫清了道路，从而阻止了剃刀鬃毛野猪人重新夺回西部丘陵。通过将这些建筑彻底烧毁，部落消除了一个长期的威胁，并保卫了杜隆塔尔的西部边界，确保了剃刀岭与更广阔地区之间补给道路的安全。"}},faq={{q="谁会发布“入侵”任务？",a="该任务由驻扎在杜隆塔尔中部剃刀岭的兽人军官加索克发布。",al={"谁给予入侵任务","在哪儿接取入侵任务","入侵任务发布者"}},{q="为什么部落要在杜隆塔尔与剃刀鬃毛野猪人作战？",a="当兽人到达杜隆塔尔时，剃刀鬃毛野猪人占据了该地区的大部分领土。虽然部落击退了他们中的大多数，但仍有一些坚固的据点保留在剃刀岭以西，威胁着这个新兴兽人家园的安全和边境。",al={"为什么要在杜隆塔尔打野猪人","为什么要攻击剃刀鬃毛","杜隆塔尔的野猪人冲突"}},{q="剃刀鬃毛的营地在哪里？",a="剃刀鬃毛的营地位于剃刀岭以西。你只需寻找茂密的荆棘丛，就能轻松找到他们的领地。",al={"野猪人营地在哪里","如何找到剃刀鬃毛营地","入侵任务地点"}},{q="谁是剃刀鬃毛？",a="剃刀鬃毛是卡利姆多干旱平原上土生土长的一个敌对野猪人部族。他们建造防御性的荆棘窝，并激烈反抗部落在杜隆塔尔和贫瘠之地的定居。",al={"谁是剃刀鬃毛","剃刀鬃毛背景知识","什么是剃刀鬃毛"}},{q="野猪人被击败后会发生什么？",a="在完成该任务后，加索克会下令烧毁被清理过的野猪人荆棘窝和建筑，巩固部落对该地区的控制，并确保杜隆塔尔边境的安全。",al={"入侵任务之后会发生什么","入侵任务交接","野猪人营地的命运"}},{q="剃刀岭在这场冲突中扮演什么角色？",a="剃刀岭是杜隆塔尔中部的一个兽人要塞，它是试炼谷和奥格瑞玛之间的军事和后勤枢纽。",al={"剃刀岭在哪里","什么是剃刀岭"}}},fp="12,142,25.351.0,20.359.0,21.296.0,33.85.0,60.213.0,38.83.0,22.184.0,44.173.0,43.140.0"}
P.entries["quest:8373"] = {n="松木的力量",s="万圣节期间，哈特曼中士请你清除南海镇的被遗忘者臭气弹。松木香清洁剂能让村庄保持洁净。",h="万圣节期间，哈特曼中士请你清除南海镇的被遗忘者臭气弹。松木香清洁剂能让村庄保持洁净。",kw={"被遗忘者","万圣节","松木清洁剂","哈特曼中士","南海镇","臭气弹清洁剂","臭气弹"},ang={["faction:Alliance"]="作为一名联盟旅人，你可以帮助哈特曼中士清除南海镇的被遗忘者臭气弹，让这里保持洁净。"},sec={{t="南海镇的臭气",b="万圣节期间，被遗忘者用臭气弹袭击南海镇，把解放的庆典弄得臭气熏天。哈特曼中士请你用臭气弹清洁剂清除落在村里的臭气弹。"}},faq={{q="是谁让我清理臭气弹？",a="南海镇的哈特曼中士请你清除被遗忘者的臭气弹。",al={"谁给了我这个","哈特曼中士"}},{q="臭气弹在哪里？",a="臭气弹在南海镇。",al={"臭气弹位置","清理地点"}},{q="谁在南海镇使用臭气弹？",a="万圣节期间，被遗忘者在南海镇使用臭气弹。",al={"谁使用臭气弹","被遗忘者臭气弹"}},{q="清洁剂有什么作用？",a="臭气弹清洁剂借助松木的力量对抗恶臭。",al={"松木清洁剂","臭气弹清洁剂"}},{q="为什么要清理南海镇？",a="被遗忘者的臭气弹把南海镇的万圣节庆典弄得臭气熏天、一片狼藉。",al={"为何清理南海镇","万圣节臭气"}}},fp="17,148,20.213.0,40.74.0,26.34.0,35.65.0,25.54.0,32.93.0"}
P.entries["quest:8374"] = {n="Claiming Arathi Basin",s="阿拉希盆地外的一名联盟准将请你带来三枚 Arathi Basin Marks of Honor。这些奖章正是将军向你索要的物品。",h="阿拉希盆地外的一名联盟准将请你带来三枚 Arathi Basin Marks of Honor。这些奖章正是将军向你索要的物品。",kw={"联盟","联盟准将","阿拉希盆地","争夺阿拉希盆地","荣誉奖章"},ang={["faction:Alliance"]="作为联盟成员，你受命将三枚 Arathi Basin Marks of Honor 带给一名联盟准将。"},faq={{q="谁在索要这些奖章？",a="战场外的一名联盟准将请你带来三枚 Arathi Basin Marks of Honor。",al={"谁要奖章","准将"}},{q="需要多少枚荣誉奖章？",a="将军请你带来三枚 Arathi Basin Marks of Honor。",al={"需要多少枚奖章","三枚奖章"}},{q="我该把奖章交到哪里？",a="把奖章交给战场外的一名联盟准将。",al={"奖章交到哪里","交付奖章"}}},fp="21,153,23.108.0,35.64.0,27.75.0"}
P.entries["quest:8386"] = {n="Fight for Warsong Gulch",s="响应为战歌峡谷而战的号召，有助于保护灰谷的天然防线。你的努力让这些防线又能完好地维持一天。",h="响应为战歌峡谷而战的号召，有助于保护灰谷的天然防线。你的努力让这些防线又能完好地维持一天。",kw={"灰谷","防线","为战歌峡谷而战","天然防线","战歌峡谷"},sec={{t="灰谷的防线",b="在灰谷，你受命为战歌峡谷而战。你的行动让这片地区的天然防线又能完好地维持一天。"}},faq={{q="为什么要为战歌峡谷而战？",a="你的努力让灰谷的天然防线又能维持一天。",al={"战歌峡谷战斗","为何为战歌而战"}},{q="这有助于保护什么？",a="这场战斗让灰谷的天然防线又能完好地维持一天。",al={"什么防线","保护灰谷"}},{q="战歌峡谷在哪里？",a="战歌峡谷是一片战场，在灰谷与贫瘠之地之间形成了一道天然屏障。",al={"战歌位置","战歌峡谷在哪"}}},fp="23,125,20.128.0,28.72.0,28.73.0,23.96.0"}
P.entries["quest:8389"] = {n="战歌峡谷之战",s="部落请求你协助确保其对战歌峡谷的所有权。你的援助关系到部落在那里的主张。",h="部落请求你协助确保其对战歌峡谷的所有权。你的援助关系到部落在那里的主张。",kw={"战斗","主张","部落","所有权","战歌峡谷"},ang={["faction:Horde"]="作为部落的一员，你的援助有助于确保部落对战歌峡谷的所有权。"},sec={{t="部落的主张",b="部落对战歌峡谷的主张需要你的援助。你的帮助将支持部落对峡谷的所有权。"}},faq={{q="部落在这里想要什么？",a="部落希望确保其对战歌峡谷的所有权。",al={"战歌峡谷部落","部落主张","战歌峡谷归谁所有"}},{q="我该如何帮忙？",a="你的援助有助于确保部落对战歌峡谷的所有权。",al={"帮助部落","我在做什么","战歌峡谷之战"}},{q="部落为什么想要战歌峡谷？",a="现有记载称，部落希望确保其对战歌峡谷的所有权。",al={"为何要战歌峡谷","部落为何想要它","战歌峡谷的缘由"}}},fp="23,112,11.116.0,30.57.0,15.63.0,38.84.0"}
P.entries["quest:8393"] = {n="Claiming Arathi Basin",s="阿拉希盆地外的一名联盟准将请你带来三枚阿拉希盆地 Marks of Honor。这项请求中只提到了这些牌子。",h="阿拉希盆地外的一名联盟准将请你带来三枚阿拉希盆地 Marks of Honor。这项请求中只提到了这些牌子。",kw={"联盟","阿拉希盆地","准将","争夺阿拉希盆地","marks of honor"},ang={["faction:Alliance"]="作为联盟成员，你需要把三枚阿拉希盆地 Marks of Honor交给一名联盟准将。"},faq={{q="这位准将要你带来什么？",a="这位联盟准将请你带来三枚阿拉希盆地 Marks of Honor。",al={"阿拉希牌子","三枚牌子","要带什么"}},{q="我该把牌子交到哪里？",a="把牌子交给战场外的一名联盟准将。",al={"交到哪里","准将位置","在哪里交牌子"}},{q="谁在索要这些牌子？",a="战场外的一名联盟准将在索要这些牌子。",al={"谁要这些牌子","阿拉希将军","谁发布这个任务"}}},fp="21,155,40.83.0,27.75.0,28.75.0"}
P.entries["quest:8399"] = {n="Fight for Warsong Gulch",s="战场之外的一名联盟准将请你带来三枚 Marks of Honor。要响应号召，前往那里作战，就需要这些印记。",h="战场之外的一名联盟准将请你带来三枚 Marks of Honor。要响应号召，前往那里作战，就需要这些印记。",kw={"联盟","联盟准将","战斗","marks of honor","战歌峡谷"},ang={["faction:Alliance"]="作为一名联盟战士，你受命将 Marks of Honor 带给战场之外的一名联盟准将。"},sec={{t="准将的请求",b="战歌峡谷的印记正是战场之外的联盟准将向你索要之物。将三枚 Marks of Honor 交给准将，你在战歌峡谷的战斗便可计入联盟的战事。"}},faq={{q="联盟准将想要什么？",a="战场之外的联盟准将请你带来三枚 Marks of Honor。",al={"准将印记","需要什么印记"}},{q="我该把 Marks of Honor 交给谁？",a="将 Marks of Honor 交给战场之外的一名联盟准将。",al={"在哪里交印记","战歌峡谷印记位置"}},{q="需要多少枚 Marks of Honor？",a="你需要三枚战歌峡谷 Marks of Honor。",al={"需要多少枚印记","三枚印记"}}},fp="23,151,23.219.0,46.96.0,36.84.0,35.44.0"}
P.entries["quest:84"] = {n="比利的馅饼",s="“回到比利身边”是艾尔文森林中部斯通菲尔德家族与马科伦家族持续争斗中的一个环节。你已经收集齐了制作猪肉馅饼的配料，现在要将刚出炉的馅饼送回给年轻的比利·马科伦，以便套出关于波尼斯·斯通菲尔德姑妈丢失项链的消息。",h="“回到比利身边”是艾尔文森林中部斯通菲尔德家族与马科伦家族持续争斗中的一个环节。你已经收集齐了制作猪肉馅饼的配料，现在要将刚出炉的馅饼送回给年轻的比利·马科伦，以便套出关于波尼斯·斯通菲尔德姑妈丢失项链的消息。",kw={"回到比利身边","波尼斯·斯通菲尔德","比利·马科伦","艾尔文森林","马科伦农场","猪肉馅饼","斯通菲尔德农场","斯通菲尔德的项链"},ang={["faction:Alliance"]="即便是宁静的艾尔文森林也深受琐碎纠纷的困扰；处理那些互相争吵的人类农场主之间的矛盾，是旅行者帮助当地民众时的家常便饭。",["profession:Cooking"]="猪肉馅饼是艾尔文森林典型的农家舒适美食，是用森林里漫游的野猪肉制成的。"},sec={{t="苦涩的馅饼",b="斯通菲尔德家族与马科伦家族之间几代人的争吵让邻里间几乎没有任何温情可言。波尼斯·斯通菲尔德姑妈极不情愿地烤了这块猪肉馅饼，仅仅是因为如果不给年轻的比利·马科伦，他就拒绝透露关于她家传宝物的消息。即便在交出温热的馅饼时，她依然毫不掩饰自己的恼怒，叮嘱送信人告诉那个马科伦家的小子，她希望他每吃一口都会被噎住。"},{t="男孩的贿赂",b="马路对面的马科伦农场，比利·马科伦正饿着肚子等着，而且他的记忆力也恰到好处地“出了点问题”。这次交易凸显了分裂这两个农场的那种顽固而琐碎的争执，甚至连孩子们都学会了拿流言蜚语和偷来的小玩意儿来换取农场的美食。馅饼送到后，比利那模糊的记忆顿时清晰起来，这也引出了寻找项链下落的线索。"}},faq={{q="这次派送的目的是什么？",a="比利·马科伦声称知道波尼斯·斯通菲尔德姑妈丢失的项链在哪里，但在得到一块家常猪肉馅饼之前拒绝透露。派送馅饼满足了他的要求，以便他揭示传家宝的去向。",al={"为什么要送馅饼","比利想要什么","回到比利身边任务目标"}},{q="波尼斯姑妈为什么那么生比利的火？",a="斯通菲尔德家族和马科伦家族多年来一直陷入痛苦的农村争端之中。波尼斯很反感为了找回在他们两家边界丢失的传家宝，还得给一个令人头疼的马科伦小孩做点心吃。",al={"波尼斯为什么讨厌比利","斯通菲尔德和马科伦的争斗","为什么要让他被噎住"}},{q="比利说项链到底在哪里？",a="当比利狼吞虎咽地吃完馅饼后，他透露项链并不在他手里。相反，它落入了一个名为金牙的臭名昭著的狗头人手中，那个家伙正潜伏在法戈第矿洞里。",al={"项链在哪里","谁拿走了项链","金牙的关联"}},{q="比利·马科伦在哪里？",a="比利·马科伦位于马科伦农场，就在艾尔文森林中部马路的南侧，斯通菲尔德农场的对面。",al={"比利·马科伦的位置","比利在哪里","找到比利"}},{q="是谁烤了猪肉馅饼？",a="波尼斯·斯通菲尔德姑妈在斯通菲尔德农场烤了这块馅饼，在此之前你从附近的荒野收集了新鲜的野猪肉块。",al={"谁做了馅饼","馅饼厨师"}},{q="这个任务能解决两个家族之间的世仇吗？",a="不能。派送馅饼仅仅满足了比利个人的勒索。斯通菲尔德家族和马科伦家族成年人之间根深蒂固的敌意依然如故。",al={"世仇是否结束","斯通菲尔德和马科伦的和平"}}},fx={["6d42dc77"]={q="波尼斯老太太为什么派一个外人去应付比利？",a="斯通菲尔德家族和马科伦家族积怨已深，几乎不可能直接往来。波尼斯老太太根本不愿踏上马科伦家的土地，更别说亲自去伺候一个拿赃物索要食物的讨厌孩子了。路过的旅人正好可以充当中立的信使，穿过道路，送去馅饼，再从小比利嘴里问出真相，而不至于让这两户邻居大打出手。",al={"为什么派我回去找比利","波尼斯为什么不亲自去","波尼斯老太太为什么需要冒险者"}}},fp="13,218,12.304.0,13.343.1,37.224.0,42.209.0,46.131.1,31.124.0,29.135.0,54.122.0"}
P.entries["quest:840"] = {n="部落的新兵",s="“部落征召”是一项引导性的过渡任务，指引年轻的部落冒险者走出杜隆塔尔，进入贫瘠之地那广袤的荒野。该任务由剃刀岭西侧道路上的斥候塔克林·寻路者发起，指引新兵穿过怒水河，前往卡加尔·战痕的边境哨所。",h="“部落征召”是一项引导性的过渡任务，指引年轻的部落冒险者走出杜隆塔尔，进入贫瘠之地那广袤的荒野。该任务由剃刀岭西侧道路上的斥候塔克林·寻路者发起，指引新兵穿过怒水河，前往卡加尔·战痕的边境哨所。",kw={"贫瘠之地","部落征召","十字路口","卡加尔·战痕","剃刀岭","募兵信","怒水河","塔克林·寻路者"},ang={["faction:Horde"]="这次征召标志着一名战士从杜隆塔尔的本土守护者，转变成为卡利姆多各地部落领土的正式捍卫者。",["race:Orc"]="对于离开试炼谷和剃刀岭训练场的年轻兽人来说，响应卡加尔·战痕的号召是效忠大酋长过程中必不可少的成人礼。",["race:Troll"]="与兽人盟友并肩作战的暗矛巨魔利用这次部署来协助部落的扩张，并保卫濒临无尽之海的领土。"},sec={{t="跨越怒水河",b="一旦有志向的部落士兵在剃刀岭附近证明了自己的实力，整个国家的局势便需要他们向西进发。塔克林·寻路者驻守在离开杜隆塔尔的土路上，代表他的老友——老兵卡加尔·战痕考察过往的旅人。接受塔克林的募兵信，标志着新兵接到了在兽人新家园杜隆塔尔之外的第一个正式任务。"},{t="边境防御",b="桥那头的边境哨所横跨在杜隆塔尔的红色峡谷与贫瘠之地的干旱平原之间。卡加尔·战痕肩负着召集新兵守卫边疆的重任，但边境守卫工作仅仅是个开始。随着半人马、野猪人和联盟的远征军不断试探边境，急需人力被调往十字路口定居点。"}},faq={{q="我要把募兵信交给谁？",a="沿着杜隆塔尔剃刀岭外的西侧道路前行，穿过横跨怒水河的木桥。卡加尔·战痕就驻守在刚刚跨过边境、位于贫瘠之地一侧的部落哨塔上。",al={"我要去哪","卡加尔·战痕位置","任务交付位置"}},{q="塔克林·寻路者是谁？",a="塔克林·寻路者是一名驻扎在剃刀岭外西侧道路上的部落斥候。他充当着路上的耳目，负责发掘有能力的战士并将他们向西送往他的战友卡加尔·战痕处。",al={"塔克林的职责","谁给予任务","任务发布者"}},{q="卡加尔·战痕是谁？",a="卡加尔·战痕是一位粗犷的资深军官，负责管理贫瘠之地东部的岗哨。他会检查到来的志愿者，签署他们的征召文书，并将他们指引至大草原更深处，以支援十字路口。",al={"卡加尔是谁","战痕背景故事"}},{q="卡加尔签署信件后会发生什么？",a="卡加尔会收下信件，并立即通过任务“十字路口的征召”让你继续服役，指示你沿着主路向西进发，向十字路口的塞格拉·黑棘报到。",al={"下一个任务","完成“部落征召”后做什么","下一步去哪"}},{q="为什么部落要在贫瘠之地招募士兵？",a="贫瘠之地是连接奥格瑞玛与莫高雷的重要边境。随着凶猛的野猪人部落、半人马掠夺者以及趁机入侵的联盟威胁着补给线，部落需要每一双能战斗的手来确保道路的安全。",al={"为什么要征召","贫瘠之地的危险","为什么要招募"}},{q="联盟玩家可以接取这个任务吗？",a="不可以。该任务仅供从杜隆塔尔早期任务线过渡到贫瘠之地的部落成员接取。",al={"联盟能接吗","是否仅限部落"}}},fp="22,229,22.363.0,14.326.0,39.186.0,25.160.0,25.208.0,43.155.0,53.221.0,44.96.0"}
P.entries["quest:841"] = {n="另一个能量源？",s="加基森的首席工程师沙克斯·比格维兹还有更多的能源，如果你愿意支付十个废土游民水袋，他会再卖给你一个。",h="加基森的首席工程师沙克斯·比格维兹还有更多的能源，如果你愿意支付十个废土游民水袋，他会再卖给你一个。",kw={"比格维兹","加基森","能源","塔纳利斯","废土游民","水袋"},sec={{t="昂贵的替代品",b="首席工程师沙克斯·比格维兹推测在“止渴”任务中获得的第一块能源已经耗尽，或者可能遗失在了沙子里。不管原因如何，沙克斯·比格维兹手头还有更多的能源可以出售。这次的价格是十个废土游民水袋，因为现在世道艰难，能源又不是长在树上的。"}},faq={{q="为什么首席工程师沙克斯·比格维兹想要废土游民水袋？",a="沙克斯·比格维兹以十个废土游民水袋的价格出售另一块能源，并声称现在世道艰难。",al={"比格维兹 水袋","为什么需要水袋"}},{q="谁提供这个交换？",a="首席工程师沙克斯·比格维兹，他手头还有更多的能源可以出售。",al={"谁开启了又一个能源任务","能源任务提供者"}},{q="在需要另一块能源之前发生了什么？",a="这紧随“止渴”任务之后，你在该任务中首次为你的工具包获得了一块能源。",al={"又一个能源前置任务","之前的能源任务"}}},fp="21,108,20.225.0,68.132.0,25.83.0,52.84.0"}
P.entries["quest:842"] = {n="十字路口征兵",s="“十字路口征兵”将刚入伍的部落新兵从边境哨所直接派往贫瘠之地的腹地。冒险者带着卡加尔·战痕签过字的信，直接向位于关键战略枢纽“十字路口”的塞尔格拉·黑刺报到。",h="“十字路口征兵”将刚入伍的部落新兵从边境哨所直接派往贫瘠之地的腹地。冒险者带着卡加尔·战痕签过字的信，直接向位于关键战略枢纽“十字路口”的塞尔格拉·黑刺报到。",kw={"贫瘠之地","战痕","征兵","十字路口","黑刺","前沿哨所","卡加尔","塞尔格拉","萨尔"},ang={["class:Shaman"]="塞尔格拉·黑刺证明了萨尔领导下的部落中的萨满祭司不仅仅是神秘的顾问，还是关键战略哨所的直接军事指挥官和管理者。",["faction:Horde"]="这项任务是年轻的部落战士从家乡的安全港湾步入贫瘠之地充满争端的荒野时，所要经历的标准成人礼。",["race:Orc"]="卡加尔与塞尔格拉之间的交流凸显了萨尔重组后的部落中不断演变的社会动态，在这里，功绩和精神洞察力正在挑战传统的氏族观念和旧式的苦工模式。"},sec={{t="报到",b="在杜隆塔尔边界的前沿哨所向卡加尔·战痕证明了自己的价值后，新兵会收到一封签过字的募兵信并被派往西方。旅程沿着贫瘠之地干旱灌木丛中的土路前行，直至抵达中央路口。在这处被烈日炙烤的交叉路口坐落着十字路口，这是部落连接卡利姆多北部与南方荒野的关键后勤枢纽。"},{t="十字路口的萨满祭司",b="等待新兵到来的是塞尔格拉·黑刺，一位言辞犀利的兽人萨满祭司，她是大酋长萨尔亲自挑选出来负责管理十字路口事务的。尽管像卡加尔·战痕这样的老兵抱怨她很难相处且过于啰嗦，但萨尔对塞尔格拉评价极高。她性格刚烈、毫不妥协，经常提醒新兵，特别是那些傲慢的男性，在萨尔领导的部落中，女性战士和领袖拥有完全平等的地位，她绝不容忍任何无礼的行为。"}},faq={{q="谁指派我执行这个任务？",a="卡加尔·战痕，一位驻扎在杜隆塔尔与贫瘠之地交界桥梁以西前沿哨所的兽人老兵，他会指派给你这项任务。",al={"谁发布十字路口征兵任务","十字路口征兵任务发布者","卡加尔的任务"}},{q="塞尔格拉·黑刺在哪里？",a="塞尔格拉·黑刺驻扎在十字路口的中心，站在商队和信使汇聚的路口附近。",al={"塞尔格拉·黑刺位置","塞尔格拉在哪里","寻找塞尔格拉·黑刺"}},{q="为什么卡加尔会抱怨塞尔格拉？",a="卡加尔觉得塞尔格拉很烦人，称她是个令人讨厌的萨满祭司，总是在让人干活前啰嗦一大堆。尽管他个人对此感到恼火，但他还是尊重并执行大酋长萨尔派遣新兵向她报到的命令。",al={"为什么卡加尔不喜欢塞尔格拉","卡加尔与塞尔格拉","诅咒她"}},{q="为什么塞尔格拉对男性和女性角色的对话内容不同？",a="塞尔格拉·黑刺对萨尔在大酋长领导下的新部落中建立女性战士完全平等地位的法令深感自豪。她会热情地鼓励主动参军的女性新兵，同时警告男性新兵，她绝不容忍任何不敬或无礼的行为。",al={"塞尔格拉男女对话差异","塞尔格拉·黑刺对话","塞尔格拉平等地位"}},{q="我该走哪条路去十字路口？",a="从前沿哨所沿主路向西走，直到遇到一个丁字路口，然后左转并沿着南面的路直行，即可到达十字路口的定居点。",al={"如何前往十字路口","十字路口路线指引","前往十字路口的道路"}},{q="向塞尔格拉·黑刺报到后会发生什么？",a="一旦被塞尔格拉接纳，她就会征召你为十字路口效力，派你去协助处理当地的威胁、狩猎任务，以及贫瘠之地中部的哨所安保工作。",al={"十字路口征兵之后做什么","塞尔格拉的后续任务","贫瘠之地新兵后续"}}},fp="23,184,18.318.0,28.425.0,27.153.0,34.111.0,38.185.0,64.193.0,49.130.0,49.145.0"}
P.entries["quest:8426"] = {n="战歌峡谷之战",s="一名部落 Warbringer 要你带来三枚战歌峡谷荣誉奖章。这些奖章就是这项委托所需的凭证。",h="一名部落 Warbringer 要你带来三枚战歌峡谷荣誉奖章。这些奖章就是这项委托所需的凭证。",kw={"战场","部落","荣誉奖章","warbringer","战歌峡谷"},ang={["faction:Horde"]="作为部落的一员，你可以把战歌峡谷荣誉奖章交给一名部落 Warbringer。"},sec={{t="归还奖章",b="你将三枚战歌峡谷荣誉奖章带给战场外的一名部落 Warbringer。Warbringer 要的就是这些奖章，这项委托只需交付它们。"}},faq={{q="Warbringer 要什么？",a="部落 Warbringer 要你带来三枚战歌峡谷荣誉奖章。",al={"要什么奖章","warbringer想要什么","要带什么"}},{q="我该把奖章交给谁？",a="把奖章交给战场外的一名部落 Warbringer。",al={"warbringer在哪里","交还奖章","交到哪里"}},{q="需要几枚奖章？",a="Warbringer 要三枚战歌峡谷荣誉奖章。",al={"需要几枚奖章","奖章数量","三枚奖章"}}},fp="23,121,15.170.0,33.74.0,27.64.0,26.59.0"}
P.entries["quest:843"] = {n="加恩的报复",s="“加恩的复仇”是一个部落任务，由流浪的牛头人流亡者加恩·石塔在南贫瘠之地发布。加恩对巴尔莫丹的矮人考古挖掘驱逐了他的部落深感愤慨，他招募旅行者进行反击，屠杀该地点的工人并取回他们领袖的日记。",h="“加恩的复仇”是一个部落任务，由流浪的牛头人流亡者加恩·石塔在南贫瘠之地发布。加恩对巴尔莫丹的矮人考古挖掘驱逐了他的部落深感愤慨，他招募旅行者进行反击，屠杀该地点的工人并取回他们领袖的日记。",kw={"巴尔莫丹","贝尔丹","矮人挖掘场","加恩·石塔","卡兹戈姆","南贫瘠之地"},ang={["class:Shaman"]="巴尔莫丹的爆破和深层开沟伤害了周围的土元素，使加恩的行动成为清除元素动乱的必要手段。",["faction:Horde"]="巴尔莫丹代表了卡利姆多领地深处的一个防御森严的联盟据点，这使得保卫加恩的领地既是一种荣誉行为，也是一种战略遏制。",["race:Tauren"]="对于舒哈鲁来说，加恩的困境令人愤怒地提醒着人们：联盟是多么不尊重大地母亲，竟然使用炸药和铁齿轮来撕裂祖先的墓地。"},sec={{t="流离失所的部落",b="在勘探员的火炮和镐头破坏这片土地之前，贫瘠之地南部的红色断崖曾是加恩·石塔部族的祖居地和狩猎场。当矮人从铁炉堡赶来建立巴尔莫丹时，牛头人遭到暴力驱逐或杀害，以便为巨大的采石场和沟渠腾出空间。在和平抗议被无视、外交手段用尽的情况下，加恩现在独自走在南部的道路上，为他阵亡的族人策划一场血腥的报复。"},{t="巴尔莫丹的废墟",b="巴尔莫丹的矮人行动对这片土地及其守护者毫无怜悯。在勘探员卡兹戈姆的领导下，探险队用蒸汽机和重型炸药炸开山坡，深入地下挖掘。加恩的任务简单而坚定：削减正在破坏神圣土地的贝尔丹挖掘者和工头的数量，杀死卡兹戈姆本人，并夺取勘探员的个人挖掘笔记，以查明这些联盟入侵者到底在寻找什么。"}},faq={{q="谁是加恩·石塔？",a="加恩·石塔是一位孤独的牛头人幸存者，他的部落曾经居住在南贫瘠之地。在矮人挖掘者驱逐了他的族人并杀害反抗者后，加恩开始徘徊在南部公路上，寻求正义并对入侵的联盟挖掘场进行报复。",al={"加恩","谁发布加恩的复仇","加恩·石塔背景故事"}},{q="为什么矮人在贫瘠之地？",a="这些矮人是来自铁炉堡的贝尔丹探险队，他们在南贫瘠之地的巴尔莫丹建立了一座堡垒和一个挖掘场。他们的爆破和嘈杂的挖掘机器撕裂了山丘，完全无视当地的牛头人居民。",al={"为什么矮人在巴尔莫丹","巴尔莫丹的目的","贫瘠之地的铁炉堡"}},{q="谁是勘探员卡兹戈姆？",a="勘探员卡兹戈姆是负责指导巴尔莫丹堡垒以南挖掘场行动的矮人领袖。加恩认为他对亵渎祖居地负有直接责任，并要求获得他的日记作为他死亡的证据。",al={"卡兹戈姆","勘探员卡兹戈姆","巴尔莫丹领袖"}},{q="在哪里可以找到加恩·石塔？",a="加恩·石塔在远南贫瘠之地的道路上徘徊，位于巴尔莫丹堡垒以西，通往升降梯和千针石林的道路以北。",al={"加恩的位置","寻找加恩","加恩在哪里"}},{q="加恩是否尝试过和平解决此事？",a="是的。加恩明确表示，他曾尝试通过外交途径阻止对其祖居地的破坏，但矮人无视了这些努力，继续炸开山丘，迫使他诉诸暴力。",al={"牛头人尝试过外交吗","加恩的外交"}},{q="完成这个任务后会发生什么？",a="在收到卡兹戈姆的日记后，加恩会研究其中的笔记以了解矮人的技术和计划，从而直接引出旨在破坏其重型机械的任务链“加恩的复仇”。",al={"加恩的复仇后的下一个任务","加恩的后续任务"}}},fp="18,202,17.379.0,23.355.0,23.270.0,35.238.0,27.190.0,35.163.0,40.195.0,30.158.1"}
P.entries["quest:8431"] = {n="战歌峡谷之战",s="部落力求确保自己对战歌峡谷的所有权。你的帮助将助其巩固这一主张。",h="部落力求确保自己对战歌峡谷的所有权。你的帮助将助其巩固这一主张。",kw={"战斗","峡谷","部落","所有权","战歌峡谷"},ang={["faction:Horde"]="你帮助部落确保其对战歌峡谷的所有权。"},sec={{t="峡谷归属之争",b="部落对战歌峡谷的所有权岌岌可危，你正贡献力量，帮助部落巩固所有权。你的努力有助于确保部落继续拥有这片峡谷。"}},faq={{q="战歌峡谷发生了什么？",a="部落正努力确保自己对战歌峡谷的所有权。",al={"战歌峡谷之战","峡谷里发生了什么"}},{q="我在帮助谁？",a="你正在帮助部落确保其对战歌峡谷的所有权。",al={"谁在寻求帮助","这是在帮助哪一方"}},{q="部落想要什么？",a="部落力求继续拥有战歌峡谷。",al={"部落的目标","为何在战歌峡谷作战"}}},fp="23,88,20.153.0,35.62.0,17.64.0,25.55.0"}
P.entries["quest:844"] = {n="平原陆行鸟的威胁",s="“陆行鸟的威胁”是十字路口的一项新手狩猎任务，由塞尔格拉·黑棘指派。刚抵达的部落冒险者会被派去捕杀那些翻找补给路线物资的本土陆行鸟，这既是为了除害，也是对狩猎技巧的初步考验。",h="“陆行鸟的威胁”是十字路口的一项新手狩猎任务，由塞尔格拉·黑棘指派。刚抵达的部落冒险者会被派去捕杀那些翻找补给路线物资的本土陆行鸟，这既是为了除害，也是对狩猎技巧的初步考验。",kw={"贫瘠之地","喙","十字路口","黑棘","狩猎","陆行鸟","塞尔格拉","补给"},ang={["class:Hunter"]="对于年轻的猎人来说，塞尔格拉的试炼是在广阔的草原上进行跟踪、追踪和击倒猎物的一项基本准则。",["faction:Horde"]="十字路口是一个重要的后勤枢纽，确保其食品补给不受野生动物的侵害，能保证部落在卡利姆多保持立足点。",["race:Orc"]="兽人崇尚狩猎纪律，塞尔格拉希望每一位新人在承担更重要的职责之前，都能在当地野兽身上证明自己的勇气。"},sec={{t="保卫十字路口",b="十字路口位于卡利姆多的后勤中心，协调着穿梭于贫瘠之地艰苦环境下的补给大篷车。然而，干旱的地形使得当地野生动物极度缺乏食物。成群高大、不会飞行的陆行鸟在哨所东侧游荡，开始啄食食品板条箱，威胁着定居点的生命线。为了保护这些脆弱的补给，萨满祭司塞尔格拉·黑棘派遣旅行者在这些凶猛的鸟类对哨所物资造成严重损害前将它们除掉。"},{t="初次狩猎",b="虽然害虫治理是一个直接的实际目标，但塞尔格拉认为陆行鸟是衡量新手的标尺。她认为这些鸟只是简单的猎物，旨在教导年轻的猎人如何在恶劣环境中生存，以及如何在被太阳炙烤的平原上追踪猎物。带回它们的陆行鸟的喙证明了猎人拥有面对贫瘠之地更凶猛野兽所需的耐心和基本的武力技巧。"}},faq={{q="为什么要针对陆行鸟？",a="十字路口东侧成群的陆行鸟变得胆大妄为，开始袭击食物补给并骚扰过往的补给线。塞尔格拉·黑棘下令捕杀它们，以保护定居点至关重要的补给。",al={"为什么要杀陆行鸟","陆行鸟问题","陆行鸟做了什么"}},{q="塞尔格拉·黑棘是谁？",a="塞尔格拉·黑棘是一位驻扎在十字路口的资深兽人萨满祭司。她负责监督定居点的狩猎试炼，训练新来的冒险者，并指挥他们对付威胁部落行动的野生猛兽。",al={"塞尔格拉是谁","塞尔格拉·黑棘的职责","十字路口任务发布者"}},{q="为什么塞尔格拉特别想要它们的喙？",a="坚硬锋利的陆行鸟的喙是陆行鸟的主要武器和觅食工具。取走它们的喙可以作为这些食腐鸟类已被杀死的无可辩驳的证据。",al={"为什么要陆行鸟的喙","陆行鸟的喙作为证明"}},{q="这次狩猎之后有什么？",a="一旦处理了陆行鸟，塞尔格拉就会让你去猎杀在平原上游荡的斑马，以此来测试你对付更敏捷、更具活力的猎物的能力。",al={"接下来是什么","陆行鸟任务后的下一个任务","狩猎顺序"}},{q="这些陆行鸟在哪里？",a="它们在十字路口正东和东南方向的稀树草原上游荡，沿着贸易路线觅食。",al={"陆行鸟在哪里","陆行鸟位置","狩猎场"}},{q="这是更大狩猎系列的一部分吗？",a="是的。这项任务标志着塞尔格拉·黑棘在贫瘠之地的狩猎试炼的起点，试炼难度将随着在草原上挑战越来越危险的野兽而逐渐升级。",al={"贫瘠之地狩猎链","塞尔格拉任务链"}}},fp="19,188,23.286.0,14.345.0,35.186.0,24.201.0,46.142.0,27.107.0,38.111.0,40.150.0"}
P.entries["quest:845"] = {n="斑马的威胁",s="斑马是十字路口的一位叫塞尔格拉·黑刺的NPC发布的一项早期狩猎试炼。作为在贫瘠之地的草原上进行武技磨练的一部分，年轻的猎手们需要追踪敏捷的斑马跑者，并取回它们强有力的斑马蹄。",h="斑马是十字路口的一位叫塞尔格拉·黑刺的NPC发布的一项早期狩猎试炼。作为在贫瘠之地的草原上进行武技磨练的一部分，年轻的猎手们需要追踪敏捷的斑马跑者，并取回它们强有力的斑马蹄。",kw={"贫瘠之地","十字路口","斑马蹄","狩猎试炼","塞尔格拉·黑刺","斑马","斑马跑者"},ang={["class:Hunter"]="对于刚在贫瘠之地开始历练的射手和追踪者来说，潜行靠近敏捷的斑马群是进行追踪和精准射击的必要实地练习。",["faction:Horde"]="十字路口依赖来往的冒险者来控制周边的野生动物数量，以确保定居点的补给路线畅通无阻。",["race:Tauren"]="塞尔格拉特别指出，斑马的一踢就能将一头成年牛头人踢倒，这让这项试炼成为一个恰当的提醒：即使是草原上的食草动物也需要保持敬畏。"},sec={{t="草原上的进阶之路",b="在初步清理了贫瘠之地中那些泛滥的平原陆行鸟之后，塞尔格拉·黑刺会将新晋的部落勇士引向难度稍高的猎物。条纹斑马成群结队地游荡在北部和南部的平原上。虽然它们并非草原上的顶级掠食者，但这些奔跑迅速的群居野兽以其顽强的耐力和能踢碎骨头的强力踢击而闻名。"},{t="黑刺的试炼",b="对塞尔格拉来说，这次狩猎与其说是为了获取贸易物资，不如说是为了考验冒险者不断增长的实力。她要求取回四只完整的斑马蹄作为猎杀的实物证明，并警告说这种野兽的后踢力足以将一头成年牛头人踢翻在地。在这些敏捷的奔跑者面前证明自己，能让猎手获得参与后续挑战那些平原掠食者任务的资格。"}},faq={{q="谁发布了这次狩猎任务？",a="塞尔格拉·黑刺，一位驻扎在贫瘠之地中部十字路口的资深兽人萨满，发布了这项试炼来考验日益强大的部落勇士。",al={"谁发布斑马任务","斑马任务发布者","塞尔格拉·黑刺任务"}},{q="在哪里可以找到斑马？",a="斑马跑者在贫瘠之地中部的十字路口南北两侧的开阔平原上游荡。",al={"斑马跑者在哪里","斑马位置","贫瘠之地斑马地图"}},{q="塞尔格拉为什么要斑马蹄？",a="斑马蹄是干净利落完成狩猎的战利品证明。它们的腿部力量惊人，带回四只蹄子证明猎手可以制服一头足以击倒强壮牛头人的野兽。",al={"为什么需要斑马蹄","斑马蹄证明","为什么狩猎斑马"}},{q="这个任务之后是什么？",a="在证明了你对抗斑马的能力后，塞尔格拉会让你在“贫瘠之地的掠食者”任务中挑战真正的掠食者。",al={"斑马任务后的下一个任务","斑马任务后续","黑刺的下一个任务"}},{q="斑马危险吗？",a="虽然通常是温顺的食草动物，但斑马拥有惊人的腿部力量。塞尔格拉警告说，受到惊吓或走投无路的斑马跑者踢出的一脚，足以将一头强壮的牛头人踢翻在地。",al={"斑马有多危险","斑马危险性","斑马踢击"}},{q="为什么之前要猎杀平原陆行鸟？",a="塞尔格拉将她的试炼安排为难度循序渐进的过程。平原陆行鸟作为最初的打靶练习，而斑马则要求在进阶到好斗的草原掠食者之前，应对更快速、更强壮的猎物。",al={"上一个任务","平原陆行鸟的威胁关联"}}},fp="10,144,24.232.0,23.248.0,22.129.0,27.93.0,35.145.0,28.116.0,22.164.0,42.169.0"}
P.entries["quest:846"] = {n="加恩的报复",s="加恩的复仇是南贫瘠之地的一个部落任务，在那儿，悲痛的牛头人流亡者加恩·石塔正计划向巴尔莫丹探险队进行报复。在除掉勘探员卡兹格姆后，加恩指引旅行者潜入这座矮人要塞，收集挥发性的弹药，准备进行一场爆炸性的反击。",h="加恩的复仇是南贫瘠之地的一个部落任务，在那儿，悲痛的牛头人流亡者加恩·石塔正计划向巴尔莫丹探险队进行报复。在除掉勘探员卡兹格姆后，加恩指引旅行者潜入这座矮人要塞，收集挥发性的弹药，准备进行一场爆炸性的反击。",kw={"巴尔莫丹","贫瘠之地","炸药","爆炸物","加恩·石塔","铁炉堡","卡兹格姆","硝化甘油","硝酸钠","木浆"},ang={["faction:Horde"]="消除南贫瘠之地的矮人行动，可以防止联盟建立军事滩头阵地，切断莫高雷、十字路口和南部边境之间的交通。",["profession:Engineering"]="硝化甘油、硝酸钠和木浆的组合展示了典型的矮人工业炸药配方，并被临时改装用于非对称作战。",["race:Tauren"]="对牛头人来说，巴尔莫丹代表了对地母神的严重伤害，这使得破坏矮人的机器成为了一项精神和领土上的职责。"},sec={{t="以其人之道还治其人之身",b="勘探员卡兹格姆的死让巴尔莫丹挖掘场遭受了挫折，但加恩·石塔知道这只是暂时的。矮人的行动很少会长期停滞，很快就会有新的工头到来，继续监管那些正在摧毁他祖辈领地的机器。加恩拒绝坐视大地继续遭受挖掘，他决心利用侵略者自己的技术进行反击。他计划将他们的爆破装备变成破坏工具，从内部摧毁他们的堡垒。"},{t="突袭要塞",b="巴尔莫丹要塞既是挖掘基地，也是加固的驻军营地，配备了士兵、火枪手和军官，以保卫矮人在贫瘠之地的利益。加恩发现，守军储存了适合工业爆破的材料：硝化甘油、木浆和硝酸钠。他派遣部落盟友潜入外围，直接从矮人守军手中夺取这些挥发性成分，收集足够的原材料来组装一个毁灭性的炸药包。"}},faq={{q="加恩·石塔为什么要寻求复仇？",a="巴尔莫丹的铁炉堡矮人占领了加恩祖辈的家园，玷污了土地，并将他的族人驱逐出去，从而建立了他们的挖掘场。在杀死了首席勘探员并找回他的日志后，加恩旨在永久停止他们持续的破坏行为。",al={"加恩愤怒的原因","加恩·石塔的动机","矮人对加恩做了什么"}},{q="在哪里可以找到爆炸材料？",a="这些配料由保卫巴尔莫丹的矮人人员携带。南贫瘠之地加固挖掘场内外的火枪手、士兵和军官都携带着硝化甘油药剂瓶、木浆包和硝酸钠样本。",al={"哪里可以获得硝化甘油","如何获得木浆","硝酸钠在哪里"}},{q="为什么加恩需要木浆和化学品？",a="矮人的挖掘图纸显示，用木浆稳定不稳定的硝化甘油，并将其与硝酸钠混合，可以产生一种可靠的工业炸药。加恩打算制作一种定制的爆破装药，用以炸毁矮人的关键设施。",al={"为什么要木浆","加恩在制造什么","加恩的炸弹原料"}},{q="收集完补给品后会发生什么？",a="一旦你带回了原材料，加恩就会组装一个爆炸装药，并指派你去用它炸毁巴尔莫丹挖掘场里的矮人飞行器，那是该设施基础设施的关键部分。",al={"加恩的复仇之后是什么","收集完材料之后"}},{q="为什么杀了卡兹格姆并不能终结矮人的威胁？",a="卡兹格姆只是首席勘探员。巴尔莫丹的矮人军事存在已经根深蒂固，有防御墙和补给线加固。除非整个基地遭受毁灭性打击，否则铁炉堡只会派另一个工头来继续挖掘。",al={"为什么杀掉卡兹格姆没用","巴尔莫丹被阻止了吗"}},{q="巴尔莫丹对部落构成了怎样的战略威胁？",a="虽然其要塞最初是为保卫挖掘场而建，但巴尔莫丹已经扩张成了一个拥有重兵把守的联盟堡垒。它位于南贫瘠之地的贸易路线旁，对附近的卡利姆多部落定居点构成了活跃的军事威胁。",al={"部落为什么要关心巴尔莫丹","巴尔莫丹的威胁"}}},fp="15,210,29.372.0,16.376.0,39.259.0,40.216.0,43.251.0,42.200.1,52.222.0,51.231.0"}
P.entries["quest:847"] = {n="迅猛龙的狡诈",s="在托尔甘的宝珠赋予了戈穆尔迅猛龙的精华后，他所感受到的力量让他开始思考萨满祭司的魔法。他让你去告诉托尔甘，他暂时被说服了，并且愿意听听看。",h="在托尔甘的宝珠赋予了戈穆尔迅猛龙的精华后，他所感受到的力量让他开始思考萨满祭司的魔法。他让你去告诉托尔甘，他暂时被说服了，并且愿意听听看。",kw={"阿拉希高地","戈穆尔","迅猛龙的狡诈","落锤镇","萨满祭司","托尔甘"},sec={{t="被说服的战士",b="戈穆尔大声思索着在他体内奔涌的力量是否就是托尔甘试图展示给他的萨满祭司之力。他觉得这很有意思。他让你去告诉托尔甘，他暂时被说服了，并且愿意听听托尔甘要说什么。"},{t="托尔甘的答复",b="托尔甘说一旦附魔效果消失，他就会与戈穆尔交谈。他感谢你帮助戈穆尔重获新生，并相信戈穆尔也会心存感激。"}},faq={{q="是谁派你去和托尔甘交谈的？",a="是戈穆尔。在感受到宝珠的力量后，他让你去告诉托尔甘，他暂时被说服了。",al={"谁开启了迅猛龙的狡诈3","谁发布了这个任务","任务起始地点"}},{q="为什么戈穆尔改变了对托尔甘的看法？",a="他想知道自己感受到的力量是否就是托尔甘试图展示给他的萨满祭司之力，他觉得这很有趣。他暂时被说服了，愿意听听托尔甘的说法。",al={"为什么戈穆尔改变了主意","戈穆尔萨满魔法","戈穆尔被说服了吗"}},{q="这一步之前发生了什么？",a="这是在你将托尔甘的宝珠带给戈穆尔之后进行的步骤。",al={"前置任务","迅猛龙的狡诈先决条件"}}},fp="19,142,19.218.0,15.169.1,36.115.0,47.176.0,27.57.0"}
P.entries["quest:848"] = {n="菌类孢子",s="皇家药剂师学会的药剂师赫布瑞姆派遣部落冒险者在贫瘠之地的各处绿洲收集菌类孢子。这些泉水中流动的奇异变异能量将当地植物转化为了强效试剂。赫布瑞姆试图收集这些独特的样本，为他在雷霆崖的同事酿制药剂。",h="皇家药剂师学会的药剂师赫布瑞姆派遣部落冒险者在贫瘠之地的各处绿洲收集菌类孢子。这些泉水中流动的奇异变异能量将当地植物转化为了强效试剂。赫布瑞姆试图收集这些独特的样本，为他在雷霆崖的同事酿制药剂。",kw={"药剂师赫布瑞姆","药剂师扎玛","贫瘠之地","十字路口","遗忘之池","菌类孢子","甜水绿洲","皇家药剂师学会","死水绿洲"},ang={["class:Druid"]="这些绿洲蕴含着一股极不寻常的狂暴自然魔法，导致周围的生态系统发生了剧烈的变异。",["faction:Horde"]="调查贫瘠之地受干扰的水域有助于保护连接奥格瑞玛、十字路口和雷霆崖的重要路线。",["profession:Herbalism"]="生长在贫瘠之地绿洲周围的多产蘑菇展示了环境能量的突然注入是如何将普通植物转化为强效试剂的。",["race:Undead"]="即使远离洛丹伦，被遗忘者的研究人员依然在继续他们的炼金工作，利用卡利姆多的自然异常现象来实现皇家药剂师学会的目标。"},sec={{t="充满活力且变异的植物",b="贫瘠之地通常是一片干旱、被烈日炙烤的热带草原，但其绿洲——例如遗忘之池、甜水绿洲和死水绿洲——却充满了非自然的活力。一股奇异的生命能量从这些水中流出，扭曲并增强了饮用这些水的植物和野兽。生长在泥泞岸边的多产蘑菇吸收了这些强烈的能量流，使它们的孢子充满了稀有的特性，引起了路过炼金术士的好奇。"},{t="卡利姆多的皇家药剂师学会",b="尽管药剂师赫布瑞姆驻扎在远离幽暗城的十字路口，但他依然致力于皇家药剂师学会的研究。他认识到了卡利姆多本土试剂的奇异效力，于是收集这些变异孢子来调制强力混合剂。这里收集的样本将送往雷霆崖的药剂师扎玛手中，这展现了被遗忘者在盟友领地中进行的深远而隐秘的科学研究。"}},faq={{q="这些菌类孢子生长在哪里？",a="这些孢子可以从贫瘠之地各绿洲水边生长的多产蘑菇上采集，包括遗忘之池、甜水绿洲和死水绿洲。",al={"菌类孢子位置","菌类孢子获取地点","多产蘑菇位置"}},{q="为什么绿洲附近的蘑菇发生了变异？",a="一股强大的生命能量流经贫瘠之地的绿洲水域。这种能量并非维持正常的植物生长，而是强力地刺激并改变了周围的野生动物和植物。",al={"蘑菇为何变异","绿洲生命能量","绿洲异常原因"}},{q="药剂师赫布瑞姆是谁？",a="药剂师赫布瑞姆是被遗忘者皇家药剂师学会的一名成员，驻扎在贫瘠之地的十字路口。他研究该地区不寻常的生物学特性，并采集当地材料用于炼金研究。",al={"赫布瑞姆背景故事","赫布瑞姆是谁","十字路口的药剂师"}},{q="赫布瑞姆打算用这些孢子做什么？",a="赫布瑞姆利用这些强效孢子调制一种特定的混合剂，并打算将其送给他在牛头人城市雷霆崖的研究伙伴——药剂师扎玛。",al={"孢子的用途","菌类孢子的目的"}},{q="为什么被遗忘者的药剂师会在贫瘠之地活动？",a="作为部落联盟的一部分，被遗忘者的研究人员会研究卡利姆多各地的陌生环境和独特植物，以发现用于药物、毒药和混合剂的新试剂。",al={"亡灵为何在贫瘠之地","卡利姆多的皇家药剂师学会"}},{q="从哪个绿洲采集孢子最安全？",a="位于十字路口西北方向的遗忘之池，相比南边的甜水绿洲或死水绿洲，其野生生物等级较低，因此是采集蘑菇最安全的地方。",al={"最简单的孢子采集地","贫瘠之地最安全的绿洲"}}},fp="13,297,25.365.0,40.385.0,34.129.0,45.170.0,26.205.0,45.124.0,55.155.0,49.175.0"}
P.entries["quest:849"] = {n="加恩的报复",s="“加恩的复仇”标志着加恩·石塔对巴尔莫丹的矮人实施的最后一次打击。部落的一名特工带着一份根据窃取的矮人图纸制造的定制炸药，被委派去炸毁探险队引以为傲的飞行器，以此为覆灭的石塔部族复仇。",h="“加恩的复仇”标志着加恩·石塔对巴尔莫丹的矮人实施的最后一次打击。部落的一名特工带着一份根据窃取的矮人图纸制造的定制炸药，被委派去炸毁探险队引以为傲的飞行器，以此为覆灭的石塔部族复仇。",kw={"巴尔莫丹","加恩的雷管","飞行器","加恩·石塔","卡兹格姆","石塔部族","贫瘠之地","雷霆崖"},ang={["faction:Horde"]="破坏巴尔莫丹的飞行器可以解除联盟一种能够深入侦察和打击南贫瘠之地的空中武器。",["profession:Engineering"]="用于飞行器的炸药是利用铁炉堡的蓝图针对旋翼机制造的，这是一次充满讽刺意味的战地破坏杰作。",["race:Tauren"]="通过摧毁矮人的战争机器来为石塔氏族复仇，这能引起任何保卫祖传家园免遭亵渎的牛头人的深刻共鸣。"},sec={{t="统治的象征",b="巴尔莫丹的挖掘行动不仅仅是一次侵入性的采矿作业，它还是一座武装堡垒，直接建立在流离失所的石塔牛头人祖传的土地之上。对于探矿者们的作战范围和军事实力而言，他们的旋翼机飞行器是关键所在。这架机械飞行器驻扎在挖掘场上方的哨塔上，负责监视周围的贫瘠之地，保护补给线，并作为联盟悍然入侵卡利姆多土地的空中象征。"},{t="以彼之道，还施彼身",b="在找回了探矿者卡兹格姆的图纸后，加恩·石塔制作了一种名为“加恩的雷管”的特殊炸药。通过将这种易爆的弹药安放在飞行器上，加恩确保了矮人的技术傲慢将成为导致他们失败的原因。随之而来的爆炸摧毁了一个重要的军事资产，给巴尔邓小队造成了羞辱性的打击，并告慰了覆灭部族的英灵。"}},faq={{q="为什么加恩专门要摧毁那架飞行器？",a="这架飞行器既是战争武器，也是巴尔莫丹基础设施的关键部分，为矮人提供了空中侦察能力。对于加恩来说更重要的是，它是矮人权力的鲜明标志，更是高耸在屠戮他部族的故土之上的羞辱性存在。",al={"为什么要摧毁旋翼机","飞行器的用途","为什么要以飞行器为目标"}},{q="飞行器位于巴尔莫丹的什么位置？",a="飞行器停在通往主要挖掘坑的坡道中途的一个木制塔台上，而不是位于矮人的主要堡垒内部或旁边。",al={"飞行器在哪里","飞行器的位置","巴尔莫丹旋翼机的位置"}},{q="加恩是如何制造这个爆炸装置的？",a="加恩利用最近从探矿者卡兹格姆那里找回的技术图纸和工程规划，制造了加恩的雷管，将矮人自己的设计转而用来对付他们。",al={"炸药是如何制造的","加恩的雷管的来源","卡兹格姆的爆炸图纸"}},{q="加恩属于哪个部族？",a="加恩属于石塔部族，这是一个历史上居住在南贫瘠之地的牛头人氏族，直到铁炉堡的矮人挖掘队暴力驱逐了他们并摧毁了他们的定居点。",al={"加恩所属部族","石塔部族是什么","石塔牛头人是谁"}},{q="摧毁这架机器能永久停止挖掘吗？",a="这严重削弱了巴尔莫丹的空中优势和基础设施，同时也让加恩完成了个人复仇，但那些盘踞在此的矮人挖掘者和他们的堡垒仍然是联盟在该地区的一个活跃据点。",al={"巴尔莫丹停止挖掘了吗","巴尔莫丹会陷落吗","加恩成功了吗"}},{q="完成这个任务后，加恩会给予什么认可？",a="加恩宣称，摧毁了飞行器的英雄将在雷霆崖受到崇敬，被视为神圣的牛头人土地的捍卫者和他覆灭部族的永恒勇士。",al={"加恩任务完成","加恩任务结束","加恩说了什么"}}},fp="15,139,22.352.0,22.343.1,62.197.0,50.143.0,41.172.0,31.181.0,60.216.0,61.156.1"}
P.entries["quest:85"] = {n="丢失的项链",s="“丢失的项链”是艾尔文森林南部的一个入门级任务，由波尼斯·斯通菲尔德姑妈发布。波尼斯怀疑是对头的那个淘气的孩子偷走了她的项链，于是派遣冒险者穿过马路去质问比利·马科伦，并找回她遗失的传家宝。",h="“丢失的项链”是艾尔文森林南部的一个入门级任务，由波尼斯·斯通菲尔德姑妈发布。波尼斯怀疑是对头的那个淘气的孩子偷走了她的项链，于是派遣冒险者穿过马路去质问比利·马科伦，并找回她遗失的传家宝。",kw={"波尼斯","比利","艾尔文","农场","马科伦","项链","斯通菲尔德","葡萄园"},ang={["faction:Alliance"]="对于在艾尔文森林开始职业生涯的联盟新手来说，调解斯通菲尔德和马科伦这两家吵架不断的邻居之间的琐事，是体验当地边境生活的一个缩影。",["race:Human"]="斯通菲尔德和马科伦之间的积怨表明，暴风城的冲突并非都来自迪菲亚盗贼或豺狼人战团；老派的乡村邻里纠纷同样根深蒂固。"},sec={{t="邻里的指责",b="斯通菲尔德和马科伦两家在艾尔文森林南部毗邻而居，但两家之间的关系十分冷淡。当波尼斯·斯通菲尔德姑妈发现她珍贵的项链不见了时，她毫不犹豫地指责是对头家的那个小儿子干的。这位满腹怨气的寡妇坚信是小比利·马科伦溜进她的农场偷走了首饰，于是请求过路的旅行者去葡萄园找到那个男孩，并要求他交还物品。"},{t="贪吃的男孩",b="在隔壁的葡萄园找到比利·马科伦后，事情很快变得复杂起来。比利愤愤不平地否认他偷了项链，声称自己不是小偷。不过，他露出了狡黠的笑容，暗示他可能知道这件首饰的下落——前提是得先有人能填饱他那咕咕叫的肚子，送来一个新鲜的猪肉馅饼。"}},faq={{q="波尼斯·斯通菲尔德姑妈是谁？",a="波尼斯·斯通菲尔德姑妈是一位住在艾尔文森林南部斯通菲尔德农场的老寡妇。她对邻居马科伦一家深表怀疑，尤其是他们那个爱惹麻烦的小儿子比利。",al={"波尼斯姑妈是谁","波尼斯·斯通菲尔德","谁发布丢失的项链任务"}},{q="比利·马科伦真的偷了项链吗？",a="当被质问时，比利断然否认自己是个小偷。他暗示自己可能知道是谁拿走了项链，但他拒绝在吃饱之前透露这个秘密。",al={"比利是小偷吗","是比利偷的吗","比利拿走项链了吗"}},{q="我在哪里能找到比利·马科伦？",a="比利·马科伦通常在马科伦农场的葡萄藤间游荡，那里就在斯通菲尔德农场穿过马路往东一点的地方。",al={"比利·马科伦位置","比利在哪里","寻找比利·马科伦"}},{q="为什么斯通菲尔德一家和马科伦一家互相厌恶？",a="这两家邻居多年来一直陷入一场激烈的乡村世仇之中。双方因财产、自尊和长期积怨而关系紧张，导致彼此总是第一时间把对方往坏处想。",al={"家庭世仇","斯通菲尔德和马科伦的积怨","他们为什么互相讨厌"}},{q="与比利·马科伦交谈后会发生什么？",a="比利坚持说他饿得想不起来项链去哪儿了，这会让你回去找波尼斯姑妈做一个猪肉馅饼来交换情报。",al={"接下来做什么","丢失的项链后续","下一个任务"}},{q="这个任务发生在哪里？",a="任务完全发生在艾尔文森林南部，需要在斯通菲尔德农场和邻近的马科伦农场之间往返。",al={"任务区域","丢失的项链在哪里"}}},fx={b7900c48={q="波尼斯老太太为什么想找回项链？",a="波尼斯老太太是一位年迈的寡妇，那条项链是她极为珍视的私人物品。项链丢失让她十分苦恼，她立刻怀疑是隔壁仇家的小比利·马科伦偷走了它。找回这件传家宝，能让一位年迈的寡妇重获安心，心中得到些许温暖。",al={"波尼斯为什么要项链","波尼斯要项链的动机","斯通菲尔德项链的重要性"}},["27b02d6f"]={q="波尼斯老太太为什么不亲自找比利·马科伦对质？",a="斯通菲尔德和马科伦家族两家的积怨极深，双方几乎无法心平气和地交谈，稍一开口就可能引发斗殴。波尼斯无法直接亲自前往马科伦农场，而暴风城的卫兵忙于应付豺狼人和迪菲亚匪徒，根本无暇调解相邻农户间的琐碎争执。一位路过的冒险者正好可以作为中立者，直接询问那个男孩。",al={"波尼斯为什么需要我","为什么派冒险者去找比利","为什么不找暴风城卫兵"}}},fp="13,169,23.376.0,22.225.1,33.196.0,46.144.1,31.117.0,55.206.0,44.156.1,33.102.0"}
P.entries["quest:850"] = {n="科卡尔首领",s="“半人马领袖”任务开启了一场由兽人雷加·死门领导的战役，旨在粉碎贫瘠之地日益猖獗的半人马督军。游牧的考卡尔部族世代困扰着牛头人，但新崛起的酋长们正在将这些松散的部族组织成真正的军事威胁。雷加派遣部落的勇士在遗忘之池铲除巴拉克·科多班，以防他的影响力继续扩张。",h="“半人马领袖”任务开启了一场由兽人雷加·死门领导的战役，旨在粉碎贫瘠之地日益猖獗的半人马督军。游牧的考卡尔部族世代困扰着牛头人，但新崛起的酋长们正在将这些松散的部族组织成真正的军事威胁。雷加派遣部落的勇士在遗忘之池铲除巴...",kw={"巴拉克","贫瘠之地","半人马","十字路口","死门","遗忘之池","科多班","考卡尔","雷加"},ang={["faction:Horde"]="贫瘠之地的十字路口是连接莫高雷、杜隆塔尔以及更远处的部落据点的生命线。消灭考卡尔的首领可以保护脆弱的补给商队免受毁灭性的伏击。",["race:Orc"]="萨尔曾承诺部落会保卫牛头人，而像雷加·死门这样的老兵严肃地对待这一血誓，将半人马好战者视为对兽人在贫瘠之地统治权的直接战略威胁。",["race:Tauren"]="对牛头人来说，击杀考卡尔的指挥官是关乎生存与复仇的问题。在部落于卡利姆多建立据点之前，半人马部族屠杀了无数牛头人部落，并将舒哈鲁人从他们祖传的牧场上驱逐了数十年。"},sec={{t="旱地上的威胁",b="多年来，马身的半人马一直恐吓着卡利姆多，在萨尔的部落到来扭转战局之前，他们几乎将游牧的牛头人逼入绝境。在贫瘠之地，占据统治地位的考卡尔部族通常以分散的劫掠小队形式活动。然而近来，好战的酋长们开始联合这些分散的队伍，将简单的劫掠小队变成了一股有组织的军事力量，足以威胁到部落的坚固据点。"},{t="斩首行动",b="驻扎在十字路口以西营地的兽人战士雷加·死门意识到，考卡尔部族非常依赖虚张声势和蛮力来维持凝聚力。如果没有强有力的指挥官，他们的袭击者就会陷入内斗。为了挫败他们的推进，雷加指示部落的冒险者“擒贼先擒王”，从巴拉克·科多班开始。这个野心勃勃的领袖正驻扎在遗忘之池那郁郁葱葱的水源附近。"},{t="众人的首领",b="击杀巴拉克·科多班对北部的考卡尔营地是一个重大打击，但雷加知道巴拉克只是更大规模运动的先锋。他的死仅仅是拆解考卡尔高层指挥体系这一协同战役的开端，也为后续在贫瘠之地追猎其他酋长——苦行者沃罗格和赫兹鲁·血印铺平了道路。"}},faq={{q="谁是巴拉克·科多班？",a="巴拉克·科多班是一位凶猛的考卡尔半人马领袖，他在十字路口北部的遗忘之池聚集了一群劫掠者。他以狡诈和残忍著称，通过将零散的部族组织起来对部落构成进攻威胁，这使他比普通的游牧掠夺者危险得多。",al={"巴拉克","谁是巴拉克","巴拉克·科多班背景"}},{q="我在哪里可以找到巴拉克·科多班？",a="巴拉克·科多班在遗忘之池建立了一个营地。遗忘之池是一片绿洲，位于贫瘠之地中部的十字路口以北。他的周围通常有忠诚的考卡尔卫兵守护。",al={"巴拉克位置","巴拉克在哪里","遗忘之池巴拉克"}},{q="谁是雷加·死门？",a="雷加·死门是一位驻扎在十字路口以西的一个小型地堡营地的兽人老兵。他负责监视贫瘠之地内半人马的动向，并策划先发制人的打击，以保护部落定居点免受有组织的突袭。",al={"雷加","谁发布半人马领袖任务","雷加·死门背景"}},{q="为什么考卡尔部族对部落来说是个大问题？",a="半人马世代对牛头人进行着冷酷的、近乎种族灭绝的战争。作为部落的正式成员，牛头人依赖他们的盟友来协助保卫他们祖祖辈辈的狩猎场和横跨贫瘠之地的贸易路线，以防止半人马的持续扩张。",al={"为什么要与考卡尔战斗","考卡尔威胁","半人马与部落的敌对关系"}},{q="巴拉克死后会发生什么？",a="击败巴拉克·科多班后显示，其他酋长正在贫瘠之地的其他地方集结部队。雷加会立即派遣你去死水绿洲暗杀苦行者沃罗格，随后去甜水绿洲暗杀赫兹鲁·血印，最终抵御一场来自考卡尔部族的直接突袭。",al={"巴拉克之后的下一个任务","半人马领袖后续","接下来是什么"}},{q="为什么考卡尔部族聚集在绿洲周围？",a="在贫瘠之地干旱的气候下，水和肥沃的土地是珍贵的宝藏。通过占领遗忘之池这样的天然泉水，考卡尔部族不仅获得了必需的水源，还能剥夺旅行者和牛头人猎手这些具有战略意义的休息点。",al={"为什么半人马在绿洲","考卡尔水源","遗忘之池半人马"}}},fx={["55ee765d"]={q="雷戈萨·死门为什么要杀死科卡尔酋长？",a="半人马部族世世代代都在骚扰牛头人，但贫瘠之地的科卡尔人通常各自为战，组织松散。最近，几位颇具魅力的酋长开始召集四散的战团，联合起来威胁部落的定居点。雷戈萨知道，如果任由这些新兴指挥官组织起来，部落在贫瘠之地建立的据点就可能土崩瓦解。除掉科多班恩·巴拉克这样的人物，便能在起义席卷地方防线之前打击其首领。",al={"为什么杀死科卡尔首领","雷戈萨·死门的动机","雷戈萨为什么要办这件事"}},["4347847a"]={q="巴拉克的头颅有什么用？",a="雷戈萨需要无可辩驳的证据，证明半人马指挥官已经倒下。在贫瘠之地这片严酷的边境，传闻和口头说法不足以确保安全。带回巴拉克被割下的头颅，便能确认驻扎在遗忘之池附近的科卡尔战团确实失去了首领，也无力再协调后续袭击。",al={"为什么要巴拉克的头颅","巴拉克头颅的用途","巴拉克的头颅要怎么处理"}}},fp="14,323,31.376.0,22.400.0,17.282.1,22.270.0,32.143.0,25.212.0,48.271.0,35.253.1,42.224.0"}
P.entries["quest:851"] = {n="狂热的维罗戈",s="维罗戈·德维什是一位行踪诡秘的考尔克半人马领袖，游荡在贫瘠之地的南部平原。为了终结他的突袭，雷加尔·死亡之门指示部落勇士突袭死水绿洲的半人马指挥帐篷，迫使这位游牧指挥官现身。",h="维罗戈·德维什是一位行踪诡秘的考尔克半人马领袖，游荡在贫瘠之地的南部平原。为了终结他的突袭，雷加尔·死亡之门指示部落勇士突袭死水绿洲的半人马指挥帐篷，迫使这位游牧指挥官现身。",kw={"贫瘠之地","半人马","十字路口","德维什","考尔克","雷加尔·死亡之门","死水绿洲","维罗戈"},ang={["faction:Horde"]="控制绿洲对于在干旱的贫瘠之地生存至关重要；清除半人马指挥官可以确保补给商队的水路畅通。",["race:Orc"]="雷加尔·死亡之门认为，消灭考尔克战帅对于保障杜隆塔尔旅行者往返十字路口与石爪山脉之间的道路安全至关重要。",["race:Tauren"]="考尔克人在这片平原上猎杀并骚扰游牧的牛头人已有数代之久，因此，像处决维罗戈这样的领袖早已成为众人期盼已久的复仇。"},sec={{t="引诱德维什",b="在巴拉克·科多班倒台后，兽人战士雷加尔·死亡之门将目标对准了考尔克部族剩余的战帅。与在遗忘之池北部水域附近徘徊的巴拉克不同，维罗戈·德维什游荡在被烈日炙烤的广袤平原上，很少在同一个营地停留太久。在广袤的土地上追踪他纯属徒劳，这使得部落侦察兵只剩下一种可行的策略：强迫这位指挥官主动现身。"},{t="死水绿洲",b="维罗戈坐镇在十字路口东南方死水绿洲的半人马指挥所。雷加尔指示冒险者直接突袭该营地，斩杀指挥帐篷附近的考尔克战士，直到恐慌促使他们吹响号角。这一战术利用了半人马的傲慢——只要在他们的领地上屠杀足够多的维罗戈下属，这位德维什就会赶回支援他的哨所，自投罗网，撞进部落早已准备好的利刃之中。"}},faq={{q="维罗戈·德维什是谁？",a="维罗戈·德维什是贫瘠之地考尔克半人马的一名游荡战帅。他负责指挥死水绿洲的行动，但大部分时间都在南部的荒野中徘徊，这让他很难被直接围困。",al={"谁是维罗戈","维罗戈背景故事","维罗戈·德维什"}},{q="为什么维罗戈不待在营地里？",a="正如他“德维什”的称号一样，维罗戈是一位游牧领袖，他频繁往来于贫瘠之地的荒凉地带，而不是无所事事地坐在某个营地里。这种机动的特性使他免受部落有组织围剿的威胁，迫使他的敌人必须激怒他才能看到他的真身。",al={"维罗戈在哪里","为什么维罗戈要游荡","维罗戈失踪"}},{q="如何召唤维罗戈？",a="当他的族群受到威胁时，维罗戈会被引回指挥所。通过攻击死水绿洲那座醒目的指挥帐篷周围聚集的半人马，冒险者可以制造足够的混乱，迫使幸存的考尔克发出警报，从而促使维罗戈飞奔回防他的帐篷。",al={"如何刷新维罗戈","寻找维罗戈","维罗戈没出现"}},{q="是谁下令处死维罗戈的？",a="雷加尔·死亡之门，一位驻扎在十字路口西侧、通往石爪山脉主路旁的兽人老兵，下令处决维罗戈。他试图通过有条不紊地猎杀每一位区域指挥官来击溃考尔克部族的脊梁。",al={"谁发布的任务","雷加尔·死亡之门"}},{q="维罗戈倒下后会发生什么？",a="将维罗戈的断头带回给雷加尔，兽人会将它与巴拉克·科多班的头颅放在一起收藏。随后，雷加尔会将目标锁定在南方甜水绿洲的半人马战帅——赫兹鲁尔·血印。",al={"接下来是什么","维罗戈之后"}},{q="为什么考尔克半人马在贫瘠之地是个大问题？",a="考尔克是极具侵略性的领土掠食者，他们占据了贫瘠之地各处至关重要的水源。他们频繁突袭商队、哨所和当地的牛头人兽群，对卡利姆多中部羽翼未丰的部落势力构成了直接的生存威胁。",al={"为什么要对抗考尔克","考尔克威胁"}}},fp="17,236,23.334.0,18.273.0,25.141.0,35.159.0,24.147.0,25.187.0,31.193.1,57.195.0"}
P.entries["quest:852"] = {n="赫兹鲁尔·血印",s="“赫兹鲁尔”是兽人老兵雷戈萨·死门委派的一项任务，旨在消灭贫瘠之地考尔克半人马的总军阀。部落希望通过在甜水绿洲取下赫兹鲁尔的头颅，一举粉碎这些入侵者的指挥体系。",h="“赫兹鲁尔”是兽人老兵雷戈萨·死门委派的一项任务，旨在消灭贫瘠之地考尔克半人马的总军阀。部落希望通过在甜水绿洲取下赫兹鲁尔的头颅，一举粉碎这些入侵者的指挥体系。",kw={"血印","半人马","十字路口","死门","赫兹鲁尔","考尔克","甜水","绿洲","雷戈萨"},ang={["faction:Horde"]="保障十字路口和贫瘠之地的安全，需要打破半人马对维持地区旅行的三大主要绿洲的控制。",["race:Orc"]="雷戈萨·死门以兽人的战争观审视这场对抗考尔克的战斗，他指出，虽然半人马凶猛异常，但他们野蛮的狂怒缺乏部落历练出的钢铁纪律。",["race:Tauren"]="世世代代以来，游牧的牛头人饱受半人马带来的流离失所和血腥杀戮之苦；终结赫兹鲁尔这样的军阀，是他们用艰辛换来的复仇。"},sec={{t="斩首考尔克",b="在巴拉克·科多班和维罗戈·德维什死后，贫瘠之地的考尔克半人马中只剩下一位最高酋长：赫兹鲁尔。雷戈萨·死门认为，赫兹鲁尔正是策划半人马在热带草原上肆虐的凶残而狡诈的急先锋。击杀赫兹鲁尔旨在制造混乱，并从根本上瓦解他们的阵型，在他们威胁到部落定居点之前，就将这头暴躁野兽的头颅斩下。"},{t="甜水据点",b="赫兹鲁尔在位于十字路口以南的甜水绿洲指挥着他的战团。控制贫瘠之地为数不多的水源是生存的关键，这使得该绿洲成为考尔克劫掠小队的战略枢纽和集结地。在赫兹鲁尔的领地上与他正面对抗，部落勇士不仅能够拔掉半人马最关键的据点，还能切断他们对该地区南部路线的控制。"},{t="危险的余波",b="虽然雷戈萨称赞了战胜赫兹鲁尔的胜利，并指出半人马缺乏兽人那种专注的纪律，但这次刺杀行动并未让部族平息下来。愤怒的考尔克人没有安静地四散奔逃，而是集结了剩余的兵力，直接对雷戈萨的营地发动了一场孤注一掷的全面进攻，以寻求血腥的复仇。"}},faq={{q="赫兹鲁尔是谁？",a="赫兹鲁尔是活跃在贫瘠之地的考尔克半人马的最高酋长。他被部落公认为凶猛、狡诈且残忍，在甜水绿洲的据点里指挥着各个部族和劫掠者。",al={"赫兹鲁尔是谁","赫兹鲁尔剧情","贫瘠之地半人马领袖"}},{q="在哪里可以找到赫兹鲁尔？",a="赫兹鲁尔在南贫瘠之地的甜水绿洲（十字路口以南）周围巡逻，身边有他的考尔克保镖护卫。",al={"赫兹鲁尔在哪","赫兹鲁尔位置","赫兹鲁尔坐标"}},{q="是谁发布了击杀赫兹鲁尔的任务？",a="雷戈萨·死门，一位驻扎在十字路口以西、通往石爪山脉道路上的小营地里的兽人战士，负责分派此任务。",al={"谁发布赫兹鲁尔任务","雷戈萨·死门任务","赫兹鲁尔任务发布者"}},{q="部落为什么要除掉赫兹鲁尔？",a="考尔克半人马不断威胁着部落的贸易路线和定居点。雷戈萨认为，消灭他们的最高酋长将瓦解部族的团结，并大大削弱他们进行协调作战的能力。",al={"为什么要杀赫兹鲁尔","赫兹鲁尔任务目的","贫瘠之地考尔克威胁"}},{q="赫兹鲁尔被杀后会发生什么？",a="幸存的考尔克人并没有投降，而是陷入了盲目的愤怒之中，联合起来对十字路口以西的雷戈萨·死门的前哨站发动了即时的反击。",al={"赫兹鲁尔死后的反击","接下来会发生什么","杀死赫兹鲁尔的后果"}},{q="赫兹鲁尔与巴拉克和维罗戈有何关系？",a="巴拉克·科多班和维罗戈·德维什是考尔克的中层领导，分别管理着各自的绿洲和战团，而赫兹鲁尔则是统领整个贫瘠之地部族的最高领袖。",al={"巴拉克 维罗戈 赫兹鲁尔","考尔克酋长","三位半人马领袖"}}},fp="16,177,23.354.0,24.339.0,21.276.1,24.147.0,36.133.0,35.135.0,36.193.0,35.158.1,42.157.0"}
P.entries["quest:853"] = {n="药剂师扎玛",s="这项差事需要冒险者从干旱的贫瘠之地奔向雷霆崖，运送一种不稳定的、提炼过的真菌乳剂。药剂师赫布瑞姆需要将这种强效混合物迅速送到他位于灵魂高地阴影深处的同事，药剂师扎玛手中。",h="这项差事需要冒险者从干旱的贫瘠之地奔向雷霆崖，运送一种不稳定的、提炼过的真菌乳剂。药剂师赫布瑞姆需要将这种强效混合物迅速送到他位于灵魂高地阴影深处的同事，药剂师扎玛手中。",kw={"药剂师赫布瑞姆","药剂师扎玛","菌类孢子","预见之池","提炼过的孢子","皇家药剂师学会","灵魂高地","贫瘠之地","雷霆崖"},ang={["faction:Horde"]="贫瘠之地的哨所与雷霆崖高地之间的快速通讯确保了区域供应链保持畅通。",["race:Tauren"]="虽然欢迎他们的新盟友，但传统的牛头人通常对被遗忘者在神圣的预见之池深处酿造的那些冒着泡的奇怪药剂持怀疑态度。",["race:Undead"]="将赫布瑞姆的研究成果送到扎玛手中，加强了皇家药剂师学会在卡利姆多中部尘土飞扬的边境地区所维持的秘密研究网络。"},sec={{t="脆弱的货物",b="在研究了在贫瘠之地的绿洲中茂盛生长的奇特真菌花朵后，药剂师赫布瑞姆将其熬制成了一种精细的乳剂。这种不稳定的药剂在制备后会迅速降解。由于没有时间亲自前往莫高雷，赫布瑞姆将药瓶托付给一名可靠的跑腿，要求其在溶液失去化学效力之前爬上峭壁。"},{t="在萨满的注视下",b="药剂师扎玛的实验室远离莫高雷广阔的平原，隐藏在预见之池内。这个地下洞穴位于灵魂高地神圣高地的深处，与被遗忘者法师和牧师共享。在这里，在牛头人圣殿的地板之下，皇家药剂师学会利用从整个大陆收集的原材料秘密地进行研究。"}},faq={{q="为什么这次运送有时间限制？",a="赫布瑞姆的提炼过的真菌乳剂具有化学不稳定性。如果暴露在外或放置太久，化合物会分解并失去效力，使这种混合物无法用于扎玛的研究工作。",al={"为什么有时间限制","任务计时器","提炼过的孢子计时器"}},{q="我在哪里可以找到药剂师扎玛？",a="药剂师扎玛位于雷霆崖的预见之池内。通往这个洞穴的入口在灵魂高地上有些隐蔽，它通向萨满帐篷的下方。",al={"扎玛在哪里","扎玛的位置","找到扎玛"}},{q="药剂师赫布瑞姆是谁？",a="药剂师赫布瑞姆是一位代表皇家药剂师学会的炼金术师，驻扎在贫瘠之地的十字路口。他分析当地的动植物，以研究卡利姆多的原生生物如何为被遗忘者所用。",al={"赫布瑞姆是谁","赫布瑞姆 十字路口"}},{q="皇家药剂师学会在雷霆崖做什么？",a="作为部落内的盟友，被遗忘者在雷霆崖驻扎了像扎玛这样的代表。他们在预见之池的地下默默运作，分析在卡利姆多各地收集的样本，并维持与其他哨所的补给联系。",al={"为什么被遗忘者在雷霆崖","预见之池的药剂师"}},{q="这些菌类孢子最初是用来做什么的？",a="这些孢子生长在贫瘠之地茂密的绿洲周围，在沙漠中非自然地繁茂生长。赫布瑞姆将它们提炼出来，以研究它们的生物特性和炼金术应用，然后才转交给扎玛。",al={"为什么需要孢子","贫瘠之地真菌的用途"}},{q="如果计时结束会发生什么？",a="如果计时结束，乳剂就会降解变质。你必须回到十字路口找药剂师赫布瑞姆，获取新的一批乳剂运送到雷霆崖。",al={"计时失败","孢子过期"}}},fp="16,153,15.241.0,30.269.0,43.165.0,34.139.0,26.209.0,60.238.0,48.184.0,35.165.0"}
P.entries["quest:854"] = {n="十字路口之旅",s="“十字路口之旅”对于离开莫高雷宁静草场、初出茅庐的部落冒险者来说，是一次关键的成人礼。在陶拉祖营地，牛头人神秘主义者基尔格·锐角会将旅行者派往北方的十字路口，去协助兽人监工索克。这标志着一位新手正式踏上了卡利姆多广阔的前线舞台。",h="“十字路口之旅”对于离开莫高雷宁静草场、初出茅庐的部落冒险者来说，是一次关键的成人礼。在陶拉祖营地，牛头人神秘主义者基尔格·锐角会将旅行者派往北方的十字路口，去协助兽人监工索克。这标志着一位新手正式踏上了卡利姆多广阔的前...",kw={"贫瘠之地","陶拉祖营地","十字路口","大地母亲","基尔格·锐角","索克","雷霆崖"},ang={["faction:Horde"]="该任务突显了雷霆崖各部族与大酋长在卡利姆多中部的先锋部队之间日益加深的合作。",["race:Orc"]="索克急需来自南方的增援，以维持萨尔的斥候在贫瘠之地好不容易建立起来的脆弱防线。",["race:Tauren"]="对于牛头人冒险者来说，这趟旅程标志着他们真正离开了大地母亲神圣台地的庇护，投身于部落更广阔的斗争中。"},sec={{t="离开摇篮",b="对于许多离开故土莫高雷的牛头人来说，陶拉祖营地是他们对贫瘠之地那严酷而多风的平原的第一次真正体验。在穿过莫高雷的山隘后，神秘主义者基尔格·锐角正注视着那些进入干旱草原的旅行者。他察觉到了他们与日俱增的能力，于是指引这些前途无量的勇士沿着尘土飞扬的贸易路线继续向北进发，而不是停留在边缘地带。"},{t="共同的纽带",b="这个任务强调了雷霆崖的牛头人与萨尔建立的新部落之间密不可分的纽带。基尔格指出，两族人民的命运如今已交织在一起，而在十字路口奋力开辟前哨站的兽人们迫切需要增援。当旅行者抵达哨站时，索克会热情地迎接来自高地远方的来客，并急切地想要考验他们的实力，让他们去对抗大草原上的重重险境。"}},faq={{q="谁开启了“十字路口之旅”？",a="该任务由基尔格·锐角提供，他是一位位于南贫瘠之地陶拉祖营地的牛头人，就在通往莫高雷的山隘以东。",al={"谁给予这个任务","任务发布者","基尔格·锐角任务"}},{q="索克在哪里？",a="索克站在十字路口的栅栏墙内，这是部落在贫瘠之地的核心定居点，位于陶拉祖营地沿主路向北的方向。",al={"索克在哪里","索克位置","寻找索克"}},{q="为什么基尔格·锐角会派遣旅行者前往十字路口？",a="基尔格感觉到冒险者已经准备好接受更大的考验，并意识到牛头人和兽人如今共享着交织在一起的命运。十字路口的兽人驻军正承受着来自当地威胁的持续压力，急需有能力的盟友协助。",al={"为什么要去十字路口","十字路口的目的","为什么派我去找兽人"}},{q="十字路口是什么地方？",a="十字路口是部落在卡利姆多中部主要的战略枢纽和贸易站。它建在南北和东西主干道的交汇处，是稳定这片荒蛮前线的集结地。",al={"十字路口是什么","十字路口定居点","贫瘠之地中心"}},{q="只有牛头人能接到这个任务吗？",a="是的。基尔格·锐角只向牛头人提供这次旅程，他欢迎从遥远的雷霆崖远道而来的族人，并派遣他们前去向索克报到。",al={"这是牛头人专属任务吗","部落引导任务"}},{q="通往十字路口的道路上有什么威胁？",a="向北的道路横穿干旱平原，那里居住着具有攻击性的平原陆行鸟、徘徊的草原狮和游荡的刺鬃野猪人部落。沿着踏实的道路走，可以帮助旅行者避开大草原中部那些更有领地意识的捕食者。",al={"路危险吗","从陶拉祖到十字路口的路线"}}},fp="25,171,18.279.0,13.352.0,37.156.0,23.149.0,58.220.0,23.203.0,33.137.0,52.239.0"}
P.entries["quest:855"] = {n="半人马护腕",s="半人马护腕是雷格萨·死亡之门在十字路口以西发布的一项军事悬赏。这项任务要求部落的勇士们削减那些争夺贫瘠之地中部控制权的、极具侵略性的考卡尔半人马的数量。",h="半人马护腕是雷格萨·死亡之门在十字路口以西发布的一项军事悬赏。这项任务要求部落的勇士们削减那些争夺贫瘠之地中部控制权的、极具侵略性的考卡尔半人马的数量。",kw={"贫瘠之地","悬赏","护腕","半人马","十字路口","部落","考卡尔","雷格萨·死亡之门"},ang={["faction:Horde"]="清理考卡尔人可以保护连接奥格瑞玛和雷霆崖的重要补给线。",["race:Orc"]="对于兽人来说，确保杜隆塔尔周边地区免受游牧掠夺者的侵扰，对于建立一个永久且稳定的新家园至关重要。",["race:Tauren"]="半人马给牛头人部落带来了数百年的破坏和种族灭绝；削减他们在贫瘠之地的人数是对他们的一种私人报复。"},sec={{t="平定平原",b="初生的部落正致力于在卡利姆多各处开辟安全领地，而贫瘠之地是连接杜隆塔尔和莫高雷的重要枢纽。然而，狂暴的考卡尔半人马游牧部落争夺着每一处水源和每一片平原，频繁袭击补给车队和侦察小队。兽人战士雷格萨·死亡之门在他位于十字路口以西的掩体中，指挥着防御行动，试图遏制他们无休止的进犯。"},{t="血腥的结算",b="雷格萨要求通过实际行动来证明战果，而不是仅仅依靠空洞的报告。冒险进入考卡尔领地的士兵们被要求带回直接从被杀死的半人马战士身上剥下的护腕。这种残酷的计算方式既是为了核实部落悬赏任务的完成情况，也是为了通过这种计算出的手段警告幸存的考卡尔掠夺者。"}},faq={{q="雷格萨·死亡之门是谁？",a="雷格萨·死亡之门是一位兽人军事指挥官，驻扎在十字路口以西的一处加固掩体中。他负责领导部落在贫瘠之地当地的行动，以压制半人马掠夺团伙。",al={"雷格萨是谁","雷格萨·死亡之门背景故事","谁发布半人马护腕任务"}},{q="为什么部落想要半人马护腕？",a="半人马护腕是战场上杀死敌方战士的无可辩驳的实物证据。收集这些护腕可以确保悬赏奖励只支付给那些对敌对的考卡尔部落造成了实际伤亡的行动。",al={"为什么需要护腕","半人马护腕的作用","收集护腕的原因"}},{q="为什么考卡尔半人马要攻击部落？",a="考卡尔是一个残暴的扩张主义半人马氏族，原产于卡利姆多中部。他们将贫瘠之地视为自己的狩猎场，并强烈反对兽人和牛头人建立的新定居点、营地和联盟。",al={"为什么半人马仇视部落","半人马冲突","考卡尔侵略行为"}},{q="考卡尔半人马在贫瘠之地的什么位置？",a="考卡尔掠夺营地聚集在贫瘠之地中部和南部的各个重要绿洲和崎岖的山脊周围，经常争夺对水源和交通路线的控制权。",al={"在哪寻找半人马","考卡尔分布地点","半人马营地"}},{q="收集这些护腕能阻止考卡尔的袭击吗？",a="不能。虽然雷格萨希望这种杀戮能给幸存的掠夺者以震慑，但他公开怀疑凶残的考卡尔人是否会自愿停止他们嗜血的进攻。",al={"半人马护腕有效吗","半人马会停止进攻吗"}},{q="十字路口的战略价值是什么？",a="十字路口是连接兽人故乡杜隆塔尔、牛头人的莫高雷平原以及通往灰谷的北部路线的中心交通枢纽。中和附近半人马战争团伙的威胁对于保持部落补给线的畅通至关重要。",al={"为什么要保卫十字路口","十字路口的重要性"}}},fp="15,132,19.328.0,21.249.0,25.157.0,40.169.0,39.210.0,53.170.0,54.125.0,46.170.0"}
P.entries["quest:8551"] = {n="船长的箱子",s="海克拜瑞·斯莫特船长过去常往返于藏宝海湾和卡利姆多的棘齿城之间，直到海巨人摧毁了他的船，杀死了船员，并将斯莫特抛弃在救生艇上，让他漂回藏宝海湾。巨人戈拉什抢走了斯莫特的船长宝箱，斯莫特想要把它夺回来。",h="海克拜瑞·斯莫特船长过去常往返于藏宝海湾和卡利姆多的棘齿城之间，直到海巨人摧毁了他的船，杀死了船员，并将斯莫特抛弃在救生艇上，让他漂回藏宝海湾。巨人戈拉什抢走了斯莫特的船长宝箱，斯莫特想要把它夺回来。",kw={"藏宝海湾","戈拉什","棘齿城","海巨人","斯莫特","鼻烟盒","荆棘谷"},sec={{t="落魄船长",b="斯莫特说，往返于卡利姆多棘齿城的航程曾为他带来了成功的事业和良好的声誉。但海巨人终结了一切：他们撞碎了船只，杀害了船员，并把斯莫特扔进一艘救生艇，让他独自飘向藏宝海湾。"},{t="被窃的宝箱",b="巨人戈拉什拿走了斯莫特的船长宝箱，声称他想把它当鼻烟盒用。这个宝箱是斯莫特的最爱，里面有个存着最珍贵宝物的暗格。斯莫特听说戈拉什就在藏宝海湾以东的海岸一带游荡。"},{t="斯莫特的谢意",b="斯莫特对找回宝箱感到欣喜若狂，这在一定程度上平息了他的怒火，但复仇尚未结束。"}},faq={{q="谁是海克拜瑞·斯莫特船长？",a="斯莫特是藏宝海湾的一位船长，曾经往返于此地和卡利姆多的棘齿城，直到海巨人撞碎了他的船并杀死了船员。",al={"斯莫特船长","斯莫特是谁","海克拜瑞·斯莫特"}},{q="是谁拿走了宝箱？",a="海巨人之一的戈拉什拿走了宝箱，并声称他想把它当成鼻烟盒。",al={"谁偷了宝箱","谁有斯莫特的宝箱","戈拉什"}},{q="在哪里可以找到戈拉什？",a="在藏宝海湾以东的海岸沿线。斯莫特听说那个巨人经常在那里出没。",al={"戈拉什在哪里","戈拉什位置","寻找戈拉什"}},{q="为什么斯莫特想要找回宝箱？",a="那是斯莫特最心爱的宝箱，其暗格中存放着他最珍贵的宝藏。",al={"宝箱里有什么","为什么斯莫特想要宝箱"}}},fp="19,310,16.259.0,16.224.0,14.125.1,33.170.0,19.87.0,27.55.0,36.112.0"}
P.entries["quest:8552"] = {n="刺着字母的腰带",s="一条精致的饰带上绣着名字缩写，暗示了其主人就在荆棘谷的某处。找到那位遗失了饰带的海员，就会引出任务“船长的弯刀”。",h="一条精致的饰带上绣着名字缩写，暗示了其主人就在荆棘谷的某处。找到那位遗失了饰带的海员，就会引出任务“船长的弯刀”。",kw={"海克拜瑞·斯莫特","hs","摩卡什","绣字饰带","海巨人","荆棘谷"},sec={{t="有标记的服饰",b="这条精致的饰带下摆绣着“HS”两个字母。只有通过这两个字母，才能追踪到失主。"},{t="斯莫特的线索",b="将服饰归还给海克拜瑞·斯莫特船长，确认它确实属于他。收回饰带揭示了海巨人摩卡什已被击杀，这个残暴的家伙曾多次摧毁船长的船只和船员，他的死让船长感到如释重负。"}},faq={{q="饰带上缝着什么字母？",a="这条精致饰带的下摆绣着“HS”这两个缩写字母。",al={"饰带上的缩写是什么","绣字饰带上的缩写","饰带上的字母"}},{q="下一步任务是什么？",a="当饰带归还给主人后，下一步就是“船长的弯刀”。",al={"绣字饰带之后是什么任务","绣字饰带后续任务","下一步"}}},fp="20,145,16.120.0,21.255.1,40.49.0,26.85.0"}
P.entries["quest:8553"] = {n="船长的弯刀",s="海克拜瑞·斯莫特船长买下了一艘名为“斯莫特复仇号”的新船，想要去猎杀那些夺走他第一艘船的海巨人，结果却再次惨败。巨人们击碎了他的船并杀死了船员，其中一个名叫奈古拉什的巨人还偷走了船长的弯刀。斯莫特船长让你去咨询他以前的船上厨师斯普罗格，以便追踪那个庞然大物。",h="海克拜瑞·斯莫特船长买下了一艘名为“斯莫特复仇号”的新船，想要去猎杀那些夺走他第一艘船的海巨人，结果却再次惨败。巨人们击碎了他的船并杀死了船员，其中一个名叫奈古拉什的巨人还偷走了船长的弯刀。斯莫特船长让你去咨询他以前的船...",kw={"弯刀","海克拜瑞·斯莫特","奈古拉什","海巨人","斯莫特复仇号","斯普罗格","荆棘谷"},sec={{t="第二次灾难",b="在失去第一艘船后，海克拜瑞·斯莫特船长又弄来了一艘名为“斯莫特复仇号”的船，召集了新的船员和补给，发誓要向海巨人复仇。这次行动以灾难告终，巨人们击碎了船只并杀光了船员，只留下斯莫特再次在救生艇上漂流。在那次袭击中，巨人奈古拉什夺走了船长的弯刀。"},{t="咨询厨师",b="为了夺回被偷的佩刀，斯莫特求助于他的厨师。斯普罗格曾在“斯莫特复仇号”上服役，他在那次袭击中幸存了下来，可以帮助找到奈古拉什。"}},faq={{q="海克拜瑞·斯莫特船长在这次袭击中失去了哪艘船？",a="斯莫特买下并装备了一艘名为“斯莫特复仇号”的船，想要猎杀摧毁他第一艘船的巨人们，但那艘船也被巨人们摧毁了。",al={"第二艘船叫什么名字","斯莫特的第二艘船","哪艘船被砸碎了"}},{q="谁偷了船长的弯刀？",a="奈古拉什，那个击碎“斯莫特复仇号”并杀害船员的海巨人之一，夺走了这把武器。",al={"谁有弯刀","哪个巨人拿走了弯刀","谁拿走了斯莫特的弯刀"}},{q="斯普罗格是谁？",a="斯普罗格曾在“斯莫特复仇号”上担任厨师，并在那次摧毁船只的袭击中幸存了下来。斯莫特船长让旅行者去找他，以寻求寻找奈古拉什的帮助。",al={"斯普罗格是谁","斯普罗格的职责","谁是厨师"}},{q="这一步在猎杀海巨人的过程中处于什么位置？",a="这一步紧随“绣字腰带”任务之后，并直接引向“面对奈古拉什”。",al={"之前的任务是什么","下一个任务是什么","弯刀任务线"}}},fp="21,216,17.330.0,19.188.0,60.148.0,32.120.0,16.170.0,58.77.0"}
P.entries["quest:8555"] = {n="守护之龙",s="来自青铜龙军团的阿纳克洛斯会在塔纳利斯与你会面，以结束“流沙节杖”的第一部分任务。那条任务线通往安其拉之门开启之路。",h="来自青铜龙军团的阿纳克洛斯会在塔纳利斯与你会面，以结束“流沙节杖”的第一部分任务。那条任务线通往安其拉之门开启之路。",kw={"阿纳克洛斯","艾索雷葛斯","伊兰尼库斯","安其拉之门","流沙节杖","塔纳利斯","瓦拉斯塔兹"},sec={{t="开始的终结",b="这次会面结束了“流沙节杖”的开篇任务，即通往安其拉之门开启之路的任务线。阿纳克洛斯将与你一起完成这第一部分的收尾工作。"},{t="三位守望者",b="阿纳克洛斯提到了三条巨龙：伊兰尼库斯、瓦拉斯塔兹和艾索雷葛斯，他们作为世界的守望者发挥了举足轻重的作用。阿纳克洛斯说，这些守护者每一位都遭遇了悲剧，无论是死于上古之神的爪牙之手，还是惨遭朋友背叛。阿纳克洛斯承认由于自己的天真，也应承担部分责任，并表示整件事加剧了他对凡人的不信任。他要求你去寻找这三位巨龙，并为最坏的情况做好准备。"}},faq={{q="阿纳克洛斯是谁？",a="阿纳克洛斯是青铜龙军团的一员，你可以在塔纳利斯见到他。",al={"阿纳克洛斯是谁","阿纳克洛斯 塔纳利斯","青铜龙"}},{q="什么是流沙节杖？",a="这是一条通往安其拉之门开启之路的漫长任务线。这次会面结束了它的第一部分。",al={"节杖任务线","流沙节杖","安其拉之门任务线"}}},fp="31,167,24.155.0,18.387.1,18.75.0,42.155.0"}
P.entries["quest:8569"] = {n="往日的贡献：战歌峡谷",s="“战歌峡谷的过往功绩”是一项提交给主城军官的军事嘉奖，旨在表彰在前线服役的士兵。它并非为了庆祝彻底的征服，而是为了向那些在灰谷冲突不断的森林中浴血奋战并做出牺牲的老兵致敬。主城指挥官接收这些徽章是为了提振战争士气，并奖励双方阵营战士的奉献精神。",h="“战歌峡谷的过往功绩”是一项提交给主城军官的军事嘉奖，旨在表彰在前线服役的士兵。它并非为了庆祝彻底的征服，而是为了向那些在灰谷冲突不断的森林中浴血奋战并做出牺牲的老兵致敬。主城指挥官接收这些徽章是为了提振战争士气，并奖励...",kw={"灰谷","准将","奥格瑞玛","过往功绩","牺牲勋带","暴风城","战争使者","战歌峡谷"},ang={["class:Warrior"]="亲历过峡谷残酷肉搏战的前线战斗人员比任何人都更明白，真正的纪律在于即便胜负难料，依然能奋勇作战。",["faction:Alliance"]="对于联盟军队而言，将勋带交给准将重申了他们保卫古老森林并支持暗夜精灵盟友抵抗战歌氏族侵略的誓言。",["faction:Horde"]="对于部落而言，将徽章交给城市的战争使者证明了他们在灰谷为获取木材和生存而流下的鲜血并非白流。"},sec={{t="向阵亡与英勇者致敬",b="银翼要塞与战歌氏族之间的战争很少能带来干净利落、毫不费力的胜利。在灰谷南部边境，冲突总是残酷而血腥的，而且往往无法以决定性的胜利告终。指挥官们认识到，士气不能完全建立在完美的战绩上，因此暴风城、奥格瑞玛以及其他主城的指挥官们设立了旨在表彰坚定服役的荣誉。牺牲勋带正是为了纪念那些不顾胜算、奋勇投身战场的战士。"},{t="后方的战争努力",b="联盟准将和部落战争使者等主城官员负责管理远离前线的动员工作。虽然征兵人员将新鲜血液引向战歌峡谷这样的战场，但军需官和战术家必须照顾好那些经历过残酷战役归来的战士。通过承认在僵局或失败中展现出的个人勇气和牺牲精神，领导层确保了前线士兵始终致力于守住灰谷。"}},faq={{q="这项嘉奖的目的是什么？",a="这项嘉奖旨在表彰在战歌峡谷交战期间竭尽全力的前线战斗人员。主城指挥官接收英勇抗争的证明，以奖励他们的坚韧不拔并提振整个王国的战争士气。",al={"为什么会有过往功绩","过往功绩的目的","过往功绩的含义"}},{q="谁会接收这些牺牲的象征？",a="驻扎在主要城市的高级军事联络官会接收这些物品，包括暴风城等地的联盟准将，以及奥格瑞玛等城市的部落战争使者。",al={"谁接收过往功绩","在哪里提交过往功绩","谁是准将"}},{q="为什么军方要奖励那些没有带来胜利的努力？",a="指挥官们明白，在灰谷森林中的无休止战斗需要付出巨大的代价。奖励奉献和勇气提醒着战斗人员，即使战斗结果并未达到完全的胜利，他们的鲜血和牺牲也是有价值的。",al={"为什么要奖励牺牲勋带","为什么要奖励失败的战斗","英勇抗争的含义"}},{q="战歌峡谷的冲突发生在哪里？",a="战歌峡谷位于灰谷南部边境，兽人的战歌氏族在此采集木材，并与暗夜精灵的银翼要塞的顽强抵抗展开激烈交锋。",al={"战歌峡谷在哪里","战歌峡谷位置","什么是战歌峡谷"}},{q="联盟和部落的成员都可以参与这项工作吗？",a="是的。双方阵营都在各自的主城中维持着相应的军事领导机构，以表彰那些从灰谷血腥伐木冲突中归来的士兵。",al={"这是双方阵营的任务吗","部落或联盟的过往功绩","部落可以提交吗"}},{q="牺牲勋带代表什么？",a="牺牲勋带是授予或佩戴在那些在战歌峡谷经历了激烈冲突的战斗人员身上的徽记，证明了他们为了自己的人民而奋战的坚定意愿。",al={"牺牲勋带背景故事","什么是牺牲勋带","牺牲勋带"}}},fp="29,193,35.318.0,22.329.0,41.158.0,38.119.0,66.147.0,52.141.0,58.104.0,44.131.0"}
P.entries["quest:857"] = {n="众月之泪",s="在南贫瘠之地的群山高处，一个名叫被流放的费格雷的疯狂矮人要求拿回一件在巴尔莫丹发掘出的神秘遗物。这件被称为众月之泪的文物让费格雷陷入了疯狂和偏执，直到双辫将军将其作为不祥的诅咒封存起来。",h="在南贫瘠之地的群山高处，一个名叫被流放的费格雷的疯狂矮人要求拿回一件在巴尔莫丹发掘出的神秘遗物。这件被称为众月之泪的文物让费格雷陷入了疯狂和偏执，直到双辫将军将其作为不祥的诅咒封存起来。",kw={"巴尔莫丹","贫瘠之地","矮人诅咒","费格雷","被流放的费格雷","双辫将军","众月之泪"},ang={["faction:Horde"]="突袭巴尔莫丹以夺回遗物，让部落有机会干扰那些直接侵犯贫瘠之地的矮人行动。"},sec={{t="在巴尔莫丹发掘",b="当矮人们开始开凿南卡利姆多的山脉以建立巴尔莫丹时，众月之泪是他们的第一个重大发现。这件奇异的文物立即对探险队的一名工人费格雷产生了强大而令人不安的影响。"},{t="双辫的隔离措施",b="费格雷声称这件泪滴状遗物赋予了他强大的个人力量，为了保护他的奖品，他甚至对同伴大打出手。双辫将军察觉到了该遗物的腐蚀性影响，将其斥为诅咒之物，从费格雷手中夺走并锁在要塞内。费格雷被驱逐出挖掘营地，只能在悬崖间避难，在痛苦的偏执中发酵，并哀求路过的旅行者帮他偷回来。"},{t="可怕的代价",b="事实证明，双辫的警告比费格雷意识到的要更加直白。在找回众月之泪后，费格雷的喜悦并没有持续多久，因为遗物中潜藏的转化魔法吞噬了他。这件神器并没有让他飞升荣光，反而暴力地将这个矮人变异成了一只野蛮的穴居怪，在他重获奖品的几秒钟后就终结了他的生命。"}},faq={{q="什么是众月之泪？",a="它是一件古老而强大的遗物，由矮人挖掘者在南贫瘠之地的巴尔莫丹早期挖掘工作中发现。它对接触它的人产生一种令人陶醉、腐蚀心智的效果。",al={"什么是众月之泪","众月之泪遗物","巴尔莫丹神器"}},{q="谁是被流放的费格雷？",a="费格雷曾是双辫将军在巴尔莫丹探险队的一名挖掘者。在众月之泪被发现后，费格雷变得偏执且暴力，导致双辫将军将他驱逐出了要塞。",al={"费格雷是谁","费格雷背景故事","矮人费格雷"}},{q="为什么双辫将军要封锁众月之泪？",a="双辫将军认为该文物是一个危险的诅咒，而不是无害的历史发现。在目睹了费格雷对挖掘队同伴施暴后，双辫将这件遗物牢牢地锁在了巴尔莫丹的要塞内。",al={"为什么双辫锁住泪滴","双辫诅咒","巴尔莫丹要塞遗物"}},{q="把众月之泪还给费格雷会发生什么？",a="归还遗物会将费格雷的偏执推向高潮。当他拿到遗物时，后续的结局就会揭晓。",al={"费格雷发生了什么","费格雷结局","归还泪滴"}},{q="众月之泪的魔法被完全理解了吗？",a="双辫将军称其为诅咒，而费格雷则渴望它所赋予的力量。任务中并未解释该遗物魔法的运作机理。",al={"泪滴魔法","众月之泪诅咒","泪滴如何运作"}},{q="如果费格雷是矮人，为什么这是一个部落任务？",a="费格雷是一个躲在贫瘠之地的流放者，他厌恶占领巴尔莫丹的联盟军队。因为部落冒险者天生敌视双辫的挖掘行动，费格雷便请求他们突袭要塞并夺回遗物。",al={"为什么是部落任务","费格雷是部落吗","巴尔莫丹部落"}}},fp="21,100,23.213.0,22.360.0,17.221.1,30.216.0,25.192.0,46.187.0,48.82.1,37.124.1,47.213.0"}
P.entries["quest:8576"] = {n="翻译龙语",s="你把艾索雷葛斯的账本带给了纳瑞安，他必须解读上面写的内容。这是开启安其拉之门道路上的一步。",h="你把艾索雷葛斯的账本带给了纳瑞安，他必须解读上面写的内容。这是开启安其拉之门道路上的一步。",kw={"奥金浮标","艾索雷葛斯","龙语","账本","纳瑞安","塔纳利斯"},sec={{t="将账本交给纳瑞安",b="你把艾索雷葛斯的账本带给了纳瑞安。总得有人解读艾索雷葛斯在上面写了什么，这个任务就落到了纳瑞安头上。"},{t="纳瑞安的解读",b="纳瑞安听说艾索雷葛斯让你制作一个奥金浮标，而账本里就有它的设计图。纳瑞安觉得奇怪，艾索雷葛斯竟然用龙语写下了这些内容，而纳瑞安看不懂龙语。为了搞定它，纳瑞安需要龙语护目镜、一只五百磅的鸡和《龙语傻瓜教程》第二卷，顺序不限。"}},faq={{q="这本账本是谁的？",a="这是艾索雷葛斯的账本。你是把它带给纳瑞安的。",al={"账本的主人","艾索雷葛斯的账本","谁写了账本"}},{q="谁在解读账本？",a="纳瑞安，他必须解读艾索雷葛斯在上面写了什么。",al={"谁翻译账本","纳瑞安","账本交给谁"}}},fp="22,150,26.140.0,23.326.1,19.64.0,21.66.0"}
P.entries["quest:8577"] = {n="斯图沃尔，前任死党",s="在完成“翻译账本”任务后，纳瑞安说如果没有占卜护目镜，什么也翻译不了。纳瑞安的前死党斯图沃尔偷走了它们，你必须找到斯图沃尔并将护目镜拿回来。",h="在完成“翻译账本”任务后，纳瑞安说如果没有占卜护目镜，什么也翻译不了。纳瑞安的前死党斯图沃尔偷走了它们，你必须找到斯图沃尔并将护目镜拿回来。",kw={"格雷迈恩之墙","不起眼的板条箱","账本","纳瑞安","占卜护目镜","银松森林","斯图沃尔","塔纳利斯"},sec={{t="被偷走的护目镜",b="纳瑞安在翻译任何东西之前都需要占卜护目镜。它们很久以前被纳瑞安的前死党斯图沃尔偷走了，那个家伙伤透了纳瑞安的心，然后把纳瑞安遗弃在了这个地方。"},{t="去哪里寻找",b="在一个可靠的水晶球帮助下，纳瑞安已经将斯图沃尔的藏身之处缩小到了两个地方。一个是银松森林的格雷迈恩之墙，另一个是传送门背后的世界。你必须找到斯图沃尔并拿回护目镜。"},{t="斯图沃尔说了什么",b="斯图沃尔无法相信纳瑞安竟然找到了他们。斯图沃尔不会回去的，而且也不想再继续做那种有时候是朋友，有时候是奴隶的关系了。"}},faq={{q="纳瑞安为什么需要占卜护目镜？",a="纳瑞安说没有它们，什么也翻译不了。",al={"为什么需要护目镜","纳瑞安护目镜用途","占卜护目镜用法"}},{q="斯图沃尔是谁？",a="斯图沃尔是纳瑞安的前死党。斯图沃尔偷走了占卜护目镜，伤透了纳瑞安的心，然后把纳瑞安遗弃在了这里。",al={"斯图沃尔是谁","斯图沃尔背景故事","纳瑞安的朋友"}},{q="纳瑞安认为斯图沃尔在哪里？",a="纳瑞安的水晶球将范围缩小到了两个地方：银松森林的格雷迈恩之墙，或是一个遥远的传送门世界。",al={"斯图沃尔在哪里","斯图沃尔位置","格雷迈恩之墙"}},{q="之前要做什么？",a="“翻译账本”，你需要把艾索雷葛斯的账本带给纳瑞安。",al={"前置任务","前置条件","任务前因"}}},fp="18,124,18.223.0,13.191.0,17.140.1,41.66.0,15.154.0,35.112.0,23.79.0"}
P.entries["quest:858"] = {n="打火钥匙",s="“打火”任务始于一位冒险者在北部贫瘠之地发现一名被困在荆棘谷地精伐木机里的特工。由于冲动地劫持了这台机器却没拿启动钥匙，飞行员需要有人从现场主管那里取回打火钥匙，以免身份暴露。",h="“打火”任务始于一位冒险者在北部贫瘠之地发现一名被困在荆棘谷地精伐木机里的特工。由于冲动地劫持了这台机器却没拿启动钥匙，飞行员需要有人从现场主管那里取回打火钥匙，以免身份暴露。",kw={"井架","打火","打火钥匙","棘齿城","伐木机","斯布特瓦夫","贫瘠之地","荆棘谷地精","维兹克兰克"},ang={["faction:Horde"]="荆棘谷地精鲁莽的滥砍滥伐威胁到了贫瘠之地的北部边界，因此任何针对其重型机械的破坏或窃取行为都是令人乐见的干扰。",["profession:Engineering"]="荆棘谷地精的伐木机机械结构显示出惊人的复杂性，利用精细的手臂操纵控制和灵敏的旋转调节器，胜过棘齿城常见的修补技术。"},sec={{t="搞砸的抢劫",b="在北部贫瘠之地繁忙的荆棘谷地精钻探场深处，一场雄心勃勃的抢劫遭遇了尴尬的阻碍。一名受斯布特瓦夫指派的特工成功潜入该公司一台尖端伐木机内，意图劫持机器并研究其内部构造。然而，这个窃贼忽略了一个基本细节：如果没有专用的打火钥匙，转向和移动操纵杆是锁死的。"},{t="高压下的虚张声势",b="当一位心生怀疑的哥布林同事询问这台刚被登上的伐木机为何静止不动时，闯入者惊慌失措，谎称引擎突然故障。被困在玻璃舱盖内，周围又有好奇的工人游荡，劫持者引导前来的冒险者潜入中央井架。现场主管将备用的打火钥匙存放在上层的控制室里，这是在谎言拆穿前唯一的脱身机会。"},{t="企业嫉妒",b="一旦主管被解决，钥匙插入仪表盘转动，窃贼便深深着迷，而非感到羞愧。荆棘谷地精的伐木机控制系统——配备精密手臂运动杠杆、旋转控制器和稳定减震器——远胜于目前在棘齿城运作的笨重机器。回收这台伐木机不再仅仅是为了生存；它是工业间谍活动中无价的战利品。"}},faq={{q="谁在伐木机里？",a="驾驶这台伐木机的是与斯布特瓦夫有关联的一名特工，斯布特瓦夫是驻扎在中立港口城市棘齿城的一名工程师。这名飞行员潜入了荆棘谷地精的营地，意图窃取他们先进的伐木机器之一。",al={"伐木机驾驶员","谁在维兹克兰克伐木机里","维兹克兰克"}},{q="为什么伐木机不能直接开走？",a="没有打火钥匙，伐木机的操纵柱处于机械锁定状态。尽管劫持者成功进入了驾驶舱，但除非钥匙解锁驱动控制装置，否则车辆无法移动或逃离。",al={"为什么需要钥匙","为什么被困住","伐木机被锁住了"}},{q="在哪里可以找到打火钥匙？",a="打火钥匙由负责监督钻探作业的荆棘谷地精主管持有。主管常驻在附近大型木制井架顶端的控制室里。",al={"打火钥匙位置","主管在哪里","如何找到钥匙"}},{q="棘齿城为什么要荆棘谷地精的伐木机？",a="荆棘谷地精拥有远超棘齿城工程师所用标准型号的工程设计。捕获一台完好的机器，可以让当地工匠反向研究其精细的手臂控制装置、速度调节器和稳定系统。",al={"为什么要偷伐木机","棘齿城伐木机","斯布特瓦夫的伐木机"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是一名以棘齿城为基地的哥布林工程师兼特工，他监视着荆棘谷地精的掠夺性扩张，并试图获取他们的机械创新成果。",al={"斯布特瓦夫是谁","谁派出了维兹克兰克","棘齿城的斯布特瓦夫"}},{q="伐木机启动后会发生什么？",a="转动钥匙会解锁移动系统，随之立即引发一场疯狂的护送行动，飞行员试图驾驶劫持来的机器冲出敌对的钻探营地，返回安全地带。",al={"打火任务后续","拿到打火钥匙后"}}},fp="8,200,21.239.0,23.341.0,18.277.1,27.188.0,41.172.0,32.122.0,49.215.0,20.152.0,43.201.1"}
P.entries["quest:8584"] = {n="少管闲事",s="纳瑞安有个计划，但他拒绝解释，而且这个计划需要一只五百磅重的鸡。你前往加基森与迪尔格·奎克里弗谈谈，他能帮你开始寻找一只合适的鸟。",h="纳瑞安有个计划，但他拒绝解释，而且这个计划需要一只五百磅重的鸡。你前往加基森与迪尔格·奎克里弗谈谈，他能帮你开始寻找一只合适的鸟。",kw={"五百磅鸡","死亡黑鸡","迪尔格·奎克里弗","加基森","纳瑞安","塔纳利斯"},sec={{t="计划与搜寻",b="纳瑞安不想再让人问起他的生意，那是你永远无法理解的事。计划由他来定，搜寻则交给你。正如他之前所说，计划需要一只五百磅重的鸡，而加基森旅店里的迪尔格·奎克里弗可以为你指明方向。"},{t="迪尔格的回答",b="迪尔格·奎克里弗挠了挠头。他说，那种重量的鸡已经找不到了，虽然他以前确实知道一只，那就是“死亡黑鸡”，而且见过那只鸟的人没一个活下来的。然后他说他有个主意，可能对你们俩都有好处。"}},faq={{q="为什么纳瑞安需要一只五百磅重的鸡？",a="纳瑞安不肯说。他的生意涉及你无法理解的事物，比如心理电子口嚼装置，而且他把计划留给自己，把搜寻任务交给你。",al={"为什么五百磅鸡","纳瑞安的鸡生意","为什么纳瑞安要鸡"}},{q="你需要去加基森找谁谈话？",a="纳瑞安让你去找加基森旅店里的迪尔格·奎克里弗，他会帮你开始寻找合适的鸡。",al={"去哪里","在加基森找谁","迪尔格·奎克里弗在哪里"}},{q="这个任务之前有什么任务？",a="首先要完成“翻译账本”。纳瑞安是在那之后才提出鸡的事情的。",al={"前置任务","先做什么任务","上一步"}},{q="纳瑞安在哪里？",a="纳瑞安在塔纳利斯。",al={"纳瑞安在哪里","纳瑞安位置","纳瑞安在塔纳利斯的位置"}}},fp="30,143,21.284.0,14.214.1,61.175.0,40.98.0,29.86.0,35.32.0"}
P.entries["quest:8586"] = {n="迪尔格的超美味奇美拉肉片",s="加基森的迪尔格·奎克里弗已经完成了他的食谱研究。他还需要你提供二十份地精火箭燃油和二十份石中盐，他要求尽快送达，以免你带给他的肉变质。",h="加基森的迪尔格·奎克里弗已经完成了他的食谱研究。他还需要你提供二十份地精火箭燃油和二十份石中盐，他要求尽快送达，以免你带给他的肉变质。",kw={"奇美拉","肉串","石中盐","迪尔格","加基森","纳瑞安","奎克里弗","火箭燃油"},sec={{t="迪尔格还需要什么",b="迪尔格·奎克里弗亲自准备香料，而你带给他的肉构成了这道菜的主要部分。他现在只缺二十份地精火箭燃油和二十份石中盐。只要有了这些东西，这道禽肉料理就可以送回给纳瑞安了。迪尔格催促你不要拖延，因为他不想让肉变坏。"}},faq={{q="谁需要这些补给品？",a="加基森的迪尔格·奎克里弗要求提供这些材料，以完成他的食谱。",al={"谁开启此任务","谁给予迪尔格的极品奇美拉肉串任务","迪尔格·奎克里弗任务"}},{q="迪尔格·奎克里弗需要什么配料？",a="迪尔格需要二十份地精火箭燃油和二十份石中盐。香料由他自己负责，你提供的肉补齐了剩余的部分。",al={"我需要什么物品","迪尔格肉串的配料","迪尔格的肉串所需物品"}},{q="这道成品菜是给谁的？",a="迪尔格说，一旦你带回了他所要求的材料，这道禽肉料理就可以送回给纳瑞安了。",al={"谁吃这些肉串","谁得到这道禽肉料理","这食物是给谁的"}},{q="交付这些材料后接下来要做什么？",a="接下来的任务是回到纳瑞安那里。",al={"后续任务","做完迪尔格肉串后我该做什么","此任务之后是什么"}}},fp="31,172,22.289.0,28.77.0,44.132.0,38.78.0,46.63.0"}
P.entries["quest:8587"] = {n="向纳瑞安回复",s="迪尔格·奎克里弗信守诺言，交出了那只五百磅重的鸡。你将它带给塔纳利斯的纳瑞安。这是在完成迪尔格的“美味奇美拉肉片”之后进行的。",h="迪尔格·奎克里弗信守诺言，交出了那只五百磅重的鸡。你将它带给塔纳利斯的纳瑞安。这是在完成迪尔格的“美味奇美拉肉片”之后进行的。",kw={"500磅重的鸡","奇美拉","迪尔格·奎克里弗","纳瑞安","塔纳利斯"},sec={{t="信守诺言",b="迪尔格·奎克里弗给了你他承诺的那只鸡，并声称他是个说话算话的地精。他无法想象一个侏儒为什么要一只那么大的鸟，并嘟囔着那一定是为了用来睡觉。从这里开始，你要把它带给塔纳利斯的纳瑞安。"},{t="纳瑞安的欢迎",b="鸡的香味引起了纳瑞安的注意。他用双拳猛击这只鸟，然后大口吃着迪尔格烹饪的食物，声称这是他吃过最美味的鸡。"}},faq={{q="这次运送之前发生了什么？",a="首先是“美味奇美拉肉片”，迪尔格·奎克里弗在那时要求获得火箭燃油和盐来完成他的食谱。",al={"上一个任务","在此之前我做了什么","前置条件"}},{q="谁收到了这只巨大的鸡？",a="塔纳利斯的纳瑞安。",al={"谁接收那只鸡","我把这个交给谁","交任务地点"}},{q="迪尔格为什么要准备一只五百磅重的鸡？",a="迪尔格是在信守诺言，把鸡交出来。他说他永远也不会知道一个侏儒要那么大的鸟做什么。",al={"为什么是500磅重的鸡","那只鸡有什么用","迪尔格的鸡"}},{q="运送鸡之后会发生什么？",a="接下来是“好消息和坏消息”，尽管纳瑞安只有在任务的其他两个部分，即“纳瑞安的占卜眼镜”和“龙语傻瓜教程：第二卷”也完成后，才会提供该任务。",al={"下一个任务","接下来是什么","接下来去哪里"}}},fp="16,169,14.251.0,16.190.1,31.113.0,33.58.0,51.148.0,40.142.0"}
P.entries["quest:8597"] = {n="龙语傻瓜教程",s="纳瑞安记得他把一本书藏在了一个安全的地方。要找到它，你需要先去天涯海滩寻找他坠毁的直升机，然后从那里向南游，前往南海的一座小岛。这是继“翻译账本”之后的任务。",h="纳瑞安记得他把一本书藏在了一个安全的地方。要找到它，你需要先去天涯海滩寻找他坠毁的直升机，然后从那里向南游，前往南海的一座小岛。这是继“翻译账本”之后的任务。",kw={"龙语傻瓜教程","新鲜的泥土堆","直升机","天涯海滩","纳瑞安","南海","塔纳利斯"},sec={{t="藏起来的书",b="纳瑞安说这本书一定会派上用场，而且他把它藏在了一个没有人能找到的地方。他第一次去那里时用的是直升机，但在回来的路上坠毁在了海滩上。他说，正是那次坠机事件给了他超凡的侏儒灵能。残骸就在天涯海滩的某处，从那里向南游就可以了。纳瑞安确信你一眼就能认出那个地方。这本书埋在南海的一座小岛上。"},{t="在岛上",b="在岛上你发现了一堆泥土，但书不见了。泥土堆上放着一张纸条。"}},faq={{q="是谁让你去找这本书的？",a="在你帮他完成“翻译账本”后，纳瑞安会派你去寻找这本书。",al={"谁给予龙语傻瓜教程","纳瑞安任务起始","谁给予此任务"}},{q="纳瑞安在哪里坠毁了他的直升机？",a="纳瑞安说他在藏好书回来的路上坠毁在了一片海滩上。你会在天涯海滩的某处找到残骸。",al={"直升机在哪里","坠毁的直升机位置","天涯海滩坠机"}},{q="书被藏在哪里？",a="纳瑞安说书被埋在南海的一座小岛上。你需要从天涯海滩的残骸处向南游，他说当你看到那个地方时，一切都会显而易见。",al={"书的位置","岛在哪里","往哪里游"}},{q="纳瑞安是如何获得灵能的？",a="纳瑞安说，在海滩上的直升机坠毁事件给了他灵能。",al={"纳瑞安灵能","纳瑞安如何获得灵能"}}},fp="20,193,18.441.0,13.101.1,32.90.0,38.120.0,40.172.0,38.74.0"}
P.entries["quest:8598"] = {n="敲诈",s="在纳瑞安的书本原本应该埋藏的那个新挖开的土堆处，留着一封勒索信。你把这封信带回塔纳利斯交给了纳瑞安。此任务紧接在《龙语傻瓜教程》之后。",h="在纳瑞安的书本原本应该埋藏的那个新挖开的土堆处，留着一封勒索信。你把这封信带回塔纳利斯交给了纳瑞安。此任务紧接在《龙语傻瓜教程》之后。",kw={"龙语傻瓜教程","新挖开的土堆","纳瑞安","勒索","勒索信","塔纳利斯"},sec={{t="拼凑的便条",b="这封信是由许多不同字体的碎纸片拼贴在羊皮纸上组成的。它称呼纳瑞安为侏儒，并告诉他，他的珍贵书籍现在落在了写信者的手中，只有严格按照信上的指示去做，他才能重新见到这本书。详细的说明写满了三页纸，结尾要求带上钱并独自前来。你把这封信带给了塔纳利斯的纳瑞安。"},{t="纳瑞安的回答",b="纳瑞安询问出了什么事，然后读了这封信，他的脸色变得通红。他非常愤怒，竟然有人敢抢走他的书，他发誓要让那些罪魁祸首知道得罪一位灵能侏儒会有什么后果。"}},faq={{q="勒索信提出了什么要求？",a="写信的人声称他们拿到了纳瑞安的书，只有当他完全按照他们的要求去做时，他才能再次见到它。说明长达三页，最后要求支付金钱并让他独自赴约。信中没有说明是谁写的。",al={"便条上写了什么","勒索信内容","是谁拿走了书"}},{q="这一步接下来会导向哪里？",a="一旦将这封信交给塔纳利斯的纳瑞安，任务线就会继续进行到“诱饵！”",al={"勒索之后是什么","勒索后续","勒索之后的下一个任务"}},{q="在找到勒索信之前发生了什么？",a="《龙语傻瓜教程》排在它之前，那是对纳瑞安埋藏的书籍的搜寻，最终止步于那个新挖开的土堆。",al={"前置任务","勒索的前置条件"}}},fp="6,199,21.346.0,15.198.1,34.234.0,31.91.0,41.103.0"}
P.entries["quest:8599"] = {n="唱给纳瑞安的情歌",s="人鱼米莉蒂丝有一封给纳瑞安的信，他就是那个曾被她从坠毁的飞行器残骸中救出的侏儒。她请你把这封情书带给身处塔纳利斯的他。你可以在寻找纳瑞安的《龙语傻瓜教程》时顺便接下这个任务。",h="人鱼米莉蒂丝有一封给纳瑞安的信，他就是那个曾被她从坠毁的飞行器残骸中救出的侏儒。她请你把这封情书带给身处塔纳利斯的他。你可以在寻找纳瑞安的《龙语傻瓜教程》时顺便接下这个任务。",kw={"飞行器","情书","米莉蒂丝","人鱼","纳瑞安","塔纳利斯","残骸"},sec={{t="来自海岸的信息",b="人鱼米莉蒂丝很少有访客。上一位访客就是她从坠毁的飞行器残骸中救出的侏儒，她凝视着虚空，沉浸在回忆中。她问你是否认识纳瑞安，因为她必须告诉他自己的心意，她确信那就是爱。她恳求你帮她带去一封信，并承诺将永远感激你。"},{t="纳瑞安的回复",b="纳瑞安评论说你身上有股鱼腥味。当他得知信的内容后，他显得局促不安，并辩解说她是鱼，他是侏儒，他们是不可能在一起的。"}},faq={{q="米莉蒂丝是谁？",a="米莉蒂丝是一位人鱼，她很少有访客。上一位访客就是她从坠毁的飞行器残骸中救出的侏儒——纳瑞安。",al={"米莉蒂丝是谁","人鱼米莉蒂丝","人鱼传说"}},{q="米莉蒂丝是如何认识纳瑞安的？",a="她从坠毁的飞行器残骸中救了他，并相信自己爱上了他。",al={"米莉蒂丝是如何认识纳瑞安的","纳瑞安和米莉蒂丝的关系","纳瑞安飞机失事"}},{q="情书里写了什么？",a="那是米莉蒂丝写给纳瑞安的信，表达了她的心意。她希望你能把它送到塔纳利斯交给他。",al={"米莉蒂丝的情书","给纳瑞安的情书","信里写了什么"}},{q="这个任务之前有什么？",a="《龙语傻瓜教程》排在这个任务之前。米莉蒂丝会向那些已经在寻找纳瑞安埋藏书籍的人提出请求。",al={"前置任务","献给纳瑞安的情歌的前置条件"}}},fp="20,194,23.355.0,15.188.1,16.141.0,41.105.0,24.133.0,30.108.0"}
P.entries["quest:86"] = {n="比利的馅饼",s="“给比利送馅饼”是一个卷入了艾尔文森林的斯通菲尔德家族与马科伦家族长期世仇的任务。年轻的比利·马科伦拒绝交出关于伯尼斯·斯通菲尔德阿姨丢失的项链的信息，除非能用一个猪肉馅饼作为交换。冒险者必须狩猎当地的野猪，收集肉类交给伯尼斯，让她烤出这份被索要的贿赂。",h="“给比利送馅饼”是一个卷入了艾尔文森林的斯通菲尔德家族与马科伦家族长期世仇的任务。年轻的比利·马科伦拒绝交出关于伯尼斯·斯通菲尔德阿姨丢失的项链的信息，除非能用一个猪肉馅饼作为交换。冒险者必须狩猎当地的野猪，收集肉类交给...",kw={"伯尼斯·斯通菲尔德","比利·马科伦","艾尔文森林","丢失的项链","马科伦农场","猪肉馅饼","斯通菲尔德农场","鲜嫩野猪肉"},ang={["profession:Cooking"]="伯尼斯阿姨提到，虽然野猪肉有时会又老又淡，但经过适当的香料腌制和文火慢炖，它能变成极其美味的馅饼内馅。",["race:Human"]="这场争吵凸显了在暴风城城门南侧，那些艾尔文森林农村定居者之间根深蒂固的顽固竞争。"},sec={{t="男孩的贿赂",b="当被问及伯尼斯·斯通菲尔德阿姨传家宝项链失窃一事时，比利·马科伦并没有表现出长辈所期望的丝毫悔意。这个男孩不仅没有归还传家宝或坦白从宽，反而抓住了机会满足自己的食欲。他坚持要一个刚烤好的猪肉馅饼，才肯吐露半个关于项链下落的字，他很清楚伯尼斯阿姨是山谷里手艺最好的厨师。"},{t="在积怨中烘焙",b="马科伦家族和斯通菲尔德家族在南瓜田里互相辱骂、打架、指责对方，这种情况已经持续了几代人。尽管让偷走自己家珠宝的顽童吃上东西让她感到无比愤慨，但伯尼斯阿姨还是同意点燃烤箱。为了换取从邻近牧场游荡的野兽身上采集的鲜嫩野猪肉，她强压怒火，为了哄好这个顽劣的少年并寻回她的珍宝，她选择了忍气吞声。"}},faq={{q="为什么比利在开口前想要馅饼？",a="比利·马科伦是一个机会主义的农家男孩，他利用自己掌握的伯尼斯阿姨项链失窃的情报作为筹码。他知道伯尼斯做的猪肉馅饼堪称一绝，因此在满足口腹之欲前，他拒绝透露是谁拿走了那件传家宝。",al={"为什么比利想要馅饼","比利的馅饼贿赂","比利猪肉馅饼"}},{q="为什么伯尼斯阿姨同意为一个小偷烤馅饼？",a="伯尼斯阿姨非常愤怒，她觉得这简直是在奖励那个她认为偷了她传家宝的男孩，但她别无他法。在得到野猪肉后，她不情愿地同意烤制馅饼，将找回失物的优先级置于尊严之上。",al={"为什么伯尼斯要烘焙","伯尼斯·斯通菲尔德做馅饼的原因","斯通菲尔德为马科伦烘焙"}},{q="做馅饼的肉是从哪里来的？",a="肉源自艾尔文森林中斯通菲尔德和马科伦农场周围草地和边缘地带出没的野猪。",al={"在哪里获得肉","鲜嫩野猪肉来源"}},{q="斯通菲尔德家族和马科伦家族之间有什么历史？",a="斯通菲尔德家族和马科伦家族是邻居，多年来一直维持着一种充满苦涩的小争斗，双方总是互相怀疑对方盗窃、蓄意破坏，并在地界线上发生琐碎的争吵。",al={"斯通菲尔德与马科伦的世仇","农场竞争","马科伦与斯通菲尔德"}},{q="比利真的偷了项链吗？",a="伯尼斯阿姨直接指控比利，虽然他避开了直接的供认，但他显然知道传家宝的去向，并以此秘密作为换取食物的筹码。",al={"比利是否偷了项链","谁拿走了项链","比利项链小偷"}},{q="伯尼斯拿到肉之后会发生什么？",a="一旦提供了鲜嫩的野猪肉，伯尼斯阿姨就会烤好一个猪肉馅饼让你带给比利，这样他最终会透露是谁拿走了她的项链。",al={"馅饼之后的下一步","给比利送馅饼后发生什么"}}},fp="13,179,13.238.0,24.273.0,41.175.0,50.208.0,42.129.0,57.207.0,38.162.0,41.152.0"}
P.entries["quest:860"] = {n="瑟格拉·黑棘",s="年轻的牛头人在证明了他们在莫高雷连绵起伏的山丘中掌握了基础的追踪与潜行技巧后，便被指引前往贫瘠之地那片干旱的荒野。梅洛·石蹄会派遣有志成为猎人的族人越过边境，向十字路口的瑟格拉·黑棘报到。这段旅程标志着猎人正式从地方试炼过渡到卡利姆多广袤平原上更为艰苦的掠食者等级体系中。",h="年轻的牛头人在证明了他们在莫高雷连绵起伏的山丘中掌握了基础的追踪与潜行技巧后，便被指引前往贫瘠之地那片干旱的荒野。梅洛·石蹄会派遣有志成为猎人的族人越过边境，向十字路口的瑟格拉·黑棘报到。这段旅程标志着猎人正式从地方试炼...",kw={"十字路口","猎人之道","梅洛·石蹄","莫高雷","平原陆行鸟","瑟格拉·黑棘","贫瘠之地","雷霆崖"},ang={["class:Hunter"]="这段旅程象征着从简单的当地猎物追踪毕业，转而征服卡利姆多内陆稀树草原上那些极具攻击性的掠食者和恶劣环境。",["faction:Horde"]="十字路口是年轻部落跳动的后勤心脏，在瑟格拉这样的老兵注视下，将兽人的坚韧、暗矛部族的狡黠和牛头人的传统紧密地联系在一起。",["race:Tauren"]="对于在莫高雷翠绿牧场长大的牛头人来说，向瑟格拉报到标志着他们首次跨越祖辈的疆界，踏入更广阔的部落中履行艰难的职责。"},sec={{t="离开圣地之丘",b="对于一名新手牛头人猎人来说，在莫高雷完成最初的仪式仅仅是个开始。他们祖居之地的葱郁山谷既受庇护又让人感到熟悉，那里驯养的野兽考验的是耐心，而非纯粹的生存能力。梅洛·石蹄深知何时一位猎人的心智已经成熟，需要接受更严酷的考验。他会指示学员收拾装备，离开血蹄村的安全地带，向东穿过山口，进入贫瘠之地那片被烤焦的灌木丛。"},{t="通往十字路口之路",b="穿过红岩峡谷的小路直通广阔、被烈日炙烤的稀树草原，年轻的部落就在那里宣示主权。在卡利姆多中心贸易路线的交汇处，坐落着十字路口，这是一座充斥着兽人、巨魔和牛头人的堡垒据点。瑟格拉·黑棘在那里等待着，她是一位以严苛标准而闻名的资深兽人萨满。她为任何胆敢猎杀贫瘠之地凶猛动物的人提供指导，承诺将他们那粗糙的急躁转化为坚韧的荒野准则。"}},faq={{q="谁提供这个任务？我在哪里可以找到他们？",a="这个任务由雷霆崖猎人高地的牛头人猎人导师梅洛·石蹄提供。",al={"谁给予瑟格拉·黑棘任务","梅洛·石蹄位置","从哪里开始"}},{q="瑟格拉·黑棘在哪里？",a="瑟格拉·黑棘驻扎在贫瘠之地中部的十字路口，站在据点东侧，靠近岗哨和兽栏的地方。",al={"瑟格拉·黑棘位置","瑟格拉在哪里","找到瑟格拉"}},{q="我该如何从莫高雷前往十字路口？",a="离开雷霆崖向南经过血蹄村，然后走莫高雷东面的路穿过峡谷山口进入贫瘠之地。穿过边境大门后，沿着主干土路向东走，直到遇到分岔路，然后向北走就能到达十字路口。",al={"去往十字路口的路线","莫高雷到贫瘠之地","如何从雷霆崖前往十字路口"}},{q="这个任务的目的是什么？",a="这作为一个引导任务，指引在莫高雷开启冒险的玩家前往贫瘠之地十字路口的下一个主要升级枢纽，并将他们与当地的狩猎任务线联系起来。",al={"为什么要做这个任务","瑟格拉·黑棘目的","这是引导任务吗"}},{q="兽人和巨魔能接到这个任务吗？",a="兽人和巨魔在杜隆塔尔会接到一个名为“部落的征召”的平行引导任务，该任务会将他们从剃刀岭指引至贫瘠之地，尽管他们到达后仍然可以见到瑟格拉并从她那里接取任务。",al={"兽人版本","巨魔版本","杜隆塔尔引导任务"}},{q="瑟格拉·黑棘教导猎人什么？",a="瑟格拉会测试前来的猎人，让他们对抗贫瘠之地的本土动物，从平原陆行鸟和徘徊者开始，教导他们真正的精通需要的是耐力、对土地的尊重以及心智的坚韧，而不是蛮力。",al={"瑟格拉角色","瑟格拉做什么","瑟格拉狩猎"}}},fx={["94d282e7"]={q="梅洛·石蹄为什么派你去找瑟格拉·黑棘？",a="梅洛·石蹄看出，你已经不再适合莫高雷那片温和的狩猎场。若要真正踏上猎手之道、磨炼意志，就必须挑战贫瘠之地那些凶猛而桀骜的野兽。梅洛派你去十字路口找瑟格拉·黑棘，因为她经验丰富，能够指导你在那片严酷、烈日炙烤的平原上接受训练。",al={"为何派我去找瑟格拉","梅洛·石蹄的动机","为何前往十字路口"}},bb525daf={q="梅洛为什么选你踏上这段旅程？",a="这趟旅程不是雷霆崖守卫交代的差事或跑腿任务，而是有志成为猎手的人必须经历的成年礼。梅洛无法代你走这条路。你已经展现出继续训练所需的决心与精神；只有亲自前往贫瘠之地的荒野，才能磨炼本能，成长为狩猎大师。",al={"梅洛为何选我","梅洛为何派我去"}}},fp="16,206,24.348.0,26.479.0,46.113.0,34.113.0,44.227.0,34.122.0,34.182.0,41.183.0"}
P.entries["quest:8606"] = {n="螳螂捕蝉！",s="纳瑞安有一个关于赎金的计划：用一袋石头代替钱，由你代替他去。你需要带着他的伪装前往绑书贼在冬泉谷指定的交接地点。这紧接着赎金信的任务。",h="纳瑞安有一个关于赎金的计划：用一袋石头代替钱，由你代替他去。你需要带着他的伪装前往绑书贼在冬泉谷指定的交接地点。这紧接着赎金信的任务。",kw={"绑书贼","诱饵","纳瑞安","第二人选","赎金","冬泉谷"},sec={{t="纳瑞安的诡计",b="赎金信要求纳瑞安亲自去交赎金，他打算这么做，但会耍点小花招。他装了一袋石头，打量了一番你，决定由你来完成这项任务。他的特殊工具包里有一顶头巾、一件长袍和那袋石头，你必须把它带到绑书贼在冬泉谷指定的交接点。当绑书贼出现取货时，纳瑞安要你干掉他们，给这些敢于冒犯他的人一点教训。"},{t="纳瑞安的判决",b="当你回来时，纳瑞安承认他和你就可能低估了这些绑书贼。"}},faq={{q="为什么纳瑞安要让你穿上伪装？",a="赎金信要求纳瑞安亲自去交赎金。他的计划是让你代替他去，并穿上他特殊工具包里的头巾和长袍。",al={"为什么要戴头巾","为什么要伪装","为什么要打扮成纳瑞安"}},{q="交接地点在哪里？",a="在冬泉谷绑书贼指定的交接地点，那是放置装满石头的袋子的地方。",al={"交接点在哪里","我要把袋子带到哪里","交接地点位置"}},{q="赎金袋里装的是什么？",a="纳瑞安往袋子里装的是石头，而不是钱。",al={"袋子里有什么","是真的金子吗","纳瑞安装了什么"}},{q="这个任务之前发生了什么？",a="之前是赎金信的任务，那封信要求用钱来赎回纳瑞安被偷的书，而你已经把书带回给他了。",al={"前置任务","上一个任务","是什么导致了这个任务"}}},fp="6,184,15.384.0,16.87.1,44.171.0,35.127.0,30.50.0,28.102.0"}
P.entries["quest:861"] = {n="猎人之道",s="“猎人之道”是斯考恩·白云长者为莫高雷的有志追踪者提供的试炼。为了证明他们初露锋芒的技巧以及对荒野的尊重，流浪者必须击败狡猾的平原徘徊者，并将它们的爪子呈交给位于雷霆崖猎人高地的梅洛·石蹄。",h="“猎人之道”是斯考恩·白云长者为莫高雷的有志追踪者提供的试炼。为了证明他们初露锋芒的技巧以及对荒野的尊重，流浪者必须击败狡猾的平原徘徊者，并将它们的爪子呈交给位于雷霆崖猎人高地的梅洛·石蹄。",kw={"平原徘徊者","平原徘徊者的爪子","猎人高地","梅洛·石蹄","莫高雷","斯考恩·白云","猎人之道","雷霆崖"},ang={["class:Hunter"]="这项试炼直接考验了荒野的核心准则——在伏击捕食者发动突袭前追踪它们，并解读草原上细微的踪迹。",["faction:Horde"]="这一仪式是部落盟友了解牛头人对自然崇敬之情的一座桥梁，也能让他们在雷霆崖的高地上赢得牛头人的信任。",["race:Tauren"]="对于年轻的牛头人来说，向猎人高地献上徘徊者的爪子是一项奠基性的成人礼，将他们与在那片广袤平原上狩猎过的世世代代祖先联系在一起。"},sec={{t="平原的传统",b="对牛头人而言，狩猎既非仅仅是一项运动，也不是简单的维生手段，而是被视为本族最高的荣誉之一。它需要耐心、对大地母亲的平衡的感知，以及对漫步在草海平原上的野兽的敬畏。斯考恩·白云长者在卡利姆多追踪了数十年，如今在莫高雷休憩，他察觉到了年轻冒险者内心的躁动。与其任由他们漫无目的地游荡，他将他们的志向引导至一项关于成熟与纪律的传统试炼中。"},{t="草原的潜行者",b="为了证明他们的追踪本能是货真价实的，候选者被要求击败莫高雷的平原徘徊者。这些大型猫科动物迅捷、隐蔽且狡猾，是善于伏击的捕食者，极易隐没在平原的高草丛中。收集四套徘徊者的爪子足以证明，初出茅庐的流浪者能够在沦为猎物前发现捕食者，并以其人之道还治其人之身。"},{t="抵达猎人高地",b="取得战利品后，试炼者需登上通往雷霆崖的高耸木塔与栈桥。在猎人高地上，梅洛·石蹄会接收这些徘徊者的爪子。作为一名珍视斯考恩·白云古老智慧的追踪大师，石蹄会以此作为证明，确认试炼者拥有正确的精神，可以继续在卡利姆多的掠食之路上接受指引。"}},faq={{q="谁提供“猎人之道”的任务？",a="该任务由斯考恩·白云提供，他是一位在莫高雷休息的受人尊敬的牛头人平原流浪者，负责指导渴望精通荒野生存之道的年轻冒险者。",al={"任务发布者","谁提供任务","斯考恩·白云"}},{q="我应该把平原徘徊者的爪子交给谁？",a="将徘徊者的爪子带给梅洛·石蹄，他居住在牛头人的主城雷霆崖的猎人高地。",al={"梅洛·石蹄在哪里","任务交付地点","猎人高地"}},{q="为什么选择平原徘徊者的爪子作为贡品？",a="平原徘徊者是莫高雷草原上隐蔽且危险的顶级猎手。成功追踪并击败它们可以证明，试炼者具备了进行进阶狩猎所需的敏锐洞察力、耐心和战斗纪律。",al={"为什么是平原徘徊者","徘徊者爪子的背景","徘徊者是什么"}},{q="这个任务只限猎人职业吗？",a="不。尽管名字如此，斯考恩·白云还是会将这项意志考验提供给任何渴望游历并学习平原传统的年轻部落冒险者。",al={"仅限猎人吗","其他职业能做吗","是给猎人的吗"}},{q="与梅洛交谈后，猎人的旅程会指向何方？",a="一旦梅洛·石蹄认可了你初露的才华，他便会引导你走向更广阔的荒野，即环境更严酷的贫瘠之地，并最终将你引荐给像瑟格拉·黑棘这样经验丰富的追踪者。",al={"接下来是什么","下一个任务","找完梅洛后去哪"}},{q="狩猎在牛头人文化中有什么意义？",a="在牛头人的信仰中，狩猎是最高的荣誉之一。它要求与大地母亲的造物和谐共处，取之有度，并对供养部落的猎物怀有崇高的敬意。",al={"牛头人狩猎背景","牛头人狩猎荣誉","为什么狩猎对牛头人很重要"}}},fp="16,232,25.357.0,30.265.0,20.305.0,45.116.0,43.87.0,53.181.0,50.121.0,61.158.1,54.193.0"}
P.entries["quest:862"] = {n="掘地鼠炖肉",s="“掘地鼠炖肉”是由贫瘠之地十字路口以东的一位兽人格拉布所提供的一项烹饪任务。为了满足沙漠中那狂野的食欲，格拉布派遣饥肠辘辘的冒险者前往南边的巴尔莫丹矮人挖掘场，去收集一批肥硕的掘地鼠，用来炖煮一锅可疑的炖肉。",h="“掘地鼠炖肉”是由贫瘠之地十字路口以东的一位兽人格拉布所提供的一项烹饪任务。为了满足沙漠中那狂野的食欲，格拉布派遣饥肠辘辘的冒险者前往南边的巴尔莫丹矮人挖掘场，去收集一批肥硕的掘地鼠，用来炖煮一锅可疑的炖肉。",kw={"巴尔莫丹","贫瘠之地","烹饪","十字路口","掘地鼠炖肉","矮人","格拉布","老鼠"},ang={["faction:Horde"]="从巴尔莫丹偷猎掘地鼠是一种嘲弄矮人挖掘场的令人满足的方式，同时也能在南贫瘠之地顺便收集口粮。",["profession:Cooking"]="制作“掘地鼠炖肉”教会了基础的边境觅食技巧，将恼人的矿坑害虫变成了能填饱肚子、虽然散发着恶臭的营火餐点。",["race:Undead"]="格拉布喜欢在烹煮前将肉类放置腐烂数周，这使他成为少数几个口味与被遗忘者一致的在世厨师之一。"},sec={{t="贫瘠之地的美味",b="在贫瘠之地这片干旱的土地上求生，需要一种不挑剔的胃口。当经验丰富的猎人们忙着捕杀斑马、平原陆行鸟和迅猛龙时，独居的兽人格拉布却对这种地下啮齿动物产生了奇特的渴望。格拉布整天都声称自己饿得不行，并承诺愿意与任何愿意干这种抓老鼠苦差事的旅行者分享他的秘制食谱。"},{t="矮人的害虫",b="这些生物的指定来源是巴尔莫丹，这是位于南贫瘠之地深处的一处庞大的联盟挖掘场。当矮人探矿者挖掘红色的土地时，他们深层的采石作业无意中惊动了大量掘地鼠的巢穴。尽管矮人们视这些小啮齿动物为虫害，但格拉布却认为这些横行的生物是敌人眼皮底下不可错过的盛宴。"},{t="关于风味的问题",b="准备“掘地鼠炖肉”需要一个强健的胃。据格拉布所说，这些啮齿动物最好是让它们腐烂几周，这样才能散发出那种刺鼻的味道。虽然他也会凑合用新鲜的食材来满足当场饥肠辘辘的冒险者，但他那粗犷的烹饪技术充分展示了卡利姆多边境路边料理的随意与包容。"}},faq={{q="格拉布是谁？",a="格拉布是一位古怪的兽人，驻扎在贫瘠之地十字路口以东的道路旁。他总是很饿，以其独特的烹饪品味和乐于教导过往冒险者烹饪当地害虫而闻名。",al={"格拉布","格拉布是谁","十字路口以东的兽人"}},{q="掘地鼠从哪里来？",a="掘地鼠出没于巴尔莫丹，这是一处位于南贫瘠之地深处、陶拉祖营地以南、剃刀沼泽以北的联盟挖掘场。矮人入侵式的采矿作业扰动了地面，吸引了成群结队的小生物。",al={"掘地鼠在哪里","掘地鼠位置","寻找掘地鼠"}},{q="为什么格拉布特别想要掘地鼠？",a="格拉布认为它们是“每个人最爱的盛宴”，并声称猎杀害虫是每一位经验丰富的冒险者的必经之路。他将它们作为他那丰盛（尽管味道刺鼻）炖肉的核心原料。",al={"为什么要用老鼠","为什么要用掘地鼠","格拉布的动机"}},{q="“掘地鼠炖肉”真的好吃吗？",a="以格拉布的标准来看，这很美味，尽管他的口味相当极端。他公开承认自己更喜欢把肉放烂几周来提升风味，这使得这道菜即使以粗犷的部落标准来看，也属于那种需要点胆量才敢尝试的重口味。",al={"炖肉好吃吗","食用掘地鼠","格拉布的食谱风味"}},{q="为什么巴尔莫丹会有矮人？",a="巴尔莫丹的矮人是一支来自铁炉堡的探险队，他们在南贫瘠之地建立了一座要塞和挖掘场，对土地进行了深度的爆破和挖掘。他们的存在加剧了与部落之间的紧张关系，也惊动了当地的害虫。",al={"贫瘠之地的矮人","为什么选择巴尔莫丹","南贫瘠之地的联盟"}},{q="制作这道炖肉需要特殊的烹饪训练吗？",a="格拉布的指导需要对炉火烹饪和野外处理有基本的了解。任何练习过基础烹饪的人都能学会他将这些啮齿动物炖煮成维持体力餐点的方法。",al={"烹饪要求","我需要烹饪技能吗"}}},fp="12,150,18.249.0,18.202.0,18.208.0,12.159.0,28.209.0,41.172.0,37.168.0,36.239.0,55.160.0"}
P.entries["quest:863"] = {n="逃跑",s="“逃离”是贫瘠之地北部的一项护送任务，冒险者们需要帮助地精飞行员维兹拉克从淤泥沼泽的荆棘谷地精钻探场逃脱。维兹拉克被困在了一台偷来的原型伐木机里，他需要保护，抵挡一波又一波荆棘谷地精雇佣兵的攻击，直到他冲出那个工业坑道。任务结束时，你需要向他在棘齿城的联络人斯布特瓦夫汇报情况。",h="“逃离”是贫瘠之地北部的一项护送任务，冒险者们需要帮助地精飞行员维兹拉克从淤泥沼泽的荆棘谷地精钻探场逃脱。维兹拉克被困在了一台偷来的原型伐木机里，他需要保护，抵挡一波又一波荆棘谷地精雇佣兵的攻击，直到他冲出那个工业坑道。...",kw={"贫瘠之地","护送","点火启动","原型机","棘齿城","伐木机","淤泥沼泽","斯布特瓦夫","荆棘谷地精","维兹拉克"},ang={["faction:Horde"]="荆棘谷地精在淤泥沼泽的石油污染作业是贫瘠之地上一道碍眼的伤疤，任何破坏性干扰都受到当地部族的欢迎。",["profession:Engineering"]="原型伐木机展示了荆棘谷地精顶尖的气动技术和驾驶舱设计，对其进行打捞将是一座工业洞察的宝库。",["race:Gnome"]="维兹拉克仅凭猜测就敢驾驶一台极不稳定的荆棘谷地精机器，这表明地精工匠和侏儒工匠一样，往往都是先动手拆解，然后再问缘由。"},sec={{t="笨拙的逃脱",b="维兹拉克在淤泥沼泽钻探场的深处点火启动了那台偷来的原型机，却很快发现，想要掌控荆棘谷地精的工程造物可没说起来那么容易。由于对控制杆和开关只有最基本的了解，这个地精笨拙地操纵着这台沉重的机器在泥泞的采石场地面上摇晃前行。他那不稳定的驾驶方式和机器轰鸣的关节不可避免地引来了附近的劳工和武装守卫，将本应是一次潜行撤离的行动，变成了一场在挖掘坑道西侧坡道上的混乱逃亡战。"},{t="荆棘谷地精的追击",b="荆棘谷地精绝不会轻视其专利原型机被窃一事。随着机器挣扎着爬上坡道向开阔地带前进，大批荆棘谷地精雇佣兵纷纷部署到位，试图拦截并摧毁这台失控的构造体。尽管原型机拼命反击以保护自己，但如果不借助外力的护卫，这台笨拙的机器根本无法抵挡协同破坏。冲出边缘后，机器终于蹒跚离开了主钻探坑，但随后不久便因严重故障而停摆。"},{t="打捞与回报",b="一旦脱离了直接危险区，原型伐木机彻底报废，瘫倒在热带稀树草原的草地上。维兹拉克死里逃生，他指示营救者去棘齿城向斯布特瓦夫汇报，而他自己则留下来看守残骸。斯布特瓦夫急于在机会窗口关闭前拆解荆棘谷地精的顶尖设计，他立即调动了一支地精打捞小队，将所有尚存完好机制的零件运回港口。"}},faq={{q="维兹拉克是谁，他为什么会在伐木机里？",a="维兹拉克是一名与棘齿城的斯布特瓦夫合作的特工兼机械师。他潜入了荆棘谷地精北部的钻探场，试图偷走他们最新的实验性伐木机原型，但在搞清楚那些陌生的驾驶舱控制装置时，被困在了里面。",al={"维兹拉克是谁","地精为什么在伐木机里","维兹拉克 伐木机"}},{q="这次逃脱发生在哪里？",a="护送任务始于淤泥沼泽的深处。这是一个由荆棘谷地精在贫瘠之地北部运营的受污染工业钻探场，位于干燥的热带稀树草原盆地以北。",al={"逃离任务在哪里","逃脱地点","淤泥沼泽护送"}},{q="必须一路把伐木机护送到棘齿城吗？",a="不用。你只需要护送维兹拉克离开钻探坑，并穿过西侧的坡道。一旦安全离开采石场边缘，机器就会损坏，维兹拉克会告诉你独自返回棘齿城汇报。",al={"我要走多远","护送路线","需要去棘齿城吗"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是一名驻扎在棘齿城码头附近的地精技术员。他负责协调针对竞争对手荆棘谷地精的工业情报工作，并试图获取他们的机械设计，以便从其技术创新中获利。",al={"斯布特瓦夫是谁","提交任务非玩家角色斯布特瓦夫","斯布特瓦夫背景"}},{q="为什么伐木机最后会翻倒？",a="维兹拉克对控制装置几乎一窍不通，而且这台实验性机器在伏击中被推到了极限。它在冲破封锁线时遭受了严重的机械损伤，导致原型机在离开钻探场后立即崩溃。",al={"为什么伐木机损坏","伐木机残骸","原型机故障"}},{q="原型机坠毁后会发生什么？",a="维兹拉克会留在报废的机器旁，而你则前往棘齿城向斯布特瓦夫汇报。斯布特瓦夫会立即安排一支地精打捞队，赶在荆棘谷地精回收之前，采集原型机上价值连城的组件。",al={"打捞队","接下来发生什么","逃离任务结论"}}},fp="10,269,16.406.0,23.354.0,18.429.1,51.252.0,34.158.0,58.198.1,20.215.0,43.226.1,41.234.1"}
P.entries["quest:8642"] = {n="银脉长者",s="银脉长者是一位受人尊敬的先祖之魂，他会在春节期间现身于洛克莫丹塞尔萨玛上方的山丘顶上。旅行者们会向他致敬，以纪念艾泽拉斯各个古老种族之间的久远联系。为了感谢人们对他本人及其文化遗产的认可，他会赐予旅行者们先祖的祝福。",h="银脉长者是一位受人尊敬的先祖之魂，他会在春节期间现身于洛克莫丹塞尔萨玛上方的山丘顶上。旅行者们会向他致敬，以纪念艾泽拉斯各个古老种族之间的久远联系。为了感谢人们对他本人及其文化遗产的认可，他会赐予旅行者们先祖的祝福。",kw={"先祖","先祖硬币","长者","洛克莫丹","春节","银脉长者","塞尔萨玛"},ang={["faction:Alliance"]="对于途径洛克莫丹的联盟旅行者来说，登上塞尔萨玛上方的山脊，可以在猎杀穴居人的间隙获得片刻宁静，以缅怀古老的逝者。",["race:Dwarf"]="银脉长者就在矮人定居点塞尔萨玛旁休息，他与这些坚韧的岩石住民以及他们对古老历史的崇敬之情有着一种心照不宣的羁绊。"},sec={{t="塞尔萨玛的守望者",b="银脉长者伫立在塞尔萨玛上方连绵起伏的山脊上，静静地守护着这里，提醒着人们勿忘往昔。作为春节期间受到尊崇的一位人物，他象征着往昔岁月里长存的记忆。尽管洛克莫丹周遭的土地正遭受穴居人入侵和当地纷争的困扰，银脉长者依然在他俯瞰的高地上静静地注视着这一切。"},{t="向古老的种族致敬",b="像银脉长者这样的灵魂，起到了连接现代住民与古老血脉的桥梁作用。当冒险者们前来寻访他时，他会对旅行者依然向艾泽拉斯的古老种族表示敬意而感到欣慰。他的问候充满了先祖带来的温情，并会向那些尊敬他的人赠予一份纪念信物。"}},faq={{q="谁是银脉长者？",a="银脉长者是一位在春节期间显灵的先祖之魂。节日期间，他会待在洛克莫丹塞尔萨玛附近的高耸悬崖顶上休息。",al={"银脉长者","银脉长者是谁","银脉长者洛克莫丹"}},{q="我在哪里可以找到银脉长者？",a="他位于洛克莫丹塞尔萨玛镇上方的一座草木丛生的山丘上。",al={"银脉长者位置","银脉长者在哪里","找到银脉长者"}},{q="寻访银脉长者的目的是什么？",a="冒险者们会在春节期间寻访他，以向先祖和古老的种族致敬，并以此获得一份节日信物和祝福作为回报。",al={"为什么要拜访银脉长者","银脉长者有什么用","银脉长者的目的"}},{q="他所说的“古老的种族”是指什么？",a="他指的是那些在现代冲突成为世界焦点之前，就已经生活在艾泽拉斯并塑造了这个世界的古老民族，以此纪念他们传承至今的精神。",al={"古老的种族含义","为什么要纪念古老的种族"}},{q="银脉长者对部落旅行者友好吗？",a="是的。春节期间受到尊崇的先祖长者们欢迎所有心怀和平、前来缅怀先祖的旅行者，不论其阵营背景如何。",al={"部落可以和银脉长者对话吗","部落银脉长者"}},{q="银脉长者与穴居人入侵有任何关联吗？",a="没有。尽管洛克莫丹正饱受穴居人入侵和挖掘场纠纷的困扰，但银脉长者与当地的军事冲突完全无关，他只专注于先祖崇拜。",al={"银脉长者与穴居人","银脉长者在对抗穴居人吗"}}},fp="20,217,22.210.0,24.167.0,24.146.0,34.70.0,52.151.0,39.151.0,48.122.0,64.161.0"}
P.entries["quest:8646"] = {n="雷锤长者",s="锤吼长者是一位在春节期间造访的先祖之魂，他伫立在暴风城的公园区。他会奖励那些停下脚步缅怀他的族人，并对艾泽拉斯长者种族悠久传承怀有敬意的旅者。即便是在人类领土的核心地带，他的存在也提醒着世人，那些古老的羁绊并未断绝。",h="锤吼长者是一位在春节期间造访的先祖之魂，他伫立在暴风城的公园区。他会奖励那些停下脚步缅怀他的族人，并对艾泽拉斯长者种族悠久传承怀有敬意的旅者。即便是在人类领土的核心地带，他的存在也提醒着世人，那些古老的羁绊并未断绝。",kw={"先祖","锤吼长者","公园区","锤吼","春节","往昔种族","暴风城"},ang={["faction:Alliance"]="造访公园区的联盟英雄会在锤吼长者身上感受到一份提醒，关于敬意、和平以及这个世界共同的先祖过往。",["faction:Horde"]="接触锤吼长者对部落朝圣者来说是一项大胆的挑战，他们需要深入暴风城并抵达公园区，以向先祖致敬。",["race:Human"]="站在暴风城的公园区，锤吼长者提醒着人类要尊重艾泽拉斯那早于现代王国建立之前的深厚历史。"},sec={{t="缅怀先祖之血",b="在春节期间，受人敬仰的先祖之灵会显现在艾泽拉斯各处，为每一位花时间致以敬意的旅者提供智慧与祝福。锤吼长者出现在暴风城的公园区。尽管他站立在现代人类文明的核心附近，但他的出现提醒着过往的冒险者：在如今的王国崛起之前，这个世界曾是由在此漫步的远古种族所塑造的。"},{t="先祖敬意的信物",b="向锤吼长者致意既不需要武力考验，也不需要冒险起誓，只需对过去表达一份简单的敬意。当现世的居民依然抽出时间祭奠往昔的种族时，他会流露出宁静的宽慰与感激。为了回报这份铭记与尊重，长者会赠予旅者一枚仪式性的信物，象征着在世一代与先祖之灵之间永恒的共鸣。"}},faq={{q="锤吼长者是谁？",a="锤吼长者是一位在春节期间现身的先祖之魂。他代表了艾泽拉斯的古老血脉，伫立在暴风城，为那些向他致敬的人提供祝福与信物。",al={"锤吼","谁是锤吼","锤吼长者身份"}},{q="在哪里可以找到锤吼长者？",a="春节期间，锤吼长者会出现在暴风城的公园区。",al={"锤吼位置","锤吼在哪里","锤吼艾尔文"}},{q="为什么锤吼长者会提到“往昔种族”？",a="他的话语反映了春节对古老传统和祭祖的庆祝，旨在纪念那些在现代定居点崛起之前，帮助塑造了艾泽拉斯的远古先民与传统。",al={"往昔种族含义","锤吼的含义"}},{q="锤吼长者提供什么信物？",a="他提供先祖硬币，这是春节期间先祖之灵赐予那些寻找长者并致以敬意的旅者的仪式性信物。",al={"锤吼奖励","锤吼信物","他给什么"}},{q="部落的冒险者可以与锤吼长者交谈吗？",a="可以。春节期间的先祖之灵超越了阵营战争的界限，尽管由于他位于联盟首都暴风城，部落旅者在前往时必须小心行事。",al={"部落能和锤吼说话吗","锤吼部落"}},{q="这次遭遇与活跃的节日有关吗？",a="锤吼长者仅在每年的春节期间显现，他会暂时出现以赐予祝福，随后便会消散回到灵界。",al={"锤吼一直都在吗","春节长者"}}},fp="21,126,22.248.0,29.224.0,25.199.0,37.91.0,53.165.0,40.156.0,51.100.0,44.121.0"}
P.entries["quest:8648"] = {n="暗灵长者",s="暗灵长者是春节期间在幽暗城可以接到的一项季节性任务。通过寻找暗灵长者，旅行者们可以向艾泽拉斯各地的远古灵魂致敬，并获得一枚先祖硬币作为回报。",h="暗灵长者是春节期间在幽暗城可以接到的一项季节性任务。通过寻找暗灵长者，旅行者们可以向艾泽拉斯各地的远古灵魂致敬，并获得一枚先祖硬币作为回报。",kw={"祖先","先祖硬币","暗灵长者","长者","春节","幽暗城"},ang={["faction:Horde"]="暗灵长者让部落成员可以直接在盟友的首都内安全地参与大陆范围内的春节祭典。",["race:Undead"]="对于走在他们昔日王国废墟上的被遗忘者来说，暗灵长者提供了一种令人毛骨悚然的提醒，让他们回想起天灾军团和洛丹伦陷落之前的往昔岁月。"},sec={{t="幽暗城的灵魂",b="春节期间，远古暗夜精灵和土灵祖先的灵魂会出现在各地，分享他们的智慧与祝福。暗灵长者居住在幽暗城阴影笼罩的大厅中，见证着现代世界，并为那些追寻世界起源的人们提供祭奠与回忆。"},{t="向祖先致敬",b="拜访暗灵长者可以满足向可敬的亡者和艾泽拉斯永恒守护者表示尊重的古老习俗。为了表彰这种朝圣之旅，这位灵魂会赠予旅行者一枚先祖硬币，作为善意和永恒记忆的信物。"}},faq={{q="拜访暗灵长者的目的是什么？",a="在春节期间拜访暗灵长者，探险者们可以向艾泽拉斯的远古先民致敬。与他交谈即可完成任务并获得一枚先祖硬币。",al={"暗灵长者目标","为什么要拜访暗灵长者","暗灵长者任务目的"}},{q="哪里可以找到暗灵长者？",a="暗灵长者显身于洛丹伦废墟的王座厅，就在被遗忘者首都幽暗城的上方。",al={"暗灵长者位置","暗灵长者在哪里","暗灵长者幽暗城位置"}},{q="什么是春节？",a="春节是艾泽拉斯每年一度的纪念与新生之季，旨在庆祝战胜燃烧军团，并向引导凡人种族的远古长者表示敬意。",al={"春节传说","为什么长者会显身","什么是长者"}},{q="长者代表了什么？",a="长者是远古的灵魂，通常与暗夜精灵或早期的土灵文化有关，他们在春节期间现身，祝福那些铭记他们事迹并将远古教训传承下去的人们。",al={"长者是谁","春节长者传说","祖先之魂"}},{q="联盟探险者可以与暗灵长者交谈吗？",a="暗灵长者会迎接任何能够找到他的旅行者，尽管联盟玩家必须闯过重兵把守的被遗忘者首都才能做到这一点。",al={"联盟与暗灵长者","联盟能否获取暗灵长者任务","暗灵长者联盟"}},{q="什么是先祖硬币？",a="先祖硬币是春节期间长者们赠予的节日代币，象征着对远古的敬畏，可以兑换节日服饰和季节性纪念品。",al={"什么是先祖硬币","先祖硬币用途","春节硬币"}}},fp="18,158,25.298.0,22.242.0,47.127.0,34.102.0,27.180.0,29.195.0,49.138.0,27.166.0"}
P.entries["quest:8649"] = {n="雷眉长者",s="雷眉长者是春节期间受到尊崇的先祖之魂之一，他就站在闪金镇附近的水边。前往拜访这位长者的旅者们，都是为了向艾泽拉斯的古老传统与旧日种族致敬。作为对这份尊重的回报，长者会赐予一枚小小的纪念品。",h="雷眉长者是春节期间受到尊崇的先祖之魂之一，他就站在闪金镇附近的水边。前往拜访这位长者的旅者们，都是为了向艾泽拉斯的古老传统与旧日种族致敬。作为对这份尊重的回报，长者会赐予一枚小小的纪念品。",kw={"先祖","雷眉长者","艾尔文森林","铁匠铺","闪金镇","春节","信物"},ang={["faction:Alliance"]="雷眉长者静静地伫立在艾尔文森林的中心，对于路过闪金镇的年轻联盟冒险者来说，他是最容易找到的先祖之魂之一。",["race:Human"]="对于居住在艾尔文的人类来说，雷眉长者的存在时刻提醒着人们，在暴风城的城墙与近期的战争之外，还有着更加古老的历史。"},sec={{t="闪金镇的先祖之魂",b="雷眉长者显身于闪金镇铁匠铺后方那片宁静的池塘旁。虽然小镇里通常熙熙攘攘，挤满了身披铠甲的卫兵、商贩以及正准备踏入艾尔文森林的疲惫冒险者，但这位受人尊敬的先祖的到来，却带来了一丝静谧的片刻。雷眉长者站在艾尔文森林那宁静的树荫下，欢迎任何愿意铭记这片疆域悠久历史的人。"},{t="纪念旧日种族",b="春节标志着伟大的先祖之灵重返人间，行走在生者之中的日子。雷眉长者称赞那些愿意花时间缅怀前人的凡间旅者。为了感谢人们对他族先辈智慧与遗产的认可，他会赐予自己的祝福以及一枚象征节日的纪念硬币。"}},faq={{q="我在哪里可以找到雷眉长者？",a="雷眉长者就站在艾尔文森林，闪金镇铁匠铺后方的池塘旁边。",al={"雷眉位置","雷眉长者在哪里","闪金镇长者"}},{q="雷眉长者是谁？",a="雷眉长者是一位先祖之魂，他会在春节期间现身，代表着艾泽拉斯旧日种族中受人尊崇的长者们。",al={"雷眉是谁","雷眉背景故事","雷眉长者身份"}},{q="拜访雷眉长者的目的是什么？",a="拜访雷眉长者可以让旅者们在节日期间向古老的先祖表达敬意。作为对传承这些传统的奖励，他会给予旅者问候与一份感激之礼。",al={"为何拜访雷眉","雷眉长者任务","雷眉长者目的"}},{q="部落玩家可以与雷眉长者交谈吗？",a="虽然春节的长者们会尊重每一位以和平之心拜访他们的人，但闪金镇是守备森严的联盟领地，部落旅者前往此处极其危险。",al={"部落雷眉","部落能否拜访雷眉"}},{q="长者提供什么信物？",a="雷眉长者提供先祖硬币，这是长者们在节日期间分享的、象征尊重与纪念的传统信物。",al={"雷眉奖励","什么信物","雷眉春节硬币"}},{q="为什么雷眉长者会提到“旧日种族”？",a="雷眉长者称赞那些能意识到现代文明建立在古代先民所塑造的土地之上，并能铭记在现代王国崛起前就已存在许久的习俗的旅者们。",al={"旧日种族含义","为什么是旧日种族","雷眉对话"}}},fp="19,182,21.239.0,24.262.0,33.104.0,23.150.0,48.150.0,43.152.0,32.135.0,45.191.0"}
P.entries["quest:865"] = {n="迅猛龙角",s="麦伯克·米希瑞克斯，一位在棘齿城颇具进取心的地精，认为当地迅猛龙的狡诈全都储存在它们的角里。他雇佣旅行者横穿贫瘠之地狩猎日鳞镰爪龙，收集完好的角来进行一项离奇的商业投机。",h="麦伯克·米希瑞克斯，一位在棘齿城颇具进取心的地精，认为当地迅猛龙的狡诈全都储存在它们的角里。他雇佣旅行者横穿贫瘠之地狩猎日鳞镰爪龙，收集完好的角来进行一项离奇的商业投机。",kw={"贫瘠之地","完整的迅猛龙角","麦伯克·米希瑞克斯","迅猛龙角","棘齿城","聪明饮料","热砂港","日鳞镰爪龙"},ang={["class:Hunter"]="熟悉卡利姆多迅猛龙群的猎人都很清楚它们致命的狡诈，尽管麦伯克关于智慧可以装瓶的说法纯属地精式的江湖骗术。",["faction:Alliance"]="棘齿城为联盟冒险者在部落统治的贫瘠之地提供了一个难得的中立立足点，使他们有机会通过像麦伯克这样的零工来赚取金币和热砂港的声望。"},sec={{t="地精的创业精神",b="棘齿城里到处都是寻找下一个发财机会的地精，麦伯克·米希瑞克斯也不例外。在观察到贫瘠之地的迅猛龙与其它地区的野兽相比表现出了异常的狡诈和协作能力后，麦伯克得出了一个古怪的结论：它们的智慧一定集中在它们的角里。理所当然，他并没有进行正式的科学调查，而是本能地想到要利用这一理论资源来牟利。"},{t="日鳞镰爪龙",b="为了验证他的理论，麦伯克需要来自日鳞镰爪龙的完好标本，它们是该地区最致命的掠食者之一。这些迅猛龙在贫瘠之地的南部地区和接近灰谷的北部边界地带出没。猎杀它们并完整地取出它们的角需要相当高超的武艺，因为这些野兽成群结队，而且会拼死保卫自己的领地。"},{t="致富秘方",b="一旦拿到手，麦伯克的计划既简单又一如既往地粗糙：把完好的角磨成细粉，酿成可饮用的药剂。他把这种混合物称为“聪明饮料”，设想把这些酒卖给那些渴望买到“瓶装智慧”的顾客，并坚信这能让他一夜暴富。"}},faq={{q="为什么麦伯克·米希瑞克斯想要迅猛龙角？",a="麦伯克认为贫瘠之地迅猛龙表现出的非凡智慧都储存在它们的角里。他打算把它们磨成粉末酿成“聪明饮料”，并以此牟取暴利。",al={"为什么需要迅猛龙角","麦伯克的目标","麦伯克想要什么"}},{q="日鳞镰爪龙位于何处？",a="日鳞镰爪龙在贫瘠之地的两个不同区域徘徊：南部地区以及靠近灰谷森林边界的北部平原。",al={"镰爪龙在哪里","日鳞镰爪龙位置","迅猛龙角位置"}},{q="迅猛龙角真的有魔法或增强心智的作用吗？",a="虽然贫瘠之地的迅猛龙以狡诈著称，但麦伯克认为它们的大脑或智慧存在于颅骨的角中，这完全是地精的伪科学，纯粹是由利益驱动，而非自然历史。",al={"聪明饮料有效吗","迅猛龙聪明吗","迅猛龙智慧设定"}},{q="麦伯克·米希瑞克斯是谁？",a="麦伯克·米希瑞克斯是一位雄心勃勃的地精商人，常驻于棘齿城港口，总是琢磨着各种可疑的计划和药剂，想要从过往的旅行者身上大发横财。",al={"麦伯克是谁","麦伯克·米希瑞克斯背景","棘齿城的麦伯克"}},{q="收集到角之后会发生什么？",a="一旦麦伯克收到完好的角，他就会开始着手将它们磨成粉末并混入酒中，这直接引出了他的下一个项目，“聪明饮料”。",al={"迅猛龙角后续任务","聪明饮料任务","迅猛龙角任务线"}},{q="联盟玩家可以帮助麦伯克完成这项任务吗？",a="可以。棘齿城是由热砂港经营的开放港口，麦伯克是一个中立地精，很乐意与部落和联盟做生意。",al={"这是部落专属任务吗","联盟的迅猛龙角","联盟可以做迅猛龙角任务吗"}}},fp="12,192,23.321.0,24.322.0,19.230.1,42.158.0,39.100.0,52.187.0,22.166.0,40.104.1,47.146.0"}
P.entries["quest:8652"] = {n="灰石长者",s="灰石长者是春节的一位遭遇NPC，位于提瑞斯法林地的布瑞尔镇附近。在节日期间，旅行者们会在荒芜的树林中寻找灰石长者，以向艾泽拉斯的远古先辈致敬。向这位灵魂表示敬意可以获得他的祝福以及节日代币。",h="灰石长者是春节的一位遭遇NPC，位于提瑞斯法林地的布瑞尔镇附近。在节日期间，旅行者们会在荒芜的树林中寻找灰石长者，以向艾泽拉斯的远古先辈致敬。向这位灵魂表示敬意可以获得他的祝福以及节日代币。",kw={"布瑞尔","先祖硬币","灰石长者","春节","提瑞斯法林地"},ang={["class:Druid"]="德鲁伊们崇敬春节的长者，认为他们是天崩地裂前那个古老世界的纽带，而不去理会他们所处的那片充满纷争的阵营界限。",["faction:Alliance"]="寻求灰石长者的联盟冒险者必须小心穿过提瑞斯法林地，因为布瑞尔是被遗忘者重兵把守的避难所。",["race:Undead"]="对于生活在布瑞尔的被遗忘者来说，这些古老先祖灵魂的到来，清晰地提醒着他们艾泽拉斯那段超越了近期天灾军团悲剧的深厚历史。"},sec={{t="布瑞尔的幽灵守望者",b="当被遗忘者在提瑞斯法林地的废弃庄园和墓地中栖息时，春节带来了与远古时代意想不到的共鸣。灰石长者以幽灵长者的形态出现在布瑞尔镇外。即使在这个被天灾军团摧毁并被亡灵收复的国度里，他依然欢迎那些停下脚步向古老传统致敬的朝圣者。"},{t="纪念古老的种族",b="春节标志着那些早已逝去时代的伟大灵魂回归的时刻，他们会带来智慧与感激。当旅行者接近灰石长者时，他会感叹尽管这片土地目前已然衰败，但提瑞斯法的居民们依然向先祖表达敬意，这让他感到非常欣慰，并会向问候他的旅行者赠予一枚先祖硬币。"}},faq={{q="灰石长者位于何处？",a="灰石长者可以在提瑞斯法林地的布瑞尔定居点附近找到，他静静地站在镇外的路边。",al={"灰石长者位置","灰石长者在哪","灰石长者坐标"}},{q="与灰石长者交谈会发生什么？",a="在问候他时，灰石长者会赞扬你对艾泽拉斯古老先民的尊敬，并作为春节庆祝活动的一部分，奖励你一枚先祖硬币。",al={"灰石长者奖励","春节灰石长者","他给你什么"}},{q="为什么一位古老的长者会站在提瑞斯法林地？",a="在春节期间，古老先祖的灵魂会显现在艾泽拉斯的各个角落，从卡多雷的森林到饱受战争与瘟疫蹂躏的土地。灰石长者守护着洛丹伦的北部地区，以确保它的历史不会被死亡完全掩盖。",al={"为什么他在提瑞斯法","灰石长者背景故事","灰石长者是谁"}},{q="联盟玩家可以拜访灰石长者吗？",a="灰石长者本人是一位中立的智慧之灵，会与联盟和部落的成员交谈。然而，由于他就在被遗忘者的布瑞尔镇外，联盟冒险者必须小心当地的守卫。",al={"联盟可以和灰石长者对话吗","联盟灰石长者","灰石长者敌对"}},{q="先祖硬币有什么用途？",a="从像灰石长者这样的长者那里收集到的先祖硬币，可以在春节期间于月光林地兑换节日服装、烟花配方以及其他庆祝物品。",al={"先祖硬币用途","春节硬币是干什么用的"}},{q="灰石长者是被遗忘者吗？",a="不是。尽管他的名字和在布瑞尔附近的幽灵形象容易让人产生误解，但灰石长者是春节期间受人纪念的古老灵魂之一，他属于艾泽拉斯长者们的古老血脉，而非希尔瓦娜斯的被遗忘者。",al={"灰石长者是亡灵吗","灰石长者是被遗忘者吗"}}},fp="19,216,24.295.0,24.274.0,33.71.0,47.144.0,52.231.0,43.192.0,38.177.0,39.205.0"}
P.entries["quest:8653"] = {n="金井长者",s="金井长者是春节的一项任务，由卡拉诺斯（丹莫罗）的金井长者发布。向他致敬体现了穿越矮人冰封大地寻找先祖之灵的悠久传统。作为对他尊敬的回报，他会赐予你先祖的祝福。",h="金井长者是春节的一项任务，由卡拉诺斯（丹莫罗）的金井长者发布。向他致敬体现了穿越矮人冰封大地寻找先祖之灵的悠久传统。作为对他尊敬的回报，他会赐予你先祖的祝福。",kw={"先祖","先祖硬币","丹莫罗","金井长者","铁炉堡","卡拉诺斯","春节","雷酒"},ang={["faction:Alliance"]="金井长者位于安全的联盟领地，对于在寒脊山谷和铁炉堡之间旅行的年轻联盟英雄来说，他是最容易拜访的长者之一。",["faction:Horde"]="想要到达金井长者身边，需要潜入丹莫罗深处，冒着危险穿过铁炉堡高大门外巡逻的矮人卫兵和刺骨寒风。",["race:Dwarf"]="对于从铁炉堡返回的矮人来说，在卡拉诺斯的主要酒馆外遇见一位古老血统的长者，将永恒的崇敬与家乡的骄傲连接在了一起。"},sec={{t="山峦的问候",b="金井长者站在卡拉诺斯雷酒酿制厂旁那刺骨的寒风中，注视着通往铁炉堡大门的繁忙贸易道路。在春节期间，这位受人尊敬的长者欢迎着疲惫的旅者、冒险者和当地居民，体现了远古凡人漫步在艾泽拉斯星空下的古老记忆。"},{t="向先祖致敬",b="接近金井长者，可以在丹莫罗严酷的冬风中获得片刻沉思。他表达了对凡人依然铭记古老种族及其事迹的欣慰与喜悦，感谢所有停下旅途脚步表达敬意的人。作为回报，他会授予一枚神圣的先祖硬币作为祝福的象征。"}},faq={{q="我在哪里可以找到金井长者？",a="金井长者站在卡拉诺斯镇的雷酒酿制厂旅店外，位于丹莫罗的雪路上，就在铁炉堡大门的西南方。",al={"金井长者位置","金井长者在哪里","金井长者坐标"}},{q="寻找金井长者的目的是什么？",a="访问金井长者是春节庆祝活动的一部分，旨在向世界上的远古之灵致敬。向他表达敬意证明了凡人种族没有忘记古代的牺牲与智慧。",al={"为什么要拜访金井长者","金井长者的作用","金井长者任务"}},{q="金井长者提供什么奖励？",a="他会奖励旅行者一枚先祖硬币，这是由节日长者赐予的祝福信物，可以交给月光林地的塞纳里奥议会来换取节日庆祝物品。",al={"金井长者奖励","金井长者的奖励是什么","金井长者先祖硬币"}},{q="部落的旅行者可以完成这个任务吗？",a="可以。像金井长者这样的节日长者是中立的先祖之灵，欢迎任何阵营的冒险者，尽管部落的旅行者必须小心，以避开在卡拉诺斯巡逻的矮人山地巡逻队员。",al={"部落能与金井长者交谈吗","部落 金井长者","金井长者对部落友好吗"}},{q="为什么金井长者居住在丹莫罗？",a="春节的长者们出现在艾泽拉斯每一个凡人文明建立了持久聚居地的地方。金井长者选择卡拉诺斯，是为了与居住在矮人王国中心附近的居民分享他的祝福。",al={"金井长者为什么在卡拉诺斯","为什么在丹莫罗","金井长者 矮人领地"}},{q="这个任务可以完成不止一次吗？",a="不可以。对金井长者的敬意在每个节日季节只能表达一次，为寻求他指引的每位冒险者提供一次祝福和一枚硬币。",al={"金井长者任务可重复吗","金井长者日常","金井长者重置"}}},fp="18,181,19.257.0,22.184.0,32.154.0,50.187.0,40.168.0,43.186.0,45.195.0,43.109.0"}
P.entries["quest:86574"] = {n="Stonetalon Supply Run",s="石爪峰的旅店老板 Faralia 正在等待补给。信使遇害，货物也不知所踪。Pridewing wyverns 可能带走了那些包裹。",h="石爪峰的旅店老板 Faralia 正在等待补给。信使遇害，货物也不知所踪。Pridewing wyverns 可能带走了那些包裹。",kw={"信使","旅店老板 faralia","失踪的货物","pridewing wyverns","stonetalon supplies","stonetalon supply run"},sec={{t="失踪的货物",b="一名死去的信使躺在散落的行囊旁，旁边的字条写明收货人是石爪峰的旅店老板 Faralia。你受托从 Pridewing Wyverns 手中找回失踪的 Stonetalon Supplies。Faralia 希望货物尽快送达。"},{t="Faralia 的谢意",b="Faralia 得知信使没能活下来。她说会妥善使用找回的补给，不让信使白白牺牲。"}},faq={{q="谁会收到补给",a="字条写明收货人是石爪峰的旅店老板 Faralia。",al={"补给的收货人","faralia 的货物"}},{q="信使遭遇了什么",a="信使遇害了，尸体上留有多处被 Pridewing wyverns 攻击的痕迹。",al={"信使遇害","这里发生了什么"}},{q="什么东西不见了",a="原本要送给旅店老板 Faralia 的一批补给，从信使丢弃的行囊中不见了。",al={"失踪的补给","行囊里有什么"}},{q="补给可能在哪里",a="Pridewing Wyverns 可能带走了那些补给包裹，用来铺设巢穴。",al={"飞龙补给","包裹在哪里"}},{q="Faralia 需要什么",a="Faralia 正在石爪峰等待那批原本要送给她的失踪补给。",al={"旅店老板想要什么","stonetalon supply run"}}},fp="21,168,15.251.0,16.139.1,25.74.0,29.88.0,18.96.0,28.83.0,23.92.0"}
P.entries["quest:86576"] = {n="Bloodfury Trinkets",s="摩罗加尔要你把血怒鹰身人从焦炭谷收集来的闪光日长石带给他。他说，这些石头与天空中的光芒相连。",h="摩罗加尔要你把血怒鹰身人从焦炭谷收集来的闪光日长石带给他。他说，这些石头与天空中的光芒相连。",kw={"血怒鹰身人","血怒饰物","焦炭谷","闪光日长石","天空中的光芒","摩罗加尔","圣坛","日长石"},sec={{t="鹰身人的石头",b="血怒鹰身人会收集闪亮的物品，其中包括金黄色的日长石。摩罗加尔就在你上方的山丘上，他提过想用这些石头。他请你把找到的闪光日长石带给他。"},{t="石中之光",b="摩罗加尔说，日长石映照着太阳的威严，可以为圣坛和家园点缀点点微光。到了夜晚，月亮又赋予它们银色的美。他觉得这些石头提醒着他，自己与天空中的光芒有所联结。"}},faq={{q="血怒鹰身人收集什么？",a="血怒鹰身人收集闪亮的物品，其中包括金黄色的日长石。",al={"鹰身人的闪亮物品","血怒饰物","鹰身人收集什么"}},{q="谁想要日长石？",a="摩罗加尔就在你上方的山丘上，他提过想用日长石。",al={"谁需要日长石","摩罗加尔饰物","日长石需求者"}},{q="摩罗加尔用日长石做什么？",a="他说，可以用它们为圣坛和家园点缀点点微光。",al={"摩罗加尔为何想要石头","日长石用途","石头有什么用"}},{q="日长石对摩罗加尔意味着什么？",a="它们让他想起自己与天空中的光芒有所联结。",al={"日长石的意义","天空之光石头","石头为何特别"}}},fp="18,140,15.207.0,14.217.0,42.78.0,24.75.0,38.79.0,40.70.0"}
P.entries["quest:86585"] = {n="Banner of the Fallen",s="Banner of the Fallen讲述了勇敢的矮人山地探险者伊尔瓦的悲惨故事。她深入穴居人的领地寻找失踪的战友。在战斗中不幸牺牲且她的铁炉堡旗帜被践踏后，再次竖起这面旗帜会将杀害她的凶手引出来接受正义的审判。",h="Banner of the Fallen讲述了勇敢的矮人山地探险者伊尔瓦的悲惨故事。她深入穴居人的领地寻找失踪的战友。在战斗中不幸牺牲且她的铁炉堡旗帜被践踏后，再次竖起这面旗帜会将杀害她的凶手引出来接受正义的审判。",kw={"陨落者之旗","拉格弗斯上尉","裂颅者","铁炉堡旗帜","铁炉堡标准旗","山地探险者伊尔瓦","穴居人","伊尔瓦"},ang={["faction:Alliance"]="铁炉堡的旗帜代表了在穴居人领地中矮人的忠诚与蔑视。保护它也是为了向那些为联盟坚守阵地的牺牲士兵致敬。",["race:Dwarf"]="山地探险者伊尔瓦死于捍卫铁炉堡的荣誉和寻找失踪的族人。找回她被践踏的旗帜并为她复仇，触及了矮人自豪感和职责的核心。"},sec={{t="被践踏的旗帜",b="铁炉堡一面被践踏的旗帜标示出了一位联盟斥候惨死的地方。山地探险者伊尔瓦深入穴居人出没的领地，决心找到巡逻时失踪的战友，她带着这座城市的旗帜作为蔑视敌人的宣言。她的决心被一名强大的穴居人打断，后者以足以击碎她防御的力量击倒了她，让这面骄傲的旗帜被丢弃在泥土中。"},{t="为伊尔瓦复仇",b="负责此事的穴居人，一只被称为“裂颅者”的野兽，认出了这面旗帜及其构成的威胁。竖起这面倒下的旗帜是一种公开的挑战，将这只怪物引回空地以保卫它的猎物。击败裂颅者后，这面破损的旗帜可以被交还给拉格弗斯上尉，他会确保伊尔瓦的武器被传承下去，并将旗帜清洗保存，作为矮人坚韧精神的纪念。"}},faq={{q="牺牲的山地探险者是谁？",a="牺牲的矮人是山地探险者伊尔瓦，一位思想独立的士兵。她深入穴居人的地盘去寻找那些巡逻时再也没回来的山地探险者同伴。她带着铁炉堡的旗帜，试图证明矮人对抗穴居人的决心，但在那之后被击倒。",al={"山地探险者是谁","伊尔瓦背景故事","谁带着旗帜牺牲了"}},{q="任务逝者之旗的内容是什么？",a="逝者之旗涉及发现山地探险者伊尔瓦的尸体以及她所携带的铁炉堡被践踏的旗帜。通过再次竖起这面旗帜，冒险者可以引出她的杀手——穴居人裂颅者，为她复仇，然后将旗帜交还给拉格弗斯上尉。",al={"阵亡者的旗帜是什么","阵亡者的旗帜发生了什么","铁炉堡旗帜任务"}},{q="谁杀害了山地探险者伊尔瓦？",a="伊尔瓦是被一只被称为“裂颅者”的穴居人杀害的，它很可能使用了一根沉重的尖刺棍棒，给了她头部致命一击并打飞了她的头盔。竖起铁炉堡的旗帜会诱使这只生物回来。",al={"谁杀了伊尔瓦","哪只穴居人杀了山地探险者","裂颅者穴居人"}},{q="拉格弗斯上尉是谁？",a="拉格弗斯上尉是负责山地探险者行动的矮人军官，他负责接收找回的旗帜。他认可伊尔瓦的勇敢和坚定的独立精神，承诺会清洗并展示这面旗帜以纪念她。",al={"拉格弗斯上尉是谁","在哪里交还旗帜","拉格弗斯上尉旗帜"}},{q="为什么山地探险者伊尔瓦独自进入穴居人的领地？",a="伊尔瓦独自出发，去调查几名在穿过穴居人领地巡逻时失踪且未归的山地探险者的下落。她以极其独立而闻名，带着旗帜是为了表明铁炉堡永远不会向穴居人屈服。",al={"为什么伊尔瓦进入穴居人领地","为什么伊尔瓦是一个人","伊尔瓦失踪的巡逻队"}},{q="穴居人裂颅者是如何被引出来的？",a="裂颅者在击倒山地探险者伊尔瓦时记住了这面铁炉堡的旗帜。再次插上并竖起这面被践踏的旗帜会激怒这只穴居人，使其回来完成它未竟的杀戮。",al={"如何召唤裂颅者","呼唤裂颅者","竖起旗帜"}}},fp="20,177,21.319.0,18.399.1,31.250.0,45.216.0,28.206.0,25.230.0,55.217.0,40.186.0"}
P.entries["quest:86613"] = {n="Excavation Tools",s="麦格玛尔·落斧请你带回矮人被石腭怪赶出挖掘场时遗弃的工具。等到入侵局势得到控制，这些工具就能帮助挖掘者恢复工作。",h="麦格玛尔·落斧请你带回矮人被石腭怪赶出挖掘场时遗弃的工具。等到入侵局势得到控制，这些工具就能帮助挖掘者恢复工作。",kw={"营地","挖掘场","矮人","挖掘","挖掘工具","麦格玛尔·落斧","石腭怪"},sec={{t="遗落的工具",b="麦格玛尔·落斧需要那些挖掘工具，石腭怪攻占营地时，矮人把它们留在了那里。你可以把工具交还给挖掘者，他们的工作因入侵而停滞。"}},faq={{q="Magmar为什么需要挖掘工具？",a="石腭怪攻占营地时，矮人留下了大部分工具。等到入侵局势得到控制，这些工具就能帮助挖掘者重新开工。",al={"为什么需要工具","magmar的工具","挖掘工具"}},{q="麦格玛尔·落斧是谁？",a="麦格玛尔·落斧是一名挖掘者，他请你带回那些被遗弃的工具。",al={"magmar是谁","magmar","要工具的人"}},{q="矮人为什么留下了工具？",a="石腭怪攻占营地时，矮人不得不留下大部分工具。",al={"矮人逃离","为什么遗弃","石腭怪与工具"}},{q="挖掘工作遇到了什么问题？",a="石腭怪攻占了营地，迫使矮人留下大部分工具，停止工作，直到入侵局势得到控制。",al={"挖掘场的问题","营地发生了什么","挖掘工作的问题"}}},fp="16,184,17.181.0,42.157.0,22.75.0,36.83.0,33.137.0"}
P.entries["quest:86614"] = {n="Silver of the Waves",s="“海浪之银”讲述的是拾回一枚被遗弃在废弃渔具中的刻字银发夹的故事。将这件丢失的纪念品物归原主，能让失主在繁重的日常琐事中得到片刻的慰藉，并找回一件本以为已随潮汐永失的珍贵之物。",h="“海浪之银”讲述的是拾回一枚被遗弃在废弃渔具中的刻字银发夹的故事。将这件丢失的纪念品物归原主，能让失主在繁重的日常琐事中得到片刻的慰藉，并找回一件本以为已随潮汐永失的珍贵之物。",kw={"琐事","渔具残骸","发夹","k.d.","字母缩写","银质纪念品","波涛之银"},sec={{t="漂浮物中的纪念品",b="当你在废弃的杂物和渔具残骸中翻找时——在生锈的鱼钩和断裂的线轴之间——细心的旅者可能会发现一件精致得多的物品：一枚刻有“K.D.”缩写的华丽银质发夹。虽然因潮湿和风化而略显黯淡，但腐蚀之下依然难掩其精湛的工艺。"},{t="重焕光彩",b="循迹找到主人后，会发现他们正忙于应付日常琐事。看到传家宝失而复得，他们立刻感到如释重负；虽然这枚银饰本以为已永远沉入水中，但只要稍加擦拭便能恢复往日的光泽，失主也因此对发现者表达了诚挚的谢意。"}},faq={{q="什么是“海浪之银”？",a="“海浪之银”是一项任务，始于探险者在废弃的渔具和漂浮物中进行搜寻。在锈蚀的鱼钩和缠绕的线缆之间，躺着一枚刻有首字母的银质发夹，这引出了一段将私人纪念品物归原主的寻回之旅。",al={"波涛之银","什么是海浪之银","发夹任务"}},{q="在残骸中发现的发夹是谁的？",a="这枚发夹上刻有“K.D.”的首字母缩写。虽然残骸没有提供失主全名的即时线索，但当发夹物归原主时，忙于日常琐事的主人一眼便认出了它，并对找回这件以为已永失的配饰感到无比感激。",al={"kd缩写","发夹是谁的","kd是谁"}},{q="发夹是在哪里丢失的？",a="这枚发夹是在杂乱的废弃物中被发现的，旁边还有普通的渔具，包括断裂的线轴和生锈的鱼钩。它似乎是在水边丢失，或者是被清理渔具垃圾时一并扫入其中的，随后才被发现。",al={"发夹在哪里找到的","发夹位置"}},{q="这枚发夹状况如何？",a="尽管因暴露在水汽和自然环境中而略有锈蚀，但这枚银质发夹依然保持着华丽的造型和完整的结构。失主表示，只需稍费点功夫擦拭一下，这件银饰就能轻松恢复往日的光彩。",al={"银发夹状况","发夹坏了吗"}},{q="这项任务是如何开始的？",a="当你在检查一堆废弃的渔具垃圾和残骸时，任务便开始了。在毁坏的线轴和鱼钩中发现那枚刻有字母的发夹，便给了你寻找失主的目标。",al={"谁提供该任务","如何开始海浪之银"}},{q="为什么归还这枚发夹很有意义？",a="归还一件随潮汐或在岸边丢失的私人纪念品是一种单纯的善举。失主在找回以为已永失的配饰后感到如释重负，并乐意放下手头的忙碌琐事，以此作为发现者应得的谢礼。",al={"发夹奖励","为什么要归还发夹"}}},fp="19,171,25.231.0,19.232.0,28.126.0,39.141.0,29.141.0,35.147.0,26.128.0,43.160.0"}
P.entries["quest:86667"] = {n="Snowbound",s="Snowbound是一个在洛克莫丹进行的本地运送任务，代表正在研究当地元素的Grenhild所执行。她的前导师Norric Lochthane请求一份从南门小径收集的未融化的雪，用于他的萨满修行。运送这份冰冷的试剂揭示了一位年迈的萨满与他昔日学生之间持久的个人纽带与默默的渴望。",h="Snowbound是一个在洛克莫丹进行的本地运送任务，代表正在研究当地元素的Grenhild所执行。她的前导师Norric...",kw={"格伦希尔德","雪罐","洛克莫丹","小型元素","诺里克·洛克塞恩","萨满修行","雪困","南门小径","洛克湖"},ang={["class:Shaman"]="Norric Lochthane对小型元素信使和冰冻试剂的依赖，突显了卡兹莫丹内部所实行的本土萨满传统和元素研究。",["race:Dwarf"]="Norric Lochthane和Grenhild之间的交流，为人们了解洛克莫丹的山峰和湖岸周围的矮人师徒关系和元素学术提供了一个窗口。"},sec={{t="不寻常的请求",b="在对洛克莫丹的当地元素进行实地研究时，Grenhild收到了一位意想不到的信使：由她的前导师Norric Lochthane派来的一只小型元素。Norric传来口信，称他急需新鲜、未融化的雪来协助他的萨满修行。Grenhild没有质疑她这位老老师那些古怪的方法，而是寻找了一位冒险者去取雪，这样她就可以专注于她的元素研究。这项差事需要从南门小径采集积雪，那里常年寒风阵阵，足以保存雪堆，并将其密封在一个特制的陶瓷罐中，以阻隔山谷的热量。"},{t="师与徒",b="Norric Lochthane居住在洛克湖西北岸的一间安静小屋里，远离繁忙的定居点，潜心研究他的萨满艺术。当那罐雪被送到他的门前时，Norric很高兴能收到这份用于他神秘研究的冰冷试剂，但他的反应暗示了这项差事背后的深层动机。他公开感叹Grenhild没有亲自来看望他。这个请求不仅仅是关于魔法试剂，更是一位年迈的导师希望与一位已经走上独立道路的昔日学生重新建立联系的默默期望。"}},faq={{q="诺里克·洛克萨恩是谁？",a="诺里克·洛克萨恩是一位经验丰富的萨满，居住在洛克莫丹洛克湖西北岸的一间小屋里。他是格伦希尔德的前导师，并继续从事私下的萨满修行。他在元素魔法方面造诣深厚，足以在荒野中雇佣小型元素作为信使。",al={"诺里克·洛克萨恩背景故事","诺里克是谁","诺里克洛克莫丹"}},{q="格伦希尔德是谁？",a="格伦希尔德是一位驻扎在洛克莫丹的元素研究员。她在诺里克·洛克萨恩门下学习过魔法，很尊重他的技艺，但她已将自己的精力投入到实地调查当地元素行为的研究中，几乎没有时间旅行。",al={"格伦希尔德是谁","格伦希尔德洛克莫丹","格伦希尔德的导师"}},{q="诺里克为什么需要一罐雪？",a="诺里克请求这份雪是专门为了协助他的萨满修行和神秘学研究。然而，他也希望这个请求能作为邀请，让他的前学生格伦希尔德亲自来拜访他的家。",al={"诺里克为什么需要雪","用于萨满修行的雪","雪罐的用途"}},{q="这个任务的雪是在哪里采集的？",a="雪是在南门小径的隧道入口附近采集的，那里位于丹莫罗和洛克莫丹之间的高山上。由于高海拔带来的严寒，雪常年积存，旅行者可以将其装入隔热的陶瓷罐中。",al={"在哪里寻找雪","南门小径的积雪位置","如何获得雪罐"}},{q="为什么格伦希尔德不能亲自运送这些雪？",a="格伦希尔德正忙于观察和研究洛克莫丹当地的元素。由于她的实地研究需要持续关注，她无法离开岗位去南门小径，也无法去诺里克的湖边住所。",al={"为什么格伦希尔德不能去","格伦希尔德为什么需要帮助","格伦希尔德很忙"}},{q="诺里克是如何向格伦希尔德发送请求的？",a="诺里克没有使用普通的矮人信差或邮政，而是召唤并派遣了一只小型元素将他的口信传达给格伦希尔德。这种不寻常的信使反映了他对元素艺术和萨满实践的熟练运用。",al={"诺里克的信使","元素信使","诺里克如何联系格伦希尔德"}}},fp="9,202,18.448.0,17.379.0,24.260.0,16.202.0,35.152.0,42.224.0,47.181.0,44.157.0"}
P.entries["quest:867"] = {n="鹰身强盗",s="“鹰身人袭击者”是达索克·快刀在十字路口发布的一项早期进攻任务，旨在遏制极具侵略性的巫翼鹰身人族群。冒险者受命前往贫瘠之地西北部猎杀基层的袭击者和飞羽，收集利爪以削弱该族群的补给袭击能力。",h="“鹰身人袭击者”是达索克·快刀在十字路口发布的一项早期进攻任务，旨在遏制极具侵略性的巫翼鹰身人族群。冒险者受命前往贫瘠之地西北部猎杀基层的袭击者和飞羽，收集利爪以削弱该族群的补给袭击能力。",kw={"贫瘠之地","十字路口","达索克","鹰身人","飞羽","快刀","利爪","巫翼"},ang={["class:Rogue"]="达索克·快刀的战略直接吸引了潜行者的共鸣：侦察目标、剖析层级，然后逐一消灭它们的领导层。",["faction:Horde"]="确保贫瘠之地内部通道的安全，对于维持新建立的岗哨获得补给并统一在奥格瑞玛的旗帜下至关重要。"},sec={{t="来自空中的威胁",b="在贫瘠之地尘土飞扬的小路上艰难前行的商队时刻面临着野兽和野猪人的侵扰，但巫翼鹰身人构成的空中威胁尤为致命。这些野蛮生物经常从西北部的岩石峭壁俯冲而下，袭击商队和补给马车，屠杀驮畜并劫掠运往兽人岗哨的关键物资。"},{t="达索克的计划",b="兽人潜行者达索克·快刀并没有针对山区的巢穴发动杂乱无章的突袭，而是花了数天时间侦察该族群的习性和等级制度。他知道，缺乏协调的打击只会让它们四散奔逃。为了彻底击溃巫翼，达索克打算从底层开始系统性地屠戮整个族群，先从前线的袭击者入手，然后再对付它们的指挥官。"}},faq={{q="部落为什么要针对巫翼鹰身人？",a="巫翼族群在贫瘠之地西北部的峭壁上筑巢，并经常俯冲下来袭击行驶在主干道上的部落补给商队。",al={"为什么杀死鹰身人","巫翼问题","为什么要攻击鹰身人"}},{q="谁是达索克·快刀？",a="达索克是驻扎在十字路口的一名兽人侦察兵兼潜行者。他负责监视当地威胁，并已经摸清了当地鹰身人族群的指挥链，以便组织一次有计划的清剿行动。",al={"达索克","达索克·快刀背景故事","达索克是谁"}},{q="达索克为什么要巫翼的利爪？",a="达索克要求以切下的利爪作为击杀的确实证据，将它们作为冷酷的战利品收集起来，以确认该族群最底层的袭击者队伍正在缩减。",al={"为什么要利爪","鹰身人利爪的用途"}},{q="这些鹰身人位于哪里？",a="它们在贫瘠之地最西北端的荆棘丛生的峭壁和峡谷中筑巢，位于通往石爪山的道路以北。",al={"哪里可以找到鹰身人","巫翼位置","鹰身人袭击者位置"}},{q="清除了这些袭击者之后会发生什么？",a="一旦基层的袭击者和飞羽被削减，达索克会将你的注意力引向该族群指挥链的更高层，即它们的副官，并最终指向它们的族群主母。",al={"下一个任务","鹰身人袭击者之后","接下来是什么"}},{q="鹰身人是为其他人效力吗？",a="巫翼鹰身人是野蛮且极具领地意识的食腐生物，直接听命于它们自己的巢穴主母塞瑞娜·血羽，而非任何外部势力。",al={"谁领导鹰身人","鹰身人的效忠对象","巫翼领导者"}}},fp="13,196,17.209.0,13.284.0,49.123.0,26.178.0,38.147.0,32.118.0,41.137.1,40.141.0"}
P.entries["quest:8670"] = {n="符文图腾长者",s="符文图腾长者是春节期间出现在杜隆塔尔的一位先祖之魂。她站在剃刀岭的一道天光之下，为前来缅怀先人的旅人们提供祝福与节日代币。",h="符文图腾长者是春节期间出现在杜隆塔尔的一位先祖之魂。她站在剃刀岭的一道天光之下，为前来缅怀先人的旅人们提供祝福与节日代币。",kw={"杜隆塔尔","暗角长者","高山长者","符文图腾长者","春节","剃刀岭","符文图腾"},ang={["faction:Alliance"]="向符文图腾长者致敬需要潜入杜隆塔尔的心脏地带，深入敌后，且不能惊动剃刀岭兽人守卫的怒火。",["faction:Horde"]="符文图腾长者就站在剃刀岭的城墙内，对于刚踏上旅程的部落新手来说，她是致敬先祖最安全、最方便的长者之一。",["race:Tauren"]="在莫高雷平原之外见到一位拥有尊贵的符文图腾家族姓名的灵魂，有力地提醒着你，你的种族在卡利姆多有着深厚的精神传承。"},sec={{t="剃刀岭的先祖",b="春节期间，古代长者的灵魂会在艾泽拉斯各地显现，与生者交流。符文图腾长者出现在剃刀岭内，位于南侧入口处不远。她沐浴在从天而降的澄澈星光中，守护着这座兽人定居点，欢迎那些驻足旅途、致敬先贤智慧的冒险者。"},{t="指引四方",b="向符文图腾长者致敬的意义不止在于缅怀一位先祖。作为对你敬意的回报，她会奖励你一枚节日代币，并告知你其他灵魂的下落，指引旅人前往寻找分散在大陆各处的暗角长者和高山长者。"}},faq={{q="符文图腾长者在哪里？",a="符文图腾长者位于杜隆塔尔的剃刀岭，从南侧入口进入后，向右侧走一点就能找到。",al={"符文图腾长者位置","符文图腾长者在哪里","寻找符文图腾长者"}},{q="为什么她身上有一道光束？",a="和所有在春节期间显现的先祖之魂一样，符文图腾长者被一道从天空中照下的神圣光束所笼罩，标志着她是一位受人尊敬的长者。",al={"长者光束","为什么符文图腾长者在发光","长者光柱"}},{q="向符文图腾长者致敬能得到什么？",a="向符文图腾长者致敬会奖励一枚纪念你尊崇先祖的节日代币，她还会指引你寻找像暗角长者和高山长者这样的其他游荡的灵魂。",al={"符文图腾长者奖励","符文图腾长者给什么","符文图腾长者上交"}},{q="联盟玩家可以拜访符文图腾长者吗？",a="春节的长者们欢迎所有凡人的致敬，不分阵营，但剃刀岭是守卫森严的部落前哨站，联盟旅人靠近她非常危险。",al={"联盟符文图腾长者","联盟可以和符文图腾长者对话吗"}},{q="符文图腾长者提到了哪些长者？",a="符文图腾长者会分享其他先祖的下落，特别是指引如何找到暗角长者和高山长者。",al={"符文图腾长者指引","符文图腾长者让你找谁"}},{q="符文图腾长者是活着的牛头人还是鬼魂？",a="符文图腾长者是一位先祖之魂，她在春节期间显现，为那些生命之火依然炽热的人们赐予祝福。",al={"符文图腾长者死了吗","符文图腾长者是鬼魂吗"}}},fp="19,215,22.289.0,25.220.0,33.116.0,44.140.0,49.142.0,43.172.0,36.75.0,46.121.0"}
P.entries["quest:8673"] = {n="血蹄长者",s="血蹄长者是春节期间显现的受人尊崇的先祖之魂之一。这位受人尊敬的灵魂位于莫高雷的血蹄村外，他会认可游历者的敬意，并回赠一枚先祖硬币。",h="血蹄长者是春节期间显现的受人尊崇的先祖之魂之一。这位受人尊敬的灵魂位于莫高雷的血蹄村外，他会认可游历者的敬意，并回赠一枚先祖硬币。",kw={"先祖","血蹄村","先祖硬币","血蹄长者","春节","莫高雷"},ang={["class:Druid"]="德鲁伊非常推崇春节的先祖之魂，他们通过与长者们交流来加强自己与大地和星辰之间的自然羁绊。",["class:Shaman"]="对于萨满祭司来说，与血蹄长者这类显现的先祖交谈，直接加强了凡世与先祖之魂之间的生动沟通。",["faction:Alliance"]="想要到达血蹄长者身边，必须潜入莫高雷的核心地带，这使得此次穿越敌对部落平原的旅程十分大胆。",["race:Tauren"]="在家园的土地上问候血蹄长者是一项神圣的职责，旨在纪念那个引导牛头人来到莫高雷这片和平避风港的部族传承。"},sec={{t="拜访先祖",b="在春节庆祝期间，往昔伟大的英雄和长者们的灵魂会回到艾泽拉斯。血蹄长者笼罩在天界的光辉中，出现在血蹄村北部的桥边。接近这些受人尊崇的先祖是一种向往昔牺牲致敬的行为，作为回报，血蹄长者会给予鼓励的话语和一枚神圣的先祖硬币。"},{t="血蹄传承",b="血蹄长者伫立在莫高雷的先祖之地上，充当着在世的牛头人部族与先辈记忆之间的桥梁。对于牛头人来说，缅怀逝者是精神生活的支柱，加强了大地母亲、先祖以及此时行走在平原上的人们之间的和谐。"}},faq={{q="在哪里可以找到血蹄长者？",a="血蹄长者站在莫高雷血蹄村外的一座桥旁，身上笼罩着一道天界光束。",al={"血蹄长者位置","血蹄长者在哪里","血蹄长者地点"}},{q="寻找血蹄长者有什么目的？",a="旅人们在春节期间寻找血蹄长者，是为了向先祖表达敬意。为了认可这种尊崇，这位灵魂会奖励造访者一枚先祖硬币，并传授有关附近其他灵魂（例如傲角长者）的智慧。",al={"为什么要与血蹄长者交谈","血蹄长者的目的","血蹄长者给予什么"}},{q="为什么有一道光束照在他身上？",a="这道光束标志着该灵魂作为春节期间显现的先祖灵体，象征着与天空及往昔之灵的神圣连接。",al={"为什么血蹄长者会发光","血蹄长者身上的光"}},{q="联盟角色可以向血蹄长者致敬吗？",a="无论阵营为何，春节的先祖们都会尊敬所有心怀敬意的凡人。然而，联盟的旅人们必须小心行事，因为血蹄长者位于部落领地的门口。",al={"联盟可以完成此任务吗","血蹄长者是部落专属吗"}},{q="这位长者提到的傲角长者是谁？",a="傲角长者是另一位在雷霆崖庆祝节日的先祖之魂。血蹄长者可以提供关于如何找到他的指引。",al={"麦蹄长者","谁是麦蹄长者"}},{q="先祖硬币代表什么？",a="先祖硬币代表了艾泽拉斯受人尊崇的灵魂所赐予的恩惠信物。它们证明了一位旅人对往昔怀有敬意，节日的庆祝者可以用它们换取节日服饰、图纸和庆祝物品。",al={"什么是先祖硬币","春节代币"}}},fp="19,159,26.277.0,20.250.0,33.117.0,51.191.0,49.170.0,54.191.0,48.134.0,40.209.0"}
P.entries["quest:8675"] = {n="逐星长者",s="逐星长者是一位先祖之魂，会在春节期间显现于西部荒野的哨兵塔之巅。向她致敬可以让尘土飞扬的平原上的旅行者向往昔的智慧致意。作为回报，这位长者会认可生者燃烧的活力，并给予她的祝福。",h="逐星长者是一位先祖之魂，会在春节期间显现于西部荒野的哨兵塔之巅。向她致敬可以让尘土飞扬的平原上的旅行者向往昔的智慧致意。作为回报，这位长者会认可生者燃烧的活力，并给予她的祝福。",kw={"先祖硬币","逐星长者","春节","哨兵岭","哨兵塔","西部荒野"},ang={["class:Druid"]="德鲁伊视春节为神圣节日，将像逐星长者这样的先祖显现视为与远古传统和深厚自然崇敬之间的持久联系。",["faction:Alliance"]="逐星长者位于哨兵岭内人民军基地的中心，这让她成为在西部荒野做任务时很容易祭奠的一位长者。",["faction:Horde"]="到达逐星长者处需要潜行、速度或蛮力，因为哨兵岭到处都是敌对的联盟卫兵和民兵侦察兵。"},sec={{t="沙尘中的灯塔",b="在西部荒野那动荡的灌木丛中，哨兵岭是抵御迪菲亚潜行者劫掠者和四处游荡的拾荒者的唯一堡垒。春节期间，一位名为逐星长者的先祖之魂会出现在哨兵塔顶端的开放平台上。在高处俯瞰着沙尘与风，她耐心地守护着下方疲惫的士兵和饱受困扰的定居者，欢迎任何攀登上来表达敬意的人。"},{t="祭奠先祖",b="春节是艾泽拉斯观察的一个神圣节日，旨在庆祝智慧、传承，以及在当前困境之前行遍大地的远古之魂的事迹。当靠近时，逐星长者会认出旅者体内那旺盛的生命火花，接受他们的敬意，并赐予她的信物作为生者与受尊崇的逝者之间血缘羁绊的礼物。"}},faq={{q="我在哪里可以找到逐星长者？",a="逐星长者位于西部荒野哨兵岭的哨兵塔的最顶端。沿着塔内的螺旋楼梯爬上去，到达顶部的瞭望台即可找到她。",al={"逐星长者位置","逐星长者在哪里","逐星长者西部荒野"}},{q="为什么逐星长者会站在哨兵塔的顶端？",a="先祖之魂会在春节期间选择艾泽拉斯各处显眼且具有象征意义的地点。哨兵塔的高处可以俯瞰整个西部荒野盆地，让这位长者能见证那些勇敢面对边境的旅行者。",al={"为什么她会在哨兵塔","逐星长者之塔"}},{q="这个任务的目的是什么？",a="寻找逐星长者是春节期间祭奠先祖长者的一部分。表示敬意可以获得一枚先祖硬币和一份庆祝冒险者生命之灵的祝福。",al={"逐星长者任务奖励","为什么要向逐星长者致敬"}},{q="部落玩家可以向逐星长者表示敬意吗？",a="逐星长者本人是一位欢迎所有朝圣者的和平之灵。然而，哨兵岭是一个防御森严的联盟前哨站，这使得部落冒险者想要接触她变得非常危险。",al={"部落可以拜访逐星长者吗","逐星长者对部落敌对吗"}},{q="逐星长者会参与哨兵岭的防御吗？",a="不会。春节期间造访的长者们只是专注于传统和远古记忆的灵魂显现。逐星长者不会参与人民军与迪菲亚潜行者之间的冲突。",al={"逐星长者会和迪菲亚潜行者战斗吗","逐星长者属于人民军吗"}},{q="当你向逐星长者问候时，她会说什么？",a="在向她问候时，逐星长者会提到你的灵魂充满了旺盛的生命力，优雅地接受你带来的敬意，并回赠一枚先祖信物。",al={"逐星长者对话","长者说了什么"}}},fp="19,189,20.334.0,22.268.0,33.126.0,57.197.0,34.169.0,40.144.0,65.195.0,43.133.0"}
P.entries["quest:86757"] = {n="Slowing the Orc Advance",s="Shandrina请你帮忙，将兽人赶出灰谷东部。兽人斥候和步兵出没，使她的族人无法安全穿行林间。",h="Shandrina请你帮忙，将兽人赶出灰谷东部。兽人斥候和步兵出没，使她的族人无法安全穿行林间。",kw={"灰谷","弯刀","步兵","锯齿剑","兽人","斥候","shandrina","武器"},sec={{t="林中兽人",b="兽人在灰谷东部森林四处蔓延，Shandrina希望你能伸出援手。如今，兽人斥候和步兵潜伏在林中各处，使她的族人难以安全通行。她请你把兽人使用的锯齿剑和弯刀带给她，以便回收利用并改作他用。"}},faq={{q="Shandrina需要什么？",a="Shandrina请你把兽人使用的锯齿剑和弯刀带给她。",al={"她想要什么","shandrina需要什么","给shandrina的物品"}},{q="为什么灰谷不安全？",a="兽人已经占据东部森林，他们的斥候和步兵潜伏在林中各处。",al={"为何不安全","灰谷的兽人","灰谷发生了什么"}},{q="Shandrina打算如何处置这些武器？",a="Shandrina打算回收利用兽人武器，并改作他用。",al={"武器用途","剑有什么用","重新利用兽人武器"}},{q="林中的兽人是谁？",a="兽人已经占据东部森林，他们的斥候和步兵如今潜伏在林中各处。",al={"兽人斥候","兽人步兵","谁占据了东部"}}},fp="23,142,17.288.0,25.85.0,24.92.0,40.57.0,30.84.0"}
P.entries["quest:86758"] = {n="Twisting the Knife",s="Marek请你猎杀Daggerfang，那条夺走他匕首的鳄鱼。这头野兽在湖边游荡，可能会危及其他猎人。",h="Marek请你猎杀Daggerfang，那条夺走他匕首的鳄鱼。这头野兽在湖边游荡，可能会危及其他猎人。",kw={"鳄鱼","daggerfang","狩猎","猎人","匕首","湖泊","marek"},sec={{t="Marek的匕首",b="Marek告诉你，一条鳄鱼险些咬掉他的手，逼得他狼狈地逃离了湖边。他觉得自己的匕首还在附近某处。他把那头野兽叫作Daggerfang，请你沿着湖边找到它，那里的其他猎人可能正面临危险。"}},faq={{q="Daggerfang是谁？",a="Daggerfang是一条鳄鱼，Marek说它在湖边捕猎。",al={"daggerfang","daggerfang 鳄鱼","大鳄鱼"}},{q="Marek的匕首怎么了？",a="Marek觉得，自己用匕首抵抗鳄鱼后，把它落在了湖边。",al={"marek的匕首","遗失的匕首","匕首在哪"}},{q="Marek为什么想要猎杀Daggerfang？",a="Marek认为Daggerfang可能会威胁到湖边的其他猎人。",al={"为什么杀daggerfang","鳄鱼的危险","猎杀鳄鱼"}},{q="Daggerfang在哪里？",a="Marek说Daggerfang在湖边捕猎。",al={"daggerfang的位置","湖边的鳄鱼","鳄鱼在哪"}},{q="Marek要我带回什么？",a="Marek请你找到并击败Daggerfang，带回他的匕首。",al={"带回什么","匕首与鳄鱼","marek的请求"}},{q="Marek是怎么说那条鳄鱼的？",a="Marek说那条鳄鱼险些咬掉他的手，他用匕首抵抗才得以逃脱。",al={"marek的鳄鱼故事","险些失去手","鳄鱼嘴里的匕首"}}},fp="18,147,15.256.0,18.70.0,33.80.0,38.71.0,20.55.0,37.70.0,40.90.0"}
P.entries["quest:8677"] = {n="暗角长者",s="“暗角长者”是一个节日任务，玩家需要在春节期间前往奥格瑞玛寻找暗角长者来完成。旅人们向这位受人尊敬的先祖致敬，并因此获得一份智慧与庆典的信物。她伫立在部落主城的核心地带，象征着岁月的沉淀、生存的意志以及先祖的荣耀。",h="“暗角长者”是一个节日任务，玩家需要在春节期间前往奥格瑞玛寻找暗角长者来完成。旅人们向这位受人尊敬的先祖致敬，并因此获得一份智慧与庆典的信物。她伫立在部落主城的核心地带，象征着岁月的沉淀、生存的意志以及先祖的荣耀。",kw={"先祖","先祖硬币","暗角长者","长者","春节","奥格瑞玛","智慧谷"},ang={["class:Shaman"]="萨满祭司尊崇生者世界与远古灵魂之间的交流，因此拜访像暗角长者这样的先祖长者是一项深具灵性的职责。",["faction:Alliance"]="接触到暗角长者需要穿越奥格瑞玛戒备森严的城门和街道，这使得对先祖的缅怀也变成了一场关于潜行或武力的危险考验。",["faction:Horde"]="对于部落勇士来说，拜访暗角长者是在自家主城的安全与繁华之中，缅怀先祖传统的绝佳良机。"},sec={{t="缅怀先祖",b="在春节期间，受人尊敬的先祖之魂会显现于艾泽拉斯各地，将他们的智慧分享给活着的后辈。暗角长者驻足于奥格瑞玛的城墙内，注视着这座年轻战士之城的繁华喧嚣。无论是部落的勇士，还是勇敢潜入城门的联盟冒险者，只要接近她，就有机会向那些在数代之前就已行走于大地之上的先祖们致以正式的敬意。"},{t="节日之魂",b="当收到路过旅人的问候与敬意时，暗角长者会认可他们心中那充满活力的生命之火。作为对尊崇古老习俗的回报，她会赐予一枚先祖硬币和她的个人祝福。这些信物象征着对远古磨难的胜利，也提醒着生者要珍惜那代代相传、从未断绝的血脉力量。"}},faq={{q="暗角长者是谁？",a="暗角长者是一位在春节期间现身于奥格瑞玛的先祖之魂。她是来自过去的使者，为那些抽出时间向长者致敬的旅人们提供祝福与信物。",al={"暗角长者","暗角长者是谁","暗角长者背景故事"}},{q="我可以在哪里找到暗角长者？",a="她位于奥格瑞玛城内，就在索尔的堡垒外侧的智慧谷，在节日期间注视着部落主城的日常生活。",al={"暗角长者位置","暗角长者在哪里","奥格瑞玛暗角长者"}},{q="春节长者的目的是什么？",a="长者们在春节期间现身，是为了让生者有机会缅怀先祖的智慧、勇气与牺牲。向长者致敬可获得一枚先祖硬币，这是传承与集体记忆的象征。",al={"为什么要寻找长者","春节长者","先祖硬币"}},{q="联盟玩家可以向暗角长者致敬吗？",a="可以，先祖长者欢迎所有活着的凡人致以敬意，不论阵营。然而，由于暗角长者身处部落重镇奥格瑞玛的深处，联盟访客必须勇敢面对敌对卫兵和玩家的阻挠才能到达她身边。",al={"联盟可以和暗角长者对话吗","联盟暗角长者","联盟奥格瑞玛长者"}},{q="暗角长者会给予什么奖励？",a="向暗角长者致敬会奖励一枚先祖硬币，以及她的祝福。",al={"暗角长者奖励","暗角长者给什么","暗角长者先祖硬币"}},{q="这个任务可以重复完成吗？",a="不可以，在每年的春节庆典期间，每位角色只能向每位先祖长者致敬一次。",al={"我可以再次完成暗角长者任务吗","暗角长者任务可以重复吗","暗角长者日常任务"}}},fp="18,155,21.328.0,26.311.0,22.184.0,32.163.0,49.200.0,42.174.0,38.82.0,25.96.0"}
P.entries["quest:86776"] = {n="Ingredients for the Forge",s="“Ingredients for the Forge”是塞尔萨玛的一项当地任务，矮人工匠莫汉·铜舌请求人们提供青铜锭，以补充他日益枯竭的作坊库存。由于无法像铁炉堡那样便捷地进行贸易，这个乡村定居点不得不依赖过往的旅人，为当地锻炉提供生产工具和日常用品所需的关键金属。",h="“Ingredients for the...",kw={"铁匠","青铜锭","锻炉","熔炉材料","洛克莫丹","莫汉·铜舌","塞尔萨玛"},ang={["profession:Blacksmithing"]="莫汉·铜舌依赖铁匠和金属工人来维持塞尔萨玛的日常五金供应，从水壶和烹饪锅到野外工具，应有尽有。",["profession:Mining"]="能够将铜和锡熔炼成青铜锭的矿工，为维持洛克莫丹乡村作坊的运营提供了所需的原材料。",["race:Dwarf"]="即便是像塞尔萨玛这样的小型矮人定居点，也深深依赖着一个活跃的锻炉，这使得金属供应短缺成为社区长期关注的问题。"},sec={{t="塞尔萨玛的补给短缺",b="塞尔萨玛的生活节奏比铁炉堡的大锻炉要缓慢得多，但远离首都也带来了物流方面的挑战。当地铁匠莫汉·铜舌努力为镇上提供必需的五金件、锅具和工具，但他常常面临青铜等原材料短缺的问题。没有了来自主城的定期补给，当地工匠只能依赖过往的旅行者和探矿者来维持铁砧的运作。"},{t="保持炉火不熄",b="获得熔炼好的青铜解决了莫汉燃眉之急的制造难题，使他能够补充镇上的日用品和实用物资。即便如此，这家乡村锻炉仍面临着持续的供应障碍，尤其是缺乏能够定期将煤炭等燃料运送至洛克莫丹的可靠商路。"}},faq={{q="谁发布“熔炉的材料”？",a="该任务由莫汉·铜舌发布，他是一位在洛克莫丹的塞尔萨玛镇从事锻造工作的矮人工匠。",al={"谁发布了锻造材料","莫汉·铜舌任务","塞尔萨玛铁匠任务"}},{q="莫汉·铜舌需要什么材料？",a="莫汉·铜舌需要青铜锭来维持他的作坊运转，这样他才能为当地居民制作锅、水壶和工具等必需的日常用品。",al={"莫汉需要什么","锻造材料所需材料","塞尔萨玛锻炉需要什么锭"}},{q="为什么塞尔萨玛会缺乏金属？",a="虽然塞尔萨玛是一个舒适的定居点，但它缺乏铁炉堡那般庞大的工业设施和稳定的贸易流，这使得当地工匠容易陷入原材料短缺的困境。",al={"为什么塞尔萨玛缺乏青铜","为什么塞尔萨玛没有金属"}},{q="莫汉用青铜锻造什么？",a="莫汉主要使用青铜来制作实用的家用和劳作用具，包括炊具、水壶、锅以及各种供镇民使用的工具。",al={"青铜在塞尔萨玛有什么用途","莫汉制作什么"}},{q="锻炉还面临什么物资短缺的问题？",a="除了金属锭，莫汉还提到需要有固定的商人将煤炭运进镇里，因为燃料对于保持锻炉炉火持续燃烧至关重要。",al={"莫汉需要什么燃料","塞尔萨玛的煤炭问题"}},{q="这个任务在哪里完成？",a="该任务在塞尔萨玛完成，这是位于洛克莫丹群山之中的主要矮人定居点，就在丹莫罗以东。",al={"锻造材料在哪里进行","锻造材料位置"}}},fp="25,198,27.374.0,25.163.0,37.93.0,45.132.0,38.106.0,39.131.0,51.112.0,30.99.0"}
P.entries["quest:8678"] = {n="傲角长者",s="傲角长者是一位先祖之魂，在春节期间受人敬仰，现身于雷霆崖的高处。拜访他是一种深切的崇敬之举，以承认那些守护着莫高雷和部落的先祖们的智慧。",h="傲角长者是一位先祖之魂，在春节期间受人敬仰，现身于雷霆崖的高处。拜访他是一种深切的崇敬之举，以承认那些守护着莫高雷和部落的先祖们的智慧。",kw={"先祖","先祖硬币","长者","春节","莫高雷","灵魂","雷霆崖","傲角"},ang={["class:Shaman"]="对于萨满祭司而言，与一位先祖长者交流是一种与永恒的精神世界进行沟通的深刻仪式。",["faction:Horde"]="这位长者位于牛头人力量的心脏地带，欢迎所有登上雷霆崖致敬的部落盟友。",["race:Tauren"]="向傲角长者致敬对牛头人勇士来说是一次神圣的归家之旅，重申了他们与守护莫高雷的灵魂之间永恒的羁绊。"},sec={{t="莫高雷之魂",b="傲角长者栖身于雷霆崖风吹不断的台地上，在春节期间以先祖的姿态显现。牛头人文化极其推崇先祖的声音，他们相信古代领袖和智者的灵魂会徘徊在世间，为生者提供指引和力量。"},{t="致敬与先祖祝福",b="攀登高处向傲角长者致敬的旅行者，所受到的礼遇并非陌生人，而是作为生命中至关重要的火焰。作为对旅行者致敬的回报，长者会赠予一枚先祖硬币，象征着永恒的过去与为世界未来而战的生者勇士之间的沟通。"}},faq={{q="谁是傲角长者？",a="他是一位受人敬仰的牛头人先祖之魂，在春节期间显现于雷霆崖之巅，以接受来自艾泽拉斯各地勇士的致敬。",al={"麦蹄","麦蹄长者","麦蹄是谁"}},{q="我可以在哪里找到傲角长者？",a="傲角长者居住在牛头人的主城雷霆崖，位于俯瞰莫高雷平原的广阔中央台地上。",al={"麦蹄长者在哪里","麦蹄位置","雷霆崖长者"}},{q="拜访他的目的是什么？",a="拜访傲角长者可以让玩家在春节期间缅怀过去的灵魂，并以此获得他的祝福和一枚先祖硬币作为回礼。",al={"为什么要拜访麦蹄","麦蹄任务","春节长者"}},{q="联盟玩家可以拜访傲角长者吗？",a="虽然灵魂会对任何恭敬的旅行者给予祝福，但作为联盟冒险者进入雷霆崖由于警惕的城市守卫和部落防御者而极其危险。",al={"联盟可以和麦蹄对话吗","联盟雷霆崖长者"}},{q="什么是先祖硬币？",a="这是春节期间由远古灵魂授予的仪式性信物，象征着生者与先祖之间的敬意与沟通。",al={"先祖硬币","春节硬币"}},{q="牛头人如何看待他们的长者？",a="牛头人将他们的先祖视为守护者和导师，他们的精神存在与土地交织在一起，为那些与大地母亲和谐相处的人们提供持续的指引。",al={"牛头人先祖崇拜","牛头人长者传说"}}},fp="19,202,19.253.0,29.258.0,27.123.0,37.118.0,36.145.0,43.142.0,27.170.0,36.141.0"}
P.entries["quest:86784"] = {n="Sticks and Bones",s="“Sticks and Bones”是提瑞斯法林地的一项当地任务，由亡灵卫兵巴塞洛缪提供。他派遣旅行者去搜集荒芜林地里的干燥树枝，并将其送到西边山丘扎营的资深生存专家Eleanor Shackleton手中。",h="“Sticks and Bones”是提瑞斯法林地的一项当地任务，由亡灵卫兵巴塞洛缪提供。他派遣旅行者去搜集荒芜林地里的干燥树枝，并将其送到西边山丘扎营的资深生存专家Eleanor Shackleton手中。",kw={"收集篮","亡灵卫兵巴塞洛缪","干燥树枝","埃莉诺·沙克尔顿","木柴","木棍与骨头","生存","提瑞斯法林地"},ang={["faction:Horde"]="像Eleanor这样的野外露营者为那些在提瑞斯法林地中闯荡的部落新手冒险者提供了友好的休憩点。",["race:Undead"]="即使在洛丹伦那片荒芜的森林里，像Eleanor Shackleton这样的被遗忘者旅行者也必须将旧有的生存习惯调整以适应他们新的不死生涯。"},sec={{t="友好的举动",b="虽然提瑞斯法林地的亡灵卫兵通常被军事巡逻任务所束缚，忙于防范天灾军团或血色十字军，但亡灵卫兵巴塞洛缪还是抽空关照了一位熟人。他知道Eleanor Shackleton在严酷的自然环境中度过她的不死生涯，因此鼓励路过的冒险者为她的营火收集干燥的树枝。"},{t="野外生活",b="Eleanor Shackleton以独自在提瑞斯法被腐蚀的荒野中生存为荣。尽管是被遗忘者，他们仍然能感受到从北部沼泽袭来的潮湿苦寒。Eleanor对于收集木柴的准则很简单：当你觉得已经收集了足够的木柴时，再多收集五倍。因为感激这些额外的木材，她让送信人保留了巴塞洛缪的篮子，并与他们分享营火的温暖。"}},faq={{q="谁发布了“木棍与骨头”任务？",a="提瑞斯法林地的亡灵卫兵巴塞洛缪将这项任务交给路过的冒险者，请他们帮助他的同伴埃莉诺·沙克尔顿。",al={"谁发布木棍与骨头","木棍与骨头任务发布者"}},{q="埃莉诺·沙克尔顿在哪里扎营？",a="埃莉诺·沙克尔顿在提瑞斯法林地西部的山丘上维持着一个小营地，远离定居点，在恶劣环境中求生。",al={"埃莉诺·沙克尔顿位置","埃莉诺在哪里","在哪里交付木棍与骨头"}},{q="被遗忘者虽然是不死族，为什么还需要木柴？",a="虽然被遗忘者不会像活人那样冻死，但他们依然能感受到提瑞斯法荒野中挥之不去的潮湿和苦寒。营火可以提供舒适感，温暖他们僵硬的关节，并维持一个适合在野外生存的营地。",al={"不死族会感到寒冷吗","为什么不死族需要木柴","被遗忘者 寒冷"}},{q="关于收集木材，埃莉诺有什么建议？",a="据亡灵卫兵巴塞洛缪所说，埃莉诺的生存金科玉律是：“当你认为已经收集了足够的木柴时，再多收集五倍。”",al={"埃莉诺的木柴准则","埃莉诺的建议"}},{q="你使用什么物品来收集树枝？",a="亡灵卫兵巴塞洛缪提供了一个收集篮，用来装载在林地各处找到的六根干燥树枝，在完成交付后，埃莉诺会让你保留这个篮子。",al={"干燥树枝篮子","如何收集树枝"}},{q="这个任务会有后续的生存训练吗？",a="埃莉诺欢迎你来到她的营地，并分享关于以冒险者身份在野外旅行的建议，为你提供了一个在提瑞斯法荒野中友好的联络点。",al={"木棍与骨头后续","埃莉诺接下来会做什么"}}},fp="16,193,18.306.0,17.364.0,38.106.0,35.125.0,53.197.0,51.72.0,45.146.0,50.145.0"}
P.entries["quest:868"] = {n="蝎卵",s="“虫卵猎手”是一项由十字路口的学者科兰指派给部落的任务。由于南贫瘠之地出现了具有智慧的昆虫类生物，科兰感到非常不安，他招募冒险者从巨人旷野的土堆中挖掘完整的异种蝎虫卵，以便送往奥格瑞玛进行研究。",h="“虫卵猎手”是一项由十字路口的学者科兰指派给部落的任务。由于南贫瘠之地出现了具有智慧的昆虫类生物，科兰感到非常不安，他招募冒险者从巨人旷野的土堆中挖掘完整的异种蝎虫卵，以便送往奥格瑞玛进行研究。",kw={"贫瘠之地","十字路口","掘地铲","虫卵猎手","巨人旷野","科兰","异种蝎"},ang={["faction:Horde"]="部落依靠像科兰这样的斥候来监视卡利姆多荒凉的土地，确保在奇异的生态威胁危及杜隆塔尔和莫高雷之前对其进行分析。",["race:Troll"]="熟悉原始生物的巨魔们认识到，异种蝎绝非仅仅是虫子而已，他们和科兰一样，对那些拥有非自然、工于心计的头脑的野兽保持警惕。"},sec={{t="十字路口的观察者",b="巨魔科兰驻守在中央稀树草原尘土飞扬的十字路口，担任向奥格瑞玛的领袖汇报情况的观察员。当部落军队忙于部落冲突和联盟入侵时，科兰则关注着生态系统中的异常扰动。其中最主要的是那些正在向贫瘠之地南部挖掘的、具有异星蜂群意识的昆虫类生物。"},{t="挖掘虫群",b="为了弄清这些昆虫生物的来源以及驱使它们的动力，科兰需要在它们成熟之前获取生物样本。冒险者装备上掘地铲，前往巨人旷野直接从异种蝎土堆中采集虫卵。惊动这些孵化巢会引来周围虫群的疯狂反击，这暗示了统一虫群的非自然智慧和共同意志。"}},faq={{q="谁发布了“虫卵猎手”任务？",a="科兰在贫瘠之地的十字路口发布此任务。他是一名巨魔观察员，代表奥格瑞玛的赞助人研究该地区的植物、动物和新出现的异常现象。",al={"任务发布者","科兰位置","谁开启虫卵猎手"}},{q="在哪里可以找到异种蝎虫卵？",a="虫卵位于贫瘠之地南部巨人旷野内的异种蝎土堆中。土堆聚集在挖掘进地表的虫巢隧道周围。",al={"虫卵位置","哪里寻找虫卵","巨人旷野虫卵"}},{q="收集虫卵需要什么工具？",a="科兰提供了一把坚固的掘地铲，用来小心地挖出完整的虫卵，以免压碎它们脆弱的外壳。工具必须与十二枚完好的虫卵一同归还。",al={"挖掘工具","掘地铲","如何获取虫卵"}},{q="这些昆虫与普通的野兽有什么不同？",a="与普通的害虫或当地野生动物不同，这些生物表现出一种令人毛骨悚然的协调性和高度的狡猾。科兰指出，它们展现出的智慧远超普通动物，暗示着它们有着统一的蜂群目标。",al={"异种蝎的特殊之处","昆虫智慧","异种蝎本质"}},{q="为什么奥格瑞玛需要异种蝎虫卵？",a="奥格瑞玛的领袖们希望尽早获得在部落边界扎根的未知威胁的情报。在虫害蔓延之前，研究虫卵有助于研究人员了解这些生物的生长周期、优势和潜在生物学特征。",al={"奥格瑞玛异种蝎研究","为何研究虫卵","科兰的目的"}},{q="打扰到虫卵堆会发生什么？",a="触碰孵化巢会激怒周围的虫群。附近的异种蝎会立即做出反应来保护后代，伏击任何掠夺巢穴的人。",al={"土堆伏击","异种蝎防卫者"}}},fp="8,193,22.260.0,20.272.0,29.153.0,34.131.0,40.120.0,55.150.0,38.179.0,43.92.0"}
P.entries["quest:8680"] = {n="风之图腾长者",s="风之图腾长者是一位受人尊敬的先祖之灵，在春节期间，她会出现在棘齿城地精港口上方的一处峭壁上。她沐浴在神圣的星光之中，迎接那些寻求尊崇往昔岁月智慧的旅人。向她表达敬意，可以获得先祖的祝福，并指引你前往卡利姆多各地寻找其他长者。",h="风之图腾长者是一位受人尊敬的先祖之灵，在春节期间，她会出现在棘齿城地精港口上方的一处峭壁上。她沐浴在神圣的星光之中，迎接那些寻求尊崇往昔岁月智慧的旅人。向她表达敬意，可以获得先祖的祝福，并指引你前往卡利姆多各地寻找其他长...",kw={"先祖","先祖硬币","风之图腾长者","春节","棘齿城","贫瘠之地"},ang={["class:Druid"]="春节及其先祖幻象旨在庆祝与塞纳里奥议会所守护的自然和星辰循环之间的深度共鸣。",["class:Shaman"]="与停留在元素交汇点附近的先祖之灵交谈，加强了萨满祭司尊崇先人、呵护大地精神健康的职责。",["race:Tauren"]="风之图腾氏族代表了古老的牛头人传承；在这座地精港口上方祭奠这位先祖，将现代部落成员与平原的先祖记忆紧密连接在了一起。"},sec={{t="海湾之上的守望",b="风之图腾长者伫立在棘齿城飞行管理员西北方的一座草坡上，俯瞰着繁忙的地精码头和广阔的大海。尽管她下方的港口充斥着铁器、火药和金币的交易，但这位长者却静静地伫立着，仿佛陷入沉思，只有贫瘠之地静谧的微风和从天而降的星光萦绕在侧。"},{t="贫瘠之地的智慧",b="如同春节期间现身的其它先祖之灵一样，风之图腾长者是指引游历凡人的向导。那些寻找到她的人，不仅能获得她的祝福和一份象征敬意的信物，还能听到她低声诉说着关于大陆各处其它长者的下落，包括符文图腾长者和血蹄长者。"}},faq={{q="风之图腾长者在哪里？",a="风之图腾长者位于棘齿城飞行管理员西北方向的一座小山上，俯瞰着贫瘠之地的港口。",al={"风之图腾位置","风之图腾在哪里","棘齿城风之图腾长者地图"}},{q="寻找风之图腾长者有什么意义？",a="春节期间，旅行者们会寻找风之图腾长者，以向这位受人尊敬的先祖表达敬意。作为对你敬意的回报，她会赠予一枚先祖硬币，并告诉你如何在这片土地上找到其他先祖之灵。",al={"为什么要和风之图腾对话","风之图腾长者用途","风之图腾有什么用"}},{q="为什么她身上有一道光柱？",a="春节期间现身的每一位先祖都沐浴在一道独特的星月光柱中，这标志着他们虚灵的存在，以及连接先祖国度与凡世之间的精神纽带。",al={"长者光柱","为什么风之图腾在发光","照在长者身上的光"}},{q="联盟和部落的玩家都能与风之图腾长者对话吗？",a="是的。棘齿城是由热砂港管理的公共港口，春节的长者们公正地欢迎来自联盟和部落的成员。",al={"联盟能和风之图腾对话吗","风之图腾是中立的吗","部落和联盟的长者"}},{q="风之图腾长者还会提起哪些长者？",a="风之图腾长者会分享有关几位邻近先祖的传闻和指引，包括血蹄长者、符文图腾长者、晨露长者、暗角长者、高山长者、月光长者和傲角长者。",al={"风之图腾提到的长者","风之图腾指向谁"}},{q="完成向长者的致敬会发生什么？",a="当你走近并向她表示敬意时，她会称赞你的精神充满了生命的活力，接受你的敬意，并奖励你一枚先祖硬币。",al={"风之图腾长者任务交还","风之图腾长者说了什么"}}},fp="19,213,20.259.0,25.285.0,33.115.0,51.169.0,49.180.0,61.142.0,55.193.0,51.163.0"}
P.entries["quest:8682"] = {n="星灵长者",s="星灵长者是一位受人尊敬的先祖之魂，在春节期间居住在乱风岗。旅人们会前往千针石林的高处寻找他的身影，向先祖表达敬意并接受他古老的祝福。",h="星灵长者是一位受人尊敬的先祖之魂，在春节期间居住在乱风岗。旅人们会前往千针石林的高处寻找他的身影，向先祖表达敬意并接受他古老的祝福。",kw={"先祖","先祖硬币","星灵长者","乱风岗","春节","千针石林"},ang={["class:Druid"]="在月光下与古老的灵魂沟通，与塞纳留斯的教诲以及纪念先人走过的土地的精神十分契合。",["faction:Alliance"]="星灵长者驻留在部落要塞乱风岗内，要求联盟朝圣者穿过危险的高地和敌对卫兵来表达敬意。",["race:Tauren"]="在你们族人最具代表性的台地高处问候一位受人尊敬的长者，体现了舒哈鲁对先祖血脉的深切崇敬。"},sec={{t="石林中的灯塔",b="星灵长者栖息在乱风岗高耸的木制悬崖上，沐浴在如柱的璀璨星光之中。他位于通往大型机械升降梯的桥梁附近，他那幽灵般的身影为千针石林风吹日晒的平顶山提供了一处宁静的避难所。"},{t="先祖之路",b="星灵长者会接待那些在春节庆典期间前来缅怀往昔的冒险者。除了接受他们的致敬外，这位德高望重的长者还能引导旅人前往散布在卡利姆多的族人处，包括晨露长者和符文图腾长者。"}},faq={{q="星灵长者在哪里？",a="星灵长者位于千针石林乱风岗的上层台地，就在靠近悬崖升降梯的吊桥附近。",al={"星灵长者位置","星灵长者在哪里","乱风岗长者"}},{q="为什么要寻找星灵长者？",a="在春节期间，旅人会拜访像星灵长者这样的先祖之魂来表达敬意，获得一枚先祖硬币，并听取关于其他长者位置的指引。",al={"为什么要拜访星灵长者","星灵长者任务目标","春节星灵长者"}},{q="为什么星灵长者在发光？",a="和其他在节日期间到访的受人尊敬的灵魂一样，星灵长者被一道明亮的月光之柱所笼罩，这标志着他是一位与生者交流的先祖。",al={"为什么星灵长者在发光","长者光柱"}},{q="星灵长者能提供哪些其他长者的方位？",a="星灵长者提供如何找到附近先祖之魂的指引，包括晨露长者、符文图腾长者、梦视长者和狂鬃长者。",al={"其他长者","星灵长者提到了谁","星灵长者指引"}},{q="联盟玩家可以和星灵长者对话吗？",a="可以，尽管乱风岗是一个防御严密的部落定居点。联盟冒险者必须小心避开卫兵，才能在不引发冲突的情况下接近这位长者。",al={"联盟可以和星灵长者对话吗","联盟乱风岗长者"}},{q="和星灵长者对话会发生什么？",a="在你向他问候并致敬后，星灵长者会赞许你的精神并给予你一份先祖的祝福信物，从而完成这次短暂的会面。",al={"星灵长者奖励","完成星灵长者任务"}}},fp="17,154,23.231.0,18.181.0,31.129.0,49.171.0,29.173.0,55.144.0,48.166.0,45.134.0"}
P.entries["quest:869"] = {n="偷钱的迅猛龙",s="当一笔至关重要的守卫薪水从十字路口的守卫塔中不翼而飞时，守卫们抓到了一名不可思议的罪魁祸首：一只野生迅猛龙。加兹罗格对这起盗窃案感到困惑且愤怒，下令进行报复性扑杀，以防止这些狡猾的野兽再次袭击。",h="当一笔至关重要的守卫薪水从十字路口的守卫塔中不翼而飞时，守卫们抓到了一名不可思议的罪魁祸首：一只野生迅猛龙。加兹罗格对这起盗窃案感到困惑且愤怒，下令进行报复性扑杀，以防止这些狡猾的野兽再次袭击。",kw={"贫瘠之地","十字路口","加兹罗格","守卫塔","薪水","迅猛龙","迅猛龙首级","白银"},ang={["class:Hunter"]="贫瘠之地的迅猛龙以其狡猾、群体协作和速度而闻名，这使它们既成为了令人畏惧的目标，也成为了猎人们必须掌握的严酷生态环境的展现。",["faction:Horde"]="十字路口是部落在卡利姆多的后勤脊梁；一支未领到薪水或蒙受羞辱的驻军威胁着每一支穿过草原的商队的安全。"},sec={{t="令人困惑的盗窃案",b="十字路口非常依赖雇佣兵和步兵守卫来保持贫瘠之地各处重要贸易路线的畅通。按时向这些守卫支付薪水对于维持士气和纪律至关重要。当装有白银的薪水直接从守卫塔中消失时，领导层本以为是半人马掠夺者或野猪人拾荒者所为。然而，在深夜里人赃并获的盗贼竟然是一只贫瘠之地的捕食性迅猛龙，这让定居点的领导层感到震惊且损失惨重。"},{t="向兽群复仇",b="加兹罗格并不假装理解为什么野兽会囤积闪亮的硬币，他也不屑于去研究动物行为。随着守卫们因为薪水丢失而变得躁动不安，加兹罗格要求血债血偿并以此震慑它们。他派遣猎人去收割萨瓦纳平原上十几只迅猛龙的头颅，旨在打破这些捕食者的嚣张气焰，然后再发起全面的白银追回行动。"}},faq={{q="为什么迅猛龙会偷白银硬币？",a="即使是加兹罗格也承认这听起来令人难以置信。迅猛龙以敏锐的智慧和高超的狩猎技巧著称，但囤积精炼货币对于野生捕食者来说是闻所未闻的。加兹罗格并不关心它们奇怪的动机，他更关心在这些生物再次袭击哨所之前惩罚它们。",al={"为什么迅猛龙想要白银","迅猛龙偷钱","为什么是白银"}},{q="加兹罗格是谁？",a="加兹罗格是一名驻扎在贫瘠之地十字路口的兽人军官。他负责维持防御和秩序，监管守卫后勤、斥候悬赏以及部落中心枢纽面临的各种当地威胁。",al={"加兹罗格","谁发布迅猛龙盗贼任务"}},{q="被偷走的白银原本是用来做什么的？",a="被偷走的箱子里装的是用来支付给保卫十字路口的守卫的薪水。如果没有它，在危险的贫瘠之地维持警惕的守卫工作将变得困难得多。",al={"白银的用途","被盗的货物"}},{q="盗窃发生在哪里？",a="这批货物是在夜幕掩护下直接从十字路口的守卫塔中被盗走的，这让那些认为他们的中心据点固若金汤的守卫们感到震惊。",al={"白银在哪里被偷","盗窃地点"}},{q="这些迅猛龙在哪里可以找到？",a="成群的迅猛龙徘徊在贫瘠之地中部和南贫瘠之地的草原上。那些在靠近十字路口地带潜伏的群体通常经验不足，更容易让旅行的冒险者进行应对。",al={"迅猛龙位置","哪里寻找迅猛龙"}},{q="这个任务能找回被偷走的白银吗？",a="不能。这项任务纯粹是为了进行惩罚性的震慑，以屠杀那些作恶的野兽并减少它们的数量。加兹罗格只有在迅猛龙的威胁被击退后，才会组织针对被盗白银钱箱的实际搜寻工作。",al={"我能拿回白银吗","白银在哪里"}}},fp="14,150,16.353.0,21.321.0,37.249.0,14.194.0,37.150.0,31.156.0,30.149.0,42.184.0"}
P.entries["quest:87"] = {n="金牙",s="金牙是艾尔文森林的一项任务，它结束了那场因寻找波尼斯的项链而引发的家族争端。在年轻的比利·马科伦交代了项链的下落后，你必须追踪一只潜伏在法戈第矿洞附近、偷窃成性的狗头人。",h="金牙是艾尔文森林的一项任务，它结束了那场因寻找波尼斯的项链而引发的家族争端。在年轻的比利·马科伦交代了项链的下落后，你必须追踪一只潜伏在法戈第矿洞附近、偷窃成性的狗头人。",kw={"波尼斯","比利","法戈第","金牙","狗头人","马科伦","项链","斯通菲尔德"},ang={["race:Human"]="解决这场争吵有助于平息艾尔文森林两个最古老的农耕家族之间的摩擦，同时还能处理困扰着这个王国的顽固狗头人害虫。"},sec={{t="小男孩的恶作剧",b="寻找波尼斯·斯通菲尔德大婶遗失的传家宝项链，最初引发了斯通菲尔德和马科伦两个家族之间激烈的边界纠纷。波尼斯自然怀疑是竞争家族拿走了项链，但罪魁祸首其实是比利·马科伦。这个小淘气在法戈第矿洞附近胡闹时弄丢了饰品，为了掩盖自己的过失，他匆忙编造说自己只是偶然发现了项链，然后被一只生物抢走了。"},{t="矿洞上方的巢穴",b="据比利所说，一只异常巨大、有着闪亮尖牙的狗头人捡走了那个闪闪发光的纪念品，然后溜走了。比利声称它逃回了矿洞上方的一个巢穴，但那只名叫金牙的野兽实际上潜伏在法戈第矿洞的下层。击杀这只生物可以找回波尼斯的项链，结束社区里的纠纷，并获得波尼斯已故丈夫留下的一件古老的战役纪念品。"}},faq={{q="谁偷了波尼斯大婶的项链？",a="最可能是比利·马科伦拿走的：他无意中说漏嘴，承认自己在法戈第矿洞附近玩耍时弄丢了它，随后又改口说自己只是在那里看到了它。在他捡回之前，狗头人金牙抢走了这个闪亮的战利品。",al={"谁偷了项链","谁拿走了项链","马科伦家族偷了项链吗"}},{q="在哪里可以找到金牙？",a="金牙潜伏在法戈第矿洞的下层，尽管比利描述它的巢穴是在矿洞上方。",al={"金牙位置","金牙在哪里","找到金牙"}},{q="金牙是什么样的生物？",a="金牙是一只超大号的狗头人，它最引人注目的特征就是那颗闪闪发光的金色尖牙，这也让它得名如此，而且像它的所有同类一样，它也对明亮闪光的饰品毫无抵抗力。",al={"金牙是什么","金牙是狗头人吗"}},{q="这项任务与马科伦和斯通菲尔德家族的争端有什么联系？",a="斯通菲尔德家族和马科伦家族是死对头，他们互相怀疑对方导致了任何微小的盗窃或不幸。波尼斯大婶认为马科伦家族是出于恶意偷走了她的项链，但追查发现这仅仅是因为比利的粗心大意。",al={"斯通菲尔德和马科伦家族的矛盾","为什么波尼斯责怪比利"}},{q="波尼斯大婶提供的奖励是什么？",a="波尼斯大婶会给你一件古老的、据说是幸运物的纪念品，它属于她已故的丈夫，他悲剧性地在最后一次军事行动中忘记带上它了。",al={"波尼斯的奖励","你能得到什么"}},{q="什么任务直接通向金牙？",a="任务“回到比利身边”直接通向金牙，在该任务中，你用猪肉贿赂了比利·马科伦，这样他最终才会交代项链的下落。",al={"金牙前置任务","金牙之前的任务"}}},fx={["36c74007"]={q="比利·马科伦为什么想找回波尼斯的项链？",a="比利在法戈第矿洞附近玩耍时，不小心弄丢了波尼斯老太太的项链，却拼命否认自己偷过项链。他知道，要是项链找不回来，自己就有大麻烦了，尤其是马科伦家族和斯通菲尔德家族之间还有着深仇大恨。让你从狗头人手中找回项链，他就能弥补过错，不必直接面对波尼斯的怒火。",al={"比利·马科伦的动机","比利为什么想要项链","为什么帮助比利·马科伦"}},b7400482={q="波尼斯的项链是什么？",a="波尼斯的项链是波尼斯·斯通菲尔德姑妈珍爱的传家宝。项链在斯通菲尔德家族和马科伦家族激烈争斗期间失踪，最终被一个贪婪的狗头人抢走。对波尼斯而言，它的价值主要在于寄托的情感，她迫切希望它能回到斯通菲尔德农场。",al={"波尼斯的项链","波尼斯老太太的项链是什么","波尼斯项链的用途"}},["4539d353"]={q="比利为什么找你，而不找卫兵？",a="比利只是个心怀愧疚、惊恐不安的孩子，向暴风城卫兵求助，就会暴露是他先拿走或弄丢了波尼斯·斯通菲尔德的首饰。况且，当地卫兵为了应付艾尔文森林各处的迪菲亚匪徒和豺狼人，早已疲于奔命，不太可能为了一位老妇人丢失的项链去追捕一个凶恶的狗头人。",al={"比利为什么选我","为什么不找暴风城卫兵","比利为什么需要帮助"}}},fp="9,159,16.302.0,22.311.0,36.234.1,29.111.0,35.120.0,61.210.1,39.155.0,41.133.0"}
P.entries["quest:870"] = {n="遗忘之池",s="十字路口的图加·符文图腾派遣部落的冒险者去调查遗忘之池，那是一片位于定居点西北方的绿洲。塞纳里奥议会怀疑有某种未知的地下能量正促使繁茂的植被在这片干旱的草原上疯狂生长。",h="十字路口的图加·符文图腾派遣部落的冒险者去调查遗忘之池，那是一片位于定居点西北方的绿洲。塞纳里奥议会怀疑有某种未知的地下能量正促使繁茂的植被在这片干旱的草原上疯狂生长。",kw={"贫瘠之地","塞纳里奥议会","十字路口","裂隙","遗忘之池","绿洲","图加·符文图腾"},ang={["class:Druid"]="对于德鲁伊来说，这项任务是初步了解那些正在塞纳里奥议会的监视下腐蚀并改变贫瘠之地自然生长的神秘力量的开端。",["faction:Horde"]="由于十字路口是杜隆塔尔、莫高雷和灰谷之间的重要枢纽，保护附近的水资源免受异常腐蚀对于部落来说是一项实际的当务之急。",["race:Tauren"]="贫瘠之地的土地是大地母亲的游牧部落所珍视的，因此保护和了解其水源对牛头人旅者来说至关重要。"},sec={{t="草原上的骚动",b="很久以前，贫瘠之地曾是一片肥沃且充满活力的土地，但在经历了无数岁月的战争和大分裂的摧残后，这片大陆支离破碎，最终沦为焦灼的灌木丛。然而最近，葱郁的绿洲奇迹般地开始在这片干涸的盆地中扎根。对于塞纳里奥议会的德鲁伊来说，这种突然的繁茂很不寻常。他们感应到的并非普通的泉水，而是某种地下力量正穿透地壳向上涌动，在这片荒原的异常区域中强行催生出植被和野生动物。"},{t="浑浊的深渊",b="为了探明这一现象背后的原因，图加·符文图腾指引旅人们深入位于十字路口西北方的遗忘之池。在池底，人们发现了一个令人不安的秘密：一道地壳裂隙正源源不断地向水中排放着奇怪的冒泡气体。图加目前还无法确定这意味着什么，但这条裂隙为揭开席卷贫瘠之地的异常变化提供了第一条切实的线索。"}},faq={{q="图加·符文图腾是谁？",a="图加·符文图腾是驻扎在十字路口的一名塞纳里奥议会牛头人德鲁伊。他致力于研究贫瘠之地的生态异常现象，希望能找出为什么这些充满活力的绿洲会突然出现在这片干旱的平原上。",al={"图加·符文图腾","任务发布者","十字路口任务发布者"}},{q="为什么塞纳里奥议会要调查遗忘之池？",a="虽然干旱的土地重新焕发绿意听起来是件好事，但德鲁伊们感觉到，某种异常的集中能量正在强行将生命催生至地表。他们希望能查明滋养这些新绿洲的根源力量，以免其发展到失控的地步。",al={"为什么要调查绿洲","贫瘠之地绿洲德鲁伊","水池有什么问题"}},{q="在遗忘之池的底部发现了什么？",a="绿洲的池底有一道水下裂隙，正向池水中排放着不断冒泡的地下气体。图加认为这可能是能量泄漏到地表的一条线索，尽管他还无法确定。",al={"水里有什么","遗忘之池裂隙","池中冒泡之物"}},{q="遗忘之池在哪里？",a="遗忘之池位于贫瘠之地中部十字路口的西北方不远处，在那片干涸的土地上，环绕着一圈郁郁葱葱的棕榈树和池水，非常容易辨认。",al={"遗忘之池位置","遗忘之池在哪里"}},{q="贫瘠之地一直都是荒漠吗？",a="根据德鲁伊的传说，贫瘠之地曾经是一片物种繁茂、生机勃勃的土地。大灾变和古代战争烧焦了这片土地，使其变成了今天人们所看到的干旱草原。",al={"贫瘠之地一直干旱吗","远古贫瘠之地","贫瘠之地历史"}},{q="调查遗忘之池后接下来要做什么？",a="图加·符文图腾在收到你关于冒泡裂隙的发现后，会派遣你去调查贫瘠之地的另一片绿洲：位于东南方的死水绿洲。",al={"后续任务","调查遗忘之池后做什么"}}},fp="19,262,25.392.0,16.306.1,23.195.0,61.179.0,51.147.0,38.125.0,32.150.0,51.89.0"}
P.entries["quest:871"] = {n="野猪人的袭击",s="“扰乱攻击”是贫瘠之地十字路口的索克发布的一项早期防御任务。极具侵略性的钢鬃野猪人切断了连接杜隆塔尔和该哨站的补给路线，威胁到了定居点的生存。部落的冒险者们被派往那里削减野猪人的兵力，同时侦察兵会试图定位他们战团的领袖。",h="“扰乱攻击”是贫瘠之地十字路口的索克发布的一项早期防御任务。极具侵略性的钢鬃野猪人切断了连接杜隆塔尔和该哨站的补给路线，威胁到了定居点的生存。部落的冒险者们被派往那里削减野猪人的兵力，同时侦察兵会试图定位他们战团的领袖。",kw={"贫瘠之地","十字路口","杜隆塔尔","野猪人","钢鬃部族","索克","荆棘织法者","水语者"},ang={["class:Hunter"]="在灌木丛中打倒钢鬃猎手，是对那些熟悉地形的本地散兵进行追踪技巧的考验。",["faction:Horde"]="杜隆塔尔和十字路口之间的补给路线是部落在卡利姆多中部的核心后勤动脉；让野猪人切断这条路线可能会导致整个哨站陷入饥荒。",["race:Orc"]="对于定居杜隆塔尔的兽人来说，贫瘠之地代表着至关重要的扩张空间，这使得野猪人不断的伏击成为了必须以武力解决的障碍。"},sec={{t="切断的生命线",b="十字路口是所有部落交通穿过卡利姆多中部的核心枢纽。它的生存完全依赖于从杜隆塔尔向西运送粮食、铁矿和装备的货运马车和商队。当钢鬃部族在东北方向的道路上发动激进的伏击时，这些重要的物资补给立刻被迫中断。随着资源日益匮乏，防御储备不断减少，索克已经无法再进行和平谈判了。"},{t="修剪荆棘",b="与其坐等野猪人对城镇城墙发动直接进攻，索克下令对定居点东北方向的荆棘巢穴进行先发制人的打击。打击他们的水语者、荆棘织法者和猎手可以削弱他们的侦察防线，并剥夺他们突袭部队的魔法和后勤支持。这些初步的战斗争取了宝贵的时间，让部落的追踪者可以深入灌木丛，查明是谁在策划这些袭击。"}},faq={{q="为什么钢鬃部族要袭击商队？",a="钢鬃部族将贫瘠之地的干旱平原视为他们的祖居地。十字路口的建立以及部落商队频繁穿过他们的狩猎场被视为不可容忍的入侵，这驱使他们伏击补给马车。",al={"为什么野猪人会攻击","钢鬃部族的动机","为什么要攻击杜隆塔尔之路"}},{q="索克是谁？",a="索克是一位驻扎在十字路口的兽人指挥官。他负责哨站的日常防御，协调侦察兵并指派勇士去保卫贸易路线，抵御敌对的半人马、鹰身人和野猪人。",al={"索克是谁","索克的背景故事","十字路口的领袖"}},{q="这些野猪人位于哪里？",a="被锁定目标的钢鬃营地位于十字路口的东侧和东北侧，坐落在将贫瘠之地与杜隆塔尔隔开的山脉底部。营地周围高耸的荆棘藤蔓是他们显眼的标志。",al={"钢鬃部族在哪里","钢鬃部族位置","荆棘织法者在哪里"}},{q="在扰乱攻击之后还有什么后续？",a="削减他们的兵力仅仅是权宜之计。一旦初步敌军被击溃，侦察兵确定了袭击者的指挥官身份，索克就会立刻指派你在后续任务“扰乱的终结”中去追杀他们的首领。",al={"扰乱攻击后接什么任务","扰乱攻击的后续任务"}},{q="水语者在部族中扮演什么角色？",a="水是贫瘠之地最稀有、最宝贵的资源。水语者是至关重要的后勤采集者，他们负责定位天然水井、绿洲和隐藏的地下泉水，以维持部族及其战团在炎热灌木丛中的水分补给。",al={"什么是水语者","钢鬃水语者背景"}},{q="什么是荆棘织法者？",a="荆棘织法者是野猪人的地卜师和施法者，他们能够操纵大地，并培育出守卫巢穴的大型坚固荆棘。在战斗中，他们会利用区域性的自然魔法来对抗入侵者。",al={"什么是荆棘织法者","野猪人荆棘织法者"}}},fp="19,258,18.343.0,20.372.0,39.182.0,13.201.0,33.175.0,42.155.1,45.159.0,22.199.0"}
P.entries["quest:8717"] = {n="月光长者",s="月光长者是一位受人尊敬的先祖之魂，在春节期间，他会伫立在贫瘠之地十字路口的一道星光束下。与他交谈，旅行者可以获得古老的智慧，并得到前往卡利姆多各地其他长者的指引。",h="月光长者是一位受人尊敬的先祖之魂，在春节期间，他会伫立在贫瘠之地十字路口的一道星光束下。与他交谈，旅行者可以获得古老的智慧，并得到前往卡利姆多各地其他长者的指引。",kw={"先祖","十字路口","长者","月光长者","长者们","春节","贫瘠之地"},ang={["class:Druid"]="对于那些与自然和月相保持协调的德鲁伊来说，月光长者对天界奥秘和星象预兆的关注引起了他们的深刻共鸣。",["faction:Alliance"]="拜访月光长者需要直接闯入防御森严的部落枢纽十字路口，这使得片刻的静谧敬意演变成了一次危险的渗透。",["faction:Horde"]="对于那些穿行于卡利姆多中心十字路口的部落流浪者来说，向月光长者致敬是庆祝先祖传统时既便捷又必不可少的一部分。"},sec={{t="贫瘠之地的一道天界之光",b="月光长者伫立在十字路口尘土飞扬的要道中央，周身沐浴着一束神圣的光芒。他代表了春节期间人们所崇敬的古老灵魂，在这个节日里，凡人们会放下纷争，向先辈的智慧致敬。"},{t="指引先祖之路",b="月光长者沉思于星空，思考它们如何向那些仰望星空寻求真理的人们揭示尘世的奥秘。除了赐予他自己的先祖祝福外，他还为寻求者指引前往卡利姆多各地其他长者的方向，包括血蹄长者、高山长者、晨露长者和符文图腾长者。"}},faq={{q="在哪里可以找到月光长者？",a="月光长者站在贫瘠之地的十字路口，上方有一道明亮的星光柱照耀着他，非常显眼。",al={"月光长者位置","月光长者在哪里","月光长者十字路口"}},{q="拜访月光长者的目的是什么？",a="旅行者在春节期间拜访他是为了向先祖之魂致敬，获得先祖硬币，并寻求前往各地其他受人尊敬的长者的指引。",al={"为什么要与月光长者交谈","月光长者任务","春节月光长者"}},{q="月光长者能指引你前往哪些其他长者处？",a="月光长者会分享几位附近灵魂的下落，特别是血蹄长者、高山长者、晨露长者和符文图腾长者。",al={"其他长者","月光长者指引","月光长者提到了谁"}},{q="联盟冒险者可以与月光长者交谈吗？",a="先祖长者会尊敬每一位勇敢的朝圣者，无论其阵营如何。但由于月光长者直接站在部落的定居点十字路口，联盟旅行者在当地守卫周围行动时必须小心谨慎。",al={"联盟可以与月光长者交谈吗","十字路口长者联盟"}},{q="为什么月光长者身上有一道光束？",a="就像春节期间出现的所有灵魂一样，月光长者被一束来自天界的月光所照亮，象征着与星辰和先祖领域的连接。",al={"光束长者","月光长者光柱"}},{q="月光长者对星辰说了些什么？",a="月光长者感叹天空中数不尽的星辰掌握着尘世奥秘的答案，并询问睿智与幸运之人是否会仰望星空并找到真理。",al={"月光长者对话","月光长者语录"}}},fp="20,203,35.214.0,25.239.0,34.95.0,49.126.0,48.111.0,53.156.0,57.117.0,47.131.0"}
P.entries["quest:8718"] = {n="迅刀长者",s="刀刃迅捷长老是一位在春节期间于暗夜精灵主城达纳苏斯受到祭奠的先祖之魂。这位古老的存在位于塞纳里奥区，向旅行者传授来自璀璨星空的智慧。寻得他的祝福，冒险者便能直接与塞纳里奥议会和暗夜精灵民族受人尊敬的传统建立联系。",h="刀刃迅捷长老是一位在春节期间于暗夜精灵主城达纳苏斯受到祭奠的先祖之魂。这位古老的存在位于塞纳里奥区，向旅行者传授来自璀璨星空的智慧。寻得他的祝福，冒险者便能直接与塞纳里奥议会和暗夜精灵民族受人尊敬的传统建立联系。",kw={"先祖","刀刃迅捷","先祖硬币","塞纳里奥区","达纳苏斯","刀刃迅捷长老","春节","泰达希尔"},ang={["class:Druid"]="作为塞纳里奥议会麾下的自然守护者，德鲁伊肩负着尊崇像刀刃迅捷这样的古老灵魂的深厚文化和精神职责。",["faction:Alliance"]="刀刃迅捷长老位于达纳苏斯内部，安全无虞，为联盟英雄在春节期间提供了一次轻松而祥和的朝圣之旅。",["race:NightElf"]="在达纳苏斯面见刀刃迅捷长老，是一次与你们民族的星空传承和对苍穹的虔诚信仰的直接交流。"},sec={{t="枝叶之灵",b="春节期间，受人尊敬的先祖之灵会在艾泽拉斯各地显现，分享他们的智慧并赐予旅行者祝福。刀刃迅捷长老伫立在达纳苏斯塞纳里奥区宁静的枝叶之间。与那些忙于应对当下困境的现代居民不同，这位幽灵般的先辈仰望着苍穹，沉思着交织在夜空中的奥秘。"},{t="星光与古老的真理",b="暗夜精灵文化一直崇敬天体，将其视为艾露恩的倒影以及生命深层秘密的映射。刀刃迅捷提醒那些接近他的人，无数星辰中蕴含着应对尘世纷争的答案，并以此敦促睿智而幸运之人向上仰望。通过对他表示敬意，冒险者可以获得一枚先祖硬币，并参与一场连接凡人世界与往昔之灵的永恒仪式。"}},faq={{q="谁是刀刃迅捷长老？",a="刀刃迅捷长老是一位在季节性的春节期间受到祭奠的暗夜精灵先祖之魂。他出现在达纳苏斯，为寻求祭奠先辈的旅行者提供哲学指导和祝福。",al={"谁是刀刃迅捷","刀刃迅捷长老背景","刀刃迅捷的身份"}},{q="在哪里可以找到刀刃迅捷长老？",a="他位于暗夜精灵主城达纳苏斯的塞纳里奥区，俯瞰着这座树城中宁静的池塘和木质步道。",al={"刀刃迅捷位置","刀刃迅捷长老在哪里","达纳苏斯刀刃迅捷"}},{q="寻找长老的目的是什么？",a="拜访长老是春节的一项核心传统。通过向世界各地的这些古老灵魂表达敬意，冒险者可以缅怀往昔的智慧，赢得先祖硬币和节日的好运。",al={"为什么要寻找长老","春节长老的目的","拜访长老"}},{q="刀刃迅捷对与他交谈的人传授什么？",a="刀刃迅捷鼓励寻求者仰望苍穹。他暗示，对于那些耐心且睿智的观察者而言，无数星辰中蕴含着深刻的真理和应对尘世奥秘的答案。",al={"刀刃迅捷的信息","刀刃迅捷说什么"}},{q="部落成员可以拜访刀刃迅捷长老吗？",a="虽然刀刃迅捷居住在达纳苏斯深处——一座由警惕的哨兵守卫的联盟主城——但这位季节性的灵魂本身欢迎任何怀有敬意的旅行者，尽管部落访客必须穿过敌对守卫才能到达他身边。",al={"部落可以和刀刃迅捷对话吗","部落刀刃迅捷长老","刀刃迅捷联盟专属"}},{q="既然泰达希尔是一棵新的世界之树，为什么那里会有长老？",a="尽管泰达希尔是在第三次战争后才刚刚种下的，但卡多雷先祖的灵魂被他们族人的生命之心所吸引，出现在他们亲友身边以观察节日。",al={"为什么刀刃迅捷在达纳苏斯","泰达希尔长老背景"}}},fp="20,195,22.281.0,28.275.0,24.171.0,36.137.0,46.193.0,52.174.0,48.189.0,64.185.0"}
P.entries["quest:872"] = {n="野猪人的头目",s="在有证据表明部落补给线遭到蓄意袭击后，索克下令处决克里尼格·钢鬃，他是负责策划从杜隆塔尔出发的商队袭击事件的刺鬃野猪人战团领袖。通过突破他们的防线并夺取克里尼格的獠牙，部落意在让这个好战的部族陷入混乱。",h="在有证据表明部落补给线遭到蓄意袭击后，索克下令处决克里尼格·钢鬃，他是负责策划从杜隆塔尔出发的商队袭击事件的刺鬃野猪人战团领袖。通过突破他们的防线并夺取克里尼格的獠牙，部落意在让这个好战的部族陷入混乱。",kw={"贫瘠之地","商队","十字路口","保卫者","杜隆塔尔","地卜师","克里尼格·钢鬃","野猪人","刺鬃","索克"},ang={["faction:Horde"]="杜隆塔尔和十字路口之间的补给路线是部落早期在卡利姆多扩张的生命线；保持其畅通可确保内陆哨所的生存。",["race:Orc"]="索克的军事哲学反映了传统的兽人战斗准则：在敌方战士面前斩杀他们的酋长，从而粉碎敌人的意志。"},sec={{t="斩首行动",b="杜隆塔尔和十字路口之间至关重要的贸易路线不断遭到伏击，威胁到了穿越贫瘠之地北部的补给和增援。斥候报告锁定了罪魁祸首：一支由名为克里尼格·钢鬃的酋长组织并指挥的极具攻击性的刺鬃野猪人突袭队。索克意识到零星的冲突永远无法永久确保道路安全，于是下令对该领袖进行直接的斩首行动，以瓦解该部族的战术凝聚力。"},{t="突入营地",b="克里尼格将他的战团驻扎在十字路口东北部的崎岖山丘中，受到坚韧的刺鬃保卫者和操纵干旱大地的地卜师的保护。消灭他的卫队并在他自己的堡垒中击杀钢鬃，意在向整个平原传达一个严厉的警告。夺取克里尼格被砍下的獠牙是不可辩驳的证据，证明部落绝不会容忍针对其生命线的掠夺行为。"}},faq={{q="克里尼格·钢鬃是谁？",a="克里尼格·钢鬃是一位驻扎在十字路口东北部的著名刺鬃野猪人突袭首领。他组织了针对从杜隆塔尔出发、行驶在主干道上的部落商队的协同袭击，促使索克下令将其处决。",al={"克里尼格是谁","克里尼格·钢鬃背景故事","谁领导刺鬃突袭者"}},{q="克里尼格·钢鬃在哪里？",a="他位于十字路口东北部的野猪人营地中，坐落在通往杜隆塔尔的主干道以南的山脚下。",al={"克里尼格在哪里","克里尼格位置","寻找克里尼格·钢鬃"}},{q="为什么索克想要克里尼格的獠牙？",a="战利品在兽人和野猪人中都具有重要的文化意义。夺取克里尼格的獠牙既是该领袖死亡的无可辩驳的证明，也对这次失败增添了公开的羞辱，从而打击剩余刺鬃战士的士气。",al={"为什么索要克里尼格的獠牙","为什么要拿走獠牙","索克的獠牙战利品"}},{q="杀死克里尼格对十字路口有什么帮助？",a="索克的策略基于这样一个信念：没有强有力的领导，野猪人战团就会陷入混乱。杀死克里尼格可以瓦解他们的战术组织，减少有组织的商队伏击，并使从杜隆塔尔通往此处的高地道路对旅行者来说更加安全。",al={"为什么要杀死克里尼格","杀死克里尼格的战略价值","十字路口商队防御"}},{q="刺鬃地卜师在部族中扮演什么角色？",a="地卜师是与大地和岩石之灵沟通的野猪人施法者，他们利用自然魔法升起尖锐的荆棘屏障，并塑造他们荆棘营地周围崎岖的地形以抵御入侵者。",al={"什么是地卜师","刺鬃地卜师背景故事","野猪人大地魔法"}},{q="哪个任务在此任务之前？",a="此任务直接承接“破坏袭击”任务，在那个任务中，斥候首次确认了刺鬃部族对东部边境商队袭击的参与程度。",al={"前置任务","在“破坏袭击终结”之前是什么","上一个任务"}}},fp="19,235,16.345.0,24.362.0,26.184.0,36.151.0,35.156.0,45.197.0,52.222.0,36.145.0"}
P.entries["quest:8721"] = {n="星纹长者",s="星纹长者是一项在黑海岸遭遇的春节任务。冒险者们会寻找位于奥伯丁定居点的星纹长者，以向卡利姆多的先祖之灵致敬。为了表彰对古老传统的尊重，她会给予旅行者天界的智慧与祝福。",h="星纹长者是一项在黑海岸遭遇的春节任务。冒险者们会寻找位于奥伯丁定居点的星纹长者，以向卡利姆多的先祖之灵致敬。为了表彰对古老传统的尊重，她会给予旅行者天界的智慧与祝福。",kw={"先祖","奥伯丁","黑海岸","刃风长者","星纹长者","春节","星纹"},ang={["class:Druid"]="德鲁伊对先祖之灵和天界的平衡保持着深深的敬意，这使得与星纹长者的沟通成为他们信仰的自然体现。",["faction:Horde"]="部落游荡者若想触及星纹长者，需要小心潜入由联盟控制的奥伯丁码头，在不激怒当地哨兵的情况下表达敬意。",["race:NightElf"]="在奥伯丁向星纹长者致敬，将暗夜精灵与他们先辈的古老灵魂以及艾露恩与星辰的崇高奥秘直接联系在了一起。"},sec={{t="奥伯丁的灯塔",b="春节期间，备受尊崇的先祖之灵会在艾泽拉斯的大陆上显现，沐浴在璀璨的天界光柱之中。星纹长者在奥伯丁的暗夜精灵中占据了一席之地，这是一座位于黑海岸迷雾缭绕的海岸线上的重要港口城镇。纪念节日的旅行者们会朝圣般来到她身边，寻求往昔岁月的永恒指引。"},{t="苍穹的低语",b="星纹长者思索着卡利姆多上空的宇宙图景，提醒所有靠近她的人，星辰承载着解答凡人疑虑与世间谜题的答案。那些花时间寻求她建议的人会被敦促仰望天空以寻求真理，并获得先祖的青睐，以及关于荒野边境其他游荡之灵的消息。"}},faq={{q="我在哪里可以找到星纹长者？",a="星纹长者位于黑海岸的暗夜精灵沿海城镇奥伯丁。她站立在一道从天而降的明亮月光束中。",al={"星纹位置","星纹长者在哪里","星纹长者黑海岸"}},{q="这个任务的目的是什么？",a="该任务是每年春节庆典的一部分。拜访并向分散在艾泽拉斯各地的先祖长者致敬，可以获得声望、节日货币和先祖的眷顾。",al={"为什么要做星纹长者任务","星纹长者目的","星纹长者做什么"}},{q="星纹长者是谁？",a="她是一位纪念春节的古老暗夜精灵之灵。她沐浴在星光之中，提供关于星座的哲学智慧，并为朝圣者指引其他受人尊敬的长者，例如刃风长者。",al={"谁是星纹长者","星纹背景故事","星纹长者背景"}},{q="部落玩家可以拜访星纹长者吗？",a="是的。节日长者保持中立，欢迎两个阵营中尊崇礼节的旅行者。然而，由于星纹长者居住在联盟的港口城市奥伯丁，部落冒险者在镇上当地的暗夜精灵卫兵身边时必须谨慎。",al={"部落可以和星纹对话吗","部落星纹长者","星纹对部落敌对"}},{q="星纹长者会对旅行者说什么？",a="在迎接访客时，她会提醒他们，头顶那无尽的星辰掌握着凡人谜题的答案，并询问那些睿智且幸运的人是否愿意仰望星空以揭示真理。",al={"星纹对话","星纹长者说什么"}},{q="星纹长者指引的是哪位长者？",a="星纹长者会分享关于刃风长者的位置与讯息，指引旅行者继续他们穿越卡利姆多北部的节日旅程。",al={"星纹提到了谁","星纹之后的长者","下一个黑海岸长者"}}},fp="19,153,21.247.0,23.301.0,33.155.0,34.138.0,23.199.0,40.190.0,41.150.0,36.114.0"}
P.entries["quest:8724"] = {n="晨露长者",s="晨露长者是一位受人尊敬的先祖之魂，在春节期间，冒险者可以前往千针石林拜访她。她沐浴在璀璨的星光之中，为朝圣者指引方向，并向他们传授那些散布在卡利姆多各地的长者们的讯息。",h="晨露长者是一位受人尊敬的先祖之魂，在春节期间，冒险者可以前往千针石林拜访她。她沐浴在璀璨的星光之中，为朝圣者指引方向，并向他们传授那些散布在卡利姆多各地的长者们的讯息。",kw={"先祖","晨露长者","长者","春节","闪光平原","星光","千针石林"},ang={["class:Druid"]="春节及其天界长者体现了与艾露恩、自然以及塞纳里奥议会所尊崇的先祖交流之间深层的联系。",["class:Shaman"]="与像晨露长者这样受人尊敬的灵魂沟通，是理解整个世界中先祖与元素平衡的关键。",["race:NightElf"]="被星光照亮的长者唤起了向天界致敬的古老传统，以及交织在卡利姆多历史中的古老智慧。",["race:Tauren"]="尊崇先祖长者的智慧是牛头人文化的支柱，这使得前往像晨露长者这样的灵魂处朝圣变得意义深远。"},sec={{t="峡谷中的天界存在",b="春节期间，古老先祖的灵魂会显现在艾泽拉斯各地，将他们的祝福分享给旅行者。晨露长者周身沐浴在月光之中，在千针石林那尘土飞扬的红岩与喧嚣的工业嘈杂声中显得格外引人注目。她提醒凡人旅行者，不要仅仅关注尘世的纷扰，还要仰望头顶那繁星璀璨的苍穹。"},{t="天堂的智慧",b="当冒险者接近她时，晨露长者会鼓励他们向无数繁星寻求尘世谜题的答案。除了这些发人深省的问候，她还是春节朝圣者的向导，分享关于徘徊在这片土地上的其他受人尊敬的灵魂的所在位置，其中包括高山长者、恐怖图腾长者、雾行者长者、月光长者和风之图腾长者。"}},faq={{q="晨露长者是谁？",a="晨露长者是一位在春节期间显现的先祖之魂。她沐浴在星光中，为那些寻求向长者致敬的过往冒险者提供智慧与指引。",al={"晨露长者","晨露长者背景故事","晨露长者是谁"}},{q="在哪里可以找到晨露长者？",a="她位于千针石林，从天而降的光柱是她最显著的标志。",al={"晨露长者位置","晨露长者在哪里","寻找晨露长者"}},{q="拜访晨露长者的目的是什么？",a="旅行者在春节期间拜访她，是为了向先祖表达敬意，获得先祖的祝福，并了解该地区其他长者的位置。",al={"为什么要拜访晨露长者","晨露长者目的","春节长者"}},{q="晨露长者知道其他哪些长者？",a="晨露长者可以为其他五位受人尊敬的灵魂指引方向：高山长者、恐怖图腾长者、雾行者长者、月光长者和风之图腾长者。",al={"晨露长者提到的其他长者","晨露长者提到的长者名单","晨露长者提到谁"}},{q="为什么会有光柱照在她身上？",a="春节期间的每一位先祖之魂都会被一道天界星光所照亮，以此彰显他们空灵的存在，以及他们与上方天界的联系。",al={"晨露长者光柱","长者光束","为什么长者会发光"}},{q="晨露长者教导朝圣者什么？",a="晨露长者教导说，天堂和那无数的星辰掌握着尘世谜题的答案，并鼓励那些有智慧且幸运的人仰望星空，去寻找真理。",al={"晨露长者建议","晨露长者对话","晨露长者说什么"}}},fp="20,170,35.291.0,21.258.0,24.170.0,36.101.0,49.145.0,46.125.0,51.138.0,36.150.0"}
P.entries["quest:8725"] = {n="水歌长者",s="水歌长者是一位在春节期间受到尊崇的暗夜精灵先祖之魂，她静静地在阿斯特兰纳的一座宁静神龛下休憩。她沐浴在一束月光中，向旅行者们提供静谧的智慧，并指引朝圣者前往卡利姆多各地的其他受人尊敬的先祖处。",h="水歌长者是一位在春节期间受到尊崇的暗夜精灵先祖之魂，她静静地在阿斯特兰纳的一座宁静神龛下休憩。她沐浴在一束月光中，向旅行者们提供静谧的智慧，并指引朝圣者前往卡利姆多各地的其他受人尊敬的先祖处。",kw={"先祖","灰谷","阿斯特兰纳","长者","春节","水歌长者","神龛","星纹长者"},ang={["class:Druid"]="春节及其天上的长者体现了塞纳里奥与自然、灵魂以及夜空的古老羁绊。",["faction:Alliance"]="阿斯特兰纳是联盟在卡利姆多中部的主要据点之一，这使得水歌长者成为春节期间联盟朝圣者轻松且受欢迎的拜访对象。",["race:NightElf"]="对于暗夜精灵来说，在阿斯特兰纳的神龛下尊崇水歌长者，是一次在灰谷星空下与他们种族悠久历史进行心灵沟通的亲密仪式。"},sec={{t="阿斯特兰纳的灯塔",b="在阿斯特兰纳的古木与木制走道之间，水歌长者出现在一座露天的暗夜精灵神龛下。一束独特的星光穿透了灰谷的树冠，照耀着她，她那空灵的存在成为春节期间寻求与往昔世代交流的参与者们关注的焦点。"},{t="凝望苍穹",b="水歌长者提醒朝圣者们，暗夜精灵有一个古老的传统，即从星空中解读真理与奥秘。她的话语引导旅行者通过耐心与沉思来寻求智慧，并指引那些庆祝这个节日的人们前往其他的先祖之灵处，包括星纹长者。"}},faq={{q="我在哪里可以找到水歌长者？",a="水歌长者位于灰谷的阿斯特兰纳定居点内。她坐落在一座暗夜精灵小神龛下，沐浴在一束从森林树冠倾泻而下的明亮星光中。",al={"水歌长者位置","水歌长者在哪里","水歌长者坐标"}},{q="拜访水歌长者的目的是什么？",a="拜访水歌长者是春节期间祭奠先祖活动的一部分。与她交谈可以获得先祖祝福和先祖硬币，同时她还会提供有关寻找卡利姆多各地其他长者的指引。",al={"为什么拜访水歌长者","水歌长者有什么用"}},{q="水歌长者会指引你去找哪位长者？",a="水歌长者指引寻求者去找星纹长者，那是另一位同样在庆祝春节的受人尊敬的暗夜精灵之灵。",al={"水歌长者之后的下一个长者","水歌长者提到了谁"}},{q="部落玩家可以与水歌长者交谈吗？",a="因为水歌长者直接居住在联盟枢纽阿斯特兰纳内，部落玩家必须在面对城镇守卫和哨兵的情况下接近她，尽管节日长者本身并不会根据阵营拒绝交流。",al={"部落可以拜访水歌长者吗","水歌长者是联盟独有的吗"}},{q="为什么水歌长者会被光束包围？",a="这束星光代表着艾露恩与苍穹的眷顾，照亮了每一位在春节期间现身的先祖之魂。",al={"为什么水歌长者会发光","水歌长者身上的光"}},{q="水歌长者在受到尊崇时会说什么？",a="水歌长者沉思于宇宙，观察到天空中无数的繁星蕴含着世间奥秘的答案，并询问那些智慧而幸运的人是否愿意仰望星空以探寻真理。",al={"水歌长者引言","水歌长者对话"}}},fp="19,188,21.207.0,21.191.0,33.141.0,48.207.0,45.112.0,43.176.0,53.167.0,43.167.0"}
P.entries["quest:8728"] = {n="好消息和坏消息",s="纳瑞安读完了账本，他有好消息也有坏消息。他几乎可以肯定能按照你的规格制造一个奥金浮标，但他需要大量的奥金锭、源质矿石和精良的宝石。这得等到小鸡、护目镜和第二本《龙语傻瓜教程》全部完成后才能开始。",h="纳瑞安读完了账本，他有好消息也有坏消息。他几乎可以肯定能按照你的规格制造一个奥金浮标，但他需要大量的奥金锭、源质矿石和精良的宝石。这得等到小鸡、护目镜和第二本《龙语傻瓜教程》全部完成后才能开始。",kw={"奥金锭","奥金浮标","艾泽拉斯钻石","蓝宝石","源质矿石","纳瑞安","塔纳利斯"},sec={{t="好消息，坏消息",b="纳瑞安默默地读着账本，低声嘟囔着。他有百分之九十九的把握能制造出你所指定的奥金浮标，但他表示这一切都取决于那个坏消息。为了这个浮标，他需要二十个奥金锭、十个源质矿石、十个艾泽拉斯钻石和十个蓝宝石。把它们带来，他就会开始制作。"},{t="纳瑞安的警告",b="当你把所有东西都带来时，纳瑞安说交易就是交易。他希望你知道自己在做什么，因为在他看来，为了钓鱼而费这么大周折实在是太麻烦了。"}},faq={{q="谁提供这个任务？",a="塔纳利斯的纳瑞安。他只在小鸡、探知护目镜和第二本《龙语傻瓜教程》部分的工作全部完成后才会提供此任务。",al={"任务发布者","纳瑞安位置","纳瑞安在哪里"}},{q="纳瑞安需要什么材料？",a="纳瑞安需要二十个奥金锭、十个源质矿石、十个艾泽拉斯钻石和十个蓝宝石。",al={"所需物品","所需材料","我需要什么材料"}},{q="纳瑞安用这些材料制造什么？",a="一个奥金浮标。他有百分之九十九的把握能制造出一个符合你所提供规格的浮标。",al={"纳瑞安在制作什么","为什么需要奥金浮标","浮标有什么用"}},{q="在这一步之前需要完成什么？",a="在这一步之前需要完成“回到纳瑞安身边”任务。纳瑞安还要求完成护目镜和第二本《龙语傻瓜教程》部分的工作。",al={"前置任务","先决条件","如何触发此任务"}}},fp="30,275,19.327.0,16.176.1,22.122.0,35.106.0,45.104.0,28.111.0"}
P.entries["quest:87288"] = {n="Soft Saber Pelts",s="Soft Saber Pelts代表了一项旨在保护荒野道路免受捕食性猫科动物侵扰的贸易协议。猎人们带回当地刃豹厚实的皮毛，以便将其制成温暖的防护毯和披肩。",h="Soft Saber Pelts代表了一项旨在保护荒野道路免受捕食性猫科动物侵扰的贸易协议。猎人们带回当地刃豹厚实的皮毛，以便将其制成温暖的防护毯和披肩。",kw={"毯子","皮毛","道路","刃豹","披肩","柔软的豹皮","贸易"},ang={["class:Hunter"]="猎人们深知在尊重像刃豹这样威严的掠食者和在它们侵扰旅行路线时进行捕杀之间，存在着一种微妙的平衡。",["profession:Tailoring"]="这个任务突显了将野生刃豹皮毛制成柔软、结实的毯子和披肩以适应寒冷的边境旅行的实用工艺。"},sec={{t="保护荒野道路",b="穿行在艾泽拉斯未受驯化的道路上，需要时刻警惕潜伏的掠食者。大型刃豹经常在繁忙的通道附近游荡，对信使、商人和独行冒险者构成了持续的威胁。虽然当地居民钦佩这些大猫的优雅和威严，但任由它们在贸易路线上大量繁殖会引来致命的伏击。召集猎人来保障当地道路的安全，是维持社区生存的必要措施。"},{t="狩猎带来的温暖",b="狩猎这些令人印象深刻的野兽不仅仅是为了运动或消灭它们。在边境营地中，每一种资源都受到重视，野生刃豹那浓密、如天鹅绒般的皮毛因其保暖性和耐用性而备受推崇。一旦由能干的猎人带回，这些毛皮就会被缝制成精美的披肩和厚重的毯子，足以抵御恶劣的天气，确保取自野外的每一份资源都不被浪费。"}},faq={{q="为什么要求旅行者猎杀刃豹？",a="虽然刃豹被视为荒野中威严的野兽，但它们在既定通道上的存在对旅行者和商人构成了持续的威胁。通过减少它们的数量，可以确保该地区往来的普通旅行者的道路安全。",al={"为什么要猎杀刃豹","为什么要击杀刃豹","刃豹威胁"}},{q="刃豹皮毛有什么用途？",a="从刃豹身上采集的柔软而厚实的皮毛非常适合制作冬装。从狩猎中收集到的皮毛被加工成耐用且温暖的毯子和披肩，以抵御风寒。",al={"皮毛的用途","刃豹皮毛工艺","毯子和披肩"}},{q="谁想要交易这些刃豹皮毛？",a="当地的商人和工匠经常寻求与猎人交易有用的材料。作为优质皮毛的交换，他们会用之前制作的结实而柔软的工艺品来奖励帮助他们的旅行者。",al={"刃豹皮毛贸易","谁收购皮毛"}},{q="野生刃豹会对道路构成真正的威胁吗？",a="是的。大型捕食性猫科动物自然会划定广阔的狩猎领地，这些领地往往与边境道路重叠。如果不控制道路附近的刃豹数量，毫无防备的信使和商队就有可能遭遇突然伏击。",al={"刃豹危险吗","刃豹道路危险"}},{q="皮毛会得到什么回报？",a="接收者会赠送一件制作得既柔软又耐用的纪念品作为感激的表示，这可以作为一种实用的提醒，让人想起在边境捕获的那些威严野兽。",al={"柔软结实的奖励","纪念品奖励"}},{q="当地商人如何看待狩猎这种威严的野兽？",a="即使是那些收购皮毛的人也承认，对这些尊贵的生物使用暴力是不幸的。然而，为了保护道路上的旅行者并充分利用它们温暖的皮毛，这种狩猎的必要性是合理的。",al={"猎杀刃豹是否合理","猎杀刃豹的遗憾"}}},fp="16,134,29.245.0,20.206.0,39.122.0,34.92.0,41.144.0,47.151.0,38.122.0,62.146.0"}
P.entries["quest:873"] = {n="依沙瓦克",s="“依沙瓦克”是秘术师马赫伦·天眼在商旅海岸发布的一项神圣的狩猎仪式。勇敢的部落游荡者们肩负着潜入无尽之海，追踪并猎杀名为“深渊末日”的可怖水生掠食者的使命。通过夺取这头野兽的心脏，猎人将参与到一种古老的精神与尊重的羁绊之中。",h="“依沙瓦克”是秘术师马赫伦·天眼在商旅海岸发布的一项神圣的狩猎仪式。勇敢的部落游荡者们肩负着潜入无尽之海，追踪并猎杀名为“深渊末日”的可怖水生掠食者的使命。通过夺取这头野兽的心脏，猎人将参与到一种古老的精神与尊重的羁绊之...",kw={"深渊末日","依沙瓦克的心脏","依沙瓦克","马赫伦·天眼","商旅海岸","棘齿城","海兽"},ang={["class:Hunter"]="追踪一头传奇水生野兽深入无尽之海的深处，是对猎人在其领地内统治一切的生物面前，其耐心、狡黠和射击技巧的终极考验。",["faction:Horde"]="征服深渊末日证明了部落在商旅海岸的军事优势，击倒了一头曾恐吓当地联盟前哨站的巨兽。",["race:Tauren"]="对依沙瓦克的狩猎反映了牛头人传统的精神狩猎习俗，即尊重猎物而非轻视，且夺取生命能带来与生物灵魂的交流。"},sec={{t="深渊末日",b="依沙瓦克潜伏在棘齿城南部的海岸波涛之下。作为深渊末日，这头巨大的海洋生物以强大的力量和掠食者的威严统治着这片沿海水域。在岸边扎营的人类入侵者们已经学会了畏惧这片水域，因为他们有许多侦察兵和士兵都成了这头野兽无尽饥饿下的牺牲品。"},{t="精神的狩猎",b="与岸边那些惊恐的人类不同，马赫伦·天眼对这头巨兽怀有深深的敬畏。对于这位牛头人秘术师来说，依沙瓦克并非诅咒或单纯的害虫，而是一份馈赠：一个值得尊敬的对手，其力量是对真正猎人意志的考验。猎杀这头野兽不仅仅是为了清除掠食者，更是一种精神上的交流，旨在获取野兽精魄栖息的心脏，并将其狂野的精神传承下去。"}},faq={{q="依沙瓦克是谁？",a="依沙瓦克，称号为“深渊末日”，是一头强大的海洋猛兽，游荡在贫瘠之地东海岸、棘齿城以南的水域。它被视为这些沿海水域的主宰，并因捕食附近驻扎的人类水手和士兵而臭名昭著。",al={"依沙瓦克是什么","依沙瓦克背景故事","深渊末日"}},{q="为什么马赫伦·天眼要猎杀依沙瓦克？",a="马赫伦并非出于恶意或恐惧而猎杀依沙瓦克。她将这头强大的掠食者视为一个值得尊敬的对手，也是一场精神上的挑战。对马赫伦而言，征服这样的野兽能让猎人吸收它的力量，并与它的狂野之魂交流。",al={"为什么猎杀依沙瓦克","马赫伦·天眼的动机"}},{q="在哪里可以找到依沙瓦克？",a="这头野兽游弋在贫瘠之地东部商旅海岸的无尽之海中，位于地精港口棘齿城以南，靠近人类居住的海岸线。",al={"依沙瓦克的位置","哪里可以找到依沙瓦克","依沙瓦克刷新"}},{q="带回心脏会发生什么？",a="马赫伦·天眼认为，生物的本质和命运都寄宿在它的心脏之中。通过将其献给这位秘术师，你将从精神上与这头陨落的巨兽结合，随身携带依沙瓦克的部分力量和掠食者的视野。",al={"依沙瓦克的心脏的作用","为什么要取依沙瓦克的心脏"}},{q="马赫伦提到的人类是谁？",a="马赫伦所指的人类是在贫瘠之地海岸线活动的塞拉摩和库尔提拉斯部队，特别是围绕北方城堡及周边前哨站的势力。他们有许多水手和岸边居民惨遭这头海兽的毒手。",al={"是哪些人类","海岸上的人类","谁害怕依沙瓦克"}},{q="依沙瓦克被认为是元素生物还是自然野兽？",a="依沙瓦克是无尽之海中一种自然的、尽管异常庞大且强大的水生野兽，当地牛头人因其原始精神和狩猎技巧而对其推崇备至。",al={"依沙瓦克是野兽吗","依沙瓦克的生物类型"}}},fp="9,166,13.255.0,16.328.0,17.192.0,45.194.0,29.140.0,43.206.0,39.199.0,57.156.0"}
P.entries["quest:874"] = {n="玛伦·星眼",s="玛伦·星眼是部落的一段旅程，旨在指引通过试炼的猎人们从陶拉祖营地出发，前往贫瘠之地的东部海岸。在精通了平原上的捕食者技巧后，探险者们会被乔恩·星眼派去向他的妹妹学习沿海追踪术。找到她需要穿越商旅海岸，那里布满了危险的水域和人类营地。",h="玛伦·星眼是部落的一段旅程，旨在指引通过试炼的猎人们从陶拉祖营地出发，前往贫瘠之地的东部海岸。在精通了平原上的捕食者技巧后，探险者们会被乔恩·星眼派去向他的妹妹学习沿海追踪术。找到她需要穿越商旅海岸，那里布满了危险的水域...",kw={"陶拉祖营地","狩猎试炼","依沙瓦克","乔恩·星眼","玛伦·星眼","瑟格拉·黑棘","贫瘠之地"},ang={["class:Hunter"]="对于猎人来说，这个任务标志着从追踪传统的稀树草原猎物转变为在资深牛头人追踪者的指导下追猎凶猛的水生野兽。",["faction:Horde"]="前往东海岸的旅程会将部落的侦察兵带到与塞拉摩那不断蚕食的敌对联盟据点极其接近的地方。",["race:Tauren"]="Skyseer兄妹体现了传统的牛头人狩猎哲学，考验着大地母亲的孩子们是否能在各种生态系统中经受住试炼。"},sec={{t="平原之外的狩猎",b="通过乔恩·星眼在陶拉祖营地设下的试炼，猎人们证明了他们对抗南贫瘠之地那片红色平原上最危险野兽的韧性。然而乔恩教导说，真正的捕食者绝不会将自己局限于干旱的土地和起伏的稀树草原。要真正掌握这门技艺，追踪者必须准备好在沼泽、陡峭的悬崖以及无尽之海那翻滚的波涛中追踪猎物。"},{t="东部海岸",b="乔恩的妹妹，玛伦·星眼，在远东的海岸边建立了自己的营地。乔恩研究雷鹰和荒原狩猎者的灵魂，而玛伦则致力于研究栖息在盐雾中的那些难以捉摸的生物。穿越该地区找到她非常危险，因为库尔提拉斯的海军陆战队和塞拉摩的远征军在沿海低地设有许多加固的前哨站和瞭望塔。"}},faq={{q="是谁发布了玛伦·星眼这个任务？",a="在南贫瘠之地的陶拉祖营地，在你成功完成关于雷鹰的狩猎任务后，乔恩·星眼会发布此任务。",al={"谁开启玛伦·星眼","乔恩·星眼任务发放者"}},{q="玛伦·星眼在哪里？",a="玛伦·星眼在贫瘠之地的东部海岸线上扎营，位于棘齿城以南，靠近沿海野生动物和塞拉摩部队经常出没的海岸。",al={"玛伦·星眼在哪里","玛伦·星眼位置","找到玛伦"}},{q="这个任务的目的是什么？",a="它作为一座桥梁任务，将乔恩·星眼在陶拉祖营地的狩猎试炼与玛伦针对海洋生物的沿海狩猎挑战联系起来。",al={"为什么我需要找到玛伦","玛伦·星眼目标"}},{q="为什么乔恩要派猎人去找玛伦？",a="乔恩认为一个完美的猎人必须精通所有的环境，包括海洋。他的妹妹玛伦专门从事追踪和对抗水生野兽，是理想的导师。",al={"为什么乔恩要把我派给他的妹妹","玛伦·星眼背景故事"}},{q="前往玛伦的路途上有哪些危险？",a="贫瘠之地的东海岸被来自塞拉摩和库尔提拉斯的敌对人类远征军重兵把守，此外还有极具攻击性的沿海猛禽和海洋捕食者。",al={"到达玛伦的危险","谁占据了海岸"}},{q="找到玛伦·星眼之后做什么？",a="当你向她介绍自己并赢得她的信任后，玛伦会指派你去追踪一只潜伏在水中的巨大而凶猛的海怪——依沙瓦克。",al={"玛伦之后的下一个任务","玛伦给你什么"}}},fp="14,149,24.310.0,17.329.0,35.90.0,32.116.0,34.106.0,37.146.0,41.126.0,40.140.0"}
P.entries["quest:8742"] = {n="卡利姆多的威力",s="阿纳克洛斯以命运等待了千年的勇士之礼问候你，你是引领人民迈向新时代的领袖。这是流沙节杖任务线的终章，仅在完成蓝色、绿色和红色节杖碎片的所有任务线后才会开启。",h="阿纳克洛斯以命运等待了千年的勇士之礼问候你，你是引领人民迈向新时代的领袖。这是流沙节杖任务线的终章，仅在完成蓝色、绿色和红色节杖碎片的所有任务线后才会开启。",kw={"阿纳克洛斯","克苏恩","卡利姆多联军","节杖","流沙","希利苏斯","塔纳利斯"},sec={{t="古神在颤抖",b="阿纳克洛斯讲述了这段酝酿了千年的命运。古神因为你的到来而颤抖，并畏惧你的信念，阿纳克洛斯催促你去打破克苏恩的预言。你带来了卡利姆多联军的力量。当你准备好时，只需告诉阿纳克洛斯，他就会将流沙节杖交到你手中。"},{t="离别之言",b="阿纳克洛斯宣布节杖再次完整，并表示唯有你能挥舞它，引领你的人民走向未来的时代。甲虫之锣现在还不能敲响：首先部落和联盟的军队必须同时抵达希利苏斯。"}},faq={{q="谁提供了卡利姆多联军任务？",a="阿纳克洛斯。他只为那些完成了全部三条节杖碎片任务线（蓝色、绿色和红色）的勇士提供此任务。",al={"谁给予卡利姆多联军任务","阿纳克洛斯任务","谁给予节杖"}},{q="古神畏惧什么？",a="阿纳克洛斯说古神克苏恩因为你的到来而颤抖，并畏惧你的信念，并催促你去粉碎它的预言。",al={"哪个古神","谁畏惧卡利姆多联军","克苏恩预言"}},{q="这一步之前必须做什么？",a="必须先完成全部三条节杖碎片任务线：蓝色、绿色和红色。",al={"前置条件","卡利姆多联军的前置需求","节杖碎片任务线"}}},fp="21,274,20.314.0,16.251.1,33.113.0,27.123.0,35.76.0"}
P.entries["quest:87491"] = {n="Spark of Freedom",s="火元素的表演以精疲力竭告终。它一直盯着黑铁矮人，其他人都庆幸它没有转而攻击他们。",h="火元素的表演以精疲力竭告终。它一直盯着黑铁矮人，其他人都庆幸它没有转而攻击他们。",kw={"黑铁矮人","火元素","烟火般的表演","自由的火花"},sec={{t="烈焰之后",b="旁观者惊叹于这场表演，也庆幸火元素已经精疲力竭。黑铁矮人吸引了它的注意；如果它转而攻击，团队中的其他人也可能陷入危险。"}},faq={{q="火元素怎么了？",a="火元素施展了一番烟火般的表演后，精疲力竭。",al={"火元素","元素精疲力竭","这里发生了什么"}},{q="元素在追击谁？",a="火元素一直在追击黑铁矮人。",al={"黑铁矮人是目标","元素与黑铁矮人","它在攻击谁"}},{q="旁观者为什么松了口气？",a="旁观者庆幸元素没有转而攻击团队中的其他人。",al={"为何庆幸","元素带来的危险","它会攻击我们吗"}}},fp="16,161,16.226.0,36.69.0,34.55.0,29.85.0"}
P.entries["quest:875"] = {n="鹰身人首领",s="“鹰身人中尉”是部落的一项任务，由十字路口的达索克·快刀指派。为了继续在贫瘠之地北部针对巫翼氏族的军事行动，勇士们被派往无水岭，去刺杀该鸟群的一线军官，并粉碎她们的指挥链。",h="“鹰身人中尉”是部落的一项任务，由十字路口的达索克·快刀指派。为了继续在贫瘠之地北部针对巫翼氏族的军事行动，勇士们被派往无水岭，去刺杀该鸟群的一线军官，并粉碎她们的指挥链。",kw={"贫瘠之地","十字路口","达索克·快刀","无水岭","鹰身人首领之戒","鹰身人中尉","瑟雷娜·血羽","巫翼屠戮者"},ang={["class:Rogue"]="达索克·快刀依赖针对高价值军官的外科手术式刺杀，而不是代价高昂的正面战争，这正好发挥了潜行者的专长。",["faction:Horde"]="确保贫瘠之地北部通道的安全，对于在杜隆塔尔、莫高雷和灰谷伐木场之间建立稳定的联络线至关重要。"},sec={{t="瞄准军官",b="在与普通的巫翼掠夺者进行初步交锋后，达索克·快刀升级了对盘踞在无水岭的鹰身人的攻势。达索克没有继续削减普通兵力，而是指派部落侦察兵去针对担任中尉的巫翼屠戮者。这些军官维持着低阶鸟群的纪律，并协调对部落补给路线的袭击，因此清除她们对于确保贫瘠之地北部的通道安全至关重要。"},{t="军衔信物",b="由于巫翼屠戮者是通过野蛮的力量和统治地位来领导同类的，只有她们之中最凶残的成员才会佩戴象征其母系社会权力的华丽戒指。夺取这些戒指就是死亡的证明，不仅能瓦解鸟巢的战术协调，还能直接、无情地向该氏族传达一个信息：对部落领土的攻击将招致决定性的报复。"},{t="通往女族长之路",b="处决这些军官会使下层鸟群陷入混乱，但这有着更广泛的战略目的。剥夺巫翼鸟巢的现场指挥官，会削弱无水岭高地周围的防线，从而使她们的女族长瑟雷娜·血羽的内殿暴露无遗。"}},faq={{q="在哪里可以找到鹰身人中尉？",a="鹰身人中尉位于无水岭，这是贫瘠之地最北端的一片崎岖峡谷区域，在十字路口的西北方。寻找在该区域巡逻的巫翼屠戮者即可。",al={"中尉位置","巫翼屠戮者在哪里","鹰身人中尉戒指位置"}},{q="如何在鸟群中辨认这些中尉？",a="在巫翼氏族内，只有巫翼屠戮者担任中尉。她们携带着独特的鹰身人戒指，象征着她们对下级侦察兵和掠夺者的权威。",al={"哪些鹰身人有戒指","巫翼屠戮者辨认"}},{q="谁发布了这个悬赏？",a="驻扎在贫瘠之地十字路口的兽人侦察兵兼协调员达索克·快刀发布了这份契约，旨在保护部落利益并惩罚鹰身人的入侵。",al={"谁发布鹰身人中尉任务","达索克·快刀的职责"}},{q="为什么部落想要杀死中尉，而不是仅仅杀死普通的鹰身人？",a="中尉负责指挥下属并组织掠夺性袭击。消灭她们可以粉碎该母系社会的领导层，使剩下的鹰身人陷入混乱并变得脆弱。",al={"为什么要杀中尉","鹰身人指挥链"}},{q="消灭中尉后接下来要做什么？",a="一旦中尉被击杀，达索克·快刀会指引勇士们前往无水岭最高的悬崖之上，亲自猎杀该鸟群的女族长瑟雷娜·血羽。",al={"中尉任务后的后续任务","接下来做什么"}},{q="为什么巫翼鹰身人会对十字路口构成威胁？",a="巫翼氏族盘踞在贫瘠之地的北部山口，掠食试图在十字路口、杜隆塔尔和灰谷之间穿行的旅客、补给商队和巡逻队。",al={"为什么要与鹰身人战斗","巫翼威胁"}}},fp="17,169,22.342.0,14.311.0,23.253.1,38.141.0,53.126.0,23.197.0,80.169.0,45.165.1,57.181.0"}
P.entries["quest:876"] = {n="塞瑞娜·血羽",s="这项赏金任务要求部落的冒险者去击杀塞琳娜·血羽，她是主导鹰身人袭击十字路口补给线的女族长。她的行动是一场源于部落勇士雷克萨杀死了她姐姐的个人血仇。终结塞琳娜旨在瓦解贫瘠之地北部鹰身人群落背后的协同能力。",h="这项赏金任务要求部落的冒险者去击杀塞琳娜·血羽，她是主导鹰身人袭击十字路口补给线的女族长。她的行动是一场源于部落勇士雷克萨杀死了她姐姐的个人血仇。终结塞琳娜旨在瓦解贫瘠之地北部鹰身人群落背后的协同能力。",kw={"贫瘠之地","血羽","十字路口","达索克","鹰身人","雷克萨","塞琳娜","快刀"},ang={["class:Rogue"]="达索克·快刀崇尚冷酷的效率，要求利落地割开塞琳娜的喉咙，而不是进行一场漫长的混战。",["faction:Horde"]="经过十字路口的北部贸易路线对于补给兽人哨站以及连接杜隆塔尔与莫高雷和石爪山脉至关重要；镇压有组织的鹰身人掠夺者能保持这些动脉畅通。",["race:Orc"]="这场狩猎清算了源于雷克萨事迹的未竟之事，唤起了杜隆塔尔早期边疆斗争中那种激烈的精神。"},sec={{t="复仇的遗产",b="盘踞在十字路口西北部岩架上的女巫之翼鹰身人并非仅仅出于野兽般的饥饿而发起攻击。她们的首领塞琳娜·血羽对部落怀有明确的血海深仇。多年前在杜隆塔尔建国期间，流浪的兽王雷克萨击杀了塞琳娜的姐姐，一位臭名昭著的女族长，名叫血羽。塞琳娜因对新兴的部落充满仇恨，将她的族群集结成一股有组织的祸害，意图屠杀往来于干旱小径上的补给车队、斥候和商旅。"},{t="斩首行动",b="十字路口的达索克·快刀一直在监督对鹰身人的系统性清理，从清理小股掠夺者到资深副官。击杀塞琳娜标志着对这一威胁发动的最后决定性打击。达索克明确要求她的断头不仅作为任务完成的证明，更要作为战利品挂在下一支出发的商队上。通过在幸存的鹰身人面前高举她们女族长的头颅，部落希望以此震慑鹰身人群落，使其放弃对贫瘠之地生命线的袭击。"}},faq={{q="为什么塞琳娜·血羽要攻击部落商队？",a="塞琳娜寻求对部落的复仇。她的姐姐，鹰身人女族长血羽，在杜隆塔尔建国期间被兽王雷克萨所杀。塞琳娜指挥她的族群袭击部落的补给马车和旅行者，以此为她姐姐的死进行报复。",al={"鹰身人为何袭击商队","塞琳娜的动机","塞琳娜为何愤怒"}},{q="血羽是谁？",a="血羽曾是一位臭名昭著的鹰身人领袖，多年前曾恐吓杜隆塔尔和贫瘠之地的边境。雷克萨在服务于大酋长萨尔的旅途中猎杀了她。塞琳娜是她幸存的妹妹，继承了她的衣钵和仇恨。",al={"塞琳娜的姐姐","最初的血羽","雷克萨与血羽"}},{q="为什么达索克·快刀想要她的头颅？",a="除了确认她的死亡外，达索克打算将塞琳娜的断头挂在一辆即将出发的商队马车上。他相信展示这位女族长的下场将给任何企图袭击部落补给线的幸存鹰身人一个严厉的警告。",al={"达索克为何需要头颅","达索克·快刀的商队头颅"}},{q="在哪里可以找到塞琳娜·血羽？",a="塞琳娜在高耸的崎岖悬崖和十字路口西北部风蚀的岩架上筑巢，周围环绕着女巫之翼氏族的精英副官和卫兵。",al={"塞琳娜·血羽的位置","塞琳娜在哪里","塞琳娜刷新点"}},{q="击败塞琳娜后会发生什么？",a="随着鹰身人的威胁被消除，达索克会指派可靠的雇佣兵去协助其他有需要的盟友，并派遣他们带着一封信去找石爪山脉的巫医金吉尔。",al={"击败塞琳娜后做什么","塞琳娜之后的任务线"}},{q="谁发布了这项赏金任务？",a="达索克·快刀，一名驻扎在十字路口的兽人斥候和特工，负责监督对威胁贸易路线的野生威胁的镇压，并在其族群的底层成员被清理后发布了赏金。",al={"谁发布塞琳娜的任务","达索克的职责"}}},fp="19,292,21.385.0,20.342.1,52.196.0,21.202.0,42.171.0,39.142.0,38.174.1,25.206.0"}
P.entries["quest:877"] = {n="死水绿洲",s="“死水绿洲”是由塞纳里奥议会的德鲁伊图加·符文图腾在十字路口提供的一个调查任务。在遗忘之池有了发现之后，图加委托旅行者们去探索东南方的浑浊水域，以确定是否存在类似的地下裂隙。用干枯的种子测试这些神秘的能量，可以揭示在这片干旱大地之下涌动着一股深不可测且无法解释的力量。",h="“死水绿洲”是由塞纳里奥议会的德鲁伊图加·符文图腾在十字路口提供的一个调查任务。在遗忘之池有了发现之后，图加委托旅行者们去探索东南方的浑浊水域，以确定是否存在类似的地下裂隙。用干枯的种子测试这些神秘的能量，可以揭示在这片...",kw={"塞纳里奥议会","十字路口","干枯的种子","裂隙","遗忘之池","死水绿洲","贫瘠之地","图加·符文图腾"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊来说，用干枯的种子测试绿洲是一种调查隐藏力量是否正在让贫瘠之地恢复生机的方法。",["faction:Horde"]="确保并了解十字路口附近可靠的淡水绿洲，对于保护横跨贫瘠之地的贸易商队和军事哨所至关重要。",["race:Tauren"]="该任务直接体现了牛头人尊重大地母亲的职责，即去理解他们祖先狩猎场中自然平衡突然发生的深刻破坏。"},sec={{t="寻找隐藏的水源",b="在发现遗忘之池下方存在一条奇特的地下裂隙并不断翻涌后，图加·符文图腾怀疑整个贫瘠之地各地突然出现的茂密植被并非巧合。他派遣冒险者们前往东南方的死水绿洲，看看在它那浑浊且充满掠食者的浅滩之下，是否也存在类似的裂口。"},{t="生命之火",b="为了测试泉水的本质，图加提供了无法自然发芽的干枯且贫瘠的种子。将这些枯萎的种子直接浸入冒泡的裂隙中，触发了惊人的生长。在地下存在着能够赋予死物生命的活跃泉水，这证实了某种超自然力量正在主动重塑这片土地。"}},faq={{q="谁发布了“死水绿洲”这个任务？",a="该任务由十字路口的牛头人德鲁伊图加·符文图腾在调查完遗忘之池后立即发布，他驻扎在贫瘠之地的中部。",al={"任务发布者","如何领取","图加任务"}},{q="干枯的种子有什么作用？",a="图加提供了死去的、贫瘠的种子作为测试。他要求你把它们放在死水绿洲下方的任何裂隙中，看看泉水是否会有影响。",al={"干枯的种子","种子用途","种子测试"}},{q="死水绿洲在哪里？",a="死水绿洲位于贫瘠之地十字路口的东南方，坐落在岩石峭壁之间，那里居住着钳嘴龟、科卡尔半人马和水栖野兽。",al={"绿洲位置","死水绿洲在哪里","地图位置"}},{q="水下裂隙的意义是什么？",a="这些裂隙是绿洲水面下神秘的缝隙。图加怀疑它们可能是绿洲生命力的源泉，并要求旅行者们去验证这一可能性。",al={"绿洲裂隙","水下裂缝","冒泡的裂隙"}},{q="任务链的下一个任务是什么？",a="带着调查结果返回图加·符文图腾处，可以直接接到任务“变异的生物”，调查重点转向了池塘周围野生动物出现的变异和攻击性行为。",al={"后续任务","后续内容","死水绿洲之后"}},{q="为什么塞纳里奥议会对这些池塘感兴趣？",a="塞纳里奥德鲁伊们长期以来一直在寻求治愈贫瘠之地干燥草原的方法。发现能够自发产生生命的泉水固然令人兴奋，但这种现象的突然性和奇特性引起了人们对非自然或不稳定起源的担忧。",al={"为什么关注池塘","塞纳里奥的兴趣","德鲁伊绿洲"}}},fp="18,185,26.296.0,21.255.1,40.116.0,27.136.0,36.169.0,52.139.0,35.149.0,53.200.0"}
P.entries["quest:87760"] = {n="Holy Diver",s="一名达纳苏斯人请求你帮忙，阻止纳迦控制玛塞斯特拉废墟附近的海洋生物。找到他们的女驯兽师，夺回用来奴役这些生物的工具。",h="一名达纳苏斯人请求你帮忙，阻止纳迦控制玛塞斯特拉废墟附近的海洋生物。找到他们的女驯兽师，夺回用来奴役这些生物的工具。",kw={"holy diver","纳迦","rod of deep dominion","玛塞斯特拉废墟","海洋生物","海龟","stormscale beastmistress","蛇颈龙"},sec={{t="女驯兽师的法杖",b="一名达纳苏斯人请你阻止玛塞斯特拉废墟中的纳迦，他们正在岸边捕捉蛇颈龙。动物样本表明，纳迦强迫海洋生物充当坐骑和驮兽。无法利用的生物则被赶走。找到Stormscale Beastmistress，带回她的Rod of Deep Dominion；在夺走法杖之前，这些生物仍受纳迦控制。"},{t="生灵的安宁",b="你在玛塞斯特拉废墟从纳迦手中夺得了Rod of Deep Dominion。那名达纳苏斯人说，这根法杖将被摧毁，让蛇颈龙和海龟能够安宁地生活。"}},faq={{q="纳迦在对海洋生物做什么？",a="纳迦强迫海洋生物充当坐骑和驮兽，并赶走那些无法利用的生物。",al={"纳迦与蛇颈龙","海洋生物坐骑","动物遭遇了什么"}},{q="纳迦部队在哪里？",a="纳迦在玛塞斯特拉废墟驻有部队。",al={"纳迦位置","mathystra纳迦","女驯兽师在哪里"}},{q="你要找谁？",a="那名达纳苏斯人指定的目标是一名Stormscale Beastmistress。",al={"女驯兽师","stormscale女性","谁持有法杖"}},{q="Rod of Deep Dominion是什么？",a="那是纳迦用来强迫海洋生物为他们效力的法杖。",al={"deep dominion法杖","纳迦的控制工具","法杖名称"}},{q="哪些生物受到了影响？",a="那名达纳苏斯人提到，法杖被摧毁后，蛇颈龙和海龟就能安宁地生活。",al={"蛇颈龙与海龟","处于危险中的动物","海洋生物"}}},fp="10,178,21.395.0,20.169.1,45.108.0,26.47.0,24.65.0,33.70.0,29.109.0"}
P.entries["quest:878"] = {n="野猪人的内战",s="“部落的战争”是一个部落任务，由被俘的野猪人碎牙在陶拉祖营地提供。碎牙被牛头人关在铁栏之后，为了换取自由（或更准确地说是利用情报交换），他提供了关于野猪人入侵的关键情报，以换取冒险者去屠杀敌对的刺鬃部族精神领袖。",h="“部落的战争”是一个部落任务，由被俘的野猪人碎牙在陶拉祖营地提供。碎牙被牛头人关在铁栏之后，为了换取自由（或更准确地说是利用情报交换），他提供了关于野猪人入侵的关键情报，以换取冒险者去屠杀敌对的刺鬃部族精神领袖。",kw={"贫瘠之地","刺鬃","陶拉祖营地","地卜师","碎牙","钢鬃","索克","荆棘织者","部落的战争","水语者"},ang={["class:Shaman"]="野猪人地卜师通过与古老灵魂绑定的原始契约来弯曲大地和岩石，向萨满祭司展示了一种粗糙却强大的元素崇拜扭曲形式。",["faction:Horde"]="陶拉祖营地周围环绕着敌对的灌木丛，任何让野蛮的野猪人派系互相残杀的机会，对部落的补给线来说都是一次战术上的胜利。",["race:Tauren"]="作为陶拉祖营地的管理者，牛头人容忍碎牙的存在仅仅是因为他的怨恨能为南部边境带来安全。"},sec={{t="囚犯的交易",b="被关在陶拉祖营地的钢鬃野猪人碎牙证明了，囚禁并不能消磨古老的仇恨。在贫瘠之地，两个主要的野猪人派系——钢鬃和刺鬃——长期以来一直在争夺地盘。当部落还在努力保障其定居点和补给线免受突袭时，碎牙提供了宝贵的信息，揭示了到底是谁在真正威胁索克的哨所——前提是部落的勇士必须先除掉刺鬃部族最受尊崇的施法者们。"},{t="瞄准地卜师",b="碎牙指引冒险者向北进军，打击刺鬃部族的神秘核心：他们的水语者、荆棘织者和地卜师。这两个部族都崇敬大地，并从他们半神始祖阿迦玛甘相关的古老魔法中汲取原始力量。通过消灭他们的施法者，部落对刺鬃部族的仪式力量造成了沉重打击，使他们容易受到钢鬃对手的攻击，并减轻了附近道路的压力。"},{t="苦涩的启示",b="当任务完成后，复仇并没有带给碎牙安宁。囚犯并没有为刺鬃部族的损失而庆祝，反而因为自己被遗弃而陷入狂怒。尽管他为了帮助自己的部族而在铁栏后策划了多次袭击，但钢鬃部族并没有派遣任何营救队伍前往陶拉祖营地。被抛弃和遗忘的碎牙将目光转向了野猪人更深层的秘密，打开了通往阿迦玛甘之血力量的道路。"}},faq={{q="为什么碎牙被关在陶拉祖营地的笼子里？",a="碎牙是一只被驻扎在陶拉祖营地的部落军队俘虏的钢鬃野猪人。牛头人将他囚禁起来，以防止突袭，并从他口中撬取有关南贫瘠之地野猪人入侵的情报。",al={"为什么碎牙被关在笼子里","谁俘虏了碎牙","碎牙的笼子"}},{q="钢鬃部族和刺鬃部族之间有什么血仇？",a="钢鬃和刺鬃是互为敌对的野猪人部族，为了贫瘠之地的领土、稀缺的水源和神圣的覆盖荆棘的土地而激烈竞争。尽管他们有着与巨猪阿迦玛甘相关的共同精神血统，但他们互相蔑视，并为了平原的统治权不断发生冲突。",al={"刺鬃与钢鬃","为什么野猪人互相争斗","野猪人战争"}},{q="为什么碎牙特别想要他们的精神领袖去死？",a="野猪人的战争严重依赖于他们与大地和鲜血魔法的联系。地卜师、荆棘织者和水语者维持着部族的生命，在战斗中召唤岩石和荆棘，并引导他们的战士。打击他们的施法者会摧毁他们的士气，并削弱他们的战斗力。",al={"为什么要杀地卜师","刺鬃施法者","水语者和荆棘织者"}},{q="索克是谁，为什么碎牙会提到他？",a="索克是一位兽人军官，负责监督部落在十字路口和整个贫瘠之地的行动与安全。他的部队面临着野猪人战团不断的压力，因此关于他们部族动向的情报变得极其宝贵。",al={"索克是谁","索克 陶拉祖营地","索克 部落"}},{q="完成这个任务后会发生什么？",a="由于对自己部族未能营救他感到愤恨，碎牙提出分享关于血岩碎片的秘密。这解锁了“阿迦玛甘的血岩碎片”任务，最终允许玩家用在野猪人身上找到的碎片换取各种部族精神祝福。",al={"部落的战争 后续任务","部落的战争解锁什么","碎牙任务后的下一个任务"}},{q="我在哪里可以找到刺鬃精神导师？",a="刺鬃水语者、荆棘织者和地卜师居住在陶拉祖营地以北的南贫瘠之地，那里是刺鬃部族占据的荆棘丛、营地和峡谷。",al={"刺鬃水语者位置","荆棘织者在哪里","刺鬃地卜师位置"}}},fp="13,205,20.377.0,26.370.0,18.359.1,52.185.0,59.271.0,68.205.0,51.216.0,41.229.1,46.164.0"}
P.entries["quest:879"] = {n="内奸",s="“内部的背叛”是碎牙提供的一项任务，他是一只被囚禁在陶拉祖营地牢笼里的野猪人。他被自己的族人唾弃并遗弃等死，碎牙一心想对那三名从剃刀沼泽走出并组织袭击贫瘠之地的刺鬃氏族督军进行血腥复仇。",h="“内部的背叛”是碎牙提供的一项任务，他是一只被囚禁在陶拉祖营地牢笼里的野猪人。他被自己的族人唾弃并遗弃等死，碎牙一心想对那三名从剃刀沼泽走出并组织袭击贫瘠之地的刺鬃氏族督军进行血腥复仇。",kw={"贫瘠之地","陶拉祖营地","剃刀沼泽","库兹","“兽人祸”洛克","碎牙","纳克","刺鬃","索克"},ang={["faction:Horde"]="阻止“兽人祸”洛克和他的同伙，可以直接打击那些应对南贫瘠之地各处部落商队和哨站所受残暴行径负责的领袖。",["race:Orc"]="督军洛克之所以被称为“兽人祸”，正是因为他杀戮该地区兽人旅行者的残暴手段和仇恨。",["race:Tauren"]="陶拉祖营地正位于刺鬃侵略最猖獗的南部走廊沿线，因此铲除这些督军对当地的安全至关重要。"},sec={{t="牢笼中的怨恨",b="碎牙这只野猪人被囚禁在陶拉祖营地的烈日下，备受煎熬，他对刺鬃族人已不再有任何忠诚。在战败后被抛弃，又面临着必然的死刑，他唯一还存有的野心就是向那些抛弃他的领袖复仇。为了实现这一目标，他向部落的旅行者们提供了关于造成平原上无情袭击的真正幕后黑手的关键情报。"},{t="剃刀沼泽的督军",b="当十字路口的部落领袖（如索克）都在为遏制持续不断的野猪人侵略而苦苦挣扎时，碎牙揭示了问题的核心：三名来自剃刀沼泽深处的资深指挥官。在强大的战士“兽人祸”洛克带领下，随行的还有追踪者纳克和施法者库兹，这三人从远在南方的营地指挥着刺鬃劫掠者。碎牙要求拿回他们的头颅，以证明在他自己走向终点前，那些背叛他的人已经倒下了。"}},faq={{q="为什么野猪人会帮助部落？",a="碎牙完全是出于复仇的动机，而不是出于对部落的友谊。他的同胞背弃了他，将他丢在陶拉祖营地的牢笼中等死。既然他自己的灭亡已不可避免，他很乐意帮助部落，仅仅是为了确保那些背叛他的人先死。",al={"为什么碎牙会帮助部落","碎牙的动机","为什么野猪人会背叛同胞"}},{q="纳克、库兹和“兽人祸”洛克是谁？",a="他们是三名杰出的刺鬃领袖，从剃刀沼泽中走出，在整个贫瘠之地组织袭击。“兽人祸”洛克是一位凶残的战士和领袖，随行的是追踪者纳克和施法者库兹。",al={"目标是谁","刺鬃领袖","“兽人祸”洛克的背景故事"}},{q="在哪里可以找到这三个目标？",a="他们的营地位于贫瘠之地的最南端，驻扎在靠近南部灌木丛边界的刺鬃领地内。",al={"“兽人祸”洛克在哪里","纳克和库兹在哪里","目标地点"}},{q="碎牙说索克错了是什么意思？",a="在十字路口负责防御的索克以为他知道是谁在指挥针对部落补给线的野猪人袭击。碎牙声称索克对真正的幕后黑手判断有误，并断言正是“兽人祸”洛克、纳克和库兹在策划这些毁灭性的攻击。",al={"索克的错误","索克哪里弄错了","索克和碎牙"}},{q="杀掉这些领袖真的能给刺鬃族带来和平吗？",a="碎牙吹嘘说，干掉这三人会让十字路口和贫瘠之地的大部分地区免受刺鬃袭击。虽然这粉碎了他们南部的直接领导层，但整个贫瘠之地根深蒂固的野猪人敌意远未平息。",al={"贫瘠之地会有和平吗","刺鬃族的终结","刺鬃族被打败了吗"}},{q="在此之后，碎牙会怎么样？",a="碎牙接受了自己被关在部落营地内必死无疑的命运。他不寻求逃跑或怜悯，只求在自己走向终点前，能亲眼看到那些背叛他的族人倒下，并以此为满足。",al={"碎牙会被释放吗","碎牙的命运","碎牙会被处决吗"}}},fp="20,196,18.300.0,25.416.0,36.183.0,34.215.0,34.113.0,51.201.0,64.224.0,39.201.0"}
P.entries["quest:88"] = {n="公主必须死！",s="“必须杀死公主！”是斯通菲尔德农场的斯通菲尔德妈妈在艾尔文森林南部发布的一项当地悬赏。她想要除掉“公主”，这是一头来自附近的布莱克威尔南瓜田、获得过大奖的巨大母猪，它不断地洗劫她珍贵的菜地。干掉这头横冲直撞的猪，能确保斯通菲尔德一家安稳地收获庄稼。",h="“必须杀死公主！”是斯通菲尔德农场的斯通菲尔德妈妈在艾尔文森林南部发布的一项当地悬赏。她想要除掉“公主”，这是一头来自附近的布莱克威尔南瓜田、获得过大奖的巨大母猪，它不断地洗劫她珍贵的菜地。干掉这头横冲直撞的猪，能确保斯...",kw={"野猪","布莱克威尔南瓜田","黄铜项圈","艾尔文","斯通菲尔德妈妈","公主","母猪","斯通菲尔德农场"},ang={["faction:Alliance"]="帮助像斯通菲尔德妈妈这样的当地农民处理横行的野兽，即使在王国正规军缺席的情况下，也能维持暴风城的南部粮仓正常运作。",["profession:Cooking"]="处理巨大的母猪“公主”是当地厨师中的传奇故事，因为艾尔文森林里超大的野猪能提供充足且丰盛的肉，非常适合在篝火上烧烤。"},sec={{t="对收成的威胁",b="斯通菲尔德农场非常依赖其农作物，但一种贪婪的威胁危及了他们的收成。公主是一头属于布莱克威尔家族的获奖名猪，由于它闯入斯通菲尔德的田地大肆吞食蔬菜，体型已经长得极为惊人。斯通菲尔德妈妈受够了这头厚颜无耻的猪，她希望在它毁掉整个季节的收成之前，将其除掉。"},{t="猪群随从",b="“公主”很少独自游荡。在马科伦农场东边的布莱克威尔南瓜田里，它总是被一群忠诚且具有防御性的野猪护卫包围着。要杀死这头巨大的母猪，需要先突破它的护卫，并取下它脖子上那条标志性的黄铜项圈，以证明这头贪吃的畜生再也不能骚扰斯通菲尔德的田地了。"}},faq={{q="公主是谁？",a="公主是一头属于布莱克威尔家族、获得过大奖的巨大母猪。它的体型变得如此庞大，主要是因为它总是溜到斯通菲尔德农场，大肆吞食斯通菲尔德妈妈珍贵的蔬菜作物。",al={"什么是公主","公主 艾尔文","猪公主是谁"}},{q="为什么斯通菲尔德妈妈想要杀死公主？",a="斯通菲尔德妈妈受够了公主闯进她的田地并吞食她的蔬菜。她担心这头巨大的母猪会在家庭收获之前吃光所有的作物，因此她雇佣旅行者杀死这头野兽，并带回它的黄铜项圈作为证据。",al={"为什么要杀公主","斯通菲尔德妈妈 猪 任务","为什么必须杀死公主"}},{q="在哪里可以找到公主？",a="公主住在布莱克威尔南瓜田，位于艾尔文森林的东南部，经过马科伦农场向东。它在废弃的南瓜地中游荡，身边有成群的野猪护卫。",al={"公主的位置","公主在哪里","公主刷新"}},{q="布莱克威尔南瓜田的主人是谁？",a="这片南瓜田属于布莱克威尔家族，他们是当地的农民，由于艾尔文森林南部的强盗活动和野兽入侵，他们的土地已经陷入困境。尽管他们疏于照料这片南瓜田，公主还是留了下来，吞食着剩下的残余物。",al={"布莱克威尔家族是谁","布莱克威尔农场背景","布莱克威尔庄园主人"}},{q="如何证明公主已经死了？",a="你在击败这头母猪后，必须从它脖子上取下黄铜项圈，并将其带回斯通菲尔德农场交给斯通菲尔德妈妈。",al={"公主的证明","公主任务物品","黄铜项圈"}},{q="公主是单独作战吗？",a="不是，公主有一群“猪群随从”，由防御性的野猪组成，它们会攻击任何试图猎杀这头名猪的人。",al={"公主的小怪","公主的随从","公主的护卫"}}},fx={f51dd6ea={q="黄铜项圈有什么用？",a="公主是一头珍贵的家养母猪，粗壮脖子上扣着的黄铜项圈就是它的标记。斯通菲尔德妈妈让你从它的尸体上扯下项圈带回来，作为确凿的证据，证明这头贪吃的野兽已经被杀死，再也不能糟蹋斯通菲尔德家的菜地。",al={"黄铜项圈的用途","为什么拿走公主的项圈","公主的项圈"}}},fp="18,236,23.222.0,21.259.0,16.173.0,44.223.0,28.175.0,37.255.0,34.110.0,26.118.0"}
P.entries["quest:880"] = {n="变异的生物",s="“变异生物”是一个部落的任务，由位于贫瘠之地十字路口的图加·符文图腾指派。在发现当地水源受到神秘裂隙影响后，图加委托冒险者从变异的鳄鱼身上收集甲壳，以调查这些不自然的水域如何影响当地野生动物。",h="“变异生物”是一个部落的任务，由位于贫瘠之地十字路口的图加·符文图腾指派。在发现当地水源受到神秘裂隙影响后，图加委托冒险者从变异的鳄鱼身上收集甲壳，以调查这些不自然的水域如何影响当地野生动物。",kw={"变异生物","变异的钳嘴龟壳","十字路口","甜水绿洲","鳄鱼","死水绿洲","贫瘠之地","图加·符文图腾"},ang={["class:Druid"]="对于德鲁伊来说，研究这些鳄鱼凸显了自然生命力与腐化变异之间脆弱的界限，提供了直面贫瘠之地地下潜伏干扰的第一线视角。",["faction:Horde"]="确保十字路口周围水源的安全和纯净，对于保护部落的心脏地带免受意外魔法危害至关重要。",["race:Tauren"]="大地之母的平衡在贫瘠之地受到严重的动摇，这使得图加·符文图腾的努力对于那些在祖先土地上寻求和谐的牛头人来说具有深远的意义。"},sec={{t="不自然的水域",b="贫瘠之地的干旱草原上点缀着几处肥沃的绿洲，然而它们的生命力并非完全自然。德鲁伊图加·符文图腾对这些水域的调查揭示了一些奇怪的地下裂隙，它们散发着奇异而强大的能量。由于怀疑有一股未知的能量源——无论是来自外部还是从地底深处涌出——正在改变生态系统，图加将注意力转向了在这些水池中饮水和栖息的生物。"},{t="甲壳中的迹象",b="为了衡量这些裂隙对生态的影响，图加指引猎人们前往甜水绿洲和死水绿洲。栖息在浅滩的本地鳄鱼通过进食和接触吸收了神秘的精华，导致它们的甲壳出现了明显的生物变异。通过检查这些变异的甲壳，图加希望在这些影响蔓延到整个卡利姆多之前，解读出究竟是什么魔法或自然干扰在影响着这片土地。"}},faq={{q="谁发放了“变异生物”任务？",a="该任务由位于贫瘠之地中部十字路口的牛头人德鲁伊图加·符文图腾发放。",al={"任务发布者","在哪里接取变异生物","谁开启变异生物"}},{q="为了完成这项任务需要猎杀哪些生物？",a="你需要猎杀栖息在贫瘠之地甜水绿洲和死水绿洲水域周围的绿洲鳄鱼。",al={"哪些怪物掉落甲壳","变异鳄鱼目标","击杀什么"}},{q="为什么鳄鱼会发生变异？",a="绿洲下方的神秘裂隙正在向水中渗入奇怪的能量。在水池中栖息或饮水的动物已经产生了变异，导致它们的甲壳发生了明显的变化。",al={"为什么鳄鱼会变异","是什么改变了乌龟","绿洲野兽出了什么问题"}},{q="甜水绿洲和死水绿洲在哪里？",a="两处绿洲都位于贫瘠之地十字路口的南面。死水绿洲坐落在东南方，靠近尘泥沼泽的边界；而甜水绿洲则位于西南方，靠近哀嚎洞穴的入口。",al={"贫瘠之地绿洲位置","甜水绿洲位置","死水绿洲位置"}},{q="完成“变异生物”后会发生什么？",a="图加·符文图腾意识到这个谜团不仅仅涉及简单的野生野兽，他指引冒险者将发现报告给更高级别的德鲁伊长者，并将他们引向哈缪尔·符文图腾或穆拉·符文图腾。",al={"变异生物后的下一个任务","任务链指向哪里","变异生物后续"}},{q="为什么图加·符文图腾要研究绿洲？",a="作为一名德鲁伊，图加试图了解贫瘠之地的自然平衡。绿洲周围突然出现的不自然生长暗示着地底深处有强大的力量在运作，德鲁伊们担心这会破坏脆弱的草原生态系统。",al={"图加·符文图腾的动机","为什么调查绿洲","贫瘠之地塞纳里奥议会"}}},fp="14,215,16.448.0,18.363.0,35.94.0,47.89.0,29.178.0,43.206.0,45.175.1,42.190.0"}
P.entries["quest:881"] = {n="埃其亚基",s="埃其亚基是一头传说中的白狮，潜伏在贫瘠之地北部，在牛头人中被尊称为“白雾”。通过十字路口的瑟格拉·黑棘，年轻的部落猎人们会被派去召唤这头顶级掠食者，并考验自己的实力。",h="埃其亚基是一头传说中的白狮，潜伏在贫瘠之地北部，在牛头人中被尊称为“白雾”。通过十字路口的瑟格拉·黑棘，年轻的部落猎人们会被派去召唤这头顶级掠食者，并考验自己的实力。",kw={"十字路口","埃其亚基","科多兽骨","草原狮","瑟格拉·黑棘","贫瘠之地","白雾"},ang={["class:Hunter"]="由于其独特的苍白皮毛和在草原野兽中流传的传奇名声，埃其亚基成为了漫步在贫瘠之地的有志猎人们对耐心与潜行能力的终极考验。",["faction:Horde"]="猎杀埃其亚基是十字路口年轻勇士的成人礼，用以证明他们在残酷的贫瘠之地野生动物面前的生存技能。",["race:Tauren"]="在牛头人文化中，作为“白雾”的埃其亚基具有神圣的意义，它是干净、无痛的杀戮的化身，也是大地母亲残酷平衡的典范。"},sec={{t="草原上的白雾",b="在牛头人语中，它被称为埃其亚基，意为“白雾”。这头白鬃狮子统治着中央平原的草原猫科动物。传说它潜行时悄无声息，就像掠过红土地的低矮晨雾一样。它的攻击极快，猎物往往来不及感到恐惧或痛苦就已丧命，因此当地猎人将它视为仁慈与迅捷死亡的化身。"},{t="号角的试炼",b="瑟格拉·黑棘是一位经验丰富的兽人萨满，她在十字路口训练初出茅庐的勇士。当学员们证明了自己有能力对抗较弱的草原猎食者后，她会指示他们去挑战这位兽王。猎人手持特制的号角，向东北方出发，穿过山脊，来到一处巨大的科多兽骨堆墓地。吹响号角即可直接挑战埃其亚基，将这头行踪诡秘的掠食者从藏身之处引出来，进行一场力量与智慧的决斗。"},{t="狮王的遗产",b="当埃其亚基的皮被带回时，瑟格拉会说它的狩猎生涯已经结束，但它的灵魂会与胜利者同在。她教导说，埃其亚基展现了微妙之中的力量以及仁慈之中的荣耀。"}},faq={{q="埃其亚基这个名字是什么意思？",a="在牛头人的语言中，埃其亚基翻译过来是“白雾”。这个名字是为了纪念它苍白的皮毛，以及它在平原上潜行时那种静谧如雾的隐秘。",al={"埃其亚基翻译","埃其亚基的意思","牛头人名字埃其亚基"}},{q="埃其亚基在哪里被召唤？",a="埃其亚基的巢穴位于十字路口东北方，越过山脊的地方。它栖息在一片巨大的科多兽骨堆中，只有使用瑟格拉·黑棘提供的号角进行召唤时，它才会现身。",al={"埃其亚基在哪里","埃其亚基位置","如何找到埃其亚基"}},{q="为什么埃其亚基被称为仁慈与死亡的化身？",a="在牛头人的狩猎传统中，它被视为仁慈与死亡，因为它的出击是瞬间完成的。它以致命的精确度和速度杀戮猎物，使受害者既不会经历漫长的痛苦，也不会感到恐惧。",al={"为什么是仁慈与死亡","埃其亚基背景故事"}},{q="是谁派遣猎人去寻找埃其亚基？",a="驻扎在十字路口的兽人萨满瑟格拉·黑棘会分配这项狩猎任务，以验证探险者是否理解作为一名真正掠食者所必需的微妙与平衡。",al={"谁给予埃其亚基任务","瑟格拉·黑棘任务"}},{q="埃其亚基被击杀后会发生什么？",a="瑟格拉会要求你将埃其亚基的皮带回十字路口给她，以此作为狩猎的证明。",al={"埃其亚基怎么了","埃其亚基之魂"}},{q="猎杀埃其亚基之后是什么？",a="一旦猎人证明了自己具备克服埃其亚基所需的耐心和致命技巧，瑟格拉·黑棘就会指引他们去挑战更凶猛的猎物：被称为镰爪龙的恶毒迅猛龙。",al={"埃其亚基之后的任务","埃其亚基之后做什么"}}},fp="9,174,25.320.0,21.426.0,17.192.1,34.134.0,28.164.0,51.148.0,34.138.0,38.106.0,35.154.0"}
P.entries["quest:882"] = {n="伊沙姆哈尔",s="伊沙姆哈尔是陶拉祖营地的乔恩·星眼布置的一项狩猎仪式。为了测试你的本领以及对大自然最致命掠食者的敬意，你需要诱捕并击杀贫瘠之地中最凶猛的sunscale raptor。",h="伊沙姆哈尔是陶拉祖营地的乔恩·星眼布置的一项狩猎仪式。为了测试你的本领以及对大自然最致命掠食者的敬意，你需要诱捕并击杀贫瘠之地中最凶猛的sunscale raptor。",kw={"陶拉祖营地","伊沙姆哈尔","乔恩·星眼","棘齿城","矛牙","赤鳞迅猛龙","贫瘠之地","斑马尸体"},ang={["class:Hunter"]="利用新鲜诱饵和地形引诱难以捉摸的顶级掠食者，代表了传统的潜行艺术，是对追踪大师的耐心和狡猾的尊重。",["faction:Horde"]="清除像伊沙姆哈尔这样的传奇威胁证明了新手的价值，同时也让棘齿城和陶拉祖之间的交通道路对于部落旅行者来说稍微安全了一些。",["race:Tauren"]="对于牛头人猎人来说，面对伊沙姆哈尔是关于平衡的重要一课，证明了夺走强大掠食者的生命需要具备控制你所继承的凶猛精神的纪律。"},sec={{t="Speartooth的本性",b="在贫瘠之地的掠食者中，sunscale raptor因其狡猾和凶残的群体战术而令人恐惧，但没有哪一只像伊沙姆哈尔那样令人胆寒。被称为Speartooth的它不仅仅是为了食物或领地而潜行于大草原。正如乔恩·星眼所解释的那样，伊沙姆哈尔的狩猎完全出于本能和激情——它杀戮仅仅因为杀戮是它的天性。面对这样的生物，考验的是猎人能否抵御纯粹、狂野且原始的恶意。"},{t="诱捕野兽",b="伊沙姆哈尔并不是那种随随便便就能在巢穴里碰见的猎物。为了引出这只巨大的迅猛龙，猎人必须模仿平原的自然节奏。乔恩指示挑战者猎杀一只新鲜的zhevra——这种迅猛龙最喜欢的猎物——并将尸体拖到棘齿城西北方的一棵枯树下。被干燥风中飘散的新鲜血液气味所吸引，伊沙姆哈尔会迅速现身，夺取猎物。"},{t="力量的重担",b="将伊沙姆哈尔的牙齿带回陶拉祖营地不仅仅是武力胜利的展示。乔恩·星眼将这个战利品视为一个深刻的精神里程碑。在牛头人的信仰中，战胜这样凶猛的顶级掠食者意味着吸收了它一部分原始的力量。随之而来的真正考验在于内心：带着节制、荣誉和克制来驾驭那种掠食性的力量，而不是屈服于盲目的嗜血欲望。"}},faq={{q="谁是伊沙姆哈尔？",a="被称为矛齿的伊沙姆哈尔是一只在贫瘠之地徘徊的异常凶猛的阳鳞迅猛龙。与仅仅受饥饿驱使的普通野兽不同，它的狩猎完全出于纯粹的掠食天性和激情。",al={"什么是伊沙姆哈尔","谁是矛齿","伊沙姆哈尔迅猛龙背景故事"}},{q="如何召唤伊沙姆哈尔？",a="必须使用刚杀死的猎物才能引出伊沙姆哈尔。你必须获得一具新鲜的斑马尸体，并将其挂在棘齿城（地精港口）西北方指定的一棵枯树上。气味会很快将其从藏身处引出。",al={"如何召唤伊沙姆哈尔","伊沙姆哈尔在哪里","诱饵伊沙姆哈尔"}},{q="这个任务在哪里开始和结束？",a="该任务由驻扎在南贫瘠之地陶拉祖营地的牛头人猎人乔恩·星眼发布。一旦伊沙姆哈尔被击杀，你需将它的牙齿带回营地交给乔恩。",al={"伊沙姆哈尔任务发布者","谁发布伊沙姆哈尔任务","在哪里交还伊沙姆哈尔任务"}},{q="为什么乔恩·星眼想要伊沙姆哈尔死？",a="乔恩并非出于恶意才寻求消灭它。相反，追踪并战胜伊沙姆哈尔是一场精神试炼，旨在考验猎人在面对大自然最原始的侵略性时的表现，并教导在继承这种凶猛力量时要懂得节制。",al={"为什么要杀死伊沙姆哈尔","乔恩·星眼的动机"}},{q="完成伊沙姆哈尔任务后会发生什么？",a="在伊沙姆哈尔一战中证明自己后，乔恩·星眼会引导你去面对破坏贫瘠之地平衡的更大威胁，继续执行涉及南方被激怒的雷霆蜥蜴的任务。",al={"伊沙姆哈尔之后的任务","迅猛龙任务之后的下一个任务"}},{q="这个任务如何融入瑟格拉·黑棘的任务链？",a="它是瑟格拉·黑棘在十字路口开启的伟大狩猎试炼的延续。在北部平原证明了自己的技能后，瑟格拉会将你派往南方的陶拉祖营地，去找乔恩·星眼面对顶级野兽。",al={"与瑟格拉·黑棘的联系","十字路口狩猎任务链"}}},fp="10,174,24.309.0,17.306.0,22.361.0,18.156.0,29.159.0,36.155.0,43.194.0,41.182.0,54.217.0"}
P.entries["quest:8827"] = {n="冬天的礼物",s="“冬幕节的礼物”是一个联盟方的节日引导任务，旨在庆祝铁炉堡的冬幕节。欢庆者和PX-238冬幕欢乐制造器操作员会敦促旅行者去拜访烟林牧场的摊位旁的冬天爷爷。在那里，在那棵宏伟的节日树下，节日的礼物正在等待着英勇的冒险者。",h="“冬幕节的礼物”是一个联盟方的节日引导任务，旨在庆祝铁炉堡的冬幕节。欢庆者和PX-238冬幕欢乐制造器操作员会敦促旅行者去拜访烟林牧场的摊位旁的冬天爷爷。在那里，在那棵宏伟的节日树下，节日的礼物正在等待着英勇的冒险者。",kw={"冬幕节","冬天爷爷","节日欢庆者","铁炉堡","烟林牧场","冬幕节的礼物","欢乐制造器操作员"},ang={["faction:Alliance"]="铁炉堡是冬日里所有联盟种族的宏伟聚集点，吸引着精灵、人类和侏儒来到温暖的矮人地下大厅分享节日欢乐。",["race:Dwarf"]="对于矮人来说，欢迎旅行者在大锻炉庆祝冬幕节，会带来欢快的歌声、温暖的炉火和冰冷的麦芽酒，让他们的山中家园充满生机。",["race:Gnome"]="侏儒技师们对这个季节带来的巧妙节日装置赞叹不已，比如遍布全城的PX-238冬幕欢乐制造器。"},sec={{t="欢乐的季节",b="随着寒冬降临卡兹莫丹的群峰，铁炉堡变身为联盟冬幕节庆祝活动的核心地带。城中的欢庆者和节日爱好者们散布着欢乐的气息，兴奋地引导路人前往烟林牧场商贩附近那棵装饰华丽的节日树。"},{t="烟林牧场与冬天爷爷",b="在慷慨分发包裹的背后，是烟林牧场的地精企业，他们与冬天爷爷本人建立了合作关系。当这位慈祥的人物用温暖的节日问候迎接访客时，地精商人们也不忘提醒快乐的礼物接收者，他们的节日点心和时令商品是送给亲朋好友的绝佳礼物。"}},faq={{q="谁指引我去和冬天爷爷谈话？",a="铁炉堡的节日欢庆者或是在PX-238冬幕欢乐制造器旁照料机器的操作员，都会邀请你去装饰树旁拜访冬天爷爷。",al={"任务发布者","谁开启冬幕节的礼物","谁给予任务"}},{q="我在铁炉堡哪里可以找到冬天爷爷？",a="他坐在铁炉堡节日树和烟林牧场商贩摊位旁边，欢迎所有联盟种族的节日访客。",al={"冬天爷爷在哪里","铁炉堡冬天爷爷位置","寻找冬天爷爷"}},{q="操作员提到的PX-238冬幕欢乐制造器是什么？",a="PX-238冬幕欢乐制造器是一项异想天开的节日发明，由地精操作员运营，可以将参加节日的冒险者暂时伪装成快乐的小节日帮手。",al={"px-238","冬幕欢乐制造器","欢乐制造器机器"}},{q="为什么烟林牧场会参与冬幕节？",a="烟林牧场是一家极具商业头脑的地精贸易组织，他们赞助了整个艾泽拉斯的时令点心、节日新奇小玩意和盛宴，将纯粹的节日精神与有利可图的时令商业结合在了一起。",al={"烟林牧场的作用","为什么地精参与冬幕节","地精节日"}},{q="部落玩家可以做这个任务吗？",a="不，这个特定的邀请纯粹是为铁炉堡的联盟玩家准备的。部落在奥格瑞玛有他们在冬天爷爷指导下进行的冬幕节习俗。",al={"这是联盟专属吗","部落的冬幕节礼物","部落可以交这个任务吗"}},{q="和冬天爷爷谈话后会发生什么？",a="冬天爷爷会欢迎你，确认他没有忘记你，并鼓励你去查看放置在周围节日树下的彩色包裹。",al={"接下来做什么","打开礼物","任务交付后"}}},fx={c93f10ff={q="欢乐制造器操作员和节日爱好者为什么让你去找冬天爷爷？",a="他们只是希望你也能分享冬幕节的欢乐。冬天爷爷已经来到铁炉堡，在烟林牧场的支持下，将礼物摆在了树下。虽然欢乐制造器操作员职责在身，必须看管PX-238冬幕欢乐制造器，无法离开岗位，但他们仍会提醒过往的人们，别错过节日庆典和等着他们的礼物。",al={"为何被派去找冬天爷爷","冬天爷爷的礼物任务缘由","节日爱好者动机"}}},fp="17,184,17.204.0,41.219.0,46.157.0,49.144.0,63.141.0,50.177.0,32.124.0,50.143.0"}
P.entries["quest:8828"] = {n="冬天的礼物",s="“冬幕节的礼物”是冬幕节期间向奥格瑞玛的冒险者发出的一项邀请。在节日组织者和地精装置操作员的引导下，部落英雄会被指引前往装饰一新的节日树下，拜访冬天爷爷并领取为您准备的礼物。",h="“冬幕节的礼物”是冬幕节期间向奥格瑞玛的冒险者发出的一项邀请。在节日组织者和地精装置操作员的引导下，部落英雄会被指引前往装饰一新的节日树下，拜访冬天爷爷并领取为您准备的礼物。",kw={"冬天爷爷","节日爱好者","奥格瑞玛","礼物","烟林牧场","冬幕节","冬幕节的礼物","奇幻变形操作员"},ang={["faction:Horde"]="对于部落来说，奥格瑞玛内热闹的节日营地提供了一个欢快、温暖的聚集点，让他们可以远离卡利姆多各地持续不断的边境冲突。",["race:Orc"]="即使在酋长那严肃的领地，兽人们也会暂停履行职责，在冬幕树的枝桠下共享冬日盛宴，享受节日的温暖。"},sec={{t="慷慨的季节",b="当岁末的寒风吹过杜隆塔尔，冬幕节给奥格瑞玛那坚硬的红石建筑带来了难得的平和与庆典时刻。来自烟林牧场的推广员和节日爱好者们，确保每一位在主城休憩的战士、猎人和流浪者都知道，装饰树下正有礼物在等着他们。"},{t="赞助者与小贩",b="冬天爷爷本人就坐在烟林牧场的市场摊位旁，被节日彩带和包装好的纸箱所环绕。虽然这位古老的人物象征着季节的更替，但精明的地精商人们从不放过任何机会，提醒游客们节日气氛与他们储备的季节性商品和节日美食是绝配。"}},faq={{q="我该在哪里上交“冬幕节的礼物”？",a="你需要将此任务交给位于奥格瑞玛力量谷、靠近烟林牧场节日区域和装饰树旁的冬天爷爷。",al={"冬天爷爷在哪里","任务上交地点","礼物交还"}},{q="是谁指引你去见冬天爷爷的？",a="节日爱好者，或者是负责照看节日场地周围“PX-238型冬幕电光机”的地精奇幻变形操作员，都会指引你前往那棵大树。",al={"谁发布任务","任务起始人","节日爱好者"}},{q="烟林牧场是什么？",a="烟林牧场是一个充满进取心的地精商业组织，负责赞助和供应冬幕节期间各大主城的庆典活动、食物、点心和礼品。",al={"烟林牧场背景故事","烟林牧场是谁"}},{q="当你与冬天爷爷交谈时，他会做什么？",a="冬天爷爷会亲自欢迎你参加冬幕节，指引你前往大树下等待领取包裹，并热情地建议你查看烟林牧场的商品，为你的同伴挑选礼物。",al={"冬天爷爷问候语","任务完成对话"}},{q="为什么部落要在奥格瑞玛庆祝冬幕节？",a="虽然起源于古老的冬季复苏传说，但现代的冬幕节被部落视为一个休息、宴饮和团聚的时刻，以此缓解他们在卡利姆多建设新家园过程中的艰辛。",al={"部落冬幕节背景","为什么兽人庆祝冬幕节"}},{q="操作员提到的“PX-238型冬幕电光机”是什么？",a="它是一个安置在节日场地附近、造型古怪的地精装置，可以将志愿者暂时变身为身着节日盛装的小帮手。",al={"冬幕电光机","px 238型电光机"}}},fp="17,179,20.324.0,27.230.0,37.125.0,41.152.0,27.151.0,57.185.0,54.199.0,63.156.0"}
P.entries["quest:883"] = {n="拉克塔曼尼",s="“拉阔塔玛尼”是一项狩猎仪式，其开端是获取拉阔塔玛尼的蹄子。拉阔塔玛尼是贫瘠之地上一头游荡的巨大科多兽。将这件战利品带给陶拉祖营地的乔恩·天视，不仅是对这头强大野兽灵魂的敬意，也标志着猎人已拥有了与其雷霆之力相匹敌的实力。",h="“拉阔塔玛尼”是一项狩猎仪式，其开端是获取拉阔塔玛尼的蹄子。拉阔塔玛尼是贫瘠之地上一头游荡的巨大科多兽。将这件战利品带给陶拉祖营地的乔恩·天视，不仅是对这头强大野兽灵魂的敬意，也标志着猎人已拥有了与其雷霆之力相匹敌的实力...",kw={"陶拉祖营地","震地者","拉阔塔玛尼之蹄","乔恩·天视","科多兽","拉阔塔玛尼","贫瘠之地"},ang={["class:Hunter"]="在这片辽阔的大草原上追踪一头传说中的独行科多兽，是对追踪能力、耐力以及在卡利姆多中心地带进行野外战斗的终极考验。",["faction:Horde"]="陶拉祖营地是部落重要的狩猎枢纽，获取平原上的战利品有助于你在各个部落间建立声望。",["race:Tauren"]="对于牛头人猎人来说，击败拉阔塔玛尼实现了古老的狩猎传统，赢得了精神上的敬畏，并获得了长者们授予的“震地者”这一崇高头衔。"},sec={{t="震地者",b="在牛头人语中，拉阔塔玛尼意为“震地者”。在贫瘠之地那被烈日炙烤的平原上漫步的兽群中，它是独一无二的——那是一头体型巨大且耐力惊人的科多兽，它的脚步声如同汇聚的雷鸣。对于牛头人猎人来说，追踪并击败这样的生物并非肆意杀戮，而是一种与卡利姆多野生动物原始生命力的神圣交流。"},{t="陶拉祖营地的狩猎荣誉",b="将这头倒下野兽的蹄子带给陶拉祖营地的乔恩·天视，为这场狩猎画上了圆满的灵性句号。乔恩会立刻察觉到这种变化，他能感受到任何从这次遭遇中归来的猎人身上那股崭新的力量与步伐。通过呈上这件战利品，猎人会获得乔恩的祝福，这代表拉阔塔玛尼那不朽的勇气与原始之魂已与他们同行。"}},faq={{q="“拉阔塔玛尼”这个名字是什么意思？",a="根据乔恩·天视的说法，在牛头人语中，拉阔塔玛尼意为“震地者”。这个名字反映了这头野兽巨大的体型，以及它那如同汇聚的雷鸣般响彻平原的脚步声。",al={"拉阔塔玛尼的含义","拉阔塔玛尼翻译","拉阔塔玛尼在牛头人语中是什么意思"}},{q="乔恩·天视是谁？",a="乔恩·天视是一位牛头人精神向导与长者，居住在南贫瘠之地的陶拉祖营地。他负责解读预兆、指导年轻猎人，并向在平原上被猎杀的伟大野兽致敬。",al={"乔恩是谁","乔恩·天视的角色","乔恩·天视在哪里"}},{q="为什么牛头人要收集伟大野兽的蹄子？",a="对于牛头人来说，从像拉阔塔玛尼这样的野兽身上取下的蹄子，是该生物巨大力量的实体象征。将其呈献给长者，可以让这头倒下野兽的灵魂与坚韧得到正式的认可，并与猎人自身的灵魂相连。",al={"为什么要拿蹄子","拉阔塔玛尼之蹄的意义","科多兽蹄战利品"}},{q="野兽拉阔塔玛尼在哪里游荡？",a="拉阔塔玛尼在贫瘠之地中部和南部的开阔大草原上游荡，混迹于较小的科多兽群中，直到被细心的猎人追踪到。",al={"拉阔塔玛尼在哪里","拉阔塔玛尼位置","如何找到拉阔塔玛尼"}},{q="为什么乔恩称呼猎人为“震地者”？",a="乔恩·天视认为，击败拉阔塔玛尼将使这头野兽的灵魂与勇气永久融入猎人自身。通过战胜“震地者”，猎人继承了这个名字，并带着同样如雷霆般的决心前行。",al={"为什么我被称为震地者","震地者头衔背景"}},{q="这项狩猎在陶拉祖营地之外还有精神上的意义吗？",a="有的。它反映了牛头人对大地母亲与自然平衡的基本信仰。猎人证明自己的强大并非通过支配自然，而是通过挑战自然界中最伟大的化身，并将它们的力量融入到未来的战斗中来考验自己。",al={"拉阔塔玛尼的精神意义","这是牛头人的仪式吗"}}},fp="11,169,15.329.0,30.287.0,36.144.0,20.182.0,49.167.0,38.135.0,44.208.0,63.227.0"}
P.entries["quest:884"] = {n="奥瓦坦卡",s="奥瓦坦卡是牛头人眼中被称为“蓝电”的传奇雷蜥，游荡在贫瘠之地的南部平原。击败这头迅捷而带电的野兽，可以获得一根奥瓦坦卡的尾刺，上面附着着狂暴的雷电，需要交给营地的长者。将这个战利品交给陶拉祖营地的乔恩·天眼，以践行向卡利姆多的原生野兽学习的传统。",h="奥瓦坦卡是牛头人眼中被称为“蓝电”的传奇雷蜥，游荡在贫瘠之地的南部平原。击败这头迅捷而带电的野兽，可以获得一根奥瓦坦卡的尾刺，上面附着着狂暴的雷电，需要交给营地的长者。将这个战利品交给陶拉祖营地的乔恩·天眼，以践行向卡利...",kw={"贫瘠之地","蓝电","陶拉祖营地","乔恩·天眼","奥瓦坦卡","尾刺","雷蜥"},ang={["class:Hunter"]="战胜奥瓦坦卡是是对追踪技巧和速度的顶尖考验，证明了一名猎人可以跑赢并战胜自然界中最迅捷的巨人。",["class:Shaman"]="奥瓦坦卡的尾刺中束缚的残留闪电，证明了天空的元素力量是如何永远重塑卡利姆多的生物的。",["faction:Horde"]="猎杀这样一只不可预测、充满闪电电荷的顶级掠食者，可以保护陶拉祖营地附近脆弱的补给路线。",["race:Tauren"]="猎杀“蓝电”是对牛头人古老传统——即尊重野性精神并夺取贫瘠之地最持久野兽的生命力——的践行。"},sec={{t="名为蓝电的野兽",b="在南贫瘠之地干旱的广袤土地上，游荡着奥瓦坦卡，这是一头牛头人猎人怀着崇敬之心谈论的稀有雷蜥。虽然他的同类大多体型庞大且行动迟缓，但奥瓦坦卡却拥有突如其来的惊人速度。牛头人称他为“蓝电”，标志着他是一头被风暴彻底改变的生物。"},{t="受天空之怒滋养",b="根据乔恩·天眼保存的传说，奥瓦坦卡在很久以前曾被闪电直接击中。这头雷蜥非但没有死亡，反而吸收了天界的打击，成为了无尽能量之怒的源泉。即使在死后，当触碰这头生物的尾刺时，它依然会剧烈地迸发出零星火花，这是风暴力量留下的触觉残留。"},{t="陶拉祖的战利品",b="将奥瓦坦卡的尾刺带回陶拉祖营地，被视为一种勇武与精神的仪式。乔恩·天眼在任何设法战胜了这头野兽速度的猎人眼中，都能立即认出这种遭遇的印记。猎人在献上战利品时，象征性地汲取了“蓝电”那持久的速度。"}},faq={{q="奥瓦坦卡是什么？",a="奥瓦坦卡是贫瘠之地本土的一种传奇雷蜥。他被当地的牛头人称为“蓝电”，以其非凡的速度和噼啪作响的闪电能量而闻名。",al={"奥瓦坦卡是谁","奥瓦坦卡是什么野兽","奥瓦坦卡背景故事"}},{q="为什么奥瓦坦卡会闪烁着闪电？",a="牛头人传说认为，奥瓦坦卡在遥远的过去曾被闪电击中。这次打击没有杀死他，反而使这头生物获得了直接来自天空的无尽能量与狂怒。",al={"为什么奥瓦坦卡带电","蓝电背景故事","为什么会有火花"}},{q="乔恩·天眼是谁？",a="乔恩·天眼是一位牛头人长者，也是居住在南贫瘠之地陶拉祖营地的精神向导。他能够识别该地区大型野兽的潜能，并接受奥瓦坦卡的尾刺之类的战利品。",al={"奥瓦坦卡在哪里交任务","乔恩是谁","陶拉祖营地任务发放者"}},{q="奥瓦坦卡在哪里游荡？",a="奥瓦坦卡在南贫瘠之地的干旱平原上游荡，通常穿行于陶拉祖营地南部的灌木丛和土路上。",al={"奥瓦坦卡位置","奥瓦坦卡在哪里","去哪里找蓝电"}},{q="上交奥瓦坦卡的尾刺会发生什么？",a="乔恩·天眼会称赞你战胜了这头迅捷的雷蜥，并指出与这样的生物周旋，会在猎人内心留下持久的能量与力量火花。",al={"奥瓦坦卡任务上交","乔恩说了什么","奥瓦坦卡奖励背景"}},{q="与普通的雷蜥相比，奥瓦坦卡更危险吗？",a="是的。除了雷蜥的标准硬度外，奥瓦坦卡还拥有极具欺骗性的敏捷，以及源自他那传说中闪电打击的先天电力。",al={"奥瓦坦卡难打吗","蓝电的危险性","奥瓦坦卡战斗"}}},fp="8,243,25.163.0,21.230.0,17.258.0,17.120.0,39.111.0,20.197.0,27.115.0,51.157.0,57.141.0"}
P.entries["quest:8846"] = {n="五枚荣誉徽章换取物资",s="铁炉堡的大元帅斯诺·落雪负责监督大联盟战争物资和装备的收集工作。贡献物资的勇士可以直接用他们的嘉奖印章换取战地口粮、绷带和关键的作战物资。这能确保在后方辛勤工作的人们为即将到来的冲突做好准备。",h="铁炉堡的大元帅斯诺·落雪负责监督大联盟战争物资和装备的收集工作。贡献物资的勇士可以直接用他们的嘉奖印章换取战地口粮、绷带和关键的作战物资。这能确保在后方辛勤工作的人们为即将到来的冲突做好准备。",kw={"嘉奖","铁炉堡","军需物资","口粮","印章","落雪","战争补给"},ang={["faction:Alliance"]="这项后勤征用任务是为准备在艾泽拉斯各地进行重大战役的联盟勇士提供的直接生命线，确保部队有足够的绷带和口粮。",["race:Dwarf"]="这座熙熙攘攘的熔炉之城作为联盟的分配中心，矮人守卫们为能看到他们的大厅武装起所有的盟友种族而感到自豪。"},sec={{t="前线补给",b="大规模的军队集结需要的不仅仅是勇气，更需要持之以恒的后勤保障。大元帅斯诺·落雪作为联盟在铁炉堡的主要军需官之一，负责组织运往各个前线的物资流向。当信使和英雄们交出通过公民服务获得的嘉奖印章时，斯诺·落雪会直接以生存口粮和战术物资作为交换。"},{t="务实的交易",b="虽然嘉奖印章通常被上交给皇家传令官以换取公众荣誉和公民地位，但斯诺·落雪提供了一种不讲排场的选择。用五个印章换取一份战地装备，既没有排场、荣耀，也没有官方认可。相反，它提供实实在在的救命物资，确保士兵和志愿者在开赴敌占区时能够生存下来。"}},faq={{q="大元帅斯诺·落雪是谁？",a="大元帅斯诺·落雪是一位驻扎在矮人主城铁炉堡的联盟高级军官。他的任务是收集原材料，并将物资分发给支援战争的士兵和冒险者。",al={"落雪 铁炉堡","大元帅斯诺·落雪","落雪是谁"}},{q="什么是联盟嘉奖印章？",a="联盟嘉奖印章是颁发给捐赠关键贸易物资、绷带、草药和矿石以支持联盟全面动员的公民和冒险者的官方代币。",al={"嘉奖印章","联盟印章","什么是印章"}},{q="为什么用印章换取补给而不是声望？",a="用印章兑换补给箱是绕过公民声望，转而换取即时、实用的资源。对于急需消耗品、口粮和战地绷带的前线战士来说，实用的装备往往比礼仪性的地位更重要。",al={"为什么要做这个任务","用印章换补给值得吗","落雪补给交易"}},{q="这种交换在哪里进行？",a="交换在铁炉堡进行，大元帅斯诺·落雪站在战争集结地和物资仓库附近，协调运往卡兹莫丹及其他地区的物资。",al={"落雪在哪里","任务地点","落雪铁炉堡位置"}},{q="我可以重复这种交换吗？",a="可以。只要你每次提供所需的五个嘉奖印章，大元帅斯诺·落雪就准备持续授权提供额外的补给包。",al={"这可以重复吗","我可以再做一次吗","上交更多印章"}},{q="上交这些物品能获得声望吗？",a="不能。大元帅斯诺·落雪明确警告说，直接用印章交易个人补给不会获得任何联盟阵营的公民认可或声望，因为其价值已通过实物返还。",al={"这给声望吗","铁炉堡声望印章","印章认可度"}}},fp="29,263,19.215.0,17.270.0,30.235.0,39.168.0,52.223.0,36.169.0,27.106.0,35.194.0"}
P.entries["quest:885"] = {n="瓦希塔帕恩",s="该任务始于从瓦希塔帕恩身上拾取的一根羽毛。它是一只稀有而受人敬仰的雷鹰，在南贫瘠之地的天空中盘旋。其羽毛散发着一种非自然的刺痛感，迫使猎人们将这件遗物带给陶拉祖营地的乔恩·星眼。对于牛头人来说，击杀这只传奇的鸟类不仅是一次简单的战利品狩猎，更是一场关于痛苦与遗憾的深刻精神试炼。",h="该任务始于从瓦希塔帕恩身上拾取的一根羽毛。它是一只稀有而受人敬仰的雷鹰，在南贫瘠之地的天空中盘旋。其羽毛散发着一种非自然的刺痛感，迫使猎人们将这件遗物带给陶拉祖营地的乔恩·星眼。对于牛头人来说，击杀这只传奇的鸟类不仅是一...",kw={"贫瘠之地","陶拉祖营地","羽毛","乔恩·星眼","灵魂之刺","牛头人语","雷鹰","瓦希塔帕恩"},ang={["class:Hunter"]="与瓦希塔帕恩的对峙挑战了猎人的动机，表明夺取一只野兽的生命所承载的重量远非仅仅是一件战利品。",["class:Shaman"]="雷鹰羽毛上挥之不去的空灵刺痛感揭示了荒野最原始的精神反馈，这种共鸣对于任何研究元素和谐的人来说都很清晰。",["faction:Horde"]="陶拉祖营地是部落的一个关键的精神和狩猎十字路口，引导年轻的战士们通过良心以及战斗技能的考验。",["race:Tauren"]="对于Shu'halo来说，夺走灵魂之刺的生命是关于尊重自然平衡的神圣一课，教导猎人们悔恨可以被锻造为内在的智慧。"},sec={{t="灵魂之刺",b="雷鹰是贫瘠之地难以捉摸的生物，被游牧部落视为带有迷信色彩的崇敬对象。其中，瓦希塔帕恩——在Taurahe语中意为“灵魂之刺”——占据着独特而宿命般的位置。与普通的猎物不同，它的死亡并非儿戏；萨满们低语道，击杀这样的生物所带来的预兆在胜利与不幸之间危险地摇摆。"},{t="遗憾的教训",b="击杀瓦希塔帕恩的猎人很快会发现，其掉落的羽毛在触碰时会产生一种刺痛且挥之不去的强烈不适感。当呈交给陶拉祖营地的乔恩·星眼时，这位预言者揭示说，这种疼痛并非物理毒素，而是遗憾带来的精神刺痛。夺走一个伟大的生命背负着沉重的负担，这次试炼旨在考问猎人是会屈服于悔恨的折磨，还是会将这种悲伤转化为持久的智慧。"}},faq={{q="瓦希塔帕恩是什么意思？",a="在牛头人使用的牛头人语中，瓦希塔帕恩的意思是“灵魂之刺”。这是给予一只雄伟、稀有的雷鹰的名字，它在南贫瘠之地的平原上空翱翔。",al={"瓦希塔帕恩的含义","瓦希塔帕恩是什么","牛头人语噬灵者含义"}},{q="为什么瓦希塔帕恩的羽毛会引起疼痛？",a="根据乔恩·星眼的说法，触碰羽毛时感到的刺痛代表了遗憾带来的剧烈阵痛。它体现了终结一个伟大的生命所带来的情感和精神代价。",al={"为什么羽毛会痛","瓦希塔帕恩的羽毛刺痛感"}},{q="我应该把瓦希塔帕恩的羽毛交给谁？",a="这根羽毛需要交给乔恩·星眼，一位居住在南贫瘠之地陶拉祖营地的牛头人长者。",al={"谁接受瓦希塔帕恩的羽毛","羽毛任务上交"}},{q="击杀雷鹰会带来什么预兆？",a="牛头人的传统认为，雷鹰的死亡预示着巨大的财富或巨大的厄运。然而，乔恩解释说瓦希塔帕恩是独特的：击杀它并不会自动导致这两种命运中的任何一种，而是让猎人从自己的悔恨中锻造出智慧。",al={"雷鹰预兆","杀雷鹰是不好的吗"}},{q="瓦希塔帕恩在哪里可以找到？",a="瓦希塔帕恩在南贫瘠之地的天空中徘徊，经常被发现盘旋在陶拉祖营地附近的稀树草原上。",al={"瓦希塔帕恩位置","噬灵者在哪里刷新"}},{q="击杀它之后，乔恩·星眼是怎么看你的？",a="乔恩并没有谴责你。相反，他观察到，忍受羽毛带来的疼痛证明你已经克服了你的遗憾，将精神上的悲伤转化为力量和深刻的理解。",al={"乔恩·星眼的反应","乔恩会生气吗"}}},fp="12,174,16.244.0,18.272.0,28.155.0,43.138.0,41.90.0,43.188.0,28.100.0,53.155.0"}
P.entries["quest:8851"] = {n="五部落荣誉徽章",s="“五枚徽记换军需”是督军格尔库克在奥格瑞玛协调的一项后勤物资交换。通过上交部落在大规模军事动员期间获得的表彰徽记，勇士们可以获得个人补给，以确保他们在即将到来的冲突中装备精良。",h="“五枚徽记换军需”是督军格尔库克在奥格瑞玛协调的一项后勤物资交换。通过上交部落在大规模军事动员期间获得的表彰徽记，勇士们可以获得个人补给，以确保他们在即将到来的冲突中装备精良。",kw={"表彰","格尔库克","军需物资","奥格瑞玛","征用","徽记","补给品","战争努力"},ang={["class:Warrior"]="对于那些比起礼节性认可更看重实用生存能力的前线战士来说，格尔库克的补给箱绝对值得他们积累的徽记。",["faction:Horde"]="在奥格瑞玛收集的每一个板条箱和包裹都确保了部落能够做好充分准备，应对地平线上潜伏的灾难性威胁。"},sec={{t="全大陆的努力",b="在整个卡利姆多，部落正在为一场大规模的战役筹集大量的原材料、军火和补给。当普通的采集者和商人们将一箱箱绷带、金属和草药运往城市中心时，军事监督员会发放表彰徽记以嘉奖他们的贡献。这些代币象征着对奥格瑞玛中心大道上堆积如山的战略储备的直接贡献。"},{t="前线物资",b="督军格尔库克深知，虽然为更大的战争努力收集补给至关重要，但单独的战士在开赴战场时也需要装备和补给来维持生命。通过这项征用，战士们可以放弃个人荣誉，将他们的表彰徽记交回战争机器，以换取适合野战的补给和剩余军需。"}},faq={{q="上交五枚徽记的目的是什么？",a="这可以让协助部落战争动员的士兵将他们获得的表彰代币直接兑换成个人生存装备和野外补给，而不是将其保留以换取政治认可。",al={"为什么上交5枚徽记","上交徽记的目的","上交5枚徽记能得到什么"}},{q="督军格尔库克是谁？",a="督军格尔库克是驻扎在奥格瑞玛的一名部落军事协调员，负责管理补给并为准备应对即将到来的冲突的战士们批准征用申请。",al={"格尔库克的身份","谁是格尔库克"}},{q="如何获得部落表彰徽记？",a="当冒险者向阵营的战争努力贡献原材料、食物、绷带和制作资源时，部落各地的军需官和后勤官员会颁发徽记。",al={"获取徽记","徽记从哪里来","表彰徽记来源"}},{q="这项征用可以重复进行吗？",a="是的。只要你继续运送所需的徽记批次来支援部队，督军格尔库克就愿意批准重复交换。",al={"可以重复吗","我可以再做一次吗"}},{q="为什么格尔库克说我不会因此获得认可？",a="将表彰徽记直接用于个人补给会消耗军需官的储备，而不是记录你的功绩，这意味着你放弃了正式的嘉奖，换取了直接且实用的野战物资。",al={"没有认可的含义","为什么没有声望"}},{q="这项交换在哪里进行？",a="征用事宜直接在奥格瑞玛处理，物资储备和后勤协调员都在那里聚集，为部落的战争努力做准备。",al={"这个任务在哪里","上交地点"}}},fp="29,186,23.327.0,27.317.0,47.181.0,23.127.0,45.172.0,33.118.0,67.199.0,36.109.0"}
P.entries["quest:8852"] = {n="十枚荣誉徽章换取物资",s="“十枚印记换军需”是督军格尔库克在奥格瑞玛协调的一项后勤交换活动。部落勇士可以用多余的嘉奖印记换取实用的战场装备和补给。虽然此举会放弃正式的荣誉和表彰，但这能直接为前线士兵武装好即将到来的冲突所需的物资。",h="“十枚印记换军需”是督军格尔库克在奥格瑞玛协调的一项后勤交换活动。部落勇士可以用多余的嘉奖印记换取实用的战场装备和补给。虽然此举会放弃正式的荣誉和表彰，但这能直接为前线士兵武装好即将到来的冲突所需的物资。",kw={"嘉奖","格尔库克","后勤","奥格瑞玛","印记","补给","战争努力","督军格尔库克"},ang={["class:Warrior"]="前线战士深知，冰冷的钢铁和充足的口粮与武力勇气一样，是赢得持久战争的可靠保障。",["faction:Horde"]="在奥格瑞玛收集的每一箱补给，都直接转化为部落应对即将来临的残酷战斗的战备力量。"},sec={{t="前线物资",b="随着部落动员军团备战，收集补给与集结战士同样至关重要。督军格尔库克负责精神谷的后勤工作，确保成箱的武器、口粮和盔甲运往前线。那些证明了自己贡献的人可以上交嘉奖印记，从军队储备中领取实用的装备。"},{t="生存至上，荣誉其次",b="部落嘉奖印记通常作为服役证明上交，能让士兵在领导层中获得声望和名望。直接用它们换取装备虽然放弃了这种正式表彰，但换来了实实在在的生存保障。格尔库克明白，一旦大军交战，多一袋补给或一件坚固的武器往往就是生与死的区别。"}},faq={{q="什么是部落嘉奖印记？",a="部落嘉奖印记是发给那些为部落战争动员收集关键原材料和资源的勇士的官方凭证。",al={"嘉奖印记","部落印记","战争印记"}},{q="督军格尔库克是谁？",a="督军格尔库克是驻扎在奥格瑞玛的一名部落后勤军官，负责收集战争资源并向动员部队分发战场补给。",al={"格尔库克","督军格尔库克位置","格尔库克是谁"}},{q="为什么要用印记换补给，而不是换取阵营声望？",a="用印记换取补给虽然牺牲了政治地位和正式表彰，但换来了实用的物品、绷带和装备，有助于在前线立即生存下来。",al={"印记与补给","为什么要补给","嘉奖奖励"}},{q="这个兑换可以重复吗？",a="是的。只要你有足够的嘉奖印记，督军格尔库克就会不断与你交换战场补给。",al={"是否可重复","重复印记","再次上交"}},{q="这个兑换在哪里进行？",a="兑换地点位于奥格瑞玛主城，这里是部落战争准备和物资储备的中心。",al={"印记上交地点","印记兑换位置","格尔库克位置"}},{q="部落在为什么样的战争做准备？",a="部落正在囤积大量的金属、布料、草药和口粮，以武装一支能够面对迫在眉睫的灾难性威胁的远征军。",al={"什么战争","为什么收集补给","战争努力"}}},fp="28,177,22.276.0,29.306.0,36.131.0,23.143.0,63.147.0,30.115.0,36.99.0,44.123.0"}
P.entries["quest:886"] = {n="贫瘠之地的绿洲",s="在雷霆崖的长者高地上，大德鲁伊哈缪尔·符文图腾察觉到一股不安的力量正在涌入贫瘠之地干涸的土壤。为了查明真相，他派遣了一些富有前途的旅者向东穿过莫高雷的门户，前往十字路口与他的族人图加·符文图腾会合。这次任务标志着对这片被太阳炙烤的平原上突然涌现的异常水源的调查正式开始。",h="在雷霆崖的长者高地上，大德鲁伊哈缪尔·符文图腾察觉到一股不安的力量正在涌入贫瘠之地干涸的土壤。为了查明真相，他派遣了一些富有前途的旅者向东穿过莫高雷的门户，前往十字路口与他的族人图加·符文图腾会合。这次任务标志着对这片被...",kw={"血蹄村","塞纳里奥议会","十字路口","长者高地","哈缪尔·符文图腾","莫高雷","绿洲","贫瘠之地","雷霆崖","图加·符文图腾"},ang={["class:Druid"]="作为哈缪尔·符文图腾门下的第一批学生，年轻的德鲁伊们受大德鲁伊之托，要倾听大地的低语，并治愈自然脆弱平衡中的伤口。",["faction:Horde"]="十字路口是连接部落西部据点与海岸的重要生命线，因此附近的任何魔法干扰都是一个深层的战略和精神问题。",["race:Tauren"]="对于第一次冒险走出莫高雷神圣草甸的牛头人来说，这项任务代表着他们的成年仪式，让他们承担起保护卡利姆多平衡的更广泛职责。"},sec={{t="干旱中的干扰",b="当莫高雷的平原在大地母亲的注视下繁荣生长时，东部的贫瘠之地却在广阔的稀树草原上保持着严酷、焦灼和干旱的状态，这种状况已经持续了数代。然而最近，在雷霆崖长者高地上冥想的牛头人德鲁伊们发现，干旱的平原深处有奇怪的能量流正在苏醒。生命在不该出现的地方萌动，塞纳里奥议会担心，造成这种能量涌动的力量可能会给这片土地及其生物带来隐藏的危险。"},{t="莫高雷以东",b="为了调查这些奇怪的现象，大德鲁伊哈缪尔·符文图腾派遣图加·符文图腾前往实地。哈缪尔意识到这片广袤的荒野对于一名调查者来说太过危险，于是他招募了离开莫高雷的旅者，让他们赶去追随图加。沿着道路向东穿过血蹄村，经过山口，就能直达十字路口——那是部落在贫瘠之地的尘土飞扬、熙熙攘攘的中心地带——图加正在那里等待答案。"}},faq={{q="哈缪尔·符文图腾为什么担心贫瘠之地？",a="哈缪尔和雷霆崖的德鲁伊们感觉到一股异常的力量正在渗入贫瘠之地的土壤中。在如此干旱、严酷的气候下，生命的突然加速生长表明地表之下有不同寻常的力量在运作。",al={"为什么贫瘠之地有绿洲","哈缪尔的担忧","为什么要派人去十字路口"}},{q="我可以在哪里找到图加·符文图腾？",a="图加·符文图腾驻扎在贫瘠之地中部的十字路口。要找到他，请沿着莫高雷主要的东向道路，进入贫瘠之地，然后沿着小径的北部分支走，直到到达该定居点。",al={"图加·符文图腾的位置","图加在哪里","图加十字路口"}},{q="这个任务只有牛头人才能接吗？",a="大德鲁伊哈缪尔·符文图腾主要向从莫高雷出来的旅者提供这个任务。不过，任何部落种族的冒险者都可以直接在十字路口与图加会面，协助调查那些绿洲。",al={"非牛头人能接贫瘠之地的绿洲任务吗","谁发布贫瘠之地的绿洲任务"}},{q="从血蹄村出发后的路尽头有什么？",a="离开血蹄村向东走，会穿过分隔莫高雷和贫瘠之地的山口。翻过群山后，在分叉路口向北转，就能安全穿过严酷的荒野到达十字路口。",al={"去十字路口的路","从莫高雷去贫瘠之地的路径"}},{q="哈缪尔感应到的奇怪力量是什么？",a="德鲁伊们感觉到魔法流正在这片以严重干旱闻名的沙漠景观中制造出郁郁葱葱、泉水滋润的绿洲。图加·符文图腾被派去查明这种生长究竟是福还是危险的腐化。",al={"贫瘠之地有什么力量","绿洲之谜","贫瘠之地的异常能量"}},{q="为什么贫瘠之地对年轻的冒险者来说如此危险？",a="贫瘠之地是一片广阔、充满掠食者的边境地带，到处都是迅猛龙、平原陆行鸟和敌对的半人马部族。哈缪尔警告旅者要严格遵守巡逻的贸易路线，以免被严酷的荒野所吞噬。",al={"贫瘠之地的危险","为什么要待在路上"}}},fx={caac276a={q="为什么大德鲁伊哈缪尔·符文图腾派你去，而不亲自前往？",a="作为大德鲁伊和雷霆崖牛头人德鲁伊的精神领袖，哈缪尔·符文图腾必须留在高地上引导同胞并为大酋长出谋划策。他已经派图加·符文图腾前往实地调查这些异象，但图加独自一人无法解开谜团。哈缪尔依靠你这样的能干新锐勇士，在广阔的世界中充当图加的耳目与双手。",al={"为什么派我去","为什么不亲自去","哈缪尔为什么需要我帮忙"}}},fp="17,231,28.323.0,19.357.0,52.189.0,33.151.0,39.164.0,58.151.0,42.183.0,66.185.0"}
P.entries["quest:8866"] = {n="铜须长者",s="铜须长者是春节期间在矮人的山中城市铁炉堡与铜须长者的邂逅。在这一祭祖庆典中向他表示敬意，可以获得智慧和他的嘉奖。这反映了卡兹莫丹的人民对自己先祖和悠久传承的深厚敬意。",h="铜须长者是春节期间在矮人的山中城市铁炉堡与铜须长者的邂逅。在这一祭祖庆典中向他表示敬意，可以获得智慧和他的嘉奖。这反映了卡兹莫丹的人民对自己先祖和悠久传承的深厚敬意。",kw={"先祖","铜须","先祖硬币","长者","铁炉堡","春节"},ang={["faction:Alliance"]="长者平静地居住在铁炉堡的首都内，欢迎那些希望在山下庆祝古老传统的联盟成员。",["faction:Horde"]="找到铜须长者意味着要深入铁炉堡防御森严的核心区域，需要潜行或勇气才能向他致意。",["race:Dwarf"]="对于矮人来说，向铜须长者致敬是与那些用石头和铁打造了他们山中王国的崇高先祖进行的直接交流。"},sec={{t="向山丘部族致敬",b="在春节期间，先祖之灵和受人尊敬的长者们会出现在艾泽拉斯各地，与向过去致敬的旅行者们分享他们的智慧。在铁炉堡，铜须长者象征着铜须部族坚韧不拔的精神。当寻求致意的冒险者们接近他时，他会流露出一种静谧的满足感，因为这片土地上的人们依然铭记并尊崇着古老种族的血脉。"},{t="先祖敬意的信物",b="这次邂逅不需要经历伟大的试炼或危险的远征，只需旅行者驻足，承认长者的存在并致以问候即可。作为回报，铜须长者会送上他的祝福并赠予一枚先祖硬币。这些神圣的节日信物是连接现代英雄与那些用石头和火焰锻造出卡兹莫丹的先辈之间鲜活纽带的实物见证。"}},faq={{q="谁是铜须长者？",a="铜须长者是一位在春节期间受到尊崇的矮人先祖，他位于铁炉堡的地下要塞内，迎接来访者并与他们共庆传承。",al={"铜须长者","谁是长者","铁炉堡长者"}},{q="尊崇铜须长者意味着什么？",a="向他致意是春节期间祭奠先祖的一种行为。他会称赞旅行者铭记艾泽拉斯早期种族的根源和古老的牺牲。",al={"为什么要尊崇铜须","铜须长者的目的"}},{q="铜须长者在铁炉堡的什么位置？",a="他位于铁炉堡内，那些探索这座山中城市、寻求节日长者并致以敬意的旅行者都可以找到他。",al={"铜须长者的位置","铜须长者在哪里","铁炉堡长者位置"}},{q="部落玩家可以与铜须长者交谈吗？",a="铜须长者会认可任何愿意向他致意的人，但部落的冒险者必须勇闯铁炉堡设防的深处，并避开矮人守卫才能找到他。",al={"部落可以做这个任务吗","部落与铜须长者"}},{q="长者会给予什么奖励？",a="他会献上先祖的祝福以及一枚节日硬币，作为善意的象征和尊崇古老先辈的证明。",al={"铜须长者奖励","他给什么信物"}},{q="这个任务涉及战斗吗？",a="与他交谈不需要战斗；只需恭敬地接近这位受人尊敬的长者即可，尽管旅途中身处敌对领地可能会带来危险。",al={"我必须战斗吗","铜须长者战斗"}}},fp="21,213,27.329.0,26.292.0,25.166.0,45.170.0,46.133.0,47.154.0,34.136.0,35.109.0"}
P.entries["quest:887"] = {n="南海海盗",s="南海海盗是棘齿城的加兹鲁维委托的一项入门级赏金任务，旨在削减当地的海盗活动。由于对海盗劫掠地精商船的行为感到愤怒，这位总工程师雇佣了冒险者，对位于镇子南面商旅海岸的南海海盗营地发起了突袭。",h="南海海盗是棘齿城的加兹鲁维委托的一项入门级赏金任务，旨在削减当地的海盗活动。由于对海盗劫掠地精商船的行为感到愤怒，这位总工程师雇佣了冒险者，对位于镇子南面商旅海岸的南海海盗营地发起了突袭。",kw={"贫瘠之地","强盗","炮手","海盗","加兹鲁维","格雷兹里克","棘齿城","南海","热砂港"},ang={["class:Rogue"]="南海海盗的营地充满了窃贼的机会，前提是你能够溜过他们警惕的哨兵和沉重的海岸火炮。",["faction:Horde"]="棘齿城是部落在卡利姆多的重要补给走廊；保持海上航线畅通，不受海上掠夺者的干扰，可以保护穿过贫瘠之地的补给线。"},sec={{t="加兹鲁维的心头大患",b="棘齿城是卡利姆多中部首屈一指的中立贸易港口，建立在往返于东部大陆和卡利姆多的商船络绎不绝的贸易之上。然而，南海海盗在商旅海岸以南直接建立了一个坚固的海滩营地。以此为据点，这些海盗盯上了进出港口的地精货船，不仅造成了巨额利润损失，还破坏了当地航道的稳定。"},{t="来自永望镇的怠慢",b="加兹鲁维的愤怒不仅源于海盗本身，也源于他对热砂港海军领导层无能的看法。尽管贸易亲王投入了巨额资金用于维持防御舰队，但格雷兹里克副海军上将却未能有效地监管这片水域。由于对永望镇缓慢的应对感到沮丧，加兹鲁维绕过海军渠道，转而雇佣独立的雇佣兵来削减海盗强盗和炮手的人数。"}},faq={{q="谁是南海海盗？",a="南海海盗是一个臭名昭著的海盗团体，活跃于南部大洋和无尽之海。在贫瘠之地，他们在棘齿城以南维持着一个武装滩头阵地，劫掠商船并掠夺运往卡利姆多的贸易货物。",al={"南海海盗","谁是南海海盗","海盗背景故事"}},{q="为什么加兹鲁维如此在意这些海盗？",a="加兹鲁维代表热砂港负责监管棘齿城。海盗们拦截或掠夺的每一艘商船，都直接减少了财团的收入，并损害了棘齿城作为安全贸易港湾的声誉。",al={"为什么加兹鲁维想要消灭海盗","加兹鲁维的动机","棘齿城海盗问题"}},{q="海盗营地在哪里？",a="南海海盗的营地位于棘齿城以南的海岸线上，坐落在商旅海岸。营地里有坚固的帐篷、搁浅的小艇，还有由南海炮手操纵的火炮阵地。",al={"南海强盗在哪里","炮手位置","海盗营地在哪里"}},{q="谁是格雷兹里克副海军上将？",a="格雷兹里克副海军上将是负责监管热砂港贸易舰队并保护其航道的军官。加兹鲁维认为他基本没有什么作为，因为猖獗的海盗活动就发生在贫瘠之地的海岸外。",al={"谁是格雷兹里克","格雷兹里克副海军上将背景故事","热砂港海军上将"}},{q="清理完营地后会发生什么？",a="削减营地的防御力量只能解决部分问题。一旦强盗和炮手被击溃，加兹鲁维就会着手追踪他们劫持的贵重货物，这直接引出了关于他丢失货物的调查。",al={"接下来做什么","南海海盗后续","丢失的货物"}},{q="南海海盗隶属于联盟还是部落？",a="不隶属于任何一方。南海海盗完全游离于两大阵营之外，无差别地劫掠联盟船只、部落补给船只以及中立的地精货船。",al={"海盗是部落吗","海盗是联盟吗","南海阵营"}}},fp="20,168,25.359.0,22.328.0,33.225.0,50.196.0,33.189.0,29.192.0,36.224.1,67.145.0"}
P.entries["quest:88756"] = {n="Bring Back a Bang",s="“Bring Back a Bang”是一个旨在寻回在当地建筑工地被窃的烈性炸药的任务。敌对的黑铁矮人将这些带有标记的炸药桶运往了东面的恶铁岭营地，如果任由其发展，将对该地区构成严重威胁。",h="“Bring Back a Bang”是一个旨在寻回在当地建筑工地被窃的烈性炸药的任务。敌对的黑铁矮人将这些带有标记的炸药桶运往了东面的恶铁岭营地，如果任由其发展，将对该地区构成严重威胁。",kw={"炸药","带回一声巨响","建筑工地","黑铁矮人","恶铁岭","被盗的炸药"},ang={["profession:Engineering"]="工程师们深知炸药和易燃化合物需要妥善存放，无人看管的炸药储备简直就是一场随时可能发生的灾难。",["race:Dwarf"]="矮人建筑工和挖掘工非常了解采矿炸药的破坏潜力，尤其是当这些东西落入他们那敌视一切的黑铁同族手中时。"},sec={{t="建筑工地的盗窃案",b="敌对的黑铁矮人在东面的恶铁岭建立了营地。他们趁着附近的建设工作之机，突袭了当地的建筑工地，劫走了重要的炸药，并将这些物资直接运回了他们的帐篷。"},{t="危险的炸药",b="落入居心叵测的黑铁矮人手中的炸药对周边土地构成了迫在眉睫的威胁。被盗的炸药桶上有明显的红色标记，以便与普通物资区分开来。在黑铁矮人将其用于破坏目的之前寻回这些炸药，是一项刻不容缓的任务。"}},faq={{q="谁偷走了炸药？",a="黑铁矮人突袭了附近的建筑工地，将炸药桶运到了东面恶铁岭的帐篷里。",al={"谁偷了炸药","谁拿走了木桶","被盗的炸药"}},{q="黑铁矮人把炸药桶带到了哪里？",a="被盗的炸药桶被运往了建立在恶铁岭各处的黑铁矮人营地。",al={"炸药在哪里","恶铁岭营地","被盗的炸药在哪里"}},{q="如何识别被盗的炸药？",a="被盗的建筑炸药可以通过桶身上涂绘的独特红色标记与普通木桶区分开来。",al={"木桶长什么样","如何识别炸药","有红色标记的木桶"}},{q="为什么要寻回这些炸药？",a="建筑工人无法承担材料损失，且让居心叵测的黑铁矮人掌握强力炸药，会对附近的所有人造成严重威胁。",al={"为什么要寻回炸药","黑铁矮人的威胁是什么","为什么要阻止黑铁矮人"}},{q="什么是恶铁岭？",a="恶铁岭位于当地工地的东面，现在已经布满了敌对的黑铁矮人营地。",al={"什么是恶铁岭","恶铁岭的背景知识"}},{q="黑铁矮人是谁？",a="黑铁矮人是一个阴险的矮人派系，因其恶意、黑暗魔法以及对同族和邻居的长期敌意而臭名昭著。",al={"黑铁矮人是谁","为什么黑铁矮人如此敌对"}}},fp="17,162,30.144.0,14.223.0,25.129.0,42.86.0,43.80.0,43.128.0,23.100.0,30.130.0"}
P.entries["quest:888"] = {n="被窃的货物",s="“被窃的战利品”结束了加兹鲁维为夺回被南海海盗在棘齿城海岸附近劫持的贵重货物所做的努力。这位地精首领并没有试图找回每一个丢失的板条箱，而是专注于两件至关重要的物品：一箱靴子以及完成他天文台建设所需的精致望远镜片。",h="“被窃的战利品”结束了加兹鲁维为夺回被南海海盗在棘齿城海岸附近劫持的贵重货物所做的努力。这位地精首领并没有试图找回每一个丢失的板条箱，而是专注于两件至关重要的物品：一箱靴子以及完成他天文台建设所需的精致望远镜片。",kw={"贫瘠之地","藏宝海湾","崔斯里克","加兹鲁维","棘齿城","南海海盗","被窃的战利品","望远镜片"},ang={["profession:Engineering"]="加兹鲁维的天文台项目突显了地精的精密光学技术，表明重型建筑和精致的玻璃工艺必须结合在一起，才能构建实用的沿海基础设施。",["profession:Tailoring"]="从藏宝海湾的崔斯里克一路进口靴子，展示了热砂港各地成品皮革和制鞋业广泛的贸易网络。"},sec={{t="海盗劫持",b="南海海盗长期以来一直骚扰着无尽之海的商路，但在棘齿城以南建立设防营地使他们与加兹鲁维发生了直接冲突。当开往该港口的商船遭到拦截和掠夺时，热砂港损失了相当多的物资。虽然优先级较低的货物可以作为常规航运风险注销，但高价值的特殊商品值得雇佣雇佣兵武力来攻破海盗据点。"},{t="遗失的部件",b="加兹鲁维的优先事项非常实际。其中一项是来自藏宝海湾的崔斯里克发出的重要的一箱靴子，当地劳工急需这些靴子。另一项则专业得多：为俯瞰棘齿城的显眼天文台塔设计的地面望远镜片。虽然它的双生镜片已通过杜隆塔尔的陆路商队安全抵达，但海运的那一半却在水上被抢走了。没有它，天文台就只剩下一个空架子。"}},faq={{q="为什么加兹鲁维如此看重这两件特定的物品？",a="加兹鲁维承认找回所有被劫货物是不可能的，但来自藏宝海湾崔斯里克的一箱靴子和望远镜片是不可替代的。靴子用于供应当地工人，而精密镜片则是完成俯瞰棘齿城的天文台所必需的。",al={"为什么需要靴子和镜片","加兹鲁维的物品","什么被偷了"}},{q="这两个天文台镜片来自哪里？",a="天文台需要两个镜片才能正常工作。较大的镜片通过经过杜隆塔尔的陆路商队安全抵达。较小的镜片通过海运，却在南海海盗于贫瘠之地海岸附近突袭船只时遭到拦截。",al={"望远镜片的来源","天文台镜片","加兹鲁维是如何获得镜片的"}},{q="崔斯里克是谁？",a="崔斯里克是一位在东部王国南部的藏宝海湾经营的地精鞋匠。在海盗拦截货船之前，他制作并寄出了发往棘齿城加兹鲁维手下的鞋类货物。",al={"藏宝海湾的崔斯里克","谁寄送了靴子","崔斯里克"}},{q="被窃物品藏在哪里？",a="一箱靴子和望远镜片都被藏在棘齿城以南、商旅海岸沿线的南海海盗营地中。",al={"靴子在哪里","海盗营地位置","镜片在哪里"}},{q="这个任务之后会发生什么？",a="“被窃的战利品”是这一特定南海海盗调查任务线的最后一章。一旦物品归还，加兹鲁维会表示感谢，称赞你的可靠性，并邀请你继续为他在棘齿城的商业企业工作。",al={"被窃的战利品后续","下一个任务","被窃的战利品之后是什么"}},{q="棘齿城为什么要建天文台？",a="地精工程学非常依赖于对周围陆地和海上航道的观察、导航和测绘。完成天文台塔可以让棘齿城的领导层监视临近的商船队、敌对船只以及商旅海岸上潜在的威胁。",al={"棘齿城望远镜","加兹鲁维的天文台","加兹鲁维为什么要望远镜"}}},fp="12,170,16.433.0,18.357.0,61.232.0,47.184.0,16.178.0,34.128.0,30.147.1,37.226.0"}
P.entries["quest:889"] = {n="风之魂",s="“风之灵魂”是由身陷囹圄的野猪人碎牙在陶拉祖营地提供的可重复仪式。通过引导阿迦玛甘血岩碎片中残留的力量，碎牙能使旅者获得迅捷，从而在广阔的贫瘠之地草原上快速穿行。",h="“风之灵魂”是由身陷囹圄的野猪人碎牙在陶拉祖营地提供的可重复仪式。通过引导阿迦玛甘血岩碎片中残留的力量，碎牙能使旅者获得迅捷，从而在广阔的贫瘠之地草原上快速穿行。",kw={"阿迦玛甘","贫瘠之地","血岩碎片","陶拉祖营地","碎牙","野猪人","速度","风之灵魂"},ang={["class:Druid"]="在贫瘠之地研究的德鲁伊常常发现，这些仪式中残留的荒野之神阿迦玛甘的力量，是一种迷人但又原始的自然本源体现。",["class:Shaman"]="通过结晶化的神圣精华与风之灵魂沟通，呼应了萨满教崇敬元素与先祖力量的传统。",["faction:Horde"]="陶拉祖营地的守卫密切看管着碎牙，但部落的侦察兵经常利用它对血岩碎片魔法的了解，以更快地穿越南部平原。"},sec={{t="血岩碎片的馈赠",b="在贫瘠之地干燥广袤的土地上，能否快速穿越开阔地带，往往决定了你是能幸存下来，还是会倒在掠食猛兽或游荡的半人马战团爪下。身陷陶拉祖营地的野猪人俘虏碎牙，深知散落在该地区各处的红色结晶体——血岩碎片中潜藏着力量。当交给它十块这样的遗物时，它会利用其原始的共鸣来赋予“风之灵魂”，给予旅者一阵疾驰的动力，以甩开平原上呼啸的风声。"},{t="阿迦玛甘的远古气息",b="野猪人的传统崇敬阿迦玛甘，这头巨猪在上古之战期间将自己的鲜血洒遍了卡利姆多中部。即使身处囚笼，碎牙依然保留着有关这位荒野之神仪式的精深知识。引导这位神灵洒下的鲜血不仅仅是改变肉体，更能激发出狂野的活力，让奔跑者拥有足以媲美疾驰斑马群的速度。尽管野猪人是部落的死敌，但碎牙仍然乐意向任何愿意用新鲜碎片来充当仪式燃料的人传授阿迦玛甘的恩泽。"}},faq={{q="什么是“风之灵魂”？",a="这是陶拉祖营地的碎牙提供的一种临时增益。用十块血岩碎片作为交换，它会赋予你更快的奔跑速度，帮助旅者穿越贫瘠之地。",al={"什么是风之灵魂","风之灵魂增益","碎牙速度增益"}},{q="谁提供了“风之灵魂”？",a="碎牙，一个被部落关押在陶拉祖营地的野猪人，一旦你赢得了它的合作，它就会为你执行仪式。",al={"谁提供风之灵魂","碎牙","谁用血岩碎片换取速度"}},{q="为什么碎牙需要血岩碎片？",a="血岩碎片是阿迦玛甘洒下的鲜血所形成的结晶碎片。碎牙利用储存在其中的这位远古半神潜藏的原始力量来编织它的各种恩泽。",al={"为什么需要血岩碎片","血岩碎片的用途","碎牙如何使用碎片"}},{q="我可以多次获得这个增益吗？",a="是的。只要你每次都给碎牙提供十块血岩碎片，当你回到它身边时，它就会反复为你引导这一增益。",al={"风之灵魂是否可重复","我可以重复完成这个任务吗","可重复增益"}},{q="为什么野猪人会帮助部落成员？",a="碎牙被囚禁在陶拉祖营地，它用自己掌握的有关阿迦玛甘魔法的先祖知识作为筹码来换取生存，因此与那些收集它所珍视的神圣碎片的旅者进行交易。",al={"为什么碎牙会提供帮助","友好的野猪人","为什么帮助部落"}},{q="这个增益持续多久？",a="碎牙提到，这种附魔持续的时间并不长，但在消散前，它提供的迅捷足以显著减轻穿越贫瘠之地的旅途负担。",al={"增益持续时间","风之灵魂持续时间","速度增益能持续多久"}}},fp="18,173,24.316.0,26.407.0,31.151.0,34.138.0,42.157.0,43.103.0,47.168.0,32.135.0"}
P.entries["quest:89"] = {n="止水湖上的桥",s="止水湖大桥重建工程由湖畔镇的工头奥斯洛负责，旨在修复该镇损毁的石桥。由于原本用于该项目的铁料在上一次兽人入侵期间被挪用去制造武器，而从暴风城派来的补给车队又遭到了赤脊山豺狼人的伏击，工程进度已陷入停滞。",h="止水湖大桥重建工程由湖畔镇的工头奥斯洛负责，旨在修复该镇损毁的石桥。由于原本用于该项目的铁料在上一次兽人入侵期间被挪用去制造武器，而从暴风城派来的补给车队又遭到了赤脊山豺狼人的伏击，工程进度已陷入停滞。",kw={"止水湖大桥","工头奥斯洛","铁桩","铁铆钉","湖畔镇","赤脊山","赤脊山豺狼人"},ang={["faction:Alliance"]="湖畔镇补给线的断绝是暴风城忽视其外围领地的又一个明显迹象，使得当地的工头不得不依赖雇佣兵来保障道路贸易的安全。",["profession:Blacksmithing"]="这一物资短缺凸显了湖畔镇守军当时的绝望境地：将结构性的铁桩和铆钉锻造成武器，是一种为了挽救生命而牺牲关键基础设施的孤注一掷的举措。"},sec={{t="孤立无援的城镇",b="横跨止水湖的石桥是湖畔镇的生命线，它连接着通往艾尔文森林的西部道路以及远处的河岸和北部山口。在近期的兽人入侵期间，该镇被逼到了灭亡的边缘。为了生存，湖畔镇将用于桥梁建设的铁料熔化，锻造成了军火、利刃和板甲，以抵御黑石氏族的入侵，这导致大桥工程半途而废，且疏于防范。"},{t="被窃取的物资",b="工头奥斯洛向暴风城贵族议会请愿，请求调拨新的建筑材料以完成修复工作。随后运载铁料的补给车队出发了，但却从未抵达。一支赤脊山豺狼人的战团在路上伏击了车队，将关键的铁桩和铆钉劫掠到了他们位于北部山丘的营地中。如果没有愿意冒险的旅行者出手夺回被盗的五金配件，桥梁工程将继续停滞不前，而豺狼人和兽人也将进一步加紧对群山的控制。"}},faq={{q="为什么止水湖大桥还没有完工？",a="湖畔镇为了在近期的兽人入侵中存活下来，不得不将建筑用的铁料熔化以制造武器、弹药和盔甲。随后从暴风城派出的补给运输队又遭到了当地豺狼人的伏击和洗劫，导致工头奥斯洛没有足够的材料来完成工作。",al={"桥梁为什么断了","谁破坏了止水湖大桥","湖畔镇大桥损坏"}},{q="工头奥斯洛是谁？",a="工头奥斯洛是负责监管止水湖大桥重建工作的总工程师。由于得不到暴风城首都的支援或材料，他只能指望路过的冒险者从山丘中找回被盗的建筑物资。",al={"工头奥斯洛","奥斯洛是谁"}},{q="是谁偷走了修桥的物资？",a="赤脊山豺狼人伏击了从暴风城出发的补给车队，并将铁桩和铆钉搬运到了湖畔镇后方山丘上的营地里。",al={"谁偷了铁铆钉","谁拿走了修桥的铁料"}},{q="为什么暴风城不派卫兵保护车队？",a="由于瓦里安·乌瑞恩国王失踪，暴风城贵族议会在很大程度上停止了对边远领地的军事援助。赤脊山只能依靠当地民兵，在几乎没有任何支援的情况下独自对抗豺狼人和黑石兽人。",al={"暴风城是否援助湖畔镇","为什么没有守卫"}},{q="为什么湖畔镇要熔化他们的铁料？",a="在上一次兽人入侵期间，湖畔镇的守军极其缺乏作战物资。为了在猛攻中幸存，该镇将库存的建筑用铁熔化，制成了盔甲、剑和弹药。",al={"为什么要熔化铁料","赤脊山兽人入侵"}},{q="修复大桥需要什么物资？",a="工头奥斯洛特别需要重型铁桩和铁铆钉，以加固和锚定横跨止水湖的桥梁跨度。",al={"修桥材料","奥斯洛需要什么"}}},fp="20,229,14.375.0,16.361.0,39.244.0,21.199.0,30.135.0,56.223.0,39.175.0,46.113.0"}
P.entries["quest:890"] = {n="丢失的货物",s="加兹鲁维正在等待一批从藏宝海湾横穿无尽之海运来的货物，但这批货物延误了。他怀疑是码头行政管理失误或是遭到了南海海盗的劫掠，于是派遣信使前往棘齿城的码头，去核对码头管理员迪兹维格的日志。",h="加兹鲁维正在等待一批从藏宝海湾横穿无尽之海运来的货物，但这批货物延误了。他怀疑是码头行政管理失误或是遭到了南海海盗的劫掠，于是派遣信使前往棘齿城的码头，去核对码头管理员迪兹维格的日志。",kw={"藏宝海湾","迪兹维格","崔斯里克","海盗","加兹鲁维","账本","棘齿城","货物"},ang={["faction:Horde"]="棘齿城保持中立立场，作为部落旅行者在卡利姆多和荆棘谷之间往来的重要港口，使得码头商业成为了共同利益所在。",["profession:Engineering"]="加兹鲁维对来自藏宝海湾的备件、异国进口商品和定制装备的持续需求，突显了在远离地精工业中心的地方维持棘齿城机械运转所面临的后勤困境。"},sec={{t="棘齿城的生命线",b="棘齿城作为热砂港在卡利姆多的商业桥头堡，一直以来都非常繁荣。船只定期横穿无尽之海从藏宝海湾往返，运载着为港口快速建设和贸易投资所需的制成品、异国补给和重型货物。当入港库存丢失时，就会扰乱首席工程师加兹鲁维的业务，因为他会仔细追踪进入港口的每一个板条箱。"},{t="核对货物",b="虽然南海海盗在镇子南边的海岸线上肆虐，并经常拦截商船，但加兹鲁维知道在查看自己的账本之前不能轻举妄动。在指控海盗或派遣雇佣兵进行冲突之前，他会将自己的个人库存记录直接发送给码头上的码头管理员迪兹维格。迪兹维格负责监管船只货物的实际卸载和储存，他是唯一一个能确定货物是在海上丢失还是仅仅在仓库中放错位置的地精。"}},faq={{q="丢失的货物里有什么？",a="虽然加兹鲁维泛指从藏宝海湾运来的重要物资，但码头管理员迪兹维格提到，这位首席工程师可能是在为崔斯里克定制的一批靴子而发愁。",al={"加兹鲁维的货物","什么被偷了","丢失的货物"}},{q="码头管理员迪兹维格是谁？",a="码头管理员迪兹维格负责监管棘齿城码头的进出港航运清单。他代表热砂港管理跨洋船只与当地仓库之间的货物转运。",al={"迪兹维格","迪兹维格是谁","棘齿城码头管理员"}},{q="为什么加兹鲁维怀疑南海海盗？",a="南海海盗在棘齿城南部的商旅海岸沿线建立了营地。他们经常掠夺卡利姆多和东部王国之间的贸易航线，每当商船货物失踪时，他们就是主要的怀疑对象。",al={"海盗的角色","海盗窃贼","为什么怀疑海盗"}},{q="货物是从哪里发出的？",a="这批货物来自藏宝海湾，这是位于东部王国荆棘谷南端的主要地精港口城市。",al={"货物来源","它是从哪来的","藏宝海湾的货物"}},{q="把账本交给迪兹维格之后会发生什么？",a="迪兹维格会将他的航运清单与加兹鲁维的账本进行核对，以确认货物是被错误地转运到了棘齿城的仓库中，还是在卸货前被劫持了。",al={"迪兹维格的后续行动","账本的后续处理"}},{q="为什么加兹鲁维不亲自去码头检查？",a="作为首席工程师和棘齿城的领导者，加兹鲁维在他的中心办公室负责城镇运营和扩张项目。他更喜欢花钱雇佣旅行的冒险者在定居点内跑腿处理文书工作。",al={"为什么要派我去","加兹鲁维的懒惰"}}},fp="20,215,24.296.0,27.381.0,32.152.0,28.176.0,50.206.0,33.116.0,49.146.0,44.173.0"}
P.entries["quest:891"] = {n="北方城堡的火炮",s="棘齿城的沙罗萨斯船长已经受够了他的商船被北方城堡的联盟炮手炸成碎片。他雇佣了部落的勇士沿着商旅海岸进军，肃清该要塞的炮兵军官，并夺取他们阵亡步兵的徽章。",h="棘齿城的沙罗萨斯船长已经受够了他的商船被北方城堡的联盟炮手炸成碎片。他雇佣了部落的勇士沿着商旅海岸进军，肃清该要塞的炮兵军官，并夺取他们阵亡步兵的徽章。",kw={"贫瘠之地","沙罗萨斯","火炮","法尔茅斯","商旅海岸","北方城堡","棘齿城","斯麦斯","塞拉摩","韦森"},ang={["faction:Horde"]="直接打击北方城堡可以瓦解一座侵犯贫瘠之地的激进联盟防御工事，为部落巩固卡利姆多的边境。",["race:Human"]="北方城堡所陷入的悲剧性偏执揭示了塞拉摩边境驻军所面临的压力，他们远离家园，孤立无援，且容易陷入鲁莽的敌对状态。"},sec={{t="海岸边的威胁",b="北方城堡矗立在贫瘠之地的南海岸，是塞拉摩人类建立的坚固堡垒。虽然其目的是为了保卫联盟的利益并监视卡利姆多的部落活动，但驻守其中的士兵已经陷入了严重的偏执之中。他们将任何陌生的船只都视为敌对目标，城墙上的炮台不加分辨地开火，威胁到了和平的商船运输以及棘齿城的私掠船只。"},{t="肃清城墙",b="沙罗萨斯船长拒绝让他的船只被无端击沉。针对北方城堡的打击目标是其指挥层：法尔茅斯船长和她的首席炮手韦森与斯麦斯。击杀他们并从驻军士兵身上搜走塞拉摩勋章将使该要塞的炮兵陷入混乱，从而让棘齿城的海上航运在商旅海岸获得喘息的空间。"}},faq={{q="为什么北方城堡要向来自棘齿城的船只开火？",a="驻守在北方城堡的人类士兵处于极度的偏执之中。由于担心遭到部落和地区海盗的袭击，他们那些喜欢随意开火的炮手们开始攻击几乎每一艘航行经过商旅海岸的船只，而不管它们悬挂的是中立旗帜还是敌对旗帜。",al={"为什么他们要炮击船只","为什么北方城堡要攻击棘齿城","北方城堡的炮火"}},{q="沙罗萨斯船长是谁？",a="沙罗萨斯船长是一位以地精港口棘齿城为基地的血精灵私掠船长。他指挥着一支商船队，保护当地的航运利益免受咄咄逼人的竞争对手的侵害，其中包括北方城堡那些过度激进的联盟军队。",al={"谁发布了这个任务","沙罗萨斯船长","棘齿城的任务发布者"}},{q="法尔茅斯船长、炮手韦森和炮手斯麦斯是谁？",a="法尔茅斯船长指挥着北方城堡的驻军，而韦森和斯麦斯则是负责指挥俯瞰大海的炮台的高级炮手。击杀他们可以破坏该要塞的指挥链，并使他们的重炮失去作用。",al={"法尔茅斯、韦森、斯麦斯","北方城堡军官","北方城堡的炮击目标"}},{q="什么是塞拉摩勋章？",a="塞拉摩勋章是驻扎在北方城堡的人类步兵和卫兵佩戴的军事徽章。沙罗萨斯船长要求获得这些勋章，作为私掠者们的死亡已获复仇、要塞驻军已被重创的切实证据。",al={"塞拉摩徽章","为什么要收集勋章","什么掉落勋章"}},{q="北方城堡位于哪里？",a="北方城堡坐落在贫瘠之地的东南悬崖上，位于棘齿城正南方的商旅海岸沿线。",al={"北方城堡在哪里","北方城堡位置","北方城堡的火炮在哪里"}},{q="北方城堡是塞拉摩的正式组成部分吗？",a="是的。北方城堡是塞拉摩王国为了在卡利姆多大陆建立军事立足点而设立的前哨站。然而，其孤立的驻军在面对穿越贫瘠之地的任何事物时，都表现得极其激进且充满怀疑。",al={"北方城堡属于塞拉摩吗","北方城堡联盟势力","吉安娜与北方城堡"}}},fp="22,245,24.305.0,22.304.0,54.191.0,36.198.0,67.212.0,26.220.0,33.106.0,48.202.0"}
P.entries["quest:892"] = {n="丢失的货物",s="在码头进行了一番调查后，码头管理员迪兹威格归还了加兹鲁维的账本，账目清晰无误，排除了港口贪污的可能，并将怀疑目标指向了当地的海盗。将文书送回给加兹鲁维后，这位地精老板决定对南海海盗进行报复，以夺回丢失的货物。",h="在码头进行了一番调查后，码头管理员迪兹威格归还了加兹鲁维的账本，账目清晰无误，排除了港口贪污的可能，并将怀疑目标指向了当地的海盗。将文书送回给加兹鲁维后，这位地精老板决定对南海海盗进行报复，以夺回丢失的货物。",kw={"贫瘠之地","迪兹威格","海盗","加兹鲁维","账本","棘齿城","货物","幽暗城"},ang={["class:Rogue"]="梳理港口的文书工作揭示了货物在海上与岸上之间是如何轻易消失的——这是走私犯的惯用伎俩。",["faction:Alliance"]="在贫瘠之地行动需要谨慎的结盟，协助棘齿城的领导层有助于在卡利姆多中部获得稳固的立足点。",["faction:Horde"]="棘齿城是中立的，但让加兹鲁维保持满意有助于维护稳定的贸易路线，这对部落有利，也符合地精的中立原则。"},sec={{t="码头的账目核对",b="棘齿城依靠贸易繁荣昌盛，但在贫瘠之地经营这样一个繁忙的港口也带来了持续的后勤难题。当一批预期的货物失踪时，加兹鲁维怀疑是港口账目出现了差错，或者是码头上发生了非法勾当。在查阅清单后，码头管理员迪兹威格坚称他的账目没问题，且入库记录完全吻合，这意味着丢失的货物根本就没上过码头。"},{t="盯上海盗",b="既然迪兹威格排除了港口内部贪污的可能性，那么唯一的嫌疑人就只剩下在海岸边扎营的南海海盗了。迪兹威格在归还账本的同时，还提到了从幽暗城运来的一批单独的板条箱，指引冒险者回到棘齿城的首席工程师那里。在确信码头管理员的忠诚后，加兹鲁维将重心从管理物资账本转移到了组织一支探险队以夺回被盗财物上。"}},faq={{q="加兹鲁维的账本里有什么？",a="加兹鲁维的账本包含了航运清单、货物库存以及详细记录运抵棘齿城的货物的港口入库日志。码头管理员迪兹威格通过核对账本，确认丢失的板条箱是否曾从船上卸货入库。",al={"什么是账本","加兹鲁维的账本","码头清单"}},{q="究竟是谁偷了加兹鲁维的货物？",a="加兹鲁维怀疑是南海海盗所为，这是一群在棘齿城以南的海岸边扎营的当地海盗。迪兹威格的记录显示码头并无出入，这让加兹鲁维将注意力转向了这些劫掠者。",al={"谁偷了货物","谁拿走了货物","谁有货物"}},{q="为什么加兹鲁维信任码头管理员迪兹威格？",a="加兹鲁维信任迪兹威格，因为这位码头管理员是他雇佣的人，而且有着可靠的服务记录。老板相信迪兹威格知道不能欺瞒自己，因此接受了他关于账目清晰的说法。",al={"迪兹威格在撒谎吗","加兹鲁维信任迪兹威格吗","迪兹威格诚实吗"}},{q="迪兹威格提到的来自幽暗城的物品是什么？",a="迪兹威格提到收到了一批来自地精主城幽暗城的单独货物，只要加兹鲁维从繁忙的城镇管理工作中抽身出来，随时都可以去领取。",al={"幽暗城货物","什么东西从幽暗城运来","幽暗城物品"}},{q="这项调查接下来会指向哪里？",a="将账本送还给加兹鲁维后，任务将直接引向“被盗的财物”，你将受雇潜入贫瘠之地南海岸的南海海盗营地，夺回丢失的货物。",al={"接下来是什么任务","失踪货物之后的下一步","下一步去哪"}},{q="码头管理员迪兹威格在哪里？",a="码头管理员迪兹威格负责监管棘齿城码头，他通常站在商船靠岸装卸货物的码头平台附近。",al={"迪兹威格在哪里","迪兹威格位置","寻找码头管理员"}}},fp="20,207,27.326.0,23.386.1,28.200.0,38.193.0,44.181.0,57.145.0,40.173.1,38.118.0"}
P.entries["quest:8921"] = {n="灵质提纯器",s="位于加基森的穆克斯·玛纳斯卡波正在制造他的超维度幽灵探测器，但资金和人手都已用尽。他需要的第一件东西是灵质提纯器，他向你要一份昂贵的材料清单和四十金币来制造它。",h="位于加基森的穆克斯·玛纳斯卡波正在制造他的超维度幽灵探测器，但资金和人手都已用尽。他需要的第一件东西是灵质提纯器，他向你要一份昂贵的材料清单和四十金币来制造它。",kw={"奥金转换器","燃烧平原","灵质提纯器","加基森","穆克斯·玛纳斯卡波","石鳞鱼油","塔纳利斯","火山灰"},sec={{t="穆克斯的需求",b="在“超自然装置”之后，穆克斯·玛纳斯卡波很乐意接受你对他的幽灵探测器的帮助，这台机器旨在跨越维度进行探测。第一部分是提纯器，用于收集死亡本身的结构，他警告说制造它并不容易。他需要一个精密的奥金转换器、四个强效永恒精华、十瓶石鳞鱼油和二十五份火山灰，外加四十金币。火山灰用于制作过滤器，必须来自燃烧平原的熔岩池。穆克斯承认这些材料很昂贵，但发誓每一件都是必需的。"},{t="穆克斯的感谢",b="穆克斯说这正是他所需要的材料，而且你来得正是时候。他承诺会立刻准备好你的提纯器，并为你带来的麻烦给予奖励。"}},faq={{q="谁需要这些材料？",a="位于塔纳利斯加基森的穆克斯·玛纳斯卡波，他正在制造一台超维度幽灵探测器。",al={"任务发布者","谁发布任务","穆克斯是谁"}},{q="穆克斯需要什么材料？",a="一个精密的奥金转换器、四个强效永恒精华、十瓶石鳞鱼油、二十五份火山灰和四十金币。",al={"所需物品","我需要什么","提纯器材料"}},{q="在哪里可以找到火山灰？",a="穆克斯说去燃烧平原的熔岩池收集它。",al={"火山灰位置","去哪获取火山灰"}},{q="为什么穆克斯需要这些特定的组件？",a="它们被用于制造灵质提纯器，这是一种收集构成死亡之物质的装置。火山灰用于制造它的过滤器。",al={"为什么需要奥金","火山灰的用途","为什么需要这些物品"}},{q="交付材料后接下来会发生什么？",a="下一步是“狩猎灵质”。",al={"下一步","接下来会发生什么","后续任务"}}},fp="25,204,14.509.0,12.161.1,29.111.0,32.135.0,32.75.0,44.124.0,42.33.0"}
P.entries["quest:8922"] = {n="超自然的设备",s="德莉亚娜正在寻找一种能与安希恩·哈蒙的鬼魂交谈的方法。一位对超自然现象有着独特迷恋的工程师声称他能制造一台与死者沟通的机器，你将收集到的血液带到加基森作为他的报酬。",h="德莉亚娜正在寻找一种能与安希恩·哈蒙的鬼魂交谈的方法。一位对超自然现象有着独特迷恋的工程师声称他能制造一台与死者沟通的机器，你将收集到的血液带到加基森作为他的报酬。",kw={"安希恩·哈蒙","德莉亚娜","加基森","穆克斯·玛纳斯卡波","密封的毒液容器","超自然装置","塔纳利斯"},ang={["faction:Alliance"]="德莉亚娜派遣联盟的冒险者前往加基森寻找穆克斯·玛纳斯卡波。"},sec={{t="工程师的报酬",b="德莉亚娜正在寻找一种能接触到安希恩·哈蒙的方法，或者更准确地说，是接触他的鬼魂。德莉亚娜心目中的工程师是穆克斯·玛纳斯卡波，他吹嘘自己拥有一台能与死者对话的机器。你手里的那份血液从一开始就是为他准备的，所以带着它前往塔纳利斯的加基森，把它交给穆克斯以换取他的服务。"},{t="受欢迎的货物",b="穆克斯很高兴收到了这些血液，因为他正好快用完了。随后他问你是不是德莉亚娜派你来的。"}},faq={{q="德莉亚娜为什么要派你去加基森？",a="德莉亚娜想要与安希恩·哈蒙的鬼魂交谈。加基森的一位工程师声称他能制造一台与死者沟通的机器，所以你给他带去了他的报酬。",al={"为什么要去加基森","德莉亚娜 加基森","超自然装置的目的"}},{q="运送的容器里装着什么？",a="那是一个密封的容器，装着你收集的血液，作为工程师的服务报酬。",al={"容器里有什么","密封的毒液容器","这是什么血"}},{q="谁在加基森接收货物？",a="穆克斯·玛纳斯卡波，加基森那位对超自然现象有着独特迷恋的工程师。",al={"谁收到了容器","加基森联络人","穆克斯·玛纳斯卡波是谁"}},{q="货物交付之后会发生什么？",a="接下来是灵质提纯器。",al={"接下来发生什么","后续任务","超自然装置之后"}}},fp="21,166,23.301.0,18.104.1,39.156.0,45.86.0,39.111.0,27.34.0"}
P.entries["quest:8923"] = {n="超自然的设备",s="莫克瓦尔需要用到你收集的毒液样本：这些样本是给加基森的一位熟人，穆克斯·玛纳斯卡波的。穆克斯正在研制一种能与死者沟通的装置，莫克瓦尔希望它能帮助联系上安希恩。",h="莫克瓦尔需要用到你收集的毒液样本：这些样本是给加基森的一位熟人，穆克斯·玛纳斯卡波的。穆克斯正在研制一种能与死者沟通的装置，莫克瓦尔希望它能帮助联系上安希恩。",kw={"安希恩","加基森","莫克瓦尔","穆克斯·玛纳斯卡波","密封的毒液容器","超自然装置","塔纳利斯"},ang={["faction:Horde"]="莫克瓦尔派遣部落冒险者前往加基森寻找穆克斯·玛纳斯卡波。"},sec={{t="工程师的毒液",b="莫克瓦尔评论说，你能留下来一定很有勇气，并表示任何愿意继续帮忙的人都能获得更多的护甲。你收集的毒液属于一位熟人，名叫穆克斯·玛纳斯卡波，他是一位对超自然现象感兴趣的工程师。穆克斯目前的项目是一个与死者交谈的装置。莫克瓦尔将最后的希望寄托于此：希望能借此联系到安希恩，从而进一步了解他自己的处境。你带着密封的容器前往塔纳利斯的加基森找穆克斯。"},{t="受欢迎的交付",b="穆克斯很高兴收到毒液，因为他的存货快用完了。随后穆克斯询问是否是莫克瓦尔派你来的。"}},faq={{q="是谁派你来送货的？",a="莫克瓦尔，他希望把密封的毒液容器送到加基森的一位熟人那里。",al={"谁给予此任务","任务发布者","莫克瓦尔"}},{q="毒液需要送到哪里？",a="送到塔纳利斯加基森的穆克斯·玛纳斯卡波那里。",al={"我该把毒液带到哪里","交付地点","穆克斯位置"}},{q="穆克斯·玛纳斯卡波是谁？",a="一位痴迷于超自然现象的工程师，也是莫克瓦尔的熟人。",al={"谁是穆克斯","穆克斯·玛纳斯卡波背景故事"}},{q="穆克斯在制造什么？",a="一种可以让你与死者沟通的装置。这是穆克斯最近的项目。",al={"该装置是什么","穆克斯建造什么","超自然装置"}},{q="莫克瓦尔为什么要联系死者？",a="莫克瓦尔希望联系上安希恩并了解更多关于他自己处境的信息，他将该装置视为最后的机会。",al={"为何联系安希恩","谁是安希恩","莫克瓦尔的动机"}}},fp="21,174,21.392.0,18.121.1,36.82.0,32.61.0,25.94.0,21.88.0,39.112.0"}
P.entries["quest:8924"] = {n="猎取灵质",s="加基森的穆克斯·玛纳斯卡波已经准备好了他的灵质提纯器，现在需要灵质。你必须前往希利苏斯、冬泉谷和东瘟疫之地这三个遥远的地区，从无形的亡灵身上收集十二份各自类型的灵质。此任务紧接“灵质提纯器”之后。",h="加基森的穆克斯·玛纳斯卡波已经准备好了他的灵质提纯器，现在需要灵质。你必须前往希利苏斯、冬泉谷和东瘟疫之地这三个遥远的地区，从无形的亡灵身上收集十二份各自类型的灵质。此任务紧接“灵质提纯器”之后。",kw={"东瘟疫之地","灵质提纯器","冰冻的灵质","加基森","猎取灵质","穆克斯·玛纳斯卡波","灼热的灵质","希利苏斯","稳定的灵质","冬泉谷"},sec={{t="三种气候，三种灵质",b="穆克斯·玛纳斯卡波对这台提纯器感到自豪，并警告说你得长途跋涉才能找到无形的亡灵。在穆克斯看来，气候会改变亡灵幽灵结构的性质。希利苏斯有饱受折磨的暗夜精灵，冬泉谷有上层精灵的灵魂，而东瘟疫之地则有鬼魂和女妖。每个地方产出的灵质各不相同：十二份灼热的灵质、十二份冰冻的灵质和十二份稳定的灵质。穆克斯说在采集前要把提纯器放在附近，然后带着它和灵质回到加基森。"},{t="穆克斯的判断",b="穆克斯对这些灵质非常满意。他解释说，其中蕴含的超自然能量将让你能够接触到尚未完全离开这个世界的灵魂。"}},faq={{q="谁派你去收集灵质？",a="位于塔纳利斯加基森的穆克斯·玛纳斯卡波，前提是他已经造好了提纯器。",al={"谁给予猎取灵质任务","猎取灵质任务发布者"}},{q="为什么穆克斯需要从三个不同的地方收集灵质？",a="穆克斯说不同的气候会赋予亡灵幽灵结构不同的质地。他需要从希利苏斯收集十二份灼热的灵质，从冬泉谷收集十二份冰冻的灵质，以及从东瘟疫之地收集十二份稳定的灵质。",al={"为什么要收集三种灵质","不同类型的灵质","为什么要前往希利苏斯、冬泉谷和东瘟疫之地"}},{q="哪些灵魂会提供灵质？",a="希利苏斯受折磨的暗夜精灵、冬泉谷的上层精灵灵魂，以及东瘟疫之地的鬼魂和女妖。",al={"什么敌人掉落灵质","为了收集灵质要击杀什么","哪些鬼魂掉落灵质"}},{q="灵质是如何收集的？",a="穆克斯说在采集灵质之前，先要把提纯器放在无形的亡灵附近。",al={"提纯器如何运作","如何收集灵质"}},{q="这个任务在穆克斯的工作流程中处于什么位置？",a="它位于“灵质提纯器”之后，其后是“便携式动力源”。",al={"猎取灵质的前提条件","猎取灵质之前的任务"}}},fp="21,245,27.492.0,13.159.1,34.82.0,56.187.0,36.149.0,30.84.0,34.77.0"}
P.entries["quest:8925"] = {n="便携的能量源",s="拿到灵质之后，穆克斯·玛纳斯卡波需要一个稳定的、便携的能源来维持它的活性。他听说在燃烧平原有一个名叫博克岩浆领主的元素生物，它的心脏是岩浆核心，他想让你把这颗核心带到加基森给他。",h="拿到灵质之后，穆克斯·玛纳斯卡波需要一个稳定的、便携的能源来维持它的活性。他听说在燃烧平原有一个名叫博克岩浆领主的元素生物，它的心脏是岩浆核心，他想让你把这颗核心带到加基森给他。",kw={"黑石山","燃烧平原","加基森","幽灵探测器","岩浆核心","博克岩浆领主","穆克斯·玛纳斯卡波"},sec={{t="永恒之热的心脏",b="在搜寻完灵质后，穆克斯·玛纳斯卡波想要一个稳定的、可移动的能源来维持灵质的活性。据传，强大的元素生物博克岩浆领主拥有一颗岩浆核心作为心脏，那是一股源源不绝的热量之源。据说这位岩浆领主栖息在燃烧平原，就在黑石山以南、灰烬之柱以西的地方。穆克斯想要把那颗核心带到加基森，好让那个超维度幽灵探测器运转起来。"},{t="终获能源",b="当你带着核心回来时，穆克斯激动不已，声称它绝对能为幽灵探测器提供所需的一切能量。"}},faq={{q="为什么穆克斯·玛纳斯卡波需要能源？",a="穆克斯想要一个稳定的、可移动的能源供应，足以维持灵质的活性并驱动超维度幽灵探测器。",al={"为什么需要能源","能源是干什么用的","为什么需要岩浆核心"}},{q="博克岩浆领主是谁？",a="据传是一位强大的元素生物，拥有一颗岩浆核心作为心脏，那是一股永不枯竭的热量泉源。",al={"博克是谁","博克岩浆领主背景故事","博克在哪里"}},{q="在燃烧平原的什么地方能找到博克岩浆领主？",a="传闻他就在燃烧平原，黑石山以南、灰烬之柱以西的地方。",al={"博克位置","博克岩浆领主在哪里","寻找博克岩浆领主"}},{q="这一步在穆克斯的工作中起什么作用？",a="它是在“搜寻灵质”之后进行的，接下来是“狡诈的商人”。",al={"之前有什么任务","任务链顺序","接下来做什么"}}},fp="23,184,23.367.0,13.134.1,47.122.0,23.105.0,58.112.0,41.69.0"}
P.entries["quest:8928"] = {n="小巧的商人",s="穆克斯·玛纳斯卡波已经有了为他的装置提供动力的核心，现在需要一根能承载这种能量且不会熔化的导杖。他曾在冬泉谷遇到过一个售卖异国商品的小鬼，现在后悔当时没有买下他手中的那根元素之杖。你需要前往暗语峡谷入口处的一个洞穴寻找那个小鬼，并买下恶魔元素之杖。",h="穆克斯·玛纳斯卡波已经有了为他的装置提供动力的核心，现在需要一根能承载这种能量且不会熔化的导杖。他曾在冬泉谷遇到过一个售卖异国商品的小鬼，现在后悔当时没有买下他手中的那根元素之杖。你需要前往暗语峡谷入口处的一个洞穴寻找那...",kw={"暗语峡谷","恶魔元素之杖","加基森","小鬼","商人","穆克斯·玛纳斯卡波","冬泉谷"},sec={{t="洞穴中的小鬼",b="在完成“便携式动力源”任务后，穆克斯·玛纳斯卡波转向了下一个难题：寻找一根能承载核心能量且不会熔化的导杖。穆克斯曾在冬泉谷遇到过一个售卖各种异国商品的小鬼，那个小鬼手中的元素之杖堪称完美。穆克斯为自己当初没有买下它而懊悔不已。那个小鬼住在冬泉谷南部暗语峡谷入口处的一个洞穴里。你需要找到那个小鬼，买下恶魔元素之杖，并把它带回给加基森的穆克斯。穆克斯坚持要求小鬼只收取四十金币，也就是当初报价给他的价格。"},{t="获得导杖",b="穆克斯对这根导杖感到非常满意，说它正合适，随后开始着手组装设备。"}},faq={{q="谁指派你去寻找导杖？",a="位于塔纳利斯加基森的穆克斯·玛纳斯卡波。",al={"谁发布狡诈的商人任务","狡诈的商人任务发布者"}},{q="在此步骤之前需要完成什么？",a="紧接在“便携式动力源”之后。",al={"前置任务","狡诈的商人前置任务"}},{q="在哪里可以找到那个小鬼商人？",a="位于冬泉谷南部暗语峡谷入口处的一个洞穴内。",al={"小鬼在哪里","暗语峡谷小鬼位置","冬泉谷的商人位置"}},{q="你被指派去购买什么物品？",a="恶魔元素之杖。",al={"我要买什么物品","小鬼卖什么"}},{q="这根导杖需要多少钱？",a="四十金币是小鬼当初给穆克斯的报价，穆克斯要求对方收费不得超过此数。",al={"导杖价格","导杖需要多少金币","小鬼的要价"}},{q="穆克斯为什么需要这根导杖？",a="虽然核心能为装置提供足够的动力，但穆克斯还需要一根能承载这种能量且不会熔化的导杖。",al={"为什么需要恶魔元素之杖","导杖的用途"}}},fp="17,300,19.453.0,15.106.1,28.67.0,27.37.0,36.92.0,35.40.0,27.65.0,27.102.0"}
P.entries["quest:893"] = {n="野猪人的武器",s="塔特纳克·钢炉是驻守在陶拉祖营地的一名部落铁匠，他正在调查有关南方的钢鬃野猪人制造出异常坚固的武器的报告。受大酋长指派评估这一威胁，他招募旅行者前往巨人旷野之外，直接从野猪人部队手中夺取武器。对这些样本的检查表明，野猪人的危险程度和技术能力远超部落最初的预想。",h="塔特纳克·钢炉是驻守在陶拉祖营地的一名部落铁匠，他正在调查有关南方的钢鬃野猪人制造出异常坚固的武器的报告。受大酋长指派评估这一威胁，他招募旅行者前往巨人旷野之外，直接从野猪人部队手中夺取武器。对这些样本的检查表明，野猪人...",kw={"背刺匕首","贫瘠之地","野猪人","钢鬃","钢炉","塔特纳克","陶拉祖","魔杖","战盾"},ang={["faction:Horde"]="陶拉祖营地在南部边境依然脆弱，因此获取关于钢鬃军事进展的情报对于保卫穿越贫瘠之地的贸易路线至关重要。",["profession:Blacksmithing"]="对于铁匠而言，评估回收的武器凸显了敌人的材料质量如何直接决定前线的战术准备程度。",["race:Orc"]="兽人的荣誉要求尊重军事力量，塔特纳克对萨尔的职责要求他在对手变得真正危险时能够识别出来。"},sec={{t="奇特的进步",b="贫瘠之地的野猪人通常被视为野蛮、粗鲁的野兽，使用着原始的木制、骨制和石制工具。然而，陶拉祖营地收到了消息，称远在南方的钢鬃部族已经开始装备异常耐用的军事装备。大酋长萨尔命令下的一名兽人铁匠塔特纳克·钢炉对此报告产生了兴趣。尽管他怀疑野猪人是否掌握了正统的冶金术，但他仍寻求证据，以确定他们是开发了新技术还是发现了更好的资源。"},{t="钢鬃的武装",b="为了研究他们的工艺，塔特纳克需要钢鬃部族军火库的各类样本。他指引侦察兵前往巨人旷野那些巨大的骨骸以南，去对抗钢鬃的战争营地。在那里，勇士们必须从野猪人猎手手中夺取钢鬃背刺匕首，从他们的预言者手中夺取烧焦的魔杖，并从狂暴的突击兵手中夺取沉重的战盾。每一件装备都揭示了目前助长钢鬃对部落领地攻势的军事和神秘技艺。"},{t="低估敌人",b="在处理回收的样本时，塔特纳克的怀疑转变成了担忧。这些武器展现出的工艺水平和韧性打破了部落对野猪人能力的固有假设。意识到部落严重低估了该部族，这位铁匠放下锻造工作，深入研究这些材料，怀疑有外部因素或新发现的资源在助长钢鬃的战争努力。"}},faq={{q="塔特纳克·钢炉是谁？",a="塔特纳克·钢炉是一名兽人铁匠和护甲匠，驻扎在南贫瘠之地的陶拉祖营地。他奉大酋长萨尔之命支持部落的前线防御，专门研究敌人的武器并为当地部队锻造装备。",al={"塔特纳克·钢炉","谁给予了武器的选择任务","陶拉祖铁匠"}},{q="为什么塔特纳克想要野猪人的武器？",a="报告显示，南方的钢鬃部族开始使用出奇耐用的武器，尽管他们从未有过熟练锻造的传统。塔特纳克想要检查他们的匕首、魔杖和盾牌，以了解他们是如何制造这些装备的，以及它们是否构成了升级的威胁。",al={"为什么要收集野猪人武器","武器的选择任务原因","塔特纳克的动机"}},{q="为完成此任务，钢鬃野猪人位于何处？",a="目标野猪人居住在南贫瘠之地远处的营地中，位于巨人旷野之外，且在通往升降梯和千针石林的道路以西。",al={"野猪人在哪里","武器的选择任务地点","去哪里找钢鬃"}},{q="哪些野猪人携带所需的武器？",a="钢鬃猎手携带钢鬃背刺匕首，钢鬃预言者使用烧焦的钢鬃魔杖，而钢鬃狂暴战士则携带坚固的钢鬃战盾。",al={"谁掉落背刺匕首","谁掉落魔杖","谁掉落战盾"}},{q="塔特纳克从武器中发现了什么？",a="在检查了这些物品后，塔特纳克证实这些武器制作得非常精良，远超部落对野猪人的预期。这一发现促使他在后续任务“新的矿石样本”中调查他们所使用的原材料。",al={"塔特纳克发现了什么","武器的选择任务结果","野猪人是铁匠吗"}},{q="为什么部落担心野猪人制造武器？",a="部落依靠卓越的金属工艺和纪律严明的力量，在广袤的贫瘠之地抵御众多的本土威胁。如果多产的钢鬃野猪人能够大规模生产坚固的铁制或钢制武器，他们可以轻易淹没像陶拉祖营地这样的前哨站。",al={"为什么野猪人武器很重要","野猪人威胁等级"}}},fp="17,179,21.402.0,26.446.0,25.307.1,29.198.0,42.240.0,55.156.0,42.164.0,47.172.1,62.262.0"}
P.entries["quest:894"] = {n="什么什么平衡器",s="这项任务由棘齿城的哥布林工程师斯布特瓦夫委托，要求冒险者向北前往淤泥沼泽西南方的荆棘谷地精研究哨站。他们的目标是找到一个被称为“萨摩范奇”的神秘装置。装备着一本偷来的操作手册，好奇的调查员必须操作一台不稳定的控制台来取出该装置。",h="这项任务由棘齿城的哥布林工程师斯布特瓦夫委托，要求冒险者向北前往淤泥沼泽西南方的荆棘谷地精研究哨站。他们的目标是找到一个被称为“萨摩范奇”的神秘装置。装备着一本偷来的操作手册，好奇的调查员必须操作一台不稳定的控制台来取出...",kw={"贫瘠之地","控制台","哥布林工程学","萨摩范奇","淤泥沼泽","斯布特瓦夫","荆棘谷地精"},ang={["faction:Horde"]="荆棘谷地精的野蛮开采和化学径流威胁着贫瘠之地脆弱的生态系统，使得破坏他们的设施对于当地的部落防御者来说势在必行。",["profession:Engineering"]="工程师们会欣赏斯布特瓦夫对竞争对手蓝图的执着，这展示了哥布林工业间谍活动中残酷的一面。"},sec={{t="一个奇特的装置",b="哥布林向来以追求创新、好奇心和利益而闻名，但即使是技师斯布特瓦夫也被荆棘谷地精在贫瘠之地北部挖掘点出现的最新进展搞得困惑不已。这个竞争对手在淤泥沼泽西南方活动，一直在摆弄一种被称为“萨摩范奇”的装置。由于不知道其精确的机械功能或潜在的利润，斯布特瓦夫渴望弄到这件设备，以便在他的商业竞争对手利用它之前反向工程设计出该装置。"},{t="渗透钻井平台",b="确保该装置的安全并非易事。荆棘谷地精严密守护着他们的行动，用武装的监工、伐木机和复杂的机械包围了设施。斯布特瓦夫提供了一本截获的操作手册，以协助安全地关闭这个不稳定的钻井平台。在到达中央控制站时，调查员会发现杂乱无章的操纵杆、指示灯和仪表，它们维持着三个关键控制阀的最佳压力，并由一个锁定的控制台把守。"}},faq={{q="什么是萨摩范奇？",a="即使是斯布特瓦夫也不完全知道它是什么或有什么用。这是一种专有的、实验性的机械组件，由荆棘谷地精在他们位于淤泥沼泽西南方的设施中制造。",al={"什么是萨摩范奇","萨摩范奇的用途","萨摩范奇的作用"}},{q="斯布特瓦夫是谁？",a="斯布特瓦夫是驻扎在棘齿城的一名哥布林工程师和技师。他对荆棘谷地精的商业秘密很感兴趣，因此雇佣冒险者去破坏他们的工作并夺取他们的技术进步。",al={"斯布特瓦夫是谁","斯布特瓦夫的位置","任务发布者"}},{q="控制台位于何处？",a="该控制台位于贫瘠之地十字路口以北、被污染的淤泥沼泽西南方的荆棘谷地精研究点内。",al={"控制台位置","控制台在哪里","去哪里找萨摩范奇"}},{q="荆棘谷地精为什么在贫瘠之地？",a="荆棘谷地精是一个唯利是图、利欲熏心的集团，在卡利姆多掠夺自然资源。在贫瘠之地，他们砍伐森林、钻探石油，并建造像淤泥沼泽周围那样的实验性钻井平台。",al={"贫瘠之地的荆棘谷地精","荆棘谷地精为什么在这里","淤泥沼泽的行动"}},{q="如何安全地拆除萨摩范奇？",a="控制台上有三个打开的控制阀和一个钥匙孔。遵循斯布特瓦夫找回的操作手册，操作员可以绕过安全锁并操纵阀门以拆下该模块。",al={"如何使用控制台","控制台操作手册","手册说明"}},{q="斯布特瓦夫为荆棘谷地精工作吗？",a="不。斯布特瓦夫是一名独立或竞争对手特工，旨在削弱并窃取荆棘谷地精的工程发现供自己研究。",al={"斯布特瓦夫是荆棘谷地精的人吗","斯布特瓦夫的阵营"}}},fp="11,156,22.366.0,20.326.0,22.176.0,20.164.0,37.144.0,42.193.0,44.171.0,47.130.0"}
P.entries["quest:895"] = {n="通缉：巴隆·朗绍尔",s="“通缉：长滩男爵”是由总工程师加兹鲁维在棘齿城的码头上张贴的一份赏金合同。它的目标是长滩男爵，这是一名臭名昭著的吉尔尼斯海盗船长，指挥着南海海盗的船只。长滩在商旅海岸的出现对该地区的各个地精商船构成了直接威胁。",h="“通缉：长滩男爵”是由总工程师加兹鲁维在棘齿城的码头上张贴的一份赏金合同。它的目标是长滩男爵，这是一名臭名昭著的吉尔尼斯海盗船长，指挥着南海海盗的船只。长滩在商旅海岸的出现对该地区的各个地精商船构成了直接威胁。",kw={"长滩男爵","加兹鲁维","吉尔尼斯","鲁莽号","商旅海岸","海盗悬赏","棘齿城","南海海盗"},ang={["faction:Alliance"]="尽管长滩来自吉尔尼斯，但他的海盗行为破坏了联盟旅行者在卡利姆多和东部王国之间往来所依赖的中立航线。",["faction:Horde"]="清理棘齿城附近的南海海盗可以使港口保持开放和友好，确保部落物资能够顺利运往贫瘠之地。",["race:Human"]="看到一位吉尔尼斯男爵在卡利姆多指挥亡命之徒，提醒着人们从东部王国出逃的叛逃者和流浪者已经散布在世界各地的海洋上有多远。"},sec={{t="商旅海岸的海盗活动",b="贫瘠之地外的水域是热砂港的重要海上航线，连接着棘齿城、藏宝海湾以及更远的地方。不幸的是，南海海盗在棘齿城南部的海岸线上建立了防御营地。在长滩男爵这类人物的指挥下，这些亡命之徒骚扰商船、破坏贸易，并榨干了当地的地精行政部门。"},{t="来自吉尔尼斯的船长",b="长滩被认定来自与世隔绝的人类王国吉尔尼斯，这使得他出现在卡利姆多成为了一件既不寻常又危险的怪事。作为海盗船“鲁莽号”的船长，他带领船员在北方城堡的北部登陆。加兹鲁维没有选择宏大的外交手段，而是通过实际的地精方式解决了这个问题：悬赏征集这名海盗的头颅。"}},faq={{q="长滩男爵是谁？",a="长滩男爵是一位来自吉尔尼斯的海盗船长，他为南海海盗指挥着“鲁莽号”这艘船。他在棘齿城南部的海岸线上活动，袭击航运路线。",al={"长滩男爵","长滩是谁","长滩船长"}},{q="为什么加兹鲁维想要他死？",a="长滩的海盗活动直接威胁到了加兹鲁维从棘齿城出发的商船运输。为了保持贸易顺利运行并保护热砂港的利润，加兹鲁维发出了悬赏，要求取下长滩的头颅。",al={"为什么要杀长滩","加兹鲁维悬赏原因","为什么长滩被通缉"}},{q="在哪里可以找到长滩男爵？",a="他经常出现在位于棘齿城南部、北方城堡北部的商旅海岸沿线的南海海盗营地中。",al={"长滩位置","长滩在哪里","长滩男爵刷新点"}},{q="长滩男爵指挥的是什么船？",a="他指挥的是“鲁莽号”，这是一艘在商旅海岸周围的公海上广为人知的可怕海盗船。",al={"长滩的船","长滩的船名","鲁莽号"}},{q="长滩男爵是联盟贵族吗？",a="虽然他拥有男爵的头衔，且原本来自吉尔尼斯，但他现在的行为纯粹是一名带领着南海海盗的叛逃劫掠者，与目前的联盟领导层没有任何关系。",al={"长滩是联盟吗","吉尔尼斯贵族海盗","长滩吉尔尼斯"}},{q="悬赏海报在哪里？",a="通缉令张贴在棘齿城港口银行附近的布告栏上。",al={"通缉令在哪里","长滩海报位置","如何开始长滩任务"}}},fp="23,238,28.358.0,22.274.0,23.162.0,31.145.0,35.129.0,39.103.0,37.176.0,35.75.0"}
P.entries["quest:896"] = {n="矿工的宝贝",s="棘齿城的码头管理员迪兹维格得知荆棘谷地精在石矿洞有一项非凡的发现：一颗拳头大小的翡翠。迪兹维格不愿让那个冷酷的矿业集团独吞利益，于是雇佣了一名冒险者，从矿场的监工手中夺回这颗猫眼翡翠，并承诺分得利润。",h="棘齿城的码头管理员迪兹维格得知荆棘谷地精在石矿洞有一项非凡的发现：一颗拳头大小的翡翠。迪兹维格不愿让那个冷酷的矿业集团独吞利益，于是雇佣了一名冒险者，从矿场的监工手中夺回这颗猫眼翡翠，并承诺分得利润。",kw={"石矿洞","猫眼翡翠","迪兹维格","执行者","监工","棘齿城","淤泥沼泽","荆棘谷地精"},ang={["class:Rogue"]="潜入敌对的采矿营地，从贪婪的监工手中夺走一颗戒备森严的宝石，这完全符合潜行者的行事风格。",["faction:Horde"]="打击石矿洞的荆棘谷地精管理层，可以扰乱这个直接侵入贫瘠之地部落领地的入侵型工业集团。",["profession:Mining"]="矿工们会欣赏这种拳头大小的完整翡翠的稀有程度，这种标本在挖掘过程中几乎从未在不破裂或破碎的情况下保存下来。"},sec={{t="码头的目光",b="身为管理棘齿城与藏宝海湾之间繁忙航运的港口官员，码头管理员迪兹维格几乎听到了商路上私语的每一个秘密。当传言称石矿洞深处挖出了一颗拳头大小的巨型宝石时，迪兹维格立刻意识到这是一个赚钱的好机会。荆棘谷地精在贫瘠之地北部的肆意露天开采让他们没什么朋友，这意味着如果他们最近最大的一笔发现悄然失踪，也不会引起多少怀疑。"},{t="分一杯羹",b="淤泥沼泽东北部的石矿洞里挤满了劳工，但迪兹维格知道，普通的挖掘工是不可能留住那种稀有珍宝的。猫眼翡翠很快就被守卫矿场的荆棘谷地精监工和执行者没收了。要找回这颗宝石，就必须直接对抗这些全副武装的管理者，夺回石头，并将它交给迪兹维格，以便根据幽暗城的有利市场价格进行估价。"}},faq={{q="码头管理员迪兹维格是谁？",a="码头管理员迪兹维格是一位驻扎在棘齿城的地精码头官员。他负责监督往返于藏宝海湾的货物和客运交通，利用他的有利位置倒卖有价值的八卦、传言和商业情报。",al={"迪兹维格","谁发布了矿工的财富任务","棘齿城码头管理员"}},{q="石矿洞位于何处？",a="石矿洞位于贫瘠之地北部，坐落在淤泥沼泽油污工业区东北部的群山之中。",al={"石矿洞位置","翡翠在哪里","贫瘠之地荆棘谷地精矿场"}},{q="谁在矿场持有猫眼翡翠？",a="这颗宝石被矿场的权威人物拿走了，而不是留在苦力手中。击败在石矿洞内外指挥和守卫采矿作业的荆棘谷地精监工和荆棘谷地精执行者，就能夺回它。",al={"谁掉落猫眼翡翠","猫眼翡翠掉落","猫眼翡翠在哪里"}},{q="荆棘谷地精在贫瘠之地有什么图谋？",a="荆棘谷地精是一个激进、不受约束的地精贸易集团，专注于快速的资源剥削。在贫瘠之地北部，他们在淤泥沼泽进行破坏性的钻探作业，并在石矿洞进行密集挖掘，不顾当地生态，掠夺木材、石油和矿产财富。",al={"为什么荆棘谷地精在贫瘠之地","荆棘谷地精贫瘠之地"}},{q="为什么迪兹维格提到了幽暗城？",a="幽暗城是地下岛屿大都市，也是地精财阀的祖籍首都。作为地精商业的主要经济和贸易中心，其市场决定了艾泽拉斯各地珍贵宝石和稀有商品的行情。",al={"幽暗城提及","幽暗城宝石价格"}},{q="迪兹维格真的会分利润吗？",a="秉持他地精式的商业道德，迪兹维格信守诺言，在交付猫眼翡翠后，给了你承诺的一半（按幽暗城市场预估价值计算）报酬。",al={"迪兹维格是否五五分成","迪兹维格付款"}}},fp="15,155,17.292.0,17.323.0,28.171.0,39.110.0,43.138.0,54.232.0,38.151.0,41.125.1"}
P.entries["quest:897"] = {n="收割者",s="“收割者”是一个起始于南贫瘠之地的任务，你需要发现一颗奇怪且异域的昆虫类捕食者的断头。将这个令人不安的样本带给陶拉祖营地的乔恩·星眼，会揭示出该地区的精神和生态平衡所面临的令人不安的影响。",h="“收割者”是一个起始于南贫瘠之地的任务，你需要发现一颗奇怪且异域的昆虫类捕食者的断头。将这个令人不安的样本带给陶拉祖营地的乔恩·星眼，会揭示出该地区的精神和生态平衡所面临的令人不安的影响。",kw={"贫瘠之地","陶拉祖营地","收割者","收割者的头","昆虫类","乔恩·星眼","其拉虫人"},ang={["class:Druid"]="研究卡利姆多重生的德鲁伊们可以立即感知到这些入侵稀树草原的异域掘穴者身上所具有的腐化和寄生本质。",["class:Shaman"]="萨满会注意到乔恩·星眼因为灵魂已经从头颅中消散而感到的沮丧，这导致他无法与元素力量沟通以发现该生物的真正起源。",["faction:Horde"]="陶拉祖营地充当了部落在贫瘠之地的南部盾牌，使得周围断崖上的任何侵入性捕食者都成为一个至关重要的安全隐患。",["race:Tauren"]="对于舒哈鲁人来说，维持大地母亲的和谐是至关重要的；遇到一个违背自然秩序的实体标志着深刻的精神失调。"},sec={{t="不自然的入侵者",b="在南贫瘠之地的稀树草原上，旅人们偶尔会撞见一个令人不安的景象：一颗被称为“收割者”的其拉虫人的断头。不同于游荡在草原上的原生狮子、迅猛龙和科多兽，这种几丁质外壳的昆虫生物似乎完全超出了卡利姆多的自然秩序。它的出现暗示着一种不属于这片开阔平原的异域生态正在逼近。"},{t="乔恩·星眼的预感",b="当牛头人神秘主义者乔恩·星眼在陶拉祖营地收到这只生物的头颅时，他检查了遗骸。由于野兽的灵魂已经消散，他无法占卜出它的起源，但他立刻意识到这代表着一种巨大的威胁。乔恩担心这种生物侵入贫瘠之地可能预示着部落阴暗的未来，并警告说黄沙之下正在酝酿着更黑暗的谜团。"}},faq={{q="什么是收割者？",a="收割者是一只潜伏在贫瘠之地南部边界的大型其拉虫人。它几丁质的、异域的生理构造与该地区的本土野生动物截然不同。",al={"收割者是谁","收割者是什么虫子","收割者生物"}},{q="乔恩·星眼是谁？",a="乔恩·星眼是一位受人尊敬的牛头人长者和精神向导，驻扎在陶拉祖营地。他观察着平原的精神健康，并就威胁土地平衡的事宜提供建议。",al={"乔恩·星眼","任务交接非玩家角色是谁","乔恩 陶拉祖"}},{q="收割者从哪里来？",a="虽然乔恩·星眼无法仅凭断头占卜出它的确切起源，但它是由南方的深层沙漠向北蔓延的其拉虫人巢穴衍生出来的分支。",al={"其拉虫人从哪里来","收割者起源","其拉虫人来源"}},{q="为什么这个生物让乔恩·星眼感到不安？",a="该生物不自然的外形和异域的灵魂深深困扰着乔恩。他感觉到它在贫瘠之地的出现并非偶然，而是一个即将到来的、非自然威胁的凶兆。",al={"为什么乔恩很担心","乔恩·星眼的反应","阴暗的未来"}},{q="如何开始这个任务？",a="该任务始于在南贫瘠之地击杀被称为收割者的稀有其拉虫人并拾取其断头，这会促使你前往陶拉祖营地寻求长者的指引。",al={"如何获取任务","收割者头部掉落","开始收割者"}},{q="乔恩接下来让你做什么？",a="乔恩没有提供立即反击的建议，因为他认识到在侵入的其拉虫人之谜慢慢揭开的同时，部落必须首先做好准备并保持警惕。",al={"后续任务","收割者头部之后","乔恩下一步"}}},fp="13,216,21.268.0,26.249.1,22.132.0,20.185.0,35.171.0,43.181.0,28.166.0,35.151.0"}
P.entries["quest:898"] = {n="逃离监牢",s="“摆脱牢笼”是贫瘠之地的一个护送任务，部落的冒险者需要从北方城堡的人类俘虏者手中救出基尔萨瑞斯·火枝。这位精灵水手在运输船被拦截并击沉后被俘，他寻求一场大胆的突围，以便回到棘齿城与他的船长团聚。",h="“摆脱牢笼”是贫瘠之地的一个护送任务，部落的冒险者需要从北方城堡的人类俘虏者手中救出基尔萨瑞斯·火枝。这位精灵水手在运输船被拦截并击沉后被俘，他寻求一场大胆的突围，以便回到棘齿城与他的船长团聚。",kw={"藏宝海湾","沙罗萨斯船长","护送","基尔萨瑞斯·火枝","私酒","北方城堡","私掠者","棘齿城","走私者","塞拉摩"},ang={["faction:Horde"]="深入北方城堡解救一名被囚禁的走私者，是对塞拉摩在贫瘠之地海岸的军事立足点的又一次令人满意的打击。"},sec={{t="囚禁于北方城堡",b="北方城堡是塞拉摩在贫瘠之地海岸的军事前哨，对任何感知到的威胁都保持着警惕与攻击性。这种偏执让基尔萨瑞斯·火枝落入了网中。他的船在棘齿城和藏宝海湾之间的贸易航线上运输私酒时，遭到了联盟军队的炮击并沉入海底。作为从残骸中被捞起的唯一幸存者，基尔萨瑞斯被扔进了北方城堡的地牢，被指控为阴谋反对联盟的敌方特工。"},{t="走私者的逃亡",b="尽管狱卒将他描绘成一个危险的破坏者，但基尔萨瑞斯坚称自己只是一个运送非法烈酒的卑微水手。在愿意进攻北方城堡的部落力量的帮助下，他孤注一掷寻求自由，在杀出堡垒后沿着海岸线向北逃往棘齿城。在那里，沙罗萨斯船长欢迎这位归队的船员重回沙罗丹私掠者（萨罗丹船队）的怀抱。"}},faq={{q="基尔萨瑞斯·火枝是谁？",a="基尔萨瑞斯·火枝是沙罗萨斯船长麾下的一名精灵水手。他在一艘往返于棘齿城和藏宝海湾之间运输私酒的运输船上服役，直到塞拉摩部队击沉了他的船并将他关入枷锁。",al={"基尔萨瑞斯","基尔萨瑞斯·火枝是谁","谁是北方城堡的囚犯"}},{q="基尔萨瑞斯为何会被塞拉摩军队逮捕？",a="来自北方城堡的联盟士兵在贫瘠之地海岸附近拦截了他的船，并将其炸沉入海。由于对要塞附近的所有海上交通工具都抱有极度的戒心，守军将这艘私酒船视为敌对船只，并认定基尔萨瑞斯是一名对抗联盟的敌对行动人员。",al={"塞拉摩为什么要逮捕他","为什么基尔萨瑞斯会被关进监狱","船为什么会被击沉"}},{q="基尔萨瑞斯获释后去了哪里？",a="基尔萨瑞斯从北方城堡向北逃走，沿着贫瘠之地的东海岸线行进，直到抵达中立地精港口棘齿城。到达那里后，他在码头与沙罗萨斯船长会合。",al={"去哪里护送基尔萨瑞斯","基尔萨瑞斯的目的地","护送任务去哪里"}},{q="什么是沙罗丹私掠者？",a="沙罗丹私掠者是一支由沙罗萨斯船长领导的船队，以棘齿城为基地。他们从事航运和非法走私，包括在卡利姆多和东部王国之间的海域运输私酿烈酒。",al={"沙罗丹私掠者","沙罗萨斯船长的船员","沙罗萨斯领导谁"}},{q="北方城堡为何要攻击平民或走私船只？",a="北方城堡作为塞拉摩在贫瘠之地的要塞，位置正好位于部落领地和关键海上航线的中间。高度的偏执和严格的军事命令使得指挥官们将几乎所有非联盟的海上交通都视为部落的颠覆行动或海盗威胁。",al={"北方城堡为什么敌对","塞拉摩在贫瘠之地的侵略","北方城堡的目的"}},{q="沉船上装载了什么货物？",a="这艘船上装载的是一批用于在棘齿城和藏宝海湾之间分销的非法私酒，而不是武器或军用物资。",al={"船上有什么","基尔萨瑞斯的货物","他们运输什么"}}},fp="18,173,24.446.0,19.277.0,27.207.0,47.213.0,35.137.1,33.206.0,60.236.0,40.125.0"}
P.entries["quest:899"] = {n="复仇的怒火",s="“为仇恨所困”是曼科里克在贫瘠之地十字路口给予的一项严峻任务。被那场让他与妻子失散的暴力伏击所折磨，这位悲痛的兽人将他痛苦的无助转化为对刺鬃野猪人毫不留情的复仇。他号召部落的旅行者们大肆屠杀这些生物，并带回海量的獠牙。",h="“为仇恨所困”是曼科里克在贫瘠之地十字路口给予的一项严峻任务。被那场让他与妻子失散的暴力伏击所折磨，这位悲痛的兽人将他痛苦的无助转化为对刺鬃野猪人毫不留情的复仇。他号召部落的旅行者们大肆屠杀这些生物，并带回海量的獠牙。",kw={"贫瘠之地","刺鬃","为仇恨所困","十字路口","曼科里克","野猪人","陶拉祖","獠牙"},ang={["class:Warrior"]="战士深知，心头的创伤无法总是通过包扎来愈合，而曼科里克唯一的良药就是在这布满荆棘的平原上以牙还牙。",["faction:Horde"]="野猪人威胁着杜隆塔尔、莫高雷和南贫瘠之地之间重要的旅行路线，这使得曼科里克的个人复仇行动与保障部落领地安全直接挂钩。",["race:Orc"]="曼科里克的悲痛以及为阵亡亲人复仇的坚定决心，与传统的兽人荣誉感以及在卡利姆多开拓家园的艰辛现实产生了深刻的共鸣。"},sec={{t="丈夫的复仇",b="站在十字路口烈日下的曼科里克是一位被悲伤所困的战士。在幸存于一场让他遍体鳞伤且妻子下落不明的野猪人残忍袭击后，他终日盯着干旱的地平线，寻找任何关于这些猪人的迹象。尽管他已亲手斩杀了许多野猪人，但他对它们鲜血的渴望仍未得到满足，这驱使他向部落的同胞寻求帮助。"},{t="刺鬃的獠牙",b="曼科里克并未寻求平静或慰藉，而是要求以纯粹的杀戮作为战利品：六十根刺鬃野猪人獠牙。对他而言，每一根碎裂的獠牙都代表着对他那破碎生活的报复，是对那些怪物所施加痛苦的一种偿还。虽然堆积的尸骨无法治愈他的悲伤，也无法平息他的复仇欲望，但看到刺鬃野猪人流血，能给这位受伤的战士带来片刻苦涩的满足。"}},faq={{q="曼科里克为什么要六十根野猪人獠牙？",a="曼科里克在一场让他与妻子失散的残忍野猪人伏击后，彻底被悲伤和愤怒所吞噬。六十根獠牙是一个刻意设定的残酷数字，旨在对刺鬃部族造成沉重的人员伤亡，看着折磨他的人受苦，能带给他些许慰藉。",al={"为什么需要60根獠牙","曼科里克的獠牙任务","为什么要这么多獠牙"}},{q="这个任务发生在哪里？",a="曼科里克在贫瘠之地中部的十字路口提供此任务，派遣冒险者对抗那些盘踞在附近灌木丛和荆棘堡垒中的刺鬃野猪人。",al={"为仇恨所困任务地点","为仇恨所困位置"}},{q="上交獠牙能满足曼科里克的复仇吗？",a="并不完全能。曼科里克承认，虽然他对复仇的渴望仍未满足，但看到野猪人遭受惨重损失让他脸上露出了阴郁的笑容，这表明它们终于感受到了他所承受的痛苦。",al={"曼科里克会停止仇恨野猪人吗","曼科里克任务结局"}},{q="曼科里克为什么要提到陶拉祖营地？",a="在痛苦的沉思中，曼科里克不禁想道，在那场伏击之后，他是否应该向南逃往陶拉祖营地，而不是向北逃往十字路口。他质疑如果当初选择了另一条路，战斗的结果和他的搜寻工作是否会有所不同。",al={"为什么要提到陶拉祖","陶拉祖营地与曼科里克"}},{q="什么是刺鬃部族？",a="刺鬃部族是贫瘠之地土生土长的侵略性野猪人部族。他们极具领地意识且排外，不断与部落发生冲突，并从他们那荆棘丛生的营地中袭击横穿平原的旅行者。",al={"什么是刺鬃部族","刺鬃部族"}},{q="这与寻找曼科里克的妻子有关吗？",a="是的。曼科里克灼人的仇恨直接源于那场让他和妻子被压制的伏击。当冒险者们在配套任务“被遗忘的战火”中搜寻平原以试图发现她的下落时，这项任务代表了他对袭击者进行报复的强烈渴望。",al={"与被遗忘的战火的联系","寻找曼科里克的妻子任务"}}},fp="18,220,21.290.0,24.286.0,43.200.0,33.137.0,52.132.0,38.167.0,25.231.0,44.197.0"}
P.entries["quest:9"] = {n="清理荒野",s="“杀戮之地”是联盟的一项任务，由西部荒野的农夫萨丁发布。萨丁委派冒险者去摧毁那些践踏了他的庄稼和邻近农田的失控的收割机傀儡。它揭示了在迪菲亚潜行者的破坏下，当地农业的崩溃。",h="“杀戮之地”是联盟的一项任务，由西部荒野的农夫萨丁发布。萨丁委派冒险者去摧毁那些践踏了他的庄稼和邻近农田的失控的收割机傀儡。它揭示了在迪菲亚潜行者的破坏下，当地农业的崩溃。",kw={"发条","迪菲亚","农夫萨丁","收割机傀儡","杀戮之地","萨丁农场","稻草人","西部荒野"},ang={["faction:Alliance"]="对于联盟的旅行者来说，帮助萨丁代表着一种直接的努力，旨在保护这一被暴风城王室所遗弃的领地中为数不多的幸存粮食来源之一。",["profession:Engineering"]="工程师们会认出这些收割机傀儡，它们原本是自动化的发条奇迹，但因缺乏适当的维护而陷入了混乱。"},sec={{t="饱受困扰的家园",b="当强盗和歹徒横扫西部荒野时，许多农民放弃了他们的土地，但农夫萨丁和他的家人决定坚守阵地。不幸的是，非法入侵的盗贼并非威胁萨丁农场的唯一隐患。本用于照料和保护谷物的机械收割机傀儡已经陷入疯狂，它们在田垄间徘徊，并攻击任何靠近的人。"},{t="清理土地",b="为了维持农场的正常运作，萨丁招募路过的旅行者去摧毁他农场及周边地块上的二十个敌对构装体。清除这些构装体为萨丁的收成提供了暂时的喘息机会，也保留了一丝难得的、关于西部荒野这座粮仓有朝一日终能恢复往日荣光的顽强希望。"}},faq={{q="谁发布了“杀戮之地”任务？",a="农夫萨丁在位于西部荒野中部路边的萨丁农场发布该任务。",al={"杀戮之地任务发布者","谁发布杀戮之地","萨丁任务"}},{q="什么是收割机傀儡？",a="收割机傀儡是发条驱动的稻草人，旨在照料农作物并保护田地免受害虫侵害。随着西部荒野的动荡和荒废，许多这种机械构装体无人照管或遭到重编程，转而攻击它们本应服务的农民。",al={"什么是收割机傀儡","收割机傀儡背景故事","西部荒野机械稻草人"}},{q="为什么农夫萨丁没有像其他人一样逃离西部荒野？",a="与那些将家园留给盗贼和歹徒的邻居不同，萨丁拒绝放弃他的生计。他在雇佣的冒险者的帮助下，顽强地维护着自己的土地，抵御那些失控的机械。",al={"为什么萨丁还留在这里","农夫萨丁背景故事","萨丁坚守"}},{q="“杀戮之地”的目标是什么？",a="你的任务是摧毁徘徊在萨丁的农田以及周边废弃农场中的二十个收割机傀儡。",al={"杀戮之地目标","收割机傀儡数量","杀戮之地击杀目标"}},{q="萨丁提到的“盗贼”是谁？",a="萨丁指的是在迪菲亚潜行者组织下松散集结的盗贼和歹徒，他们的掠夺和勒索迫使大多数农民离开了自己的土地。",al={"谁是盗贼","萨丁盗贼","谁将农民赶出了西部荒野"}},{q="完成这项任务能解决西部荒野的农业问题吗？",a="摧毁那二十个收割机傀儡能为萨丁的农场提供暂时的喘息之机，但整个地区面临的巨大强盗威胁和机械故障问题依然没有解决。",al={"西部荒野会恢复吗","杀戮之地结局","萨丁的处境"}}},fx={a141c1eb={q="农夫萨丁为什么要杀死收割傀儡？",a="农夫萨丁是为数不多的拓荒者之一，尽管西部荒野已经衰败，他仍不愿放弃自己的土地。曾经养活暴风城的田野如今已沦为废墟，长满杂草，还被失控的机械收割傀儡占据。萨丁希望摧毁这些失控的自动机械，让他和其他留守的人有机会重新开垦土地，使西部荒野再度兴盛。",al={"为什么要杀收割傀儡","萨丁在杀戮之地的动机","农夫萨丁的理由"}},["05cf05c3"]={q="为什么农夫萨丁需要冒险者帮忙，而不是亲自对付收割傀儡？",a="萨丁只是个普通农夫，想保护自己的家园和家人，却没有王室卫兵或士兵前来援助。暴风城驻扎在西部荒野的军力已经所剩无几，当地农民面对武装窃贼和致命的故障农耕机器，毫无自保之力。独自面对二十个收割傀儡无异于自寻死路，因此武装冒险者是他唯一的希望。",al={"萨丁为什么不能自己动手","为什么在杀戮之地找我帮忙","萨丁为什么需要帮助"}}},fp="18,223,23.296.0,17.264.0,40.97.0,26.239.0,57.204.0,46.110.0,39.153.0,59.157.0"}
P.entries["quest:90"] = {n="干烤狼肉串",s="“调味狼肉串”是夜色镇血鸦旅店的厨师格鲁奥提供的一项联盟烹饪任务。格鲁奥想要烹制他的招牌菜，于是委托冒险者前往暮色森林猎杀野狼以获取肉类，而他的调味香草则是从暴风城运来的。该任务突显了在这个被围困的村庄中，人们为了生存所面临的挑战以及他们需要发挥的聪明才智。",h="“调味狼肉串”是夜色镇血鸦旅店的厨师格鲁奥提供的一项联盟烹饪任务。格鲁奥想要烹制他的招牌菜，于是委托冒险者前往暮色森林猎杀野狼以获取肉类，而他的调味香草则是从暴风城运来的。该任务突显了在这个被围困的村庄中，人们为了生存所...",kw={"厨师格鲁奥","夜色镇","暮色森林","瘦狼肋排","血鸦旅店","暴风城","狼肉串"},ang={["class:Hunter"]="追踪暮色森林中贪婪的狼群需要经典的追踪和捕杀技巧，这样既能保护村庄，又能确保酒馆的储备充足。",["faction:Alliance"]="夜色镇和暴风城之间的物流运输证明了王国中孤立的定居点是如何依赖首都市场的，即使在军事驻军被撤回的情况下也是如此。",["profession:Cooking"]="厨师格鲁奥的食谱教导冒险者，荒野猎人是如何通过精致的城市香料掩盖野味特有的腥味，从而利用强韧的食肉动物肉质的。"},sec={{t="夜色镇的菜肴",b="夜色镇是一个被暮色森林中潜藏的恐怖事物所包围的孤立定居点，商队很少涉足此地，传统的农业也已完全崩溃。尽管阴霾笼罩，亡灵四伏，但镇上的居民仍需果腹。掌管血鸦旅店厨房的厨师格鲁奥充分利用了森林中危险的动物，将野狼肉制作成可口的烤肉串。由于当地的木材和土壤无法种植精细的农作物，格鲁奥只能依靠从首都运来的特殊香料来去除这种野味特有的腥味。"},{t="来自暴风城的货物",b="要完成格鲁奥的食谱，旅行者只需要从潜伏在暮色森林的凶猛野狼身上获取瘦肉。格鲁奥刚刚收到了他订购的暴风城调味香草，所以现在只差肉了。这批货物突显了夜色镇与更广阔王国之间脆弱的联系：虽然王室的军事援助已经减少，但城市商人和外围村庄之间小规模的民事联系和供应线依然勉强维持着。"}},faq={{q="厨师格鲁奥是谁？",a="厨师格鲁奥是夜色镇血鸦旅店的驻店厨师。他负责为顾客、当地居民和守夜人成员提供食物，利用在周围树林中捕获的猎物制作丰盛的饭菜。",al={"厨师格鲁奥","格鲁奥 夜色镇","谁发布调味狼肉串任务"}},{q="去哪里获取暴风城调味香草？",a="你不需要去寻找它们。厨师格鲁奥刚刚收到了他订购的暴风城调味香草，所以他现在只需要你提供10块瘦狼肋排。",al={"暴风城香草位置","调味香草在哪里"}},{q="在哪里可以找到掉落狼肋排的野狼？",a="野狼在暮色森林的阴暗树林中四处游荡，尤其是在夜色镇外的树林和小径中潜伏。当地的任何野狼都可以产出厨师格鲁奥所需的瘦肉。",al={"瘦狼肋排位置","狼肋排 暮色森林","哪里狩猎野狼"}},{q="为什么夜色镇需要狼肉来作为食物？",a="暮色森林的农田被毁，又被怪物切断了外界联系，使得传统的畜牧和农作物种植几乎不可能进行。当地人通过捕猎边界外徘徊的危险野生动物（包括随处可见的野狼）来生存。",al={"为什么吃狼肉","夜色镇食物供应","为什么制作狼肉串"}},{q="为什么格鲁奥不能在暮色森林当地获取香草？",a="暮色森林中弥漫的诅咒已经腐蚀了大部分原生植物，几乎找不到什么可食用的或有香味的烹饪香草。格鲁奥必须依赖从暴风城进口的栽培品种来为他的菜肴调味。",al={"为什么在暴风城购买香草","暮色森林香草"}},{q="这个任务与更大的故事情节有关联吗？",a="这只是一个独立的本地风味任务，而不是宏大叙事的一部分。然而，它生动地展示了夜色镇居民质朴、自力更生的生活方式，以及他们与暴风城之间持续存在且脆弱的物资供应联系。",al={"狼肉串剧情意义","调味狼肉串任务重要吗"}}},fp="20,171,20.398.0,25.308.0,18.185.0,47.131.0,47.154.0,43.195.0,46.191.0,44.157.0"}
P.entries["quest:900"] = {n="什么什么平衡器",s="此任务需要关闭贫瘠之地北部支持荆棘谷地精挖掘作业的复杂机械。通过切断三个独立的控制阀，冒险者可以安全地关闭中央装置。关闭这些阀门会停止维持机器运转的不稳定燃料流和压力。",h="此任务需要关闭贫瘠之地北部支持荆棘谷地精挖掘作业的复杂机械。通过切断三个独立的控制阀，冒险者可以安全地关闭中央装置。关闭这些阀门会停止维持机器运转的不稳定燃料流和压力。",kw={"贫瘠之地","控制台","燃料阀","调节阀","萨莫弗兰吉","淤泥沼泽","荆棘谷地精"},ang={["faction:Horde"]="阻止荆棘谷地精的机器可以保护贫瘠之地北部免受肆无忌惮的工业开采。",["profession:Engineering"]="工程师们会认出这种经典的地精设计：动力过剩、不稳定的燃料管线，且几乎没有自动故障保护装置，需要手动关闭以避免灾难性的压力反冲。"},sec={{t="驯服装置",b="荆棘谷地精在淤泥沼泽的机械装置既复杂又危险。面对中央控制台时，仪表和指示器清楚地表明核心机制不能仅仅通过拨动开关来关闭。为了防止爆炸或机械故障，必须先手动处理输送管线。"},{t="三个阀门",b="有三个不同的阀门控制着进入钻机的流量：主控制阀、燃料控制阀和调节阀。每一个都必须在高压下手动密封。随着每个阀门的关闭，控制台上的发光状态指示灯会从绿色变为黄色，最终允许安全地启动中央关闭机制。"}},faq={{q="关闭这些阀门的目的是什么？",a="控制台监视着流入机器的压力管线和燃料管线。在管线开启时尝试关闭装置可能会损坏设备或引发灾难，因此必须预先密封燃料、调节和主管线。",al={"为什么要关闭阀门","萨莫弗兰吉阀门的作用","阀门有什么作用"}},{q="所有三个阀门关闭后会发生什么？",a="关闭三个阀门会降低内部压力并切断燃料。控制台上闪烁的指示灯会变暗并从绿色变为黄色，从而使主关闭开关最终可以自由移动。",al={"控制台指示灯","阀门关闭后做什么"}},{q="这台机器是谁建造的？",a="该装置由荆棘谷地精建造，这是一个在贫瘠之地北部开采石油和原始资源的冷酷地精贸易集团。",al={"谁制造了萨莫弗兰吉","荆棘谷地精机械"}},{q="阀门位于何处？",a="这三个阀门位于贫瘠之地荆棘谷地精挖掘现场的中央控制台和主要机械装置周围。",al={"阀门位置","阀门在哪里"}},{q="部落为什么对这个装置感兴趣？",a="荆棘谷地精的重工业破坏了贫瘠之地，并侵犯了部落的领土。了解并破坏他们的技术有助于遏制他们的破坏性开采。",al={"为什么部落会关心","部落与萨莫弗兰吉"}},{q="什么是萨莫弗兰吉？",a="萨莫弗兰吉是一种晦涩难懂的地精技术组件，非工程师很少能理解其确切的内部功能，尽管它似乎是高压钻探设备必不可少的部件。",al={"萨莫弗兰吉的含义","什么是萨莫弗兰吉"}}},fp="11,165,20.235.0,16.256.0,49.139.0,46.178.0,23.125.0,29.120.0,43.158.0,22.169.0"}
P.entries["quest:901"] = {n="什么什么平衡器",s="这个任务是关闭北贫瘠之地淤泥沼泽中荆棘谷地精机械的关键步骤。在已经关闭了周围的阀门后，执行者必须从修补匠斯尼格斯手中获得控制台钥匙，才能打开主控制单元并取出神秘的萨摩弗兰奇。",h="这个任务是关闭北贫瘠之地淤泥沼泽中荆棘谷地精机械的关键步骤。在已经关闭了周围的阀门后，执行者必须从修补匠斯尼格斯手中获得控制台钥匙，才能打开主控制单元并取出神秘的萨摩弗兰奇。",kw={"贫瘠之地","控制台钥匙","萨摩弗兰奇","淤泥沼泽","斯尼格斯","荆棘谷地精"},ang={["faction:Horde"]="破坏荆棘谷地精在淤泥沼泽中的设备有助于减缓他们对整个北卡利姆多的剥削和有毒径流排放。",["profession:Engineering"]="在开启外壳之前将钻探平台的仪表调整至空闲状态的细致过程，展示了地精虽然古怪但标准的机械安全协议。"},sec={{t="解锁机制",b="在物理取出核心部件之前，必须将机械彻底断电并解锁。随着辅助阀门被关闭，压力得到释放，终端的仪表和量表会进入空闲状态。然而，为了防止破坏，外壳仍然紧锁着，需要由负责监督钻井工地的地精总工程师持有的物理钥匙来开启。"},{t="修补匠斯尼格斯",b="荆棘谷地精依靠修补匠斯尼格斯来监管淤泥沼泽中工业设备的微妙平衡。斯尼格斯随身携带着控制台钥匙，住在主钻探平台东北方向附近的一间小屋里。击败这位工程师是执行者获取嵌套在机壳内的萨摩弗兰奇前必须跨越的最后障碍。"},{t="电力消耗",b="在控制台插入斯尼格斯的钥匙可以打开锁住的外壳。随着最后一声咔哒声，框架上的红色指示灯熄灭，持续的电流嗡嗡声也完全消失了。控制台的故障保护装置解除，使得内部核心可以被取出。"}},faq={{q="修补匠斯尼格斯在哪里？",a="修补匠斯尼格斯位于北贫瘠之地淤泥沼泽中主控制台东北方向的一间小型地精小屋内。",al={"寻找斯尼格斯","斯尼格斯位置","修补匠斯尼格斯在哪里"}},{q="控制台钥匙有什么用途？",a="控制台钥匙可以解锁淤泥沼泽的主控制终端，排空系统中剩余的电力，以便取出里面的萨摩弗兰奇。",al={"控制台钥匙用途","钥匙打开什么","如何使用控制台钥匙"}},{q="为什么在使用钥匙之前必须先关闭控制台？",a="必须先通过放气阀使机械进入空闲状态。在满负荷运转的压力下试图解锁和操作机械是非常危险的。",al={"为什么先要关闭","钥匙之前的阀门"}},{q="修补匠斯尼格斯为谁工作？",a="修补匠斯尼格斯是一名受雇于荆棘谷地精的工程师。荆棘谷地精是一个正在蹂躏北贫瘠之地的冷酷贸易和资源开采集团。",al={"斯尼格斯所属派系","斯尼格斯是荆棘谷地精吗"}},{q="什么是萨摩弗兰奇？",a="萨摩弗兰奇是一种深奥且复杂的工程组件，对于荆棘谷地精重型钻探和泵送机械的运作至关重要。",al={"萨摩弗兰奇的含义","什么是萨摩弗兰奇"}},{q="在控制台上使用钥匙后会发生什么？",a="解锁终端会切断控制台的所有电源，关闭警示灯，并让你能够取回萨摩弗兰奇本身。",al={"接下来发生什么","使用控制台钥匙后"}}},fp="11,180,23.212.0,17.219.0,11.194.1,35.122.0,33.141.0,62.124.0,36.113.0,22.118.0,48.118.0"}
P.entries["quest:902"] = {n="什么什么平衡器",s="这个任务标志着对贫瘠之地北部荆棘谷地精机械调查的终结。在拆除系统防御并关闭控制台后，你取出了难以捉摸的萨莫佛兰奇，并把它带回棘齿城进行评估。事实证明，它比任何人预想的都要挑剔和脆弱得多。",h="这个任务标志着对贫瘠之地北部荆棘谷地精机械调查的终结。在拆除系统防御并关闭控制台后，你取出了难以捉摸的萨莫佛兰奇，并把它带回棘齿城进行评估。事实证明，它比任何人预想的都要挑剔和脆弱得多。",kw={"控制台","棘齿城","萨莫佛兰奇","斯布特瓦夫","贫瘠之地","修补匠工会","安德麦","荆棘谷地精"},ang={["faction:Horde"]="与棘齿城的地精港口打交道意味着要处理不稳定的荆棘谷地精废料，这提醒当地的部落冒险者，中立的地精企业往往伴随着爆炸性的无能。",["profession:Engineering"]="萨莫佛兰奇让修补匠们面对着一台荆棘谷地精机器，其密集的线路、管道和陌生的零件引人深思。"},sec={{t="发掘核心",b="在荆棘谷地精控制台的面板后面，隐藏着令人费解的错综线路、毫无用处的管道和特立独行的工程设计。在这个机械迷宫的最深处，放置着让该地区工程师们困惑不已的核心部件：萨莫佛兰奇。只要用力一拉，该装置就会从外壳中脱落，准备好交给那位发起整个回收工作的地精。"},{t="脆弱的创新",b="回到棘齿城，斯布特瓦夫急切地拿走了这个奇特的装置，承诺将把它送到位于安德麦的修补匠工会总部进行彻底研究。然而，地精的好奇心却害了他。就在他放下萨莫佛兰奇想急切地进行初步观察时，这个精致的机械瞬间在地面上摔得粉碎，留下他在一旁手忙脚乱地抢救研究资料。"}},faq={{q="萨莫佛兰奇到底是什么？",a="即使对经验丰富的机械师来说，萨莫佛兰奇也是一堆令人难以理解的电线、管道和小零件的集合体。虽然它表面上是荆棘谷地精控制台内部的关键部件，但无论是斯布特瓦夫还是那些拾荒者，都从未完全弄懂它是如何运作的。",al={"什么是萨莫佛兰奇","萨莫佛兰奇的用途","它的作用是什么"}},{q="为什么斯布特瓦夫想要萨莫佛兰奇？",a="斯布特瓦夫打算将该部件运往安德麦的修补匠工会总部。那里的地精发明家以逆向工程和研究竞争对手的技术设计而闻名——前提是该装置在接受检查前还能保持完好。",al={"为什么斯布特瓦夫想要它","谁想要萨莫佛兰奇"}},{q="当你交出萨莫佛兰奇时会发生什么？",a="斯布特瓦夫打算把萨莫佛兰奇送到安德麦的修补匠工会，尽管他自己也很好奇，想先检查一下。",al={"萨莫佛兰奇会坏掉吗","斯布特瓦夫拿它做什么"}},{q="是谁建造了容纳该装置的控制台？",a="控制台和萨莫佛兰奇是由在贫瘠之地北部的淤泥沼泽开展业务的荆棘谷地精建造的。他们的行动以粗制滥造、高污染的技术实验而臭名昭著。",al={"谁制造了萨莫佛兰奇","控制台制造者"}},{q="斯布特瓦夫在这之后会派你去哪里？",a="调查将继续进行，斯布特瓦夫的合伙人维尼基·螺栓桶（维妮·布特巴克）是贫瘠之地的另一位工程师。",al={"萨莫佛兰奇之后的下一个任务","下一步要做什么"}},{q="斯布特瓦夫在哪里？",a="斯布特瓦夫站在码头上，在位于贫瘠之地东海岸的港口城镇棘齿城内的工作间里工作。",al={"斯布特瓦夫位置","斯布特瓦夫在哪里","在哪里上交萨莫佛兰奇"}}},fp="11,183,19.329.0,19.332.1,31.249.0,43.189.0,48.120.1,49.183.0,44.92.1,30.109.0"}
P.entries["quest:903"] = {n="草原上的徘徊者",s="“贫瘠之地的徘徊者”是塞格拉·黑棘在十字路口布置的一项狩猎仪式。作为考验冒险者战斗能力系列任务的一部分，猎人们需要潜入高耸的草原草丛，追踪那些隐匿其中的食肉性草原徘徊者。带回它们的爪子，即证明了一个人有资格去挑战平原上最强大的野兽。",h="“贫瘠之地的徘徊者”是塞格拉·黑棘在十字路口布置的一项狩猎仪式。作为考验冒险者战斗能力系列任务的一部分，猎人们需要潜入高耸的草原草丛，追踪那些隐匿其中的食肉性草原徘徊者。带回它们的爪子，即证明了一个人有资格去挑战平原上最...",kw={"十字路口","伊萨克","狩猎","徘徊者的爪子","徘徊者","草原徘徊者","塞格拉·黑棘","贫瘠之地"},ang={["class:Hunter"]="在高大的灌木丛中追踪草原徘徊者，能为追踪、潜行侦测以及制服具有攻击性的猫科野兽提供必要的训练。",["faction:Horde"]="平定十字路口周边的荒野，能确保往来于杜隆塔尔、莫高雷和南部哨所之间的补给车队安全通行。",["race:Tauren"]="虽然血腥，但清除流氓掠食者能维护自然平衡，并保护那些穿越祖辈狩猎地的脆弱商队。"},sec={{t="真正的掠食者",b="在证明了自己有能力对抗平原上胆小的平原陆行鸟和顽固的斑马之后，渴望获得塞格拉·黑棘认可的猎人们将面临一项更致命的挑战。草原徘徊者是贫瘠之地中部的顶级潜行者，它们潜伏在十字路口西南方金黄与赭红色的灌木丛中。不同于吃草的畜群，这些大猫会进行蓄意狩猎，从高草丛中伏击猎物，将毫无防备的旅人变成受害者。"},{t="掠食者还是猎物",b="塞格拉·黑棘强调了追踪以狩猎为生的野兽所固有的风险。想要获得它们的爪子，冒险者必须学会观察草丛，并在猫科动物扑击之前出击。收集七只徘徊者的爪子，证明了一名猎人拥有在遭遇卡利姆多最致命的动物时生存所必需的狡黠与反应速度。"},{t="迈向勇士之路",b="带着一把爪子成功归来，证实了猎人已经掌握了开阔草原上的基础生存技能。塞格拉对这种展现出的战斗技巧感到满意，并准备让猎人进行一项真正英勇的试炼：召唤并击杀伊萨克，那头被视为贫瘠之地掠食者中勇士的白狮。"}},faq={{q="是谁提供了这项狩猎任务？",a="塞格拉·黑棘，一位驻扎在贫瘠之地十字路口的经验丰富的兽人，将这项狩猎任务作为传统狩猎仪式晋升的一部分分配出去。",al={"任务发布者","谁发布了徘徊者任务","塞格拉·黑棘"}},{q="草原徘徊者位于何处？",a="它们潜伏在十字路口西南方的高草丛中，隐藏在草甸里，以此捕食斑马和毫无戒心的旅人。",al={"徘徊者在哪里","徘徊者位置","哪里能找到草原徘徊者"}},{q="塞格拉需要什么样的战利品？",a="猎人必须切下并带回七只徘徊者的爪子，以证明他们在正面战斗中战胜了这些猫科动物。",al={"我需要什么","徘徊者任务物品","爪子"}},{q="这项狩猎任务通向哪里？",a="击杀徘徊者证明你已准备好挑战伊萨克，那头贫瘠之地著名的白狮。",al={"下一个任务","徘徊者任务之后是什么","伊萨克"}},{q="为什么塞格拉要让旅人去狩猎掠食者？",a="除了清除威胁道路的危险野兽外，塞格拉的试炼还考验猎人是否理解掠食者与猎物之间的平衡，并在他们面对更大的威胁之前剔除掉鲁莽之辈。",al={"为什么要狩猎徘徊者","狩猎目的","背景故事原因"}},{q="草原徘徊者对定居点有危险吗？",a="虽然徘徊者很少直接袭击像十字路口这样设防的营地，但它们潜伏在南部道路附近，并主动捕食旅人、信使和驮兽。",al={"徘徊者会攻击十字路口吗","对十字路口的威胁"}}},fp="23,151,15.303.0,16.222.0,28.246.1,21.125.0,40.135.0,37.119.0,28.105.1,46.195.0,50.146.0"}
P.entries["quest:905"] = {n="狂暴的镰爪龙",s="瑟格拉·黑棘派遣雄心勃勃的猎手前往十字路口以南，去对抗潜伏在贫瘠之地的凶猛镰爪龙。通过收集日鳞迅猛龙的羽毛并将其直接放置在野兽的繁殖巢穴中，猎手们证明了自己的勇气，并在充满敌意的荒野中赢得了尊重。",h="瑟格拉·黑棘派遣雄心勃勃的猎手前往十字路口以南，去对抗潜伏在贫瘠之地的凶猛镰爪龙。通过收集日鳞迅猛龙的羽毛并将其直接放置在野兽的繁殖巢穴中，猎手们证明了自己的勇气，并在充满敌意的荒野中赢得了尊重。",kw={"十字路口","蛋","黄金之路","巢穴","迅猛龙巢穴","迅猛龙","镰爪龙","瑟格拉·黑棘","死水绿洲","日鳞"},ang={["class:Hunter"]="进入领地型掠食者的繁殖巢穴以挑战其统治地位，是卡利姆多所见过的最直接的荒野生存技巧的应用之一。",["faction:Horde"]="黄金之路沿线的迅猛龙群不断威胁着在十字路口和南部哨站之间往来的重要商队和落单的信使。",["race:Orc"]="在严酷的野生环境中考验自己，反映了兽人的核心信仰，即在杜隆塔尔和贫瘠之地生存需要力量、坚韧和坚定的意志。"},sec={{t="胆量的考验",b="对于瑟格拉·黑棘而言，在贫瘠之地狩猎绝不仅仅是为了杀戮；这是一种持久的成年仪式。在已经让旅行者面对过较弱的野兽进行考验后，她指派猎手去寻找十字路口南部的邪恶日鳞迅猛龙。获取它们的羽毛只是初步的试炼。为了真正证明自己的实力，猎手必须将这些战利品直接带入死水绿洲西南方的迅猛龙领地中心，亵渎它们的巢穴，以彰显无所畏惧的气概。"},{t="镰爪龙巢穴",b="在死水绿洲的西南方，靠近黄金之路的地方，有三个独特的迅猛龙巢穴——以独特的红色、蓝色和黄色蛋为标志——它们是好斗的镰爪龙的公共活动地。进入这些筑巢点非常危险，因为迅猛龙会猛烈地保卫它们的巢穴，攻击任何靠近的东西。将倒下同类的羽毛直接放入这些巢穴中，是对这些野兽不可置疑的统治宣言。"},{t="荒原的磨砺",b="在勇闯巢穴后回到十字路口，这展现的不仅仅是武艺——它证明了干旱的平原正在重塑这位猎手。正如瑟格拉在任务完成后所观察到的，活着走出迅猛龙的巢穴需要相当大的胆量。在贫瘠之地残酷的生态系统中，每一次对抗要么让渴望成为战士的人变得坚韧，要么就会将他们的遗骨留在散落在尘土中的科多兽残骸之间。"}},faq={{q="为什么瑟格拉·黑棘要我把羽毛放到迅猛龙巢穴里？",a="瑟格拉·黑棘希望你展现至高无上的统治力和勇气。通过猎杀日鳞迅猛龙并将它们的羽毛直接插在它们有颜色的繁殖巢穴中，你向它们的族群和亲属证明你并不惧怕它们。",al={"为什么要去镰爪龙巢穴","巢穴中羽毛的目的","为什么要亵渎巢穴"}},{q="镰爪龙巢穴在哪里？",a="这些巢穴位于十字路口以南，死水绿洲的西南方，靠近黄金之路。它们坐落在路边沟渠以东的一个小山丘附近，那里有巨大的科多兽骨头作为标记。",al={"巢穴的位置","镰爪龙巢穴地点","红黄蓝巢穴位置"}},{q="贫瘠之地的这一带生活着什么样的迅猛龙？",a="该地区栖息着日鳞镰爪龙及其同类。它们是狡猾、好斗的爬行动物掠食者，成群结队地狩猎，并在黄金之路和附近的迅猛龙巢穴周围激烈地保卫着它们的巢穴。",al={"贫瘠之地的迅猛龙种类","日鳞迅猛龙","什么是镰爪龙"}},{q="我在哪里收集日鳞羽毛？",a="日鳞羽毛可以从游荡在十字路口以南平原，以及通往东部丘陵的邻近迅猛龙巢穴地区的日鳞迅猛龙和镰爪龙身上掉落。",al={"在哪里获取羽毛","日鳞羽毛掉落","如何获取迅猛龙羽毛"}},{q="瑟格拉·黑棘是谁？",a="瑟格拉·黑棘是一位驻扎在十字路口的经验丰富的兽人。她通过派遣新抵达的部落冒险者前往贫瘠之地进行试炼，来评估他们的生存本能和战斗纪律。",al={"谁是瑟格拉","瑟格拉·黑棘的背景故事"}},{q="这个任务会引向其他狩猎吗？",a="会。这项任务是瑟格拉·黑棘在贫瘠之地更广泛的狩猎系列任务的一部分，最终将引向对贫瘠之地海岸外传说中的海兽——伊沙·觉醒的狩猎。",al={"愤怒的镰爪龙后续任务","十字路口狩猎任务链","巢穴之后的下一个任务"}}},fp="21,197,15.345.0,20.294.0,23.269.0,70.184.0,39.183.0,55.188.0,41.177.0,24.196.0,36.141.1"}
P.entries["quest:906"] = {n="内奸",s="“内部的背叛”是一项部落任务，标志着对在贫瘠之地中部发动激进袭击的刺鬃猪人领袖的狩猎行动告一段落。通过将洛克·奥克班恩的头颅带给十字路口的索克，玩家证明了这位猪人部族最凶残的战术家终于陨落了。",h="“内部的背叛”是一项部落任务，标志着对在贫瘠之地中部发动激进袭击的刺鬃猪人领袖的狩猎行动告一段落。通过将洛克·奥克班恩的头颅带给十字路口的索克，玩家证明了这位猪人部族最凶残的战术家终于陨落了。",kw={"阿迦玛甘","贫瘠之地","陶拉祖营地","十字路口","洛克·奥克班恩","碎牙","猪人","刺鬃","索克"},ang={["faction:Horde"]="洛克·奥克班恩的死亡保障了陶拉祖营地和十字路口之间重要的交通走廊，削弱了刺鬃猪人对卡利姆多新定居点的威胁。",["race:Orc"]="洛克的姓氏“奥克班恩”（意为“兽人克星”）直观地反映了他长期以来在干旱平原上屠杀兽人定居者和补给车队的罪行。"},sec={{t="叛徒的头颅",b="被关在陶拉祖营地笼子里的刺鬃猪人俘虏碎牙透露，是洛克·奥克班恩指使了针对部落大篷车的野蛮袭击。当那位酋长在南部荆棘迷宫深处被杀后，碎牙交出了洛克的颅骨，并对兽人们在毫无察觉的情况下，因为猪人部族内部的背叛而获利感到好笑。"},{t="巩固十字路口",b="将洛克那令人毛骨悚然的战利品带到十字路口交给索克，减轻了整个中部草原部落补给线所面临的巨大压力。索克难以置信居然有一个孤身旅行者设法击败了这位强悍的领袖，并承认他原本以为这些有组织的袭击背后另有主谋。洛克的死瓦解了刺鬃的攻势，使他们的山脊群失去了组织。"}},faq={{q="谁是碎牙？",a="碎牙是被关在陶拉祖营地木笼中的一名刺鬃猪人俘虏。因为被自己的部族抛弃而心怀怨恨，他引导部落的冒险者去刺杀他部族的督军，以此进行报复。",al={"碎牙","被俘的猪人","陶拉祖俘虏"}},{q="洛克·奥克班恩是谁？",a="洛克·奥克班恩是刺鬃部族中一位著名的酋长，他策划了针对部落前哨站以及蜿蜒穿过贫瘠之地的补给线的凶猛伏击。",al={"洛克","洛克·奥克班恩","刺鬃领袖"}},{q="为什么索克关心洛克的死？",a="作为保卫十字路口的指挥官，索克负责协调防御，抵御那些盘踞在荆棘丛中的袭击者。消灭洛克·奥克班恩等于除掉了策划黄金之路沿线袭击的主要战术家。",al={"为什么索克要洛克死","十字路口补给袭击"}},{q="碎牙为什么要协助消灭他自己的酋长？",a="碎牙对部族的领导层怀有深深的怨恨，并且比起同族，他更崇尚纯粹的力量。通过指引部落的勇士处决洛克，他在发泄仇恨的同时，也隔着牢笼维持着他与阿迦玛甘之间的神秘联系。",al={"碎牙为何背叛","碎牙的动机"}},{q="这个任务链通向哪里？",a="这次交付任务标志着这一系列直接暗杀任务的结束，不过碎牙仍会用阿迦玛甘的元素祝福来换取从贫瘠之地各处猪人身上收集到的血岩碎片。",al={"“内部的背叛”之后的后续任务","“内部的背叛”后续"}},{q="索克在哪里？",a="索克在贫瘠之地中北部十字路口定居点内守卫，监督着防御行动和后勤工作。",al={"索克的位置","索克在哪里"}}},fp="20,189,16.376.0,23.349.1,19.182.0,20.139.0,38.184.0,53.227.0,33.191.0,23.117.0"}
P.entries["quest:907"] = {n="被激怒的雷霆蜥蜴",s="“愤怒的雷霆蜥蜴”是陶拉祖营地的乔恩·天视给予的一项部落狩猎试炼。作为穿越贫瘠之地的一系列成人礼的一部分，猎人们的任务是面对游荡在南部平原上的巨大雷霆蜥蜴，并取回它们的血液。",h="“愤怒的雷霆蜥蜴”是陶拉祖营地的乔恩·天视给予的一项部落狩猎试炼。作为穿越贫瘠之地的一系列成人礼的一部分，猎人们的任务是面对游荡在南部平原上的巨大雷霆蜥蜴，并取回它们的血液。",kw={"贫瘠之地","陶拉祖营地","愤怒的雷霆蜥蜴","乔恩·天视","风暴兽皮龙","风暴口鼻龙","雷首龙"},ang={["class:Hunter"]="对付雷霆蜥蜴考验的是你的脚步，要在保持距离避开毁灭性践踏的同时，消耗掉这个拥有厚重兽皮的对手。",["faction:Horde"]="猎杀这些狂暴的野兽可以确保陶拉祖营地周边的道路安全，保护商队和在南贫瘠之地穿行的旅行战士。",["race:Tauren"]="对于舒哈鲁人来说，狩猎陶拉祖营地周围巨大的雷霆蜥蜴是展示他们祖辈平原上尊重、坚毅和平衡的传统方式。"},sec={{t="南部平原的考验",b="在证明了自己对抗迅猛龙伊沙姆哈尔的实力后，猎人们回到了陶拉祖营地。在那里，牛头人长者乔恩·天视将考验猎人是否能应付这片土地上最大的食草动物那庞大的身躯和狂暴的怒火。震动着南部贫瘠之地的雷霆蜥蜴——从风暴口鼻龙到雷首龙——都是可怕的对手，它们沉重的步伐足以将粗心大意者碾碎在脚下。"},{t="掠食者之道",b="对于牛头人和兽人猎人来说，击杀一只雷霆蜥蜴不仅是消灭野兽，更是展示风度、站位和力量的机会。乔恩需要它们强效的血液作为实物证据，证明猎人确实站在了这些隆隆作响的巨兽面前，并能安然无恙地归来。成功获取这份战利品，便开启了通往乔恩任务中最终猎物——天空霸主的道路。"}},faq={{q="我在哪里可以找到狩猎用的雷霆蜥蜴？",a="雷霆蜥蜴游荡在南贫瘠之地的陶拉祖营地周围的平原上。你可以在营地的北面、东面和南面找到正在吃草的风暴口鼻龙、风暴兽皮龙和雷首龙。",al={"雷霆蜥蜴位置","风暴口鼻龙在哪里","雷霆蜥蜴去哪找"}},{q="是谁派我执行这项狩猎任务的？",a="陶拉祖营地的一位牛头人猎人长者乔恩·天视会提供这个任务。它紧接在对迅猛龙伊沙姆哈尔的狩猎之后。",al={"任务发布者","谁发布愤怒的雷霆蜥蜴任务","乔恩·天视"}},{q="雷霆蜥蜴有什么特别危险的地方？",a="它们庞大的物理体型和带电的本质构成了巨大的威胁。它们可以轻易地将粗心的猎人践踏致死，或者用带有风暴能量的震颤践踏将其击晕。",al={"它们为什么危险","雷霆蜥蜴战斗"}},{q="乔恩用收集到的血液做什么？",a="这些血液主要作为不可辩驳的证据，证明你曾与这些生物正面交锋，并在近战中击败了它们。乔恩会检查血液，以确认你在这些践踏兽群的面前幸存下来，且并未受伤。",al={"为什么需要雷霆蜥蜴的血液","血液的用途"}},{q="这个任务之后是什么？",a="将血液交还给乔恩·天视后，会引出“雷霆之鹰的呼唤”，这是南部狩猎试炼的下一阶段，将派你去追捕平原上的有翼掠食者。",al={"后续任务","完成愤怒的雷霆蜥蜴之后做什么"}},{q="这与赛格拉·黑刺的试炼有什么关系？",a="赛格拉·黑刺在北贫瘠之地的十字路口附近开启了你的狩猎历程，让你对抗平原陆行鸟、斑马和迅猛龙，随后将你派往南方的陶拉祖营地，跟随乔恩·天视学习如何对抗更强大的猎物。",al={"十字路口狩猎试炼","赛格拉·黑刺任务线"}}},fp="23,185,29.275.0,23.293.0,51.160.0,26.159.0,50.155.0,43.168.0,28.164.0,49.231.0"}
P.entries["quest:90902"] = {n="Rediscovering the Light",s="该任务由丧钟镇的Aramis Hammerhand发布，旨在挑战新生的被遗忘者圣骑士，要求他们重新拥抱圣光。召唤圣光之力会给亡灵之躯带来剧烈的痛苦，初出茅庐的圣骑士必须在灼烧的痛楚中坚持为受伤的死亡卫士进行治疗。",h="该任务由丧钟镇的Aramis Hammerhand发布，旨在挑战新生的被遗忘者圣骑士，要求他们重新拥抱圣光。召唤圣光之力会给亡灵之躯带来剧烈的痛苦，初出茅庐的圣骑士必须在灼烧的痛楚中坚持为受伤的死亡卫士进行治疗。",kw={"阿拉米斯·锤手","死亡卫士","丧钟镇","被遗忘者圣骑士","圣光","重寻圣光","提瑞斯法林地","亡灵圣骑士"},ang={["class:Paladin"]="对于亡灵圣骑士来说，重新连接圣光是一场关于信仰和耐力的严酷考验，它证明了即使面临灼热的痛楚，神圣誓言依然能够超越死亡。",["race:Undead"]="这一仪式展示了被遗忘者顽强的韧性，他们将圣光带来的灼烧折磨转化为了生存的纪律武器。"},sec={{t="痛苦的重逢",b="对于曾经的白银之手勇士和洛丹伦的陨落骑士来说，在亡灵状态下苏醒意味着要面对一个可怕的现实：圣光依然回应着他们的呼唤，但却会从内部灼烧他们枯萎的躯体。Aramis Hammerhand教导新生的被遗忘者圣骑士，那些曾经习以为常的能力如今会带来极度的痛苦。由于圣光能量与维持亡灵存在的邪恶魔法天然冲突，引导圣光需要极强的意志力和痛苦的毅力。"},{t="苦难中的净化",b="被遗忘者圣骑士并没有让这种折磨阻碍自己，而是将痛苦视为信仰的永恒见证。整个丧钟镇的死亡卫士在与毫无理智的僵尸作战时身负重伤，而治愈他们便成了这些亡灵骑士的职责。Aramis教导他们，忍受灼烧的痛楚就像是在锻炼萎缩的肌肉——这种痛苦本身就被视为一种荣誉勋章，也是圣光并未抛弃他们的活生生的证明。"}},faq={{q="为什么使用圣光会伤害被遗忘者圣骑士？",a="圣光与维持亡灵存在的死灵能量在本质上是对立的。尽管被遗忘者的意志和信念使他们能够引导圣光的力量，但让这种神圣的能量在死去的血肉中循环会带来剧烈的灼烧痛楚。",al={"为什么圣光会伤害亡灵","圣光灼烧亡灵","治疗时的痛楚"}},{q="阿拉米斯·锤手是谁？",a="阿拉米斯·锤手是一位驻扎在丧钟镇的亡灵圣骑士训练师。他指引新生的被遗忘者圣骑士重铸他们与圣光之间破碎的联系。",al={"阿拉米斯·锤手是谁","阿拉米斯·锤手背景故事","任务发布者"}},{q="为什么丧钟镇的死亡卫士会受伤？",a="死亡卫士是保卫丧钟镇的士兵，他们需要抵御毫无理智的亡灵、野性的天灾残党，以及在新生亡灵从坟墓中爬出时环绕在定居点周围的敌对野生生物。",al={"为什么死亡卫士会受伤","受伤的死亡卫士背景","丧钟镇防御者"}},{q="亡灵可以自然地使用圣光吗？",a="可以，前提是他们保持着曾经的誓言所带来的信仰、意志和记忆。圣光会回应真诚的信念，尽管这会对死去的身体造成残酷的肉体代价。",al={"被遗忘者可以成为圣骑士吗","亡灵使用圣光","被遗忘者圣骑士背景"}},{q="阿拉米斯所说的“痛苦是荣誉勋章”是什么意思？",a="阿拉米斯并不将灼烧的痛苦视为诅咒，而是将其视为圣光依然倾听他们呼唤的无可辩驳的证明。被遗忘者圣骑士忍受法术带来的灼热，以证明他们不可动摇的忠诚与目标。",al={"痛苦的净化属性","荣誉勋章的含义","阿拉米斯的言论"}},{q="这个任务在哪里进行？",a="任务全程在丧钟镇进行，这是位于提瑞斯法林地西南部的一处隐秘的新手避难所，新生的被遗忘者正是从这里开始他们的亡灵存在。",al={"这个任务在哪里","任务地点","丧钟镇任务"}}},fp="23,102,17.373.0,30.305.0,48.185.0,25.153.0,46.206.0,42.200.0,58.177.0,33.144.0"}
P.entries["quest:91"] = {n="所罗门的律法",s="“所罗门法”是经由湖畔镇镇长办公室的拜里弗·科纳彻尔发布的一道地方政令。该政令判处赤脊山的影皮豺狼人死刑，理由是他们与暴风城的敌人摩根索相互勾结。冒险者们受命执行这项严苛的边境正义，并将从豺狼人身上搜集的坠饰带回作为凭证。",h="“所罗门法”是经由湖畔镇镇长办公室的拜里弗·科纳彻尔发布的一道地方政令。该政令判处赤脊山的影皮豺狼人死刑，理由是他们与暴风城的敌人摩根索相互勾结。冒险者们受命执行这项严苛的边境正义，并将从豺狼人身上搜集的坠饰带回作为凭证...",kw={"科纳彻尔","豺狼人","湖畔镇","摩根索","坠饰","赤脊山","影皮","所罗门","镇长办公室"},ang={["class:Mage"]="摩根索代表着将奥术知识扭曲为黑暗恐怖的行径，这使得他的爪牙成为受过训练的施法者们的优先打击目标。",["class:Paladin"]="惩治那些甘愿效力于黑魔法师的卑劣豺狼人，正是为了响应那呼唤，为遭受围困的边境城镇带来神圣的正义与保护。",["faction:Alliance"]="维护所罗门的法令加强了边境东部的法治，而那里正是暴风城正规军明显缺席的地方。"},sec={{t="湖畔镇的边境正义",b="湖畔镇在很大程度上与暴风城的直接军事支援隔绝，这迫使所罗门镇长及其镇政府官员不得不以严苛的边境职权来管理赤脊山。拜里弗·科纳彻尔在镇长办公室办公，他是当地地方法院的执行者。当外部威胁侵扰小镇时，法院除了悬赏通缉罪犯外别无他法，只能依靠自由雇佣兵和过往的卫士来维护王国的律法。"},{t="协助王国的敌人",b="铲除影皮氏族的法律依据在于他们与摩根索结盟，摩根索是一名盘踞在东部山丘的流亡施法者。根据湖畔镇和暴风城王国的法律，直接协助王国宣布的敌人将面临强制性的死刑判决。由于豺狼人积极执行摩根索的指令，法院不仅将他们视为野蛮的食腐动物，更视其为必须处决的叛国交战方。"}},faq={{q="所罗门是谁，他的法律是什么？",a="所罗门指的是所罗门镇长，他是湖畔镇的平民领袖。“所罗门法”反映了他发布的地方政令和暴风城的法典，即协助王国认定的罪犯是叛国罪，可判处死刑。",al={"所罗门是谁","所罗门法含义","什么是所罗门法"}},{q="摩根索是谁，为什么湖畔镇要对付他？",a="摩根索是一名盘踞在赤脊山东部山脚下的流亡奥术修行者。他被暴风城列为敌人，利用邪恶的魔法恐吓当地居民，并将影皮豺狼人置于其黑暗意志的支配之下。",al={"摩根索是谁","摩根索背景故事","为什么摩根索很危险"}},{q="为什么要专门猎杀影皮豺狼人？",a="虽然豺狼人对当地定居者来说总是危险的，但影皮氏族已经直接投靠了黑巫师摩根索。这种积极的结盟关系使他们成为根据城镇政令可被依法处决的目标。",al={"为什么要杀影皮豺狼人","赤脊山影皮豺狼人","为什么要针对豺狼人"}},{q="坠饰有什么用？",a="影皮豺狼人佩戴的坠饰是他们死亡的证明。拜里弗·科纳彻尔要求冒险者上交十个坠饰，以证明法院的判决已执行完毕，之后才会发放赏金。",al={"为什么要影皮坠饰","坠饰的目的","坠饰作为凭证"}},{q="拜里弗·科纳彻尔在哪里办公？",a="拜里弗·科纳彻尔驻守在湖畔镇的镇长办公室里，与所罗门镇长及其他管理赤脊山事务的文职官员在一起。",al={"科纳彻尔位置","拜里弗·科纳彻尔在哪里","湖畔镇法院"}},{q="为什么暴风城不派皇家士兵来处理这件事？",a="暴风城王国兵力吃紧，目前正饱受政治瘫痪和各地动荡的困扰。湖畔镇提出的正式军事增援请求屡屡被忽视，导致所罗门镇长不得不雇佣冒险者。",al={"暴风城军队在哪里","为什么没有卫兵对付豺狼人","湖畔镇被暴风城遗弃"}}},fp="13,200,29.391.0,28.312.0,35.187.0,54.211.0,56.156.0,26.163.0,49.124.0,60.223.0"}
P.entries["quest:91208"] = {n="Coming to Terms",s="这个任务由丧钟镇的Aramis Hammerhand发布，要求新复活的圣骑士去接触一位难以接受亡灵身份的同僚。这位刚刚复苏的战士在惊恐中逃往山丘，不得不面对自己已经变成了曾经誓死抗击之物的痛苦现实。",h="这个任务由丧钟镇的Aramis Hammerhand发布，要求新复活的圣骑士去接触一位难以接受亡灵身份的同僚。这位刚刚复苏的战士在惊恐中逃往山丘，不得不面对自己已经变成了曾经誓死抗击之物的痛苦现实。",kw={"阿拉米斯·锤手","接受现实","丧钟镇","惊慌的圣骑士","圣光","圣骑士","提瑞斯法林地","亡灵圣骑士"},ang={["class:Paladin"]="这项任务触及了圣骑士在亡灵状态下面临的核心困境：面对自己已经变成曾经誓言要清除之物的恐怖事实。",["race:Undead"]="在提瑞斯法苏醒带来的心理打击让许多人精神崩溃；处理那些陷入恐慌而迷失自我的人，是被遗忘者早期生活中必须面对的悲剧现实。"},sec={{t="苦涩的复生",b="从死亡中苏醒并加入被遗忘者的行列，对任何人来说都是一种冲击，但对于白银之手的前圣骑士而言，这种打击更是深入骨髓。他们曾毕生致力于以圣光之名消灭亡灵，如今却发现自己的灵魂被重新禁锢在腐烂的躯体之中。虽然一些人在Aramis Hammerhand的指导下适应了这种生活，但另一些人却被恐惧和困惑压垮，宁愿逃入提瑞斯法的荒野，也不愿面对自己那残酷的新生。"},{t="仁慈的解脱",b="Aramis Hammerhand希望有同为骑士的同僚能怀着同情与理解，去接触躲在教堂西侧山丘中的那位惊慌失措的圣骑士。不幸的是，重生的沉重负担让她彻底陷入了疯狂。当有人靠近时，她在恐惧和愤怒的驱使下盲目攻击，让人别无选择，只能将其击杀。对于那些在坟墓中精神崩溃的被遗忘者来说，迅速的终结是唯一的仁慈。"}},faq={{q="那位惊慌的圣骑士是谁？",a="她是一位刚刚复活的被遗忘者，生前曾是一名圣骑士。作为亡灵生物醒来后，她因极度恐惧而彻底陷入慌乱，从丧钟镇逃往了附近西边的山丘。",al={"惊慌的圣骑士","山丘上的圣骑士是谁","在接受现实中我要找谁"}},{q="为什么这位惊慌的圣骑士会发起攻击？",a="在苏醒后发现自己变成了曾经抗击的那类生物，这让她感到恐惧，无法接受自己的新存在。阿拉米斯警告说，一些刚复活的圣骑士会变得具有暴力倾向，并请求你怀着同情去接近她。",al={"为什么她会变得敌对","为什么要攻击","能救那个惊慌的圣骑士吗"}},{q="是谁发布了“接受现实”这个任务？",a="阿拉米斯·锤手，一位位于丧钟镇教堂的圣骑士导师，他向需要了解复活后同僚脆弱精神状态的新生骑士发布这项任务。",al={"接受现实任务发布者","阿拉米斯·锤手任务","在哪里开始接受现实"}},{q="被遗忘者还能使用圣光吗？",a="可以。像阿拉米斯·锤手这样的复活圣骑士依然侍奉着圣光，他也希望引导刚复活的圣骑士重回圣光之道。",al={"亡灵圣骑士圣光","被遗忘者圣骑士使用圣光吗","亡灵使用圣光"}},{q="那位惊慌的圣骑士在哪里？",a="她从丧钟镇的教堂直接向西逃去，躲藏在俯瞰定居点的树木丛生的山丘中。",al={"惊慌的圣骑士位置","她在哪里","在丧钟镇的哪里"}},{q="完成“接受现实”后会发生什么？",a="你会回到阿拉米斯·锤手身边，报告你帮助那位惊慌圣骑士的尝试。随后，他会指导你进行进一步的训练，以磨练你作为一名被遗忘者圣骑士的纪律。",al={"接受现实的后续任务","接受现实之后"}}},fx={ea9eba60={q="为什么阿拉米斯·锤手派你去做这项任务？",a="阿拉米斯·锤手明白，倒下的圣职战士醒来后发现自己成了亡灵，是多么令人痛苦。圣骑士曾以凡人之躯与天灾军团作战，几乎无法接受自己竟然也会复生。阿拉米斯希望用慈悲拯救一位新近复生的姐妹，耐心倾听并引导她重返圣光，免得绝望和疯狂彻底吞噬她。",al={"阿拉米斯·锤手的动机","为什么帮助受惊的圣骑士","阿拉米斯为什么想让这件事完成"}}},fp="15,145,21.309.0,18.353.1,30.142.0,39.197.1,36.165.0,35.120.0,40.102.0,46.174.1"}
P.entries["quest:91209"] = {n="Continue Your Training",s="这个任务指引新复生的被遗忘者圣骑士离开丧钟镇，前往布瑞尔进行进阶训练。在Aramis Hammerhand的嘱托下，这段旅程让这位初出茅庐的圣光勇士开始面对提瑞斯法林地更广阔的危险。同时也作为一个严峻的警告，提醒着他们：圣光使用者在亡灵中面临着极深的猜忌。",h="这个任务指引新复生的被遗忘者圣骑士离开丧钟镇，前往布瑞尔进行进阶训练。在Aramis...",kw={"阿拉米斯·锤手","布瑞尔","继续训练","丧钟镇","被遗忘者圣骑士","圣光","莎莉·斯迪威尔","提瑞斯法林地"},ang={["class:Paladin"]="对于一名亡灵圣骑士来说，这次过渡是一个清醒的提醒：即便是在被遗忘者同胞中间，挥舞圣光之力也会使你成为一个局外人。",["race:Undead"]="该任务凸显了被遗忘者社会内部的紧张关系，即对洛丹伦土地的忠诚与围绕圣光的挥之不去的创伤之间产生的冲突。"},sec={{t="离开丧钟镇",b="一旦新苏醒的灵魂在丧钟镇与世隔绝的墓地中掌握了武技和引导圣光之力的基本功，Aramis Hammerhand就会指引他们向东前往提瑞斯法林地更广阔的区域。他们的目的地是布瑞尔，这是一个繁忙的区域哨站，也是提瑞斯法中部行政枢纽。在那里，Shari Stilwell负责监管那些敢于在亡灵状态下踏上圣骑士之路的人的晋升。"},{t="充满危险的使命",b="Aramis在临行前给出了建议，强调了身为亡灵圣骑士的艰难现实。虽然洛丹伦仍然需要防御力量来应对外部威胁，但在希尔瓦娜斯·风行者的旗帜下挥舞圣光会引来苦涩的怀疑。无数被遗忘者曾在圣光狂热者的手中遭受痛苦或死亡，仅仅是圣光的存在，就会在亡灵同胞中滋生不信任。"}},faq={{q="谁提供了这个任务？我在哪里可以找到他们？",a="该任务由阿拉米斯·锤手提供，他是驻扎在提瑞斯法林地丧钟镇的圣骑士训练师。",al={"任务发布者","如何开始","阿拉米斯·锤手位置"}},{q="我在哪里提交“继续训练”？",a="你需要将任务提交给莎莉 斯迪威尔，她是位于布瑞尔镇的圣骑士训练师，从丧钟镇沿大路向东即可到达。",al={"在哪里交任务","沙瑞·斯迪威尔位置","任务提交点"}},{q="为什么被遗忘者不信任圣骑士？",a="许多被遗忘者对圣光怀有根深蒂固的怨恨，这既是因为圣光会对亡灵躯体造成剧痛，也是由于血色十字军等圣光教派的残酷迫害。走上圣骑士之路让人身处一种大多数亡灵所恐惧或鄙夷的力量的危险近处。",al={"为什么亡灵讨厌圣骑士","被遗忘者圣骑士偏见","接近圣光"}},{q="任何被遗忘者职业都能接这个任务吗？",a="不能。这个任务明确是为被遗忘者圣骑士准备的过渡任务，引导他们从丧钟镇的初始区域前往布瑞尔的更广阔的世界。",al={"这个任务是圣骑士专属吗","职业要求"}},{q="什么是布瑞尔？",a="布瑞尔是提瑞斯法林地中部的一个关键城镇，是位于幽暗城废墟北部的被遗忘者旅行者、守卫和商人的主要枢纽。",al={"什么是布瑞尔","布瑞尔城镇背景"}},{q="根据阿拉米斯的说法，洛丹伦面临着什么威胁？",a="尽管洛丹伦已经破碎，但它仍处于猖獗的天灾余孽、充满敌意的野生生物，以及诸如血色十字军之类复仇心切的生者派系的持续威胁之下。",al={"洛丹伦的威胁","为什么要保护洛丹伦"}}},fp="22,218,18.305.0,20.331.0,46.72.0,42.105.0,38.188.0,39.83.0,14.143.0,53.137.0"}
P.entries["quest:91282"] = {n="A Second Home",s="A Second Home 是一封旨在邀请新生的被遗忘者加入提瑞斯法林地一个新兴组织的邀请函。它指引初学者前往班达里安堡，这是一座坐落在索利丹农场西北方峭壁上的修道院，靠近静语林地。该倡议旨在为那些在新的非生命形态中开辟一席之地的人们提供社区、共同的信仰和相互支持。",h="A Second Home...",kw={"第二个家","班达里安堡","被遗忘者组织","修道院","索利丹农场","提瑞斯法林地","静语林地"},ang={["faction:Horde"]="加强提瑞斯法林地的被遗忘者联系有助于巩固部落在东部王国北部的存在。",["race:Undead"]="新生的被遗忘者在脱离天灾军团的控制后，常常感到迷茫，因此一个基于社区和共同信仰的组织成为了他们重建生活的难得机会。"},sec={{t="复生者集会",b="A Second Home 是一封旨在指引那些在提瑞斯法林地寻找立足点的新生被遗忘者的入门邀请函。与其在非生命的严酷现实中独自徘徊，不如鼓励新苏醒的个体在同伴中寻求友谊，依靠共同的信仰和社区来释放他们真正的潜力。"},{t="峭壁上的避难所",b="这份邀请指引旅行者前往班达里安堡，这是一座位于索利丹农场西北方崎岖峭壁上的修道院。它坐落在神秘的静语林地旁，这处据点提供了一个避难所，新成立的组织的成员可以在此学习、实践并在这片提瑞斯法的土地上扎根。"}},faq={{q="什么是任务 第二个家？",a="第二个家 是一封旨在邀请新生的被遗忘者加入提瑞斯法林地一个新成立的职业组织的邀请函。它指引寻求者前往一座偏僻的修道院，志同道合的修行者们聚集在那里，旨在培养友谊并探索他们共同的潜力。",al={"什么是 第二个家","任务 第二个家","第二个家 任务"}},{q="班达里安堡在哪里？",a="班达里安堡位于提瑞斯法林地索利丹农场西北方的峭壁上，坐落在静语林地的边缘。",al={"班达里安堡在哪里","班达里安堡位置","如何前往班达里安堡"}},{q="是谁建立了班达里安堡的修道院？",a="这座堡垒是提瑞斯法林地被遗忘者圣骑士组织“提尔之卫”的修道院，旨在为新生的同胞提供社区支持和共同的信仰。",al={"谁管理班达里安堡","谁组建了班达里安堡","班达里安堡组织"}},{q="为什么被遗忘者会被邀请到班达里安堡？",a="创建者们相信，新生的亡灵只有通过社区和共同的目标才能发挥出全部潜力，因此将班达里安堡作为该组织的避难所和学习场所。",al={"为什么去班达里安堡","班达里安堡目的"}},{q="它与索利丹农场有什么联系？",a="索利丹农场位于提瑞斯法林地西部，是班达里安堡俯瞰静语林地边缘的峭壁东南方的一个地标。",al={"索利丹农场在哪里","索利丹农场 班达里安"}},{q="什么样的组织聚集在班达里安堡？",a="班达里安堡的组织是“提尔之卫”，这是一个新成立的被遗忘者圣骑士组织，旨在支持同胞适应他们的非生命状态。",al={"班达里安堡是什么组织","班达里安堡职业组织"}}},fp="13,304,24.189.0,23.219.0,32.208.0,34.120.0,48.159.0,53.176.0,49.144.0,50.144.0"}
P.entries["quest:91285"] = {n="Murlocs at the Gates",s="Breton Samuels请求你帮忙击退骚扰要塞的鱼人。他们的袭击让重建工作更加困难。",h="Breton Samuels请求你帮忙击退骚扰要塞的鱼人。他们的袭击让重建工作更加困难。",kw={"袭击者","布雷顿·塞缪尔斯","要塞","鱼人","大门口的鱼人","先知","繁殖地","邪鳍"},sec={{t="鱼人的麻烦",b="从前，一支鱼人部族曾把要塞当作繁殖地。自从你和其他人将他们赶走后，他们一直是个麻烦，袭击也越来越难以应付。Breton Samuels请求你击退其中一部分鱼人。他们潜伏在东边道路沿线的峭壁上，也藏身于西边湖泊周围的营地中。"},{t="袭击",b="Breton Samuels预计袭击还会持续，但希望击退邪鳍袭击者和先知能让袭击有所缓解。鱼人不断袭击要塞居民，重建工作已经困难重重。"}},faq={{q="谁在请求帮助？",a="布雷顿·塞缪尔斯请求你击退一些骚扰要塞的鱼人。",al={"谁提出请求","布雷顿·塞缪尔斯","谁需要帮助"}},{q="鱼人为何是个麻烦？",a="要塞居民将鱼人赶出繁殖地后，他们便一直骚扰要塞，袭击也越来越难以应付。",al={"为何是鱼人","鱼人的麻烦","他们在做什么"}},{q="鱼人在哪里？",a="他们潜伏在东边道路沿线的峭壁上，也藏身于西边湖泊周围的营地中。",al={"鱼人在哪里","鱼人位置","去哪里找他们"}},{q="涉及哪些鱼人？",a="邪鳍袭击者和邪鳍先知正在骚扰要塞。",al={"鱼人种类","邪鳍鱼人","要对付谁"}},{q="要塞为何需要帮助？",a="要塞正在重建，鱼人的袭击让这项工作更加困难。",al={"为何要帮忙","重建要塞","利害攸关之事"}}},fp="20,103,18.283.0,11.195.0,23.77.0,30.136.0,22.92.0,27.65.0,28.68.0"}
P.entries["quest:91294"] = {n="Touring the Grounds",s="鱼人袭击得到控制后，Breton请你巡视班达里安堡。先认识堡垒的领袖Danitha Morr，才能开始融入这里的居民。",h="鱼人袭击得到控制后，Breton请你巡视班达里安堡。先认识堡垒的领袖Danitha Morr，才能开始融入这里的居民。",kw={"班达里安堡","布雷顿","达妮莎·莫尔","场地","圣光","鱼人袭击","居民"},sec={{t="堡垒之内",b="Breton请你结识班达里安堡的居民，并四处看看这座要塞。巡视完毕后，Danitha Morr会帮你安顿下来。堡垒规模尚小，但这里的人们已把它当作家园。"},{t="一位指挥官",b="Danitha Morr自称是堡垒里最接近指挥官的人。她欢迎那些希望与仍忠于圣光的人们结交的人，并说堡垒要想完全建立起来，还需要帮助。"}},faq={{q="是谁让我四处看看？",a="鱼人袭击得到控制后，布雷顿鼓励你探索班达里安堡。",al={"谁让我巡视","布雷顿 巡视堡垒"}},{q="谁在领导班达里安堡？",a="达妮莎·莫尔是班达里安堡里最接近指挥官的人。",al={"丹妮莎是谁","堡垒领袖"}},{q="我为什么要和达妮莎·莫尔交谈？",a="达妮莎·莫尔可以帮你融入堡垒的居民之中。",al={"巡视后去哪里","找丹妮莎交谈"}},{q="班达里安堡是什么样的？",a="这是一座小型要塞，居民们把它当作家园。",al={"堡垒是什么样的","班达里安堡"}},{q="谁会受到堡垒欢迎？",a="达妮莎欢迎那些希望与仍忠于圣光的人们结交的人。",al={"谁能加入","忠于圣光"}}},fp="19,160,11.199.0,11.219.0,32.92.0,25.68.0,35.65.0,28.66.0,27.84.0"}
P.entries["quest:913"] = {n="雷鹰的嘶鸣",s="“雷鹰的哀鸣”是乔恩·天视在南贫瘠之地狩猎试炼的顶点。在陶拉祖营地的长者们委托下，猎人必须寻找在灌木丛中翱翔的带翼蛇形生物，并带回它们的翅膀，以证明自己能够驾驭这片草原上最凶猛的野兽。",h="“雷鹰的哀鸣”是乔恩·天视在南贫瘠之地狩猎试炼的顶点。在陶拉祖营地的长者们委托下，猎人必须寻找在灌木丛中翱翔的带翼蛇形生物，并带回它们的翅膀，以证明自己能够驾驭这片草原上最凶猛的野兽。",kw={"贫瘠之地狩猎","陶拉祖营地","雷鹰的哀鸣","乔恩·天视","雷鹰","雷鹰的翅膀","带翼蛇形生物"},ang={["class:Hunter"]="击落像雷鹰这样的空中蛇形生物是对你远程作战纪律和耐心的考验，也是正式通过成为平原狩猎大师的一道入行仪式。",["faction:Horde"]="驯服并守护陶拉祖营地周边的危险前线，确保了部落旅人们在途经贫瘠之地大道时的安全。",["race:Tauren"]="对于舒哈鲁人来说，追踪翱翔的雷鹰是一项关于尊重与荣誉的神圣试炼，旨在证明猎人有能力与大地母亲最迅捷的孩子们进行沟通，并挑战自我。"},sec={{t="试炼的顶点",b="在证明了自己足以对抗游荡的平原陆行鸟、潜行者以及狂躁的雷蜥之后，贫瘠之地的猎人们会受到乔恩·天视的指引，去迎接他们的最终挑战。雷鹰被认为是栖息在陶拉祖营地周边灌木丛中最凶猛的空中捕食者之一。猎杀一只雷鹰需要耐心、精准的瞄准，以及对天空的敏锐洞察力，而这正是大多数地面捕食者所不具备的。"},{t="猎人之道",b="带回雷鹰的翅膀，标志着新兵在陶拉祖营地严密注视下的教导期宣告结束。对于牛头人而言，狩猎不仅仅是杀戮，而是与大地母亲以及荒野自然法则保持和谐的持续精神修行。击败这样一种骄傲的生物，证明了猎人是以力量、勇气和荣誉行事——这是踏入中央平原之外更严酷的荒野前所必须具备的美德。"}},faq={{q="什么是雷鹰？",a="雷鹰是贫瘠之地原生的一种带翼蛇形捕食者。它们在干旱的平原上空滑翔，从高处捕猎小型猎物，利用它们迅如闪电的突袭和空中机动性，统治着陶拉祖营地周边的天空。",al={"什么是雷鹰","雷鹰生物","贫瘠之地飞行蛇"}},{q="是谁发布的这个任务？",a="乔恩·天视，一位驻扎在南贫瘠之地陶拉祖营地的受人尊敬的牛头人猎人。在你证明了自己能够对抗该地区狂怒的雷蜥之后，他会发布这项试炼。",al={"谁开启雷鹰的哀鸣","任务发布者"}},{q="哪里可以找到雷鹰？",a="它们在南贫瘠之地广阔的天空和岩石峭壁间游荡，主要盘旋在陶拉祖营地以北和以西道路两侧的平原上空。",al={"在哪里找到雷鹰","雷鹰位置"}},{q="带回翅膀对牛头人意味着什么？",a="呈上切下的翅膀是干净利落且光荣狩猎的切实证明。在牛头人文化中，从危险的猎物身上获取战利品，既展示了对野兽的征服，也表达了对倒下的生物那份骄傲与凶猛的认可。",al={"为什么要带回翅膀","雷鹰翅膀的意义"}},{q="这项狩猎试炼接下来会引向何处？",a="完成乔恩·天视的试炼意味着你在陶拉祖营地的训练结束了，乔恩会让你去找他的妹妹玛恩·天视，她在棘齿城以南的贫瘠之地东海岸进行狩猎。",al={"雷鹰的哀鸣之后是什么","雷鹰任务后的下一步"}},{q="这与十字路口的塞格拉·黑刺有什么联系？",a="这项试炼构成了在十字路口塞格拉·黑刺指导下开始的整个狩猎仪式的南部篇章。在掌握了北部的野兽习性后，前途无量的猎人会被派往南方的陶拉祖营地，继续在乔恩·天视的指导下接受训练。",al={"塞格拉·黑刺的联系","十字路口狩猎链"}}},fx={["2e0d4fa8"]={q="为什么乔恩·星眼想让这件事完成？",a="乔恩·星眼正在考验你作为猎人的力量、勇气和荣誉。在引导你完成南贫瘠之地的试炼后，他让凶猛的雷鹰成为你在他指导下训练的最后一关。击倒这样骄傲的掠食者，便能证明你已准备好结束在陶拉祖营地的时光，踏上真正猎人的广阔征途。",al={"乔恩·星眼的动机","为什么杀死雷鹰","猎杀雷鹰的目的"}}},fp="22,295,15.413.0,15.441.0,22.232.0,21.184.0,29.153.0,51.246.0,40.202.0,60.256.0"}
P.entries["quest:91316"] = {n="Making Repairs",s="幽暗城远方的一座要塞物资短缺，守军缺少建筑材料。你受命前往影谷寻找木材，助其修复要塞。",h="幽暗城远方的一座要塞物资短缺，守军缺少建筑材料。你受命前往影谷寻找木材，助其修复要塞。",kw={"建筑材料","要塞","修复","地窖","影谷","结实的木材","幽暗城","耳语森林"},sec={{t="影谷的物资",b="影谷这座废弃村庄位于耳语森林，处于要塞西南方。你受命搜寻村中一栋建筑里的旧地窖，寻找可用的材料。要塞远离有人定居的地区，补给十分困难，修复工作只能依靠在那里找到的物资。"}},faq={{q="为何需要建筑材料？",a="要塞需要材料来协助修复。它距离幽暗城遥远，物资难以运送。",al={"为何需要木材","要塞修复"}},{q="影谷在哪里？",a="影谷是耳语森林中的一座废弃村庄，位于要塞西南方。",al={"影谷位置","村庄在哪里"}},{q="在哪里可能找到可用的材料？",a="影谷的一栋建筑里有个旧地窖，里面可能存有可用的材料。",al={"地窖材料","去哪里寻找"}},{q="要塞缺少什么？",a="要塞缺少修复所需的建筑材料。",al={"缺少什么物资","木材短缺"}}},fp="14,178,22.302.0,34.122.0,20.83.0,38.90.0,30.71.0"}
P.entries["quest:91317"] = {n="The Tarnished",s="一位被遗忘者领袖请你前往提瑞斯法林地的影谷，阻止The Tarnished。他们的袭击加深了被遗忘者之间的不信任，也威胁着一个新兴组织在提瑞斯法的立足之地。",h="一位被遗忘者领袖请你前往提瑞斯法林地的影谷，阻止The Tarnished。他们的袭击加深了被遗忘者之间的不信任，也威胁着一个新兴组织在提瑞斯法的立足之地。",kw={"指挥官鲁道夫·格尔哈特","新兴组织","被遗忘者","不信任","影谷","蒙尘苦工","蒙尘狂热者","蒙尘者","提瑞斯法林地"},ang={["faction:Horde"]="该组织希望在部落中赢得一席之地，但其领袖预计，获得接纳可能需要数年甚至数十年。",["race:Undead"]="作为一名被遗忘者，你面对的是攻击自己族人的复生同胞，而这加剧了人们对一个新兴组织的不信任。"},sec={{t="The Tarnished组织",b="一些复生者保留了生前的偏见，如今开始攻击自己的被遗忘者同胞。The Tarnished聚集在此地西南方的影谷。有人请你制止他们的暴行，并带回指挥官Rudolph Gelhardt的头颅。"},{t="在他们之中的一席之地",b="The Tarnished的袭击让那些不信任该组织的人更有理由与之为敌。阻止他们或许能帮助该组织在被遗忘者中赢得一席之地，但要获得接纳，可能需要数年甚至数十年。"}},faq={{q="蒙尘者是谁？",a="蒙尘者是一些复生者，他们带着生前的偏见，并攻击自己的被遗忘者同胞。",al={"蒙尘者是谁","这些蒙尘者是谁"}},{q="蒙尘者在哪里？",a="有不少蒙尘者在此地西南方的提瑞斯法林地影谷定居。",al={"蒙尘者的位置","蒙尘者在哪里"}},{q="蒙尘者为何构成威胁？",a="他们攻击被遗忘者同胞，加深了被遗忘者对该组织的不信任。",al={"为何阻止蒙尘者","蒙尘者的袭击"}},{q="谁领导蒙尘者？",a="指挥官鲁道夫·格尔哈特被认定为蒙尘者的首领。",al={"蒙尘者的首领","鲁迪·盖尔哈特"}},{q="为何该组织需要被遗忘者的信任？",a="被遗忘者记得生者曾以圣光之名迫害他们，因此不信任该组织。蒙尘者的袭击让这种不信任更加深重。",al={"组织信任","被遗忘者的不信任"}}},fp="13,168,17.244.0,18.203.0,22.99.0,24.91.0,31.81.0,24.47.0,45.153.0"}
P.entries["quest:914"] = {n="尖牙德鲁伊",s="“毒牙领袖”是部落的一项关键任务，由雷霆崖长者高地的纳拉·蛮鬃委派。该任务指引冒险者进入哀嚎洞穴，击败腐化的毒牙德鲁伊的四位领袖，并取回他们扭曲的梦境宝石。阻止这些叛变的德鲁伊对于防止他们的蛇形梦魇永久占据贫瘠之地至关重要。",h="“毒牙领袖”是部落的一项关键任务，由雷霆崖长者高地的纳拉·蛮鬃委派。该任务指引冒险者进入哀嚎洞穴，击败腐化的毒牙德鲁伊的四位领袖，并取回他们扭曲的梦境宝石。阻止这些叛变的德鲁伊对于防止他们的蛇形梦魇永久占据贫瘠之地至关重...",kw={"安娜科德拉","贫瘠之地","考布莱恩","梦境宝石","毒牙领袖","纳拉·蛮鬃","皮萨斯","瑟芬迪斯","哀嚎洞穴"},ang={["class:Druid"]="对于牛头人德鲁伊来说，这项任务具有极其私人的意义。眼看着自然的同僚将翡翠梦境扭曲成剧毒的枯萎，这是对塞纳里奥原则难以容忍的亵渎。",["faction:Horde"]="贫瘠之地是连接奥格瑞玛、雷霆崖和暗矛部族岛屿的关键十字路口。放任一个狂热的蛇信徒教派突变这片土地，将威胁到整个部落的稳定。",["race:Tauren"]="大地之母的健康是牛头人信仰的核心，因此从贫瘠之地的泉水中渗出的非自然腐化，是对他们所游牧的土地的直接亵渎。"},sec={{t="腐化的幻象",b="暗夜精灵德鲁伊纳拉雷克斯怀揣着一个无私的宏愿，冒险进入了哀嚎洞穴的地下泉水：他想要利用翡翠梦境为干旱的贫瘠之地恢复郁郁葱葱的生机。可悲的是，当他陷入沉睡，他的梦境却变成了一场清醒的噩梦。随行的追随者们失去了对自然和谐的虔诚，屈服于梦魇的腐化，并穿上了毒牙德鲁伊的伪装。"},{t="四颗梦境宝石",b="为了将贫瘠之地重塑为他们自己的毒蛇伊甸园，这一分裂教派的领袖们通过一种被称为梦境宝石的特殊焦点来引导扭曲的梦境能量。考布莱恩、安娜科德拉、皮萨斯和瑟芬迪斯每人持有一颗这样的宝石。只要这些神器仍掌握在他们手中，他们那腐蚀性的影响就会不断向卡利姆多的土地和水域蔓延。"},{t="雷霆崖的解脱",b="纳拉·蛮鬃在雷霆崖守护着自然的平衡，她能感受到从洞穴中传来的精神折磨直接侵蚀着她的心智。通过猎杀这四位毒蛇领主并夺走他们的宝石，部落勇士可以瓦解该教派的指挥结构，将这位牛头人德鲁伊从挥之不去的梦魇中解救出来，并拯救周围平原免遭非自然的枯萎。"}},faq={{q="谁是毒牙德鲁伊的领袖？",a="该教派由四位堕落的德鲁伊领导：安娜科德拉、考布莱恩、皮萨斯和瑟芬迪斯。他们每个人都放弃了最初的自然教诲，转而化身为蛇形，并在哀嚎洞穴中引导梦魇魔法。",al={"毒牙领袖名字","哀嚎洞穴首领","谁领导毒牙德鲁伊"}},{q="什么是梦境宝石？",a="梦境宝石是哀嚎洞穴内四位领袖每人携带的导管。它们汇聚了从纳拉雷克斯的沉睡中泄露出的扭曲的、被梦魇污染的能量，助长了该教派突变贫瘠之地的企图。",al={"什么是宝石","考布莱恩宝石","梦境宝石背景"}},{q="为什么纳拉·蛮鬃想要这些宝石？",a="纳拉·蛮鬃是雷霆崖的一位牛头人德鲁伊，她感受到了梦魇带来的精神和灵性波动。那些被腐化的领袖的面孔不断在她的梦中浮现，她需要打破他们的力量，以保护她自己的理智和贫瘠之地的未来。",al={"谁是纳拉·蛮鬃","为什么要杀领袖","纳拉·蛮鬃的动机"}},{q="毒牙德鲁伊一直都是邪恶的吗？",a="不是。他们最初是高尚的暗夜精灵德鲁伊，跟随纳拉雷克斯进入洞穴，希望能治愈干燥的草原。当纳拉雷克斯陷入梦魇时，这些能量扭曲了他们的心智，将他们变成了狂热的蛇教徒。",al={"毒牙德鲁伊起源","德鲁伊为何堕落","纳拉雷克斯的信徒"}},{q="这个任务在哪里交付？",a="任务的开始和结束都在雷霆崖长者高地的纳拉·蛮鬃处。当你从哀嚎洞穴深处收集齐全部四颗宝石后，必须返回莫高雷将它们呈交给她。",al={"毒牙领袖任务交付","纳拉·蛮鬃在哪里","交付毒牙领袖任务"}},{q="杀死领袖能治愈纳拉雷克斯吗？",a="击杀这四位领袖可以粉碎该教派的高层体系并阻止他们仪式的蔓延，但这本身并不能唤醒纳拉雷克斯。还需要洞穴深处其他的德鲁伊仪式才能唤醒这位沉睡的大师。",al={"这能拯救纳拉雷克斯吗","击杀领袖的效果"}}},fx={["5ca16cf2"]={q="为什么娜拉·蛮鬃要杀死尖牙德鲁伊？",a="尖牙德鲁伊曾是塞纳里奥议会的成员，他们原本想让贫瘠之地重新变得郁郁葱葱，却被翡翠梦魇扭曲了心智。如今，他们企图把这片土地改造成自己那充满邪念的梦境。腐化也侵扰着娜拉自己的思想和梦境。她担心，如果不杀死他们的四名首领、打破他们的影响，整个贫瘠之地都将走向黑暗而受诅咒的未来。",al={"娜拉·蛮鬃的动机","为什么杀死尖牙德鲁伊","娜拉为什么要他们死"}}},fp="19,265,18.326.0,19.322.0,32.311.1,46.234.0,24.186.0,37.203.0,40.228.0,30.165.0,38.203.0"}
P.entries["quest:916"] = {n="树林蜘蛛的毒囊",s="“树林蜘蛛的毒液”是发生在泰达希尔幽影谷的一项联盟任务。学者基尔沙兰·风行者派遣年轻的暗夜精灵去收集巨型树林蜘蛛的毒囊，以研究这棵新世界之树的生长对当地野生动物产生了怎样的影响。",h="“树林蜘蛛的毒液”是发生在泰达希尔幽影谷的一项联盟任务。学者基尔沙兰·风行者派遣年轻的暗夜精灵去收集巨型树林蜘蛛的毒囊，以研究这棵新世界之树的生长对当地野生动物产生了怎样的影响。",kw={"奥达希尔","基尔沙兰","幽影谷","黑丝","蜘蛛","泰达希尔","毒液","树林蜘蛛","风行者"},ang={["class:Druid"]="德鲁伊对基尔沙兰的研究结果非常关注，因为了解泰达希尔究竟是在治愈还是在扭曲周围的野生生物，是塞纳里奥议会保持警惕的核心所在。",["race:NightElf"]="对于在幽影谷成年的年轻暗夜精灵来说，这项任务提供了一个早期的课题，让他们了解到在泰达希尔的枝叶下，自然变得多么脆弱和不可预测。"},sec={{t="自然学家的好奇心",b="基尔沙兰·风行者来到幽影谷，是为了调查黑丝洞中那些体型巨大且极具攻击性的本地树林蜘蛛。他指出，这些野兽是其他地区体型较小的蜘蛛的近亲。他怀疑泰达希尔蕴含的巨大魔法能量正在导致当地动物群发生迅速而令人不安的变异，因此他需要毒囊来将其生物特性与普通蛛形纲动物进行对比。"},{t="幽影谷中潜伏的威胁",b="栖息在黑丝洞周围及洞内的树林蜘蛛对幽影谷中的暗夜精灵新兵来说正变得愈发危险。收集它们的毒液具有双重目的：既能清理这种危险的局部虫害，又能为达纳苏斯的科研人员提供有关泰达希尔对野生生物产生动荡影响的直接生物学证据。"}},faq={{q="谁是基尔沙兰·风行者？",a="基尔沙兰·风行者是一位驻扎在幽影谷奥达希尔的暗夜精灵研究员。他正在研究泰达希尔的本地野生动物，以揭示世界之树的迅速生长是如何影响当地生态系统的。",al={"基尔沙兰","谁给予树林蜘蛛的毒液","树林蜘蛛的毒液任务发放者"}},{q="为什么树林蜘蛛会变得这么大？",a="它们原本是体型较小的蜘蛛的近亲。基尔沙兰·风行者认为，泰达希尔的迅速生长和潜在的魔法力量导致了它们体型的反常增大，并扭曲了它们的行为。",al={"泰达希尔巨型蜘蛛","为什么幽影谷的蜘蛛这么大","树林蜘蛛变异"}},{q="黑丝洞在哪里？",a="黑丝洞位于幽影谷的北部，坐落在奥达希尔训练场后方的岩脊之中。",al={"黑丝洞位置","哪里寻找树林蜘蛛","树林蜘蛛洞穴"}},{q="基尔沙兰要用毒囊做什么？",a="他计划将这些毒液运回达纳苏斯，将其化学和魔法特性与普通森林蜘蛛进行对比，寻找由世界之树导致的异常情况。",al={"为什么收集毒囊","基尔沙兰毒液研究","达纳苏斯毒液研究"}},{q="黑丝洞里还有其他任务吗？",a="是的。在收集毒液的同时，冒险者通常会协助附近的迪兰妮亚·月光去救助埃沃隆，这是一位被黑丝洞里的蜘蛛所毒害的精灵。",al={"幽影谷其他蜘蛛任务","黑丝洞任务","埃沃隆任务"}},{q="“树林蜘蛛的毒液”后续是什么任务？",a="在检查完毒液后，基尔沙兰会要求冒险者直接从黑丝洞深处取回一枚树林蜘蛛的卵，以研究它们的生命周期。",al={"树林蜘蛛的毒液后续任务","树林蜘蛛的毒液之后是什么","基尔沙兰后续"}}},fp="13,201,24.343.0,32.237.0,28.177.0,37.183.0,27.103.0,43.193.0,44.100.0,33.127.0"}
P.entries["quest:917"] = {n="树林蜘蛛的卵",s="基尔沙兰·风行者指派幽影谷的年轻守卫去黑丝洞深处取回一枚未孵化的蜘蛛卵。在收集了它们的毒液样本后，他需要活的标本，以研究泰达希尔野生动物身上那种反常的攻击性。获取一窝未孵化的卵可以让研究人员安全地研究这些生物，而无需制服成年蛛形纲动物。",h="基尔沙兰·风行者指派幽影谷的年轻守卫去黑丝洞深处取回一枚未孵化的蜘蛛卵。在收集了它们的毒液样本后，他需要活的标本，以研究泰达希尔野生动物身上那种反常的攻击性。获取一窝未孵化的卵可以让研究人员安全地研究这些生物，而无需制服...",kw={"奥达希尔","基尔沙兰·风行者","幽影谷","黑丝洞","蜘蛛卵","泰达希尔","树林蜘蛛","树林蜘蛛的卵"},ang={["class:Druid"]="研究这些卵和毒液为塞纳里奥研究人员提供了一个机会，以诊断导致这些野兽发生变异的腐蚀是否可以被净化，或者这种枯萎病是否根深蒂固。",["race:NightElf"]="对于年轻的暗夜精灵来说，取回这枚卵突显了泰达希尔所受到的阴险腐蚀，迫使学者们不得不将自己家园的野生动物视为敌对威胁来进行研究。"},sec={{t="安全的标本",b="在从潜伏在幽影谷周边的具有攻击性的树林蜘蛛身上获取了原始毒液后，基尔沙兰·风行者需要活体对象来更好地理解它们身上那种反常的腐蚀。基尔沙兰知道，将一只挣扎的巨型蛛形纲动物从地底深处拖出来对任何新手来说都是致命的，因此他选择了一个更实际的方案：直接从黑丝洞的巢穴中取出一枚未孵化的卵。"},{t="前往首都之路",b="黑丝洞是这片森林中日益凶猛的蛛形纲生物的地下育儿室。潜入洞穴并取回一枚完好的卵，可以为学者提供一个可以在受控环境下孵化的研究对象。基尔沙兰打算将这枚卵与他的毒液样本一起打包，直接送往达纳苏斯进行进一步检查，这也标志着他当地实地研究工作的结束，并将新兵引向奥达希尔枝干上更重要的职责。"}},faq={{q="基尔沙兰为什么想要蜘蛛卵而不是成年蜘蛛？",a="基尔沙兰承认，捕获一只活的巨型蜘蛛对未经考验的新兵来说太危险了，对他自己来说单独关押也太困难了。一枚完好、未孵化的卵可以让研究人员安全地运输活体标本，并在幼体孵化前安排好收容措施。",al={"为何选择蜘蛛卵","为何不抓活蜘蛛","为何要树林蜘蛛卵"}},{q="在哪里可以找到树林蜘蛛的卵？",a="这种卵位于黑丝洞深处的一个蛛网巢穴中，该洞穴切入了泰达希尔幽影谷北端的枝干和根部。",al={"蜘蛛卵位置","哪里能找到树林蜘蛛卵","黑丝洞巢穴"}},{q="谁是基尔沙兰·风行者？",a="基尔沙兰·风行者是一位驻扎在幽影谷奥达希尔的暗夜精灵研究员。他正在调查导致泰达希尔原生生物出现暴力行为的突发性腐蚀疾病。",al={"基尔沙兰是谁","基尔沙兰背景"}},{q="卵上交后会怎么样？",a="基尔沙兰会将这枚卵和他收集的毒液瓶准备好，运往首都达纳苏斯。一旦他在幽影谷的工作结束，那里的学者和德鲁伊就可以在受控条件下对它们进行检查。",al={"基尔沙兰如何处理蜘蛛卵","蜘蛛卵去向"}},{q="完成这个任务后接下来要做什么？",a="在确保了蜘蛛卵的安全后，基尔沙兰会指引你前往奥达希尔上方响应特纳隆的召唤，将你介绍给指引幽影谷核心区域的德鲁伊长者。",al={"蜘蛛卵任务后续","交卵后的任务"}},{q="为什么树林蜘蛛如此具有攻击性？",a="泰达希尔的蜘蛛，像那里的许多野生动物一样，正在屈服于在年轻的世界之树上扎根的反常腐蚀，使得曾经温顺或中立的野兽变成了极具攻击性的掠食者。",al={"蜘蛛为何发狂","蜘蛛的腐蚀"}}},fp="11,288,15.358.0,23.355.0,58.235.0,31.137.0,28.183.0,46.184.0,38.147.0,42.210.0"}
P.entries["quest:91723"] = {n="Delicate Instruments",s="Delicate Instruments是艾尔文森林中的一项任务，由阿祖拉之塔的哈米什·伯格沃特发布。哈米什的敏感奥术设备正受到从北方辐射出的不稳定的魔法波动的影响。为了恢复稳定，旅行者必须进入玉石矿洞，并消灭造成干扰的狗头人地卜师。",h="Delicate...",kw={"奥术","精密仪器","艾尔文森林","地卜术","哈米什·伯格沃特","玉石矿洞","狗头人","狗头人地卜师","阿祖拉之塔"},ang={["class:Mage"]="阿祖拉之塔内精密的奥术仪器需要极度稳定的环境，这表明了粗糙的地卜干扰如何破坏严谨的奥术研究。",["faction:Alliance"]="协助阿祖拉之塔的研究人员有助于保护艾尔文森林的学者聚居点免受地下害虫的混乱干扰。"},sec={{t="校准中断",b="在阿祖拉之塔内，哈米什·伯格沃特负责监管需要精细校准的敏感奥术仪器。不幸的是，对于这位学者来说，周边的乡村并不安宁。反复出现的不受控能量浪涌不断干扰着他的测量工作，导致在解决干扰源之前，精确的魔法调整无法实现。"},{t="来自玉石矿洞的干扰",b="调查追踪到，这些魔法脉冲直接源自北方的玉石矿洞。这些地下隧道已被狗头人占据，他们的地卜师在岩石中引导粗糙的土系魔法。虽然他们的巫术缺乏学识上的精炼，但他们那粗陋仪式所产生的巨大频率足以引发元素涟漪，穿透大地并扰乱阿祖拉那些敏感的仪器。"}},faq={{q="谁是哈米什·伯格沃特？",a="哈米什·伯格沃特是一位驻扎在艾尔文森林阿祖拉之塔的奥术研究员。他使用需要精确校准的敏感仪器进行工作，这些仪器很容易受到环境魔法波动的影响。",al={"哈米什·伯格沃特是谁","精密仪器任务发布者","阿祖拉之塔的哈米什·伯格沃特"}},{q="为什么奥术仪器会发生故障？",a="这些仪器正受到从北方玉石矿洞辐射出的魔法能量浪涌的干扰，这些浪涌是由练习粗糙土系魔法的原始狗头人所产生的。",al={"为什么仪器会被干扰","奥术浪涌的原因","是什么干扰了阿祖拉"}},{q="什么是玉石矿洞？",a="玉石矿洞是位于艾尔文森林阿祖拉之塔以北的一座被侵扰的矿洞。狗头人已经占领了这些隧道，他们的施法者正在其中进行混乱的地卜仪式，这些仪式产生的涟漪波及了周围的森林。",al={"什么是玉石矿洞","地卜师在哪里","玉石矿洞的狗头人"}},{q="什么是狗头人地卜师？",a="狗头人地卜师是狗头人族群中的地下施法者，他们挥舞着粗糙的元素土系魔法。虽然原始，但他们集体引导的能量产生了显著的魔法干扰，妨碍了敏感的奥术设备。",al={"什么是狗头人地卜师","狗头人施法者","狗头人地卜术"}},{q="消灭地卜师如何解决这个问题？",a="消灭玉石矿洞内的地卜师可以停止持续的元素能量尖峰，使阿祖拉之塔的研究人员能够在不受干扰的情况下，对他们的敏感奥术设备进行适当的校准。",al={"为什么要消灭地卜师","精密仪器的任务目的","阻止浪涌"}},{q="什么是阿祖拉之塔？",a="阿祖拉之塔是位于东艾尔文森林的一座著名的奥术研究塔。那里的学者和法师观察区域现象并维护着精密调试的魔法仪器。",al={"什么是阿祖拉之塔","阿祖拉之塔背景故事","艾尔文森林法师塔"}}},fp="20,171,22.207.0,32.250.0,23.180.0,46.129.0,24.162.0,27.187.0,54.167.0,27.166.0"}
P.entries["quest:91724"] = {n="Delicate Instruments",s="Delicate Instruments是艾尔文森林东部的一个任务，目标是恢复阿祖拉之塔的魔法稳定性。Hamish Bergwort的精密仪器正受到附近迪菲亚潜行者法师施展的不稳定法术的干扰。解决这一干扰需要阻止石碑湖周围那些业余的施法行为。",h="Delicate Instruments是艾尔文森林东部的一个任务，目标是恢复阿祖拉之塔的魔法稳定性。Hamish...",kw={"迪菲亚潜行者","迪菲亚潜行者法师","精密仪器","艾尔文森林","哈米什·伯格沃特","石碑湖","阿祖拉之塔"},ang={["class:Mage"]="奥术修行者们会意识到，像迪菲亚潜行者法师这样的业余人士草率施法，会引发贯穿艾尔文森林的狂野波动，导致敏感的魔法研究陷入混乱。",["faction:Alliance"]="维持阿祖拉之塔周围的秩序，对于保护艾尔文森林东部免受迪菲亚侵扰至关重要。"},sec={{t="塔中的干扰",b="在阿祖拉之塔内，Hamish Bergwort试图进行精密的魔法实验，却不断被无法解释的环境干扰所打断。在一个要求精确测量的奥术圣所中，哪怕是当地魔法波动的细微涟漪，也足以毁掉数小时的心血。Bergwort怀疑这些干扰并非自然现象，而是附近施放的粗糙法术所致。"},{t="强盗与奥术",b="魔法静电的来源可以追溯到石碑湖，迪菲亚潜行者法师们一直在那里肆无忌惮地练习法术。迪菲亚兄弟会对这些游荡施法者的依赖，将不稳定的业余魔法引入了艾尔文森林的乡村地区。消灭这些游荡法师可以平息魔法噪音，让Bergwort的精密仪器最终读出准确的数据。"}},faq={{q="谁发布了精密仪器任务？",a="哈米什·伯格沃特在艾尔文森林东部的阿祖拉之塔内发布此任务。他正在进行的奥术研究需要稳定的魔法条件。",al={"谁发布精密仪器","精密仪器任务发布者","哈米什·伯格沃特在哪里"}},{q="是什么在干扰哈米什·伯格沃特的仪器？",a="阿祖拉之塔内的精密仪器正遭受奥术干扰，这源于当地的迪菲亚强盗，他们在石碑湖附近施展粗糙的法术。",al={"是什么在干扰仪器","为什么仪器受到干扰","精密仪器干扰"}},{q="在哪里可以找到迪菲亚潜行者法师？",a="迪菲亚潜行者法师聚集在石碑湖的岸边及其周边地区，该湖位于艾尔文森林中阿祖拉之塔的正北方。",al={"游荡法师在哪里","石碑湖的游荡法师","去哪里找迪菲亚潜行者法师"}},{q="为什么迪菲亚强盗要练习魔法？",a="虽然迪菲亚兄弟会主要由心怀不满的劳工、拦路强盗和窃贼组成，但他们也招募了一些奥术方面的流浪涉猎者。这些游荡法师未经许可练习魔法，导致该地区出现不稳定的干扰。",al={"为什么迪菲亚有法师","迪菲亚施法者","游荡法师背景"}},{q="什么是阿祖拉之塔？",a="阿祖拉之塔是位于艾尔文森林东部的一座奥术尖塔，是研究地脉、魔法异常和区域安全的人类法师和学者的避风港。",al={"什么是阿祖拉之塔","艾尔文森林阿祖拉之塔","谁负责阿祖拉之塔"}},{q="消灭这些游荡法师能解决问题吗？",a="是的。一旦你除掉了在石碑湖施法的迪菲亚潜行者法师，环境魔法共鸣就会平静下来，让哈米什·伯格沃特的仪器恢复正常运作。",al={"阻止法师有用吗","精密仪器结果","哈米什·伯格沃特仪器修复"}}},fp="20,218,25.237.0,23.270.0,42.146.0,49.108.0,44.144.0,40.167.0,27.152.0,51.154.0"}
P.entries["quest:91725"] = {n="Stolen Enchanting Supplies",s="Stolen Enchanting Supplies 是一项在艾尔文森林东部的阿祖拉之塔附近进行的跑腿任务。一位名叫 Blixie Fitzwink 的学徒在一次豺狼人伏击中遗失了一批魔法试剂，冒险者必须从石碑湖周围的营地中取回这些被盗的货物。回收这些材料可以让这位学徒免受繁重的杂役惩罚，并保证塞欧克瑞图斯大师的奥术研究有足够的补给。",h="Stolen Enchanting Supplies 是一项在艾尔文森林东部的阿祖拉之塔附近进行的跑腿任务。一位名叫 Blixie Fitzwink...",kw={"布里克希·菲兹温克","艾尔文森林","附魔补给","豺狼人","塞欧克瑞图斯大师","变形术","石碑湖","阿祖拉之塔"},ang={["class:Mage"]="在阿祖拉之塔进行的奥术研究需要精细的材料，因此回收的附魔试剂对于塞欧克瑞图斯大师门下的法师们来说至关重要。",["faction:Alliance"]="维护一条通往阿祖拉之塔的安全补给线，能让暴风城前线的法师们有足够的装备来应对艾尔文森林及更远地区的威胁。",["race:Gnome"]="像 Blixie Fitzwink 这样的侏儒学徒经常发现自己要为人类大法师处理琐事，一旦出错，往往会导致丢脸的杂役惩罚。"},sec={{t="路上的伏击",b="当协助塞欧克瑞图斯大师的学徒 Blixie Fitzwink 在贸易站和阿祖拉之塔之间遭到敌对豺狼人的伏击时，一次例行的补给运输演变成了危险的遭遇。为了保命，她丢弃了货物，导致珍贵的附魔试剂散落在石碑湖沿岸的豺狼人营地中。由于极度担心在奥术变形实验后还要面对数周的纪律性打扫任务，她请求路过的冒险者帮忙找回丢失的货物。"},{t="奥术差事与当地威胁",b="阿祖拉之塔是艾尔文森林东部的一座奥术堡垒，塞欧克瑞图斯大师在此进行机密的魔法研究。采购精细的试剂需要与当地的贸易站进行频繁的往来，但石碑湖周围日益嚣张的豺狼人群落使运输变得危机四伏。回收遗失的补给能确保塞欧克瑞图斯的研究得以不间断地进行，同时也能让这位处境困难的助手免受麻烦。"}},faq={{q="谁发布了 被盗的附魔材料 这个任务？",a="布里克茜·菲兹温克 在阿祖拉之塔附近发布这项任务。她是塞欧克瑞图斯大师的助手，在从当地贸易站运送必要补给回来的途中遭到了豺狼人的伏击。",al={"谁发布了 被盗的附魔材料","布莉克希·菲兹温克 是谁","任务发布者 布莉克希"}},{q="塞欧克瑞图斯大师是谁？",a="塞欧克瑞图斯大师是一位居住在艾尔文森林东部阿祖拉之塔的高阶人类法师。他负责监督该地区的奥术调查，并依靠助手来获取附魔试剂和研究材料。",al={"塞欧克瑞图斯大师是谁","塞欧克瑞图斯的职责","阿祖拉之塔的法师"}},{q="豺狼人抢走了什么补给？",a="包裹里装着从贸易站为塞欧克瑞图斯大师的奥术工作收集的附魔试剂。在伏击导致货物散落后，这些物品被带到了石碑湖周围的豺狼人营地。",al={"这些补给是什么","豺狼人偷了什么","附魔试剂"}},{q="豺狼人把补给带到了哪里？",a="石碑湖位于艾尔文森林东部，阿祖拉之塔的北面。豺狼人群落沿着湖岸和周围的岛屿建立了营地，对附近道路上的旅行者构成了经常性的威胁。",al={"石碑湖在哪里","豺狼人把补给藏在哪","艾尔文湖区的豺狼人"}},{q="为什么 布里克茜·菲兹温克 担心丢失包裹？",a="布里克茜 担心塞欧克瑞图斯大师会惩罚她，让她负责清理数周的变形实验残局。每当差事或魔法任务出错时，塔里的学徒就会被分配去做繁琐或肮脏的杂活。",al={"如果 布莉克希 失败了会怎样","布莉克希 的惩罚","变形术清理工作"}},{q="为什么豺狼人在艾尔文东部袭击旅行者？",a="豺狼人团伙在艾尔文森林东部游荡，在石碑湖周围建立敌对营地并袭击附近的道路。它们的存在破坏了贸易，并埋伏了往返于定居点和奥术哨所之间的落单旅行者。",al={"为什么豺狼人在阿祖拉之塔附近","艾尔文森林的豺狼人威胁","石碑湖的河爪豺狼人"}}},fp="26,279,21.384.0,32.375.0,47.167.0,25.230.0,39.194.0,39.177.0,56.195.0,53.198.0"}
P.entries["quest:91732"] = {n="Good Steel",s="“Good Steel”是联盟的一项任务，起始于艾尔文森林东部的东谷伐木场。在近期的冲突之后，高质量的金属变得非常稀缺，导致伐木场的伐木设备磨损严重且难以更换。工匠哈格·罗威委托冒险者深入玉石矿洞，回收制作精良的矿镐，以便将它们的钢材重新利用。",h="“Good...",kw={"东谷伐木场","艾尔文森林","好钢","哈格·罗威","玉石矿洞","采矿工具","战后物资短缺","钢材回收利用"},ang={["faction:Alliance"]="暴风城外围领地的物资压力意味着像东谷伐木场这样的地方定居点必须回收废弃设备，以维持其运作。",["profession:Blacksmithing"]="战后的艾尔文森林中高标号钢材依然稀缺，迫使铁匠和工匠不得不搜寻并重新利用旧的、废弃的工业工具中的金属。",["profession:Mining"]="留在玉石矿洞中的坚固矿镐展示了一种现代艾尔文工人们难以企及的、更古老且更优越的金属加工标准。"},sec={{t="王国的匮乏",b="在一系列蹂躏人类王国的毁灭性冲突之后，优质钢材在艾尔文森林中已成为一种日益稀缺的奢侈品。在东谷伐木场，日常的木材采伐极其依赖耐用的斧头、锯子和五金工具，但目前可用的工具因金属质量低劣和长期磨损而严重受损。由于暴风城的铸造厂无法提供可靠的补给，像哈格·罗威这样的伐木场工匠被迫寻找创新的解决方案，以维持伐木场的运转。"},{t="回收往昔",b="为了更换磨损的设备，哈格将目光投向了位于伐木场北部的废弃挖掘场——玉石矿洞。在矿洞荒废之前，在此开采丰富矿脉的矿工们使用着那个时代精工锻造的矿镐，那时的钢材供应充足且淬火工艺精湛。冒险者们被派往受灾严重的隧道，将这些废弃的矿镐找回，带回东谷，以便将其优良的钢材熔炼并重新制成伐木工人所需的工具，而不是让这些坚固的器具在黑暗中生锈腐朽。"}},faq={{q="谁发放“优质钢材”任务？",a="哈格·罗威是一位驻扎在艾尔文森林东部东谷伐木场的木工或工匠。由于面临优质工具的短缺，他请求冒险者从附近废弃的作业点回收优质的钢制设备。",al={"优质钢材任务发布者","优质钢材任务交还地点","哈格·罗威是谁"}},{q="为什么哈格·罗威需要从玉石矿洞获取采矿工具？",a="在近期的战争之后，王国各地优质钢材供应短缺，导致伐木场的作业工具磨损严重。哈格寻求在玉石矿洞中遗留的精工矿镐，以便将它们的钢材熔炼并重新利用，制成实用的伐木工具。",al={"为什么要获取矿镐","为什么哈格需要采矿工具","采矿工具的用途"}},{q="什么是玉石矿洞？",a="玉石矿洞是一处位于艾尔文森林东北部、东谷伐木场北方的旧采矿点。它曾是王国的一处活跃作业点，但在被占领后荒废，其精良的采矿设备散落在矿洞深处。",al={"什么是玉石矿洞","工具在哪里","玉石矿洞背景故事"}},{q="为什么优质钢材如此匮乏？",a="第三次战争和持续的冲突严重破坏了人类王国的生产、补给线和贸易。随着王国为了防御和重建而耗尽资源，像东谷这样的外围定居点必须通过回收旧时代的耐用金属来凑合度日。",al={"为什么钢材稀缺","艾尔文森林钢材短缺","战后金属短缺"}},{q="什么是东谷伐木场？",a="东谷伐木场是暴风城主要的木材采伐定居点，位于艾尔文森林东部边界，靠近赤脊山。它的伐木工人为暴风城及周边社区提供原木，因此可靠的工具对他们的工作至关重要。",al={"东谷伐木场在哪里","东谷伐木场的作用","东谷伐木场"}},{q="玉石矿洞里的工具为何如此特别？",a="遗留在玉石矿洞中的工具是在近期战争短缺导致金属供应受损之前，那个工艺水平更高的时代锻造的。正如哈格所指出的，它们持久的光泽和耐用性证明了它们是用比今天所能获取的钢材好得多的材质制成的。",al={"谁制造了这些矿镐","为什么这些矿镐质量好","采矿工具质量"}}},fp="10,208,20.345.0,18.365.0,31.179.0,59.189.0,24.183.0,34.248.0,30.234.0,51.209.0"}
P.entries["quest:91733"] = {n="Downstream",s="“下游”是艾尔文森林东部的一项任务，由东谷伐木场的奥尔明·佩尔福德（Ormin Pelford）发布。在奥尔明的货车意外翻入河中后，冒险者们受托前往下游，在鱼人和狼群的威胁下取回那些浸水的木工补给品。",h="“下游”是艾尔文森林东部的一项任务，由东谷伐木场的奥尔明·佩尔福德（Ormin Pelford）发布。在奥尔明的货车意外翻入河中后，冒险者们受托前往下游，在鱼人和狼群的威胁下取回那些浸水的木工补给品。",kw={"下游","东谷伐木场","艾尔文森林","鱼人","奥尔明·佩尔福德","浸水的斧头","浸水的锯子","浸水的工具箱"},ang={["faction:Alliance"]="确保东谷伐木场拥有充足的工具，可以保证重要的木材补给持续供应给暴风城和艾尔文森林的各个定居点。"},sec={{t="路上的事故",b="劳工奥尔明·佩尔福德在从当地贸易站运送一批装备回来的途中遭遇了事故，他的货车在东谷伐木场附近的河道旁翻倒了。货物滚入水中，在他还没来得及将其固定住时就被水流冲到了下游。没有了这些至关重要的木工工具，伐木工们的木材作业将面临延误。"},{t="河岸边的危险",b="回收这些浸水的货物因当地危险的野生生物而变得复杂。具有攻击性的鱼人占据了下游泥泞的浅滩，而掠食性的狼群则在周围的树林中游荡。由于无法独自抵御这些威胁，奥尔明只能依靠勇敢的旅行者们前往河岸，打捞起沉没的锯子、斧头和工具箱，并安全地带回来。"}},faq={{q="谁发布了“下游”这个任务？",a="奥尔明·佩尔福德在东谷伐木场附近发布了这项任务。他是一名工人在从贸易站运送货物时，不慎将补给车翻进了河里。",al={"谁发布下游任务","下游任务发布者","奥尔明·佩尔福德是谁"}},{q="哪些补给品掉进了水里？",a="遗失的货物包括一把浸水的斧头、一把浸水的锯子和一个浸水的工具箱，它们是在奥尔明·佩尔福德的货车翻倒时滑入水中的。",al={"什么东西掉进了河里","下游遗失的货物","下游有什么物品"}},{q="补给品被冲到了哪里？",a="板条箱和工具沿着艾尔文森林东部东谷伐木场以南的河流漂到了下游。",al={"工具在哪里","补给品被冲到哪里","下游位置"}},{q="为什么奥尔明·佩尔福德不能亲自去取回补给品？",a="奥尔明无法独自冒险前往河岸，因为货物漂流的水域中潜伏着掠食性的河中鱼人和饥饿的森林狼。",al={"为什么奥尔明无法取回补给","为什么奥尔明·佩尔福德需要帮助"}},{q="河岸边潜伏着什么危险？",a="下游的河岸充斥着具有攻击性的鱼人和游荡的狼群，这使得打捞工作对于手无寸铁的劳工来说非常危险。",al={"下游河流危险","下游威胁"}},{q="为什么这些工具对东谷伐木场很重要？",a="斧头、锯子和工具箱是东谷伐木场的伐木工人们必不可少的装备，他们为艾尔文森林和暴风城提供原木。",al={"为什么东谷的工具很重要","伐木场木材工具"}}},fp="10,176,20.299.0,26.343.0,31.162.0,37.136.0,31.112.0,54.107.0,39.104.0,42.142.0"}
P.entries["quest:91736"] = {n="Applejack Still",s="Applejack Still是一种蒸馏装置，用于将发酵后的苹果加工成高浓度的烈酒。靠近该装置会闻到一股刺鼻的浓缩果味，机器将其冷凝后会流出清澈的烈酒。",h="Applejack Still是一种蒸馏装置，用于将发酵后的苹果加工成高浓度的烈酒。靠近该装置会闻到一股刺鼻的浓缩果味，机器将其冷凝后会流出清澈的烈酒。",kw={"酒精","装置","苹果白兰地","酿造","苹果酒","酿酒厂","烈酒","蒸馏器"},ang={["profession:Cooking"]="用收获的果园水果蒸馏和酿造烈酒是艾泽拉斯各地乡村厨师和酒馆老板的一项基本工艺。",["profession:Engineering"]="该装置利用机械冷凝和管道系统自动将发酵的苹果酒加工成浓缩烈酒。"},sec={{t="蒸馏装置",b="Applejack Still是一种功能性的蒸馏装置，旨在将发酵的苹果酒提纯为高浓度烈酒。任何靠近该装置的人，立刻就会闻到一股刺鼻的浓缩苹果味，足以灼伤鼻腔。它的管道和冷凝管能高效地萃取并浓缩果园收获的精华，制成强劲的烈酒。"},{t="清澈的酒液",b="一旦启动并让其运转，机器会将蒸发的酒精冷凝成清澈、纯净的烈酒。成品苹果白兰地会整齐地流入出口处的待装瓶中，随时可供饮用或储存。尽管在野外蒸馏的条件较为简陋，该装置依然能可靠地酿造出清澈强劲的酒液。"}},faq={{q="什么是苹果酒蒸馏器？",a="苹果酒蒸馏器是一种机械蒸馏装置，旨在生产苹果白兰地（苹果白兰地），这是一种由苹果制成的烈性酒。检查并操作该机器时，它会将发酵的苹果泥或苹果酒冷凝成清澈的蒸馏酒，直接流入瓶中。",al={"什么是苹果白兰地蒸馏器","这是什么装置","蒸馏器有什么用"}},{q="为什么蒸馏器周围的苹果味如此浓烈？",a="检查该装置会发现一股刺鼻、浓烈的浓缩苹果味，足以灼伤鼻腔。这种强度来自于酒精在金属管内蒸发和再冷凝时产生的高浓度蒸汽。",al={"闻起来是什么味道","为什么会有灼烧感","蒸馏器的气味"}},{q="机器流出的是什么液体？",a="操作机器后，它会直接将清澈的液体分装到瓶子里。这种蒸馏酒就是苹果白兰地，是一种通过蒸馏过程制成的清澈且强劲的果味白兰地。",al={"流出的是什么液体","蒸馏出的清澈液体","它会流出什么"}},{q="蒸馏装置是如何运作的？",a="该蒸馏器通过加热发酵的苹果酒或酒醪，将挥发性的酒精蒸汽与水和果渣分离，并将蒸汽冷凝回液体。产生的蒸馏酒会聚集在出酒口，流入等待装酒的瓶子中。",al={"苹果白兰地蒸馏器如何运作","蒸馏过程"}},{q="苹果白兰地到底是什么？",a="苹果白兰地（苹果白兰地）是一种传统的烈性酒精饮料，由发酵的苹果酒蒸馏而成。产生的烈酒清澈、芳香，且酒精含量明显高于普通的苹果酒或麦芽酒。",al={"什么是苹果白兰地","苹果白兰地饮料"}},{q="操作该蒸馏器有危险吗？",a="该蒸馏器产生的酒精蒸汽浓度很高，检查时足以刺激鼻腔。虽然它能够正常运作并流出清澈的烈酒而不会爆炸，但处理高浓度酒精蒸汽和压力时仍需谨慎。",al={"蒸馏器安全吗","有危险吗"}}},fp="15,113,23.193.0,12.225.0,28.147.0,50.170.0,46.122.0,41.196.0,26.151.0,33.148.0"}
P.entries["quest:91738"] = {n="An Apple Treat",s="一位军士已有数月没见过Thunder Applejack，如今很高兴收到一瓶。他说，这应该能让士兵们高兴起来。",h="一位军士已有数月没见过Thunder Applejack，如今很高兴收到一瓶。他说，这应该能让士兵们高兴起来。",kw={"an apple treat","瓶子","军士","thunder applejack","士兵"},sec={{t="受欢迎的一瓶酒",b="一位军士认出了你带来的Thunder Applejack，说士兵们见到它一定会很高兴。他感谢你把酒带来。"}},faq={{q="军士想要什么？",a="军士很高兴收到一瓶Thunder Applejack，他说这应该能给士兵们带来一些欢乐。",al={"他需要什么","军士 applejack","apple treat"}},{q="他有多久没见过Thunder Applejack了？",a="军士说，他已经好几个月没见过Thunder Applejack了。",al={"applejack 多久","好几个月没有了","上次见到applejack是什么时候"}},{q="这瓶酒是给谁的？",a="军士说，这瓶酒应该能让士兵们的脸上露出笑容。",al={"applejack给谁","给士兵的applejack","谁想要这瓶酒"}}},fp="14,111,16.115.0,28.102.0,52.62.0,22.69.0"}
P.entries["quest:91740"] = {n="Croaky's Head",s="Croaky's Head 是一名凶恶鱼人首领被斩下的头颅，也是领取悬赏的凭证；这名首领曾在艾尔文森林东部的道路上肆虐。将它的死讯凭证交给山巅之塔的暴风城卫兵，能让哀悼阵亡同袍的驻军得到一丝沉重的慰藉。对于奋力守住艾尔文争夺不休的水道的当地守军而言，这标志着一次至关重要的胜利。",h="Croaky's Head...",kw={"呱呱","呱呱的头颅","东谷","艾尔文森林","梅雷尔·罗斯","鱼人","山巅之塔","暴风城卫兵"},ang={["class:Warrior"]="战士深知前线战斗的残酷现实，也明白阵亡卫兵付出的代价。挺身而出，击杀凶悍的部族酋长，便能缓解防线承受的重压。",["faction:Alliance"]="作为王国腹地的保卫者，联盟勇士通过消灭那些捕食旅人的危险领袖，直接援助了暴风城人手不足的部队。确保东部边境公路的安全，加强了联盟在艾尔文森林和赤脊山之间的管辖权。",["race:Human"]="对于艾尔文的人类而言，鱼人的入侵威胁着他们的家园，也夺走了当地城镇卫兵的性命。击杀 Croaky，既能为两名阵亡卫兵讨回公道，也能保卫王国的腹地。"},sec={{t="东谷道路上的恐怖",b="艾尔文森林河流与溪涧沿岸的鱼人日益猖獗，伏击毫无戒备的旅人，威胁着重要商路。在这些水栖劫掠者中，Croaky 是一名格外凶悍的酋长，它纠集其他鱼人，在紧邻当地道路的地方发动袭击。对于往来于艾尔文和赤脊山之间的商人、农夫与旅人而言，这个生物的存在让原本宁静的道路变成了危机四伏的险地。击杀这个凶悍的劫掠者，便能终结接连不断的伏击，铲除这个公然挑战暴风城对东部林地边缘地区统治的猖狂祸患。"},{t="山巅之塔的守望",b="山巅之塔是暴风城在艾尔文森林最东端的哨所，守卫着通往赤脊山的战略要道。驻守此地的卫兵由 Merell Ross 军官率领，面对周围的种种威胁，已然疲于应付。鱼人愈演愈烈的袭击最近夺走了两名巡逻卫兵的性命，令哨所上下深受震动，也暴露出边境如今何等脆弱。将 Croaky 被斩下的头颅交给 Ross 军官，便能以实物证明大仇已报，提振陷入困境的驻军士气，让守军终于有机会将这些水栖劫掠者逐出艾尔文的边境。"}},faq={{q="呱呱 是谁？",a="呱呱 是一名臭名昭著的鱼人首领，曾在艾尔文森林东部的水道沿岸袭扰旅人和当地巡逻队。这个生物以在道路附近组织凶猛的伏击而闻名，严重威胁着当地的安宁，直到一名冒险者将其猎杀。",al={"呱呱 是谁","呱呱 的故事","呱呱 是什么鱼人"}},{q="梅雷尔·罗斯 是谁？",a="梅雷尔·罗斯 是暴风城城市卫队的一员，驻守在艾尔文森林东部边境的山巅之塔。罗斯 负责保护通往赤脊山的大道，维持边境地区的安全，并在凶猛的鱼人袭击导致卫兵阵亡后，设法重振驻军的士气。",al={"梅雷尔·罗斯","罗斯 军官是谁","山巅之塔指挥官"}},{q="山巅之塔位于何处？",a="山巅之塔位于艾尔文森林最东端，守卫着通往赤脊山的道路。这座石砌堡垒坐落在东谷伐木场以东，是暴风城卫兵抵御敌对生物与拦路匪徒的前沿防御据点。",al={"山巅之塔在哪里","山巅之塔位置","如何找到山巅之塔"}},{q="山巅之塔的卫兵为何想要杀死 呱呱？",a="驻守山巅之塔的暴风城卫兵最近损失惨重，两名巡逻队员在周围的林地和水域遭鱼人杀害。卫兵们希望除掉这名鱼人首领，制止道路上持续不断的伏击，并开始合力将这些生物逐出艾尔文。",al={"为何击杀 呱呱","卫兵为何想要 呱呱的头颅","鱼人袭击山巅之塔卫兵"}},{q="交付 呱呱的头颅 对艾尔文森林有何作用？",a="将 呱呱的头颅 送到山巅之塔，能让驻军确认，那个在路旁组织袭击的危险头目已经伏诛。鱼人首领死后，卫兵们希望重新掌握攻势，确保东部商路的安全，并逐步将不断进犯的鱼人部族赶出艾尔文的河岸。",al={"呱呱的头颅 的用途","击杀 呱呱 后会怎样","交付 呱呱的头颅"}},{q="鱼人为何对艾尔文的道路构成如此大的威胁？",a="鱼人常在艾尔文森林的河流、湖泊与溪涧沿岸筑巢。由于重要道路沿着这些水道延伸，凶悍的部族经常伏击毫无防备的旅人、商队和孤立的巡逻队，凭借数量优势与协同进攻，以及凶猛而难以预料的袭击压倒守军。",al={"鱼人为何袭击道路","艾尔文 的鱼人问题","艾尔文 的鱼人威胁"}}},fp="13,224,28.411.0,29.486.0,15.225.0,19.274.0,34.227.0,56.215.0,64.226.0,51.250.0"}
P.entries["quest:91741"] = {n="Nibbled-On Book",s="Nibbled-On Book是北郡修道院图书馆的一册藏书，从北郡山谷的狗头人拾荒者手中找回。书上留着某只糊涂或饥饿的生物啃咬的齿痕，必须将它归还给帕克斯顿修士，以保全修道院为数不多的藏书。",h="Nibbled-On Book是北郡修道院图书馆的一册藏书，从北郡山谷的狗头人拾荒者手中找回。书上留着某只糊涂或饥饿的生物啃咬的齿痕，必须将它归还给帕克斯顿修士，以保全修道院为数不多的藏书。",kw={"修道院图书馆","帕克斯顿修士","艾尔文森林","狗头人","被啃过的书","北郡修道院","失窃的书"},ang={["faction:Alliance"]="北郡修道院是艾尔文森林中新晋联盟招募人员的摇篮，在那里，即便是找回被盗修道院财产这样的小差事，也有助于保障当地山谷的安全。",["race:Human"]="北郡修道院内的图书馆为暴风城王国保存着当地的教务与历史知识，因此，找回遗失的典籍与北郡居民息息相关。"},sec={{t="被啃过的书",b="在侵扰北郡山谷的地下害物中，狗头人是出了名的拾荒者，凡是无人看管的东西，都会被它们拖走。当一名冒险者从被杀死的狗头人身上找回一本被啃过的书时，显然，这只生物不只是在囤积闪亮的小玩意，还在使劲啃咬封皮和羊皮纸。书籍显然来自附近北郡修道院的图书馆书架，上面留下了这些害物贪吃的痕迹。"},{t="帕克斯顿修士的困境",b="在北郡修道院内，帕克斯顿修士尽心照料着一座小图书馆，供北郡兄弟会静思与学习。不幸的是，在山谷中游荡的无耻害物养成了一个令人头疼的习惯：偷偷溜进来，直接从书架上偷走书籍。虽然帕克斯顿修士很感激能找回这本被啃过的书，但其余散失的藏书仍落在山谷的害物手中，让他忧心不已。"}},faq={{q="被啃过的书是什么？",a="被啃过的书是肆虐的狗头人从北郡修道院偷走的一册图书馆藏书。找回时，书上留着清晰的齿痕，表明这些地下害物可能把羊皮纸和皮革装帧当成了食物。",al={"这本书是什么","被啃过的书的故事","狗头人掉了什么书"}},{q="狗头人为什么想吃这本书？",a="狗头人主要在地下拾荒，痴迷于蜡烛和采矿，但它们也经常囤积或啃咬一切能搜罗到的东西。帕克斯顿修士哀叹道，这些害物似乎就是为了啃咬或吃掉他的书，才特意来偷书的。",al={"狗头人为什么要书","狗头人为什么吃书","狗头人食物书籍"}},{q="帕克斯顿修士是谁？",a="帕克斯顿修士是一位住在北郡修道院内的牧师，负责照管修道院的小图书馆及其文献藏品。狗头人偷偷溜进修道院，从他的书架上窃取书籍，令他苦恼不已。",al={"帕克斯顿修士是谁","帕克斯顿 北郡","修道院图书管理员"}},{q="这本书原本来自哪里？",a="这本书原本属于北郡修道院内由帕克斯顿修士照管的小图书馆，应当放在那里的书架上；修道院坐落于艾尔文森林幽静的北郡山谷。",al={"这本书来自哪里","帕克斯顿把书放在哪里","北郡图书馆"}},{q="修道院的图书馆还有其他遗失的书吗？",a="有，收到归还的书后，帕克斯顿修士忧心地提到，狗头人已经多次从他的书架上偷书，他不知道该如何找回其余遗失的藏书。",al={"还有更多书遗失吗","其余藏书","狗头人还偷了其他书吗"}},{q="这本书应该归还给谁？",a="找回的书必须直接归还给北郡修道院内的帕克斯顿修士，他会查看那留有齿痕的封皮，再将书收回保管。",al={"如何找回这本书","谁想要被啃过的书","把书归还给帕克斯顿"}}},fp="15,146,13.284.0,23.321.0,28.153.0,40.158.0,22.160.0,40.121.0,55.145.0,35.136.0"}
P.entries["quest:91743"] = {n="Rascally Rodents",s="“Rascally Rodents”是北郡山谷的一项任务，帕克斯顿修士委托冒险者从当地的狗头人手中追回被窃的书籍。起初，帕克斯顿担心这些害虫在啃食他的藏书，但当书本被找回后，却揭开了一个关于这些生物动机的令人不安的谜团。",h="“Rascally Rodents”是北郡山谷的一项任务，帕克斯顿修士委托冒险者从当地的狗头人手中追回被窃的书籍。起初，帕克斯顿担心这些害虫在啃食他的藏书，但当书本被找回后，却揭开了一个关于这些生物动机的令人不安的谜团。",kw={"帕克斯顿修士","狗头人","图书馆","北郡修道院","北郡山谷","捣蛋的啮齿动物","被窃的书籍"},ang={["class:Mage"]="奥术学者明白书面知识和著作的不可替代价值，即使是在面对像狗头人这样的非寻常小偷的威胁时也是如此。",["class:Priest"]="协助北郡修道院的牧师致力于维护圣光信徒在学术传承上的神圣性，保护珍贵的文本免遭破坏。",["race:Human"]="在北郡山谷开始训练的人类新手被召集起来，以保护修道院的宝藏和学术著作免受投机取巧的害虫和入侵者的侵害。"},sec={{t="对图书馆的威胁",b="位于北郡山谷的帕克斯顿修士因为当地的狗头人入侵而感到苦恼，这些狗头人从周围的山丘和矿洞中涌入神圣的领地。他确信这些贪婪的生物开始啃食他藏书中的文本，于是他召集年轻的冒险者去猎杀这些害虫，并在图书馆彻底毁坏前抢救出尽可能多的卷轴。"},{t="无法解释的食欲",b="在从山谷的狗头人手中找回八本被窃的书籍后，帕克斯顿修士发现了一些意想不到的事实：这些生物其实并没有吃掉纸张或装订。相反，狗头人是在刻意窃取并囤积这些书籍，目的不明，这让修士感到深感不安，因为山谷中还有许多下落不明的书籍。"}},faq={{q="谁发放了“捣蛋的啮齿动物”这个任务？",a="帕克斯顿修士是一位修道院的居民，他急于保护修道院的图书馆免受侵扰山谷的害虫破坏，并将这项任务提供给北郡山谷的冒险者。",al={"谁发放捣蛋的啮齿动物任务","捣蛋的啮齿动物任务发放者","帕克斯顿书籍任务"}},{q="为什么狗头人要偷书？",a="帕克斯顿修士起初认为狗头人真的在吃他的书。然而，在检查了找回的书籍后，他意识到它们根本没有被吃掉，这使得它们对文本的真实意图和兴趣成为了一个令人不安的谜题。",al={"为什么狗头人要拿书","狗头人吃书吗","为什么狗头人想要书"}},{q="在哪里可以找到被窃的书籍？",a="被窃的书籍可以在侵扰北郡山谷的狗头人身上找到，它们从当地的藏书中掠夺了这些文本，并将它们带回了自己的营地和矿洞工作区。",al={"哪里可以找到被窃的书籍","被窃书籍位置","北郡狗头人书籍"}},{q="帕克斯顿修士是谁？",a="帕克斯顿修士是北郡兄弟会的一员，他深切关心着山谷中的书面著作，并依靠过往的新手将它们从当地的拾荒者手中解救出来。",al={"谁是帕克斯顿修士","帕克斯顿修士背景故事"}},{q="帕克斯顿修士给你什么奖励？",a="在归还八本被窃书籍后，帕克斯顿修士感激地给了你一本他宣称自己不需要的“操作指南”书籍，同时也感叹仍有许多书籍下落不明。",al={"帕克斯顿给什么奖励","操作指南书籍奖励"}},{q="所有的被窃书籍都找回了吗？",a="没有。即使在找回八本被窃书籍后，帕克斯顿修士指出仍有许多卷轴在山谷中丢失，而狗头人对它们那奇怪的兴趣至今仍无法解释。",al={"书全找回了吗","书都救回来了吗"}}},fp="16,139,23.286.0,23.254.1,37.116.0,35.149.0,35.99.0,22.158.0,46.148.0,35.128.0"}
P.entries["quest:91745"] = {n="Mining Consultant",s="Mining Consultant是北郡山谷的一个任务，它要求冒险者前往回音山矿洞外与矿业学徒Kelsey Fargo商谈。她的观察揭示了一个不同寻常的情况：当地的狗头人开始从北郡修道院的图书馆掠夺书籍。",h="Mining Consultant是北郡山谷的一个任务，它要求冒险者前往回音山矿洞外与矿业学徒Kelsey Fargo商谈。她的观察揭示了一个不同寻常的情况：当地的狗头人开始从北郡修道院的图书馆掠夺书籍。",kw={"回音山矿洞","凯尔希·法戈","狗头人","图书馆","采矿","采矿顾问","北郡修道院","北郡山谷"},ang={["profession:Mining"]="Kelsey Fargo担任驻扎在回音山矿洞外的矿业学徒，为寻求了解矿业工作和附近情况的潜在矿工提供了一个切实的当地联络人。",["race:Human"]="北郡山谷是人类新冒险者的训练场，确保修道院宝贵的档案和附近的矿洞免受狗头人入侵对于区域稳定至关重要。"},sec={{t="矿洞里的麻烦",b="回音山矿洞的狗头人骚乱出现了意想不到的发展。这些生物不仅仅是在保卫地下领地和收集蜡烛，它们奇怪而协调的干扰行为引起了当地当局的注意。冒险者们被指引去寻找驻扎在矿洞入口附近的矿业学徒Kelsey Fargo，以确认她在隧道外观察到了什么。"},{t="嗜书的拾荒者",b="Kelsey Fargo证实了矿洞里的害虫表现出了古怪的行为：人们看到狗头人搬着厚重的书卷跑来跑去，并在彼此间争吵。Kelsey推断这些书卷是直接从北郡修道院内的图书馆偷来的，这让人担心这些目不识丁的穴居生物到底想拿偷来的学术文献做什么。"}},faq={{q="凯尔希·法戈是谁？",a="凯尔希·法戈是一名驻扎在北郡山谷回音山矿洞入口处的矿业学徒。由于她的工作岗位，她处于观察当地狗头人异常活动和习性的最佳位置。",al={"凯尔希·法戈是谁","凯尔希·法戈的角色","北郡的矿业学徒"}},{q="为什么狗头人要带着书？",a="据凯尔希·法戈所说，有人看到狗头人边吵架边带着书跑来跑去。她怀疑它们是直接从北郡修道院内的图书馆偷走了书卷，尽管它们具体的目的仍然是个谜。",al={"为什么狗头人要偷书","狗头人在看书","回音山矿洞里的书"}},{q="回音山矿洞在哪里？",a="回音山矿洞位于北郡山谷的西北部，隐藏在北郡修道院西北的山丘中。它已经被大量的狗头人所占据，这些狗头人破坏了采矿作业。",al={"回音山矿洞在哪里","回音山矿洞位置"}},{q="狗头人是从哪里弄到这些书的？",a="据信这些被盗的书籍取自北郡修道院内的图书馆，那里存放着由当地人类神职人员和学者维护的记录、经文和历史书籍。",al={"书从哪里来","修道院图书馆的狗头人"}},{q="咨询矿业学徒的目的是什么？",a="该任务引导冒险者去矿洞外找凯尔希·法戈，以调查有关狗头人异常活动的报告，并了解她在现场驻扎时观察到的情况。",al={"采矿顾问任务目标","为什么要和凯尔希交谈"}},{q="狗头人表现出了什么奇怪的行为？",a="除了常规的领地拾荒和挖掘外，回音山矿洞周围的狗头人被观察到互相吼叫并搬走书面文本，表现出异常不寻常的协调性。",al={"狗头人在做什么","北郡狗头人的行为"}}},fp="17,140,19.354.0,20.249.1,20.168.0,31.186.0,25.165.0,42.165.0,56.147.0,49.202.0"}
P.entries["quest:91746"] = {n="Elmpaw's Head",s="Elmpaw's Head 是一项战利品任务，旨在奖励那些猎杀了强大野兽 Elmpaw 的冒险者。这颗野兽的头颅会被交给一位工匠，他负责将这些头颅制成供富有的收藏家所使用的标本。",h="Elmpaw's Head 是一项战利品任务，旨在奖励那些猎杀了强大野兽 Elmpaw 的冒险者。这颗野兽的头颅会被交给一位工匠，他负责将这些头颅制成供富有的收藏家所使用的标本。",kw={"野兽","收藏家","榆爪","头颅","猎人","壁炉台","战利品"},ang={["class:Hunter"]="击倒像 Elmpaw 这样强大的野兽并获得实体战利品，是娴熟的追踪者和猎人的典型标志。"},sec={{t="倒下的野兽",b="Elmpaw's Head 标志着针对名为 Elmpaw 的生物的狩猎任务的终结。对于荒野追踪者和收藏家来说，击杀这样的野兽被视为一项令人印象深刻的成就，他们看重的是战胜危险野生动物的实质性证据。"},{t="收藏家的奖赏",b="在呈交 Elmpaw 的断头后，猎人会直接获得一位精明的经办人的奖励。接收者不会让这些遗骸白白浪费，而是会将它们处理并制成战利品，出售给那些希望用凶猛的野生战利品装饰自家壁炉台的富裕顾客。"}},faq={{q="榆爪 是谁或什么东西？",a="榆爪 是一头强大的生物，击败它被认为是一项了不起的壮举。虽然关于它物种的具体细节很少，但猎人们仍在搜寻这头野兽，以获取它的头颅作为珍贵的战利品。",al={"谁是 榆爪","榆爪 是什么","榆爪 首领"}},{q="为什么任务发布者想要 榆爪 的头颅？",a="任务发布者将头颅制成标本并进行展示，他指出富有的收藏家愿意花大价钱购买这些珍奇的战利品，用来装饰他们的壁炉台。",al={"为什么要头颅","榆爪 的头颅交任务","战利品有什么用"}},{q="哪些收藏家对这个战利品感兴趣？",a="任务发布者与那些重视珍奇野兽战利品并将其陈列在家中的富有收藏家有生意往来。一旦处理得当，这种头颅标本在这些爱好者手中能卖出高价。",al={"谁购买战利品","榆爪 的买家","谁想要 榆爪 的头颅"}},{q="榆爪 是个危险的目标吗？",a="任务发布者将击败 榆爪 描述为非常令人印象深刻，这表明该野兽是一个重大的挑战，或者是某种罕见的掠食者，而非普通的野生动物。",al={"榆爪 有多难","榆爪 是否强力"}},{q="榆爪的头颅 是什么样的任务？",a="它的作用相当于赏金和战利品交易。冒险者在野外击败 榆爪，猎取它的头颅，并将其带给感兴趣的一方。在对方准备将其制成标本以供转售之前，会给予冒险者奖励。",al={"榆爪 的头颅是赏金任务吗","谁发布了 榆爪 任务"}},{q="在哪里可以找到 榆爪？",a="榆爪 在冒险者和大型狩猎追踪者与危险野兽狭路相逢的荒野中游荡。一旦你获胜，就将它的头颅带回给收藏家吧。",al={"榆爪 的位置","哪里能找到 榆爪"}}},fp="13,169,16.153.0,19.158.0,22.120.0,44.131.0,48.137.0,29.96.0,35.130.0,26.117.0"}
P.entries["quest:91751"] = {n="Rough Wolf Pelts",s="Rough Wolf Pelts是艾尔文森林的一项新手剥皮任务，由闪金镇附近的海伦尼·派特斯金纳提供。由于她的丈夫在北郡修道院附近帮忙，海伦尼指望能干的剥皮手收集当地狼群的生皮，以完成她积压的制皮订单。",h="Rough Wolf Pelts是艾尔文森林的一项新手剥皮任务，由闪金镇附近的海伦尼·派特斯金纳提供。由于她的丈夫在北郡修道院附近帮忙，海伦尼指望能干的剥皮手收集当地狼群的生皮，以完成她积压的制皮订单。",kw={"艾尔文森林","闪金镇","海伦尼·派特斯金纳","制皮","毛皮","粗糙的狼皮","剥皮","森林狼"},sec={{t="剥皮者的需求",b="海伦尼·派特斯金纳就在闪金镇外勤恳地工作，为旅客和居民提供熟制皮革和毛皮。虽然她的丈夫通常会狩猎艾尔文森林里潜行的森林狼来维持她工作室的供应，但北郡修道院附近的职责使他暂时离开了工作台。因为积压了许多客户的订单需要完成，海伦尼向路过的学徒寻求帮助，希望他们能将剥皮刀对准当地的野生动物。"},{t="森林潜行者",b="艾尔文森林茂密的林地里到处都是森林狼，它们在农田和道路边缘潜行。对于新手剥皮手来说，收集Rough Wolf Pelts是在剥皮行业中积累实战经验的好方法。上交这些毛皮可以让海伦尼维持她的生意，让交易在闪金镇继续流通，同时也为游荡的猎人们提供了一个磨练技艺的机会。"}},faq={{q="海伦尼·派特斯金纳是谁？",a="海伦尼·派特斯金纳是一位当地的剥皮师和制皮师，工作地点位于艾尔文森林的闪金镇外。她为旅客和当地居民准备毛皮并完成手工订单。由于她的丈夫在北郡修道院附近帮忙，她只能依靠路过的冒险者来收集完成交易工作所需的新鲜狼皮。",al={"海伦尼·派特斯金纳是谁","海伦尼·派特斯金纳","谁发布了粗糙的狼皮任务"}},{q="为什么海伦尼需要狼皮？",a="海伦尼正在处理闪金镇附近积压的皮革订单，需要原材料来维持她的生意。通常情况下，她的丈夫会通过狩猎狼群来供货，但他在艾尔文森林其他地方的任务使她短缺了粗糙的狼皮。冒险者们可以通过剥取当地狼群的皮来帮助她填补这一缺口。",al={"为什么需要粗糙的狼皮","为什么要收集毛皮","海伦尼用毛皮做什么"}},{q="海伦尼的丈夫在哪里？",a="海伦尼的丈夫通常会协助她狩猎狼群并获取毛皮，但他目前在北边的北郡修道院忙碌。由于他的缺席，海伦尼必须雇佣当地的冒险者来获取狼皮，这样她才能跟上工作室持续不断的毛皮订单。",al={"海伦尼的丈夫在哪里","海伦尼的丈夫","海伦尼的丈夫是谁"}},{q="艾尔文森林里的狼在哪里可以找到？",a="粗糙的狼皮可以从游荡在闪金镇和北郡周围艾尔文森林林地的森林狼身上获得。那些练习剥皮技能的人可以直接从森林各处的野兽身上剥取这些毛皮，然后交回海伦尼的制皮点。",al={"哪里可以找到粗糙的狼皮","哪种狼掉落毛皮","艾尔文森林的狼的位置"}},{q="收集这些毛皮需要剥皮技能吗？",a="海伦尼明确表示，这项任务是让旅客练习剥皮技能的机会。目标要求真正剥取被杀死的狼，而不是单纯为了掉落战利品而狩猎，这使其特别适合正在学习剥取动物毛皮的学徒。",al={"收集粗糙的狼皮需要剥皮吗","粗糙的狼皮剥皮要求","闪金镇剥皮任务"}},{q="在哪里可以找到海伦尼·派特斯金纳？",a="海伦尼·派特斯金纳在艾尔文森林的中心定居点闪金镇附近工作。她的皮革贸易点靠近城镇，沿着国王之路移动的猎人和旅客可以很方便地给她送去刚收获的森林毛皮。",al={"海伦尼·派特斯金纳在哪里","海伦尼·派特斯金纳位置","哪里能找到海伦尼"}}},fp="16,175,16.310.0,22.260.0,26.264.0,32.238.0,26.172.0,44.154.0,44.154.0,38.200.0"}
P.entries["quest:91752"] = {n="The Big Picture",s="The Big Picture是一项北郡山谷的任务，内容是关于一只名为“探光者”纳夫的贪婪狗头人，它在当地矿井深处囤积了许多被偷来的书籍。冒险者们受当地当局派遣，负责追回这些带插图的书籍，并将它们交还给北郡修道院的治安官玛克布莱德。",h="The Big...",kw={"帕克斯顿修士","狗头人","治安官玛克布莱德","纳夫","北郡修道院","图画书","探光者纳夫","大局"},ang={["faction:Alliance"]="北郡山谷是新晋联盟勇士的训练场和避难所，在那里维持和平并从入侵的害虫手中追回被盗物资是至关重要的工作。",["race:Human"]="北郡修道院是新招募的人类冒险者踏上保护暴风城边远领土之路的摇篮。"},sec={{t="狗头人窃书贼",b="一件怪事打破了北郡山谷的平静：潜伏在附近的狗头人被发现成群结队地溜走，怀里还抱着书，嘴里叫喊着“纳夫要图画书！”虽然狗头人通常以搜集蜡烛和小亮晶晶而臭名昭著，但其中一只名为“探光者”纳夫的洞穴居民却对带插图的著作产生了兴趣，并在他的地下巢穴里积攒了一整袋的书。"},{t="收回修道院的书籍",b="矿井深处的矿坑里藏匿着更强壮、更凶恶的狗头人，它们拼死守护着纳夫和他那堆古怪的藏品。想要追回失窃的文献，就必须深入这些黑暗的坑道，直接与纳夫对峙。一旦从这只生物的爪牙中夺回那袋书，就可以将其带给北郡修道院的治安官玛克布莱德，他会确保这些珍贵的书籍被安全地送还给帕克斯顿修士。"}},faq={{q="“探光者”纳夫是谁？",a="“探光者”纳夫是一只狗头人首领，位于北郡山谷附近的矿井深处。他一直在囤积偷来的书籍并叫喊着要图画书，这促使当地当局下令追回他的藏品。",al={"纳夫是谁","探光者纳夫背景故事","纳夫狗头人"}},{q="为什么狗头人要偷书？",a="从矿井里出来的狗头人被发现一边抢夺阅读材料，一边叫喊着“纳夫要图画书！”纳夫似乎并不是出于学术兴趣，而是痴迷于收集带插图的著作，并把它们塞进深处坑道里的一个袋子里。",al={"为什么狗头人想要图画书","什么是纳夫要图画书","为什么书会被偷"}},{q="这些书是谁被偷的？",a="帕克斯顿修士是北郡修道院的一位居民，这些失窃的书籍就是属于他的。一旦追回的书籍袋被送到治安官玛克布莱德手中，它们就会被安排直接送还给帕克斯顿修士的藏书阁。",al={"帕克斯顿修士是谁","帕克斯顿的书"}},{q="治安官玛克布莱德是谁？",a="治安官玛克布莱德是驻扎在北郡修道院内的当地执法官，负责维护治安、保护修道院土地，并组织抵御当地狗头人的威胁。",al={"治安官玛克布莱德是谁","玛克布莱德在哪里"}},{q="在哪里可以找到“探光者”纳夫？",a="纳夫居住在北郡山谷当地矿井更深处、更危险的隐蔽点，周围环绕着守卫它们搜刮来的赃物的更凶残的狗头人。",al={"纳夫在哪里","去哪里找纳夫","矿井位置"}},{q="纳夫居住的矿井有多危险？",a="虽然矿井外的普通狗头人只是些讨厌的拾荒者，但深入坑道与纳夫一起居住的狗头人要凶狠和敌对得多，这使得纳夫和他的巢穴对于孤身一人的冒险者来说非常危险。",al={"纳夫危险吗","可以单挑纳夫吗"}}},fp="15,167,21.249.0,28.281.1,24.178.0,35.167.0,24.186.0,23.178.0,36.143.0,43.163.0"}
P.entries["quest:91753"] = {n="An Enchanting Lesson",s="An Enchanting Lesson 是一个由艾尔文森林的阿祖拉之塔中的基塔·火风提供的任务。它指导修行者检查狗头人地卜师的粗糙蜡像，证明实践实验对附魔而言与正式的奥术理论同样至关重要。",h="An Enchanting Lesson 是一个由艾尔文森林的阿祖拉之塔中的基塔·火风提供的任务。它指导修行者检查狗头人地卜师的粗糙蜡像，证明实践实验对附魔而言与正式的奥术理论同样至关重要。",kw={"附魔课程","分解术","艾尔文森林","基塔·火风","狗头人地卜师","发光的残渣","阿祖拉之塔","蜡像"},ang={["class:Mage"]="虽然学术派法师经常嘲笑这些地底害虫，但基塔·火风提醒修行者，即使是原始生物也能揭示关于操纵原始魔法流的意想不到的真理。",["faction:Alliance"]="在艾尔文森林的阿祖拉之塔中学习，为联盟冒险者提供了洞察学术巫术以及困扰他们领地的、令人惊讶的魔法害虫的机会。"},sec={{t="理论与实践",b="学术严谨性是奥术研究的重要支柱，但真正的精通需要扎根于实践应用。在阿祖拉之塔，基塔·火风向附魔学徒发起挑战，要求他们放眼于那些被翻烂的藏书之外，在魔法自然出现的地方去审视它。即使是在艾尔文森林地底挖掘的未受教育的狗头人，也能将戏法灌注进日常的护身符中，这表明魔法直觉往往会挑战正规的学校教育。"},{t="原始戏法",b="狗头人地卜师会塑造灌注了简单的民间附魔的粗糙蜡像。通过获取这些蜡像并利用分解术小心地解开束缚的魔法，观察入微的学生可以提取出发光的残渣。解构这些粗糙的护身符证明了，理解附魔的基本脉络需要观察原始魔法在实地是如何运作的，而不仅仅是在布满灰尘的魔典中阅读相关内容。"}},faq={{q="谁提供了 附魔课程 这个任务？",a="艾尔文森林阿祖拉之塔的附魔师基塔·火风提供了这个课程，旨在帮助冒险者平衡学术魔法理论与动手实践。",al={"谁提供附魔课程","附魔课程任务给予者","基塔·火风任务"}},{q="阿祖拉之塔位于哪里？",a="阿祖拉之塔矗立在艾尔文森林的东部，在人类王国的农田与森林之中，它是魔法研究和巫术的一座堡垒。",al={"阿祖拉之塔在哪里","阿祖拉之塔位置"}},{q="狗头人是如何知道如何使用魔法的？",a="尽管没有受过正规教育或学术传统，但狗头人——特别是地卜师——拥有一种将基础戏法和附魔结合进他们粗糙蜡像中的本能诀窍。",al={"狗头人会魔法吗","狗头人地卜师魔法","狗头人有附魔吗"}},{q="蜡像有什么用途？",a="粗糙的蜡像是狗头人地卜师制作的原始物品。虽然并不精巧，但它们内部束缚着魔法能量，可以通过分解术来解开并进行研究。",al={"什么是蜡像","粗糙的蜡像","狗头人蜡像魔法"}},{q="什么是发光的残渣？",a="发光的残渣是在解构和分解狗头人地卜师携带的粗糙蜡像后获得的残留精华。它是他们天生戏法的具体证明。",al={"什么是发光的残渣","如何获得发光的残渣"}},{q="基塔·火风的课程的主要收获是什么？",a="基塔·火风教导说，理论知识和实践实验是同一枚硬币不可分割的两个面，敦促学生在魔法出现的地方去研究实践魔法。",al={"任务的课程","基塔·火风教什么"}}},fp="20,222,19.335.0,18.371.0,41.176.0,36.148.0,37.167.0,35.173.0,25.176.0,53.161.0"}
P.entries["quest:91758"] = {n="Follow That Kobold!",s="“Follow That Kobold!”是北郡山谷的一项联盟任务，讲述了当地矿井中发生的一起离奇盗窃案。一只狗头人背着一袋帕克斯顿修士的书籍逃走了，这促使修道院招募了矮人猎人训练师托德林·刃星来协助追踪这名窃贼。",h="“Follow That Kobold!”是北郡山谷的一项联盟任务，讲述了当地矿井中发生的一起离奇盗窃案。一只狗头人背着一袋帕克斯顿修士的书籍逃走了，这促使修道院招募了矮人猎人训练师托德林·刃星来协助追踪这名窃贼。",kw={"帕克斯顿修士","跟上那个狗头人","猎人训练师","铁炉堡","凯尔西","狗头人","北郡","托德林·刃星"},ang={["class:Hunter"]="这项任务介绍了托德林·刃星，一位刚从铁炉堡赶来协助北郡修道院的资深猎人训练师。",["faction:Alliance"]="暴风城的圣洁修道院与铁炉堡登山者之间的合作，突显了联盟相互支持的力量。",["race:Dwarf"]="托德林·刃星直接从铁炉堡带来了传统的矮人追踪专长，以帮助北郡的人类。"},sec={{t="北郡的书籍窃贼",b="正当北郡修道院的工人和牧师们以为矿井里的害虫问题已经得到控制时，凯尔西带来了一个不寻常的报告：有人发现一只落单的狗头人拖着一袋沉重的书籍逃离了隧道。这些被盗的书籍属于帕克斯顿修士，他急需将其找回并归还给修道院的藏书馆。"},{t="召唤登山者",b="要在北郡的树林地带追踪一只敏捷的地下食腐动物需要专门的技能。为了找到窃贼，冒险者们被指引去修道院后的马厩寻找托德林·刃星，他是一位刚从铁炉堡赶来的矮人猎人训练师，拥有发现踪迹所需的荒野知识。"}},faq={{q="“跟上那个狗头人!”是关于什么的？",a="“跟上那个狗头人!”是北郡山谷的一项任务，任务目标是追捕一只从当地矿井逃走的流氓狗头人，它背着一袋帕克斯顿修士被盗的沉重书籍。",al={"什么是 跟上那个狗头人","任务 跟上那个狗头人"}},{q="托德林·刃星是谁？",a="托德林·刃星是一位刚从铁炉堡赶来的矮人猎人训练师。他驻扎在北郡修道院后的马厩附近，并提供他的追踪专长来帮助找回被盗的书籍。",al={"托德林·刃星是谁","托德林在哪里","北郡猎人训练师"}},{q="狗头人偷了什么？",a="根据凯尔西的报告，一只狗头人拖着一大袋书溜出了北郡矿井。修道院需要代表帕克斯顿修士找回这些书，尽管狗头人为什么要觊觎人类的书籍仍是个谜。",al={"为什么狗头人要偷书","狗头人拿走了什么","一袋书"}},{q="是谁报告了这起盗窃案？",a="凯尔西·法戈是新来的矿工学徒，就在北郡矿井外工作。她最先注意到那只不寻常的狗头人背着一袋塞满书的袋子离开了隧道。",al={"凯尔西是谁","北郡凯尔西"}},{q="帕克斯顿修士是谁？",a="帕克斯顿修士是一位居住在北郡修道院的牧师。被盗的图书馆资料属于他或与他的神圣职责有关，因此促使他寻求一位经验丰富的追踪者来找回它们。",al={"帕克斯顿修士是谁","帕克斯顿的书"}},{q="如何追踪那个偷东西的狗头人？",a="冒险者们不会盲目地冲进树林，而是被派去咨询修道院后的托德林·刃星，他会准备好追踪技巧来跟随窃贼的足迹。",al={"我该如何追踪狗头人","追踪窃贼"}}},fp="19,182,28.245.0,26.342.0,34.121.0,26.177.0,26.176.0,23.177.0,22.175.0,37.166.0"}
P.entries["quest:91772"] = {n="Shhh! We're Hunting Kobolds",s="“嘘！我们在猎杀狗头人”是一个引导冒险者走出北郡山谷，在艾尔文森林追踪游荡狗头人的任务。玩家需要使用追踪工具，发现踪迹指向受灾严重的法戈第矿洞，并将这一发现报告给闪金镇的治安官杜汉。",h="“嘘！我们在猎杀狗头人”是一个引导冒险者走出北郡山谷，在艾尔文森林追踪游荡狗头人的任务。玩家需要使用追踪工具，发现踪迹指向受灾严重的法戈第矿洞，并将这一发现报告给闪金镇的治安官杜汉。",kw={"艾尔文森林","法戈第矿洞","闪金镇","狗头人追踪工具","狗头人","治安官杜汉","治安官玛克布莱德","北郡","嘘！我们在猎杀狗头人"},ang={["class:Hunter"]="擅长追踪猎物的猎人会懂得在森林中利用追踪工具追踪害虫踪迹的实用之处。",["faction:Alliance"]="从北郡出发的联盟冒险者通过向闪金镇的卫戍部队通报集结的威胁，有助于保障艾尔文森林的补给线和定居点安全。"},sec={{t="追踪害虫",b="随着北郡山谷的狗头人威胁日益加剧，种种迹象表明这些害虫正在修道院外集结。侦察兵们被派去装备追踪工具，循着生物的踪迹，查明它们在何处聚集。这次侦察行动成为了解决北郡当地麻烦与保卫整个艾尔文森林之间的关键桥梁。"},{t="法戈第的关联",b="踪迹从北郡向西南延伸，穿过艾尔文森林直指法戈第矿洞。驻守在闪金镇的治安官杜汉对这份报告并不感到意外，他指出法戈第矿洞早已被大量的狗头人占据。这一发现为夺回这座重要矿山的军事行动奠定了基础。"}},faq={{q="这项任务的目标是什么？",a="该任务要求冒险者使用特制的追踪工具，跟随北郡山谷外的狗头人。目标是找出这些生物的聚集地，并将情报传达给在闪金镇的暴风城当局。",al={"任务目标","这是什么任务","为什么要猎杀狗头人"}},{q="谁在担心狗头人的动向？",a="北郡山谷的指挥官治安官玛克布莱德对狗头人的动向感到担忧。一位当地向导提供了追踪工具，以便循着它们的踪迹走出山谷，进入更广阔的艾尔文森林。",al={"谁提供了追踪工具","谁在担心狗头人"}},{q="狗头人的踪迹通往哪里？",a="踪迹离开北郡，直接指向艾尔文森林中部的法戈第矿洞，该地点目前已被狗头人严重侵扰。",al={"踪迹去往何处","狗头人的目的地","狗头人正前往哪里"}},{q="治安官杜汉是谁？",a="治安官杜汉是驻扎在闪金镇的暴风城卫兵指挥官。他协调艾尔文森林各地的防御工作，并负责接收有关入侵威胁的报告。",al={"谁是治安官杜汉","杜汉在哪里","向杜汉报告"}},{q="为什么狗头人要前往法戈第矿洞？",a="法戈第矿洞是艾尔文森林中一个现成的采矿点，早已被狗头人占据。更多害虫向矿洞移动，预示着当地工人和附近定居点的麻烦将进一步加剧。",al={"为什么是法戈第矿洞","法戈第矿洞的狗头人"}},{q="到达闪金镇后会发生什么？",a="收到你的报告后，治安官杜汉确认法戈第矿洞已被狗头人占据。他对此并不感到惊讶，反而准备招募有能力的战士来直接处理矿洞内的侵扰问题。",al={"报告后会发生什么","杜汉的反应"}}},fp="27,163,19.213.0,24.257.1,30.171.0,44.202.0,32.119.0,22.168.0,46.138.0,38.166.0"}
P.entries["quest:91775"] = {n="Book Return",s="Book Return是艾尔文森林的一个任务，指引冒险者们从法戈第矿洞那危险的深处寻回布罗瑟·帕克森丢失的读物。在丢失的书中，最重要的是《元素之乐》，这是一本入门指南，如果不从狗头人手中夺回，它可能会让矿洞里的这些生物获得危险的召唤能力。",h="Book...",kw={"归还书籍","布罗瑟·帕克森","艾尔文森林","法戈第矿洞","元素之乐","闪金镇","狗头人","治安官杜汉"},ang={["class:Mage"]="如果让《元素之乐》这类奥术入门书落入狗头人等简单的地下生物手中，后果将不堪设想。",["faction:Alliance"]="北郡修道院的图书馆与闪金镇的驻军携手合作，以保护民用文献和危险的魔法书免受艾尔文森林害虫的破坏。"},sec={{t="黑暗中的遗失书页",b="在调查法戈第矿洞中日益严重的狗头人威胁时，治安官杜汉指派冒险者们去寻回属于北郡修道院布罗瑟·帕克森的失窃书籍。在阴暗的地下隧道中散落着的书本里，有一本名为《元素之乐》的入门书显得尤为危险。帕克森担心书中的内容过于通俗易懂，甚至连矿洞里那些粗鲁的狗头人也能破解其中的奥秘，并在深处召唤出元素生物。"},{t="危险的知识",b="法戈第矿洞曾是暴风城王国的黄金矿产，但最近的动荡导致害虫侵占了其下层。由于艾尔文森林的防御力量捉襟见肘，找回的文本必须妥善存放在保护性的书包里，以防它们在潮湿、险恶的洞穴中受损。找回帕克森丢失的藏书可以确保世俗记录得以保存，并防止危险的奥术知识落入原始生物之手。"}},faq={{q="什么是归还书籍任务？",a="归还书籍是治安官杜汉在闪金镇发布的任务，旨在寻回属于布罗瑟·帕克森并丢失在法戈第矿洞中的书籍。除了散落的一般读物外，帕克森尤其急于找回一本名为《元素之乐》的魔法入门书。",al={"什么是归还书籍","归还书籍任务","谁发布归还书籍任务"}},{q="为什么布罗瑟·帕克森的书在法戈第矿洞里？",a="偷走布罗瑟·帕克森书本的狗头人从北郡一直逃到了法戈第矿洞，最近这里已经被狗头人占领。帕克森迫切希望在书本损毁或被滥用之前将其找回。",al={"帕克森的书为什么在矿洞里","书籍是如何进入法戈第矿洞的","为什么法戈第矿洞里有书"}},{q="什么是《元素之乐》这本书？",a="《元素之乐》是一本布罗瑟·帕克森急于寻回的奥术召唤入门书。他担心其中的指令过于基础和简单，以至于连愚笨的狗头人都有可能误打误撞地学会，并在矿洞深处召唤出元素仆从。",al={"元素之乐","什么是元素之乐","帕克森的元素书籍"}},{q="布罗瑟·帕克森是谁？",a="布罗瑟·帕克森是北郡修道院的一名牧师，以潜心钻研学术、记录和文献而闻名。他对丢失读物的担忧不仅限于对私人财产的损失，还因为其中一些文本包含了强大的基础魔法知识。",al={"谁是布罗瑟·帕克森","帕克森背景故事","图书管理员帕克森"}},{q="为什么治安官杜汉会参与书籍的回收工作？",a="治安官杜汉负责在闪金镇协调艾尔文森林的防御工作。在派遣冒险者前往调查威胁法戈第矿洞的狗头人入侵时，他顺便协助布罗瑟·帕克森寻回其丢失的卷宗，以防狗头人构成更大的魔法威胁。",al={"为什么杜汉关心书籍","治安官杜汉书籍"}},{q="狗头人真的能召唤元素吗？",a="狗头人通常是粗鲁的穴居生物，以擅长地卜术和操纵火焰而闻名，但布罗瑟·帕克森担心一本简单的教学指南可能会赋予它们召唤元素力量的手段，这将使本已危险的入侵局面变得更加恶劣。",al={"狗头人会使用魔法吗","狗头人能召唤元素吗"}}},fp="11,179,22.274.0,18.332.0,30.188.0,53.194.0,39.213.0,22.141.0,51.230.0,42.149.0"}
P.entries["quest:91777"] = {n="珍本",s="珍本是北郡山谷的一项联盟任务，旨在为帕克斯顿修士找回两本被偷走的魔法入门书。狗头人将这些失踪的书籍拖进了玉石矿洞，在那里他们似乎正在钻研基础魔法和召唤仪式。",h="珍本是北郡山谷的一项联盟任务，旨在为帕克斯顿修士找回两本被偷走的魔法入门书。狗头人将这些失踪的书籍拖进了玉石矿洞，在那里他们似乎正在钻研基础魔法和召唤仪式。",kw={"奥术解析","帕克斯顿修士","地卜术","玉石矿洞","狗头人","北郡修道院","北郡山谷","珍稀书籍"},ang={["class:Mage"]="像《好奇小巫师的地卜术》和《奥术解析》这样的入门读物在地下生活的狗头人看来是非常奇特的读物，尽管初级奥术师们会认出其中正在研习的基本原理。",["faction:Alliance"]="从玉石矿洞中追回北郡修道院被盗的知识财产，有助于保护山谷的文化遗产，同时也为当地民兵提供了援助。"},sec={{t="修道院的失窃",b="北郡修道院的帕克斯顿修士正面临着图书馆的危机：几卷书籍被盘踞在山谷里的害虫偷走了。他的目录里只剩下两本书下落不明：《好奇小巫师的地卜术》和《奥术解析：魔法的通俗解释》。这些教学入门书被占据矿洞的狗头人拖进了玉石矿洞深处。"},{t="玉石矿洞里的奥术狗头人",b="寻回这些简单的课本有着意想不到的紧迫性。虽然狗头人通常以小偷小摸和挥舞矿镐而闻名，但玉石矿洞里的狗头人已经开始摆弄这些手册里的知识了。已经有人目击到一名狗头人学徒试图召唤元素生物，这引发了人们的担忧：如果让更有经验的地卜师或大师掌握了这些奥术文献，他们会召唤出什么东西来？"}},faq={{q="任务珍稀书籍是什么？",a="珍稀书籍是北郡的一项任务，探险者需要找回帕克斯顿修士目录中最后两本被偷走的书，这些书现在落入了深藏在玉石矿洞中的狗头人手中。",al={"珍稀书籍任务","珍稀书籍是什么","这个任务是什么"}},{q="帕克斯顿修士是谁？",a="帕克斯顿修士是居住在北郡修道院内的一名牧师，负责照看修道院的书籍和文献收藏。他依靠探险者来找回被入侵的狗头人偷走的图书馆藏书。",al={"帕克斯顿是谁","帕克斯顿修士背景","修道院图书管理员"}},{q="需要找回哪些书？",a="两本失踪的书分别是《好奇小巫师的地卜术》和《奥术解析：魔法的通俗解释》。它们都是关于奥术和魔法理论的入门读物。",al={"失踪的书籍有哪些","被盗书籍标题","丢失的图书馆书籍"}},{q="失踪的书籍在哪里？",a="被偷的书位于玉石矿洞，这是一个位于北郡山谷的金矿，目前已被狗头人挖掘工和地卜师占领。",al={"书在哪里","书籍位置","去哪里找书"}},{q="为什么狗头人要拿走魔法书籍？",a="玉石矿洞里的狗头人似乎正在利用这些被偷的魔法文献进行地卜术和施法实验。据报道，甚至有一名学徒利用这些偷来的知识试图召唤元素生物。",al={"为什么狗头人有书","狗头人识字吗","狗头人巫师"}},{q="为什么帕克斯顿修士奖励原本为民兵准备的武器？",a="帕克斯顿修士用原本为当地北郡民兵储备的备用武器来奖励帮忙的人，他认为这些武器在积极应对山谷威胁的探险者手中能发挥更大的作用。",al={"帕克斯顿奖励武器","为什么是民兵武器","修道院武器"}}},fp="10,130,22.288.0,28.195.1,29.128.0,22.158.0,33.151.0,36.114.0,40.139.0,64.161.0"}
P.entries["quest:918"] = {n="林精的种子",s="“木之种”是泰达希尔奥拉密斯湖的植物学家德纳兰发布的一项早期任务。由于当地自然元素表现出日益增长的敌意，德纳兰深感忧虑，他试图收集它们的种子，以测试富含养分的土壤能否培育出更温和、更和谐的植物。这项任务展现了暗夜精灵草药师为理解困扰世界之树的种种细微病症所付出的安静努力。",h="“木之种”是泰达希尔奥拉密斯湖的植物学家德纳兰发布的一项早期任务。由于当地自然元素表现出日益增长的敌意，德纳兰深感忧虑，他试图收集它们的种子，以测试富含养分的土壤能否培育出更温和、更和谐的植物。这项任务展现了暗夜精灵草药...",kw={"植物学","德纳兰","元素","奥拉密斯湖","种子","泰达希尔","木之怪"},ang={["class:Druid"]="德鲁伊对自然之灵有着深厚的亲和力。协助德纳兰的研究有助于在不完全依赖暴力屠杀的情况下维持元素的平衡。",["profession:Herbalism"]="与泰达希尔植物群有共鸣的采集者会赞赏德纳兰的植物学实验，这些实验探索了植物种子与肥沃土壤之间微妙的关系。",["race:NightElf"]="对于卡多雷来说，木之怪是泰达希尔健康状况的直接晴雨表。看着这些温和的灵魂变得野蛮，是一个令人不寒而栗的信号，说明他们的新家园病了。"},sec={{t="躁动的自然",b="木之怪是泰达希尔树枝间原生的自然元素，与它们周围植物的健康和活力息息相关。它们原本是森林平衡的和平映射，但最近莫名其妙的敌意让当地的暗夜精灵感到不安。植物学家德纳兰并不想简单地屠杀它们，而是希望能弄清它们焦躁不安的根源。"},{t="新生的种子",b="德纳兰怀疑问题的根源深埋在地下，因此他计划在经过仔细处理的肥沃土壤中培育新鲜的木之怪。通过收集奥拉密斯湖附近游荡的木之怪身上的种子，他希望能培育出更温和的元素后代，并探究这种土地的腐化是否能从根源上得到解决。"}},faq={{q="什么是木之怪？",a="木之怪是泰达希尔上发现的小型植物状自然元素。它们反映了世界之树动植物群的自然秩序和生命周期。",al={"木之怪背景故事","什么是木之怪","泰达希尔自然元素"}},{q="为什么木之怪会变得具有攻击性？",a="德纳兰怀疑泰达希尔的土壤存在某种潜在的缺陷或污染。作为世界之树生态的元素体现，木之怪反映了正在岛上蔓延的腐化。",al={"为什么木之怪会生气","木之怪敌意","愤怒的木之怪"}},{q="德纳兰是谁？",a="德纳兰是一位暗夜精灵博物学家和植物学家，他在奥拉密斯湖东岸照料着一个小花园，专门研究泰达希尔奇异的植物群和土壤。",al={"德纳兰背景故事","谁是德纳兰","奥拉密斯湖植物学家"}},{q="在哪里可以收集到木之怪的种子？",a="木之怪在泰达希尔中部的奥拉密斯湖周边的林荫灌木丛、湖岸和林间空地中游荡。",al={"哪里寻找木之怪种子","木之怪分布","奥拉密斯湖种子"}},{q="德纳兰打算如何处理这些种子？",a="德纳兰打算在他开发的特殊净化土壤混合物中培育这些种子，希望能培育出摆脱了森林躁动的温顺木之怪。",al={"种子会怎样","德纳兰计划","种植木之怪种子"}},{q="这与泰达希尔面临的更广泛的危机有什么联系？",a="这些基础自然之灵的暴躁行为，是泰达希尔受到非自然腐化影响的最早迹象之一，这也引导研究者们前往达纳苏斯进行更深入的调查。",al={"泰达希尔腐化","为什么泰达希尔生病了","树木腐化"}}},fp="16,302,15.337.0,21.289.0,21.154.0,43.168.0,15.162.0,39.107.0,44.159.0,53.174.0"}
P.entries["quest:91858"] = {n="Diplomatic Incident",s="两位大地之环要员在前往塔伦米尔的途中，于银松森林失踪。Danitha 派你前往瑟伯切尔，向 Trevan Rol 了解详情，并帮助巩固部落的合法地位。",h="两位大地之环要员在前往塔伦米尔的途中，于银松森林失踪。Danitha 派你前往瑟伯切尔，向 Trevan Rol 了解详情，并帮助巩固部落的合法地位。",kw={"danitha","要员","外交事件","大地之环","部落","失踪的旅人","瑟伯切尔","银松森林","塔伦米尔","trevan rol"},sec={{t="失踪的旅人",b="Danitha 派你前往银松森林的瑟伯切尔，寻找 Trevan Rol。两位大地之环要员在前往塔伦米尔的途中失踪，除了外交事件的传闻外，几乎没有其他消息。找回他们或许能帮助部落获得合法地位。Trevan 说，你卷入了一个大麻烦。"}},faq={{q="谁在银松森林失踪了？",a="两位大地之环要员在前往塔伦米尔的途中，于银松森林失踪。",al={"失踪的要员","大地之环旅人","谁失踪了"}},{q="我该去哪里打听消息？",a="Danitha 派你前往银松森林的瑟伯切尔，与 Trevan Rol 交谈。",al={"trevan rol 在哪里","寻找 trevan","瑟伯切尔"}},{q="Danitha 为什么想找到这些旅人？",a="找回失踪的大地之环要员或许能帮助部落获得合法地位。",al={"为什么要找到他们","部落的合法地位","外交事件"}},{q="这些要员出了什么事？",a="他们在前往塔伦米尔的途中，于银松森林失踪。目前下落不明。",al={"银松森林发生了什么","他们为什么失踪","要员的下落"}}},fp="19,204,17.306.0,31.103.0,30.81.0,42.85.0,33.105.0"}
P.entries["quest:91859"] = {n="A Curious Pair",s="当Trevan Rol注意到有一对奇怪的组合穿过银松森林的瑟伯切尔时，“A Curious Pair”任务就开始了。这两人打着大地之环的旗号，其中一名牛头人与一名高等精灵同行——这种联盟在部落领地极为罕见，足以引起立即的怀疑。",h="当Trevan Rol注意到有一对奇怪的组合穿过银松森林的瑟伯切尔时，“A Curious...",kw={"奇怪的一对","死亡卫士巴尔德伦","大地之环","高等精灵","瑟伯切尔","银松森林","牛头人","特雷文·罗尔"},ang={["class:Shaman"]="即便对于经验丰富的萨满来说，提及大地之环成员与精灵同行也是不寻常的，因为他们知道大地之环的传统中很少涉及高等精灵。",["race:Tauren"]="牛头人冒险者看到自己的族人与一名精灵陌生人穿过洛丹伦，可能会感到矛盾，并引来被遗忘者哨兵锐利的目光。",["race:Undead"]="对于守卫瑟伯切尔的被遗忘者来说，任何潜入银松森林的局外人都值得密切关注，特别是考虑到洛丹伦分裂的政治气候。"},sec={{t="瑟伯切尔的注视",b="瑟伯切尔是一个阴森的中转站，陌生人在这里都会受到严密的盘查，尤其是那些声称有外交事务的人。当两名自称属于大地之环的代表沿着道路经过时，当地侦察兵Trevan Rol发现了他们。虽然一名身披萨满教派外袍的牛头人并不让人感到惊讶，但他的兜帽同伴却让这名被遗忘者觉得极其古怪：那无疑是一名高等精灵。"},{t="古怪的伙伴关系",b="一名高等精灵与部落萨满教派的一员公开同行，这自然引起了被遗忘者哨兵的质疑。大地之环通常只关心元素平衡，很少在洛丹伦派遣高等精灵，更不用说作为牛头人使者的同伴了。为了查明这对不同寻常的组合去了哪里，以及他们在森林里有什么企图，旅行者们被指引去咨询镇边的死亡卫士Baldren。"}},faq={{q="这个任务中提到的两名旅行者是谁？",a="根据特雷文·罗尔的说法，这些旅行者自称是大地之环的显贵。其中一个是该萨满组织的典型牛头人，但他的同伴被确认为一名披着斗篷的高等精灵。",al={"奇怪的组合是谁","谁经过了瑟伯切尔","旅行者是谁"}},{q="为什么高等精灵与牛头人同行会如此罕见？",a="高等精灵与联盟和奥术魔法有着历史渊源，而牛头人是部落的忠诚成员，且是萨满教义的忠实实践者。看到这两个种族的成员以大地之环的名义一同穿过部落控制的银松森林，是非常罕见且令人怀疑的一幕。",al={"为什么高等精灵与牛头人同行很奇怪","牛头人与高等精灵背景"}},{q="谁开启了“奇怪的二人组”任务？",a="该任务由位于银松森林的前哨站瑟伯切尔的特雷文·罗尔发布。",al={"任务发布者","好奇的一对任务接取地点"}},{q="我在哪里可以找到死亡卫士巴尔德伦？",a="死亡卫士巴尔德伦在银松森林瑟伯切尔的入口附近站岗，监视着路上往来的旅行者。",al={"巴尔德伦位置","巴尔德伦在哪里"}},{q="什么是大地之环？",a="大地之环是一个古老的萨满组织，致力于维护元素平衡并治愈世界各地的灵性失调。虽然成员主要由牛头人和兽人等萨满组成，但他们的外交官偶尔也会前往遥远的土地。",al={"大地之环背景","什么是大地之环"}},{q="这名高等精灵是被遗忘者的敌人吗？",a="目前还不清楚。特雷文·罗尔指出，这名精灵披着斗篷，以外交为借口与一名牛头人同行，这让被遗忘者对他们的目的产生了怀疑，而不是直接发动攻击。",al={"他们是敌对的吗","精灵是敌人吗"}}},fp="14,190,21.424.0,22.381.0,50.137.0,53.239.0,36.79.0,35.123.0,25.269.0,41.200.0"}
P.entries["quest:91860"] = {n="A Grim Fate",s="巡逻兵在芬里斯岛上的所见，让人担忧一名精灵和一支大地之环旅行队的安危。你受托调查这支队伍的命运。",h="巡逻兵在芬里斯岛上的所见，让人担忧一名精灵和一支大地之环旅行队的安危。你受托调查这支队伍的命运。",kw={"a grim fate","大地之环","精灵","芬里斯岛","豺狼人","火葬柴堆","牛头人","旅行队"},ang={["class:Paladin"]="巡逻兵以你身为圣骑士对誓言的重视相劝，尽管他怀疑这次搜寻是否值得冒险。"},sec={{t="岸边的柴堆",b="一名巡逻兵看见豺狼人将一具庞大的尸体放在芬里斯岛岸边的火葬柴堆上。他没有看见精灵，也没有看见较小的尸体，因此担心那支旅行队的安危。你受托搜寻这座岛，查明他们的遭遇。"},{t="尸体",b="芬里斯岛上的那具尸体属于一名牛头人，已经被啃咬得残缺不全。四处都不见那名女精灵的踪影。她可能还在附近要塞的深处，因此命运仍未可知。"}},faq={{q="巡逻兵看见了什么？",a="一名巡逻兵看见豺狼人正将一具庞大的尸体放在芬里斯岛岸边的火葬柴堆上。",al={"巡逻所见","豺狼人与火葬柴堆","岸边有什么"}},{q="那支旅行队是什么人？",a="据描述，那是一支大地之环的旅行队。",al={"大地之环队伍","谁在旅行","旅行队伍"}},{q="为什么派我去芬里斯岛？",a="你受托调查芬里斯岛，查明大地之环旅行队的命运。",al={"为什么去芬里斯岛","要寻找什么","a grim fate任务"}},{q="有人在岸边看见那名精灵吗？",a="巡逻兵没有在火葬柴堆旁的人中看见精灵。",al={"精灵在哪里","fenris上的精灵","他们看见她了吗"}}},fp="11,144,19.212.0,8.181.1,27.79.0,27.58.0,35.96.0,30.49.0"}
P.entries["quest:91861"] = {n="Into Fenris Keep",s="只发现了一具尸体，让人仍抱有希望，相信大地之环队伍中失踪的成员可能还活着。你受托前往芬里斯城堡，寻找这名俘虏。",h="只发现了一具尸体，让人仍抱有希望，相信大地之环队伍中失踪的成员可能还活着。你受托前往芬里斯城堡，寻找这名俘虏。",kw={"俘虏","大地之环","芬里斯城堡","哈德瑞克","高等精灵","进入芬里斯城堡","失踪的成员","trevan"},sec={{t="搜寻芬里斯城堡",b="大地之环队伍中的一名成员失踪了，你受托前往芬里斯城堡寻找。Trevan和哈德瑞克提到，附近的堡垒里有一名高等精灵。由于只发现了一具尸体，失踪的队员仍有生还的希望。"},{t="求援",b="在芬里斯城堡内，你发现了失踪的高等精灵，正在请求一名被遗忘者帮助自己逃脱。留给这名俘虏的时间已经不多了。"}},faq={{q="我要在芬里斯城堡寻找谁？",a="你要寻找大地之环队伍中一名失踪的成员，据Trevan和哈德瑞克描述，那是一名高等精灵。",al={"失踪者 fenris","谁失踪了","大地之环队伍"}},{q="为什么失踪者还有生还的希望？",a="只发现了一具尸体，因此人们仍抱有希望，相信失踪的高等精灵还在芬里斯城堡内。",al={"只有一具尸体","精灵还活着吗","芬里斯城堡尸体"}},{q="是谁让我搜寻芬里斯城堡？",a="你受托调查芬里斯城堡，设法找到大地之环队伍中失踪的成员。",al={"谁派我来的","谁要我去搜寻","芬里斯城堡的委托"}},{q="俘虏提出了什么请求？",a="俘虏请求一名被遗忘者帮助自己脱身，说时间已经不多了。",al={"救我出去","帮助俘虏","精灵想要什么"}}},fp="16,144,23.249.0,15.118.1,36.111.0,46.92.0,34.105.0,30.71.1"}
P.entries["quest:91899"] = {n="A Sealed Crate",s="A Sealed Crate代表了从地区道路和强盗藏身处找回的被劫货物。随着盗贼日益频繁地切断补给线，贸易商会雇佣四处游历的冒险者来找回丢失的货物，以恢复道路的稳定。",h="A Sealed Crate代表了从地区道路和强盗藏身处找回的被劫货物。随着盗贼日益频繁地切断补给线，贸易商会雇佣四处游历的冒险者来找回丢失的货物，以恢复道路的稳定。",kw={"强盗","商队","货物","交付","密封的箱子","补给品","盗贼","贸易路线"},sec={{t="濒危的贸易路线",b="近期公路犯罪激增，有组织的强盗和不法之徒开始大肆劫掠常规贸易路线。商队马车、驮畜队伍和单独的信使遭到伏击，导致货物散落在荒野道路上，或是被拖进了法外之徒的营地。这种猖獗的劫掠行为威胁着连接各个定居点的关键补给线。"},{t="找回丢失的货物",b="为了保持补给流通并找回被窃商品，商人和货物经办人依靠独立的冒险者来回收散落的货物。任何从强盗手中解救出或在灌木丛中发现的密封的箱子都可以上交给贸易经办人，以确保物资安全，遏制非法的黑市交易，并恢复区域商业的安全。"}},faq={{q="什么是密封的箱子？",a="密封的箱子代表了从荒野路线中找回的被劫商人和丢失的货物。上交它们可以保住本会落入盗贼之手的货物，并有助于重建安全的商业环境。",al={"密封的箱子任务","什么是密封的箱子","箱子上交"}},{q="为什么贸易路线会被强盗劫掠？",a="投机取巧的强盗和法外之徒突然增多，使得常规道路和贸易路线的旅行变得危险。商队和信使成为被针对和劫掠的目标，导致货物散落在荒野各处。",al={"为什么强盗要偷箱子","贸易路线强盗","谁在袭击商队"}},{q="谁在收集这些找回的箱子？",a="贸易经办人和军需官负责接收找回的箱子，以此清点丢失的商人财产，并建立起避开游荡盗贼的储备库，同时向回收这些物资的拾荒者和冒险者提供报酬。",al={"谁来接收密封的箱子","密封的箱子去向","箱子交付"}},{q="可以上交多个密封的箱子吗？",a="可以。贸易协调员鼓励旅行者继续上交在道路和荒野中发现的任何额外箱子，因为强盗活动仍在持续干扰正常的物资交付。",al={"密封的箱子可以重复做吗","更多的箱子","还有更多的箱子吗"}},{q="密封的箱子里有什么？",a="箱子里装有在运输途中被拦截的回收贸易补给品和商业货物。虽然递送它们的信使没有打开过箱子，但它们会被送回贸易储备库，以减轻因公路劫匪造成的损失。",al={"密封的箱子里有什么","密封的箱子内部","箱子里装的是什么"}},{q="这些找回的箱子来自哪里？",a="这些箱子通常是在危险的贸易通路上被遗弃的，发现于强盗营地附近，或是从拦截了补给物资的法外之徒手中劫回的。",al={"哪里可以找到密封的箱子","如何获得密封的箱子","强盗箱子"}}},fp="14,157,23.280.0,21.309.0,23.163.0,45.155.0,36.196.0,40.150.0,30.193.0,42.127.0"}
P.entries["quest:919"] = {n="林精的新芽",s="《林精的新芽》是由位于泰达希尔中心奥拉密斯湖附近的自然观察者德纳兰发布的一个任务。德纳兰对湖岸周围林精的新芽突然且不自然地大量繁殖感到担忧，他请求旅行者在它们长成充满敌意的林精之前将其拔除。这项任务突显了某种蔓延的腐蚀正在干扰这棵新生的世界之树的平衡的早期迹象。",h="《林精的新芽》是由位于泰达希尔中心奥拉密斯湖附近的自然观察者德纳兰发布的一个任务。德纳兰对湖岸周围林精的新芽突然且不自然地大量繁殖感到担忧，他请求旅行者在它们长成充满敌意的林精之前将其拔除。这项任务突显了某种蔓延的腐蚀正...",kw={"腐蚀","德纳兰","奥拉密斯湖","污染","泰达希尔","林精的新芽","林精","除草"},ang={["class:Druid"]="德鲁伊肩负着维护自然微妙平衡的责任；修剪受枯萎影响的新芽是保护更广泛生态系统的一项悲哀但必要的职责。",["profession:Herbalism"]="草药师对于健康的植被应该如何生长有着敏锐的洞察力，能瞬间识别出这些新芽是病态且不自然扭曲的。",["race:NightElf"]="对于卡多雷来说，泰达希尔本应是一处崭新的避难所，因此在奥拉密斯湖这类圣水周围出现的腐化生长物是一个令人深感不安的预兆。"},sec={{t="除草奥拉密斯湖",b="在奥拉密斯湖宁静的岸边，一种被称为林精的奇异植物状生物开始以惊人的速度繁殖。这些出现的林精的新芽并没有与林地和谐共存，反而从扎根的那一刻起就表现出被腐蚀的迹象。住在湖边的自然研究者德纳兰认为这些新芽已无法治愈。如果不加以控制，它们会迅速长成充满攻击性的树皮生物，威胁当地野生动物和粗心的旅行者。收集并消灭这些新芽是保持林地洁净的一道即时防线。"},{t="更深层污染的迹象",b="虽然拔除新芽有助于控制当地的危害，但德纳兰恐惧地注意到新芽出现的速度太快了。它们不受控制的繁殖在泰达希尔是一种不自然的现象。这些受污染的新芽并非孤立的侵扰，而是威胁着世界之树本身的根基和土壤的某种更深层病态的征兆——德纳兰和达纳苏斯的德鲁伊们正竞相解开这个谜团。"}},faq={{q="什么是林精的新芽？",a="林精的新芽是林精的初期幼体——泰达希尔枝干上原生的微型元素植物生物。不幸的是，在奥拉密斯湖沿岸发芽的新芽遭到了污染，并迅速成长为充满敌意和攻击性的生物。",al={"林精是什么","林精的新芽背景故事","什么是新芽"}},{q="德纳兰是谁？",a="德纳兰是一位草药师和自然看护者，居住在奥拉密斯湖岸边的一个安静营地里。他守护着枝干上的植物，并研究泰达希尔正在发生的生态变化和奇异的腐蚀现象。",al={"谁发布林精的新芽任务","德纳兰背景故事","奥拉密斯湖任务发布者"}},{q="为什么不能直接治愈或净化这些新芽？",a="德纳兰观察到，这些新芽浮出地表时就已经受到了不可挽回的污染。试图恢复它们是徒劳的，因此清除是防止它们长成危险隐患的唯一切实可行的方法。",al={"新芽可以被拯救吗","为什么要消灭林精","新芽是否无可救药"}},{q="在哪里可以找到这些新芽？",a="新芽扎根在泰达希尔中心奥拉密斯湖周围的泥泞湖岸、浅滩和茂密的河岸边。",al={"林精的新芽位置","在哪里寻找新芽","奥拉密斯湖新芽"}},{q="是什么导致林精如此疯狂地滋生？",a="充满敌意的林精不自然地激增，是由蔓延到泰达希尔土壤和水域中的腐蚀力量所驱动的。即使是幼小的植株在完全盛开之前也遭到了腐蚀，这指向了困扰着这棵年轻的世界之树的潜在枯萎病。",al={"为什么林精会发狂","什么污染了新芽","林精腐蚀"}},{q="清除这些新芽后会发生什么？",a="德纳兰继续调查湖泊疾病的本质，通过检查土壤、种子和水样本来追踪枯萎病的根源。",al={"林精的新芽后续任务","林精的新芽后续"}}},fp="18,148,21.277.0,23.192.0,28.160.0,15.152.0,53.166.0,28.104.0,54.188.0,42.104.0"}
P.entries["quest:91900"] = {n="A Sealed Crate",s="强盗和窃贼正在劫掠道路，遗失的货物散落在荒野各处。当地商人愿意付钱，请你带回一个密封的货箱。",h="强盗和窃贼正在劫掠道路，遗失的货物散落在荒野各处。当地商人愿意付钱，请你带回一个密封的货箱。",kw={"强盗","货物","补偿","递送","密封的箱子","装运","窃贼","贸易路线"},sec={{t="中断的贸易路线",b="如今，商队和信使在古老的商道上时常遭到伏击。许多人逃跑时丢下货车和货箱，货物便留在灌木丛中，直到有人发现。商人和货站管理员都指望旅人将这些货物带回来。"},{t="货物回收",b="将一个密封的货箱送到收货站，就能当场领到赏金。货运人员会分拣货物，再将其发往目的地，让商贸在强盗肆虐之下仍能继续运转。只要道路上的争夺不息，找回遗失的货物就始终是过路旅人一份稳定的差事。"}},faq={{q="密封的箱子里有什么？",a="箱子里装的是在贸易路线上被拦截或丢失的回收商品。商人和收货人会向信使和冒险者支付费用，让他们取回并原封不动地送回，而不是让这些货物落入不法之徒手中。",al={"箱子里有什么","箱子内容物","密封的箱子里是什么"}},{q="为什么人们要求递送密封的箱子？",a="近期强盗和窃贼的暴乱中断了活跃的贸易路线，导致货物散落或被盗。商人和当地组织者为任何愿意找回并归还这些失落货物的人提供赏金和补偿。",al={"为什么归还箱子","谁需要密封的箱子","箱子递送原因"}},{q="可以上交多个密封的箱子吗？",a="可以。由于商业路线上持续发生的强盗劫掠，废弃和被盗的箱子不断出现在受阻的道路上。信使们被鼓励将他们发现的任何额外箱子带回来，以获得进一步的补偿。",al={"我能找到更多箱子吗","去哪里获取箱子","更多密封的箱子"}},{q="是谁在拦截贸易路线？",a="当地的窃贼和强盗越来越频繁地将目标对准运输路线，伏击商队并拦截贸易往来。虽然该地区活跃着许多不同的团伙，但它们共同导致的结果就是货物被丢弃或在道路上被劫掠。",al={"谁偷了箱子","强盗暴乱贸易路线","谁在袭击货物"}},{q="你自己可以打开密封的箱子吗？",a="你是否可以自己打开箱子尚不明确。请将回收的箱子交给收货人，以领取递送报酬。",al={"我可以打开箱子吗","打开密封的箱子","为什么要保持箱子密封"}},{q="谁为回收这些货物支付报酬？",a="当地的货物经手人和仓库管理员会接收回收的货物并当场提供补偿，负责管理库存并指导进一步的回收工作。",al={"谁为箱子支付报酬","谁提供箱子奖励","箱子补偿"}}},fp="14,152,22.252.0,14.270.0,30.240.0,56.234.0,39.225.0,37.252.0,37.129.0,40.168.0"}
P.entries["quest:91901"] = {n="A Sealed Crate",s="商人请你送来密封的货箱，因为土匪和盗贼正在袭击商路。其他遗弃的货箱也可能需要同样处理。",h="商人请你送来密封的货箱，因为土匪和盗贼正在袭击商路。其他遗弃的货箱也可能需要同样处理。",kw={"土匪","货箱","货物","报酬","密封的箱子","盗贼","商路","商人"},sec={{t="在货堆旁",b="商人感谢你辛勤劳作，并请你把货物放在一堆货箱旁。报酬已经备好。最近土匪和盗贼频频袭击商路，因此其他遗弃在外的货箱也可能需要送到这里。"}},faq={{q="为什么货箱会被遗弃在外？",a="土匪和盗贼一直在劫掠商路，导致货箱遗落在外。",al={"货箱为何被遗弃","土匪偷货箱","商路遇袭"}},{q="其他货箱该怎么办？",a="把你找到的其他货箱带给商人，他会处理剩下的事。",al={"货箱送到哪里","其他货箱怎么处理","货箱送往何处"}},{q="谁要这些货箱？",a="一位商人请你把货物放在一堆货箱旁，并愿意为你的辛劳付酬。",al={"谁要货箱","货箱交付对象","谁接收货物"}}},fp="14,138,11.243.0,33.85.0,35.78.0,28.87.0"}
P.entries["quest:91904"] = {n="A Sealed Crate",s="“密封的箱子”是一项上交任务，涉及回收落入强盗之手或在商路上丢失的贸易货物。冒险者们将截获的货物归还给贸易负责人，以保障地区补给线的安全并获得报酬。",h="“密封的箱子”是一项上交任务，涉及回收落入强盗之手或在商路上丢失的贸易货物。冒险者们将截获的货物归还给贸易负责人，以保障地区补给线的安全并获得报酬。",kw={"密封的箱子","强盗","商队","货物","箱子","交付","商人","盗贼","贸易路线"},sec={{t="被盗货物与险象环生的道路",b="由于针对贸易商队的伏击事件激增，马车道和航运路线变得十分危险。毫无防备的运输者和信使经常在猝不及防之下丢失货物，导致沉重的密封箱子被遗弃在荒野的道路和小径上，直到被人发现并回收。"},{t="保障供应链安全",b="商人和补给协调员为找回丢失的商品提供长期赏金。找回这些流落的箱子并将其运回地区收集点的冒险者，有助于修复受损的物流线路，并因保护商业活动而获得直接的货币补偿。"}},faq={{q="什么是密封的箱子？",a="密封的箱子代表了在商业路径上被截获或遗失的贸易货物。冒险者回收这些被遗弃的货物后，可以将其上交给商人或当地接收人，以确保货运安全，并为他们的打捞工作获得经济补偿。",al={"密封的箱子用途","什么是密封的箱子","密封的箱子有什么用"}},{q="为什么这些箱子会随处可见？",a="近期，针对地区贸易路线的强盗行径和有组织窃案频发。劫匪和不法之徒经常伏击补给商队和运输者，导致货物被盗、被遗弃或散落在道路上。",al={"谁丢了箱子","为什么会丢失箱子","为什么路上会有箱子"}},{q="谁想要找回这些箱子？",a="商队协调员、军需官和贸易商会接收回收的箱子，将其整合堆放，并对货物进行分类，重新纳入正常的补给线中。他们会向找回丢失物资的人支付酬劳。",al={"谁收购密封的箱子","谁需要密封的箱子","箱子上交"}},{q="可以查看密封的箱子里面的东西吗？",a="为了确保贸易商品的安全性，这些箱子在运输途中始终保持锁闭和密封状态。将其完好地移交，可以让物流处理人员在不破坏箱子的情况下处理货物并向回收者发放报酬。",al={"我能打开密封的箱子吗","箱子里有什么","打开密封的箱子"}},{q="以后还能上交更多密封的箱子吗？",a="可以。由于主要交通要道上的劫掠行为依然猖獗，商人正在积极寻求更多回收的货物，并鼓励漫游者将他们在野外发现的任何其他流落箱子带回来。",al={"更多箱子","我可以上交更多箱子吗","箱子任务可以重复吗"}},{q="是谁在截断贸易路线？",a="在各个贸易区域内，盗贼和扒手的胆子越来越大，他们盯上了商人的货物，企图窃取贵重商品并破坏定居点之间的商业分销。",al={"强盗袭击贸易路线","盗贼窃取货物","谁在劫掠道路"}}},fp="14,154,32.206.0,25.220.0,23.163.0,34.163.0,32.187.0,35.158.0,48.154.0,37.141.0"}
P.entries["quest:91905"] = {n="A Sealed Crate",s="A Sealed Crate 代表了从被强盗和不法之徒破坏的贸易路线上回收的商人货物。贸易接收方支付报酬给冒险者，让他们寻回这些散落的货物，并保护它们免受日益猖獗的公路犯罪的侵害。",h="A Sealed Crate 代表了从被强盗和不法之徒破坏的贸易路线上回收的商人货物。贸易接收方支付报酬给冒险者，让他们寻回这些散落的货物，并保护它们免受日益猖獗的公路犯罪的侵害。",kw={"强盗","货物","箱子","运送","商人","回收","密封的箱子","窃贼","贸易路线"},sec={{t="受干扰的贸易路线",b="既定贸易路线上不法活动的激增，使得商队变得脆弱，货物散落一地。公路强盗和窃贼经常伏击补给线，导致在争议地区，未回收的货物随处可见。那些保护这些被遗弃或被盗集装箱的冒险者，有助于在无序状态下维持当地的商业活动。"},{t="回收的货物",b="当地的贸易接收方和搬运工依赖自由职业的信使来找回丢失的货物并将其送回储存仓库。每一箱送回的货物都能充实当地的库存，并让不法之徒无法通过公路抢劫获利，同时也让那些敢于闯荡危险道路的回收者获得公平的报酬。"}},faq={{q="密封的箱子里装的是什么？",a="具体的物品内容并未说明，但这个箱子代表了在贸易路线上被拦截的回收商业货物。商人和搬运工急于将这些货物储存起来，使其远离窃贼。",al={"密封的箱子里有什么","箱子内容物","箱子里装了什么"}},{q="为什么这些箱子会被丢弃在这里？",a="强盗和窃贼的崛起一直在拦截贸易路线，导致货物散落，并使商业箱子在该地区被遗弃或盗窃。",al={"为什么箱子会丢失","谁在偷箱子","强盗偷窃贸易货物"}},{q="谁想要这些箱子被送回？",a="当地的商人和贸易协调员负责接收找回的箱子，将其放入安全的库存中，并向从危险中打捞它们的冒险者支付报酬。",al={"谁来接收这些箱子","箱子去了哪里","上交箱子"}},{q="还可以回收更多的密封的箱子吗？",a="可以。由于强盗活动持续干扰陆路运输，当地的搬运工会不断支付报酬，请冒险者找回在贸易走廊上发现的任何其他箱子。",al={"我还能找到更多的箱子吗","可重复的箱子任务","更多密封的箱子"}},{q="是什么在威胁贸易路线？",a="贸易路线面临着机会主义的强盗和不法之徒的持续压力，他们掠夺毫无防备的商队，促使商人为找回的货物支付赏金。",al={"强盗贸易路线","贸易中断","为什么道路不安全"}},{q="为什么箱子是密封的？",a="任务文本中并未说明它为何是密封的。它仅仅是一个丢失的货物箱子，你把它带回给搬运工，他们会把它放进货物堆里，并以此向你支付报酬。",al={"密封的箱子用途","为什么要密封箱子"}}},fp="14,143,22.268.0,15.245.0,32.139.0,34.124.0,32.154.0,36.137.0,37.123.0,24.118.0"}
P.entries["quest:91906"] = {n="A Sealed Crate",s="一名商人请你送来一个密封的箱子，此时贸易路线上的劫掠事件日益增多。沿途发现的其他箱子也可以送到这里，由商人一并处理。",h="一名商人请你送来一个密封的箱子，此时贸易路线上的劫掠事件日益增多。沿途发现的其他箱子也可以送到这里，由商人一并处理。",kw={"劫匪","箱子","送交","报酬","密封的箱子","盗贼","贸易路线"},sec={{t="贸易物品",b="劫匪和盗贼开始拦截贸易路线上的货物，一名商人请你把一个密封的箱子送到那堆箱子旁。商人感谢你送来箱子，并说其他箱子也可以送到这里，由他们处理。贸易路线上的货物仍面临风险。"}},faq={{q="密封的箱子该送到哪里？",a="把箱子交给商人，他们会把它放在那堆箱子旁。",al={"密封的箱子","送交箱子","箱子送到哪里"}},{q="为什么箱子会被拦截？",a="最近劫匪和盗贼一直在拦截贸易路线上的货物。",al={"劫匪和箱子","贸易路线上的盗贼","箱子为何失踪"}},{q="我可以把其他箱子也送来吗？",a="可以。商人说，其他箱子也可以送到这里，他们会处理。",al={"其他箱子","发现箱子","继续送交箱子"}},{q="商人会给我什么？",a="商人会为你的辛劳付给你报酬。",al={"箱子报酬","补偿","报酬是什么"}}},fp="14,168,11.262.0,35.61.0,33.63.0,30.75.0,29.44.0"}
P.entries["quest:91920"] = {n="Wild Eyes",s="Wild Eyes是银松森林中的一个任务，一名病恹恹的被遗忘者斥候试图寻找一种解药，以避免彻底的二次死亡。由于对药剂师伦弗利尔那些基于心脏的无效药剂感到沮丧，这名斥候指派冒险者从洛丹米尔湖收集鱼人眼球，以迫使药剂师的研究取得突破。",h="Wild...",kw={"药剂师伦弗利尔","死亡猎手","被遗忘者炼金术","洛丹米尔湖","鱼人眼球","瑟伯切尔","银松森林","狂野之眼"},ang={["class:Rogue"]="死亡猎手是被遗忘者的精英斥候和刺客，这使得他们的身体恢复成为该地区的首要行动优先事项。",["faction:Horde"]="银松森林的被遗忘者战争事业在很大程度上依赖于药剂师伦弗利尔在瑟伯切尔的研究，以维持前线斥候和死亡猎手的作战能力。",["race:Undead"]="被遗忘者士兵不断与亡灵的身体腐烂作斗争，依靠皇家药剂师学会的残酷药剂来维持他们日渐衰退的力量。"},sec={{t="绝望的举措",b="在银松森林，一名病恹恹的被遗忘者死亡猎手正面临肉体腐烂和可能彻底二次死亡的严峻现实。由于对药剂师伦弗利尔酿造的无效药剂感到不满，这名斥候冒着触怒以臭名昭著著称的伦弗利尔的风险，在布满生物的洛丹米尔湖岸边寻找替代解药。"},{t="瑟伯切尔的新试剂",b="死亡猎手怀疑伦弗利尔最近沉迷于采集心脏，这让他忽略了其他可行的炼金试剂，于是指派冒险者收集鱼人眼球。将这些奇特的器官交给瑟伯切尔的伦弗利尔后，终于促使这位古怪的药剂师拓宽了他的实验，并让那位日渐虚弱的斥候恢复了活力。"}},faq={{q="是谁让你去收集鱼人眼球的？",a="银松森林里一名病恹恹的被遗忘者死亡猎手请求你帮助他们恢复日渐衰退的力量。如果伦弗利尔的药剂没有改善，他们将面临第二次死亡，因此他们孤注一掷，尝试寻找替代配料。",al={"谁给予野性之眼任务","野性之眼任务发布者","谁要求收集鱼人眼球"}},{q="为什么任务需要鱼人眼球？",a="这名死亡猎手注意到洛丹米尔湖岸边聚集了大量鱼人，于是建议采集它们的眼球。他们希望这种新奇的成分能让药剂师伦弗利尔的实验不再局限于他那狭隘的心脏执念。",al={"为什么需要鱼人眼球","鱼人眼球有什么用","鱼人眼球药剂"}},{q="药剂师伦弗利尔对递交的任务物品有何反应？",a="药剂师伦弗利尔起初嗤之以鼻，将药剂失效归咎于心脏数量不足，而不是他的配方问题。然而，他承认自己确实没有考虑过使用鱼人的身体部位，并同意将它们整合到药剂中以恢复死亡猎手的状态。",al={"伦弗利尔的反应","伦弗利尔说了什么","伦弗利尔喜欢这些眼球吗"}},{q="药剂师伦弗利尔在哪里？",a="药剂师伦弗利尔在瑟伯切尔进行他的黑暗研究，这是银松森林中主要的被遗忘者据点。",al={"药剂师伦弗利尔在哪里","伦弗利尔位置","在哪里上交野性之眼任务"}},{q="为什么伦弗利尔最初的药剂没有效果？",a="据伦弗利尔所说，药剂失败是因为只提供了三颗心脏，而不是配方要求的六颗。然而，那名病恹恹的死亡猎手认为，无论如何，该配方都没有产生任何明显的效果。",al={"为什么药剂失效","为什么伦弗利尔的药剂不起作用","死亡猎手药剂失效"}},{q="药剂师伦弗利尔沉迷于什么？",a="药剂师伦弗利尔对在他的恢复性混合药剂中使用动物心脏产生了狭隘的迷恋，这使他忽略了其他生物标本，直到看到鱼人眼球。",al={"伦弗利尔对心脏的执念","为什么伦弗利尔需要心脏"}}},fp="9,204,18.264.0,29.275.1,35.199.0,39.181.0,52.174.0,38.108.0,49.169.0,43.163.0"}
P.entries["quest:91921"] = {n="Return to Quinn (Again)",s="“回到奎恩身旁 (Again)”是银松森林中的一个运送任务，一名信使将一种复原炼金药剂送至伊瓦农场的奎恩·尤瑞克手中。这种特制的药剂能够阻止奎恩退化成丧失心智的食尸鬼，并恢复他的体力，使他能够继续旅程。",h="“回到奎恩身旁 (Again)”是银松森林中的一个运送任务，一名信使将一种复原炼金药剂送至伊瓦农场的奎恩·尤瑞克手中。这种特制的药剂能够阻止奎恩退化成丧失心智的食尸鬼，并恢复他的体力，使他能够继续旅程。",kw={"食尸鬼","伊瓦农场","奎恩·尤瑞克","奎恩的药水","回到奎恩身边","银松森林","瑟伯切尔"},ang={["faction:Horde"]="救助银松森林中陷入困境的旅行者和流浪者，有助于巩固部落在瑟伯切尔以北受瘟疫侵袭地区的影响力。",["race:Undead"]="奎恩·尤瑞克对退化成丧失心智的食尸鬼的恐惧，突显了被遗忘者为了保持自由意志和身体机能而不得不维持的微妙平衡。"},sec={{t="绝望的补救",b="奎恩·尤瑞克在银松森林瑟伯切尔以北的伊瓦农场休养，他正遭受着一种威胁其心智和身体的折磨。为了遏制他的病情，人们配制了一种以六颗心脏为原料的特殊炼金药剂，并被送往他的营地。对于被遗忘者及其盟友来说，运送此类药剂是救助受苦同胞，防止他们堕入腐烂与疯狂的关键一步。"},{t="防止退化",b="奎恩曾一度濒临接受严酷的命运：退化成丧失心智的食尸鬼。在收到并饮下新鲜调制的药剂后，药物立即生效，恢复了他的活力，使他得以准备继续在饱受瘟疫蹂躏的土地上旅行。"}},faq={{q="谁是奎恩·尤瑞克？",a="奎恩·尤瑞克是一位受折磨的旅行者，位于银松森林瑟伯切尔以北的伊瓦农场。他需要特殊的炼金药剂来抵御严重的身体退化，并恢复足够的体力以继续旅行。",al={"奎恩是谁","奎恩·尤瑞克背景故事","奎恩·尤瑞克是谁"}},{q="什么是奎恩的药水，他为什么需要它？",a="这种药水是专门为帮助奎恩·尤瑞克康复并防止其病情恶化而调制的。如果没有它，奎恩担心自己会屈服于退化，变成一个丧失心智的食尸鬼。",al={"药水有什么用","奎恩的药水用途","为什么奎恩需要药水"}},{q="伊瓦农场在哪里？",a="伊瓦农场位于银松森林瑟伯切尔的正北方，是奎恩·尤瑞克康复期间的临时住所。",al={"伊瓦农场在哪里","伊瓦农场位置"}},{q="奎恩的药水成分是什么？",a="送给奎恩的药物是一种炼金药剂，由提取自六颗完整心脏的精华调制而成，旨在阻止他的身体腐坏。",al={"药水成分","奎恩的药水是什么做的","心脏药水"}},{q="药水治好了奎恩·尤瑞克吗？",a="在喝下刚送达的药水后，奎恩立即感受到了其恢复效果。他表示自己很快就能恢复体力继续旅行，而不是退化成食尸鬼。",al={"奎恩怎么了","奎恩会变成食尸鬼吗","奎恩康复"}},{q="谁为奎恩调制药水？",a="药剂师伦弗利尔在瑟伯切尔调制了这种药水，使用的是六颗完整心脏的提取物。他以其典型的官僚作风不耐烦地将药水交出，急于打发走信使，以免产生更多文书工作。",al={"谁制作了奎恩的药水","药剂师奎恩"}}},fp="23,195,18.304.0,21.216.1,20.206.0,47.165.0,32.131.0,43.119.0,47.134.0,31.176.0"}
P.entries["quest:92"] = {n="赤脊山炖肉",s="赤脊山炖肉是湖畔镇当地的一种烹饪传统，由厨师布雷纳在湖畔的定居点延续至今。在最近黑石兽人入侵期间，为了供养驻守的暴风城守军，她的储藏室被掏空了，布雷纳因此转向那些四处游历的冒险者，以补充她制作这道丰盛山地菜肴所需的食材。",h="赤脊山炖肉是湖畔镇当地的一种烹饪传统，由厨师布雷纳在湖畔的定居点延续至今。在最近黑石兽人入侵期间，为了供养驻守的暴风城守军，她的储藏室被掏空了，布雷纳因此转向那些四处游历的冒险者，以补充她制作这道丰盛山地菜肴所需的食材。",kw={"黑石兽人","厨师布雷纳","秃鹫肉","野猪鼻","湖畔镇","赤脊山炖肉","赤脊山","蜘蛛肉"},ang={["faction:Alliance"]="湖畔镇物资匮乏的现状，鲜明地提醒了人们黑石兽人入侵对当地联盟驻军和民用基础设施造成的沉重代价。",["profession:Cooking"]="对于探索东部王国的厨艺爱好者来说，厨师布雷纳的炖肉展示了边境厨师是如何化腐朽为神奇，将凶猛的山地野兽变成足以饱腹的美味佳肴的。"},sec={{t="空空如也的山地储藏室",b="湖畔镇一直处于黑石兽人、豺狼人和凶猛野生生物的围攻之下。当最近兽人起义在山脊沿线爆发时，厨师布雷纳肩负起了为驻守镇上的整支暴风城部队提供食物的重任。维持一支活跃的军事驻军迅速耗尽了她的库存，让这位镇上的厨师虽然面对着许多需要满足的胃口，却落得个粮仓告急的下场。"},{t="山地的馈赠",b="随着储藏室见底，厨师布雷纳只好向湖畔镇大门外那危险的荒野求助。这道招牌炖肉需要混合几种当地野兽的硬核食材：来自山地秃鹫的粗糙肉块，来自强大的巨型野猪的鲜嫩猪鼻，以及从潜伏在山丘中的巨型蜘蛛身上采集的脆皮肉。"}},faq={{q="为什么厨师布雷纳的食物供应耗尽了？",a="在最近的黑石兽人起义期间，布雷纳必须供养整支部署在湖畔镇进行防御的暴风城部队，这彻底清空了她的储藏室。",al={"为什么储藏室是空的","布雷纳的储藏室","为什么没有食物"}},{q="制作赤脊山炖肉需要什么食材？",a="正宗的赤脊山炖肉需要五份硬秃鹫肉，五份巨型野猪鼻，以及五份香脆蜘蛛肉，这些食材全部采集自周围山区的原生生物。",al={"炖肉食材","赤脊山炖肉里有什么","炖肉用的肉"}},{q="厨师布雷纳在哪里？",a="厨师布雷纳可以在湖畔镇找到，她在那里照料着自己的炉火和锅具，镇子坐落在止水湖的北岸，位于赤脊山中。",al={"布雷纳的位置","厨师布雷纳在哪里","湖畔镇厨师"}},{q="为什么湖畔镇不直接从暴风城进口食物？",a="由于兽人、黑石突袭者和豺狼人切断了山路，加上暴风城的资源也捉襟见肘，湖畔镇必须经常依靠当地的野生生物和到访的冒险者来维持补给。",al={"暴风城物资","为什么不和暴风城贸易","湖畔镇食物短缺"}},{q="赤脊山炖肉算得上是美味佳肴吗？",a="虽然蜘蛛肉、野猪鼻和如同皮革般的秃鹫肉组合在一起，听起来对外乡人来说有些难以接受，但厨师布雷纳和湖畔镇的边境居民都认为这道成品菜肴是一道丰盛的山地珍馐。",al={"炖肉好吃吗","美味炖肉","赤脊山美食"}},{q="布雷纳需要供养哪支部队？",a="布雷纳负责为驻守湖畔镇的暴风城士兵提供食物，以抵御从北部山脊压境的黑石兽人部队。",al={"暴风城部队","谁保卫了湖畔镇","湖畔镇的部队"}}},fp="16,217,22.284.0,15.256.0,41.171.0,51.182.0,30.134.0,59.187.0,42.183.0,38.147.0"}
P.entries["quest:920"] = {n="特纳隆的召唤",s="特纳隆的召唤标志着幽影谷中年轻暗夜精灵的一个关键转折点。在协助基尔沙兰·风行者处理当地森林的危险后，你被召集前往攀登巨大的奥达希尔枝干，与特纳隆·雷拳商议。这份召唤标志着新手离开琐碎的本地杂务，去面对影响泰达希尔的更深层次精神创伤的时刻。",h="特纳隆的召唤标志着幽影谷中年轻暗夜精灵的一个关键转折点。在协助基尔沙兰·风行者处理当地森林的危险后，你被召集前往攀登巨大的奥达希尔枝干，与特纳隆·雷拳商议。这份召唤标志着新手离开琐碎的本地杂务，去面对影响泰达希尔的更深层...",kw={"奥达希尔","基尔沙兰","幽影谷","雷拳","召唤","泰达希尔","特纳隆","风行者"},ang={["class:Druid"]="向特纳隆·雷拳报到是了解如何监测和维护泰达希尔德鲁伊平衡的重要一步。",["race:NightElf"]="这份召唤标志着你正式在卡多雷社会中步入成年，从简单的林地防御转向直接服务于照料世界之树的长者们。"},sec={{t="树冠的召唤",b="你已经证明了自己有能力处理幽影谷中出没的剧毒蜘蛛和腐化的野生生物，你的努力并没有被忽视。基尔沙兰·风行者传话称，特纳隆·雷拳本人已经要求见你。即使在极其长寿的暗夜精灵中，让一位长者在大树奥达希尔之巅等待也被认为是无礼的行为。"},{t="攀登奥达希尔",b="特纳隆在奥达希尔的最高处房间等待，俯瞰着幽影谷翠绿的枝叶。回应这份召唤将直接引导你进入更重要的管理职责：净化泰达希尔的月亮井，并调查侵蚀世界之树雏形生态系统的非自然腐化。"}},faq={{q="特纳隆·雷拳是谁？",a="特纳隆·雷拳是一位居住在幽影谷奥达希尔最顶层房间里的有影响力的暗夜精灵。他负责监督幽影谷的精神照料，并协调监测和净化泰达希尔圣水的相关工作。",al={"特纳隆是谁","特纳隆·雷拳背景故事"}},{q="我在哪里可以找到特纳隆·雷拳？",a="他位于幽影谷中巨大的空心树干城市——奥达希尔的最顶层房间。你必须沿着树内的蜿蜒坡道向上攀登，才能到达他位于树冠附近的瞭望点。",al={"寻找特纳隆","特纳隆位置","特纳隆在哪里"}},{q="特纳隆为什么要召唤我？",a="一旦你证明了自己有能力处理下方受侵蚀的野生生物，特纳隆就会交给你更重要的责任——具体来说是调查圣洁的月亮井，并测试井水以寻找腐化的迹象。",al={"为什么召唤","特纳隆想要什么"}},{q="这个任务之后会发生什么？",a="回应这份召唤会直接开启“大地之冠”任务线，特纳隆会指派你收集泰达希尔各地月亮井的水样，以检查这棵树的健康状况。",al={"后续任务","特纳隆的召唤之后是什么"}},{q="是谁派你去找特纳隆的？",a="当你协助基尔沙兰·风行者处理威胁幽影谷低处空心的受毒液疯狂影响的蛛网林蜘蛛后，他就会交给你这份召唤。",al={"谁给予任务","基尔沙兰·风行者"}},{q="奥达希尔是什么？",a="奥达希尔是坐落在幽影谷偏僻山谷中的巨大枝干树，它是泰达希尔上年轻暗夜精灵冒险者的主要定居点和训练圣地。",al={"奥达希尔背景故事","什么是奥达希尔"}}},fp="17,159,20.223.0,19.215.0,25.193.0,34.157.0,27.191.0,30.159.0,25.138.0,18.146.0"}
P.entries["quest:921"] = {n="大地之冠",s="大地之冠是一项由特纳隆·雷拳在奥达希尔高处发起的入门仪式。当年轻的暗夜精灵准备踏出幽影谷去冒险时，他们会被派去附近的一口月亮井汲取圣水，并直面海加尔山那段痛苦的历史，以及他们种族失去永生的情况。",h="大地之冠是一项由特纳隆·雷拳在奥达希尔高处发起的入门仪式。当年轻的暗夜精灵准备踏出幽影谷去冒险时，他们会被派去附近的一口月亮井汲取圣水，并直面海加尔山那段痛苦的历史，以及他们种族失去永生的情况。",kw={"奥达希尔","大地之冠","水晶瓶","海加尔山","月亮井","诺达希尔","幽影谷","泰达希尔","特纳隆·雷拳"},ang={["class:Druid"]="月亮井是塞纳里奥议会的重要工具，提供了净化自然能量的渠道，这对于维护森林的平衡至关重要。",["class:Priest"]="月亮井致力于侍奉艾露恩，作为反思性的圣所，其中的水在月之母的注视下得到圣化。",["race:NightElf"]="这项仪式标志着你从幽影谷毕业，将你的个人命运与海加尔山之巅所做的牺牲以及守护泰达希尔的责任联系在了一起。"},sec={{t="近期历史的一课",b="在任何初出茅庐的冒险者离开幽影谷的庇护树枝之前，长者们都会确保他们理解卡多雷最近付出的沉重代价。在海加尔山之战中，世界之树诺达希尔为了击败阿克蒙德并放逐燃烧军团而被牺牲了。随着那场灾难性的爆炸，暗夜精灵失去了他们亘古不变的永生和神圣的护盾。特纳隆·雷拳既是导师也是历史学家，他为新手布置了这个仪式，旨在让他们在面对瞬息万变的世界之前，学会谦逊与使命感。"},{t="月亮井之水",b="这项任务需要使用水晶瓶从奥达希尔北部的月亮井中汲取井水。这些月亮井绝非普通的泉水；它们的泉水中融入了永恒之井的遗迹。虽然德鲁伊们将它们的恢复力量引导至荒野，而哨兵们也将它们尊为艾露恩女神的宁静圣所，但卡多雷仍然保持着高度警惕。奥术魔法在暗夜精灵社会中仍然被严格禁止，因为支撑他们家园的泉水，同时也提醒着人们，曾经那鲁莽的魔法差点毁灭了世界。"}},faq={{q="特纳隆·雷拳是谁？",a="特纳隆·雷拳是一位身处幽影谷奥达希尔高层树枝上的暗夜精灵。他指导那些即将完成基础训练的年轻暗夜精灵，布置仪式让他们在前往泰达希尔之前学习种族庄严的历史。",al={"特纳隆·雷拳","谁给予大地之冠任务","奥达希尔德鲁伊非玩家角色"}},{q="收集月亮井水的目的是什么？",a="用水晶瓶收集井水是穿越整座岛屿的仪式性和实践性旅程的第一步。月亮井的井水蕴含着古老的魔法，德鲁伊们利用这些魔法来滋养大地，而仪式本身旨在教育年轻的卡多雷关于他们社会的神圣义务。",al={"为什么要获取月亮井水","装满水的水晶瓶用途","月亮井的用途"}},{q="为什么暗夜精灵失去了永生？",a="在第三次战争期间，暗夜精灵引爆了编织在世界之树诺达希尔中的先祖之力，以此在海加尔山之巅消灭恶魔领主阿克蒙德。那次牺牲摧毁了军团的先锋，但也剥夺了暗夜精灵亘古不变的青春和对疾病的免疫力。",al={"为什么暗夜精灵会变得终有一死","永生发生了什么","诺达希尔的毁灭"}},{q="月亮井被认为危险吗？",a="月亮井中含有与永恒之井有迹可循的稀释精华。虽然德鲁伊和女祭司们安全地引导这些能量进行治疗、祝福和自然沟通，但卡多雷严禁将它们用于奥术魔法，因为鲁莽的魔法在古代历史上曾引发过灾难。",al={"月亮井属于奥术吗","月亮井水是否安全","永恒之井的危险"}},{q="这个任务链接下来通向哪里？",a="归还装满水的水晶瓶即完成了大地之冠系列任务的开篇课程。特纳隆随后会派你去找多兰纳尔的科瑞萨斯·月怒，他会让你在泰达希尔各处的月亮井里装满瓶子，交给达纳苏斯的德鲁伊，并最终呈交给大德鲁伊范达尔·鹿盔。",al={"大地之冠之后是什么","大地之冠任务线","特纳隆之后的下一个任务"}},{q="这个任务的月亮井位于何处？",a="这口月亮井位于奥达希尔巨大的树枝以北，只需步行很短的路程，便可发现它静谧地坐落在幽影谷的树林之中。",al={"月亮井在哪里","幽影谷月亮井位置","寻找水晶瓶之井"}}},fp="18,205,26.391.0,18.412.0,25.222.0,49.212.0,47.261.0,35.257.0,38.221.0,45.96.0"}
P.entries["quest:92109"] = {n="My First Alchemy Set",s="月溪镇一名年轻炼金师向你索要基础材料。尽管父亲警告她不要碰草药，她还是想开始学习炼金术。",h="月溪镇一名年轻炼金师向你索要基础材料。尽管父亲警告她不要碰草药，她还是想开始学习炼金术。",kw={"炼金术","空瓶","月溪镇","我的第一套炼金材料","peacebloom","银叶草","西部荒野","年轻的炼金师"},sec={{t="年轻的炼金师",b="月溪镇谷仓里的女孩被告知不要碰父亲的草药。她希望趁年幼时学习炼金术，于是请你带来空瓶、银叶草和 Peacebloom。她正等着看看自己能用这些材料做出什么。"}},faq={{q="谁在索要炼金材料？",a="月溪镇谷仓里一名年轻、立志成为炼金师的女孩向你索要材料。",al={"谁想要材料","月溪镇炼金女孩"}},{q="她为什么想要这些东西？",a="她想开始学习炼金术，但父亲认为草药很危险，不让她碰。",al={"为什么要炼金材料","她为什么需要材料"}},{q="她在要哪些材料？",a="她要五个 Empty Vials、五份银叶草和五份 Peacebloom。",al={"需要哪些物品","炼金材料"}},{q="我在哪里能找到那名年轻的炼金师？",a="她在西部荒野的月溪镇谷仓里。",al={"女孩在哪里","月溪镇谷仓"}},{q="她打算用这些材料做什么？",a="她说要看看自己能用这些材料做出什么。",al={"她会做出什么","她会制作药水吗"}}},fp="20,129,17.248.0,34.79.0,31.122.0,32.68.0,37.46.0,43.58.0"}
P.entries["quest:92110"] = {n="My First Real Potion",s="一个躲藏起来的孩子请你带回鱼人的眼睛，好让她制作第一瓶真正的药水。她迫不及待地想亲自试着调配。",h="一个躲藏起来的孩子请你带回鱼人的眼睛，好让她制作第一瓶真正的药水。她迫不及待地想亲自试着调配。",kw={"孩子","草药","鱼人的眼睛","我的第一瓶真正的药水","橙色药水","药水","瓶子"},sec={{t="初次尝试",b="你带着鱼人的眼睛回来时，孩子兴奋不已。你离开期间，她采集了更多草药，还在楼下找到了空瓶子。这次她请你调配材料，并在鱼人的眼睛放进去后，看着药水变成令人作呕的橙色。"}},faq={{q="孩子想要什么？",a="孩子想要鱼人的眼睛、草药和空瓶子，好制作她的第一瓶真正的药水。",al={"她想要什么","孩子药水","药水材料"}},{q="谁来调配药水？",a="你来调配药水，孩子在一旁看着。",al={"谁来调配","调配药水","药水调配者"}},{q="药水变成了什么颜色？",a="加入鱼人的眼睛后，混合物几秒内就变成了令人作呕的橙色。",al={"药水颜色","橙色药水","看起来怎么样"}},{q="孩子会喝下它吗？",a="不会。孩子说她才不会喝这药水，但把配方给了你。",al={"喝下药水","她会喝吗","安全吗"}}},fp="20,95,15.228.0,25.88.0,21.43.0,32.73.0,24.76.0"}
P.entries["quest:92124"] = {n="Book Inventory",s="“Book Inventory”是北郡修道院的一项入门任务，由帕克斯顿修士发布。由于书籍丢失和错位，修道院的图书管理员感到非常沮丧，于是派遣年轻的冒险者去寻找他的助手丹尼尔，并清点修道院图书馆的藏书。然而，丹尼尔那热衷于幻想当地商业技能的臭毛病，使得想要得到一个直接的答案变得比帕克斯顿希望的要困难得多。",h="“Book...",kw={"书籍清点","帕克斯顿修士","丹尼尔","艾尔文森林","图书馆","北郡修道院","专业","商业技能"},ang={["class:Priest"]="在北郡学习神圣档案的牧师们依靠图书馆的秩序来保存神圣的经文和教会传统。",["race:Human"]="对于在北郡修道院开始服役的年轻人类来说，平衡修道院的学术职责与现实的村庄生活是一种熟悉的挣扎。"},sec={{t="图书管理员的苦恼",b="北郡修道院保存着第一次战争后暴风王国境内仅存的一些最古老的学术著作、灵性文献和历史记录。管理这些卷册的任务落在了帕克斯顿修士肩上，他是一位一丝不苟的僧侣，对修道院的藏书引以为傲。近来，书架上的书籍频频失踪，威胁到了北郡档案馆的宁静。帕克斯顿需要一份清晰的清单来了解损失到底有多严重，但他实在没有耐心去追着他那个爱做白日梦的助手跑。"},{t="丹尼尔飘忽的兴趣",b="丹尼尔驻守在修道院图书馆内，担任帕克斯顿修士的助手，但这个年轻人的心思很少放在羊皮纸和目录编号上。相反，丹尼尔对艾尔文森林里的实用商业技能——锻造、制皮、裁缝和草药学非常着迷。这种专注让帕克斯顿感到无比恼火，因为每次清点任务最终都会变成助手在絮絮叨叨地谈论当地的工匠，而不是去寻找丢失的经文。"}},faq={{q="谁是帕克斯顿修士？",a="帕克斯顿修士是北郡修道院的一位僧侣，负责照看修道院庞大的书籍、经文和历史卷轴收藏。每当书籍丢失或助手逃避职责时，他总是很容易发火。",al={"帕克斯顿修士","谁发布了清点书籍任务","帕克斯顿 艾尔文森林"}},{q="谁是丹尼尔？",a="丹尼尔是帕克斯顿修士派驻在北郡修道院图书馆的年轻助手。虽然他的任务是整理书籍和进行清点，但他很容易被自己对艾尔文森林各地商业技能和专业的痴迷所分心。",al={"丹尼尔是谁","帕克斯顿的助手","丹尼尔 北郡"}},{q="为什么北郡修道院的书籍会丢失？",a="帕克斯顿修士说书籍丢失了，但没有解释原因。他要求丹尼尔清点藏书，并确定损失的程度。",al={"为什么书籍丢失","北郡丢失书籍","修道院丢失书籍"}},{q="在哪里可以找到丹尼尔？",a="丹尼尔在北郡修道院内，具体来说是在修道院图书馆的书架和书桌旁研究。",al={"丹尼尔在哪里","丹尼尔的位置","寻找丹尼尔"}},{q="为什么帕克斯顿称丹尼尔没用？",a="帕克斯顿认为丹尼尔没用，因为这孩子总是忽视他的档案职责。丹尼尔花时间做白日梦和谈论实用的商业技能，而不是去编目和上架书籍。",al={"为什么帕克斯顿讨厌丹尼尔","丹尼尔没用"}},{q="丹尼尔对哪些商业技能感兴趣？",a="丹尼尔对艾尔文森林各地流行的各种工艺非常着迷，例如锻造、制皮和裁缝，比起积满灰尘的典籍，他更喜欢亲手劳作。",al={"丹尼尔的商业技能","丹尼尔喜欢什么专业"}}},fx={deb80ab5={q="帕克斯顿修士为什么要清点书籍？",a="北郡修道院发现书架上的书籍接连失踪，帕克斯顿修士需要赶在藏书遭受更多损失之前，查清究竟丢了多少书。他的助手丹尼尔本该负责整理图书馆，却总在幻想当地的各种行当，这让帕克斯顿十分恼火，也完全不知道究竟有多少书不翼而飞。",al={"为何进行清点书籍","帕克斯顿为何要清点书籍","帕克斯顿的动机"}}},fp="14,251,25.340.0,27.370.0,22.246.0,14.215.0,44.135.0,26.94.0,36.190.0,41.177.0"}
P.entries["quest:922"] = {n="雷利亚·绿树",s="这项任务要求你从泰达希尔的德纳兰的湖畔隐居处前往首都达纳苏斯。将一颗林精的种子交给德鲁伊雷利亚·绿树，会揭示出关于世界之树枝叶间蔓延的腐蚀这一令人不安的消息。",h="这项任务要求你从泰达希尔的德纳兰的湖畔隐居处前往首都达纳苏斯。将一颗林精的种子交给德鲁伊雷利亚·绿树，会揭示出关于世界之树枝叶间蔓延的腐蚀这一令人不安的消息。",kw={"塞纳里奥区","腐蚀","达纳苏斯","德纳兰","雷利亚·绿树","泰达希尔","林精的种子"},ang={["class:Druid"]="对于塞纳里奥的入门者来说，这项任务凸显了一种无法预见的疾病已经深入泰达希尔新发芽的生态系统，强调了保护本土元素生物的迫切需要。",["race:NightElf"]="林精本应随着泰达希尔的生长而繁荣，雷利亚发现的遗传性腐蚀对于卡多雷的新家园来说是一个令人担忧的迹象。"},sec={{t="前往首都的信使",b="德纳兰花费了大量精力来培育和研究奥拉密斯湖周围的植物群和元素生物。在收集了当地林精的种子后，他派遣你前往达纳苏斯，将样本呈交给他的同事雷利亚·绿树。雷利亚也是一位德鲁伊，在塞纳里奥区的宁静露台上行走，他之前就对德纳兰的研究表示过好奇，并希望能亲自培育一只林精。"},{t="被污染的生长",b="在收到种子后，雷利亚带来的不是学术上的乐观，而是严峻的消息。他最近的调查证实，泰达希尔各处的林精正成为一种具有侵略性且无处不在的腐蚀的受害者。更糟糕的是，从被污染的样本中收获的种子已经携带了它们亲本的枯萎。雷利亚承认净化它们超出了他个人的能力范围，并建议只有德纳兰对生命体深厚的亲和力才有一丝恢复平衡的希望。"}},faq={{q="雷利亚·绿树是谁？",a="雷利亚·绿树是一位暗夜精灵德鲁伊，在达纳苏斯的塞纳里奥区的小径上徘徊。他与德纳兰保持着密切的学术联系，共同关注泰达希尔的生态和元素之灵。",al={"雷利亚·绿树背景故事","雷利亚是谁","雷利亚·绿树位置"}},{q="为什么德纳兰要给雷利亚发送林精的种子？",a="德纳兰在你的协助下收集了奥拉密斯湖的林精种子。想起雷利亚曾对林精生物学表示过兴趣并拥有自己的理论，德纳兰提供了一颗种子，以便雷利亚能在首都尝试培育一只。",al={"为什么要发送林精种子","德纳兰的差事"}},{q="雷利亚发现了什么问题？",a="雷利亚发现一种非自然的腐蚀感染了林精。因此，从它们身上收获的种子已经被其亲本的枯萎所扭曲，如果不先找到治愈方法，就不可能培育出健康的嫩芽。",al={"林精种子有什么问题","林精腐蚀"}},{q="这项任务接下来指向哪里？",a="雷利亚自己无法治愈受污染的种子，所以他派你去泰达希尔北部的涌泉湖砍伐受污染最严重的林精，并带回它们的苔藓肿瘤以便焚烧。",al={"雷利亚·绿树之后是什么","雷利亚之后的下一个任务"}},{q="在哪里可以找到雷利亚·绿树？",a="雷利亚在位于达纳苏斯西北角的塞纳里奥区中的开阔小径上行走。",al={"雷利亚在哪里","雷利亚地图位置"}},{q="为什么雷利亚不能自己净化种子？",a="腐蚀的深层性质超出了雷利亚特定的才能。他推崇德纳兰在植物学和培育生命体方面的非凡技能，认为他的朋友是治愈未来一代林精的最大希望。",al={"为什么雷利亚无法治愈它们","雷利亚德鲁伊能力"}}},fp="18,182,24.351.0,14.312.1,26.175.0,51.198.0,35.161.0,31.177.1,38.96.0,44.206.0"}
P.entries["quest:923"] = {n="青苔之瘤",s="这项任务旨在协助达纳苏斯的塞纳里奥议会，派遣冒险者去泰达希尔北部的涌泉湖附近清理那些受感染的树木怪。通过从这些扭曲的自然之灵身上收集苔藓肿瘤，德鲁伊们希望能研究这种蔓延的毒素，并安全地烧毁那些腐蚀性的增生物。",h="这项任务旨在协助达纳苏斯的塞纳里奥议会，派遣冒险者去泰达希尔北部的涌泉湖附近清理那些受感染的树木怪。通过从这些扭曲的自然之灵身上收集苔藓肿瘤，德鲁伊们希望能研究这种蔓延的毒素，并安全地烧毁那些腐蚀性的增生物。",kw={"塞纳里奥议会","腐蚀","达纳苏斯","德纳兰","青苔之瘤","雷利亚·绿树","泰达希尔","树木怪","肿瘤","涌泉湖"},ang={["class:Druid"]="对于塞纳里奥议会的德鲁伊来说，摧毁腐化的自然之灵是一项悲剧但必要的职责，旨在保护泰达希尔脆弱的平衡免于彻底崩溃。",["profession:Herbalism"]="草药师和植物学家们看到活木和苔藓扭曲成有毒的恶性肿瘤，而不是健康的枝叶，感到非常不安。",["race:NightElf"]="这种疾病在新长成的世界之树上迅速出现，这对卡多雷来说是一个令人担忧的迹象，挑战了范达尔·鹿盔关于一片未受污染的避难所的承诺。"},sec={{t="树木怪的枯萎病",b="泰达希尔本被建成一个和谐的避难所，但一种奇怪的疾病已经开始扭曲其本土的动植物。树木怪——通常是温和、树皮质感的自然之灵——已经变得充满敌意且不可预测。在它们活生生的木质躯体上，长出了怪诞的苔藓肿瘤，跳动着污秽且不自然的毒素。当像德纳兰和雷利亚·绿树这样的塞纳里奥学者正在寻找这种疾病的根源时，那些已经陷入邪恶的生物必须被清理，以保护其他枝桠。"},{t="涌泉湖的遏制行动",b="泰达希尔北部的涌泉湖已成为疫情的中心点。徘徊在湖岸边的树木怪是整棵世界之树上受污染最严重的生物。雷利亚·绿树委托旅行者砍倒这些腐化的守护者并切除它们的增生物。通过将肿瘤直接带到达纳苏斯交给德鲁伊进行安全焚烧，暗夜精灵们希望在继续寻找疾病源头的同时，遏制这种传染病的蔓延。"}},faq={{q="为什么树木怪会长出肿瘤？",a="一种神秘的疾病已在泰达希尔的野性之灵中扎根。苔藓肿瘤是毒素在其体内流动的外部物理症状，将它们自然的保护本能扭曲成了盲目的攻击性。",al={"树木怪怎么了","树木怪疾病","为什么树木怪会生病"}},{q="雷利亚·绿树是谁？",a="雷利亚·绿树是一位隶属于塞纳里奥议会的暗夜精灵研究员，驻扎在达纳苏斯。他与其他植物学家（如德纳兰）密切合作，研究困扰着泰达希尔生态系统的奇怪腐蚀。",al={"雷利亚·绿树背景故事","绿树是谁","雷利亚·绿树"}},{q="为什么要焚烧肿瘤？",a="雷利亚·绿树说这些肿瘤充满了毒素，必须从泰达希尔清除。他要求把这些增生物带给他，以便进行焚烧。",al={"焚烧肿瘤","为什么要焚烧肿瘤","摧毁苔藓肿瘤"}},{q="涌泉湖在哪里？",a="涌泉湖位于泰达希尔的北部地区，由枝桠间纯净的水道供给。环绕在其岸边的树木怪明显比其他地方发现的更虚弱。",al={"涌泉湖位置","去哪里找树木怪","苔藓肿瘤在哪里"}},{q="树木怪可以被治愈而不是被杀死吗？",a="塞纳里奥议会正在积极寻找这种枯萎病的治疗方法或起源，但徘徊在涌泉湖的树木怪已被认为无药可救。在找到源头之前，消灭最具有攻击性的灵魂是保护森林的唯一途径。",al={"树木怪能被拯救吗","治疗树木怪"}},{q="把肿瘤带到达纳苏斯之后会发生什么？",a="在雷利亚妥善处理并摧毁肿瘤后，他会指引冒险者回到奥拉密斯湖附近的野外植物学家德纳兰那里，继续调查泰达希尔植被中蔓延的腐蚀。",al={"肿瘤任务后续","肿瘤任务接下来做什么"}}},fp="6,236,27.423.0,30.406.0,39.202.0,26.205.0,30.148.0,25.164.0,47.240.0,52.203.0"}
P.entries["quest:924"] = {n="恶魔之种",s="在尼鲁·火刃的授意下，阿克泽洛斯指派部落的旅行者去消灭鬼雾峰顶的恶魔之种。通过在火焰祭坛上安置一颗不稳定的破损的能量石，冒险者们可以摧毁这个与燃烧军团相连的强力媒介，阻止其黑暗影响力在贫瘠之地进一步蔓延。",h="在尼鲁·火刃的授意下，阿克泽洛斯指派部落的旅行者去消灭鬼雾峰顶的恶魔之种。通过在火焰祭坛上安置一颗不稳定的破损的能量石，冒险者们可以摧毁这个与燃烧军团相连的强力媒介，阻止其黑暗影响力在贫瘠之地进一步蔓延。",kw={"阿克泽洛斯","火焰祭坛","贫瘠之地","燃烧军团","恶魔之种","鬼雾峰","破损的能量石","尼鲁·火刃"},ang={["class:Warlock"]="术士们深知制作能量石所需的精细工作，这种能量石必须能破坏军团的纽带，同时又不会意外引发灾难性的恶魔内爆。",["faction:Horde"]="清除贫瘠之地中的军团立足点，可以保护维持年轻部落运转的重要大篷车十字路口和贸易路线。",["race:Orc"]="在经历了德拉诺因恶魔腐蚀而毁灭的惨剧后，兽人对在杜隆塔尔边境附近滋生的军团祭坛几乎零容忍。"},sec={{t="峭壁上的信标",b="恶魔之种坐落在鬼雾峰高处的一个嶙峋洞穴内，悬浮在恶魔的火焰祭坛上方。这件神器是燃烧军团的一件强力装置，它将恶魔的频率锚定在了贫瘠之地的尘土中心。为了应对这一威胁，兽人阿克泽洛斯准备了专门的能量石，能够切断该神器与虚空的联系，前提是有特工能在其不稳定的能量消散前将其带到峰顶。"},{t="摧毁纽带",b="在鬼雾峰崎岖的山坡上运送这块脆弱的石头是一场与时间的赛跑，因为石头在缓慢地消耗自身的能量。一旦将其放入火焰祭坛，催化剂就会使恶魔之种过载并切断其连接。然而，让这个媒介沉寂也会带来令人不安的后果：它突然的毁灭会向以太中散发出惊人的冲击波，警告那些强大的、未知的掌控者：他们宝贵的装置已经被破坏了。"}},faq={{q="什么是恶魔之种？",a="恶魔之种是燃烧军团的一件神器，位于鬼雾峰顶的一个洞穴中。它放置在火焰祭坛上方，作为一个将恶魔力量和影响力直接引入贫瘠之地的媒介。",al={"恶魔之种的用途","什么是恶魔之种","恶魔之种背景"}},{q="是谁下令摧毁恶魔之种的？",a="这个任务由兽人阿克泽洛斯直接指派，他在奥格瑞玛下方大断崖处驻扎的著名术士尼鲁·火刃的指示下行动，并负责发放其奖励。",al={"谁想要摧毁恶魔之种","尼鲁与恶魔之种","阿克泽洛斯任务发布者"}},{q="为什么破损的能量石有时间限制？",a="阿克泽洛斯制作的破损的能量石天生不稳定。其魔法禁锢并不完美，如果不能在短时间内将其带到恶魔祭坛，其破坏性能量就会耗尽并吞噬这块石头。",al={"破损的能量石时间限制","为什么石头会失效","石头消失"}},{q="火焰祭坛位于何处？",a="恶魔火焰祭坛位于鬼雾峰山顶附近的一个洞穴内，那是一座位于贫瘠之地北部、十字路口西北方向的险恶山峰。",al={"火焰祭坛位置","恶魔之种洞穴","鬼雾峰洞穴"}},{q="恶魔之种被摧毁后会发生什么？",a="摧毁之种切断了其与燃烧军团的联系，但剧烈的魔法释放会在以太中激起巨大的涟漪。阿克泽洛斯警告说，强大的恶魔实体会感应到这种干扰，并将调查他们的工具为何会被毁坏。",al={"恶魔之种冲击波","恶魔之种的后果","能量波"}},{q="这与尼鲁·火刃有什么关系？",a="尼鲁·火刃与阿克泽洛斯协作，针对贫瘠之地各处的竞争性或干扰性恶魔神器采取行动。一旦恶魔之种被清除，尼鲁就会提供作为补偿的金币和装备。",al={"尼鲁的关联","尼鲁是好人吗","尼鲁的参与"}}},fp="14,237,21.308.0,21.297.1,23.164.0,45.162.0,50.158.0,35.122.0,46.234.1,41.186.0"}
P.entries["quest:92401"] = {n="A Frightened Request",s="A Frightened Request 是一个关于爱德华·心织者在危险的洛丹伦废墟中失踪的任务。在儿子于首都沦陷时遇难后，爱德华悲痛欲绝，他多次前往这座废墟城市的墓地寻找孩子的遗体，随后便杳无音讯。一位冒险者被委托前往危险的废墟，查明他的最终下场。",h="A Frightened Request...",kw={"惊恐的请求","阿尔萨斯","爱德华·心织者","心织者","洛丹伦墓地","失踪的丈夫","洛丹伦废墟","天灾军团"},ang={["class:Priest"]="致力于精神治愈和抚慰的牧师们能够轻易理解那种驱动一位父亲在被占领的墓地中寻找失踪儿子的无法承受的悲伤和精神不安。",["race:Human"]="洛丹伦的陷落仍然是人类记忆中最深重的悲剧之一。对于人类来说，爱德华的绝望搜寻是一个令人心碎的提醒，提醒人们阿尔萨斯王子在背叛并屠杀自己的人民时，无数家庭是如何支离破碎的。",["race:Undead"]="幽暗城上方的废墟被崛起于王国灰烬之中的被遗忘者所占据。穿行于破碎的首都墓地的活人，在被遗忘者如今控制的土地上，映照出过去的残影。"},sec={{t="父亲的悲痛",b="当阿尔萨斯王子和天灾军团在第三次战争期间夷平洛丹伦首都时，无数家庭在屠杀中支离破碎。在这些因悲剧而破碎的家庭中，心织者一家在王国陷落时失去了他们年幼的儿子。由于在毁灭中未能找回男孩的尸体，他的父亲爱德华·心织者陷入了巨大的悲伤和无法释怀的愧疚之中。爱德华无法放下过去，也无法接受失去的现实，开始每周进行危险的朝圣之旅，进入那座被占领的废墟首都的墓地，渴望找到孩子遗体的任何踪迹。"},{t="废墟的危险",b="洛丹伦的地上废墟已不再是一个静谧的纪念之地。在城市毁灭后的余波中，这里充斥着敌对的实体和潜伏的恐怖，对于普通市民来说，这片土地依然极其危险。尽管他的妻子一再发出警告和恳求，爱德华还是拒绝放弃他每周的守望。当他例行的旅程变成了长达数天且无法解释的失踪时，他绝望的妻子向有能力的冒险者寻求帮助，请求他们勇敢地面对废墟中的危险，查明她丈夫的最终下场。"}},faq={{q="谁是爱德华·心织者？",a="爱德华·心织者是一位悲痛欲绝的人类父亲，他的儿子在天灾军团毁灭洛丹伦时失踪。由于未能找回孩子的尸体而备受愧疚的折磨，爱德华每周都会进行朝圣，在首都废墟中杂草丛生的墓地里进行搜寻，直到他神秘地消失。",al={"爱德华是谁","爱德华·心织者背景故事","废墟中的丈夫"}},{q="为什么爱德华要去洛丹伦废墟？",a="爱德华冒险进入洛丹伦废墟，是为了寻找他在阿尔萨斯王子夷平首都时失踪的儿子的遗体。背负着悲痛和无法释怀的遗憾，尽管妻子一再警告，爱德华还是拒绝停止在废墟危险的墓地中进行搜寻。",al={"爱德华为什么去洛丹伦","爱德华·心织者墓地","为什么要搜寻洛丹伦废墟"}},{q="为什么洛丹伦废墟如此危险？",a="自从天灾军团在第三次战争中洗劫了首都以来，洛丹伦的地上废墟就已经被危险的生物和敌对势力所占据。普通平民无法安全地前往那里，这使得对旧址的任何长时间搜寻都极其危险。",al={"为什么洛丹伦废墟很危险","洛丹伦废墟里有什么","洛丹伦废墟的威胁"}},{q="谁提供了惊恐的请求任务？",a="这个任务由爱德华·心织者焦急的妻子提供。她自己无法面对潜伏在废墟王国中的致命恐怖，于是向过往的冒险者求助，请他们在她丈夫每周的搜寻后未能归来时去寻找他。",al={"谁发布了惊恐的请求","惊恐的请求任务发布者","爱德华妻子的任务"}},{q="爱德华的儿子发生了什么事？",a="心织者一家的儿子在洛丹伦沦陷时失踪，当时阿尔萨斯王子和他的亡灵大军彻底摧毁了这座城市。在混乱中，孩子的尸体一直未能找到，这让他的父亲陷入了深深的悲伤和无法得到解答的疑问之中。",al={"儿子发生了什么","爱德华·心织者的儿子","洛丹伦失踪的儿子"}},{q="惊恐的请求的任务目标是什么？",a="该任务要求冒险者前往危险的洛丹伦废墟，调查爱德华·心织者的遭遇。玩家必须勇敢地面对被占领的城市地面，揭开他的最终下场，并将答案带给他等待中的妻子。",al={"惊恐的请求要做什么","惊恐的请求目标","如何完成惊恐的请求"}}},fp="20,248,16.370.0,23.382.0,26.193.0,44.204.0,44.163.0,42.168.0,30.169.0,46.117.0"}
P.entries["quest:92415"] = {n="Remember That I Love You",s="“Remember That I Love You”始于一张在洛丹伦废墟中亡灵出没的墓地中发现的破损且沾染污渍的羊皮纸。这封信讲述了一个属于Heartweaver家族的失踪孩子的悲剧故事。想要寻求答案，就需要将这件脆弱的遗物带往南方的暴风城孤儿院。",h="“Remember That I Love...",kw={"染血的信","首都","织心者","孤儿监护员奈丁加尔","记住我爱你","洛丹伦废墟","暴风城孤儿院"},ang={["faction:Alliance"]="将信安全送达暴风城是为了纪念洛丹伦陷落时那些支离破碎的北方家庭。",["race:Human"]="对于洛丹伦血统的人类来说，这卷羊皮纸是一个痛苦的提醒，让人想起当首都陷落于阿尔萨斯王子和Scourge时，那些破碎的家庭。"},sec={{t="来自废墟的恳求",b="在首都废墟那些枯萎的大地和游荡的亡灵之间，幸存者和拾荒者偶尔会偶然发现第三次大战蹂躏后的残留物。这卷破损且染血的羊皮纸勉强在亡灵践踏的墓地中保存了下来。它提到了Heartweaver家族的一个失踪孩子，是阿尔萨斯王子和Scourge撕裂王国时破碎生命的见证。"},{t="前往孤儿院的旅程",b="随着洛丹伦的陷落和幽暗城占据了下方的墓穴，少数逃往南方的难民散落在联盟的各个王国中。在暴风城，孤儿监护员奈丁加尔照顾着那些在战争中失去双亲的孩子。将这封染血的信交给她照看，是确认Heartweaver家族幸存孩子并使其获得慰藉的仅有希望之一。"}},faq={{q="在哪里可以找到染血的信？",a="这卷破损且沾染污渍的羊皮纸是在洛丹伦废墟的墓地区域被发现的，该区域现在有不安的亡灵和被遗忘者部队游荡。",al={"染血的信位置","羊皮纸位置","任务起始点"}},{q="织心家族是谁？",a="目前关于织心家族的信息知之甚少。这封在洛丹伦废墟墓地中找到的信提到了家族中一个失踪的孩子，让人希望这个孩子已经逃到了南方的联盟避难所。",al={"织心","谁是织心家族","织心背景故事"}},{q="谁是孤儿监护员奈丁加尔？",a="孤儿监护员奈丁加尔负责管理暴风城教堂广场的暴风城孤儿院，为那些在近期的战争中失去双亲的青少年提供食物、住所和指导。",al={"奈丁加尔","监护员奈丁加尔","孤儿监护员"}},{q="为什么要将洛丹伦的纪念物一直带到暴风城？",a="当天灾军团席卷洛丹伦时，许多孤儿被疏散到南方的暴风城王国。羊皮纸本身暗示了管理暴风城孤儿院的暴风城孤儿监护员会知道更多信息。",al={"为什么是暴风城","为什么要交给奈丁加尔"}},{q="部落玩家可以完成这个任务吗？",a="该任务指引持有者前往暴风城教堂广场深处的孤儿监护员奈丁加尔处，这明确表明该旅程属于联盟的职责。",al={"部落版本","部落能否完成"}},{q="洛丹伦废墟现在的状态如何？",a="首都的地表废墟大多荒废、崩塌，并有残留的亡灵徘徊，而希尔瓦娜斯·风行者和被遗忘者已经在下方的地下墓穴中加固了他们的地下首都：幽暗城。",al={"洛丹伦废墟现状","谁控制洛丹伦废墟"}}},fp="24,250,21.276.0,24.357.0,40.125.0,30.153.0,33.158.0,55.192.0,38.114.0,51.211.0"}
P.entries["quest:92421"] = {n="Light's Justice",s="“Light's Justice”是由幽暗城的莫尔宾·光劫者发布的一项被遗忘者任务。冒险者受命肃清洛丹伦废墟上方残留的天灾军团，并收集完好的肢体，以修复和维持他们正在腐烂的被遗忘者同胞。",h="“Light's Justice”是由幽暗城的莫尔宾·光劫者发布的一项被遗忘者任务。冒险者受命肃清洛丹伦废墟上方残留的天灾军团，并收集完好的肢体，以修复和维持他们正在腐烂的被遗忘者同胞。",kw={"被遗忘者圣骑士","加瑞克·班达里安","完好的肢体","圣光的正义","莫尔宾·光劫者","洛丹伦废墟","天灾军团","幽暗城"},ang={["class:Paladin"]="莫尔宾·光劫者公开表明自己是被遗忘者的圣骑士，这表明在黑暗女王的统治下，即便是在亡灵状态下，对神圣战争和战斗职责的忠诚依然能够存续。",["faction:Horde"]="保卫幽暗城上方的洛丹伦废墟，既是保护部落在北方的重要首都，也是在巩固他们在东部王国的脆弱据点。",["race:Undead"]="被遗忘者的躯体无法自行再生腐烂的血肉，这使得从天灾残党身上收集肢体成为保持伤者和士兵完整的残酷必要手段。"},sec={{t="上方的天灾",b="在幽暗城的正上方，毫无理智的天灾残党依然在洛丹伦前首都废墟的地面街道上徘徊。尽管黑暗女王战胜了恐惧魔王并建立了被遗忘者王国，但清理地面依然是一项艰苦且代价高昂的工作。入侵的亡灵威胁着幽暗城的入口，并不断消耗着被派去收复这座沦陷王国的防御部队。"},{t="血肉与白骨",b="亡灵的躯体无法自然愈合；腐烂的组织和破碎的筋腱无法自行重连。为了维持战斗力，莫尔宾·光劫者指挥战士们从上方废墟中被摧毁的天灾军团身上获取完好的肢体。这些回收的部件提供了至关重要的移植和替换材料，让受伤的被遗忘者有机会坚持战斗。"},{t="一位队长的遗产",b="莫尔宾·光劫者执行这项严酷的职责是为了纪念他已故的长官，加瑞克·班达里安队长。铭记着班达里安治愈族人并将洛丹伦从天灾占领中解放出来的誓言，莫尔宾视毁灭那些毫无理智的敌人和修复族人的躯体为在希尔瓦娜斯女王治下正义的真正体现。"}},faq={{q="莫尔宾·光劫者是谁？",a="莫尔宾·光劫者是一位居住在幽暗城的被遗忘者圣骑士。他致力于执行希尔瓦娜斯女士的意志，在照料亡灵同胞身体存续的同时，也铭记着他阵亡的长官加瑞克·班达里安的使命与回忆。",al={"谁发布了圣光的正义任务","莫尔宾·光劫者是谁","任务发布者"}},{q="为什么需要完好的肢体？",a="被遗忘者的血肉会自然腐烂，无法自行愈合或重连。为了修复受损的躯体并保持日益减少的战斗力，被遗忘者必须从上方废墟中落败的亡灵身上搜集完好的肢体。",al={"为什么需要完好的肢体","被遗忘者为什么需要肢体","为什么要收集尸体部位"}},{q="加瑞克·班达里安队长是谁？",a="加瑞克·班达里安队长是一位受人尊敬的指挥官，他致力于肃清洛丹伦的天灾残党并治愈他的被遗忘者同胞。尽管他已经阵亡，但他的追随者们仍在铭记他的遗志并继续他的工作。",al={"加瑞克·班达里安队长是谁","加瑞克·班达里安背景故事","加瑞克·班达里安"}},{q="天灾军团位于何处？",a="这些肢体收集于洛丹伦废墟，即幽暗城正上方的地面城市，尽管被遗忘者一直在努力肃清，但仍有大量非受控的天灾入侵者在那里徘徊。",al={"天灾军团在哪里徘徊","在哪里寻找完好的肢体","洛丹伦废墟的天灾军团"}},{q="被遗忘者中有圣骑士吗？",a="莫尔宾·光劫者明确称自己为被遗忘者的圣骑士。虽然传统的人类圣骑士侍奉圣光，但莫尔宾将他的战斗虔诚倾注于侍奉希尔瓦娜斯·风行者和保护他的族人。",al={"被遗忘者可以是圣骑士吗","亡灵圣骑士背景故事","被遗忘者圣骑士"}},{q="“圣光的正义”对被遗忘者意味着什么？",a="这个标题援引了神圣报应的概念，并被莫尔宾·光劫者重新利用。对他而言，伸张正义意味着将毫无理智的天灾军团从洛丹伦的首都彻底清除，并将它们的残骸转化为被遗忘者的救赎。",al={"圣光的正义意味着什么","为什么叫圣光的正义","任务名称含义"}}},fp="15,199,17.319.0,14.274.0,18.294.0,24.194.0,28.192.0,32.168.0,37.178.0,38.151.0,53.135.0"}
P.entries["quest:92422"] = {n="The Wrath of Rath'mael",s="“The Wrath of Rath'mael”是布瑞尔的死亡卫士克里斯托夫发布的一项被遗忘者任务。冒险者们受命进入迷雾笼罩的洛丹伦废墟，消灭天灾军团的死灵法师Rath'mael，因为他正在幽暗城上方掩盖亡灵的行动。",h="“The Wrath of Rath'mael”是布瑞尔的死亡卫士克里斯托夫发布的一项被遗忘者任务。冒险者们受命进入迷雾笼罩的洛丹伦废墟，消灭天灾军团的死灵法师Rath'mael，因为他正在幽暗城上方掩盖亡灵的行动。",kw={"布瑞尔","死亡卫士克里斯托夫","洛丹米尔瞰台","拉斯梅尔","洛丹伦废墟","天灾军团死灵法师","拉斯梅尔之怒","提瑞斯法林地","邪恶迷雾"},ang={["faction:Horde"]="守卫洛丹伦的周边领土能保住部落在东部王国对抗无尽亡灵恐怖的立足点。",["race:Undead"]="被遗忘者占据着废弃首都下方的幽暗城，因此头顶庭院和墓地中任何天灾军团的涌动都对他们的家门口构成了直接威胁。"},sec={{t="废墟之上的阴影",b="来自洛丹米尔瞰台的侦察报告显示，一股邪恶势力已加强了对洛丹伦废墟的控制。浓重且邪恶的迷雾笼罩了废弃的街道和附近的墓地，掩盖了残留天灾军团的动向。这种超自然的屏障是Rath'mael的作品，作为一名升格的死灵法师，他的法术为亡灵爪牙提供了潜行和掩护，而这一切就发生在被遗忘者领地的核心上方。"},{t="提瑞斯法的防御",b="布瑞尔的死亡卫士克里斯托夫意识到被遗忘者绝不能任由这种威胁肆无忌惮地生根发芽，因此他指挥冒险者们召集盟友，击溃Rath'mael。虽然克里斯托夫知道天灾军团最终会派人接替这名术士，但除掉Rath'mael可以扰乱他们的协调行动，驱散魔法迷雾，并为提瑞斯法林地争取宝贵的喘息时间。"}},faq={{q="拉斯梅尔是谁？",a="拉斯梅尔是一名天灾军团的死灵法师，最近在潜伏于洛丹伦废墟的亡灵势力中声名鹊起。他利用黑暗巫术召唤出邪恶的迷雾，掩盖了洛丹米尔瞰台附近街道和墓地中天灾军团的行动。",al={"拉斯梅尔是谁","拉斯梅尔背景故事"}},{q="洛丹伦废墟中的邪恶迷雾是什么？",a="笼罩在废弃首都街道和墓地上空的超自然薄雾是由死灵法师拉斯梅尔召唤出的邪恶迷雾。它使该地区笼罩在阴暗之中，为残留的天灾军团提供了潜行，使其免受被遗忘者巡逻队的察觉。",al={"洛丹伦的迷雾是什么","为什么洛丹伦废墟有迷雾","废墟中的邪恶迷雾"}},{q="谁发布了这个任务？",a="死亡卫士克里斯托夫是一名驻扎在提瑞斯法林地布瑞尔镇的被遗忘者士兵。他负责监视通往首都废墟的道路，并发出紧急呼吁，要求勇士们在天灾军团的威胁变得无法控制之前消灭拉斯梅尔。",al={"谁发布了拉斯梅尔之怒","死亡卫士克里斯托夫在哪里","布瑞尔的克里斯托夫"}},{q="拉斯梅尔在哪里？",a="拉斯梅尔在洛丹伦废墟深处活动，特别是在街道、墓地以及俯瞰湖泊的洛丹米尔瞰台附近。",al={"在哪里可以找到拉斯梅尔","哪里可以找到拉斯梅尔","拉斯梅尔位置"}},{q="为什么被遗忘者要消灭拉斯梅尔？",a="被遗忘者绝不能允许天灾军团在幽暗城上方集结兵力或隐蔽位置。拉斯梅尔的死灵迷雾对被遗忘者的防线以及整个提瑞斯法地区的旅行者安全构成了直接的战术威胁。",al={"为什么要杀死拉斯梅尔","为什么要与拉斯梅尔战斗"}},{q="杀死拉斯梅尔能永久保卫废墟吗？",a="不能。正如死亡卫士克里斯托夫所观察到的，天灾军团迟早会用另一名黑暗施法者来替换掉落的副官。击杀拉斯梅尔只是削弱了他们当前的势头，减少了他们的数量，并暂时驱散了遮蔽视线的迷雾。",al={"杀死拉斯梅尔能终结天灾军团吗","杀死拉斯梅尔后天灾军团会消失吗"}}},fp="22,220,23.287.0,23.277.0,17.218.0,49.148.0,24.213.0,27.122.0,45.173.0,52.178.0"}
P.entries["quest:92432"] = {n="An Alarming Request",s="南海镇的使者雅克带来了达拉然的坏消息：城市中的地脉发生了偏移，导致城市的构造体变得异常且具有破坏性。大法师莫德拉派雅克寻找外界援助，你被要求在洛丹米尔湖畔的达拉然附近寻找她的影像。",h="南海镇的使者雅克带来了达拉然的坏消息：城市中的地脉发生了偏移，导致城市的构造体变得异常且具有破坏性。大法师莫德拉派雅克寻找外界援助，你被要求在洛丹米尔湖畔的达拉然附近寻找她的影像。",kw={"奥特兰克","构造体","达拉然","雅克","地脉","洛丹米尔","莫德拉","南海镇"},sec={{t="达拉然的麻烦",b="使者雅克说达拉然的地脉受到了干扰，城市的构造体现在的行为变得异常且具有破坏性。起因尚不清楚。高等议会下令对此事保密，以免给组织蒙羞，但雅克说这种伪装无法长久维持，因为城市正处于被占领的边缘。大法师莫德拉派雅克寻找外界援助，你需要去洛丹米尔湖畔的达拉然附近寻找她的影像。"},{t="莫德拉的欢迎",b="在她的影像处，莫德拉指出雅克成功找到了援助。虽然这严格来说是不被允许的，但她认为在城市处于绝望时刻时，不应让自尊心阻挡盟友。她警告说，无论卫兵们想让你相信什么，事实是局势完全失控了。"}},faq={{q="使者雅克是谁？",a="雅克是达拉然驻南海镇的使者，受大法师莫德拉之命前来寻求外界援助。",al={"使者雅克","雅克是谁","谁发布了惊人的请求"}},{q="达拉然发生了什么事？",a="城市的地脉受到了干扰，构造体现在的行为变得异常且具有破坏性。起因尚不清楚，且城市正面临被占领的危机。",al={"达拉然出了什么问题","达拉然的问题","构造体为何攻击达拉然"}},{q="为什么这件事要保密？",a="高等议会下令对此事保密，以免给组织蒙羞。",al={"达拉然为何保密","为何隐藏构造体的问题","达拉然高等议会的秘密"}},{q="大法师莫德拉的影像在哪里？",a="在洛丹米尔湖畔，达拉然附近。",al={"在哪里找到莫德拉","莫德拉的位置","大法师莫德拉的影像"}}},fp="19,262,18.421.0,16.232.1,24.96.0,29.143.0,37.75.0,46.78.0"}
P.entries["quest:92434"] = {n="Blood in the Streets",s="达拉然的结界已经消失，整座城市陷入了一片混乱。既然巡逻队已经被清理干净，大法师沃迪恩·伍德格莱尔认为现在正是潜入城内窃取法师们秘密的最佳时机。你需要带着从拘留营地获得的钥匙前往城市北缘的下水道。",h="达拉然的结界已经消失，整座城市陷入了一片混乱。既然巡逻队已经被清理干净，大法师沃迪恩·伍德格莱尔认为现在正是潜入城内窃取法师们秘密的最佳时机。你需要带着从拘留营地获得的钥匙前往城市北缘的下水道。",kw={"奥特兰克","血染街头","达拉然","污浊的钥匙","洛丹米尔湖","莫德拉","下水道","沃迪恩·伍德格莱尔"},sec={{t="令人不快的入口",b="在解决了达拉然的巡逻队后，大法师沃迪恩·伍德格莱尔表示，导致达拉然结界消失的原因让整座城市陷入了混乱，现在正是部落潜入其中并探寻法师们秘密的好机会。你需要拿着从拘留营地获得的钥匙，前往洛丹米尔湖畔，寻找城市北缘的下水道入口。运气好的话，那些法师或许没觉得有必要在这条令人不快的入口处设下防备。"},{t="钥匙的用途",b="大法师莫德拉的幻象让你收起武器。她说仅凭这把钥匙还不足以通过她的结界，因为法师们绝不会在如此危急的时刻留下这种弱点。她表示部落对她城市的兴趣绝非巧合，一切都在她的预料之中，而且她有一个提议想和你谈谈。"}},faq={{q="是谁派你进入达拉然下水道的？",a="在巡逻队被解决后，是大法师沃迪恩·伍德格莱尔派我去的。",al={"血染街头 任务发布者","谁发布 血染街头 任务","沃迪恩·伍德格莱尔任务"}},{q="达拉然的入口在哪里？",a="沃迪恩指引我前往位于城市北缘、洛丹米尔湖畔的下水道。",al={"达拉然下水道在哪里","洛丹米尔湖下水道入口","如何进入达拉然"}},{q="用什么钥匙尝试进入？",a="从拘留营地获得的污浊的钥匙。",al={"达拉然污浊的钥匙","钥匙是从哪里来的","拘留营地钥匙"}},{q="为什么达拉然现在防御薄弱？",a="因为它的结界已经消失，整座城市陷入了一片混乱。",al={"为什么达拉然结界会消失","达拉然护盾发生了什么"}}},fp="20,259,21.345.0,21.270.1,36.89.0,43.61.0,34.49.0,36.60.0"}
P.entries["quest:92456"] = {n="A Green Sample",s="“A Green Sample”是由暴风城的莎拉米尔发布的一项差事，旨在引导冒险者潜入与世隔绝的魔法城市达拉然。本来期待着从中央花园获取一份纯净的法力植物样本，但这次探险却揭开了肯瑞托植物群中意想不到的邪能腐化。",h="“A Green Sample”是由暴风城的莎拉米尔发布的一项差事，旨在引导冒险者潜入与世隔绝的魔法城市达拉然。本来期待着从中央花园获取一份纯净的法力植物样本，但这次探险却揭开了肯瑞托植物群中意想不到的邪能腐化。",kw={"绿色样本","植物学","中央花园","达拉然","注入邪能的花朵","肯瑞托","莎拉米尔","暴风城"},ang={["class:Mage"]="肯瑞托封闭的魔法实验和达拉然的植物学长期以来一直引起学者的兴趣，尽管意想不到的腐化暗示着这个法师聚集地内部隐藏着麻烦。",["class:Rogue"]="莎拉米尔专门招募了一位擅长在不受欢迎的地方潜行的人，以溜过肯瑞托的防御体系。",["profession:Herbalism"]="从达拉然的中央花园采集奇异植物，揭示了某种不自然的力量正在将普通的植被腐化成注入邪能的花朵。"},sec={{t="前往达拉然的差事",b="在暴风城，神秘的莎拉米尔正在寻找一位敢于冒险的旅行者，愿意去完成一项进入禁区的秘密差事。出于对肯瑞托不同寻常的植物学研究的兴趣，莎拉米尔想要达拉然中央花园中培育的一株带有法力能量的植物活体样本。由于这些封闭的法师们拒绝外人进入，获取这种植物需要有人擅长潜入那些未经许可的地方。"},{t="受污染的根系",b="潜入这个法师之城的中央花园后，发现了一个令人震惊的事实：这些植物不仅吸收了纯粹的奥术能量，而且已经变异成了“注入邪能的花朵”。当这份受污染的样本被呈交时，莎拉米尔感到措手不及，他意识到秘密的肯瑞托正面临着比表面看起来更深层的动荡。尽管如此，这种意想不到的邪能腐化比普通的奥术草药更令他着迷。"}},faq={{q="谁发布了“绿色样本”这个任务？",a="该任务由暴风城的莎拉米尔发布，他正在寻找一位敢于潜入达拉然并收集植物样本的外来者。",al={"谁发布绿色样本","绿色样本任务发布者","莎拉米尔位置"}},{q="莎拉米尔让你取回什么？",a="莎拉米尔委托玩家设法进入达拉然，取回城市中央花园生长的植物，他期待的是一份充满法力能量的植物样本。",al={"莎拉米尔想要什么","绿色样本目标","绿色样本物品"}},{q="在哪里可以找到所要求的样本？",a="该样本来自达拉然的中央花园，这座封闭的法师之城严格防范着外部势力的入侵。",al={"中央花园在哪里","如何获得注入邪能的花朵","达拉然花园位置"}},{q="为什么花朵是注入邪能的而不是充满法力的？",a="你发现的不是健康的法力植物，而是“注入邪能的花朵”。收到样本后，莎拉米尔意识到肯瑞托正在应对远比预期更黑暗、更动荡的力量。",al={"为什么有邪能","达拉然有邪能腐化吗","达拉然植物邪能"}},{q="为什么莎拉米尔对达拉然的植物感兴趣？",a="莎拉米尔指出，尽管达拉然是一个法师之城，但它对植物学有着令人惊讶的兴趣，他试图研究肯瑞托是如何培育这些充满法力植物的。",al={"为什么莎拉米尔想要达拉然的植物","达拉然植物学原因"}},{q="莎拉米尔对交回的花朵有什么反应？",a="虽然对样本被邪能而非奥术法力污染感到震惊，但莎拉米尔对这一发现感到好奇，并称赞了冒险者完成了这项危险的差事。",al={"莎拉米尔的反应","绿色样本交任务"}}},fp="14,172,20.359.0,13.353.1,35.89.0,40.106.0,36.127.0,55.186.0,47.129.0,54.129.0"}
P.entries["quest:92457"] = {n="Starving Arcane",s="大法师莫德拉请你清除达拉然城中的失控元素。裂隙扰乱了城中的附魔与防御，肯瑞托需要腾出空间来维护结界。",h="大法师莫德拉请你清除达拉然城中的失控元素。裂隙扰乱了城中的附魔与防御，肯瑞托需要腾出空间来维护结界。",kw={"奥术能量","大法师莫德拉","裂隙","达拉然","元素","肯瑞托","法力回响","饱和残迹者","寻觅残迹者","奥术饥渴"},sec={{t="奥术碎片",b="裂隙扰乱了达拉然各处的魔像与附魔，包括与城市防御相关的设施。破碎的奥术能量引来了寻觅残迹者、饱和残迹者和法力回响，它们试图吸收这些自由流动的魔法。大法师莫德拉请你减少它们的数量，同时肯瑞托维护结界并处理其他突发事件。"}},faq={{q="元素为何聚集在达拉然？",a="裂隙逸散的破碎奥术能量引来了失控元素，它们试图吸收这些自由流动的魔法。",al={"元素为何在此","达拉然元素","奥术元素"}},{q="是谁让我清除元素？",a="身在达拉然城外的大法师莫德拉请你减少城中元素的数量。",al={"任务发布者","莫德拉的任务","大法师莫德拉"}},{q="裂隙影响了什么？",a="裂隙影响了达拉然各处的魔像与附魔，其中一些与城市防御有关。",al={"裂隙破坏","什么受损","达拉然结界"}},{q="涉及哪些元素？",a="这些元素包括寻觅残迹者、饱和残迹者和法力回响。",al={"哪些残迹者","元素类型","要清除什么"}}},fp="15,185,16.377.0,40.123.0,36.88.0,27.111.0,30.83.0"}
P.entries["quest:92458"] = {n="Heart of Disruption",s="大法师莫德拉的影像请求你协助控制达拉然的奥术异变。紫罗兰城堡的结界正承受着巨大压力，肯瑞托需要时间控制危机。",h="大法师莫德拉的影像请求你协助控制达拉然的奥术异变。紫罗兰城堡的结界正承受着巨大压力，肯瑞托需要时间控制危机。",kw={"奥术微粒","大法师莫德拉","达拉然","heart of disruption","肯瑞托","ley线","紫罗兰城堡","结界"},sec={{t="寻路入城",b="大法师莫德拉的影像说，异变始于紫罗兰城堡顶层，起居室里传来一声雷鸣般的巨响。肆虐的奥术力量如今威胁着结界，而肯瑞托成员正忙于城堡内部。你得到一把钥匙，并受托寻找一条不那么引人注目的入城路线，以免异变恶化。"},{t="奥术微粒",b="莫德拉请你收集一枚奥术微粒。她没有问你在城堡里看到了什么；她只关心控制微粒并平息异变。结界仍在支撑，肯瑞托现在必须接手这项工作。"}},faq={{q="谁在求助？",a="大法师莫德拉的影像请求你协助处理达拉然的奥术异变。",al={"谁需要帮助","莫德拉求助","谁给了这个"}},{q="异变是怎么造成的？",a="起居室上方传来一声雷鸣般的巨响后，异变便始于紫罗兰城堡顶层。",al={"城堡里发生了什么","结界为何承压","奥术异变"}},{q="结界为何陷入危险？",a="肆虐的奥术力量席卷了城堡，肯瑞托正竭力维持结界。",al={"结界出了什么问题","达拉然为何被席卷","肆虐的奥术力量"}},{q="莫德拉让我收集什么？",a="莫德拉请你收集一枚奥术微粒。",al={"我要收集什么","奥术微粒","微粒任务"}},{q="我为什么需要钥匙？",a="莫德拉给你一把钥匙，让你能以不那么引人注目的方式进入城市。",al={"钥匙有什么用","如何入城","城堡钥匙"}},{q="我带回微粒后会怎样？",a="莫德拉说，肯瑞托必须控制微粒并平息异变。",al={"莫德拉会怎么处理它","微粒后续","接下来会发生什么"}}},fp="19,196,12.328.0,8.213.0,23.84.0,27.111.0,28.106.0,35.42.0,20.83.0,41.71.0"}
P.entries["quest:92459"] = {n="Friend of the Kirin Tor",s="大法师茉德拉的幻象承认，议会肯定不喜欢听到有关这种诡计的消息，但也无法反驳其成果：达拉然正在趋于平静，防护结界可以撤销了。她给了你一个奥术微粒，让你带给紫罗兰城堡的大法师塞琳卓。",h="大法师茉德拉的幻象承认，议会肯定不喜欢听到有关这种诡计的消息，但也无法反驳其成果：达拉然正在趋于平静，防护结界可以撤销了。她给了你一个奥术微粒，让你带给紫罗兰城堡的大法师塞琳卓。",kw={"奥特兰克","奥术微粒","塞琳卓","达拉然","肯瑞托","茉德拉","紫罗兰城堡","防护结界"},sec={{t="好消息",b="大法师茉德拉的幻象承认，议会肯定不喜欢听到有关这种诡计的消息，但也无法反驳其成果。城市正在趋于平静，防护结界现在可以撤销了。她认为你应该负责传递这个好消息，并给了你一个奥术微粒，让你带给达拉然紫罗兰城堡里的大法师塞琳卓。"}},faq={{q="是谁派你去找大法师塞琳卓的？",a="大法师茉德拉的幻象，她让你去传递关于达拉然的好消息。",al={"谁发布肯瑞托之友","肯瑞托之友任务发布者","茉德拉任务"}},{q="大法师塞琳卓在哪里？",a="在达拉然城的紫罗兰城堡里。",al={"肯瑞托之友任务去哪里交","塞琳卓是谁","大法师塞琳卓位置"}},{q="你要带什么物品去紫罗兰城堡？",a="一个奥术微粒，是茉德拉给你的，让你带给大法师塞琳卓。",al={"肯瑞托之友任务物品","奥术微粒是什么"}},{q="什么是好消息？",a="达拉然正在趋于平静，其防护结界可以撤销了。",al={"茉德拉传达了什么消息","为什么要撤销防护结界"}}},fp="23,96,13.279.0,35.79.0,27.67.0,45.64.0,22.49.0"}
P.entries["quest:92460"] = {n="Coming of Age",s="Coming of Age是年轻的天裔踏出森达尔村并开启人生第一步的成人礼。在新兵导师Ailee Farheart的指引下，他们将向村长Rorian the Dayseeker报到，领取一件先祖遗物，并正式宣誓效忠于shen'dorei。",h="Coming of Age是年轻的天裔踏出森达尔村并开启人生第一步的成人礼。在新兵导师Ailee Farheart的指引下，他们将向村长Rorian the...",kw={"艾莉·远心","成年礼","寻日者罗里安","申多雷","天裔","森达尔林地","森达尔村","泽风岛"},ang={["race:Skyborne"]="这场成人礼定义了你迈向成年的时刻，并赋予你一件无论风吹向何处都将随身携带的神圣家族传家宝。"},sec={{t="成人礼",b="对于每一位步入成年的年轻天裔来说，旅程都始于森达尔村。在Ailee Farheart的指引下，雏鹰们向西前往巨父之树，村长正在那里等待着他们。对于shen'dorei而言，成年不仅是一个社会里程碑，更是一项在动荡局势中服务族群的仪式性承诺。"},{t="先祖遗物",b="在巨父之树的入口处，Rorian the Dayseeker主持了仪式。他正式将一件先祖遗物授予新兵——这是一件在shen'dorei世代相传的传家宝。这件遗物由无数先辈佩戴，是故乡之风的永恒象征，注定要等到持有者的骨灰随风飘散时，才会回归族人手中。"}},faq={{q="成人礼仪式的目的是什么？",a="它标志着年轻天裔正式迈入成年，象征着他们正式加入申多雷的现役序列，并获赠一件先祖传家宝。",al={"为什么要举行成人礼","成人礼的目的","天裔成人礼"}},{q="谁发起了这个任务？",a="在泽风岛森达尔村照看新兵的艾莉·远心会欢迎你，并指引你前往会见村庄的首领。",al={"谁发布成人礼任务","成人礼从哪里开始","艾莉·远心的位置"}},{q="仪式需要向谁报到？",a="逐日者罗里安，森达尔村的村长，他站在定居点以西的巨父之树入口处。",al={"罗瑞安是谁","罗瑞安在哪里","逐日者罗瑞安的位置"}},{q="仪式上会授予什么遗物？",a="罗里安会赠予一件传承至今的成人礼遗物，在你之前已有几代申多雷佩戴过它。传统规定它将伴随你终生，直到你去世后传给下一代。",al={"什么是遗物","天裔遗物","你获得了什么"}},{q="在此语境下“申多雷”是什么意思？",a="罗里安用“申多雷”来指代天裔，唤起他们复杂的历史、共同的考验以及在泽风岛上延续至今的身份认同。",al={"谁是申多雷","申多雷的含义","天裔与申多雷"}},{q="仪式结束后你的旅程将去往何处？",a="完成成人礼后，罗里安会让你关注威胁岛屿的地方事务，并从平衡中的和谐和虫害调查等任务开始。",al={"接下来是什么任务","成人礼之后的后续步骤","罗瑞安之后做什么"}}},fx={["39b489c8"]={q="艾莉·远心为什么派你去找罗瑞安？",a="艾莉·远心认为你已经准备好在族人中承担自己的责任。作为一名即将成年的年轻辛多雷，这一生只有一次这样的成人礼。森达尔村一直热切期待你的到来，也需要你的帮助；但在你开始肩负社区责任之前，依照传统必须先去见村长罗瑞安·寻日者，完成成年礼。",al={"艾莉为什么要这么做","艾莉·远心的动机","为什么派我去找罗瑞安"}}},fp="13,238,17.279.0,19.293.0,50.145.0,24.109.0,36.123.0,43.160.0,44.137.0,52.152.0"}
P.entries["quest:92461"] = {n="Harmony in Balance",s="Harmony in Balance是Rorian the Dayseeker在泽风岛给予初出茅庐的冒险者们的一项早期职责仪式。该任务要求玩家在森达尔林地捕杀幼年vuldren，以维护岛上的自然平衡。通过这一琐碎的必要工作，新手们能够了解到当地野兽对于周围波动的魔法流是多么敏感。",h="Harmony in Balance是Rorian the...",kw={"平衡中的和谐","幼年沃尔德伦","寻日者罗里安","森达尔林地","沃尔德伦","泽风岛"},ang={["class:Druid"]="捕杀数量过多的vuldren的命令与德鲁伊哲学产生了强烈的共鸣，在这种哲学中，有时为了维护整个生态系统的健康，必须进行捕杀。",["class:Hunter"]="管理兽群数量并观察原生野兽如何应对环境干扰，是任何森达尔林地追踪者的基础训练。"},sec={{t="照料林地",b="即便是在一个充满不确定未来和日益增长的危险的时代，泽风岛上的日常生存仍需要谦卑与勤勉。在森达尔林地，当地的vuldren种群数量增长过快，已经威胁到了维持岛上野生动物生存的微妙环境平衡。Rorian the Dayseeker将减少它们数量这一严峻任务分配给了年轻的守护者们，以避免大范围的生态压力。"},{t="不安之风",b="虽然捕杀野生动物看起来像是普通的狩猎管理，但vuldren数量激增反映出了更深层次的问题。尽管通常是温顺的生物，但泽风岛的野生动物与岛上的大气环境息息相关，当随风飘荡的魔法失去平衡时，它们会产生剧烈的反应。尽早纠正这种失衡可以防止这些温顺的生物退化为不可预测且危险的害兽。"}},faq={{q="为什么要捕杀沃尔德伦？",a="森达尔林地的沃尔德伦种群数量已经激增到了不可持续的程度。如果不加控制，它们可能会耗尽当地资源，并破坏维持林地其他居民生存的微妙生态平衡。",al={"为什么杀沃尔德伦","沃尔德伦数量过多","森达尔林地沃尔德伦"}},{q="逐日者罗里安是谁？",a="逐日者罗里安是泽风岛上的一位年长向导和导师。他负责监督年轻冒险者的训练，并提醒他们，保护家园需要同时关注重大的危机和日常的生态维护。",al={"罗瑞安背景故事","罗里安是谁"}},{q="是什么导致了沃尔德伦的行为异常？",a="沃尔德伦通常是温顺的生物，但泽风岛上的原生动物能够感知到编织在岛屿之风中的环境魔法何时失去了平衡，从而导致行为上的突然转变。",al={"为什么沃德伦具有攻击性","沃德伦行为"}},{q="这项任务发生在哪里？",a="该任务在森达尔林地进行，这是一个位于泽风岛定居点东部和东南部一带的区域。",al={"森达尔林地位置","森达尔林地在哪里"}},{q="罗里安想要传授什么样的教训？",a="罗里安教导说，保护自己的家园往往需要采取困难且令人不快的措施。对于任何新兴的守护者来说，采取坚定的引导手段来恢复自然秩序是一项必不可少的责任。",al={"罗里安的教诲","平衡中的和谐的含义"}},{q="在狩猎沃尔德伦时应该做些什么？",a="附近的艾拉特雷尔·轻羽要求冒险者调查一群讨厌的卷云蝇，因此顺便去调查林地里的虫害是非常实用的。",al={"附近的其他任务","虫害调查"}}},fx={["240c10a3"]={q="你要猎杀的幼年vулдрен是什么？",a="幼年vулдрен是栖息在森达尔林地的本土生物。它们通常温顺，是当地生态系统的重要组成部分，但数量已激增至难以维持的程度。此外，当地野生生物开始感受到泽弗拉斯的风中所携带的魔法出现扰动，若不加控制，它们的行为就会变得难以预测。",al={"vулдрен是什么","幼年vулдрен","我们要猎杀什么"}},b29e78f0={q="罗瑞安为什么派你去，而不亲自处理数量问题？",a="你刚刚完成成年礼，眼下正要接受考验，学习维护泽弗拉斯的实际职责。罗瑞安认为，处理森达尔林地日常事务是应尽的责任，也是重要的一课：即使面临巨大的不确定性，要保护家园、维持和谐，也需要有人引领。",al={"为什么派我去","罗里安为什么需要我","为什么是我"}}},fp="18,218,17.292.0,15.277.0,37.198.0,28.195.0,30.163.0,32.99.0,38.150.0,46.153.0"}
P.entries["quest:92462"] = {n="Infestation Investigation",s="Infestation Investigation是给予初次踏入森达尔林地上的泽风岛的年轻冒险者的早期任务。游侠Elatrell Featherlight下令扑杀开始在东部林地成群结队的讨厌的卷云飞虫。如果放任不管，这些繁殖迅速的昆虫将威胁到宁静的林地，并危及当地的定居点。",h="Infestation Investigation是给予初次踏入森达尔林地上的泽风岛的年轻冒险者的早期任务。游侠Elatrell...",kw={"卷云飞虫","艾拉崔尔·轻羽","虫害","调查","恼人的卷云飞虫","森达尔林地","泽风"},ang={["class:Druid"]="保护森达尔林地意味着在具有攻击性的虫群将林地剥蚀殆尽之前，先处理好自然的不平衡。",["class:Hunter"]="对于初露头角的射手和追踪者来说，在树木间追踪小巧、飞速移动的卷云飞虫，能为在茂密掩体中锁定快速移动的目标提供宝贵的练习机会。"},sec={{t="树冠中的虫群",b="森达尔林地长期以来保持着微妙的平衡，但当地游侠的最新报告显示，在树林的东边缘，恼人的卷云飞虫数量突然激增。虽然单个的卷云飞虫只是小害虫，但一旦数量膨胀，它们的虫群会迅速变得具有攻击性和破坏性。游侠Elatrell Featherlight毫不拖延地派遣有能力的年轻人去扑杀这些飞虫，以免它们的出现彻底压垮这片林地。"},{t="服役的早期阶段",b="在完成最初的Coming of Age后，年轻的守卫者们被直接投入到维护泽风岛的实际工作中。清理害虫看起来可能像是琐碎的工作，但保护林地免受野生动物爆发的侵扰，对于保障附近定居点的安全至关重要。归来的猎人身上沾满了大量的内脏和昆虫，这证明虫群的规模远比最初担心的要严重得多。"}},faq={{q="什么是卷云飞虫？",a="卷云飞虫是泽风岛茂密环境中原产的带翅昆虫害虫。虽然它们个体很小，但繁殖迅速，如果像在森达尔林地这样的地方放任其数量不管，很快就会形成危险的虫群。",al={"卷云飞虫","什么是卷云飞虫"}},{q="谁发布了虫害调查任务？",a="该任务由驻扎在森达尔林地的游侠艾拉特蕾尔·轻羽指派，她的职责是控制当地的野生动物和周围的树林。",al={"任务发布者","谁开启此任务","艾拉特雷尔·轻羽"}},{q="卷云飞虫位于哪里？",a="恼人的卷云飞虫聚集在泽风岛上森达尔林地的东部和东南部区域，在树叶间嗡嗡作响，并伴有年幼的沃德伦兽。",al={"去哪里找飞虫","卷云飞虫位置","森达尔林地的飞虫"}},{q="为什么要扑杀卷云飞虫？",a="虽然单只昆虫构成的危险很小，但卷云飞虫群很快就会变得密集，足以威胁到旅行者，消耗当地的植物，并扰乱森达尔林地的宁静平衡。",al={"为什么要杀飞虫","为什么要扑杀卷云飞虫","卷云飞虫威胁"}},{q="虫害调查之后是什么任务？",a="在清理完虫群并向艾拉特蕾尔·轻羽报告后，冒险者们会被指引前往虫害的中心，去面对卷云飞虫女王。",al={"下一个任务","接下来做什么","调查后续"}},{q="这个任务在泽风岛的早期旅程中处于什么位置？",a="该任务在完成成年礼试炼后立即提供，作为给予泽风岛新晋守卫者的首批战斗任务之一。",al={"任务链","我何时能接到此任务","等级要求"}}},fp="25,174,21.260.0,22.240.0,20.168.0,46.138.0,34.144.0,41.155.0,43.139.1,60.147.0"}
P.entries["quest:92463"] = {n="The Cirrusfly Queen",s="The Cirrusfly Queen 是一项针对居住在泽风岛森达尔林地中具有攻击性的昆虫巢穴女王的狩猎任务。在对虫害进行初步侦察后，Elatrell Featherlight 指引新兵深入林地中心，以消灭女王并从源头上铲除虫群。终结她的统治能为当地致力于维护荒野安全的游侠们提供即时的缓解。",h="The Cirrusfly Queen 是一项针对居住在泽风岛森达尔林地中具有攻击性的昆虫巢穴女王的狩猎任务。在对虫害进行初步侦察后，Elatrell Featherlight...",kw={"卷云蝇","艾拉崔尔·轻羽","巢穴","女王","兵虫","森达尔林地","泽风"},ang={["class:Hunter"]="击败具有攻击性的巢穴女王并战胜她身边的防卫兵虫，是追踪和野兽清理方面的早期考验，这会赢得当地游侠的直接赞扬。",["race:Skyborne"]="清除森达尔林地中的入侵虫群有助于维护自然平衡，并确保穿越你的家园泽风岛的旅行路线安全。"},sec={{t="突袭巢穴",b="对付 cirrusflies 的初步努力表明，仅仅消灭零散的工虫永远无法遏制在森达尔林地蔓延的虫害。Elatrell Featherlight 委派有能力的游荡者深入林地的东南部，那里正是主巢穴所在之处。在那里，女王在更强壮的兵虫的严密保护下指挥着整个群体。"},{t="游侠的重担",b="虽然普通的 cirrusflies 从远处看可能只是微不足道的小害虫，但它们中体型较大的种类对任何经过泽风岛树荫下的人来说都构成了严重的物理威胁。通过猎杀女王并抵御她的护卫，新手们证明了自己的战斗能力，并赢得了 Featherlight 的游侠团队的高度赞扬和点头致意。"}},faq={{q="卷云飞虫女王 位于何处？",a="卷云飞虫女王 将巢穴筑在泽风岛森达尔林地的东南角，靠近昆虫巢穴的中心。",al={"女王位置","卷云蝇女王在哪","找到女王"}},{q="为什么仅仅消灭工虫是不够的？",a="艾拉特蕾尔·轻羽 意识到，针对游荡的工虫只能削弱虫群的边缘。只要女王活着，她就会继续繁殖具有攻击性的兵虫并补充巢穴，从而维持对森达尔林地的威胁。",al={"为什么要杀掉女王","剿灭虫巢"}},{q="谁发布了猎杀 卷云飞虫女王 的任务？",a="一旦来自森林的初步报告确认了 卷云飞虫 虫害的严重性，艾拉特蕾尔·轻羽 就会提供这项任务。",al={"谁发布的任务","任务发布者女王"}},{q="为什么女王比普通的 卷云飞虫 更危险？",a="与在林地中游荡的基本工虫不同，女王周围环绕着体型更大、更具攻击性的兵虫，它们致力于保卫她的巢穴。",al={"女王的危险性","卷云蝇兵虫"}},{q="哪项任务在此任务之前？",a="此任务直接承接 虫害调查 任务，该任务首次确认了昆虫在林地中的蔓延程度。",al={"前置任务","在此之前的任务"}},{q="艾拉特蕾尔·轻羽 在该地区担任什么角色？",a="艾拉特蕾尔·轻羽 负责监管泽风岛的荒野安全，监控区域性威胁，并指导新的冒险者学习林地追踪和游侠职责。",al={"轻羽的角色","谁是轻羽"}}},fx={["4d5b02bf"]={q="卷云蝇女王是什么？",a="卷云蝇女王是席卷森达尔林地的虫害核心处的首领。她潜伏在林地深处、主巢穴附近，指挥虫群，并依靠凶猛的士兵蝇守卫自己。杀死普通工蝇永远无法阻止这些昆虫繁衍，只有击倒女王才能解除蜂巢对森林的侵扰。",al={"卷云蝇女王是谁","卷云蝇女王是什么","卷云蝇女王目标"}}},fp="19,184,17.272.0,17.271.0,37.121.0,43.176.0,44.139.0,61.75.0,36.117.0,55.166.0"}
P.entries["quest:92464"] = {n="Elemental Unrest",s="Elemental Unrest 是 Rorian the Dayseeker 在泽风岛上发布的入门任务。随着岛上那些有知觉的元素恩主离去，森达尔立石附近的次级风之精魂变得狂躁且不可预测。你需要前往森达尔林地找到 Rorian 的学徒 Yala Windwatcher，并找出是什么搅乱了当地的微风。",h="Elemental Unrest 是 Rorian the Dayseeker 在泽风岛上发布的入门任务。随着岛上那些有知觉的元素恩主离去，森达尔立石附近的次级风之精魂变得狂躁且不可预测。你需要前往森达尔林地找到...",kw={"元素动荡","寻日者罗里安","森达尔林地","森达尔立石","风之妖精","雅拉·捕风者","泽风岛"},ang={["class:Shaman"]="泽风岛的风之精魂如同镜子一般映射着岛上的情绪气候，使得这次扰动成为更深层环境破坏的明确预警信号。",["race:Skyborne"]="元素恩主的离去使风向变得难以预测，这要求那些依赖泽风岛天空的人们必须保持警惕。"},sec={{t="风向转变",b="世世代代以来，泽风岛的人民一直与强大且有知觉的风之精魂共同生活，这些精魂指引并保护着他们。随着那些元素恩主的离去，岛屿陷入了持续的不平衡之中。空气不再由仁慈的意识所照料，只留下了简单的风之妖精，它们映射着大地上残留的动荡情绪与力量。"},{t="森达尔立石",b="在 Rorian 驻地东北方，靠近古老的森达尔立石处，空气变得极其敌对。因为这些次级表现形式缺乏真正的自我意识，它们的动荡并非源于恶意，而是出于反应。Rorian 派他的学徒 Yala Windwatcher 在林地边缘监视它们古怪的行为，并推断是什么无形的紧张局势在困扰着它们。"}},faq={{q="风之妖精为什么会狂躁不安？",a="与岛上曾经的元素恩主不同，这些风之妖精缺乏真正的自我意识。它们本能地映射出周围生物与事件的情绪、意图和环境魔法力量，每当当地环境失去平衡时，它们就会变得动荡不安。",al={"为什么元素会狂躁","风之扰动的原因","妖精愤怒"}},{q="罗瑞安 提到的元素恩主是谁？",a="它们是曾经与泽风岛居民共存的有知觉的仁慈风之精魂。自它们离去后，岛屿失去了它们的稳定影响，一直处于持续的动荡之中。",al={"元素恩主","谁离开了泽风岛","泽风岛的风之精魂"}},{q="我在哪里可以找到 亚拉·捕风者？",a="亚拉·捕风者 驻扎在东北方的森达尔林地，俯瞰着狂躁的风之妖精聚集的森达尔立石。",al={"雅拉·捕风者 的位置","雅拉 在哪里","森达尔林地学徒"}},{q="寻日者罗瑞安 是谁？",a="寻日者罗瑞安 是泽风岛上的一位年长向导，他守护着岛屿的精神平衡，并研究着当地元素之间持续的扰动。",al={"罗里安 是谁","逐日者罗里安"}},{q="找到 亚拉 之后会发生什么？",a="与 亚拉 对话将直接引向对立石处动荡背后真正原因的调查，从任务“煽动者”开始。",al={"下一个任务","元素骚动 之后是什么","雅拉 后续任务"}},{q="风之妖精危险吗？",a="虽然它们本质上很简单，但狂躁的状态使它们变得古怪且具有防御性。只要根本的扰动持续存在，它们就会对入侵者做出攻击性反应。",al={"妖精是否具有敌意","元素危险"}}},fx={["8058eaf6"]={q="罗瑞安·寻日者为什么想让你这么做？",a="自从元素恩主离去后，这片区域便接连陷入危机。如今，森达尔立石周围的风之化身显得焦躁不安。由于这些低等小精灵只会映照附近生物动荡的情绪和意图，罗瑞安担心究竟是什么令它们如此不安。他派学徒雅拉前去观察情况，需要你去找她商议，以便他们查明骚乱的根源。",al={"罗里安的动机","为什么派去找雅拉","罗里安为什么要这么做"}}},fp="16,271,20.339.0,27.338.0,34.226.0,50.210.0,34.134.0,28.155.0,32.126.0,31.148.0"}
P.entries["quest:92465"] = {n="Agitators",s="“煽动者”是泽风岛上由Yala Windwatcher发布的一项早期任务。激进的奥拉凯斯邪教徒已经侵入森达尔林地，将原本和平的本土风之精灵煽动成了充满敌意的元素生物。冒险者们受命驱散翻腾的风元素，并清除威胁该地区的邪教皈依者。",h="“煽动者”是泽风岛上由Yala...",kw={"煽动者","奥拉凯斯","奥拉凯斯皈依者","翻腾的风元素","申多雷","森达尔林地","雅拉·捕风者","泽风岛"},ang={["class:Druid"]="不法邪教徒对森达尔林地自然和谐的亵渎，使得保护其本土精灵成为了一项紧迫的任务。",["class:Shaman"]="目睹自然风之精灵因邪教徒的干预而陷入暴力疯狂，这是对元素平衡的侵犯，必须加以干预。"},sec={{t="干扰林地",b="森达尔林地已笼罩在奥拉凯斯邪教的阴影之下。这些邪教徒因其在泽风岛上的不安分企图而臭名昭著，他们侵蚀了这片林地，并主动激怒了栖息于此的脆弱的风之灵。曾经和平的精灵们变得狂暴，形成了不稳定的翻腾的风元素，威胁着任何经过该区域的人。"},{t="痛苦的必然",b="Yala Windwatcher委派路过的勇士去镇压那些愤怒的元素生物，以及煽动动乱的奥拉凯斯皈依者。虽然消灭风之生物能使林地恢复脆弱的平静，但处理这些邪教徒却是一项沉重的职责：Yala对流下shen'dorei族人的鲜血感到惋惜，但她也意识到，邪教并没有给他们留下什么选择。"}},faq={{q="谁发布了“煽动者”任务？",a="亚拉·捕风者在泽风岛的森达尔林地附近提供该任务。",al={"任务发布者","谁开启煽动者任务","雅拉·捕风者"}},{q="奥拉凯斯邪教在森达尔林地做什么？",a="奥拉凯斯邪教进入了林地，并煽动了本土的风之灵，驱使这些和平的生物陷入了敌对和暴力的疯狂状态。",al={"邪教徒在做什么","奥拉凯斯为什么在这里","奥拉凯斯皈依者的目的"}},{q="什么是翻腾的风元素？",a="它们是泽风岛上纯朴的本土风之精灵，被奥拉凯斯邪教徒煽动并腐化成了具有侵略性的元素旋风。",al={"翻腾的风元素","风之灵","森达尔林地的风元素生物"}},{q="为什么亚拉·捕风者因为杀死皈依者而感到悲伤？",a="亚拉哀叹不得不在这片林地中洒下申多雷族人的鲜血，这表明奥拉凯斯皈依者属于她自己的人民，只是误入了危险的邪教教义。",al={"为什么雅拉对杀戮感到后悔","流下申多雷的鲜血","雅拉完成任务时的台词"}},{q="“煽动者”任务后续是什么？",a="在为亚拉·捕风者完成“煽动者”任务后，你将接到指引，继续执行返回罗瑞安身边任务。",al={"下一个任务是什么","煽动者后续任务","完成煽动者后去哪里"}},{q="这场冲突发生在什么地方？",a="冲突集中在位于泽风岛上的森达尔林地。",al={"煽动者任务地点","森达尔林地区域","森达尔林地在哪里"}}},fx={ae9ef6e2={q="雅拉·捕风者为什么要你去对付奥拉凯斯邪教？",a="雅拉·捕风者视奥拉凯斯邪教为威胁岛屿平衡的祸患。他们的仪式激怒了原本平和的本地风之精灵，使其化作狂乱之风，危及所有在森达尔林地附近行走的人。为了保护这片土地，避免无辜者丧命，她必须迅速行动，驱散这些狂暴的元素生物并将邪教驱逐出去。",al={"雅拉·捕风者的动机","雅拉为什么要对付邪教徒","为什么要消灭狂乱之风"}},["5a804844"]={q="你奉命在森达尔林地杀死谁？",a="你的任务是击杀奥拉凯斯皈依者并摧毁狂乱之风。皈依者是加入奥拉凯斯邪教、并在森达尔林地站稳脚跟的辛多雷，他们正在干扰当地元素。他们的破坏性存在激怒了原本平和的本地风之精灵，使其堕落为狂暴的活体气流，袭击所有经过此地的人。",al={"煽动者的目标","我在森达尔林地要杀谁","煽动者任务的目标是谁"}}},fp="9,192,20.190.0,19.300.0,30.70.0,49.105.0,27.121.0,57.122.0,29.105.0,36.55.0"}
